#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for a network event log entry
typedef struct {
    time_t timestamp;
    int id;
    char message[256];
} LogEntry;

// Define the structure for the dynamic array of log entries
typedef struct {
    LogEntry* entries;
    int size;
    int capacity;
    pthread_mutex_t mutex; // Thread-safe locking mechanism
} LogArray;

// Function to initialize a new log array with the given initial capacity
LogArray* initLogArray(int initialCapacity) {
    LogArray* array = (LogArray*)malloc(sizeof(LogArray));
    array->entries = (LogEntry*)calloc(initialCapacity, sizeof(LogEntry));
    array->size = 0;
    array->capacity = initialCapacity;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

// Function to add a new log entry to the array
void addLogEntry(LogArray* array, LogEntry* entry) {
    pthread_mutex_lock(&array->mutex);

    if (array->size == array->capacity) {
        // Increase capacity by doubling it and reallocate memory
        int newCapacity = array->capacity * 2;
        array->entries = (LogEntry*)realloc(array->entries, newCapacity * sizeof(LogEntry));
        array->capacity = newCapacity;
    }

    array->entries[array->size] = *entry;
    array->size++;

    pthread_mutex_unlock(&array->mutex);
}

// Function to filter log entries by event type
void filterByEventType(LogArray* array, int eventType) {
    pthread_mutex_lock(&array->mutex);

    for (int i = 0; i < array->size; i++) {
        if (array->entries[i].id != eventType) {
            // Shift remaining entries to fill the gap
            memmove(&array->entries[i], &array->entries[i + 1], (array->size - i - 1) * sizeof(LogEntry));
            array->size--;
            i--; // Decrement loop counter
        }
    }

    pthread_mutex_unlock(&array->mutex);
}

// Function to retrieve log entries within a specified time range
void retrieveEntriesByTimeRange(LogArray* array, time_t startTime, time_t endTime) {
    pthread_mutex_lock(&array->mutex);

    for (int i = 0; i < array->size; i++) {
        if (array->entries[i].timestamp < startTime || array->entries[i].timestamp > endTime) {
            // Shift remaining entries to fill the gap
            memmove(&array->entries[i], &array->entries[i + 1], (array->size - i - 1) * sizeof(LogEntry));
            array->size--;
            i--; // Decrement loop counter
        }
    }

    pthread_mutex_unlock(&array->mutex);
}

// Function to free the log array and its entries
void freeLogArray(LogArray* array) {
    pthread_mutex_lock(&array->mutex);

    for (int i = 0; i < array->size; i++) {
        // Perform any necessary cleanup or freeing of individual entry structures
    }

    free(array->entries);
    pthread_mutex_unlock(&array->mutex);
}

// Example usage:
int main() {
    LogArray* logArray = initLogArray(10);

    LogEntry entry1 = { .timestamp = time(NULL), .id = 1, .message = "Network event 1" };
    LogEntry entry2 = { .timestamp = time(NULL) + 1000, .id = 2, .message = "Network event 2" };

    addLogEntry(logArray, &entry1);
    addLogEntry(logArray, &entry2);

    filterByEventType(logArray, 1); // Filter entries with ID 1

    retrieveEntriesByTimeRange(logArray, time(NULL) - 2000, time(NULL)); // Retrieve entries within the last 2 seconds

    freeLogArray(logArray);
    return 0;
}
