#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    int* keys;
    int* values;
    pthread_mutex_t lock;
    int size;
    int capacity;
} KVMap;

KVMap* kvmap_create(int initial_capacity) {
    KVMap* map = (KVMap*)malloc(sizeof(KVMap));
    map->keys = (int*)malloc(initial_capacity * sizeof(int));
    map->values = (int*)malloc(initial_capacity * sizeof(int));
    map->size = 0;
    map->capacity = initial_capacity;
    pthread_mutex_init(&map->lock, NULL);
    return map;
}

void kvmap_insert(KVMap* map, int key, int value) {
    if (map->size >= map->capacity / 2) {
        resize_map(map);
    }
    int index = find_index(map, key);
    if (index == -1) {
        map->keys[map->size] = key;
        map->values[map->size] = value;
        map->size++;
    } else {
        map->values[index] = value;
    }
}

int kvmap_lookup(KVMap* map, int key) {
    pthread_mutex_lock(&map->lock);
    int index = find_index(map, key);
    if (index != -1) {
        int result = map->values[index];
        pthread_mutex_unlock(&map->lock);
        return result;
    } else {
        pthread_mutex_unlock(&map->lock);
        return -1; // or some other indication that the key was not found
    }
}

void kvmap_remove(KVMap* map, int key) {
    pthread_mutex_lock(&map->lock);
    int index = find_index(map, key);
    if (index != -1) {
        memmove(map->keys + index, map->keys + index + 1, (map->size - index - 1) * sizeof(int));
        memmove(map->values + index, map->values + index + 1, (map->size - index - 1) * sizeof(int));
        map->size--;
    }
    pthread_mutex_unlock(&map->lock);
}

int find_index(KVMap* map, int key) {
    for (int i = 0; i < map->size; i++) {
        if (map->keys[i] == key) {
            return i;
        }
    }
    return -1;
}

void resize_map(KVMap* map) {
    KVMap* new_map = kvmap_create(map->capacity * 2);
    for (int i = 0; i < map->size; i++) {
        new_map->keys[new_map->size] = map->keys[i];
        new_map->values[new_map->size] = map->values[i];
        new_map->size++;
    }
    free(map->keys);
    free(map->values);
    *map = *new_map;
}

void kvmap_free(KVMap* map) {
    pthread_mutex_lock(&map->lock);
    free(map->keys);
    free(map->values);
    pthread_mutex_unlock(&map->lock);
    free(map);
}

KVMap* kvmap_deserialize(FILE* file) {
    KVMap* map = (KVMap*)malloc(sizeof(KVMap));
    pthread_mutex_init(&map->lock, NULL);
    // deserialize from file
    return map;
}

void kvmap_serialize(KVMap* map, FILE* file) {
    // serialize to file
}

int main() {
    KVMap* map = kvmap_create(1000);
    // test insert, lookup, and remove operations
    kvmap_insert(map, 1, 2);
    int value = kvmap_lookup(map, 1);
    printf("%d\n", value); // prints 2
    kvmap_remove(map, 1);
    return 0;
}
