u_char* perform_dns_resolution(const char* hostname) {
    int sd, len;
    struct sockaddr_in serv_addr;
    char buffer[256];
    u_char* ip = NULL;

    sd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sd < 0)
        return (u_char*)-1; // error

    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(53); // DNS port
    inet_aton("8.8.8.8", &serv_addr.sin_addr); // Google's public DNS

    len = sizeof(serv_addr);
    if (sendto(sd, hostname, strlen(hostname), 0, (struct sockaddr*)&serv_addr, len) < 0)
        return (u_char*)-1; // error

    if (recvfrom(sd, buffer, 256, 0, NULL, NULL) < 0)
        return (u_char*)-1; // error

    ip = (u_char*)malloc(4); // allocate memory for IP address
    if (ip == NULL)
        return (u_char*)-2; // error allocating memory

    // parse the received buffer to extract the IP address
    // ...

    close(sd);
    free(ip);

    return ip;
}

int main() {
    FILE* file = fopen("log.txt", "r");
    if (file == NULL)
        return -1; // error opening file

    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, file)) {
        char* token = strtok(line, ",");
        int sensor_readings[MAX_SENSOR_READINGS];

        for (int i = 0; i < MAX_SENSOR_READINGS; i++) {
            sensor_readings[i] = atoi(token);
            token = strtok(NULL, ",");
        }

        // calculate and print the average of the last three sensor readings
        double avg = (sensor_readings[0] + sensor_readings[1] + sensor_readings[2]) / 3.0;
        printf("%.2f,", avg);

        // dynamically allocate memory for each line's content handling
        char* new_line = (char*)malloc(strlen(line) + 5); // account for the extra comma and average value
        if (new_line == NULL)
            return -1; // error allocating memory

        strcpy(new_line, line);
        strcat(new_line, ",%.2f\n", avg);

        printf("%s", new_line);
        free(new_line);
    }

    fclose(file);

    return 0;
}
