#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

void read_csv_file(const char* file_path, int** arr_ptr, size_t* arr_len) {
    FILE* file = fopen(file_path, "r");
    if (file == NULL) {
        printf("Error opening file: %s\n", file_path);
        return;
    }

    char line[1024];
    *arr_len = 0;

    while (fgets(line, sizeof(line), file)) {
        size_t len = strlen(line);
        int num;
        if (sscanf(line, "%d", &num) == 1) {
            (*arr_len)++;
            *arr_ptr = realloc(*arr_ptr, (*arr_len) * sizeof(int));
            (**arr_ptr) = num;
        } else {
            // Log error
            printf("Invalid data format: %s\n", line);
        }
    }

    fclose(file);
}

int find_largest_int(int* arr, size_t len) {
    int max = arr[0];
    for (size_t i = 1; i < len; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        printf("Usage: %s <file_path>\n", argv[0]);
        return 1;
    }

    int* arr = NULL;
    size_t arr_len = 0;

    read_csv_file(argv[1], &arr, &arr_len);

    if (arr == NULL || arr_len == 0) {
        printf("No data found in the file.\n");
        return 2;
    }

    int largest_int = find_largest_int(arr, arr_len);
    printf("Largest integer: %d\n", largest_int);

    free(arr);
    return 0;
}
