#define LOG_FILE_NAME_LENGTH 256
#define LOG_MESSAGE_MAX_LENGTH 1024
#define LOG_SIZE_LIMIT 10 * (1024 * 1024) // 10 MB
#define MAX_LOG_FILES 5

typedef struct {
    FILE* file;
    int64_t fileSize;
} LogFile;

LogFiles logFiles[MAX_LOG_FILES];
int logFileIndex = -1;

void initLogFileSystem() {
    for (int i = 0; i < MAX_LOG_FILES; i++) {
        logFiles[i].file = fopen(getNextLogFileFileName(), "a");
        if (!logFiles[i].file) {
            // handle error
            exit(1);
        }
        logFiles[i].fileSize = 0;
    }
}

void appendMessageToFifo(const char* format, ...) {
    va_list args;
    va_start(args, format);

    for (int i = 0; i < MAX_LOG_FILES; i++) {
        if (logFiles[i].file && logFiles[i].fileSize < LOG_SIZE_LIMIT) {
            int writtenBytes = fprintf(logFiles[i].file, format, args);
            logFiles[i].fileSize += writtenBytes;
            if (logFiles[i].fileSize >= LOG_SIZE_LIMIT) {
                fclose(logFiles[i].file);
                logFileIndex = (logFileIndex + 1) % MAX_LOG_FILES;
                i--;
            }
        } else if (!logFiles[logFileIndex].file || logFiles[logFileIndex].fileSize >= LOG_SIZE_LIMIT) {
            // handle error or use a different logger
        }
    }

    va_end(args);
}

void closeLogFileSystem() {
    for (int i = 0; i < MAX_LOG_FILES; i++) {
        fclose(logFiles[i].file);
    }
}
