import os
import concurrent.futures
import requests
from collections import Counter
from functools import lru_cache

@lru_cache(maxsize=None)
def fetch_stop_words():
    try:
        response = requests.get('https://api.stopwords.com/latest')
        response.raise_for_status()
        return set(response.json()['stop_words'])
    except requests.exceptions.RequestException:
        return {'the', 'and', 'a'}

def process_file(file_path, stop_words):
    word_frequency = Counter()
    with open(file_path, 'r') as file:
        for line in file.read().splitlines():
            words = [word for word in line.split() if word.isalpha()]
            for word in words:
                if word.lower() not in stop_words:
                    word_frequency[word] += 1
    return word_frequency

def calculate_average_word_frequency(directory_path, num_processes):
    stop_words = fetch_stop_words()
    total_word_frequency = Counter()
    with concurrent.futures.ProcessPoolExecutor(max_workers=num_processes) as executor:
        futures = {executor.submit(process_file, os.path.join(directory_path, file), stop_words): file for file in os.listdir(directory_path)}
        for future in concurrent.futures.as_completed(futures):
            word_frequency = future.result()
            total_word_frequency += word_frequency
    return {word: count for word, count in total_word_frequency.items() if count >= 10}

def main():
    directory_path = '/path/to/files'
    num_processes = os.cpu_count()
    average_word_frequency = calculate_average_word_frequency(directory_path, num_processes)
    print(average_word_frequency)

if __name__ == '__main__':
    main()
