}

int encrypt_decrypt(const char *filename, int mode, const char *algorithm, const char *key) {
    CipherConfig *config = (CipherConfig *) malloc(sizeof(CipherConfig));
    config->mode = mode;
    config->algorithm = strdup(algorithm);
    config->key = strdup(key);

    pthread_t thread[MAX_CONCURRENT_SESSIONS];
    int i = 0;

    for (; i < MAX_CONCURRENT_SESSIONS; i++) {
        pthread_create(&thread[i], NULL, encrypt_decrypt_thread, config);
    }

    for (i = 0; i < MAX_CONCURRENT_SESSIONS; i++) {
        pthread_join(thread[i], NULL);
    }

    free(config->algorithm);
    free(config);
    return 0;
}

int main(int argc, char **argv) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <filename> <mode> <algorithm>\n", argv[0]);
        return -1;
    }

    const char *filename = argv[1];
    int mode = atoi(argv[2]);
    const char *algorithm = argv[3];

    encrypt_decrypt(filename, mode, algorithm, NULL);
    return 0;
}
