#include <semaphore.h>
#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>

// Structure to represent a semaphore pool
typedef struct {
    sem_t* semaphores; // Array of semaphores
    int num_semaphores; // Number of semaphores in the pool
    int max_pool_size; // Maximum size of the pool
} SemaphorePool;

// Function to create a new semaphore pool with a specified maximum size
SemaphorePool* create_semaphore_pool(int max_pool_size) {
    SemaphorePool* pool = (SemaphorePool*)malloc(sizeof(SemaphorePool));
    pool->num_semaphores = 0;
    pool->max_pool_size = max_pool_size;
    pool->semaphores = (sem_t*)calloc(max_pool_size, sizeof(sem_t));

    for (int i = 0; i < max_pool_size; i++) {
        sem_init(&pool->semaphores[i], 1, 0);
    }

    return pool;
}

// Function to add a new semaphore to the pool
void add_semaphore(SemaphorePool* pool) {
    if (pool->num_semaphores >= pool->max_pool_size) {
        printf("Pool is full. Cannot add more semaphores.\n");
        return;
    }

    sem_init(&pool->semaphores[pool->num_semaphores], 1, 0);
    pool->num_semaphores++;
}

// Function to remove a semaphore from the pool
void remove_semaphore(SemaphorePool* pool) {
    if (pool->num_semaphores <= 0) {
        printf("No semaphores in the pool. Cannot remove more.\n");
        return;
    }

    sem_destroy(&pool->semaphores[pool->num_semaphores - 1]);
    pool->num_semaphores--;
}

// Function to acquire a semaphore from the pool
void acquire_semaphore(SemaphorePool* pool) {
    for (int i = 0; i < pool->num_semaphores; i++) {
        sem_wait(&pool->semaphores[i]);
    }
}

// Function to release a semaphore in the pool
void release_semaphore(SemaphorePool* pool) {
    for (int i = 0; i < pool->num_semaphores; i++) {
        sem_post(&pool->semaphores[i]);
    }
}

// Function to print the current state of the semaphore pool
void print_pool_state(SemaphorePool* pool) {
    printf("Number of available resources: %d\n", pool->max_pool_size - pool->num_semaphores);
}

int main() {
    SemaphorePool* pool = create_semaphore_pool(10);

    // Example usage
    add_semaphore(pool);
    acquire_semaphore(pool);
    release_semaphore(pool);

    print_pool_state(pool);

    return 0;
}
