    public List<string> SerializeObjects(List<object> objects, string directoryPath, string fileNamingConvention)
    {
        var filePaths = new List<string>();
        var stopwatch = Stopwatch.StartNew();

        try
        {
            foreach (var obj in objects)
            {
                // Validate the object before serialization
                if (!IsValidObject(obj))
                {
                    continue;
                }

                // Serialize the object to JSON
                string json = JsonConvert.SerializeObject(obj, Formatting.Indented);

                // Write the JSON to a file
                string filePath = Path.Combine(directoryPath, $"{fileNamingConvention}_{Guid.NewGuid()}.json");
                File.WriteAllText(filePath, json);
                filePaths.Add(filePath);

                // Log serialization metrics and error handling information
                Logger.Log($"Serialized object to {filePath} in {stopwatch.ElapsedMilliseconds}ms.");
            }
        }
        catch (Exception ex)
        {
            // Handle transient errors by retrying the operation after a delay
            if (ex is HttpRequestException || ex is IOException)
            {
                Logger.Error("Transient error occurred during serialization. Retrying...");
                System.Threading.Thread.Sleep(500);
                SerializeObjects(objects, directoryPath, fileNamingConvention);
            }
            else
            {
                // Log permanent errors and throw the exception
                Logger.Error("Permanent error occurred during serialization: {0}", ex.Message);
                throw;
            }
        }

        return filePaths;
    }

