namespace GameConfigManager
{
    public class ConfigManager
    {
        private Dictionary<string, object> _configCache = new();
        private HttpClient _httpClient = new();

        public async Task LoadConfigurationsAsync()
        {
            // Load local file configurations
            string xmlConfigPath = Path.Combine(Directory.GetCurrentDirectory(), "settings.xml");
            if (File.Exists(xmlConfigPath))
            {
                XmlSerializer serializer = new XmlSerializer(typeof(ConfigSettings));
                ConfigSettings settings = (ConfigSettings)serializer.Deserialize(new FileStream(xmlConfigPath, FileMode.Open));
                _configCache.Add("LocalXML", settings);
            }

            // Load JSON configurations from cloud storage
            string jsonConfigUrl = "https://game-configs.cloud/resolve";
            HttpResponseMessage response = await _httpClient.GetAsync(jsonConfigUrl);
            if (response.IsSuccessStatusCode)
            {
                string jsonConfig = await response.Content.ReadAsStringAsync();
                ConfigSettings settings = JsonSerializer.Deserialize<ConfigSettings>(jsonConfig);
                _configCache.Add("CloudJSON", settings);
            }
        }

        public void ApplyConfigurations()
        {
            // Get the highest-priority configuration
            object config = _configCache.Values.MaxBy(c => c.Priority).FirstOrDefault();

            if (config is ConfigSettings settings)
            {
                // Adjust game resolution and frame rate based on the loaded configurations
                GameService.Resolution = settings.Resolution;
                GameService.FrameRate = settings.FrameRate;
            }
        }

        public void HandleUpdate()
        {
            // Check for updates in cloud storage
            string updateUrl = "https://game-configs.cloud/update";
            HttpResponseMessage response = _httpClient.GetAsync(updateUrl).Result;
            if (response.IsSuccessStatusCode)
            {
                string updateJson = response.Content.ReadAsStringAsync().Result;
                ConfigSettings updatedSettings = JsonSerializer.Deserialize<ConfigSettings>(updateJson);

                // Update the cache and apply changes
                _configCache["CloudJSON"] = updatedSettings;
                ApplyConfigurations();
            }
        }

        public class ConfigSettings
        {
            public int Priority { get; set; }
            public ResolutionResolution { get; set; }
            public int FrameRate { get; set; }
        }

        public enum Resolution
        {
            HD,
            FullHD,
            4K
        }
    }
}
