import json
from flask import Flask, request, jsonify
from flask_api import status
from marshmallow import Schema, fields, validate
from datetime import datetime

app = Flask(__name__)

class SettingSchema(Schema):
    name = fields.Str(required=True)
    metadata = fields.Dict(unknown='EXCLUDE')
    dependencies = fields.List(fields.Str(), unknown='EXCLUDE')

class UpdateSettingSchema(Schema):
    name = fields.Str(required=True)
    configuration = fields.Nested(SettingSchema, many=False)

class Setting:
    def __init__(self, name, metadata, dependencies):
        self.name = name
        self.metadata = metadata
        self.dependencies = dependencies
        self.last_modified = datetime.utcnow()
        self.version = 1

settings = {}

@app.route('/settings', methods=['GET'])
def get_settings():
    if settings:
        return jsonify({'error': 'Cannot set default values due to existing data.'}), status.HTTP_409_CONFLICT
    return jsonify([setting.to_dict() for setting in settings.values()])

@app.route('/settings/<string:name>', methods=['PUT'])
def update_setting(name):
    schema = UpdateSettingSchema()
    data = request.get_json()
    if not schema.validate(data):
        return jsonify({'error': 'Invalid configuration.'}), status.HTTP_400_BAD_REQUEST
    if name not in settings:
        settings[name] = Setting(name, data['metadata'], data['dependencies'])
        settings[name].last_modified = datetime.utcnow()
        settings[name].version += 1
        return jsonify(settings[name].to_dict()), status.HTTP_201_CREATED
    else:
        if request.is_json and 'If-Match' in request.headers:
            expected_version = int(request.headers['If-Match'].split('.')[-1])
            if settings[name].version == expected_version:
                settings[name].metadata.update(data['metadata'])
                settings[name].dependencies.extend(data['dependencies'])
                settings[name].last_modified = datetime.utcnow()
                settings[name].version += 1
                return jsonify(settings[name].to_dict()), status.HTTP_200_OK
        else:
            return jsonify({'error': 'Conditional update failed.'}), status.HTTP_412_PRECONDITION_FAILED

@app.route('/settings/<string:name>', methods=['DELETE'])
def delete_setting(name):
    if name in settings:
        del settings[name]
        return '', status.HTTP_204_NO_CONTENT
    return jsonify({'error': 'Setting not found.'}), status.HTTP_404_NOT_FOUND

if __name__ == '__main__':
    app.run(debug=True)
