public class HashService {

    private Map<String, String> cache = new HashMap<>();
    private static final String CACHE_FILE = "hash_cache.json";
    private final org.apache.logging.log4j.Logger logger = org.apache.logging.log4j.LogManager.getLogger(HashService.class);

    public void processBatch(String[] inputs) {
        for (String input : inputs) {
            if (input == null) continue;
            try {
                String md5Hash = computeMD5Hash(input);
                cache.put(md5Hash, input);
                logger.info("Processed: {} with hash {}", input, md5Hash);
            } catch (Exception e) {
                logger.error("Error processing {}: {}", input, e.getMessage());
            }
        }
    }

    private String computeMD5Hash(String input) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] bytes = input.getBytes();
        byte[] hashBytes = md.digest(bytes);
        return bytesToHex(hashBytes);
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder hexString = new StringBuilder();
        for (byte b : bytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

