        return json_encode(array('status' => 'error', 'message' => 'Missing action parameter'));
    }

    $allowedActions = array('create', 'update', 'delete');
    if (!in_array($_POST['action'], $allowedActions)) {
        return json_encode(array('status' => 'error', 'message' => 'Invalid action: ' . $_POST['action']));
    }

    $validatedInput = validateInput($_POST);
    if ($validatedInput === false) {
        return json_encode(array('status' => 'error', 'message' => 'Invalid input'));
    }

    $id = $validatedInput['id'];
    try {
        db()->transaction(function () use ($id, $validatedInput) {
            if (!empty($id)) {
                switch ($_POST['action']) {
                    case 'update':
                        persistUser('update', $id, $validatedInput);
                        break;
                    case 'delete':
                        if (hasAssociatedSessions($id)) {
                            persistUser('delete', $id);
                        } else {
                            return json_encode(array('status' => 'error', 'message' => 'Cannot delete user without sessions'));
                        }
                        break;
                }
            } else {
                switch ($_POST['action']) {
                    case 'create':
                        persistUser('create', $validatedInput);
                        // Send confirmation email
                        sendConfirmationEmail($validatedInput['email']);
                        break;
                }
            }

            logAction($_POST['action'], $id, 'success');
        });
