        public DynamicUpdateController(IDynamicUpdateService dynamicUpdateService)
        {
            _dynamicUpdateService = dynamicUpdateService;
        }

        [HttpPost]
        public async Task<IActionResult> UpdatePageSection([FromBody]DynamicUpdateRequest request)
        {
            try
            {
                await _dynamicUpdateService.UpdatePageSectionAsync(request.PageSectionId, request.ElementId, request.NewContent);
                return Ok();
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error updating page section");
                return StatusCode(StatusCodes.Status500InternalServerError, "Internal Server Error");
            }
        }
    }

    public class DynamicUpdateRequest
    {
        public Guid PageSectionId { get; set; }
        public string ElementId { get; set; }
        public string NewContent { get; set; }
    }

    public interface IDynamicUpdateService
    {
        Task UpdatePageSectionAsync(Guid pageSectionId, string elementId, string newContent);
    }

    public class DynamicUpdateService : IDynamicUpdateService
    {
        private readonly YourNamespaceDbContext _context;
        private readonly ILogService _logService;

        public DynamicUpdateService(YourNamespaceDbContext context, ILogService logService)
        {
            _context = context;
            _logService = logService;
        }

        public async Task UpdatePageSectionAsync(Guid pageSectionId, string elementId, string newContent)
        {
            using (var transaction = await _context.Database.BeginTransactionAsync())
            {
                try
                {
                    // Validate and sanitize incoming HTML content here

                    // Update database records within the transaction scope
                    await _context.PageSections.UpdateAsync(pageSectionId);

                    // Signal a refresh of the entire page to clients
                    _logService.LogInformation("Page section updated successfully");

                    await transaction.CommitAsync();
                }
                catch (Exception ex)
                {
                    await transaction.RollbackAsync();
                    _logService.LogError(ex, "Error updating page section");
                    throw;
                }
            }
        }
    }

