import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;

public class MoSTStateManager {
    public static MoSTState loadMoSTState(String filePath) throws IOException, ClassNotFoundException {
        MoSTState loadedState = null;
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath))) {
            loadedState = (MoSTState) ois.readObject();
            if (loadedState != null && !loadedState.themeBitmap.isRecyclable()) {
                loadedState.themeBitmap.recycle();
                loadedState.themeBitmap = null;
            }
        } catch (IOException e) {
            System.out.println("Error reading file: " + e.getMessage());
        } finally {
            // Handle resource management for ObjectInputStream
            try {
                if (ois != null) ois.close();
            } catch (IOException e2) {
                System.out.println("Error closing object input stream: " + e2.getMessage());
            }
        }

        return loadedState;
    }
}
