const { promisify } = require('util');
const fs = require('fs');
const path = require('path');
const logging = require('./logging'); // existing logging framework
const { Parallel, Sequential } = require('./processing-strategies');

// Define a custom error class for file processing errors
class FileProcessingError extends Error {
  constructor(message) {
    super(`File Processing Error: ${message}`);
  }
}

async function processFiles(directoryPath, strategy = new Sequential()) {
  try {
    const files = await fs.readdirSync(directoryPath);
    const processedFiles = [];
    const skippedFiles = [];

    // Use parallel processing for better performance
    if (strategy instanceof Parallel) {
      const filePromises = files.map((file) => processFile(path.join(directoryPath, file), strategy));
      const results = await Promise.all(filePromises);

      results.forEach((result) => {
        if (result.valid) processedFiles.push(result.file);
        else skippedFiles.push(result.file);
      });
    } else { // Sequential processing for small files or single-core systems
      for (const file of files) {
        const result = await processFile(path.join(directoryPath, file), strategy);
        if (result.valid) processedFiles.push(file);
        else skippedFiles.push(file);
      }
    }

    logging.info(`Processed ${processedFiles.length} files. Skipped ${skippedFiles.length}.`);
    return { processedFiles, skippedFiles };
  } catch (error) {
    throw new FileProcessingError(error.message);
  }
}

async function processFile(filePath, strategy) {
  try {
    const content = await fs.readFile(filePath, 'utf8');
    // Implement your file processing logic here
    if (/* valid file content */) {
      return { valid: true, file: path.basename(filePath) };
    } else {
      logging.error(`Invalid file content in ${filePath}. Skipping.`);
      return { valid: false, file: path.basename(filePath) };
    }
  } catch (error) {
    throw new FileProcessingError(`Error processing file ${path.basename(filePath)}: ${error.message}`);
  }
}
