function runTests(label, f, retryLimit) {
  const blueslip = require('blueslip');

  async function testWrapper(testName) {
    try {
      await f();
      console.log(`Test ${testName} passed in ${Date.now() - startTime}ms`);
      blueslip.reset();
    } catch (error) {
      let retries = 0;
      while (retries <= retryLimit) {
        try {
          await f();
          console.log(`Test ${testName} passed after retry in ${Date.now() - startTime}ms`);
          blueslip.reset();
          return;
        } catch (e) {
          retries++;
          if (retries >= retryLimit) {
            console.error(`Test ${testName} failed after ${retryLimit} retries: ${error}`);
          }
        }
      }
    }
  }

  const startTime = Date.now();
  await Promise.all(Object.keys(f).map((testName, index) => testWrapper(testName)));
  console.log(`Module ${label} testing finished in ${Date.now() - startTime}ms`);
  console.log(`Summary: ${successfulTests.length} tests passed, ${failedTests.length} tests failed, and ${retriedTests.length} tests retried.`);
}
