import requests
from bs4 import BeautifulSoup
import logging
from typing import Dict, List

def extract_metadata(url: str, fields: List[str], parse_js: bool = False) -> Dict:
    try:
        response = requests.get(url)
        if response.status_code == 200:
            soup = BeautifulSoup(response.content, 'html.parser')
            metadata = {}

            # Extract title and meta description
            title = soup.find('title').text.strip()
            meta_description = soup.find('meta', attrs={'name': 'description'})['content']
            metadata.update({'title': title, 'meta_description': meta_description})

            # Extract external links
            external_links = [link.get('href') for link in soup.find_all('a', href=True) if not link.get('href').startswith('#')]
            metadata.update({'external_links': external_links})

            # Extract additional fields if supported
            for field in fields:
                if field == 'title':
                    continue
                elif field == 'meta_description':
                    continue
                else:
                    value = soup.find(field).text.strip() if soup.find(field) else ''
                    metadata.update({field: value})

            # Parse JavaScript-rendered content if enabled
            if parse_js:
                js_content = requests.get(url, headers={'X-Requested-With': 'XMLHttpRequest'}).content
                soup = BeautifulSoup(js_content, 'html.parser')
                for field in fields:
                    if field == 'title':
                        continue
                    elif field == 'meta_description':
                        continue
                    else:
                        value = soup.find(field).text.strip() if soup.find(field) else ''
                        metadata.update({field: value})

            # Log execution and metadata extraction
            logging.info(f"Metadata extracted from {url}: {metadata}")
            return metadata

        else:
            logging.error(f"Failed to retrieve URL {url} with status code {response.status_code}")
            return {}

    except requests.exceptions.RequestException as e:
        logging.error(f"Request failed: {e}")
        return {}

