function renderFooterScripts(scripts) {
  const footer = '<footer>';

  for (const script of scripts) {
    if (!('key' in script) || !('value' in script)) {
      continue;
    }

    let scriptTag = `<script${script.environment === 'production' ? '' : ` type="${script.key}"`}>`;
    scriptTag += `${script.value}`;
    scriptTag += '</script>';

    if (scriptTag !== '') {
      footer += scriptTag + '\n';
    }
  }

  return footer + '</footer>';
}
