void refreshDialogFields(int resourceID, std::vector<std::string> fieldNames) {
    // Create an unordered map to store the updated values
    std::unordered_map<std::string, std::string> updates;

    // Send asynchronous message to the parent window with the resource ID and field names
    SendMessageToParent(resourceID, fieldNames);

    // Process the received updates for each field name
    for (const auto& fieldName : fieldNames) {
        if (updates.find(fieldName) != updates.end()) {
            // Update the dialog field value
            UpdateDialogField(fieldName, updates.at(fieldName));
        }
    }
}

// Asynchronous message-passing mechanism to communicate with the parent window
void SendMessageToParent(int resourceID, const std::vector<std::string>& fieldNames) {
    // Send a message to the parent window with the required information
    SendMessage(WM_USER + MSG_UPDATE_DIALOG_FIELDS, reinterpret_cast<WPARAM>(resourceID), LPARAM(fieldNames));
}

// Handle updates received from the parent window
void OnUpdateDialogFields(int resourceID, const std::vector<std::string>& fieldNames) {
    // Process the received updates for each field name
    refreshDialogFields(resourceID, fieldNames);
}
