class BufferManager {
  constructor(maxBufferSize, config = { priority: 'speed' }) {
    this.maxBufferSize = maxBufferSize;
    this.config = config;
    this.buffers = [];
    this.lock = new Promise((resolve) => (this.resolve = resolve));
  }

  async mergeBuffers() {
    if (!this.buffers.length) return;

    const mergedBuffer = [];
    let totalLength = 0;

    for (const buffer of this.buffers) {
      if (!buffer || !buffer.length) continue;
      totalLength += buffer.length;
      if (totalLength > this.maxBufferSize) throw new Error('Total length exceeds maximum size');

      mergedBuffer.push(...buffer);
    }

    this.buffers = [];
    return mergedBuffer;
  }

  async addBuffer(newBuffer, options = { overwrite: false }) {
    if (!newBuffer || !newBuffer.length) return;

    if (options.overwrite) {
      this.lock = new Promise((resolve) => (this.resolve = resolve));
      await this.lock;
    } else {
      const merged = await this.mergeBuffers();
      await this.lock;
    }

    if (merged.length + newBuffer.length > this.maxBufferSize)
      throw new Error('New buffer exceeds maximum size');

    this.buffers.push(newBuffer);
  }

  async getBuffer() {
    return this.mergeBuffers();
  }

  log(operation, result) {
    console.log(`${operation} buffer: ${result}`);
  }
}

module.exports = BufferManager;
