function fetchDynamicContent(baseURL, query, callback, config = {}) {
  const cache = {};
  let nextLink;
  let currentPage = 1;

  async function fetchPage(page = 1) {
    const url = `${baseURL}?page=${page}&${Object.keys(query).map(k => `${k}=${query[k]}`).join('&')}`;
    const headers = { 'X-Next-Page': '' };
    if (nextLink) {
      headers['X-Next-Page'] = nextLink;
    }
    const requestConfig = {
      method: config.method || 'GET',
      url,
      headers,
      cache,
      timeout: config.timeout || 30000
    };

    try {
      const response = await fetch(requestConfig.url, requestConfig);
      const data = await response.json();

      if (response.ok) {
        callback(data.items.map(item => item.filter ? callback(item.filter) : item));
        if (data.nextPage) {
          nextLink = data.nextPage;
          currentPage++;
          return fetchPage(currentPage);
        }
        return Promise.resolve();
      } else if (response.status === 304) {
        // Handle caching efficiency vs stale data
        const cacheKey = JSON.stringify({ baseURL, query });
        if (!cache[cacheKey]) {
          cache[cacheKey] = data;
          return fetchPage(currentPage);
        }
        return Promise.resolve();
      } else {
        throw new Error(`Failed to retrieve page ${page}: ${response.statusText}`);
      }
    } catch (error) {
      // Fallback strategies for network failures, server errors, and timeouts
      if (error.code === 'ETIMEDOUT' || error.name === 'TimeoutError') {
        // Handle timeouts with a retry mechanism
        return setTimeout(() => fetchPage(page), 1000);
      } else {
        throw error;
      }
    }
  }

  return fetchPage().then(() => Promise.resolve());
}
