import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;
import java.util.HashMap;
import java.util.Map;

public class FileProcessor {
    private static final int BATCH_SIZE = 1000; // adjust as needed

    public Map<String, Long> processFiles(String filePath) throws IOException {
        ConcurrentHashMap<String, Long> fileTypes = new ConcurrentHashMap<>();
        AtomicLong totalFilesProcessed = new AtomicLong();
        AtomicLong averageProcessingTime = new AtomicLong();

        try (BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
            String line;
            long start = System.currentTimeMillis();
            int batchCount = 0;

            while ((line = reader.readLine()) != null) {
                batchCount++;

                if (batchCount % BATCH_SIZE == 0) { // process every BATCH_SIZE lines
                    processBatch(fileTypes, totalFilesProcessed, averageProcessingTime);
                    start = System.currentTimeMillis(); // reset timer for next batch
                }

                // simulate file processing time
                long processingTime = Math.random() * 100;
                try {
                    Thread.sleep(processingTime);
                } catch (InterruptedException e) {}

                if (line != null && line.length() > 0) { // validate file path
                    String[] parts = line.split("/");
                    String fileType = parts[parts.length - 1].split("\\.")[1]; // extract file type

                    fileTypes.computeIfAbsent(fileType, k -> 0L).incrementAndGet();
                    totalFilesProcessed.incrementAndGet();
                }
            }

            if (batchCount % BATCH_SIZE != 0) { // process the remaining files
                processBatch(fileTypes, totalFilesProcessed, averageProcessingTime);
            }
        } catch (IOException e) {
            // handle file reading failure gracefully
            System.err.println("Error processing file: " + e.getMessage());
            return new HashMap<>(); // return an empty map if file read fails
        }

        long end = System.currentTimeMillis();
        System.out.printf("Total files processed: %d, Average processing time per file type: %.2f ms\n", totalFilesProcessed.get(), (double) averageProcessingTime.get() / totalFilesProcessed.get());
        System.out.println("Elapsed time: " + (end - start) + " ms");

        return new HashMap<>(fileTypes);
    }

    private void processBatch(ConcurrentHashMap<String, Long> fileTypes, AtomicLong totalFilesProcessed, AtomicLong averageProcessingTime) {
        long startTime = System.currentTimeMillis();
        for (Map.Entry<String, Long> entry : fileTypes.entrySet()) {
            averageProcessingTime.addAndGet(entry.getValue());
        }
        totalFilesProcessed.set(fileTypes.size());
        long endTime = System.currentTimeMillis();

        System.out.printf("Batch %d: Total files processed - %d, Average processing time per file type - %.2f ms\n", (fileTypes.size() / BATCH_SIZE), totalFilesProcessed.get(), (double) averageProcessingTime.get() / totalFilesProcessed.get());
    }
}
