['Here is a Java-based distributed file upload service that supports concurrent uploads and ensures data integrity across multiple nodes:

```java
import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class DistributedFileUploadService {
    private static final int DEFAULT_CONCURRENCY_LEVEL = 10;
    private ExecutorService executorService;
    private List<Node> nodes;

    public DistributedFileUploadService(int concurrencyLevel, List<Node> nodes) {
        this.executorService = Executors.newFixedThreadPool(concurrencyLevel);
        this.nodes = nodes;
    }

    public void uploadFile(String filePath) throws IOException, ExecutionException {
        File file = new File(filePath);
        int fileSize = (int) file.length();

        // Create a list of callable tasks
        List<Callable<Void>> callables = new ArrayList<>();
        for (Node node : nodes) {
            Callable<Void> task = () -> uploadFileChunk(file, fileSize, node);
            callables.add(task);
        }

        // Submit the tasks to the executor service and get the futures
        List<Future<Void>> futures = executorService.invokeAll(callables);

        // Check the status of each future
        for (Future<Void> future : futures) {
            if (!future.isDone()) {
                throw new IOException("Upload failed");
            }
        }
    }

    private Void uploadFileChunk(File file, int fileSize, Node node) throws IOException {
        FileInputStream fileInputStream = new FileInputStream(file);
        byte[] buffer = new byte[1024];

        // Calculate the chunk size
        int chunkSize = Math.min(1024 * 1024, fileSize);

        for (int i = 0; i < fileSize; i += chunkSize) {
            int bytesRead = fileInputStream.read(buffer);
            node.uploadData(buffer, bytesRead);

            if (i >= fileSize - chunkSize) {
                // Last chunk, upload the remaining bytes
                byte[] lastChunk = new byte[fileSize - i];
                fileInputStream.read(lastChunk);
                node.uploadData(lastChunk, lastChunk.length);
            }
        }

        return null;
    }
}

class Node {
    public void uploadData(byte[] buffer, int length) throws IOException {}
}
```

This is just a basic implementation and would require additional code for error handling, retry mechanisms, scalability, and other requirements you mentioned.']

