['```rust
use std::sync::{Arc, Mutex};
use std::thread;
use reqwest;
use log::{info, warn};

pub struct HttpClient {
    max_connections: u16,
    timeout_ms: u32,
    disable_cert_validation: bool,
    connection_pool: Arc<Mutex<Vec<reqwest::blocking::Client>>>,

    retry_policy: Vec<(u16, u16)>, // (num_retries, interval_seconds)
}

impl HttpClient {
    pub fn new(max_connections: u16, timeout_ms: u32, disable_cert_validation: bool) -> Self {
        let connection_pool = Arc::new(Mutex::new(vec!()));
        let retry_policy = vec![(3, 1)]; // Default to 3 retries with 1 second interval

        HttpClient {
            max_connections,
            timeout_ms,
            disable_cert_validation,
            connection_pool,
            retry_policy,
        }
    }

    async fn send_request(&self, req: &reqwest::Request) -> Result<reqwest::BlockingResponse, reqwest::Error> {
        let client = self.get_client().await?;
        Ok(client.request(req).timeout(std::time::Duration::from_millis(self.timeout_ms)).send().await?)
    }

    async fn get_client(&self) -> Result<reqwest::blocking::Client, reqwest::Error> {
        let mut pool = self.connection_pool.lock().unwrap();
        if let Some(ref client) = *pool.first() {
            return Ok(client.clone());
        }
        let new_client = reqwest::blocking::Client::builder()
            .timeout(std::time::Duration::from_millis(self.timeout_ms))
            .disable_certificate_validation(self.disable_cert_validation)
            .build()?;
        pool.push(new_client.clone());
        Ok(new_client)
    }

    async fn handle_request(&self, req: &reqwest::Request) -> Result<(), reqwest::Error> {
        let client = self.get_client().await?;
        match client.request(req).timeout(std::time::Duration::from_millis(self.timeout_ms)).send().await {
            Ok(res) => {
                info!("Received response: {}", res.status());
                // Log request metrics and response times
                // ...
            }
            Err(err) => {
                if let reqwest::Error::Timeout = err {
                    warn!("Request timed out");
                } else if let Some((num_retries, interval_seconds)) = self.retry_policy.get(0) {
                    thread::sleep(std::time::Duration::from_secs(interval_seconds));
                    self.handle_request(req).await?;
                }
            }
        }
    }
}
