        raise ValueError("Invalid city name or API rate limit exceeded")

    weather_description = data["weather_description"]
    temperature = data["temperature"]
    humidity = data["humidity"]

    return {"temperature": temperature, "humidity": humidity, "weather_description": weather_description}

