function generateSecureRandomString($length, $charset, $minStrength) {
    $random_string = '';
    while (strlen($random_string) < $length) {
        $random_string .= substr(str_shuffle($charset), 0, floor($minStrength / strlen($charset)));
    }
    return array('random_string' => $random_string, 'hashed_password' => hash('argon2', uniqid()));
}

function safeReadFile($filePath) {
    if (!is_string($filePath)) {
        throw new InvalidArgumentException("Invalid file path");
    }
    if (strpos($filePath, '..') !== false || strpos($filePath, '\\\\') !== false) {
        throw new SecurityException("Path traversal attempt detected");
    }
    $file = @fopen($filePath, 'r');
    if (!$file) {
        throw new FileNotFoundException("Failed to read file: " . $filePath);
    }
    try {
        return fread($file, filesize($filePath));
    } catch (Error $e) {
        fclose($file);
        throw $e;
    } finally {
        fclose($file);
    }
}

