function fetchAndCombinePEMCertificate(request) {
  const { privateKeyUrl, certificateUrl } = request;
  const timeout = request.timeout || 5000;
  const maxRetries = request.maxRetries || 3;

  return new Promise((resolve, reject) => {
    async function fetchFile(url) {
      let attempts = 0;
      let error;
      while (attempts < maxRetries) {
        try {
          const response = await fetch(url, { timeout });
          if (!response.ok) throw new Error(`Failed to retrieve ${url}: ${response.status}`);
          return response;
        } catch (e) {
          attempts++;
          if (attempts >= maxRetries) {
            reject(e);
            break;
          }
          setTimeout(() => {
            fetchFile(url);
          }, timeout);
        }
      }
    }

    async function combineCertificates(privateKeyResponse, certificateResponse) {
      const privateKey = await privateKeyResponse.text();
      const certificate = await certificateResponse.text();
      return Buffer.concat([Buffer.from(privateKey), Buffer.from(certificate)]).toString('utf8');
    }

    fetchFile(privateKeyUrl)
      .then((privateKeyResponse) => {
        fetchFile(certificateUrl)
          .then((certificateResponse) => combineCertificates(privateKeyResponse, certificateResponse))
          .then((pemContent) => resolve(pemContent))
          .catch((error) => reject(error));
      })
      .catch((error) => reject(error));
  });
}
