#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct FSA {
    int* states;
    int num_states;
    pthread_mutex_t lock;
} FSA;

void create_state_list(FSA* f, int* last_state, int max_size) {
    pthread_mutex_lock(&f->lock);

    if (f->num_states > 0 && *last_state >= f->num_states) {
        printf("Error: Last state index out of range.\n");
        return;
    }

    int new_state = f->num_states++;
    int* new_list = (int*)malloc((max_size + 1) * sizeof(int));
    if (!new_list) {
        pthread_mutex_unlock(&f->lock);
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < max_size; i++) {
        new_list[i] = -1; // Initialize all states to "error" state
    }
    new_list[max_size] = -2; // Mark the end of the list

    if (*last_state >= f->num_states) {
        printf("Error: Last state index out of range.\n");
        free(new_list);
        pthread_mutex_unlock(&f->lock);
        return NULL;
    }

    if (!f->states) { // Initialize the 'next' pointer for the first state
        f->states = (int*)malloc((2 + 1) * sizeof(int));
        if (!f->states) {
            free(new_list);
            pthread_mutex_unlock(&f->lock);
            return NULL;
        }
    } else if (*last_state > 0 && !f->states[*last_state].next) {
        f->states[*last_state].next = (int*)malloc(1 * sizeof(int));
        *(f->states[*last_state].next) = -2; // Mark the end of the list
    }

    if (*last_state < f->num_states - 1 || max_size <= 0) {
        printf("Error: Last state index out of range or invalid maximum size.\n");
        free(new_list);
        pthread_mutex_unlock(&f->lock);
        return NULL;
    }

    *last_state = new_state;
    f->states[new_state].next = new_list;
    pthread_mutex_unlock(&f->lock);
}
