```csharp
using System;
using System.IO;

public class DynamicRangeGenerator
{
    private float minValue;
    private float maxValue;

    public DynamicRangeGenerator(float minValue, float maxValue)
    {
        if (minValue > maxValue)
        {
            throw new ArgumentException("Min value must be less than or equal to max value.");
        }

        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public float GenerateRandomFloat()
    {
        return (float)Rand.NextDouble() * (maxValue - minValue) + minValue;
    }

    public int GenerateRandomInt()
    {
        Random rand = new Random();
        return Rand.Next((int)minValue, (int)maxValue);
    }

    public float GenerateExclusiveRandomFloat()
    {
        return (float)Rand.NextDouble() * (maxValue - minValue) + minValue;
    }

    public int GenerateExclusiveRandomInt()
    {
        Random rand = new Random();
        return Rand.Next((int)minValue, (int)maxValue);
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}]";
    }

    public void AdjustRange(float adjustment)
    {
        if (adjustment < 0)
        {
            // Check if range would become invalid
            if ((minValue + adjustment) >= maxValue)
            {
                throw new InvalidOperationException("Cannot adjust the range to a value that would cause it to become invalid.");
            }

            minValue += adjustment;
        }
        else
        {
            if (adjustment > (maxValue - minValue))
            {
                throw new InvalidOperationException("Cannot adjust the range to a value that would cause it to become invalid.");
            }

            maxValue -= adjustment;
        }
    }

    public void ResetRange()
    {
        this.minValue = 0;
        this.maxValue = 100;
    }

    public void LoadCustomRange(string rangeConfig)
    {
        try
        {
            string[] values = rangeConfig.Split(',');
            if (values.Length != 2 || !float.TryParse(values[0], out float minValue) || !float.TryParse(values[1], out float maxValue))
            {
                throw new FormatException("Invalid range configuration.");
            }

            if (minValue > maxValue)
            {
                throw new ArgumentException("Min value must be less than or equal to max value.");
            }

            this.minValue = minValue;
            this.maxValue = maxValue;
        }
        catch (FormatException ex)
        {
            Console.WriteLine($"Error parsing custom range: {ex.Message}");
        }
    }
}
