function processDOMNodes(inputStr, sizeLimit, rootNode) {
    const result = [];
    function traverse(node, inputStr, sizeLimit) {
      if (!node || !inputStr || !sizeLimit) return;

      const newNodeContent = node.textContent.trim();
      const newNodeSize = newNodeContent.length;

      if (newNodeSize > sizeLimit) return null;

      const newNodeStr = inputStr + (newNodeContent ? '/' : '');
      result.push(newNodeStr);

      const childNodes = Array.from(node.children);
      for (const child of childNodes) {
        traverse(child, newNodeStr, sizeLimit - newNodeSize);
      }
    }
    traverse(rootNode, inputStr, sizeLimit);
    return result;
  }"]

