typedef struct {
    int event_id;
    char* fields[0];
} Event;

void process_log_file(char* log_file_name) {
    FILE* file = fopen(log_file_name, "r");
    if (!file) return;

    Event* current_event = NULL;
    size_t event_size = sizeof(Event);

    while (1) {
        char line[1024];
        fgets(line, 1024, file);
        if (!line[0]) break;

        // Allocate memory for the new event
        current_event = realloc(current_event, event_size + strlen(line));
        Event* prev_event = current_event;
        current_event->fields = (char**) (((char*)current_event) + sizeof(Event));
        *(((char**)current_event) + 0) = strdup(line);
        *(current_event->fields) = NULL;

        // Parse the line and extract numeric fields
        char* token = strtok(line, " ");
        while (token && strlen(token)) {
            if (strtol(token, NULL, 10)) { // Check if token is a number
                current_event->event_id = strtol(token, NULL, 10);
            }
            token = strtok(NULL, " ");
        }

        int last_two_numeric_fields_sum = 0;
        for (int i = strlen(line) - 1; i >= 0; --i) {
            char c = line[i];
            if (c == ' ') { // Found a space
                line[i] = '\0';
                break;
            }
            last_two_numeric_fields_sum += (line[i] - '0') * pow(10, strlen(line) - i - 1);
        }

        printf("Average of the last two numeric fields: %f\n", (float)last_two_numeric_fields_sum / 2.0);

        free(prev_event->fields[0]);
        free(prev_event);
    }
    fclose(file);
}

int main() {
    process_log_file("log.txt");
    return 0;
}
