typedef struct {
    int bitsPerSample;
    int samplesPerPixel;
    int extraSamples;
} ImageInfo;

void processImageAndComputeHash(const char* path, const char* text) {
    TIFF *tif = TIFFOpen(path, "r");
    if (!tif) {
        // Handle error
        return;
    }

    uint16_t bitsPerSample = 0;
    uint16_t samplesPerPixel = 0;
    uint16_t extraSamples = 0;

    while (TIFFGetField(tif, TIFF-field- PlanarConfig, &bitsPerSample)) {
        if (!TIFFGetField(tif, TIFF-field-SamplesPerPixel, &samplesPerPixel) || 
            !TIFFGetField(tif, TIFF-field-ExtraSamples, &extraSamples)) {
            // Handle error
            break;
        }
    }

    TIFFClose(tif);

    char hash[MD5_DIGEST_LENGTH * 2];
    MD5_CTX ctx;
    unsigned char mdBuffer[MD5_DIGEST_LENGTH];

    MD5_Init(&ctx);
    MD5_Update(&ctx, text, strlen(text));
    MD5_Final(mdBuffer, &ctx);

    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        sprintf(&hash[i*2], "%02x", mdBuffer[i]);
    }

    // Append hash to output
    printf("Image Info: Bits Per Sample - %d, Samples Per Pixel - %d, Extra Samples - %d\n", bitsPerSample, samplesPerPixel, extraSamples);
    printf("MD5 Hash: %s\n", hash);

    return;
}
