#define MAX_FILENAME_LENGTH 255
#define MAX_BASENAME_LENGTH 250
#define FILE_TYPES_SIZE 4
#define RND_FILE_TYPE ((rand() % FILE_TYPES_SIZE))

void generateNewFilename(char* original_filename, char** new_filename) {
    char base_name[MAX_BASENAME_LENGTH + 1];
    char* p = strrchr(original_filename, '.');
    if (p != NULL && p - original_filename <= MAX_FILENAME_LENGTH) {
        strncpy(base_name, original_filename, p - original_filename);
        base_name[p - original_filename] = '\0';
        int len = strlen(base_name);

        // Generate new filename
        sprintf(*new_filename, "%s_%05d%s", base_name, len, (RND_FILE_TYPE % 4 ? ".txt" : RND_FILE_TYPE % 2 ? ".csv" : ".log" : ".html"));
    } else {
        *new_filename = NULL;
    }
}

int main() {
    char original_filename[] = "long_file_with_spaces_and_leading_zeros_0123456789.txt";
    char* new_filename;
    generateNewFilename(original_filename, &new_filename);
    printf("Original filename: %s\n", original_filename);
    printf("Generated filename: %s\n", new_filename);

    return 0;
}
