    struct tm* tm = localtime(&now);
    printf("[Error] %02d:%02d:%s: %s\n", tm.tm_hour, tm.tm_min, ctime(&now), message);

    // Handle error based on the error code
    switch (err_code) {
        case 0:
            // Fatal error - exit application
            exit(EXIT_FAILURE);
        default:
            // Non-fatal error - continue with fallback or warning
            printf("[Warning] Error occurred, but falling back to backup plan\n");
    }
}

