#include <fcntl.h>
#include <string.h>

#define MAX_CONCURRENT 10
#define USER_ID_RANGE 1000 // range of user IDs to use

int execute_command_in_background(char *command, char *config_file) {
    int i, status;
    pid_t pids[MAX_CONCURRENT];
    int user_ids[MAX_CONCURRENT];

    for (i = 0; i < MAX_CONCURRENT; i++) {
        pids[i] = fork();
        if (pids[i] == -1) {
            perror("fork");
            return 0;
        }
        if (pids[i] == 0) { // child process
            setuid(getpid() % USER_ID_RANGE); // assign unique user ID
            execl("/bin/sh", "sh", "-c", command, NULL);
            perror("execl");
            _exit(1); // if execl fails, terminate the process
        }
    }

    for (i = 0; i < MAX_CONCURRENT; i++) {
        waitpid(pids[i], &status, 0);
        if (WEXITSTATUS(status) != 0) { // if any process failed to start
            return 0;
        }
    }

    int config_fd[10];
    for (i = 0; i < MAX_CONCURRENT; i++) {
        config_fd[i] = open(config_file, O_RDONLY);
        if (config_fd[i] == -1) { // handle errors opening files
            perror("open");
            return 0;
        }
    }

    // mechanism to monitor and clean up process entries upon termination
    for (i = 0; i < MAX_CONCURRENT; i++) {
        close(config_fd[i]);
    }

    return 1;
}
