    public void StartWebSites(List<(string DirectoryPath, string SiteName)> siteDirectories)
    {
        foreach (var (directoryPath, siteName) in siteDirectories)
        {
            if (!Directory.Exists(directoryPath))
                continue;

            var configFilePath = Path.Combine(directoryPath, "web.config");
            if (!File.Exists(configFilePath))
            {
                Console.WriteLine($"Error: No web.config file found at {configFilePath}");
                continue;
            }

            try
            {
                // Check directory permissions
                if (!Directory.GetFiles(directoryPath).Any())
                    throw new DirectoryNotFoundException();

                // Start the site with timeout mechanism
                var startTime = DateTime.Now;
                while (true)
                {
                    try
                    {
                        // Implement site startup logic here
                        // For example:
                        Process.Start(Path.Combine(directoryPath, "site.exe"));
                        break;
                    }
                    catch (Exception ex) when (ex is InvalidOperationException || ex is IOException)
                    {
                        if (DateTime.Now - startTime > TimeSpan.FromMinutes(0.5))
                            throw;

                        Console.WriteLine($"Error starting site {siteName} at {directoryPath}: {ex.Message}");
                        Thread.Sleep(TimeSpan.FromSeconds(1));
                    }
                }

                // Support graceful shutdowns
                // For example:
                if (Directory.GetFiles(directoryPath).Any())
                    Process.Kill(Process.Start(Path.Combine(directoryPath, "site.exe")));
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error starting site {siteName} at {directoryPath}: {ex.Message}");
            }
        }
    }
}
