import java.io.*;
import java.net.*;
import java.util.*;
import com.jcraft.jsch.*;

public class SSHBatchProcessor {
    private static final int MAX_ATTEMPTS = 5;
    private static final int MIN_DELAY_MILLIS = 5000; // 5 seconds
    private static final int MAX_DELAY_MILLIS = 30000; // 30 seconds

    public static void main(String[] args) throws Exception {
        JSch jsch = new JSch();
        Session session = jsch.getSession("username", "hostname", 22);
        session.setPassword("password");

        try (InputStream inputStream = new FileInputStream("script.sh")) {
            String command = "/bin/bash -x <(cat script.sh)";
            int attempt = 0;
            long delayMillis = MIN_DELAY_MILLIS;

            while (true) {
                try {
                    session.exec(command);
                    break;
                } catch (JSchException e) {
                    if (attempt >= MAX_ATTEMPTS) {
                        throw new Exception("Max attempts reached: " + e.getMessage());
                    }

                    attempt++;
                    delayMillis = Math.min(delayMillis * 2, MAX_DELAY_MILLIS);
                    Thread.sleep(delayMillis);
                }
            }

            session.close();
        } finally {
            // Automatically clean up temporary files
            File tempDir = new File(System.getProperty("java.io.tmpdir"), "ssh-batch-processor-temp");
            if (tempDir.exists()) {
                try (FileSystem fs = FileSystems.getDefault()) {
                    Files.walk(tempDir.toPath())
                            .filter(Files::isRegularFile)
                            .map(fs::getPath)
                            .forEach(FileUtil.deleteSilent);
                }
            }
        }
    }
}
