    if (!json_object_object_get_ex(config, "session_timeout", &data.session_timeout)) {
        json_object_object_add(config, "session_timeout", json_object_new_int_value(0));
    }
    // Check if the session timeout is valid
    if (data.session_timeout <= 0) {
        valid = false;
        printf("Invalid session timeout: %d seconds\n", data.session_timeout);
    }

    // Get the session cookie name
    if (!json_object_object_get_ex(config, "session_cookie_name", &data.session_cookie_name)) {
        json_object_object_add(config, "session_cookie_name", json_string_create(""));
    }
    // Check if the session cookie name is valid
    if (strlen(data.session_cookie_name) == 0 || !isalnum(*data.session_cookie_name)) {
        valid = false;
        printf("Invalid session cookie name: %s\n", data.session_cookie_name);
    }

    // Get the session secret key
    if (!json_object_object_get_ex(config, "session_secret_key", &data.session_secret_key)) {
        json_object_object_add(config, "session_secret_key", json_string_create(""));
    }
    // Check if the session secret key is valid
    if (strlen(data.session_secret_key) < 32) {
        valid = false;
        printf("Invalid session secret key: %s\n", data.session_secret_key);
    }

    // Get the session regeneration interval
    int reg_interval = 0;
    if (json_object_object_get_ex(config, "session_regeneration_interval", &reg_interval)) {
        // Check if the session regeneration interval is valid
        if (reg_interval <= 0) {
            valid = false;
            printf("Invalid session regeneration interval: %d seconds\n", reg_interval);
        }
    }

    return valid;
}
