using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class BatchDecryptor
{
    public async Task ProcessBatch(string configFilePath)
    {
        await Task.Run(() =>
        {
            string[] messages = File.ReadAllLines(configFilePath);
            foreach (string message in messages)
            {
                if (!string.IsNullOrEmpty(message))
                {
                    // Parse message details
                    string[] parts = message.Split(',');
                    string encryptedMessage = parts[0];
                    string mode = parts[1];
                    string key = parts[2];
                    string iv = parts[3];
                    string signature = parts[4];

                    try
                    {
                        using (TripleDESCryptoServiceProvider desCrypto = new TripleDESCryptoServiceProvider())
                        {
                            // Set the decryption key and IV
                            desCrypto.Key = Convert.FromBase64String(key);
                            desCrypto.IV = Convert.FromBase64String(iv);

                            // Decrypt the message based on the specified mode
                            byte[] decryptedBytes;
                            if (mode == "CBC")
                                decryptedBytes = desCrypto.DecryptBlock(Convert.FromBase64String(encryptedMessage));
                            else if (mode == "CFB")
                                decryptedBytes = desCrypto.DecryptCFB(Convert.FromBase64String(encryptedMessage));
                            else
                            {
                                // Invalid mode, log and skip the message
                                Console.WriteLine($"Invalid encryption mode '{mode}' for message {message}");
                                continue;
                            }

                            // Verify the HMAC-SHA256 signature
                            byte[] decryptedBytesWithoutSignature = new byte[decryptedBytes.Length - 64];
                            Array.Copy(decryptedBytes, 0, decryptedBytesWithoutSignature, 0, decryptedBytes.Length - 64);
                            byte[] expectedSignature = Convert.FromBase64String(signature);
                            if (!HmacSha256.VerifyHashedData(decryptedBytesWithoutSignature, expectedSignature))
                            {
                                // Signature verification failed, log and skip the message
                                Console.WriteLine($"Invalid signature for message {message}");
                                continue;
                            }

                            // Process the decrypted message
                            string decryptedMessage = Encoding.UTF8.GetString(decryptedBytes);
                            Console.WriteLine($"Decrypted message: {decryptedMessage}");
                        }
                    }
                    catch (CryptographicException ex)
                    {
                        // Log decryption error and attempt fallback if available
                        Console.WriteLine($"Decryption failed for message {message}: {ex.Message}");
                    }
                }
            }
        });
    }

    public static bool HmacSha256.VerifyHashedData(byte[] input, byte[] signature)
    {
        using (HMACSHA256 hmac = new HMACSHA256())
        {
            hmac.Key = Convert.FromBase64String("your-fallback-key");
            byte[] hash = hmac.ComputeHash(input);
            return ByteArraysAreEqual(hash, signature);
        }
    }

    public static bool ByteArraysAreEqual(byte[] array1, byte[] array2)
    {
        if (array1.Length != array2.Length)
            return false;
        for (int i = 0; i < array1.Length; i++)
            if (array1[i] != array2[i])
                return false;
        return true;
    }
}
