using System;
using System.Security.Cryptography;
using System.Text;

public class AESDecryptor
{
    public byte[] Decrypt(byte[] encryptedData, byte[] key, byte[] iv, bool fromBase64 = false)
    {
        using (var aes = Aes.Create())
        {
            aes.Key = key;
            aes.IV = iv;

            if (!fromBase64)
            {
                using (var ms = new MemoryStream(encryptedData))
                {
                    encryptedData = ms.ToArray();
                }
            }

            var decryptedBytes = DecryptChunked(aes, encryptedData);

            return decryptedBytes;
        }
    }

    private byte[] DecryptChunked(AES aes, byte[] data)
    {
        const int chunkSize = 1024 * 1024; // 1 MB
        var decryptedBytes = new List<byte>();

        for (int i = 0; i < data.Length; i += chunkSize)
        {
            var chunk = data.Subarray(i, Math.Min(chunkSize, data.Length - i));
            var decryptedChunk = DecryptChunk(aes, chunk);
            decryptedBytes.AddRange(decryptedChunk);

            if (decryptedChunk.Length == chunkSize)
                Log.Info("Decrypted {0} MB chunk", (i / 1024 / 1024) + 1);
        }

        return decryptedBytes.ToArray();
    }

    private byte[] DecryptChunk(AES aes, byte[] data)
    {
        using (var ms = new MemoryStream())
        {
            using (var cs = new CryptoStream(ms, aes.CreateDecryptor(), CryptoStreamMode.Write))
            {
                cs.Write(data, 0, data.Length);
            }
            return ms.ToArray();
        }
    }

    private void Log(string message)
    {
        // Integrate with an existing logging framework
    }
}
