    private readonly object _lock = new object();
    private readonly Dictionary<string, byte[]> _cache = new Dictionary<string, byte[]>(10);
    private readonly HttpClient _httpClient = new HttpClient();

    public async Task<Byte[]> LoadData(string filePath)
    {
        if (_cache.TryGetValue(filePath, out byte[] cachedData))
            return cachedData;

        lock (_lock)
        {
            if (_cache.TryGetValue(filePath, out cachedData))
                return cachedData;
        }

        try
        {
            using (FileStream stream = File.OpenRead(filePath))
            {
                using (GZipStream gzipStream = new GZipStream(stream, CompressionMode.Read))
                {
                    byte[] data = new byte[stream.Length];
                    await gzipStream.ReadAsync(data, 0, data.Length);
                    return data;
                }
            }
        }
        catch (IOException)
        {
            try
            {
                using (FileStream stream = File.OpenRead(filePath))
                {
                    using (DeflateStream deflateStream = new DeflateStream(stream, CompressionMode.Read))
                    {
                        byte[] data = new byte[stream.Length];
                        await deflateStream.ReadAsync(data, 0, data.Length);
                        return data;
                    }
                }
            }
            catch
            {
                throw;
            }
        }
    }

    public async Task<Byte[]> LoadDataFromService(string filePath)
    {
        try
        {
            using (HttpResponseMessage response = await _httpClient.GetAsync($"https://data-service.com/{filePath}"))
            {
                if (!response.IsSuccessStatusCode)
                    throw new Exception("Failed to retrieve data from service");

                using (Stream stream = await response.Content.ReadAsStreamAsync())
                {
                    using (GZipStream gzipStream = new GZipStream(stream, CompressionMode.Read))
                    {
                        byte[] data = new byte[stream.Length];
                        await gzipStream.ReadAsync(data, 0, data.Length);
                        return data;
                    }
                }
            }
        }
        catch (HttpRequestException)
        {
            try
            {
                using (HttpResponseMessage response = await _httpClient.GetAsync($"https://data-service.com/{filePath}"))
                {
                    if (!response.IsSuccessStatusCode)
                        throw new Exception("Failed to retrieve data from service");

                    using (Stream stream = await response.Content.ReadAsStreamAsync())
                    {
                        using (DeflateStream deflateStream = new DeflateStream(stream, CompressionMode.Read))
                        {
                            byte[] data = new byte[stream.Length];
                            await deflateStream.ReadAsync(data, 0, data.Length);
                            return data;
                        }
                    }
                }
            }
            catch
            {
                throw;
            }
        }
    }

