const { spawn } = require('child_process');
const fs = require('fs');
const path = require('path');

function getMetadata(filePath) {
  const cmd = `stat ${filePath}`;
  return new Promise((resolve, reject) => {
    try {
      const child = spawn('stat', [filePath], {
        maxBuffer: 1024 * 500,
      });

      let output = '';
      child.stdout.on('data', (chunk) => {
        output += chunk.toString();
      });

      child.stderr.on('data', (chunk) => {
        process.stderr.write(chunk);
      });

      child.on('close', () => {
        const [size, modDate] = output.split('\n').slice(5).map((line) => line.trim());
        resolve({ size: parseInt(size), modified: new Date(modDate) });
      });
    } catch (err) {
      reject(err);
    }
  });
}
