using namespace std;
namespace asio = boost::asio;

class SandeshClient {
public:
    SandeshClient(asio::io_context& ctx)
        : io_(ctx) {}

    void sendRequests() {
        int numVertices = 10;
        int numEdges = 20;
        int maxAttempts = 3;
        int delayTime = 1000; // in milliseconds
        random_device rd;

        for (int i = 0; i < numVertices; ++i) {
            boost::beast::http::request<boost::beast::http::string_body> req(boost::beast::http::verb::get, "/vertices");
            req.set("property1", to_string(rd()));
            req.set("property2", to_string(rd()));

            // Send request
            asio::ip::tcp::resolver resolver(io_);
            auto results = resolver.resolve("localhost", "8080");
            asio::ip::tcp::socket socket(io_, results->endpoint());
            boost::beast::http::write(socket, req);
            boost::beast::error_code ec;
            boost::beast::http::read(socket, boost::beast::http::response<boost::beast::http::string_body> result, ec);

            // Handle response
            if (ec) {
                cout << "Error: " << ec.message() << endl;
            } else {
                cout << "Vertex created successfully!" << endl;
            }

            asio::deadline_timer timer(io_);
            timer.expires_after(asio::chrono::milliseconds(delayTime));
            timer.wait();
        }

        for (int i = 0; i < numEdges; ++i) {
            boost::beast::http::request<boost::beast::http::string_body> req(boost::beast::http::verb::get, "/edges");
            req.set("property1", to_string(rd()));
            req.set("property2", to_string(rd()));
            req.set("property3", to_string(rd()));

            // Send request
            asio::ip::tcp::resolver resolver(io_);
            auto results = resolver.resolve("localhost", "8080");
            asio::ip::tcp::socket socket(io_, results->endpoint());
            boost::beast::http::write(socket, req);
            boost::beast::error_code ec;
            boost::beast::http::read(socket, boost::beast::http::response<boost::beast::http::string_body> result, ec);

            // Handle response
            if (ec) {
                cout << "Error: " << ec.message() << endl;
            } else {
                cout << "Edge created successfully!" << endl;
            }

            asio::deadline_timer timer(io_);
            timer.expires_after(asio::chrono::milliseconds(delayTime));
            timer.wait();
        }
    }

private:
    asio::io_context& io_;
};

int main() {
    asio::io_context ctx;
    SandeshClient client(ctx);
    client.sendRequests();

    return 0;
}
