    match matches.value_of("task") {
        Some(task) => {
            match task.as_str() {
                "1" => info!("Executing Task 1");
                "2" => info!("Executing Task 2"),
                "3" => info!("Executing Task 3"),
                _ => error!("Invalid task specified. Please try again."),
            };
            match task.as_str() {
                "1" => task1().await,
                "2" => task2().await,
                "3" => task3(),
                _ => error!("Invalid task specified. Please try again."),
            }
        },
        None => error!("No task specified. Please provide the task number as a command-line argument"),
    }
}
