use std::thread::sleep;
use std::time::Duration;

const MAX_ATTEMPTS: usize = 5;
const RETRY_DELAY: Duration = Duration::from_millis(500);

struct DirectoryManager {
    config: Arc<Mutex<Config>>,
    lock: Arc<Mutex<i32>>,
}

#[derive(Debug, Clone)]
struct Config {
    dirs: HashMap<String, PathBuf>,
}

impl DirectoryManager {
    fn new(config_file_path: &str) -> Self {
        let mut config = Config { dirs: HashMap::new() };
        // Load configuration from file
        // ...
        DirectoryManager { config: Arc::new(Mutex::new(config)), lock: Arc::new(Mutex::new(0)) }
    }

    fn create_dir(&self, dir_name: &str) -> Result<(), String> {
        let mut lock = self.lock.lock();
        for _ in 0..MAX_ATTEMPTS {
            if let Ok(config) = self.config.clone() {
                let path = Path::new(dir_name);
                let p = path.canonicalize()?;
                match fs::create_dir_all(p.as_path()) {
                    Ok(_) => {
                        config.dirs.insert(String::from(dir_name), p);
                        println!("Created directory: {}", dir_name);
                        return Ok(());
                    }
                    Err(e) => {
                        if e.kind() == std::io::ErrorKind::AlreadyExists {
                            println!("Directory already exists: {}", dir_name);
                            return Ok(());
                        } else {
                            return Err(format!("Failed to create directory: {}", e));
                        }
                    }
                }
            }
            sleep(RETRY_DELAY);
        }
        Err("Maximum attempts reached. Directory creation failed.".to_string())
    }

    fn update_dir(&self, old_name: &str, new_name: &str) -> Result<(), String> {
        // ...
    }

    fn delete_dir(&self, dir_name: &str) -> Result<(), String> {
        let mut lock = self.lock.lock();
        for _ in 0..MAX_ATTEMPTS {
            if let Ok(config) = self.config.clone() {
                match config.dirs.remove(dir_name) {
                    Some(old_path) => {
                        println!("Deleted directory: {}", dir_name);
                        match fs::remove_dir_all(old_path.as_path()) {
                            Ok(_) => return Ok(()),
                            Err(e) => {
                                if e.kind() == std::io::ErrorKind::NotFound {
                                    println!("Directory not found: {}", dir_name);
                                    return Ok(());
                                } else {
                                    return Err(format!("Failed to delete directory: {}", e));
                                }
                            }
                        }
                    }
                    None => {
                        println!("Directory not found: {}", dir_name);
                        return Ok(())
                    }
                }
            }
            sleep(RETRY_DELAY);
        }
        Err("Maximum attempts reached. Directory deletion failed.".to_string())
    }

    fn log_operation(&self, operation: &str) -> Result<(), String> {
