class JSONRegistry:
    _registry = defaultdict(dict)
    _lock = Lock()

    @classmethod
    def register_factory(cls, factory_type, factory_func):
        with cls._lock:
            if isinstance(factory_type, str):
                factory_type = factory_type.encode('utf-8')
            elif not isinstance(factory_type, bytes):
                raise ValueError("Invalid type for registry")
            cls._registry[factory_type]['factory_func'] = factory_func

    @classmethod
    def get_factory(cls, factory_type):
        with cls._lock:
            if isinstance(factory_type, str):
                factory_type = factory_type.encode('utf-8')
            elif not isinstance(factory_type, bytes):
                raise ValueError("Invalid type for registry")
            return cls._registry[factory_type].get('factory_func')

