#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_KEY 10000
#define INT_RANGE 100

typedef struct {
    int key;
    int value;
} Record;

Record **hashTable;
int tableSize = 16; // Initial size of the hash table

void initHashTable() {
    hashTable = (Record **)malloc(tableSize * sizeof(Record *));
    for(int i = 0; i < tableSize; i++) {
        hashTable[i] = NULL;
    }
}

void insertRecord(int key, int value) {
    int index = key % tableSize;
    Record *record = (Record *)malloc(sizeof(Record));
    record->key = key;
    record->value = value;
    if(hashTable[index] == NULL || hashTable[index]->key != key) {
        hashTable[index] = record;
    } else {
        free(record);
    }
}

void cleanup() {
    for(int i = 0; i < tableSize; i++) {
        Record *temp = hashTable[i];
        while(temp != NULL) {
            Record *next = temp->next;
            free(temp);
            temp = next;
        }
    }
    free(hashTable);
}

int findLargest() {
    int largest = INT_MIN;
    for(int i = 0; i < tableSize; i++) {
        Record *temp = hashTable[i];
        while(temp != NULL) {
            if(temp->value > largest) {
                largest = temp->value;
            }
            temp = temp->next;
        }
    }
    return largest;
}

void serialize() {
    FILE *file = fopen("data", "wb");
    for(int i = 0; i < tableSize; i++) {
        Record *temp = hashTable[i];
        while(temp != NULL) {
            fwrite(&temp->key, sizeof(int), 1, file);
            fwrite(&temp->value, sizeof(int), 1, file);
            temp = temp->next;
        }
    }
    fclose(file);
}

void deserialize() {
    FILE *file = fopen("data", "rb");
    for(int i = 0; i < tableSize; i++) {
        Record *record = (Record *)malloc(sizeof(Record));
        fread(&record->key, sizeof(int), 1, file);
        fread(&record->value, sizeof(int), 1, file);
        // Insert record into hash table
    }
    fclose(file);
}

int main() {
    srand(time(NULL)); // Seed random number generator

    initHashTable();

    for(int i = 0; i < MAX_KEY; i++) {
        int key = rand() % MAX_KEY;
        insertRecord(key, rand() % INT_RANGE);
    }

    printf("Largest integer: %d\n", findLargest());

    serialize();

    // Deserialize and re-insert records

    cleanup();

    return 0;
}
