#include <stdlib.h>
#include <stdio.h>

typedef struct {
    int key;
    long offset;
    int value;
} Record;

Record* allocateRecords(int initialCapacity) {
    Record* records = (Record*)malloc(initialCapacity * sizeof(Record));
    if (!records) {
        return NULL; // Handle memory allocation failure
    }
    for (int i = 0; i < initialCapacity; i++) {
        records[i].key = -1;
        records[i].offset = -1;
        records[i].value = 0;
    }
    return records;
}

void resizeRecords(Record** records, int newCapacity) {
    Record* newRecords = (Record*)realloc(*records, newCapacity * sizeof(Record));
    if (!newRecords) {
        return; // Handle memory reallocation failure
    }
    *records = newRecords;
    for (int i = newCapacity - 1; i < (*records)[0]; i++) {
        (*records)[i].key = -1;
        (*records)[i].offset = -1;
        (*records)[i].value = 0;
    }
}

void addRecord(Record** records, int key, long offset, int value) {
    Record* record = *records;
    for (int i = 0; i < record->size; i++) {
        if (record[i].key == key) {
            // Handle duplicate key
            return;
        }
    }
    // Add new record
    (*records)->size++;
    if ((*records)->size >= (*records)->capacity * 2) {
        resizeRecords(records, (*records)->capacity * 2);
    }
}

Record* searchRecord(Record** records, int key) {
    Record* record = *records;
    for (int i = 0; i < record->size; i++) {
        if (record[i].key == key) {
            return &record[i];
        }
    }
    // Handle not found
    return NULL;
}

void freeRecords(Record** records) {
    if (!*records) {
        return;
    }
    free(*records);
    *records = NULL;
}
