#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dlfcn.h>

typedef struct {
    char* name;
    void (*implementation)(void);
    // configuration parameters
} Algorithm;

Algorithm* loadAlgorithms(const char** supportedAlgos) {
    Algorithm* algorithms = NULL;
    int count = 0;

    for (int i = 0; i < sizeof(supportedAlgos)/sizeof(supportedAlgos[0]); i++) {
        void* handle = dlopen(supportedAlgos[i], RTLD_LAZY);
        if (!handle) {
            fprintf(stderr, "Error loading algorithm: %s\n", supportedAlgos[i]);
            continue;
        }

        Algorithm alg = (Algorithm)malloc(sizeof(struct Algorithm));
        alg->name = strdup(supportedAlgos[i]);
        alg->implementation = (void(*)(void))dlsym(handle, "algorithmImplementation");
        if (!alg->implementation) {
            fprintf(stderr, "Error loading algorithm implementation: %s\n", supportedAlgos[i]);
            free(alg);
            dlclose(handle);
            continue;
        }

        algorithms = realloc(algorithms, (count + 1) * sizeof(Algorithm));
        algorithms[count] = alg;

        dlclose(handle);
        count++;
    }

    if (count == 0) {
        return NULL;
    }

    Algorithm* result = (Algorithm*)malloc((count+1)*sizeof(Algorithm));
    memcpy(result, algorithms, count*sizeof(Algorithm));
    free(algorithms);

    return result;
}
