public class JsonProcessorService {
    private static final int MAX_INFLIGHT_REQUESTS = 1000;
    private static final int CACHING_THRESHOLD = 10000;
    private static final ObjectMapper mapper = new ObjectMapper();

    private ConcurrentHashMap<String, CustomDataModel> cache = new ConcurrentHashMap<>();
    private CopyOnWriteArrayList<CustomDataModel> uniqueEntries = new CopyOnWriteArrayList<>();

    public void processJson(String jsonString) {
        try {
            JsonNode jsonNode = mapper.readTree(jsonString);
            if (jsonNode.isArray()) {
                for (JsonNode node : jsonNode) {
                    processJson(node);
                }
            } else {
                processJson(node);
            }
        } catch (IOException e) {
            // Log error and skip malformed JSON
            logError("Malformed JSON: " + jsonString, e);
            return;
        }

        if (!isUnique(jsonNode)) {
            logDuplicateEntry(jsonNode.toString());
            return;
        }

        CustomDataModel dataModel = new CustomDataModel(mapper.treeToValue(jsonNode));
        cache.put(dataModel.getUniqueId(), dataModel);

        // Retain only unique entries
        if (uniqueEntries.size() < CACHING_THRESHOLD) {
            uniqueEntries.add(dataModel);
        }
    }

    private boolean isUnique(JsonNode node) {
        return !cache.containsValue(mapper.treeToValue(node));
    }

