#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int *states;
    int num_states;
    int last_state;
} FSA;

FSA* create_new_state_list(int* states, int num_states, FSA* fsa, int max_size) {
    FSA* new_fsa = (FSA*)malloc(sizeof(FSA));
    if (!new_fsa) return NULL;

    pthread_mutex_lock(&fsa->mutex);
    if (num_states > max_size) {
        free(new_fsa);
        pthread_mutex_unlock(&fsa->mutex);
        return NULL;
    }

    new_fsa->states = (int*)calloc(num_states, sizeof(int));
    if (!new_fsa->states) {
        free(new_fsa);
        pthread_mutex_unlock(&fsa->mutex);
        return NULL;
    }

    new_fsa->num_states = num_states;
    new_fsa->last_state = num_states - 1;

    if (fsa->last_state >= 0) {
        fsa->states[fsa->last_state] = &new_fsa->last_state;
    } else {
        new_fsa->next = NULL;
    }

    pthread_mutex_unlock(&fsa->mutex);
    return new_fsa;
}

