    unsigned char *key;
    unsigned char *iv;
} CipherContext;

// Function to initialize the AES-256-GCM cipher
CipherContext* aes256_gcm_init(const char* passphrase) {
    // Initialize the KDF (PBKDF2) to derive the encryption key from the passphrase
    PBKDF2_CTX kdf_ctx;
    PBKDF2_hmac_sha1(kdf_ctx, NULL, 0, passphrase, strlen(passphrase), 32, &kdf_ctx.key, NULL);

    // Initialize the AES-256-GCM cipher context
    CipherContext* ctx = (CipherContext*)malloc(sizeof(CipherContext));
    ctx->ctx = EVP_CIPHER_CTX_new();
    EVP_CipherInit(ctx->ctx, EVP_aes_256_gcm(), kdf_ctx.key, 32, NULL);

    // Get the IV length and key length based on system resources and performance constraints
    int iv_len = EVP_CIPHER_CTX_block_size(ctx->ctx);
    int key_len = EVP_CIPHER_CTX_key_length(ctx->ctx);

    // Initialize the IV and key
    ctx->iv = (unsigned char*)malloc(iv_len);
    RAND_bytes(ctx->iv, iv_len);
    ctx->key = kdf_ctx.key;

    return ctx;
}

// Function to enable the cipher context
void aes256_gcm_enable(CipherContext* ctx) {
    EVP_CipherInit(ctx->ctx, EVP_aes_256_gcm(), ctx->key, 32, ctx->iv);
}

// Function to disable the cipher context and free memory
void aes256_gcm_disable(CipherContext* ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx);
    free(ctx->key);
    free(ctx->iv);
    free(ctx);
}

int main() {
    CipherContext* ctx = aes256_gcm_init("your_passphrase_here");
    aes256_gcm_enable(ctx);
    // Use the cipher context for encryption/decryption operations
    aes256_gcm_disable(ctx);
    return 0;
}
