#include <stdarg.h>
#include <semaphore.h>

#define LOG_MAX_SIZE 1024 * 1024 // 1MB
#define MAX_LOGGERS 16

sem_t log_semaphore;
int current_loggers = 0;

void appendLogMessage(char* filename, int threshold, const char* format, ...) {
    FILE* file = fopen(filename, "a");
    if (file == NULL) {
        // Handle error
        return;
    }

    va_list args;
    va_start(args, format);

    size_t message_len = 0;
    char buffer[LOG_MAX_SIZE];
    while ((message_len + vsnprintf(buffer + message_len, LOG_MAX_SIZE - message_len, format, args)) >= LOG_MAX_SIZE) {
        if (sem_wait(&log_semaphore) == -1) {
            // Handle error
            fclose(file);
            return;
        }
        current_loggers++;
        // Write log entry
        if (fputs(buffer, file) < 0) {
            // Handle error
            fclose(file);
            sem_post(&log_semaphore);
            return;
        }
        // Reset message buffer and length
        message_len = vsnprintf(buffer, LOG_MAX_SIZE, format, args);

        if (current_loggers >= MAX_LOGGERS) {
            // Handle max loggers reached
            fclose(file);
            while (sem_wait(&log_semaphore) == -1 && current_loggers > 0) {}
            current_loggers--;
            return;
        }
    }

    // Write formatted message
    vsnprintf(buffer, LOG_MAX_SIZE, format, args);

    if (fputs(buffer, file) < 0) {
        // Handle error
        fclose(file);
        return;
    }

    va_end(args);
    fclose(file);

    sem_post(&log_semaphore);
}
