import argparse
import datetime
import os
import yaml
from ruamel.yaml import YAMLConstructor

def load_yaml_config(yaml_file):
    with open(yaml_file, 'r') as f:
        return yaml.safe_load(f)

def parse_args():
    parser = argparse.ArgumentParser(description='Dynamic configuration update script')
    parser.add_argument('target_env', help='Target environment (e.g., development, staging, production)')
    parser.add_argument('--dry-run', action='store_true', help='Simulate the update process without modifying the actual file')
    return parser.parse_args()

def backup_config(config_file):
    timestamp = datetime.datetime.now().strftime('%Y-%m-%d-%H-%M-%S')
    backup_dir = f'config-backups/{timestamp}'
    os.makedirs(backup_dir, exist_ok=True)
    os.replace(config_file, f'{backup_dir}/{os.path.basename(config_file)}')

def update_config(config_file, target_env, dry_run):
    config = load_yaml_config(config_file)

    # Fallback mechanism for environment-specific settings
    if target_env not in config:
        print(f'Using default configuration for {target_env}')
        target_config = config['default']
    else:
        target_config = config[target_env]

    # Replace placeholders with environment-specific variables
    updated_config = {}
    for key, value in target_config.items():
        updated_config[key] = value.format(**{k: v for k, v in os.environ.items()})

    if dry_run:
        print(f'Dry-run update of {config_file}:')
        print(yaml.dump(updated_config, default_flow_style=False))
    else:
        with open(config_file, 'w') as f:
            yaml.safe_dump(updated_config, f, default_flow_style=False)

        # Backup original file
        backup_config(config_file)

def main():
    args = parse_args()

    try:
        config_file = 'config.yaml'  # Replace with actual configuration file path
        update_config(config_file, args.target_env, args.dry_run)
    except Exception as e:
        print(f'Error: {str(e)}')
        raise

    print('Configuration updated successfully!')

if __name__ == '__main__':
    main()
