import logging
from typing import Dict

async def authenticate_user(username: str, password: str) -> Dict[str, str]:
    # Validate user credentials against third-party API with retry mechanism
    attempts = 0
    while attempts < 3:
        try:
            auth_response = await api_request("https://auth-api.com", {"username": username, "password": password})
            if auth_response["status"] == "success":
                return {"status": "success", "message": "Authentication successful"}
        except (asyncio.TimeoutError, Exception) as e:
            attempts += 1
            # Exponential backoff with a max delay of 30 seconds and 3 retries
            await asyncio.sleep(2 ** attempts)
    return {"status": "failure", "message": "Invalid credentials"}

async def fetch_email(username: str) -> Dict[str, str]:
    # Fetch user's email address from external API with fallback mechanism
    attempts = 0
    while attempts < 3:
        try:
            email_response = await api_request("https://email-api.com", {"username": username})
            if email_response["status"] == "success":
                return {"status": "success", "email": email_response["data"]}
        except (asyncio.TimeoutError, Exception) as e:
            attempts += 1
            # Fallback to local database or alternative email retrieval method
            await asyncio.sleep(2 ** attempts)
    return {"status": "failure", "message": "Email retrieval failed"}

def generate_session_token() -> str:
    # Generate unique session token using secure storage mechanism
    return f"SessionToken-{uuid.uuid4().hex}"

async def process_authentication_request(username: str, password: str) -> Dict[str, str]:
    auth_result = await authenticate_user(username, password)
    if auth_result["status"] == "success":
        # Generate unique session token and store securely
        session_token = generate_session_token()
        # Fetch user's email address with fallback mechanism
        email_result = await fetch_email(username)
        return {"status": "success", "message": f"Authentication successful, email: {email_result['email']}", "session_token": session_token}
    else:
        return auth_result

def log_authentication_event(event_type: str, username: str) -> None:
    # Log authentication attempts, successes, and failures
    logging.info(f"{event_type} for user {username}")

async def rate_limit_authenticated_users() -> None:
    # Implement rate-limiting mechanism using fixed window algorithm
    await asyncio.sleep(1)

def main():
    loop = asyncio.get_event_loop()
    loop.set_logger(logging.getLogger())
    try:
        while True:
            username = input("Enter username: ")
            password = input("Enter password: ")
            auth_result = loop.run_until_complete(process_authentication_request(username, password))
            print(auth_result)
            log_authentication_event("success" if auth_result["status"] == "success" else "failure", username)
    except KeyboardInterrupt:
        pass

if __name__ == "__main__":
    main()
