#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define a struct to represent a semaphore
typedef struct {
    int value;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} Semaphore;

// Define a struct to manage the pool of semaphores
typedef struct {
    int size; // Current number of semaphores in the pool
    int max_size; // Maximum allowed number of semaphores in the pool
    Semaphore** semaphores; // Array of semaphore pointers
    pthread_mutex_t mutex; // Mutex for synchronizing access to the pool
    pthread_cond_t cond; // Condition variable for signaling changes to the pool
} SemaphorePool;

// Function to create a new semaphore with an initial value
Semaphore* semaphore_create(int initial_value) {
    Semaphore* sem = (Semaphore*)malloc(sizeof(Semaphore));
    sem->value = initial_value;
    pthread_mutex_init(&sem->mutex, NULL);
    pthread_cond_init(&sem->cond, NULL);
    return sem;
}

// Function to add a new semaphore to the pool
void semaphore_pool_add(SemaphorePool* pool, Semaphore* sem) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->size >= pool->max_size) {
        // Handle memory allocation failure
        printf("Error: Pool is full. Cannot add more semaphores.\n");
        return;
    }
    pool->semaphores[pool->size++] = sem;
    pthread_mutex_unlock(&pool->mutex);
}

// Function to remove a semaphore from the pool
void semaphore_pool_remove(SemaphorePool* pool, int index) {
    if (index < 0 || index >= pool->size) {
        // Handle invalid index
        printf("Error: Invalid index. Cannot remove semaphore.\n");
        return;
    }
    pthread_mutex_lock(&pool->mutex);
    pool->semaphores[index] = NULL; // Mark the semaphore as removed
    pool->size--;
    pthread_mutex_unlock(&pool->mutex);
}

// Function to acquire a resource from a semaphore in the pool
void semaphore_acquire(SemaphorePool* pool, int index) {
    Semaphore* sem = pool->semaphores[index];
    pthread_mutex_lock(&sem->mutex);
    while (sem->value <= 0) {
        // Wait for the semaphore to become available or timeout after 10 seconds
        pthread_cond_wait(&sem->cond, &sem->mutex);
    }
    sem->value--;
    pthread_mutex_unlock(&sem->mutex);
}

// Function to release a resource from a semaphore in the pool
void semaphore_release(SemaphorePool* pool, int index) {
    Semaphore* sem = pool->semaphores[index];
    pthread_mutex_lock(&sem->mutex);
    sem->value++;
    if (sem->value > 0) {
        // Signal to threads waiting for the semaphore
        pthread_cond_signal(&sem->cond);
    }
    pthread_mutex_unlock(&sem->mutex);
}

// Function to initialize a new thread and add it to the pool
void* thread_function(void* arg) {
    int index = *(int*)arg;
    // Perform thread-specific actions
    printf("Thread %d acquired resource from semaphore.\n", index);
    // Release the resource when done
    semaphore_release(pool, index);
    return NULL;
}

int main() {
    // Initialize a new semaphore pool with a maximum size of 10 semaphores
    SemaphorePool* pool = (SemaphorePool*)malloc(sizeof(SemaphorePool));
    pool->size = 0;
    pool->max_size = 10;
    pool->semaphores = (Semaphore**)malloc(pool->max_size * sizeof(Semaphore*));
    pthread_mutex_init(&pool->mutex, NULL);
    pthread_cond_init(&pool->cond, NULL);

    // Create and add a few semaphores to the pool
    Semaphore* sem1 = semaphore_create(5);
    Semaphore* sem2 = semaphore_create(3);
    semaphore_pool_add(pool, sem1);
    semaphore_pool_add(pool, sem2);

    // Create and start 10 threads that acquire resources from the pool
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        int* index = (int*)malloc(sizeof(int));
        *index = i;
        pthread_create(&threads[i], NULL, thread_function, index);
    }

    // Wait for all threads to finish
    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up the pool and semaphores
    for (int i = 0; i < pool->size; i++) {
        semaphore_pool_remove(pool, i);
        free(pool->semaphores[i]);
    }
    free(pool->semaphores);
    free(pool);

    return 0;
}
