typedef struct {
    int key;
    long offset;
    short value;
} record;

record* expandGraphStructure(int numRecords) {
    // Fetch initial graph parameters from data source
    int initNumNodes = 0; 
    int initMaxKey = 0; 

    // Initialize the array with a default size
    int capacity = 10;
    record* records = (record*)malloc(capacity * sizeof(record));

    for (int i = 0; i < numRecords; i++) {
        // Generate random key and offset within the existing range
        int newKey = rand() % (initMaxKey + 1);
        long newOffset = rand() % (initNumNodes + 1);

        // Ensure uniqueness of keys and offsets
        for (int j = 0; j < capacity; j++) {
            if ((records[j].key == newKey) || (records[j].offset == newOffset)) {
                i--; // Roll back the loop to try again
                break;
            }
        }

        // Check if we need to resize the array
        if (i >= capacity) {
            capacity *= 2; 
            record* temp = (record*)realloc(records, capacity * sizeof(record));
            records = temp;
        }

        // Create a new record with unique key and offset
        record newRecord;
        newRecord.key = newKey;
        newRecord.offset = newOffset;
        newRecord.value = rand() % 256; 
        records[i] = newRecord;
    }

    return records;
}
