#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* name;
    int priority;
    struct project* dependencies;
} project;

project* init_project(char* name, int priority) {
    project* p = (project*)malloc(sizeof(project));
    if (!p) return NULL; // Memory allocation failure

    p->name = malloc(strlen(name) + 1);
    if (!p->name) return NULL; // Memory allocation failure
    strcpy(p->name, name);

    p->priority = priority;
    p->dependencies = NULL;

    return p;
}

void free_project(project* p) {
    if (p) {
        free(p->name);
        free(p);
    }
}

void traverse_projects(project* root) {
    project* current = root;
    while (current) {
        printf("Project %s, priority %d:\n", current->name, current->priority);
        project* dependency = current->dependencies;
        while (dependency) {
            printf("  Dependency: %s\n", dependency->name);
            dependency = dependency->dependencies;
        }
        free_project(current);
        current = current->dependencies;
    }
}

int main() {
    project* root = init_project("Project A", 1);
    if (!root) return 1; // Memory allocation failure

    project* p2 = init_project("Project B", 2);
    if (!p2) return 1; // Memory allocation failure
    root->dependencies = p2;

    project* p3 = init_project("Project C", 3);
    if (!p3) return 1; // Memory allocation failure
    p2->dependencies = p3;
    p3->dependencies = NULL;

    traverse_projects(root);

    free_project(root);
