#include <forward_list>
#include <string>
#include <vector>
#include <unordered_map>

void insertStringAfter(std::forward_list<std::string>& list,
                        const std::string& searchStr, 
                        const std::string& insertStr, 
                        int maxKeySize) {
    std::vector<int> keys(maxKeySize);
    std::vector<long> offsets(maxKeySize);

    // Initialize key and offset arrays
    for (int i = 0; i < maxKeySize; i++) {
        keys[i] = i;
        offsets[i] = i;
    }

    auto it = list.begin();
    while (it != list.end()) {
        if (*it == searchStr) {
            list.insert_after(it, insertStr);
            break;
        }
        it++;
    }

    // Insert unique key values into the record structure
    for (int i = 0; i < maxKeySize; i++) {
        int key = keys[i];
        long offset = offsets[i];

        // Hash-based lookup and insertion of unique keys
        if (!insertKeyAndOffset(list, key, offset)) {
            break;
        }
    }

    // Cleanup function to release allocated memory
    void cleanup() {
        for (int i = 0; i < maxKeySize; i++) {
            delete[] new int[keys[i]];
            delete[] new long[offsets[i]];
        }
    }
}
