#include <iostream>
#include <cmath>
#include <random>

class RandomNumberGenerator {
public:
    RandomNumberGenerator(unsigned long long seed = 1) : _seed(seed) {}

    template<typename Distribution>
    typename Distribution::result_type generate(const Distribution& dist) {
        std::mt19937 engine(_seed);
        return dist(engine);
    }

    void setSeed(unsigned long long seed) {
        _seed = seed;
    }

private:
    unsigned long long _seed;
};

class UniformDistribution {
public:
    template<typename Engine>
    double operator()(Engine& e) const {
        std::uniform_real_distribution<double> distribution(0.0, 1.0);
        return distribution(e);
    }
};

class NormalDistribution {
public:
    template<typename Engine>
    double operator()(Engine& e) const {
        std::normal_distribution<double> distribution(0.0, 1.0);
        return distribution(e);
    }
};

template<typename Distribution>
class CustomDistribution : public Distribution {
public:
    using Distribution::operator();

    template<typename Engine>
    typename Distribution::result_type operator()(Engine& e) const {
        return (*this)(e);
    }
};

int main() {
    RandomNumberGenerator rng;
    UniformDistribution uniformDist;
    NormalDistribution normalDist;

    for (int i = 0; i < 10; ++i) {
        std::cout << "Uniform: " << rng.generate(uniformDist) << "\n";
        std::cout << "Normal: " << rng.generate(normalDist) << "\n";
    }

    return 0;
}

