using Newtonsoft.Json;

public class ComplexObjectProcessor
{
    private readonly ILogger _logger;
    private readonly ICachingStrategy _cache;

    public List<string> ProcessComplexObjects(List<ComplexObject> objects, string directoryPath, string fileNamingConvention)
    {
        var filePaths = new List<string>();

        foreach (var obj in objects)
        {
            try
            {
                var json = JsonConvert.SerializeObject(obj);
                var filePath = Path.Combine(directoryPath, $"{fileNamingConvention}_{Guid.NewGuid()}.json");
                File.WriteAllText(filePath, json);
                _logger.LogInformation($"Object serialized and written to file: {filePath}");
                filePaths.Add(filePath);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error processing complex object");
            }
        }

        return filePaths;
    }
}

public class EmployeeRecordSerializer
{
    private readonly ILogger _logger;

    public List<string> SerializeEmployeeRecords(string connectionString, string username, string password, int supervisorId, string directoryPath)
    {
        var filePaths = new List<string>();

        using (var connection = new SqlConnection(connectionString))
        {
            try
            {
                connection.Open();

                using (var command = new SqlCommand("SELECT name, city, address FROM Employees WHERE supervisor_id = @supervisorId", connection))
                {
                    command.Parameters.AddWithValue("@supervisorId", supervisorId);

                    using (SqlDataReader reader = command.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            var employeeRecord = new
                            {
                                Name = reader["name"].ToString(),
                                City = reader["city"].ToString(),
                                Address = reader["address"].ToString()
                            };

                            try
                            {
                                var json = JsonConvert.SerializeObject(employeeRecord);
                                var filePath = Path.Combine(directoryPath, $"{Guid.NewGuid()}.json");
                                File.WriteAllText(filePath, json);
                                _logger.LogInformation($"Employee record serialized and written to file: {filePath}");
                                filePaths.Add(filePath);
                            }
                            catch (Exception ex)
                            {
                                _logger.LogError(ex, "Error serializing employee record");
                            }
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error connecting to database");
            }
        }

        return filePaths;
    }
}
