        public ConfigReader(string configFilePath)
        {
            _configFilePath = configFilePath;
            _jsonSerializerSettings = new JsonSerializerSettings { Formatting = Formatting.Indented };
        }

        public GameConfig LoadConfig()
        {
            if (!File.Exists(_configFilePath))
                throw new FileNotFoundException("Configuration file not found", _configFilePath);

            return JsonConvert.DeserializeObject<GameConfig>(File.ReadAllText(_configFilePath), _jsonSerializerSettings);
        }
    }

    public class GameConfig
    {
        public int TileWidth { get; set; }
        public int TileHeight { get; set; }
        public int WorldWidth { get; set; }
        public int WorldHeight { get; set; }
        public double CameraSpeed { get; set; }
    }

    public class ImageConverter
    {
        private readonly string _imagePath;
        private readonly string _outputPath;
        private readonly IRestClient _restClient;

        public ImageConverter(string imagePath, string outputPath)
        {
            _imagePath = imagePath;
            _outputPath = outputPath;
            _restClient = new RestClient("https://api.your-third-party-library.com/");
        }

        public void ConvertImages()
        {
            var images = Directory.GetFiles(_imagePath);
            foreach (var image in images)
            {
                try
                {
                    var response = _restClient.Post(new RestRequest("/convert", Method.POST));
                    if (response.StatusCode == System.Net.HttpStatusCode.OK)
                    {
                        File.WriteAllBytes(Path.Combine(_outputPath, Path.GetFileName(image)), response.RawResponse.Bytes);
                    }
                    else
                    {
                        Console.WriteLine($"Error converting {image}: {response.ErrorMessage}");
                    }
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"An error occurred while converting {image}: {ex.Message}");
                }
            }
        }
    }

