    private static final String DEFAULT_FILE_NAME = "user_profile.json";
    private static final String JSON_FILE_DIR = "config/";

    public UserProfile loadUserProfile() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(SerializationFeature.INDENT_OUTPUT);

        try {
            // Load user profile from file
            String userProfileJson = loadFileContent(DEFAULT_FILE_NAME);
            if (userProfileJson == null) {
                // Create a default user profile and save it to the file
                UserProfile defaultUserProfile = new UserProfile();
                saveUserProfile(defaultUserProfile, DEFAULT_FILE_NAME);
                return defaultUserProfile;
            }

            // Parse JSON data
            UserProfile userProfile = mapper.readValue(userProfileJson, UserProfile.class);

            // Start monitoring for changes in the JSON file
            startFileMonitoring(DEFAULT_FILE_NAME, userProfile);

            return userProfile;
        } catch (JsonMappingException e) {
            // Handle unexpected JSON errors
            logger.error("Error parsing user profile JSON: " + e.getMessage());
            return new UserProfile();
        } catch (IOException e) {
            // Handle file read/write errors
            logger.error("Error reading/writing user profile file: " + e.getMessage());
            return new UserProfile();
        }
    }

    private String loadFileContent(String fileName) throws IOException {
        try (InputStream inputStream = getClass().getResourceAsStream(JSON_FILE_DIR + fileName)) {
            if (inputStream == null) {
                // File not found, create a default user profile and save it to the file
                return null;
            }
            return IOUtils.toString(inputStream);
        }
    }

    private void saveUserProfile(UserProfile userProfile, String fileName) throws IOException {
        try (OutputStream outputStream = getClass().getResourceAsStream(JSON_FILE_DIR + fileName)) {
