namespace UserAccountManagementConsoleApp
{
    public class Program
    {
        private readonly ILogger<Program> _logger;
        private readonly UserDbContext _dbContext;
        private readonly JWTService _jwtService;
        private readonly TwoFactorAuthenticator _twoFactorAuthenticator;

        public Program(ILogger<Program> logger, UserDbContext dbContext, JWTService jwtService, TwoFactorAuthenticator twoFactorAuthenticator)
        {
            _logger = logger;
            _dbContext = dbContext;
            _jwtService = jwtService;
            _twoFactorAuthenticator = twoFactorAuthenticator;
        }

        [ApiController]
        [Route("api/[controller]")]
        public class UserController : ControllerBase
        {
            private readonly UserManager<User> _userManager;

            public UserController(UserManager<User> userManager)
            {
                _userManager = userManager;
            }

            [HttpPost]
            public async Task<IActionResult> CreateUser([FromBody] CreateUserRequest request)
            {
                var user = await _userManager.CreateAsync(new User { Username = request.Username, Password = request.Password }, false);
                if (user == null) return BadRequest("Username already exists");
                return CreatedAtAction(nameof(GetUser), new { id = user.Id }, user);
            }

            [HttpGet]
            public async Task<IActionResult> GetUser([FromRoute] int id)
            {
                var user = await _userManager.FindByIdAsync(id.ToString());
                if (user == null) return NotFound();
                return Ok(user);
            }

            [HttpPut]
            public async Task<IActionResult> UpdateUser([FromBody] UpdateUserRequest request, [FromRoute] int id)
            {
                var user = await _userManager.FindByIdAsync(id.ToString());
                if (user == null) return NotFound();
                user.Username = request.NewUsername;
                user.Password = request.NewPassword;
                await _dbContext.SaveChangesAsync();
                return Ok(user);
            }

            [HttpDelete]
            public async Task<IActionResult> DeleteUser([FromRoute] int id)
            {
                var user = await _userManager.FindByIdAsync(id.ToString());
                if (user == null) return NotFound();
                await _dbContext.RemoveAsync(user);
                await _dbContext.SaveChangesAsync();
                return NoContent();
            }

            [HttpPost("2fa")]
            public async Task<IActionResult> EnableTwoFactorAuth([FromBody] Enable2faRequest request)
            {
                var user = await _userManager.FindByIdAsync(request.UserId.ToString());
                if (user == null) return NotFound();
                _twoFactorAuthenticator.Enable2FA(user);
                return Ok();
            }

            [HttpPost("2fa/validate")]
            public async Task<IActionResult> ValidateTwoFactorAuth([FromBody] Validate2faRequest request)
            {
                var user = await _userManager.FindByIdAsync(request.UserId.ToString());
                if (user == null) return NotFound();
                if (!_twoFactorAuthenticator.Validate2FA(user, request.Code))
                    return BadRequest("Invalid 2FA code");
                return Ok();
            }
        }

        public class CreateUserRequest
        {
            public string Username { get; set; }
            public string Password { get; set; }
