const require = require('require');
const blueslip = require('blueslip');
const async = require('async');
const fs = require('fs');
const os = require('os');

function runTests(moduleName, tests) {
  const testResults = [];
  let retries = 0;
  let retryLimit = 3;

  async.parallel(
    tests.map((test) => {
      return (callback) => {
        try {
          blueslip.reset(); // Reset mocking library before each test
          const startTime = process.hrtime()[0];
          require(moduleName)[test.name](); // Execute the test
          const endTime = process.hrtime()[0];
          testResults.push({ testName: test.name, duration: (endTime - startTime) / 1e6 });
          console.log(`Test "${test.name}" passed in ${endTime - startTime}ms`);
        } catch (err) {
          retries++;
          if (retries <= retryLimit) {
            setTimeout(() => {
              runTests(moduleName, tests);
            }, 1000);
          } else {
            testResults.push({ testName: test.name, duration: null });
            console.error(`Test "${test.name}" failed after ${retries} retries`);
          }
        } finally {
          if (os.platform() === 'win32') {
            // Handle Windows-specific issues with mocking library
          }
        }
      };
    }),
    (err) => {
      if (err) {
        console.error('Test execution failed:', err);
      }

      const summaryReport = {
        successful: testResults.filter((result) => result.duration).length,
        failed: testResults.length - summaryReport.successful,
        retried: retries > 0 ? retries : 0
      };

      fs.writeFileSync('test-report.json', JSON.stringify(summaryReport));

      console.log(`Test suite completed with ${summaryReport.failed} failures and ${retries} retries`);
    }
  );
}

module.exports = runTests;
