import requests
from bs4 import BeautifulSoup
from concurrent.futures import ThreadPoolExecutor, as_completed
from urllib.parse import urlparse

def extract_metadata(url):
    # Send a GET request to the URL and get the response
    try:
        response = requests.get(url)
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        print(f"Error occurred while processing {url}: {e}")
        return {}

    soup = BeautifulSoup(response.content, 'html.parser')

    metadata = {
        "title": soup.find('title').text.strip(),
        "meta_description": soup.find('meta', attrs={'name': 'description'})['content'].strip(),
        "external_links": [a['href'] for a in soup.find_all('a', href=True)],
        "social_media_sharing_counts": {
            "facebook": None,
            "twitter": None,
            "linkedin": None
        },
        "user_generated_content_snippets": []
    }

    # Extract social media sharing counts
    try:
        facebook_count = int(soup.find('meta', attrs={'property': 'og:shares:facebook'})['content'])
        metadata["social_media_sharing_counts"]["facebook"] = facebook_count
    except (ValueError, AttributeError):
        pass

    try:
        twitter_count = int(soup.find('meta', attrs={'property': 'twitter:share-count'})['content'])
        metadata["social_media_sharing_counts"]["twitter"] = twitter_count
    except (ValueError, AttributeError):
        pass

    try:
        linkedin_count = int(soup.find('meta', attrs={'name': 'linkedin:shares'})['content'])
        metadata["social_media_sharing_counts"]["linkedin"] = linkedin_count
    except (ValueError, AttributeError):
        pass

    # Extract user-generated content snippets
    for tag in ['p', 'h1', 'h2', 'h3']:
        for snippet in soup.find_all(tag):
            metadata["user_generated_content_snippets"].append(snippet.text.strip())

    return metadata

def process_urls(urls, concurrency=50):
    with ThreadPoolExecutor(max_workers=concurrency) as executor:
        futures = {executor.submit(extract_metadata, url): url for url in urls}

        results = []
        for future in as_completed(futures):
            url = futures[future]
            try:
                metadata = future.result()
                results.append((url, metadata))
            except Exception as e:
                print(f"Error occurred while processing {url}: {e}")

    return dict(results)

def main():
    urls = ["http://example.com/page1", "http://example.com/page2", ...]
    results = process_urls(urls)
    for url, metadata in results.items():
        print(f"{url}:\n{metadata}\n")

if __name__ == "__main__":
    main()
```']

