function renderScripts(scripts) {
  const footer = document.createElement('footer');
  const promises = [];

  scripts.forEach((script) => {
    if (!script.key || !script.value || !script.environment) {
      console.error('Invalid script object:', script);
      return;
    }

    if (script.timeout) {
      if (isNaN(Number(script.timeout)) || Number(script.timeout) <= 0) {
        console.error('Invalid timeout value:', script.timeout);
        return;
      }
    }

    if (script.environment !== 'local' && script.environment !== 'staging' && script.environment !== 'production') {
      console.info('Ignoring script from unsupported environment:', script);
      return;
    }

    const scriptTag = document.createElement('script');
    scriptTag.src = `data:text/javascript;charset=utf-8,${encodeURIComponent(script.value)}`;
    scriptTag.async = true;

    if (script.timeout) {
      setTimeout(() => {
        document.body.appendChild(scriptTag);
      }, Number(script.timeout));
    } else {
      document.body.appendChild(scriptTag);
    }

    promises.push(new Promise((resolve, reject) => {
      try {
        // execute the script
        eval(`(${script.value})`);
        resolve();
      } catch (error) {
        console.error('Error executing script:', error);
        reject(error);
      }
    }));
  });

  Promise.all(promises).then(() => {
    footer.appendChild(scriptTag);
    document.body.appendChild(footer);
  }).catch((error) => {
    console.error('Error rendering scripts:', error);
    // handle the error
  });
}

