function mergeBuffers(bufferList, maxSize) {
  const bufferPool = new Uint8Array(maxSize);
  let writtenBytes = 0;
  let overflowed = false;

  for (const buffer of bufferList) {
    if (!buffer || buffer.length === 0) continue; // Handle empty buffers

    const bufferChunkSize = Math.min(buffer.length, maxSize - writtenBytes);

    if (writtenBytes + bufferChunkSize > maxSize) {
      // Buffer exceeds maximum size, split into smaller chunks
      const chunkSize = Math.floor((maxSize - writtenBytes) / buffer.length);
      let offset = 0;
      while (offset < buffer.length) {
        const chunk = new Uint8Array(Math.min(chunkSize, buffer.length - offset));
        bufferPool.set(buffer.subarray(offset, offset + chunk.length), writtenBytes);
        writtenBytes += chunk.length;
        offset += chunk.length;

        if (writtenBytes >= maxSize) {
          overflowed = true;
          break;
        }
      }

      if (!overflowed && writtenBytes < maxSize) {
        // Merge remaining buffer chunks
        const remainingChunkSize = maxSize - writtenBytes;
        let remainingOffset = 0;
        while (remainingOffset < buffer.length) {
          const chunk = new Uint8Array(Math.min(remainingChunkSize, buffer.length - remainingOffset));
          bufferPool.set(buffer.subarray(remainingOffset, remainingOffset + chunk.length), writtenBytes);
          writtenBytes += chunk.length;
          remainingOffset += chunk.length;
        }
      }

      if (overflowed) {
        throw new Error("Total size of buffers exceeds maximum size");
      }
    } else {
      // Buffer fits within current space, write it directly
      bufferPool.set(buffer, writtenBytes);
      writtenBytes += bufferChunkSize;
    }
  }

  return bufferPool.subarray(0, writtenBytes).buffer;
}

