function fetchAndAggregateData(apiEndpoints, queryParameters, callbackFunction, errorCallback, config) {
  const cache = {};
  const promises = [];
  let retries = 0;
  let maxRetries = 3;

  function processResponse(response) {
    if (response && response.data) {
      return response.data;
    }
    throw new Error('Invalid or empty response');
  }

  async function fetchAndMergeData(endpoint, queryParam) {
    const cachedResult = cache[JSON.stringify({ endpoint, queryParam })];
    if (cachedResult) {
      return cachedResult;
    }
    try {
      let page = 1;
      let data = [];
      let isValidResponse = false;

      while (!isValidResponse) {
        const response = await fetch(`${endpoint}?page=${page}&${queryParam}`);
        const responseData = await response.json();
        if (responseData.length > 0) {
          data = [...data, ...responseData];
          page++;
          isValidResponse = true;
        } else {
          break;
        }
      }

      cache[JSON.stringify({ endpoint, queryParam })] = data;
      return data;
    } catch (error) {
      if (retries < maxRetries) {
        retries++;
        await new Promise((resolve) => setTimeout(resolve, Math.pow(2, retries) * 1000));
        return await fetchAndMergeData(endpoint, queryParam);
      }
      throw error;
    }
  }

  async function aggregateData() {
    const aggregatedData = [];
    for (const endpoint of apiEndpoints) {
      promises.push(fetchAndMergeData(endpoint, queryParameters));
    }
    let results = await Promise.all(promises);
    for (let i = 0; i < results.length; i++) {
      aggregatedData.push(...results[i]);
    }
    return aggregatedData;
  }

  async function processAndTransformData(data) {
    const filteredData = data.filter(config.filterFunction);
    const transformedData = await Promise.all(filteredData.map(async (item) => config.transformFunction(item)));
    return transformedData;
  }

  try {
    const results = await aggregateData();
    const processedData = await processAndTransformData(results);
    callbackFunction(processedData);
  } catch (error) {
    errorCallback(error);
  }
}
