async function loadFiles(files, retries = 3, timeout = 1000) {
  const log = [];
  let lastError;

  for (const file of files) {
    try {
      await executeFile(file);
    } catch (err) {
      if (retries > 0) {
        setTimeout(() => {
          try {
            await executeFile(file);
          } catch (err) {
            log.push({ timestamp: Date.now(), error: err.stack });
            throw err;
          }
        }, timeout);
        retries--;
        lastError = err;
      } else {
        log.push({ timestamp: Date.now(), error: lastError.stack });
        console.error(`File ${file} failed to load after 3 attempts.`);
      }
    }

    log.push({ timestamp: Date.now(), success: true });
  }

  function executeFile(file) {
    return new Promise((resolve, reject) => {
      fs.readFile(file, 'utf8', (err, content) => {
        if (err) {
          reject(new Error(`Failed to read file ${file}: ${err.message}`));
        } else {
          try {
            eval(content);
            resolve();
          } catch (err) {
            reject(err);
          }
        }
      });
    });
  }

  return log;
}

