import java.time.*;
import java.util.*;

public class TransactionProcessor {

    public static Map<LocalDateTime, Set<String>> processTransactions(Iterator<Transaction> transactionStream) {
        // Initialize data structures for efficient processing
        Map<LocalDateTime, Set<String>> userIdsByTimestamp = new TreeMap<>();
        Map<String, Integer> userTransactionCount = new HashMap<>();

        while (transactionStream.hasNext()) {
            Transaction transaction = transactionStream.next();
            LocalDateTime timestamp = transaction.getTimestamp();

            // Manage transactions based on timestamps using a custom data structure
            if (!userIdsByTimestamp.containsKey(timestamp)) {
                userIdsByTimestamp.put(timestamp, new HashSet<>());
            }

            String userId = transaction.getUserId();
            userTransactionCount.put(userId, userTransactionCount.getOrDefault(userId, 0) + 1);

            // Quick lookup and addition of user IDs for the current timestamp
            userIdsByTimestamp.get(timestamp).add(userId);
        }

        int uniqueUsersWithMultipleTransactions = 0;
        for (Map.Entry<LocalDateTime, Set<String>> entry : userIdsByTimestamp.entrySet()) {
            for (String userId : entry.getValue()) {
                if (userTransactionCount.getOrDefault(userId, 0) > 1) {
                    uniqueUsersWithMultipleTransactions++;
                    break;
                }
            }
        }

        // Estimate memory usage in kilobytes
        int memoryUsageKB = estimateMemoryUsage(userIdsByTimestamp, userTransactionCount);

        return Map.of("uniqueUsersWithMultipleTransactions", uniqueUsersWithMultipleTransactions, "memoryUsageKB", memoryUsageKB);
    }

    private static int estimateMemoryUsage(Map<LocalDateTime, Set<String>> userIdsByTimestamp, Map<String, Integer> userTransactionCount) {
        // Approximate calculation based on data structure sizes
        int memoryUsage = 0;
        for (Map.Entry<LocalDateTime, Set<String>> entry : userIdsByTimestamp.entrySet()) {
            memoryUsage += entry.getKey().hashCode() + entry.getValue().size() * String.valueOf(entry.getValue()).length();
        }
        for (String key : userTransactionCount.keySet()) {
            memoryUsage += key.hashCode() + String.valueOf(userTransactionCount.get(key)).length();
        }
        return memoryUsage / 1024;
    }

    public static class Transaction {
        private String userId;
        private LocalDateTime timestamp;

        // Getters and setters
        public String getUserId() { return userId; }
        public void setUserId(String userId) { this.userId = userId; }
        public LocalDateTime getTimestamp() { return timestamp; }
        public void setTimestamp(LocalDateTime timestamp) { this.timestamp = timestamp; }
    }
}
