    public void startInstance(String instanceId) {
        // Start the instance
        Instance instance = new Instance(instanceId);
        instances.put(instanceId, instance);

        if (instances.size() < minInstances) {
            loadBalancer.startRouting();
        }
    }

    public void stopInstance(String instanceId) {
        // Stop the instance
        instances.remove(instanceId);

        if (instances.size() < minInstances) {
            startNewInstance();
        } else {
            loadBalancer.stopRouting();
        }
    }

    public void sendHeartbeat(String instanceId) {
        Instance instance = instances.get(instanceId);
        instance.sendHeartbeat();
    }

    private void startNewInstance() {
        // Start a new instance
        String instanceId = generateInstanceId();
        startInstance(instanceId);
    }

    private String generateInstanceId() {
        // Generate a unique ID for the instance
        return UUID.randomUUID().toString();
    }
}
