import requests
import json
from datetime import datetime, timedelta
from cachetools import TTLCache

class TrafficAndWeatherAPI:
    def __init__(self):
        self.api_keys = {
            'traffic_api': 'YOUR_TRAFFIC_API_KEY',
            'weather_api': 'YOUR_WEATHER_API_KEY'
        }
        self.cache = TTLCache(maxsize=100, ttl=300)  # cache for 5 minutes

    def get_traffic_data(self, city_name, start_time, end_time):
        traffic_api_key = self.api_keys['traffic_api']
        try:
            response = requests.get(f'https://traffic-api.com/{city_name}?start={start_time}&end={end_time}',
                                    headers={'Authorization': f'Bearer {traffic_api_key}'})
            if response.status_code == 200:
                return response.json()
            else:
                return None
        except Exception as e:
            print(f"Error fetching traffic data: {str(e)}")
            return None

    def get_weather_data(self, city_name):
        weather_api_key = self.api_keys['weather_api']
        try:
            response = requests.get(f'https://weather-api.com/{city_name}',
                                    headers={'Authorization': f'Bearer {weather_api_key}'})
            if response.status_code == 200:
                return response.json()
            else:
                return None
        except Exception as e:
            print(f"Error fetching weather data: {str(e)}")
            return None

    def aggregate_data(self, city_name, start_time, end_time):
        traffic_data = self.get_traffic_data(city_name, start_time, end_time)
        weather_data = self.get_weather_data(city_name)

        if not traffic_data or not weather_data:
            return {'error': 'Failed to retrieve data'}

        traffic_congestion_levels = []
        average_speeds = []
        weather_conditions = []

        for item in traffic_data['items']:
            traffic_congestion_levels.append(item['congestion_level'])
            average_speeds.append(item['average_speed'])

        for item in weather_data['items']:
            weather_conditions.append({
                'temperature': item['temperature'],
                'humidity': item['humidity'],
                'description': item['description']
            })

        return {
            'traffic_congestion_levels': traffic_congestion_levels,
            'average_speeds': average_speeds,
            'weather_conditions': weather_conditions
        }

    def fetch_and_aggregate_data(self, city_name, start_time, end_time):
        cached_response = self.cache.get(f"{city_name}_{start_time}_{end_time}")
        if cached_response:
            return cached_response

        response = self.aggregate_data(city_name, start_time, end_time)
        self.cache.set(f"{city_name}_{start_time}_{end_time}", response, timeout=300)  # cache for 5 minutes
        return response

    def main(self):
        city_name = 'New York'
        start_time = datetime.now().strftime('%Y-%m-%d')
        end_time = (datetime.now() + timedelta(days=1)).strftime('%Y-%m-%d')

        api_response = self.fetch_and_aggregate_data(city_name, start_time, end_time)

        if 'error' in api_response:
            print(f"Error: {api_response['error']}")
        else:
            print(json.dumps(api_response, indent=4))

if __name__ == "__main__":
    traffic_weather_api = TrafficAndWeatherAPI()
    traffic_weather_api.main()']

