<?php

function generateAndHash($length, $charset, $salt, $directoryPath) {
    if (!$length || !$charset || !$salt || !$directoryPath) {
        return ['error' => 'Invalid input'];
    }

    $randomString = substr(str_shuffle(str_repeat($charset, ceil($length / strlen($charset)))), 1, $length);
    $password = hash('sha256', $randomString . $salt);

    if (!file_exists($directoryPath)) {
        mkdir($directoryPath, 0777, true);
    }

    file_put_contents("$directoryPath/password.txt", $password);

    return [
        'randomString' => $randomString,
        'hashedPassword' => $password,
        'filePath' => "$directoryPath/password.txt"
    ];
}

function readFileSync($directoryPath) {
    if (!strpos($directoryPath, 'allowedPrefix/') === 0) {
        return ['error' => 'Invalid file path'];
    }

    if (!file_exists($directoryPath)) {
        return ['error' => 'File not found'];
    }

    if (!is_readable($directoryPath)) {
        return ['error' => 'File unreadable'];
    }

    try {
        $contents = file_get_contents($directoryPath);
        if (!$contents) {
            return ['error' => 'File contents empty'];
        }
        return $contents;
    } catch (Exception $e) {
        return ['error' => $e->getMessage()];
    }
}

