function fetchAndCombinePEMCertificate(oauthRequest) {
    const { privateKeyLocation, certificateLocation } = oauthRequest;
    const mutex = new Mutex();
    let.pemCertificateContent = [];
    let.pemPrivateKeyContent = [];

    async function fetchAndConcatenateFiles() {
        try {
            const privateKeyBuffer = await httpGetWithRetry(privateKeyLocation);
            pemPrivateKeyContent = privateKeyBuffer.toString();

            const certificateBuffer = await httpGetWithRetry(certificateLocation);
            pemCertificateContent = certificateBuffer.toString();
        } catch (error) {
            return { data: null, error: 'Failed to fetch or concatenate files' };
        }

        try {
            const pemFileBuffer = Buffer.concat([Buffer.from(pemPrivateKeyContent), Buffer.from('\n'), Buffer.from(pemCertificateContent)]);
            const pemFilePath = join(__dirname, `combined.pem`);

            await promisify(writeFileSync)(pemFilePath, pemFileBuffer);

            return { data: pemFilePath };
        } catch (error) {
            return { data: null, error: 'Failed to write combined PEM file' };
        }
    }

    async function processStream(stream) {
        let buffer = Buffer.alloc(0);
        stream.on('data', (chunk) => {
            buffer = Buffer.concat([buffer, chunk]);
        });
        stream.on('end', () => {
            const arrayBuffer = buffer.toJSON();
            if (arrayBuffer.length > PEM_FILE_MAX_SIZE) {
                // Handle oversized data
            }
            stream.pause();
        });
        return arrayBuffer;
    }

    async function main() {
        try {
            const { data, error } = await mutex.runExclusive(() => fetchAndConcatenateFiles());
            return { data, error };
        } catch (error) {
            return { data: null, error: 'Failed to concatenate files' };
        }
    }

    return main();
}

module.exports = fetchAndCombinePEMCertificate;
