class OctreeNode {
public:
    void* data;
    int depth;
    std::unique_ptr<OctreeNode> children[8];
};

std::unique_ptr<OctreeNode> initializeOctreeWithDynamicResources(int featureSize, int numLeafNodes, int maxDepth) {
    // Initialize the octree root node
    auto root = std::make_unique<OctreeNode>();
    root->depth = 0;

    // Allocate memory for each level of the octree
    int nodesPerLevel = 1;
    while (root->depth < maxDepth - 1) {
        nodesPerLevel *= 8;
        for (int i = 0; i < nodesPerLevel; i++) {
            auto node = std::make_unique<OctreeNode>();
            node->data = nullptr;
            node->depth = root->depth + 1;
            root->children[i] = std::move(node);
        }
        root = root->children[0];
    }

    // Initialize the leaf nodes
    for (int i = 0; i < numLeafNodes; i++) {
        auto leafNode = std::make_unique<OctreeNode>();
        leafNode->data = nullptr;
        leafNode->depth = maxDepth - 1;
        root->children[i] = std::move(leafNode);
    }

    return root;
}

int main() {
    // Example usage
