package com.session.management.module;

import java.util.*;
import java.util.concurrent.*;

public class SessionManager {
    private static final int SESSION_EXPIRY = 30; // in minutes
    private Map<String, Session> sessionMap;
    private ConcurrentHashMap<String, Callable<Session>> sessionQueue;
    private ExecutorService executorService;
    private DataStore dataStore;

    public SessionManager(DataStore dataStore) {
        this.sessionMap = new HashMap<>();
        this.sessionQueue = new ConcurrentHashMap<>();
        this.executorService = Executors.newCachedThreadPool();
        this.dataStore = dataStore;
    }

    public void createSession(String userId, String metadata) throws Exception {
        Callable<Session> sessionCallable = () -> new Session(userId, SESSION_EXPIRY, dataStore.fetchMetadata(metadata));
        FutureTask<Session> futureTask = new FutureTask<>(sessionCallable);
        sessionQueue.put(userId, futureTask);
        executorService.submit(futureTask);

        try {
            Session session = futureTask.get();
            sessionMap.put(userId, session);
        } catch (ExecutionException e) {
            // Handle session creation error
        }
