public:
    void selectAttack(int& selectedAttack) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (cooldowns_.empty()) {
            for (int i = 0; i < 5; ++i) {
                cooldowns_[i] = 10 - i;
            }
        }

        auto it = std::min_element(cooldowns_.begin(), cooldowns_.end(),
                                    [](const auto& a, const auto& b) {
                                        return a > b;
                                    });

        selectedAttack = std::distance(cooldowns_.begin(), it);

        --(*it);
        if ((*it) == 0) {
            *it = 10 - (selectedAttack + 1);
        }

        for (int i = 0; i < 20; ++i) {
            logBuffer_[i] = "Attack " + std::to_string(selectedAttack) + " used at " +
                std::to_string(std::time(nullptr));
            if (++logIndex_ >= 20) logIndex_ = 0;
        }

        totalUses_[selectedAttack]++;
    }

private:
    mutable std::mutex mutex_;
    mutable std::condition_variable cv_;
    int cooldowns_[5];
    int logBuffer_[20];
