using System;
using System.Threading;

public class DynamicRangeGenerator
{
    private float minValue;
    private float maxValue;
    private readonly Random random = new Random();
    private readonly object rangeLock = new object();
    private readonly log4net.ILog logger = log4net.LogManager.GetLogger(typeof(DynamicRangeGenerator));

    public DynamicRangeGenerator(float minValue, float maxValue)
    {
        if (minValue > maxValue)
        {
            throw new ArgumentException("Min value must be less than or equal to max value.");
        }

        AdjustRange(minValue, maxValue);
    }

    public float GenerateRandomFloat()
    {
        return random.NextDouble() * (maxValue - minValue) + minValue;
    }

    public int GenerateRandomInt()
    {
        return (int)((random.NextDouble() * (maxValue - minValue)) + minValue);
    }

    public float GenerateExclusiveRandomFloat()
    {
        return random.NextDouble() * (maxValue - minValue - 1) + minValue;
    }

    public int GenerateExclusiveRandomInt()
    {
        return (int)((random.NextDouble() * (maxValue - minValue - 1)) + minValue);
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}]";
    }

    public void AdjustRange(float adjustment)
    {
        lock (rangeLock)
        {
            if (adjustment <= 0f)
            {
                throw new ArgumentException("Adjustment must be positive.");
            }
            else
            {
                minValue += adjustment;
                maxValue += adjustment;

                // Ensure range remains valid
                while (minValue > maxValue)
                {
                    minValue -= (maxValue - minValue);
                }
            }

            logger.Info($"Adjusted range to [{minValue}, {maxValue}]");
        }
    }

    public void ResetRange()
    {
        lock (rangeLock)
        {
            minValue = 0f;
            maxValue = 100f;

            logger.Info("Reset range to [0, 100]");
        }
    }

    public void SetRandomSeed(long seed)
    {
        random.Seed(seed);
    }
}
