#include <string.h>

// Define a structure for projects
typedef struct {
    char* name;
    int priority;
    double estimatedCompletionTime;
    struct Project* subProjects;
} Project;

// Function to create and initialize a new project
Project* createProject(char* name, int priority, double estimatedCompletionTime) {
    Project* newProject = (Project*)malloc(sizeof(Project));
    if (!newProject) return NULL; // Handle memory allocation failure

    newProject->name = (char*)malloc(strlen(name) + 1);
    strcpy(newProject->name, name);

    newProject->priority = priority;
    newProject->estimatedCompletionTime = estimatedCompletionTime;

    newProject->subProjects = NULL;

    return newProject;
}

// Function to add a project as a sub-project
void addSubProject(Project* parent, Project* subProject) {
    if (!parent || !subProject) return; // Handle null pointer

    if (!parent->subProjects) {
        parent->subProjects = (Project*)malloc(sizeof(Project));
        if (!parent->subProjects) return; // Handle memory allocation failure
        *parent->subProjects = *subProject;
        subProject = NULL;
    }

    Project* current = parent->subProjects;
    while (current && current->name) {
        if (strcmp(current->name, subProject->name) == 0) {
            return; // Sub-project already exists
        }
        current = current->subProjects;
    }

    current->subProjects = subProject;
}

// Function to print project details
void printProject(Project* project) {
    if (!project) return; // Handle null pointer

    printf("Name: %s\n", project->name);
    printf("Priority: %d\n", project->priority);
    printf("Estimated Completion Time (days): %.2f\n", project->estimatedCompletionTime);

    Project* subProject = project->subProjects;
    while (subProject) {
        printProject(subProject);
        subProject = subProject->subProjects;
    }
}

// Function to free memory allocated for projects
void destroyProject(Project* project) {
    if (!project) return; // Handle null pointer

    Project* subProject = project->subProjects;
    while (subProject) {
        Project* nextSubProject = subProject->subProjects;
        free(subProject);
        subProject = nextSubProject;
    }

    free(project->name);
    free(project);
}

// Example usage: Initialize the list with predefined projects
int main() {
    // Create and initialize projects
    Project* project1 = createProject("Project A", 1, 5.0);
    Project* project2 = createProject("Project B", 2, 3.5);
    Project* project3 = createProject("Project C", 3, 7.0);

    // Add sub-projects
    addSubProject(project1, project2);
    addSubProject(project1, project3);
    addSubProject(project2, createProject("Sub-Project B1", 4, 2.5));
    addSubProject(project2, createProject("Sub-Project B2", 5, 6.0));

    // Print project details
    printProject(project1);

    // Destroy the list and free memory
    destroyProject(project1);

    return 0;
}
