#include <iostream>
#include <map>

namespace po = boost::program_options;

class SemaphoreManager {
public:
    SemaphoreManager() : semaphores_(), mutex_(std::make_unique<std::mutex>()) {}

    int run(int argc, char* argv[]) {
        po::options_description desc("Options");
        desc.add_options()
            ("help", "display this help message")
            ("create", po::value<std::string>()->required(), "create a named semaphore with the given initial value")
            ("delete", po::value<std::string>()->required(), "delete the named semaphore")
            ("increment", po::value<std::string>()->required(), "increment the named semaphore by 1")
            ("decrement", po::value<std::string>()->required(), "decrement the named semaphore by 1");

        po::variables_map vm;
        po::store(po::command_line_parser(argc, argv).options(desc).style(pof::default_style | pof::output_posixly_correct).run(), vm);
        po::notify(vm);

        if (vm.count("help")) {
            std::cout << desc << "\n";
            return 1;
        }

        for (auto& arg : { "create", "delete", "increment", "decrement" }) {
            if (!vm.count(arg.c_str())) continue;

            auto op = vm[arg].as<std::string>();

            if (op == "create") {
                createSemaphore(vm["create"].as<std::string>());
            } else if (op == "delete") {
                deleteSemaphore(vm["delete"].as<std::string>());
            } else if (op == "increment") {
                incrementSemaphore(vm["increment"].as<std::string>());
            } else if (op == "decrement") {
                decrementSemaphore(vm["decrement"].as<std::string>());
            }
        }

        return 0;
    }

private:
    void createSemaphore(const std::string& name, int initialValue = 1) {
        // Create a named semaphore with the given initial value
        std::unique_lock<std::mutex> lock(*mutex_);
        semaphores_[name] = std::semaphore(name, initialValue);
    }

    void deleteSemaphore(const std::string& name) {
        // Delete the named semaphore
        std::unique_lock<std::mutex> lock(*mutex_);
        if (semaphores_.erase(name) != 1) {
            std::cerr << "Error: Semaphore not found.\n";
            return;
        }
    }

    void incrementSemaphore(const std::string& name) {
        // Increment the named semaphore by 1
        std::unique_lock<std::mutex> lock(*mutex_);
        if (semaphores_.count(name)) {
            semaphores_[name].post();
        } else {
            std::cerr << "Error: Semaphore not found.\n";
        }
    }

    void decrementSemaphore(const std::string& name) {
        // Decrement the named semaphore by 1
        std::unique_lock<std::mutex> lock(*mutex_);
        if (semaphores_.count(name)) {
            semaphores_[name].wait();
        } else {
            std::cerr << "Error: Semaphore not found.\n";
        }
    }

private:
    std::map<std::string, std::semaphore> semaphores_;
    std::unique_ptr<std::mutex> mutex_;
};

int main(int argc, char* argv[]) {
    SemaphoreManager manager;
    return manager.run(argc, argv);
}
