#include <string.h>

// Define a structure for the entry data type
typedef struct {
    char* key;
    int value;
} entry;

// Define a hash table node structure
typedef struct {
    char* key;
    entry* data;
    struct node* next;
} node;

// Define the hash table structure
typedef struct {
    int size;
    node** buckets;
} hashtable;

// Function to create and initialize a new hash table with a given size
hashtable* create_hashtable(int size) {
    hashtable* h = (hashtable*)malloc(sizeof(hashtable));
    h->size = size;
    h->buckets = (node**)malloc(size * sizeof(node*));
    for (int i = 0; i < size; i++) {
        h->buckets[i] = NULL;
    }
    return h;
}

// Function to free the memory allocated for a hash table
void free_hashtable(hashtable* h) {
    for (int i = 0; i < h->size; i++) {
        node* current = h->buckets[i];
        while (current != NULL) {
            node* next = current->next;
            free(current);
            current = next;
        }
    }
    free(h->buckets);
    free(h);
}

// Function to add a new entry to the hash table
void add_entry(hashtable* h, char* key, int value) {
    int index = hash(key, h->size);
    node* current = h->buckets[index];
    while (current != NULL) {
        if (strcmp(current->key, key) == 0) {
            // Entry already exists, update its value
            free(current->data);
            current->data = malloc(sizeof(entry));
            current->data->value = value;
            return;
        }
        current = current->next;
    }
    // Create a new node for the entry
    node* new_node = (node*)malloc(sizeof(node));
    new_node->key = key;
    new_node->data = malloc(sizeof(entry));
    new_node->data->value = value;
    new_node->next = NULL;
    h->buckets[index] = new_node;
}

// Function to retrieve the integer value for a given string key
int get_value(hashtable* h, char* key) {
    int index = hash(key, h->size);
    node* current = h->buckets[index];
    while (current != NULL) {
        if (strcmp(current->key, key) == 0) {
            return current->data->value;
        }
        current = current->next;
    }
    // Entry not found
    return -1;
}

// Hash function to calculate the index for a given string
int hash(char* str, int size) {
    unsigned long hash_value = 0;
    while (*str != '\0') {
        hash_value += (unsigned char)*str;
        str++;
    }
    return (hash_value % size);
}
