const AsyncReduce = (arr, initialValue, callback) => {
  let currentlyProcessing = false;
  let attempts = 0;
  let maxAttempts = 3;
  const context = {};
  const retryFlag = false;

  return new Promise((resolve, reject) => {
    (function next() {
      if (!currentlyProcessing && arr.length > 0) {
        currentityProcessing = true;
        const [num, ...rest] = arr;
        callback(num, initialValue, context, retryFlag)
          .then(result => {
            initialValue = result;
            arr = rest;
            attempts = 0;
            maxAttempts = 3; // Reset the max attempts
            return next();
          })
          .catch(err => {
            if (attempts < maxAttempts) {
              // Exponential backoff for up to three attempts
              setTimeout(() => {
                next();
              }, Math.pow(2, attempts++) * 100);
            } else {
              reject(err);
            }
          });
      } else if (!arr.length) {
        resolve(initialValue);
      } else {
        currentityProcessing = false;
      }
    })();
  });

  AsyncReduce.logExecutionStats = (stats) => {
    console.log(`Retries: ${stats.retries}`);
    console.log(`Error Count: ${stats.errorCount}`);
  };
};
