    for (int i = 0; i < size_limit && input_str[i]; i++) {
        temp = realloc(temp, sizeof(char) * (i + 2));
        if (!temp) {
            // Handle memory allocation failure and provide feedback on resource exhaustion
            printf("Memory allocation failed. Resource exhausted.\n");
            return NULL;
        }
        temp[i] = input_str[i];
    }

    // Append a slash to the end of the string if it does not exceed the size limit or the truncation flag is set
    if (strlen(temp) <= size_limit || !truncation_flag) {
        temp[strlen(temp)] = '/';
    } else {
        // Truncate the string to fit within the limit and append a special marker character at the end
        temp[size_limit - 1] = '\0';
        strcat(temp, "...");
    }

    // Release all allocated memory before returning
    free(temp);

    return result ? NULL : strdup(temp);
}

