        json_object *json_entry;
        int err = 0;

        // Parse JSON entry from log line
        json_entry = json_tokener_parse(line);
        if (!json_entry) {
            printf("Error parsing JSON: %s\n", line);
            continue;
        }

        // Process session stats
        SessionStats *new_stats = session_stats_new();
        int duration_sum = 0, count = 0;
        json_object_object_foreach(json_entry, key, val) {
            if (json_is_int(val)) {
                int value = json_object_get_int(val);
                duration_sum += value;
                count++;
            }
