        new_stats->duration_sum = duration_sum / count;

        // Update JSON cache
        pthread_mutex_lock(&cache_lock);
        if (json_object_object_add(json_cache, session_stats_new_key(stats), json_object_new())) {
            printf("Error adding to JSON cache: %s\n", line);
            err++;
        }
        stats->count++;
        pthread_mutex_unlock(&cache_lock);

        // Free session stats
        session_stats_free(new_stats);
    }

    // Close file and free JSON cache
    fclose(file);
    pthread_mutex_destroy(&cache_lock);
    json_object_put(json_cache);
    return 0;
}
