    DynamicImageProcessor(double min, double max) {
        if (min > max) {
            std::cerr << "Error: minValue must be less than or equal to maxValue." << std::endl;
            return;
        }
        if (std::abs(max - min) > 1000000) {
            std::cerr << "Error: The range is too large. Please provide a more practical range." << std::endl;
            return;
        }
        minValue = min;
        maxValue = max;
    }

    // Generate random floating-point numbers
    double generateRandomFloat() {
        std::random_device rd;  // Obtain a non-deterministic seed
        std::mt19937 eng(rd());
        std::normal_distribution<> distr(minValue, (maxValue - minValue) / 3.0);
        return distr(eng);
    }

    // Generate random integer numbers within the specified range
    int generateRandomInt(bool excludeMax = false) {
        if (!excludeMax)
            return rand() % (maxValue - minValue + 1) + minValue;
        else
            return rand() % (maxValue - minValue) + minValue;
    }

    // Set the random seed for reproducible results
    void setRandomSeed(long seed) {
        std::random_device rd(seed);
