#define MAX_RECORDS 10000000
#define MIN_KEY_VALUE 0
#define MAX_KEY_VALUE 9999999
#define RECORD_SIZE sizeof(record_t)

typedef struct {
    int key;
    long offset;
    int value;
} record_t;

record_t* records = NULL;
int num_records = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* log_buffer = NULL;
size_t log_size = 0;
int log_level = 1; // 0: error, 1: warning, 2: info

void log_message(int level, const char* message) {
    pthread_mutex_lock(&mutex);
    if (log_level >= level) {
        printf("%s\n", message);
    }
    pthread_mutex_unlock(&mutex);
}

int insert_record(int key, long offset, int value) {
    record_t new_record;
    new_record.key = key;
    new_record.offset = offset;
    new_record.value = value;

    if (num_records == MAX_RECORDS) {
        log_message(1, "Record collection is full.");
        return -1; // failed to insert
    }

    record_t* temp_records = realloc(records, (num_records + 1) * RECORD_SIZE);
    if (!temp_records) {
        log_message(0, "Memory allocation failure for new records.");
        return -1; // failed to allocate memory
    }
    records = temp_records;

    pthread_mutex_lock(&mutex);
    records[num_records] = new_record;
    num_records++;
    pthread_mutex_unlock(&mutex);

    return 0; // successful insertion
}

void delete_record(int key) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_records; i++) {
        if (records[i].key == key) {
            memmove(&records[i], &records[i + 1], (num_records - i - 1) * RECORD_SIZE);
            num_records--;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

int get_record(int key, record_t* target) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_records; i++) {
        if (records[i].key == key) {
            *target = records[i];
            return 1; // found the record
        }
    }
    pthread_mutex_unlock(&mutex);
    return 0; // not found
}

void resize_records() {
    record_t* new_records = realloc(records, (num_records + 10) * RECORD_SIZE);
    if (!new_records) {
        log_message(0, "Memory allocation failure for resized records.");
        return;
    }
    records = new_records;
}

void print_stats() {
    printf("Total records: %d\n", num_records);
    printf("Average offset value: %.2f\n", (double)num_records ? (long)sum_records / num_records : 0.0);
    printf("Maximum key value: %d\n", get_max_key());
    printf("Minimum key value: %d\n", get_min_key());
}

int sum_records() {
    int total = 0;
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_records; i++) {
        total += records[i].value;
    }
    pthread_mutex_unlock(&mutex);
    return total;
}

int get_max_key() {
    int max = MIN_KEY_VALUE;
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_records; i++) {
        if (records[i].key > max) {
            max = records[i].key;
        }
    }
    pthread_mutex_unlock(&mutex);
    return max;
}

int get_min_key() {
    int min = MAX_KEY_VALUE;
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_records; i++) {
        if (records[i].key < min) {
            min = records[i].key;
        }
    }
    pthread_mutex_unlock(&mutex);
    return min;
}

void* worker_thread(void* arg) {
