#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <time.h>

#define MAX_FILENAME_LENGTH 255
#define TRUNCATION_LENGTH 250
#define FILE_TYPES "txt,csv,log,html"
#define CACHE_SIZE 1000

typedef struct {
    char* file_type;
} FileTypes;

void generate_filename(const char* input_filename, const char** output_filenames) {
    // Check for filename length and truncate if necessary
    int input_length = strlen(input_filename);
    int truncated_length = (input_length > MAX_FILENAME_LENGTH) ? TRUNCATION_LENGTH : input_length;

    // Generate base name
    char* base_name = malloc(truncated_length + 1);
    strncpy(base_name, input_filename, truncated_length);
    base_name[truncated_length] = '\0';

    // Append random file type
    srand(time(NULL));
    int rand_index = rand() % strlen(FILE_TYPES) / sizeof(char*);
    FileTypes* file_types = malloc(sizeof(FileTypes));
    char** types = (char**)malloc(strlen(FILE_TYPES) + 1);
    const char* token = strtok((char*)FILE_TYPES, ",");
    for (int i = 0; i < strlen(FILE_TYPES); i++) {
        types[i] = token;
        token = strtok(NULL, ",");
        if (!token) break;
    }
    file_types->file_type = types[rand_index];
    free(types);

    // Construct output filenames
    char* filename = malloc(truncated_length + sizeof(char*) + 1);
    sprintf(filename, "%s.%s", base_name, file_types->file_type);

    // Cache the generated filename for future reuse
    int cache_hit = 0;
    if (output_filenames) {
        for (int i = 0; i < CACHE_SIZE && !cache_hit; i++) {
            if (!strcmp(filename, output_filenames[i])) {
                cache_hit = 1;
                break;
            }
        }
        if (!cache_hit) {
            // Update the cache
            for (int i = 0; i < CACHE_SIZE - 1; i++) {
                strcpy(output_filenames[i], output_filenames[i + 1]);
            }
            strcpy(output_filenames[CACHE_SIZE - 1], filename);
        } else {
            free(filename);
        }
    }

    // Clean up
    free(base_name);
    free(file_types);
}

int main() {
    const char* input_filename = "example.txt";
    const char** output_filenames = (const char**)malloc(CACHE_SIZE * sizeof(char*));
    generate_filename(input_filename, output_filenames);

    for (int i = 0; i < CACHE_SIZE; i++) {
        printf("%s\n", output_filenames[i]);
    }

    return 0;
}

