#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>
#include <semaphore.h>
#include <pthread.h>

int manageSemaphores(int numProcesses) {
    int i;
    pid_t child;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    sem_t *semaphores;

    // Initialize semaphore pool
    if ((semaphores = (sem_t *)calloc(numProcesses, sizeof(sem_t))) == NULL) {
        return 0; // Memory allocation failure
    }

    for (i = 0; i < numProcesses; i++) {
        if (sem_init(&semaphores[i], 1, 1) != 0) {
            return 0; // Semaphore initialization failure
        }
    }

    for (i = 0; i < numProcesses; i++) {
        child = fork();
        if (child < 0) {
            return 0; // Forking error
        } else if (child > 0) {
            continue;
        }

        // Child process: Create unique user ID and acquire semaphore
        pthread_mutex_lock(&mutex);
        pid_t pid = getpid();
        if (setuid(pid)) { // Set user ID to the current process ID
            return 0; // User ID set failure
        }
        sem_wait(&semaphores[i]);
        pthread_mutex_unlock(&mutex);

        // Child process: Simulate work by sleeping for a random time
        sleep(rand() % 5); 

        // Child process: Release semaphore and exit
        sem_post(&semaphores[i]);
        _exit(0);
    }

    // Parent process: Wait for child processes to complete
    for (i = 0; i < numProcesses; i++) {
        waitpid(-1, NULL, 0); // Wait for all child processes to finish
    }

    // Clean up semaphore pool and memory resources
    for (i = 0; i < numProcesses; i++) {
        sem_destroy(&semaphores[i]);
    }
    free(semaphores);

    return 1;
}
