#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define RECORD_MAX 1000
#define TABLE_SIZE 256

typedef struct record {
    int key;
    long offset;
    double value;
} Record;

typedef struct node {
    Record record;
    struct node* next;
} Node;

Record records[RECORD_MAX];
Node* hashTable[TABLE_SIZE] = {NULL};
int recordCount = 0;
long memoryUsage = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void addRecord(int key, long offset, double value) {
    pthread_mutex_lock(&lock);
    Record newRecord = {key, offset, value};
    int index = key % TABLE_SIZE;
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->record = newRecord;
    newNode->next = hashTable[index];
    hashTable[index] = newNode;
    recordCount++;
    pthread_mutex_unlock(&lock);
}

void updateRecord(int key, long offset, double value) {
    pthread_mutex_lock(&lock);
    int index = key % TABLE_SIZE;
    Node* current = hashTable[index];
    while (current != NULL) {
        if (current->record.key == key) {
            current->record.offset = offset;
            current->record.value = value;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&lock);
}

Record* getRecord(int key) {
    pthread_mutex_lock(&lock);
    int index = key % TABLE_SIZE;
    Node* current = hashTable[index];
    Record* found = NULL;
    while (current != NULL) {
        if (current->record.key == key) {
            found = &current->record;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&lock);
    return found;
}

void pruneRecords(double percentage) {
    pthread_mutex_lock(&lock);
    int totalBytes = memoryUsage / recordCount;
    int bytesToPrune = (int)(totalBytes * percentage);
    for (int i = 0; i < TABLE_SIZE; i++) {
        Node* current = hashTable[i];
        while (current != NULL) {
            if (recordCount > 1 && current->next != NULL) {
                recordCount--;
                memoryUsage -= totalBytes;
                free(current);
                current = current->next;
            } else {
                break;
            }
        }
    }
    pthread_mutex_unlock(&lock);
}

void* cleanup(void* ptr) {
    free(records);
    for (int i = 0; i < TABLE_SIZE; i++) {
        Node* current = hashTable[i];
        while (current != NULL) {
            Node* next = current->next;
            free(current);
            current = next;
        }
    }
    return NULL;
}

void logError(const char* message) {
    // implement logging interface here
}
