package com.containerapp;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class ContainerAppManager {
    private final ScheduledExecutorService executor = Executors.newScheduledThreadPool(1);
    private final List<Container> containers = new ArrayList<>();
    private final CloudProvider cloudProvider;

    public ContainerAppManager(CloudProvider cloudProvider) {
        this.cloudProvider = cloudProvider;
    }

    public void deploy(Container container, int replicas) {
        // Deploy the container to the cloud provider
        cloudProvider.deploy(container, replicas);

        // Schedule a rollback if deployment fails within 5 minutes
        executor.schedule(() -> {
            try {
                // Roll back the deployment if it failed
                if (!cloudProvider.checkDeploymentSuccess()) {
                    rollback(container);
                }
            } catch (Exception e) {
                // Handle exceptions
            }
        }, 30000, TimeUnit.MILLISECONDS); // 30 seconds = 5 minutes
    }

    public void scale(Container container, int replicas) {
        // Scale the container to the desired number of replicas
        cloudProvider.scale(container, replicas);
    }

    public void terminate(Container container) {
        // Terminate the container and its replicas
        cloudProvider.terminate(container);
    }

    private void rollback(Container container) {
        // Roll back the deployment by terminating any newly created resources
        cloudProvider.rollbackDeployment(container);
    }

    public static class Container {
        private final String name;
        private final String image;

        public Container(String name, String image) {
            this.name = name;
            this.image = image;
        }
    }

    public interface CloudProvider {
        void deploy(Container container, int replicas);

        boolean checkDeploymentSuccess();

        void rollbackDeployment(Container container);

        void scale(Container container, int replicas);

        void terminate(Container container);
    }
}
