public class Base64Decryptor
{
    public const int DefaultMessageSizeLimit = 1024 * 1024; // 1MB

    private readonly TripleDES _des;
    private readonly HMACSHA256 _hmac;
    private readonly int _messageSizeLimit;

    public Base64Decryptor(string key, string iv)
    {
        _des = TripleDES.Create(key, iv);
        _hmac = new HMACSHA256(Encoding.UTF8.GetBytes(key));
        _messageSizeLimit = DefaultMessageSizeLimit;
    }

    public async Task<string[]> ProcessAsync(string input)
    {
        var messages = input.Split('\n');
        var results = new List<string>();

        foreach (var message in messages)
        {
            if (string.IsNullOrEmpty(message))
                continue;

            try
            {
                var decrypted = DecryptBase64(message);
                var hmacSignature = GetHmacSignature(decrypted);

                // Validate HMAC signature
                if (!VerifyHmacSignature(decrypted, hmacSignature))
                    throw new Exception("Invalid HMAC signature");

                results.Add(decrypted);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error processing message: {ex.Message}");
            }
        }

        return results.ToArray();
    }

    private string DecryptBase64(string base64Message)
    {
        var iv = GetIV(base64Message);
        var key = GetKey(base64Message);

        if (!IsValidIV(iv) || !IsValidKey(key))
            throw new Exception("Invalid IV or key");

        var desMode = base64Message.Contains("cfb") ? CipherMode.CFB : CipherMode.CBC;

        using (var memoryStream = new MemoryStream())
        {
            using (var cryptoStream = _des.CreateDecryptingStream(memoryStream, iv, key, desMode))
            {
                var buffer = new byte[_messageSizeLimit];
                int bytesRead;
                while ((readBytes = cryptoStream.Read(buffer, 0, buffer.Length)) > 0)
                {
                    // Process data here
                }
            }
        }
    }

    private string GetIV(string base64Message) => base64Message.Substring(0, 16);
    private string GetKey(string base64Message) => base64Message.Substring(base64Message.IndexOf("key=") + 4);
    private bool IsValidIV(string iv) => !string.IsNullOrEmpty(iv);
    private bool IsValidKey(string key) => !string.IsNullOrEmpty(key);

    private HMACSHA256 GetHmac() => _hmac;
}

public enum CipherMode
{
    CBC,
    CFB
}
