public sealed class DataProcessorUtility : IDisposable, ILoggable
{
    private readonly RNGCryptoServiceProvider _rng = new RNGCryptoServiceProvider();
    private readonly SecureRandom _secureRand = new SecureRandom();

    public int MinValue { get; set; }
    public int MaxValue { get; set; }

    public DataProcessorUtility(int minValue, int maxValue)
    {
        MinValue = minValue;
        MaxValue = maxValue;
    }

    public byte[] GenerateRandomBytes(int length)
    {
        var randomBytes = new byte[length];
        _rng.GetBytes(randomBytes);
        return randomBytes;
    }

    public float GenerateRandomFloat()
    {
        return (float)_secureRand.NextDouble();
    }

    public int GenerateRandomInt()
    {
        return _secureRand.Next(MinValue, MaxValue + 1);
    }

    public override string ToString()
    {
        return $"Range: {MinValue} - {MaxValue}";
    }

    public void Dispose()
    {
        _rng.Dispose();
    }

    #region AES-CBC Decryption

    private const int ChunkSize = 1024 * 1024; // 1 MB
    private const int MaxConcurrency = 10;

    public async Task<DecryptionResult> DecryptAsync(byte[] ciphertext, byte[] key, byte[] iv, bool useBase64)
    {
        if (key == null || key.Length < 16) throw new ArgumentException("Invalid encryption key.", nameof(key));
        if (iv == null || iv.Length != 16) throw new ArgumentException("Invalid IV length.", nameof(iv));

        var result = new DecryptionResult();
        try
        {
            using var aes = Aes.Create();
            aes.Key = key;
            aes.IV = iv;

            var decryptor = aes.CreateDecryptor();

            int bytesRead;
            byte[] buffer = new byte[ChunkSize];
            using (var ms = new MemoryStream(ciphertext))
            {
                await using (var cryptoStream = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                {
                    bytesRead = cryptoStream.Read(buffer, 0, buffer.Length);
                    while (bytesRead > 0)
                    {
                        var chunk = new byte[bytesRead];
                        Array.Copy(buffer, 0, chunk, 0, bytesRead);
                        result.Plaintext += Encoding.UTF8.GetString(chunk);
                        bytesRead = await ReadChunkAsync(cryptoStream, buffer);
                    }
                }
            }

            if (result.Plaintext.Length == ciphertext.Length)
            {
                // Successful decryption
                return result;
            }
            else
            {
                // Decryption failed
                throw new CryptographicException("Decryption failed.");
            }
        }
        catch (CryptographicException ex)
        {
            result.Error = ex;
            return result;
        }
    }

    private async Task<int> ReadChunkAsync(Stream stream, byte[] buffer)
    {
        int bytesRead;
        try
        {
            bytesRead = await new CancellationTokenSource(1000).WaitForCancellation().ReadAsync(stream, buffer, 0, buffer.Length);
        }
        catch (OperationCanceledException) when (!stream.CanSeek)
        {
            // Stream not seekable; assume end of stream reached.
            return 0;
        }
        catch (Exception ex)
        {
            throw new CryptographicException("Error reading decryption chunk.", ex);
        }
        return bytesRead;
    }

    #endregion

    public async Task<string> FetchMetadataAsync(string operationId)
    {
        // External API call implementation
        using var client = new HttpClient();
        client.DefaultRequestHeaders.Add("Authorization", $"Bearer {operationId}");

        try
        {
            var response = await client.GetAsync("https://example.com/metadata");
            if (response.IsSuccessStatusCode)
            {
                return await response.Content.ReadAsStringAsync();
            }
            else
            {
                // API call failed; retry with backoff strategy
                return await RetryFetchMetadataAsync(operationId);
            }
        }
        catch (HttpRequestException ex)
        {
            throw new Exception("Error fetching metadata.", ex);
        }
    }

    private async Task<string> RetryFetchMetadataAsync(string operationId)
    {
        // Backoff strategy implementation
        using var client = new HttpClient();
        client.DefaultRequestHeaders.Add("Authorization", $"Bearer {operationId}");

        for (int attempt = 0; attempt < 3; attempt++)
        {
            try
            {
                var response = await client.GetAsync("https://example.com/metadata");
                if (response.IsSuccessStatusCode)
                {
                    return await response.Content.ReadAsStringAsync();
                }
                else
                {
                    // API call failed; wait and retry
                    await Task.Delay(TimeSpan.FromSeconds(Math.Pow(2, attempt)));
                }
            }
            catch (HttpRequestException ex)
            {
                throw new Exception("Error fetching metadata.", ex);
            }
        }
        return null;
    }

    public async Task FetchMetadataAsync(CancellationToken ct)
    {
        // External API call implementation
        using var client = new HttpClient();
        client.DefaultRequestHeaders.Add("Authorization", $"Bearer {operationId}");

        try
        {
            while (!ct.IsCancellationRequested)
            {
                var response = await client.GetAsync("https://example.com/metadata");
                if (response.IsSuccessStatusCode)
                {
                    return;
                }
                else
                {
                    // API call failed; retry with backoff strategy
                    await RetryFetchMetadataAsync(operationId);
                }
            }
        }
        catch (HttpRequestException ex)
        {
            throw new Exception("Error fetching metadata.", ex);
        }
    }

    public void Log(string message)
    {
        // Logging framework integration
        Console.WriteLine(message);
    }
}

public class DecryptionResult
{
    public string Plaintext { get; set; }
    public Exception Error { get; set; }
}
