    if (!offsets) {
        free(arrays);
        printf("Memory allocation failed.\n");
        exit(1);
    }

    arrays[0].key = -1;  // Sentinel value for collision detection

    return arrays;
}

void cleanup(record_t** arrays, int* num_keys, int* max_offset) {
    if (*arrays) {
        free(*arrays);
        *arrays = NULL;
    }
    if (*max_offset > 0) {
        free((long*) ((record_t*) *arrays + 1));
        *max_offset = 0;
    }
}

int insert_key(record_t** arrays, int* num_keys, int* max_offset, int key) {
    // Hash-based lookup mechanism
    int index = key % (*max_offset);
    if ((*arrays)[index].key >= 0) {  // Key collision detected
        printf("Collision detected for key %d.\n", key);
        return -1;
    }

    // Insert new record with unique key
    (*arrays)[index].key = key;

    return 0;
}
