// Define a structure to hold user profile metadata
typedef struct {
    char* username;
    char* email;
    char* phoneNumber;
    char* address;
} UserProfile;

// Define a structure to represent the in-memory cache
typedef struct {
    UserProfile* profiles;
    size_t capacity;
    size_t size;
} InMemoryCache;

// Define a function to create an in-memory cache with a given capacity
InMemoryCache* createCache(size_t capacity) {
    InMemoryCache* cache = (InMemoryCache*)malloc(sizeof(InMemoryCache));
    cache->profiles = (UserProfile*)calloc(capacity, sizeof(UserProfile));
    cache->capacity = capacity;
    cache->size = 0;
    return cache;
}

// Define a function to add a user profile to the in-memory cache
void addUserProfile(InMemoryCache* cache, UserProfile* profile) {
    if (cache->size >= cache->capacity / 2) {
        // Resize the cache when it's half full
        InMemoryCache* newCache = createCache(cache->capacity * 2);
        for (int i = 0; i < cache->size; i++) {
            newCache->profiles[i] = cache->profiles[i];
        }
        free(cache->profiles);
        cache = newCache;
    }
    cache->profiles[cache->size++] = profile;
}

// Define a function to retrieve a user profile from the in-memory cache
UserProfile* getUserProfile(InMemoryCache* cache, const char* username) {
    for (int i = 0; i < cache->size; i++) {
        if (strcmp(cache->profiles[i]->username, username) == 0) {
            return cache->profiles[i];
        }
    }
    return NULL;
}

// Define a function to remove a user profile from the in-memory cache
void removeUserProfile(InMemoryCache* cache, const char* username) {
    for (int i = 0; i < cache->size; i++) {
        if (strcmp(cache->profiles[i]->username, username) == 0) {
            // Move the last profile to this position and shrink the array
            UserProfile* lastProfile = cache->profiles[--cache->size];
            free(lastProfile);
            break;
        }
    }
}

