function generateReport(userInput) {
  const reportData = [];
  const reportConfig = {};

  // Handle user input configuration
  if (userInput.config) {
    reportConfig = userInput.config;
  }

  // Fetch data from REST APIs and WebSocket connections
  const externalDataSources = [
    { url: 'https://api.example.com/data1', method: 'GET' },
    { url: 'wss://websocket.example.com/socket', method: 'POST' }
  ];

  Promise.all(
    externalDataSources.map((source) => {
      return axios(source);
    })
  ).then((responses) => {
    responses.forEach((response) => {
      reportData.push(response.data);
    });
  });

  // Handle data inconsistencies and merge data
  const mergedData = reportData.reduce((acc, current) => {
    acc = [...acc, ...current];
    return acc;
  }, []);

  // Generate the report
  const exporter = new Exporter();
  const reportString = exporter.generateReport(mergedData, reportConfig);

  // Handle export options (CSV, PDF, JSON)
  const exportFormat = 'JSON'; // default format

  if (userInput.exportFormat) {
    exportFormat = userInput.exportFormat;
  }

  switch (exportFormat) {
    case 'CSV':
      return exporter.toCsv(reportString);
    case 'PDF':
      return exporter.toPdf(reportString);
    case 'JSON':
    default:
      return reportString;
  }
}

module.exports = generateReport;
