use log::{info, warn, error};
use std::sync::{Arc, Mutex};
use std::thread;

struct Backend {
    name: String,
    level: log::LevelFilter,
}

impl Backend {
    fn new(name: &str) -> Self {
        let level = match name {
            "console" => log::LevelFilter::Info,
            "file" => log::LevelFilter::Warn,
            "network" => log::LevelFilter::Error,
            _ => panic!("Invalid backend"),
        };
        Backend { name: name.to_string(), level }
    }

    fn write(&self, log_entry: &str) {
        match self.name.as_str() {
            "console" => println!("{}", log_entry),
            "file" => {
                let file = std::fs::File::create(self.name.clone() + ".log").unwrap();
                let mut writer = std::io::BufWriter::new(file);
                writeln!(writer, "{}", log_entry).unwrap();
            }
            "network" => {
                // implement network logging
            }
        }
    }
}

struct LoggingService {
    backends: Arc<Mutex<Vec<Backend>>>,
}

impl LoggingService {
    fn new() -> Self {
        LoggingService { backends: Arc::new(Mutex::new(Vec::new())) }
    }

    fn add_backend(&self, backend_name: &str) -> Result<(), String> {
        let mut backends = self.backends.lock().unwrap();
        backends.push(Backend::new(backend_name));
        Ok(())
    }

    fn write_log_entry(&self, log_entry: &str) {
        let mut backends = self.backends.lock().unwrap();
        for backend in &*backends {
            match backend.write(log_entry) {
                Err(_) => warn!("Failed to write to {}", backend.name),
            }
        }
    }
}

fn main() {
    env_logger::init();

    let logging_service = LoggingService::new();

    thread::spawn(move || {
        for _ in 0..10 {
            logging_service.write_log_entry("Hello, world!");
            thread::sleep(std::time::Duration::from_millis(100));
        }
    });

    info!("Starting logging service");
}
