from decimal import Decimal
import threading

class JSONSerializable:
    def to_json(self):
        raise NotImplementedError

    @classmethod
    def from_json(cls, data):
        raise NotImplementedError

class CustomJSONEncoder(json.JSONEncoder):
    def default(self, obj):
        if isinstance(obj, (datetime.datetime, datetime.date)):
            return {'__datetime__': obj.isoformat()}
        elif isinstance(obj, Decimal):
            return str(obj)
        else:
            return super().default(obj)

class CustomJSONDecoder(json.JSONDecoder):
    def object_hook(self, data):
        if '__datetime__' in data:
            return datetime.datetime.strptime(data['__datetime__'], '%Y-%m-%dT%H:%M:%S.%f')
        elif isinstance(data, str) and '.' in data:
            return Decimal(data)
        else:
            return super().object_hook(data)

class Registry:
    _registry = {}
    _lock = threading.Lock()

    @classmethod
    def register(cls, factory):
        with cls._lock:
            if factory not in cls._registry:
                cls._registry[factory] = 0
            else:
                raise ValueError(f"Factory function {factory} is already registered")

    @classmethod
    def deregister(cls, factory):
        with cls._lock:
            if factory in cls._registry:
                del cls._registry[factory]
            else:
                raise ValueError(f"Factory function {factory} is not registered")

    @classmethod
    def get_factory(cls, factory):
        return cls._registry.get(factory)

class DynamicRegistry(Registry):
    _registered = 0

    @classmethod
    def register(cls, factory):
        if cls._registered >= 100:
            raise ValueError("Maximum number of registered factories reached")
        super().register(factory)
        cls._registered += 1

    @classmethod
    def deregister(cls, factory):
        super().deregister(factory)
        cls._registered -= 1

