// Initialize cache with given memory budget
Cache* init_cache(size_t capacity) {
    Cache* c = malloc(sizeof(Cache));
    c->capacity = capacity;
    c->size = 0;
    c->last_access = calloc(capacity, sizeof(time_t));
    c->entries = calloc(capacity, sizeof(Entry*));
    return c;
}

// Add entry to cache with given string key and value
void add_entry(Cache* c, char* str, int val) {
    // Check if memory budget is exceeded
    if (c->size >= c->capacity) {
        printf("Cache full!\n");
        return;
    }

    Entry* e = malloc(sizeof(Entry));
    e->str = str;
    e->val = val;

    // Update cache statistics
    c->last_access[c->size] = time(NULL);
    c->entries[c->size++] = e;
}

// Retrieve integer value by given string key, handling cache misses and evictions
int retrieve(Cache* c, char* str) {
    int i;
    for (i = 0; i < c->size; i++) {
        if (strcmp(c->entries[i]->str, str) == 0) {
            // Update last access time
            c->last_access[i] = time(NULL);

            return c->entries[i]->val;
        }
    }

    // Cache miss, fetch from external data source or generate default value
    printf("Cache miss!\n");
    return -1; // placeholder for actual retrieval logic
}

// Flush cache and free resources
void flush_cache(Cache* c) {
    size_t i;
    for (i = 0; i < c->size; i++) {
        free(c->entries[i]->str);
        free(c->entries[i]);
