// Define the entry structure
typedef struct {
    char* key;
    int value;
} Entry;

// Define the hash table
typedef struct {
    size_t size;
    Entry** entries;
} HashTable;

// Function to initialize the hash table
HashTable* init_hash_table(size_t size) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->size = size;
    table->entries = (Entry**)calloc(size, sizeof(Entry*));
    return table;
}

// Function to add an entry to the hash table
void add_entry(HashTable* table, char* key, int value) {
    // Create a new entry and initialize it
    Entry* entry = (Entry*)malloc(sizeof(Entry));
    entry->key = strdup(key);
    entry->value = value;

    // Find the bucket for the given key using a simple hash function
    size_t index = strlen(key) % table->size;
    if (!table->entries[index]) {
        table->entries[index] = (Entry*)malloc(sizeof(Entry));
    }
    table->entries[index]->key = entry->key;
    table->entries[index]->value = value;

    // If the hash table is full, resize it
    if (table->size * 2 < strlen(key)) {
        HashTable* new_table = init_hash_table(table->size * 2);
        for (size_t i = 0; i < table->size; i++) {
            Entry* entry = table->entries[i];
            while (entry) {
                size_t index = strlen(entry->key) % new_table->size;
                if (!new_table->entries[index]) {
                    new_table->entries[index] = (Entry*)malloc(sizeof(Entry));
                }
                new_table->entries[index]->key = strdup(entry->key);
                new_table->entries[index]->value = entry->value;
                entry = entry->next;
            }
        }
        free(table->entries);
        table = new_table;
    }
}

// Function to retrieve the integer value using a given string key
int get_value(HashTable* table, char* key) {
    size_t index = strlen(key) % table->size;
    if (table->entries[index]) {
        for (Entry* entry = table->entries[index]; entry; entry = entry->next) {
            if (!strcmp(entry->key, key)) {
                return entry->value;
            }
        }
    }
    return -1;
}

// Function to remove an entry from the hash table
void remove_entry(HashTable* table, char* key) {
    size_t index = strlen(key) % table->size;
    if (table->entries[index]) {
        Entry** prev = &table->entries[index];
        for (; *prev; prev = &(*prev)->next) {
            if (!strcmp((*prev)->key, key)) {
                free((*prev)->key);
                free(*prev);
                *prev = (*prev)->next;
                return;
            }
        }
    }
}

// Function to check the existence of a configuration file
int has_config() {
    FILE* file = fopen("config.yaml", "r");
    if (file) {
        fclose(file);
        return 1;
    }
    return 0;
}

int main() {
    // Initialize the hash table with an initial size of 16
    HashTable* table = init_hash_table(16);

    // Add some entries to the hash table
    add_entry(table, "entry1", 10);
    add_entry(table, "entry2", 20);
    add_entry(table, "entry3", 30);

    // Retrieve an entry from the hash table
    int value = get_value(table, "entry2");
    printf("Value: %d\n", value);

    // Remove an entry from the hash table
    remove_entry(table, "entry1");

    // Check the existence of a configuration file
    int has_config_file = has_config();
    if (has_config_file) {
        printf("Config file exists.\n");
    } else {
        printf("Insufficient configuration.\n");
    }

    return 0;
}
