int dns_resolution(char* hostname, u_char* ip_addr) {
    struct hostent* host;
    int ret_code = 0;

    // Set limits on system resources to prevent unauthorized access
    setrlimit(RLIMIT_CORE, (struct rlimit){RLIM_INFINITY, RLIM_INFINITY});
    setrlimit(RLIMIT_AS, (struct rlimit){RLIM_INFINITY, RLIM_INFINITY});

    host = gethostbyname(hostname);
    if (!host) {
        // Handle DNS resolution failure
        ret_code = 1;
        printf("DNS resolution failed for hostname '%s'\n", hostname);
    } else {
        // Perform IP address resolution and store it in the u_char array
        strcpy(ip_addr, inet_ntoa(*(struct in_addr*)host->h_addr));
    }

    return ret_code;
}
