def modify_kickstart_config(config_file_path, placeholders, actual_values):
    # Create a temporary file to hold the modified configuration
    temp_file = "temp_{}".format(os.path.basename(config_file_path))
    with open(temp_file, 'w') as f:
        with open(config_file_path, 'r') as original_file:
            for line in original_file:
                for placeholder, value in placeholders.items():
                    if placeholder in line:
                        line = line.replace(placeholder, str(value))
                f.write(line)

    # Replace placeholders with actual values
    for placeholder, value in placeholders.items():
        subprocess.run(["sed", "-i", "s/{}\/{}/g".format(placeholder, value), temp_file])

    # Add a new line with an encrypted password
    subprocess.run(["echo", "encrypted_password"], stdout=subprocess.PIPE)

    # Create the modified configuration file
    os.replace(temp_file, config_file_path)

