void nfa_pi_crc_indication_pdu_manager_init() {
    nfa_pi_crc_indication_pdu_manager.list = NULL;
    pthread_mutex_init(&nfa_pi_crc_indication_pdu_manager.lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* nfa_pi_crc_indication_pdu_manager_alloc() {
    NFAPI_CRC_INDICATION_PDU_T* p = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!p) return NULL;
    atomic_init(&p->CRCFLAG, true);
    return p;
}

void nfa_pi_crc_indication_pdu_manager_free(NFAPI_CRC_INDICATION_PDU_T* p) {
    free(p);
}

int nfa_pi_crc_indication_pdu_manager_insert(NFAPI_CRC_INDATION_PDU_T* p) {
    pthread_mutex_lock(&nfa_pi_crc_indication_pdu_manager.lock);
    if (!nfa_pi_crc_indication_pdu_manager.list) {
        nfa_pi_crc_indication_pdu_manager.list = p;
    } else {
        NFAPI_CRC_INDICATION_PDU_T** tail = &nfa_pi_crc_indication_pdu_manager.list;
        while (*tail) {
            tail = &((*tail)->next);
        }
        *tail = p;
    }
    pthread_mutex_unlock(&nfa_pi_crc_indication_pdu_manager.lock);
}

