pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T* dynamic_list = NULL;
int list_size = 0;
int gc_count = 0;

void gc(void) {
    if (gc_count < GC_INTERVAL) return;
    gc_count = 0;

    pthread_mutex_lock(&lock);
    for (int i = 0; i < list_size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* ptr = &dynamic_list[i];
        if (!ptr->RX_UE_INFORMATION_TAG || !ptr->RNTI[0] || !ptr->CRC_INDICATION_REL8_TAG || !ptr->CRCFLAG) {
            // reclaim memory
            free(&dynamic_list[i]);
            --list_size;
            i--;
        }
    }
    pthread_mutex_unlock(&lock);
}

