#include <libgen.h>

unsigned int load_resource_bundle(const char *file_path) {
    int fd = open(file_path, O_RDONLY);
    if (fd == -1) {
        printf("Error opening file: %s\n", strerror(errno));
        return 0;
    }

    struct stat sb;
    fstat(fd, &sb);

    // Check for invalid file size or number of items
    if (sb.st_size > 1024 * 1024 * 1 || sb.st_size / sizeof(struct bundle_item) > 10000) {
        printf("Invalid file size or number of items\n");
        close(fd);
        return 0;
    }

    struct bundle_item *bundle = mmap(NULL, sb.st_size, PROT_READ, MAP_SHARED, fd, 0);
    if (bundle == MAP_FAILED) {
        printf("Error mapping file: %s\n", strerror(errno));
        close(fd);
        return 0;
    }

    unsigned int count = 0;
    for (unsigned int i = 0; i < sb.st_size / sizeof(struct bundle_item); i++) {
        if (bundle[i].id != 0) {
            count++;
        }
    }

    munmap(bundle, sb.st_size);
    close(fd);

    return count;
}

struct bundle_item {
    uint32_t id;
    // Variable-length data field
};

