void processTiffFile(std::forward_list<std::string>& tiffData) {
    std::string targetString = "target_string";
    std::string insertionString = "insertion_string";

    auto insertIterator = tiffData.begin();
    for (auto it = tiffData.begin(); it != tiffData.end(); ++it) {
        if (*it == targetString) {
            // Found the target string, insert the new string
            tiffData.insert(it++, insertionString);
            break;
        }
    }

    if (insertIterator == tiffData.end()) {
        // Target string not found, append to the end of the list
        tiffData.push_back(insertionString);
    }
