#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/stat.h>

#define MAX_FILENAME_LENGTH 255
#define RANDOM_SEQUENCE_LENGTH 8
#define FILE_TYPE_ID_COUNT 3

char* get_file_type(const char* filename) {
    static const char* extensions[] = {".txt", ".jpg", ".png"};
    int i;
    for (i = 0; i < FILE_TYPE_ID_COUNT; i++) {
        if (strrchr(filename, extensions[i][1]) != NULL) {
            return extensions[i];
        }
    }
    return ".txt";
}

char* generate_random_sequence(void) {
    static char buffer[RANDOM_SEQUENCE_LENGTH + 1];
    int i;
    for (i = 0; i < RANDOM_SEQUENCE_LENGTH; i++) {
        buffer[i] = 'a' + rand() % 26;
    }
    buffer[RANDOM_SEQUENCE_LENGTH] = '\0';
    return buffer;
}

char* generate_timestamp(void) {
    static char buffer[16];
    time_t now = time(NULL);
    struct tm* timestamp = localtime(&now);
    strftime(buffer, sizeof(buffer), "%Y%m%d%H%M%S", timestamp);
    return buffer;
}

int rename_files(const char* directory_path, const char** files_to_process) {
    DIR* dir = opendir(directory_path);
    if (dir == NULL) {
        return -1; // Error opening directory
    }

    struct dirent* dent;
    while ((dent = readdir(dir)) != NULL) {
        char* filename = dent->d_name;
        int file_index;
        for (file_index = 0; file_index < strlen(files_to_process); file_index++) {
            if (strcmp(filename, files_to_process[file_index]) == 0) {
                break;
            }
        }

        if (file_index >= strlen(files_to_process)) {
            continue; // File not in the list
        }

        char* original_filename = malloc(strlen(directory_path) + strlen(filename) + 1);
        strcpy(original_filename, directory_path);
        strcat(original_filename, "/");
        strcat(original_filename, filename);

        char* new_filename = malloc(MAX_FILENAME_LENGTH + 1);
        strcpy(new_filename, get_file_type(filename));
        if (strlen(filename) > 0 && filename[0] != '.') {
            strcat(new_filename, "_");
        }
        strcat(new_filename, generate_random_sequence());
        strcat(new_filename, "_");
        strcat(new_filename, generate_timestamp());
        strcat(new_filename, ".txt"); // Default file type if none specified

        int result = rename(original_filename, new_filename);
        free(original_filename);
        free(new_filename);

        if (result == -1) {
            return -1; // Error renaming file
        }
    }

    closedir(dir);
    return 0;
}

