};

class DynamicList {
private:
    struct Node {
        MAC_PDU data;
        Node* next;
    };

    Node* head;
    Node* tail;
    size_t size;
    std::mutex mtx;
    std::condition_variable cv;

public:
    DynamicList() : head(nullptr), tail(nullptr), size(0) {}

    void insert(MAC_PDU pdu) {
        {
            std::unique_lock<std::mutex> lock(mtx);
            Node* newNode = new Node();
            newNode->data = pdu;
            newNode->next = nullptr;

            if (head == nullptr) {
                head = tail = newNode;
            } else {
                tail->next = newNode;
                tail = newNode;
            }

            size++;
        }
        // Validate checksum
    }

    bool validateChecksum(MAC_PDU pdu) {
        return pdu.payload_checksum == calculateChecksum(pdu);
    }

    void remove() {}

    size_t getSize() const {
        std::lock_guard<std::mutex> lock(mtx);
        return size;
    }

    void clear() {
        Node* curr = head;
        while (curr != nullptr) {
            Node* next = curr->next;
            delete curr;
            curr = next;
        }
        head = tail = nullptr;
        size = 0;
    }

    ~DynamicList() {
        clear();
    }
};

