#include <random>

class DynamicRangeCommandExecutor {
private:
    int minValue;
    int maxValue;

public:
    DynamicRangeCommandExecutor(int min, int max) : minValue(min), maxValue(max) {
        if (min > max) {
            std::swap(minValue, maxValue);
        }
    }

    int ExecuteCommand(const std::string& command) {
        // Implement the execution of the command in the background
        return 1; // Successful execution
    }

    float GenerateRandomFloat() {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_real_distribution<float> dis(minValue, maxValue);
        return dis(gen);
    }

    int GenerateRandomInt() {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<int> dis(minValue, maxValue);
        return dis(gen);
    }

    float GenerateExclusiveRandomFloat() {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_real_distribution<float> dis(0.0f, static_cast<float>(maxValue - minValue));
        return dis(gen) + static_cast<float>(minValue);
    }

    int GenerateExclusiveRandomInt() {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<int> dis(0, maxValue - minValue - 1);
        return dis(gen) + minValue;
    }

    std::string ToString() const {
        return "Range: [" + std::to_string(minValue) + ", " + std::to_string(maxValue) + "]";
    }

    void AdjustRange(float adjustment) {
        if (adjustment > 0) {
            maxValue += static_cast<int>(adjustment);
            minValue = std::max(0, minValue);
        } else if (adjustment < 0) {
            minValue -= std::abs(static_cast<int>(adjustment));
            maxValue = std::min(maxValue, static_cast<int>(1000000 - adjustment));
        }
    }

    void ResetRange() {
        minValue = 0;
        maxValue = 100;
    }

    // Log adjustments for debugging purposes
    void LogAdjustment(float adjustment) {
        // Implement the logging mechanism
    }
};
