using System;
using System.Collections.Generic;
using System.Linq;

public class LogManager
{
    private Dictionary<string, List<LogEntry>> _logs = new();
    private readonly object _lock = new();
    private readonly int _initialCapacity = 1000; // adjustable based on traffic load

    public void Log(string logType, string data)
    {
        lock (_lock)
        {
            if (!_logs.TryGetValue(logType, out List<LogEntry> entries))
                _logs.Add(logType, (entries = new List<LogEntry>(_initialCapacity)));

            entries.Add(new LogEntry(DateTime.Now, data));
        }
    }

    public IEnumerable<LogEntry> GetLogs(string logType, DateTime startTime, DateTime endTime)
    {
        lock (_lock)
        {
            return _logs.ContainsKey(logType) 
                ? _logs[logType].Where(e => e.Timestamp >= startTime && e.Timestamp <= endTime) 
                : Enumerable.Empty<LogEntry>();
        }
    }

    public class LogEntry
    {
        public DateTime Timestamp { get; set; }
        public string Data { get; set; }

        public LogEntry(DateTime timestamp, string data)
        {
            Timestamp = timestamp;
            Data = data;
        }
    }
}
