    while (fscanf(file, "%s\n", strings_size + 1) == 1) {
        size_t new_strings_size = strings_size + 2;
        strings = realloc(strings, sizeof(char*) * new_strings_size);
        if (!strings) {
            printf("Error allocating memory for strings.\n");
            fclose(file);
            return;
        }
        char* line = (char*)malloc(new_strings_size);
        if (!line) {
            printf("Error allocating memory for string.\n");
            free(strings);
            fclose(file);
            return;
        }
        fgets(line, new_strings_size, file);
        strings[strings_size] = line;
        strings_size = new_strings_size;
    }

    while (fscanf(file, "%d %d\n", &points[lines].x, &points[lines].y) == 2) {
        points_size += sizeof(point);
        point* temp_points = (point*)realloc(points, points_size);
        if (!temp_points) {
            printf("Error allocating memory for points.\n");
            free(strings);
            fclose(file);
            return;
        }
        points = temp_points;
    }

    for (int i = 0; i < lines; i++) {
        free(strings[i]);
    }
    free(strings);

    for (int i = 0; i < points_size / sizeof(point); i++) {
        free(&points[i]);
    }
    free(points);

    fclose(file);
}

int main() {
    manage_memory("input.txt");
    return 0;
}
