using System;
using System.IO;
using System.Xml.Linq;
using System.Collections.Generic;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

public class XmlProcessor
{
    private readonly ILogger _logger;
    private readonly XDocument _xmlDoc;

    public XmlProcessor(ILogger<XmlProcessor> logger, string xmlPath)
    {
        _logger = logger;
        _xmlDoc = XDocument.Load(xmlPath);
    }

    public async Task<IEnumerable<XElement>> ProcessAsync(string elementName)
    {
        var uniqueElements = new HashSet<XElement>();
        int totalElementsProcessed = 0;

        await using (var stream = _xmlDoc.CreateStream())
        {
            using (var reader = XmlReader.Create(stream, new XmlReaderSettings { Async = true }))
            {
                while (await reader.ReadAsync())
                {
                    if (reader.NodeType == XmlNodeType.Element && reader.Name == elementName)
                    {
                        var element = (XElement)XNode.Read(reader);
                        if (!uniqueElements.Add(element))
                        {
                            _logger.LogInformation("Duplicate element found: {0}", elementName);
                        }
                        totalElementsProcessed++;
                    }
                }
            }
        }

        _logger.LogInformation("Total elements processed: {0}, Unique matching elements: {1}", totalElementsProcessed, uniqueElements.Count);

        return uniqueElements;
    }
}

public class XmlProcessorFactory
{
    public static XmlProcessor Create(ILogger<XmlProcessor> logger, string xmlPath)
    {
        return new XmlProcessor(logger, xmlPath);
    }
}
