typedef struct NFAPI_RRC_PDU_T {
    int rrConnectionStatusIndicationPdu;
    int cellIdentity;
} NFAPI_RRC_PDU_T;

// Function to manage dynamic list of NFAPI_RRC_PDU_T structures
void manageRRConnectionList(NFAPI_RRC_PDU_T **list, size_t *size) {
    // Allocate memory for new structure
    NFAPI_RRC_PDU_T *newElement = (NFAPI_RRC_PDU_T *)malloc(sizeof(NFAPI_RRC_PDU_T));

    // Validate the integrity of the received data packet
    if (!newElement || !validateData(newElement->rrConnectionStatusIndicationPdu, newElement->cellIdentity)) {
        free(newElement);  // Deallocate memory if data is invalid
        return;
    }

    // Add new element to the list
    if (*size == 0) {
        *list = newElement;
    } else {
        NFAPI_RRC_PDU_T *temp = (NFAPI_RRC_PDU_T *)malloc((*size + 1) * sizeof(NFAPI_RRC_PDU_T));
        memcpy(temp, *list, (*size) * sizeof(NFAPI_RRC_PDU_T));
        free(*list);
        *list = temp;
    }
    (*list)[*size] = *newElement;

    (*size)++;

    // Log successful operation
    logInfo("Added new RR connection to the list");

    return;
}

// Function to deallocate memory for dynamic list of NFAPI_RRC_PDU_T structures
void freeRRConnectionList(NFAPI_RRC_PDU_T **list, size_t *size) {
    if (*size > 0) {
        // Deallocate memory for each element in the list
        for (int i = 0; i < *size; i++) {
            free((*list + i)->cellIdentity);  // Deallocate cell identity
            free(*list + i);
        }
    }

    free(*list);

    *size = 0;

    return;
}

// Function to validate the integrity of received data packet
int validateData(int rrConnectionStatusIndicationPdu, int cellIdentity) {
    if (rrConnectionStatusIndicationPdu >= 0 && rrConnectionStatusIndicationPdu <= 255 &&
        cellIdentity >= 0 && cellIdentity <= 1023) {
        return 1;  // Data packet is valid
    } else {
        return 0;  // Data packet is invalid
    }
}

// Function to log messages
void logInfo(const char *message) {
    printf("INFO: %s\n", message);
}
