{
    private readonly ILogger<UpdateElementController> _logger;
    private readonly IDistributedService _distributedService;
    private readonly ICacheManager _cacheManager;
    private readonly IBgJobService _bgJobService;

    public UpdateElementController(ILogger<UpdateElementController> logger, 
                                    IDistributedService distributedService, 
                                    ICacheManager cacheManager, 
                                    IBgJobService bgJobService)
    {
        _logger = logger;
        _distributedService = distributedService;
        _cacheManager = cacheManager;
        _bgJobService = bgJobService;
    }

    [HttpPost]
    public async Task UpdateElement([FromUri] string pageSectionId, 
                                    [FromUri] string elementId, 
                                    [FromBody] string htmlContent, 
                                    [FromHeader] string userToken)
    {
        if (!ValidateUserToken(userToken))
        {
            _logger.LogError("Invalid user token");
            return StatusCode(401);
        }

        var executionTime = DateTime.Now;
        try
        {
            await _distributedService.UpdateElementAsync(pageSectionId, elementId, htmlContent);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error updating element");
            if (!ShouldRetry(ex))
            {
                return StatusCode(500);
            }

            // Retry logic with exponential backoff
            await Task.Delay(TimeSpan.FromMilliseconds(Random.Next(1000) * 2));
            await _distributedService.UpdateElementAsync(pageSectionId, elementId, htmlContent);
        }
        finally
        {
            _logger.LogInformation("Element updated");
            _logger.LogInformation($"Execution time: {DateTime.Now - executionTime}");
        }

        // Trigger background job to invalidate CDN cache
        await _bgJobService.InvalidateCdnCacheAsync(pageSectionId);

        return StatusCode(200);
    }

    private bool ValidateUserToken(string token)
    {
        // Implement user session validation logic here
    }

