// Function to manage dynamic memory allocation for multiple data structures
void* manageMemory(int** doubleArr, int* doubleSize, char*** strArr, int* strSize, Point** pointArr, int* pointSize) {
    // Check if the number of elements is greater than 0
    if (*doubleSize > 0 || *strSize > 0 || *pointSize > 0) {
        // Initialize the pointers to NULL
        *doubleArr = (int*)malloc(*doubleSize * sizeof(int));
        *strArr = (char**)malloc(*strSize * sizeof(char*));
        *pointArr = (Point*)malloc(*pointSize * sizeof(Point));

        if (*doubleArr == NULL || *strArr == NULL || *pointArr == NULL) {
            // If memory allocation fails, free already allocated memory
            if (*doubleArr != NULL) free(*doubleArr);
            if (*strArr != NULL) {
                for (int i = 0; i < *strSize; i++) {
                    if ((*strArr)[i] != NULL) free((*strArr)[i]);
                }
                free(*strArr);
            }
            if (*pointArr != NULL) free(*pointArr);

            // Log error
            printf("Memory allocation failed.\n");

            return NULL;
        }

        // Initialize pointers in the arrays
        for (int i = 0; i < *doubleSize; i++) {
            (*doubleArr)[i] = i;
        }
        for (int i = 0; i < *strSize; i++) {
            (*strArr)[i] = (char*)malloc(100 * sizeof(char));
            sprintf((*strArr)[i], "String %d", i);
        }
        for (int i = 0; i < *pointSize; i++) {
            (*pointArr)[i].x = i;
            (*pointArr)[i].y = i;
        }

        // Log success
        printf("Memory allocation successful.\n");

        return NULL;
    } else {
        // If the number of elements is 0, log warning and free allocated memory
        printf("No data to process.\n");
        if (*doubleArr != NULL) free(*doubleArr);
        if (*strArr != NULL) {
            for (int i = 0; i < *strSize; i++) {
                if ((*strArr)[i] != NULL) free((*strArr)[i]);
            }
            free(*strArr);
        }
        if (*pointArr != NULL) free(*pointArr);

        return NULL;
    }
}

// Function to log critical events
void logEvent(const char* message) {
    printf("Critical event: %s\n", message);
}

int main() {
    int doubleSize = 5;
    char** strArray;
    Point* pointArray;

    manageMemory(&strArray, &doubleSize, &pointArray);

