record** getDisjointSets(int n, int* offsets, int keys[], int num_keys) {
    // Create Union-Find data structure
    int* parent = (int*)malloc((n+1)*sizeof(int));
    for (int i = 0; i <= n; i++) parent[i] = i;

    srand(time(NULL));  // Initialize random number generator

    // Calculate and record offsets
    long* offset_arr = (long*)malloc(n*sizeof(long));
    for (int i = 0; i < n; i++) {
        offset_arr[i] = rand() % num_keys;  // Initialize to a random key value
    }

    int count = 1;
    for (int i = 1; i <= n; i++) {
        if (parent[offsets[i-1]] != parent[i-1]) {
            parent[offsets[i-1]] = parent[i];
            count++;
        }
    }

    // Calculate and record keys
    int* key_arr = (int*)malloc(n*sizeof(int));
    for (int i = 0; i < n; i++) key_arr[i] = keys[offsets[i]];

    // Group records by their keys
    int set_count = 1;
    for (int i = 1; i <= n; i++) {
        if (parent[offsets[i-1]] != parent[i]) {
            set_count++;
            parent[offsets[i-1]] = parent[i];
        }
    }

    // Calculate and record disjoint sets
    int** disjoint_sets = (int**)malloc(set_count*sizeof(int*));
    for (int i = 0; i < set_count; i++) {
        disjoint_sets[i] = (int*)malloc(count*sizeof(int));
        for (int j = 0; j < count; j++)
            disjoint_sets[i][j] = offset_arr[j];
    }

    free(offset_arr);
    free(key_arr);

    return disjoint_sets;
}
