        *(void**) ((char*) array + i * sizeof(void*)) = str;
        *(point**) ((char*) array + size * sizeof(void*) + i * sizeof(point)) = pt;
    }

    return array;
}

void destroy_array(void* array, int size) {
    for (int i = 0; i < size; i++) {
        // Free strings
        char* str = *(char**) ((char*) array + i * sizeof(void*));
        free(str);

        // Free points
        point* pt = *(point**) ((char*) array + size * sizeof(void*) + i * sizeof(point));
        free(pt);
    }

    free(array);
}

int main() {
    int size = 10;
    int string_length = 5;

    srand(time(NULL)); // seed random number generator

    void* array = create_array(size, string_length);

    // Use the array...

    destroy_array(array, size);

    return 0;
}
