#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PROFILES 10000
#define USERNAME_MAX_LENGTH 20
#define EMAIL_MAX_LENGTH 50
#define AGE_MIN 18
#define AGE_MAX 65

typedef struct {
    char* username;
    int age;
    char* email;
} UserProfile;

UserProfile** profiles = NULL;
int profileCount = 0;

void initializeProfiles() {
    profiles = (UserProfile**)malloc(MAX_PROFILES * sizeof(UserProfile*));
}

void insertProfile(char* username, int age, char* email) {
    UserProfile* newProfile = (UserProfile*)malloc(sizeof(UserProfile));
    newProfile->username = strdup(username);
    newProfile->age = age;
    newProfile->email = strdup(email);

    if (profileCount < MAX_PROFILES) {
        profiles[profileCount++] = newProfile;
    } else {
        // Resize the collection when necessary
        UserProfile** newProfiles = (UserProfile**)realloc(profiles, (MAX_PROFILES * 2 + 1) * sizeof(UserProfile*));
        for (int i = profileCount; i < MAX_PROFILES * 2; i++) {
            newProfiles[i] = NULL;
        }
        profiles = newProfiles;
    }
}

void deleteProfile(char* username) {
    for (int i = 0; i < profileCount; i++) {
        if (strcmp(profiles[i]->username, username) == 0) {
            free(profiles[i]->username);
            free(profiles[i]->email);
            free(profiles[i]);
            for (int j = i; j < profileCount - 1; j++) {
                profiles[j] = profiles[j + 1];
            }
            profileCount--;
            break;
        }
    }
}

UserProfile* getProfile(char* username) {
    for (int i = 0; i < profileCount; i++) {
        if (strcmp(profiles[i]->username, username) == 0) {
            return profiles[i];
        }
    }
    return NULL;
}

void serializeProfilesToBinaryFile(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    for (int i = 0; i < profileCount; i++) {
        UserProfile* profile = profiles[i];
        fwrite(&profile->age, sizeof(int), 1, file);
        size_t usernameLength = strlen(profile->username);
        fwrite(&usernameLength, sizeof(size_t), 1, file);
        fwrite(profile->username, sizeof(char), usernameLength, file);
        size_t emailLength = strlen(profile->email);
        fwrite(&emailLength, sizeof(size_t), 1, file);
        fwrite(profile->email, sizeof(char), emailLength, file);
    }

    fclose(file);
}

void deserializeProfilesFromBinaryFile(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return;

    UserProfile** newProfiles = (UserProfile**)malloc(MAX_PROFILES * sizeof(UserProfile*));
    int newProfileCount = 0;
    while (1) {
        UserProfile* newProfile = (UserProfile*)malloc(sizeof(UserProfile));
        fread(&newProfile->age, sizeof(int), 1, file);
        size_t usernameLength;
        fread(&usernameLength, sizeof(size_t), 1, file);
        char* newUsername = (char*)malloc((usernameLength + 1) * sizeof(char));
        fread(newUsername, sizeof(char), usernameLength, file);
        newUsername[usernameLength] = '\0';
        newProfile->username = newUsername;

        size_t emailLength;
        fread(&emailLength, sizeof(size_t), 1, file);
        char* newEmail = (char*)malloc((emailLength + 1) * sizeof(char));
        fread(newEmail, sizeof(char), emailLength, file);
        newEmail[emailLength] = '\0';
        newProfile->email = newEmail;

        if (!fread(&newProfile->age, sizeof(int), 1, file)) break;
        newProfiles[newProfileCount++] = newProfile;
    }

    for (int i = 0; i < profileCount; i++) {
        free(profiles[i]->username);
        free(profiles[i]->email);
        free(profiles[i]);
    }
    for (int i = 0; i < newProfileCount; i++) {
        profiles[i] = newProfiles[i];
    }
    profileCount = newProfileCount;
    free(newProfiles);

    fclose(file);
}

int main() {
    srand(time(NULL));
    initializeProfiles();
    for (int i = 0; i < MAX_PROFILES; i++) {
        char* username = malloc((USERNAME_MAX_LENGTH + 1) * sizeof(char));
        int age = rand() % (AGE_MAX - AGE_MIN + 1) + AGE_MIN;
        char* email = malloc((EMAIL_MAX_LENGTH + 1) * sizeof(char));
        sprintf(username, "user_%d", i);
        sprintf(email, "example_email_%d@example.com", i);
        insertProfile(username, age, email);
    }

    // Example usage
    UserProfile* profile = getProfile("user_0");
    if (profile) {
        printf("Username: %s\nAge: %d\nEmail: %s\n", profile->username, profile->age, profile->email);
    } else {
        printf("Profile not found.\n");
    }

    // Example usage
    deleteProfile("user_5");

    // Example usage
    serializeProfilesToBinaryFile("profiles.bin");
    deserializeProfilesFromBinaryFile("profiles.bin");

    return 0;
}
