struct UserInteraction {
    int action_type;
    time_t timestamp;
};

class InteractionManager {
public:
    std::vector<UserInteraction*> interactions;
    size_t count = 0;

    void addInteraction(int action_type, time_t timestamp) {
        interactions.push_back(new UserInteraction{action_type, timestamp});
        ++count;
    }

    std::vector<UserInteraction*> getFilteredInteractions(time_t start_time, time_t end_time, int action_type) {
        std::vector<UserInteraction*> filtered_interactions;
        for (size_t i = 0; i < count; ++i) {
            if ((interactions[i]->timestamp >= start_time && interactions[i]->timestamp <= end_time) &&
                interactions[i]->action_type == action_type) {
                filtered_interactions.push_back(interactions[i]);
            }
        }
        return filtered_interactions;
    }
};

int main() {
    InteractionManager manager;

    // Add some user interactions
    for (int i = 0; i < 10000; ++i) {
        manager.addInteraction(i % 2, std::chrono::system_clock::now().time_since_epoch().count());
    }

    // Filter and retrieve interactions
    auto filtered_interactions = manager.getFilteredInteractions(std::chrono::system_clock::now().time_since_epoch().count() - 1000,
                                                                 std::chrono::system_clock::now().time_since_epoch().count(),
                                                                 1);

    for (auto& interaction : filtered_interactions) {
        std::cout << "Action type: " << interaction->action_type << ", Timestamp: " << interaction->timestamp << std::endl;
    }

    return 0;
}
