    int key;
    int value;
} Record;

typedef struct {
    Record** records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} HashTable;

HashTable* hash_table_create(size_t initial_capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    table->capacity = initial_capacity;
    table->size = 0;
    pthread_mutex_init(&table->mutex, NULL);
    return table;
}

void hash_table_free(HashTable* table) {
    for (int i = 0; i < table->capacity; i++) {
        free(table->records[i]);
    }
    free(table->records);
    pthread_mutex_destroy(&table->mutex);
    free(table);
}

size_t hash_function(int key) {
    return key % table->capacity;
}

void hash_table_insert(HashTable* table, int key, int value) {
    pthread_mutex_lock(&table->mutex);
    size_t index = hash_function(key);
    if (index >= table->size) {
        // Resize the underlying storage as needed
        if (table->size * 2 > table->capacity) {
            Record** new_records = (Record**)realloc(table->records, sizeof(Record*) * table->size * 2);
            for (int i = 0; i < table->size; i++) {
                new_records[i] = table->records[i];
            }
            free(table->records);
            table->records = new_records;
        }
    }
    if (!table->records[index]) {
        table->records[index] = (Record*)malloc(sizeof(Record));
        table->records[index]->key = key;
        table->records[index]->value = value;
    } else {
        // Handle collision by rehashing or using a different technique
        size_t new_index = hash_function(key);
        if (!table->records[new_index]) {
            table->records[new_index] = (Record*)malloc(sizeof(Record));
            table->records[new_index]->key = key;
            table->records[new_index]->value = value;
        }
    }
    table->size++;
    pthread_mutex_unlock(&table->mutex);
}

int hash_table_get_largest_value(HashTable* table) {
    int largest_value = INT_MIN;
    for (int i = 0; i < table->capacity; i++) {
        if (table->records[i] && table->records[i]->value > largest_value) {
            largest_value = table->records[i]->value;
        }
    }
    return largest_value;
}

void hash_table_serialize(HashTable* table, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        // Handle error
    }
    size_t capacity = table->capacity;
    for (int i = 0; i < capacity; i++) {
        Record* record = table->records[i];
        if (record) {
            fwrite(&record->key, sizeof(int), 1, file);
            fwrite(&record->value, sizeof(int), 1, file);
        } else {
            fwrite(&capacity, sizeof(size_t), 1, file);
        }
    }
    fclose(file);
}

int main() {
    HashTable* table = hash_table_create(1000);
    // Insert records
    for (int i = 0; i < 10000; i++) {
        int key = rand() % 100000;
        int value = rand() % 1000000;
        hash_table_insert(table, key, value);
    }
    printf("Largest value: %d\n", hash_table_get_largest_value(table));
    // Serialize and deserialize
    hash_table_serialize(table, "data.bin");
    // Read from file
    HashTable* table2 = (HashTable*)malloc(sizeof(HashTable));
    table2->capacity = 1000;
    table2->records = (Record**)calloc(1000, sizeof(Record*));
    table2->size = 0;
    pthread_mutex_init(&table2->mutex, NULL);
    FILE* file = fopen("data.bin", "rb");
