#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef enum {
    OK,
    ERROR
} status_t;

struct metric {
    double value;
    int timestamp;
    status_t status;
};

void processAndManageMetrics(struct metric **metrics, size_t *num_metrics, FILE *fp) {
    // Initialize arrays and structures
    *num_metrics = 0;
    *metrics = NULL;
    size_t capacity = 1;
    struct metric *temp_metrics = (struct metric *)malloc(capacity * sizeof(struct metric));

    if (!temp_metrics) {
        perror("Memory allocation failed");
        return;
    }

    int last_timestamp = -1;

    while (fscanf(fp, "%lf %d\n", &temp_metrics[*num_metrics].value, &temp_metrics[*num_metrics].timestamp) == 2) {
        if (temp_metrics[*num_metrics].timestamp <= last_timestamp) {
            printf("Timestamp is not unique. Skipping...\n");
            continue;
        }
        last_timestamp = temp_metrics[*num_metrics].timestamp;

        // Increase the capacity if necessary
        if (*num_metrics >= capacity) {
            capacity *= 2;
            struct metric *new_metrics = (struct metric *)realloc(temp_metrics, capacity * sizeof(struct metric));
            if (!new_metrics) {
                perror("Memory reallocation failed");
                free(temp_metrics);
                return;
            }
            temp_metrics = new_metrics;
        }

        (*num_metrics)++;
    }

    // Reorder the array to ensure unique timestamps
    for (size_t i = 0; i < *num_metrics; ++i) {
        for (size_t j = i + 1; j < *num_metrics; ++j) {
            if (temp_metrics[j].timestamp < temp_metrics[i].timestamp) {
                struct metric temp = temp_metrics[i];
                temp_metrics[i] = temp_metrics[j];
                temp_metrics[j] = temp;
            }
        }
    }

    *metrics = temp_metrics;
}

void filterAndPrintMetrics(struct metric **metrics, size_t num_metrics, status_t target_status) {
    for (size_t i = 0; i < num_metrics; ++i) {
        if (metrics[i]->status == target_status) {
            printf("Value: %f, Timestamp: %d\n", metrics[i]->value, metrics[i]->timestamp);
        }
    }
}

double calculateAverageMetricValue(struct metric **metrics, size_t num_metrics) {
    double sum = 0.0;
    for (size_t i = 0; i < num_metrics; ++i) {
        sum += metrics[i]->value;
    }
    return sum / num_metrics;
}

void serializeMetrics(struct metric **metrics, size_t num_metrics, FILE *fp) {
    fwrite(metrics, sizeof(struct metric), num_metrics, fp);
}

struct metric *deserializeMetrics(FILE *fp, size_t *num_metrics) {
    struct metric *metrics = NULL;
    fseek(fp, 0, SEEK_END);
    size_t size = ftell(fp);
    rewind(fp);

    metrics = (struct metric *)malloc(size / sizeof(struct metric));
    fread(metrics, sizeof(struct metric), size / sizeof(struct metric), fp);

    *num_metrics = size / sizeof(struct metric);
    return metrics;
}

int main() {
    // Open file for reading and writing
    FILE *fp = fopen("metrics.txt", "r+");
    if (!fp) {
        perror("File operation failed");
        return 1;
    }

    // Initialize arrays and structures
    size_t num_metrics = 0;
    struct metric *metrics = NULL;

    processAndManageMetrics(&metrics, &num_metrics, fp);

    // Filter and print metrics with a specific status
    filterAndPrintMetrics(&metrics, num_metrics, OK);

    // Calculate the average metric value
    double average_value = calculateAverageMetricValue(&metrics, num_metrics);
    printf("Average metric value: %f\n", average_value);

    // Serialize the data structure to a file for persistence
    FILE *fp_out = fopen("persisted_metrics.txt", "wb");
    if (!fp_out) {
        perror("File operation failed");
        return 1;
    }
    serializeMetrics(&metrics, num_metrics, fp_out);
    fclose(fp_out);

    // Deserialize the data structure from a file back into memory
    FILE *fp_in = fopen("persisted_metrics.txt", "rb");
    if (!fp_in) {
        perror("File operation failed");
        return 1;
    }
    size_t num_deserialized_metrics = 0;
    struct metric *deserialized_metrics = deserializeMetrics(fp_in, &num_deserialized_metrics);
    fclose(fp_in);

    // Handle and log errors gracefully
    if (num_metrics != num_deserialized_metrics) {
        printf("Error deserializing metrics. Number of metrics mismatch.\n");
    } else {
        for (size_t i = 0; i < num_deserialized_metrics; ++i) {
            printf("Value: %f, Timestamp: %d\n", deserialized_metrics[i].value, deserialized_metrics[i].timestamp);
        }
    }

    return 0;
}

