int profileCount = 0;

void insertProfile(char* username, int age, char* email) {
    UserProfile* newProfile = (UserProfile*) malloc(sizeof(UserProfile));
    newProfile->username = strdup(username);
    newProfile->age = age;
    newProfile->email = strdup(email);

    if(profiles == NULL || profileCount >= 50000) {
        profiles = realloc(profiles, sizeof(UserProfile*) * (profileCount + 1));
    }
    profiles[profileCount++] = newProfile;
}

void deleteProfile(char* username) {
    for(int i=0; i<profileCount; i++) {
        if(strcmp(profiles[i]->username, username) == 0) {
            free(profiles[i]->username);
            free(profiles[i]->email);
            free(profiles[i]);
            for(int j=i; j<profileCount-1; j++) {
                profiles[j] = profiles[j+1];
            }
            profileCount--;
            return;
        }
    }
}

UserProfile* getProfile(char* username) {
    for(int i=0; i<profileCount; i++) {
        if(strcmp(profiles[i]->username, username) == 0) {
            return profiles[i];
        }
    }
    return NULL;
}

void releaseMemory() {
    for(int i=0; i<profileCount; i++) {
        free(profiles[i]->username);
        free(profiles[i]->email);
        free(profiles[i]);
    }
    free(profiles);
}

UserProfile* searchByUsername(char* username) {
    for(int i=0; i<profileCount; i++) {
        if(strcmp(profiles[i]->username, username) == 0) {
            return profiles[i];
        }
    }
    return NULL;
}

UserProfile* searchByEmail(char* email) {
    for(int i=0; i<profileCount; i++) {
        if(strcmp(profiles[i]->email, email) == 0) {
            return profiles[i];
        }
    }
    return NULL;
}

// External API integration
void updateProfile(char* username, int age, char* email) {
    UserProfile* profile = getProfile(username);
    if(profile != NULL) {
        profile->age = age;
        profile->email = strdup(email);
    } else {
        // Handle error
    }
}

void retryUpdate() {
    sleep(1); // exponential backoff
    updateProfile(username, age, email);
}
