#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure to store records
typedef struct {
    int key;
    double value;
    char* string;
} Record;

// Define the data structure to manage records
typedef struct {
    int size; // current number of records
    int capacity; // maximum number of records
    Record** records; // array of pointers to records
    pthread_mutex_t mutex; // mutex for thread-safe access
    int* lastAccessedKeys; // array to track last accessed indices
} Records;

// Function to initialize the data structure
Records* initRecords(int capacity) {
    Records* records = (Records*)malloc(sizeof(Records));
    records->size = 0;
    records->capacity = capacity;
    records->records = (Record**)malloc(capacity * sizeof(Record*));
    records->lastAccessedKeys = (int*)malloc(capacity * sizeof(int));
    pthread_mutex_init(&records->mutex, NULL);
    return records;
}

// Function to resize the underlying arrays
void resizeRecords(Records* records, int newCapacity) {
    Record** newRecords = (Record**)realloc(records->records, newCapacity * sizeof(Record*));
    if (!newRecords) {
        printf("Error allocating memory for records\n");
        exit(1);
    }
    records->records = newRecords;
    int* newLastAccessedKeys = (int*)realloc(records->lastAccessedKeys, newCapacity * sizeof(int));
    if (!newLastAccessedKeys) {
        printf("Error allocating memory for last accessed keys\n");
        exit(1);
    }
    records->lastAccessedKeys = newLastAccessedKeys;
}

// Function to add a record to the data structure
void addRecord(Records* records, int key, double value, char* string) {
    pthread_mutex_lock(&records->mutex);
    if (records->size >= records->capacity) {
        resizeRecords(records, records->capacity * 2 + 1);
    }
    Record* record = (Record*)malloc(sizeof(Record));
    record->key = key;
    record->value = value;
    record->string = string;
    records->records[records->size] = record;
    records->lastAccessedKeys[records->size] = -1; // mark as not accessed
    records->size++;
    pthread_mutex_unlock(&records->mutex);
}

// Function to get the last accessed index of a key
int getLastAccessedIndex(Records* records, int key) {
    for (int i = 0; i < records->size; i++) {
        if (records->lastAccessedKeys[i] == key) {
            return i;
        }
    }
    return -1; // key not found
}

// Function to serialize the data structure to a file
void serializeRecords(Records* records, FILE* file, int compress) {
    pthread_mutex_lock(&records->mutex);
    if (compress) {
        // use zlib for compression
        int err;
        uint8_t compressed[records->size * sizeof(Record)];
        size_t len = compressor_compress(records->records, compressed, &len);
        fwrite(compressed, 1, len, file);
    } else {
        fwrite(records->records, sizeof(Record*), records->size, file);
    }
    pthread_mutex_unlock(&records->mutex);
}

// Function to deserialize the data structure from a file
Records* deserializeRecords(FILE* file) {
    Records* records = initRecords(16); // initial capacity
    int size;
    fread(&size, sizeof(int), 1, file);
    for (int i = 0; i < size; i++) {
        Record* record = (Record*)malloc(sizeof(Record));
        fread(record, sizeof(Record), 1, file);
        records->records[records->size] = record;
        records->lastAccessedKeys[records->size] = -1; // mark as not accessed
        records->size++;
    }
    return records;
}

// Function to free all allocated memory when the data structure is no longer needed
void freeRecords(Records* records) {
    for (int i = 0; i < records->size; i++) {
        free(records->records[i]->string);
        free(records->records[i]);
    }
    free(records->lastAccessedKeys);
    free(records->records);
    free(records);
}

// Example usage
int main() {
    Records* records = initRecords(16);
    addRecord(records, 1, 2.0, "hello");
    addRecord(records, 2, 3.0, "world");
    // ...
    FILE* file = fopen("data.txt", "wb");
    serializeRecords(records, file, 1); // compress
    fclose(file);
    return 0;
}
