    // serialize using zlib and JSON
    z_stream stream;
    stream.zalloc = Z_NULL;
    stream.zfree = Z_NULL;
    stream.opaque = Z_NULL;

    deflateInit2(&stream, Z_DEFAULT_COMPRESSION, Z_DEFLATED, 15 | (16 << 8), 8, Z_DEFAULT_WINDOW);
    if (deflateInit2(&stream, Z_DEFAULT_COMPRESSION, Z_DEFLATED, 15 | (16 << 8), 8, Z_DEFAULT_WINDOW) != Z_OK) {
