class InterfaceManagementSystem {
public:
    std::map<std::string, std::string> metadataToUUIDMap;

    void addMetadataIPToUUIDMapping(const std::string& metadataIP, const std::string& uuid) {
        metadataToUUIDMap[metadataIP] = uuid;
    }

    std::string getUUIDFromMetadataIP(const std::string& metadataIP) {
        if (metadataToUUIDMap.find(metadataIP) != metadataToUUIDMap.end()) {
            return metadataToUUIDMap[metadataIP];
        }
        return "";
    }
