class Client {
public:
    Client(io_service& ioService, InterfaceManagementSystem& interfaceManagementSystem)
        : ioService_(ioService), interfaceManagementSystem_(interfaceManagementSystem),
          socket_(new ip::tcp::socket(ioService)) {}

    void start() {
        std::thread t([&]() { this->startAsync(); });
        t.detach();
    }

    void startAsync() {
        boost::asio::deadline_timer timer(ioService_);
        timer.expires_after(std::chrono::seconds(1));
        timer.async_wait([this](boost::system::error_code ec) {
            if (!ec) {
                sendRequest("GET", "http://example.com");
            }
        });
    }

    void sendRequest(const std::string& requestType, const std::string& url) {
        boost::asio::io_context ioContext;
        ip::tcp::socket socket(ioContext);
        boost::asio::connect(socket, ip::tcp::endpoint(ip::tcp::v4(), 80));
        boost::asio::write(socket, "GET / HTTP/1.0\r\nHost: example.com\r\n\r\n");

        boost::asio::read_until(socket, buffer_, "\r\n");
