#include <forward_list>
#include <string>
#include <mutex>
#include <fstream>

class ForwardList {
private:
    std::forward_list<std::string> list;
    std::mutex mtx;

public:
    void insertAfter(const std::forward_list<std::string>& forwardList, const std::string& target, const std::string& insert) {
        // Serialize the forward list to a file
        serialize(forwardList);

        // Locate the first occurrence of 'target' in 'forwardList'
        auto it = forwardList.srbegin();
        while (it != forwardList.sentinel()) {
            if (*it == target) {
                // Insert 'insert' immediately after 'target'
                std::unique_lock<std::mutex> lock(mtx);
                list.insert_after(it.base(), insert);
                break;
            }
            ++it;
        }

        // If 'target' is not found, append 'insert' to the end of the list
        if (it == forwardList.sentinel()) {
            list.append(insert);
        }
    }

    void serialize(const std::forward_list<std::string>& forwardList) {
        // Serialize the forward list to a file, supporting optional compression
        std::ofstream file("forward_list.bin", std::ios::binary);
        if (file.is_open()) {
            for (const auto& str : forwardList) {
                file.write(str.c_str(), str.size());
                file.put('\n');
            }
            file.close();
        }
    }

    void deserialize() {
        // Deserialize the forward list from a file
        std::ifstream file("forward_list.bin", std::ios::binary);
        if (file.is_open()) {
            std::string str;
            while (std::getline(file, str)) {
                list.insert_after(list.end(), str);
            }
            file.close();
        }
    }
};
