record *expandGraphStructure(int **keys, int **offsets, int **values, int **lastAccessedIndex) {
    // Define constants
    const int INITIAL_RECORDS = 1000;
    const int MAX_RECORDS = 10000;
    const int KEY_RANGE = 1000000;
    const int OFFSET_RANGE = 2000000;

    record *records = (record *)malloc(INITIAL_RECORDS * sizeof(record));
    if (!records) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Initialize arrays
    *keys = (int *)malloc(MAX_RECORDS * sizeof(int));
    *offsets = (long *)malloc(MAX_RECORDS * sizeof(long));
    *values = (short *)malloc(MAX_RECORDS * sizeof(short));
    *lastAccessedIndex = (int *)malloc(MAX_RECORDS * sizeof(int));

    int recordsCount = 0;
    int maxKey = 0, maxOffset = 0;

    // Read graph initialization parameters from external data source
    FILE *file = fopen("graph_params.txt", "r");
    if (!file) {
        printf("Failed to read graph initialization parameters\n");
        return NULL;
    }

    int newRecordsToAdd;
    fscanf(file, "%d", &newRecordsToAdd);
    fclose(file);

    // Add new records
    for (int i = 0; i < newRecordsToAdd; i++) {
        record newRecord;
        newRecord.key = rand() % KEY_RANGE;
        newRecord.offset = rand() % OFFSET_RANGE;
        short valueInRange = rand() % 10000;
        while (findRecord(*keys, *offsets, *values, &newRecord) != -1) {
            newRecord.key++;
            newRecord.offset++;
            valueInRange = rand() % 10000;
        }
        newRecord.value = valueInRange;

        // Update arrays
        records[recordsCount] = newRecord;
        (*keys)[recordsCount] = newRecord.key;
        (*offsets)[recordsCount] = newRecord.offset;
        (*values)[recordsCount] = newRecord.value;
        (*lastAccessedIndex)[recordsCount] = -1;

        // Check for memory growth
        if (recordsCount >= MAX_RECORDS) {
            int oldSize = INITIAL_RECORDS * sizeof(record);
            int newSize = (MAX_RECORDS + 1000) * sizeof(record);
            records = (record *)realloc(records, newSize);
            if (!records) {
                printf("Memory allocation failed\n");
                return NULL;
            }
        }

        recordsCount++;
    }

    // Update max key and offset
    for (int i = 0; i < recordsCount; i++) {
        if (maxKey < (*keys)[i]) {
            maxKey = (*keys)[i];
        }
        if (maxOffset < (*offsets)[i]) {
            maxOffset = (*offsets)[i];
        }
    }

    return &records[0];
}

int findRecord(int *keys, long *offsets, short *values, record *recordToFind) {
    for (int i = 0; i < recordsCount; i++) {
        if ((*keys)[i] == recordToFind->key && (*offsets)[i] == recordToFind->offset) {
            return i;
        }
    }
    return -1;
}
