record_t* expandGraphStructure(int numRecords) {
    // Allocate memory for arrays
    record_t* records = (record_t*)malloc(numRecords * sizeof(record_t));
    long* offsets = (long*)malloc(numRecords * sizeof(long));
    int* keys = (int*)malloc(numRecords * sizeof(int));

    // Initialize arrays
    for (int i = 0; i < numRecords; i++) {
        records[i].key = -1;
        records[i].offset = -1;
        records[i].value = 0;
    }

    int* lastAccessedIndexByKey = (int*)malloc(numRecords * sizeof(int));
    for (int i = 0; i < numRecords; i++) {
        lastAccessedIndexByKey[i] = -1;
    }

    // Dynamically resize arrays as needed
    void (*resizeArrays)(record_t**, long**, int**, int) = (void (*)(record_t**, long**, int**, int))malloc(sizeof(void(*)(record_t**, long**, int**, int)));
    *resizeArrays = &dynamicResizeArrays;

    return records;
}

void dynamicResizeArrays(record_t** records, long** offsets, int** keys, int numRecords) {
    // Resize arrays as needed
    record_t* newRecords = (record_t*)realloc(*records, (numRecords + 1000) * sizeof(record_t));
    long* newOffsets = (long*)realloc(*offsets, (numRecords + 1000) * sizeof(long));
    int* newKeys = (int*)realloc(*keys, (numRecords + 1000) * sizeof(int));

    // Update pointers
    *records = newRecords;
    *offsets = newOffsets;
    *keys = newKeys;
}

// Function to set the value of each record's int field to a random value within a given range
void setRandomValue(record_t* records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        records[i].value = rand() % 100;
    }
}

// Function to find and print the largest integer in the array
int findLargestInteger(record_t* records, int numRecords) {
    int maxVal = INT_MIN;
    for (int i = 0; i < numRecords; i++) {
        if (records[i].value > maxVal) {
            maxVal = records[i].value;
