using System;
using System.Collections.Generic;
using System.Threading;

public class NetworkEventLogEntry
{
    public DateTime Timestamp { get; set; }
    public int EventId { get; set; }
    public string Message { get; set; }
}

class LogManagementSystem
{
    private const int InitialCapacity = 1000;
    private const int ResizeFactor = 2;

    private readonly Dictionary<int, NetworkEventLogEntry[]> _eventLogs;
    private readonly object _lockObject;

    public LogManagementSystem()
    {
        _eventLogs = new Dictionary<int, NetworkEventLogEntry[]>(InitialCapacity);
        _lockObject = new object();
    }

    public void AddEventLogEntry(int eventLogId, DateTime timestamp, int eventId, string message)
    {
        lock (_lockObject)
        {
            if (!_eventLogs.TryGetValue(eventLogId, out var entries))
            {
                entries = new NetworkEventLogEntry[InitialCapacity];
                _eventLogs.Add(eventLogId, entries);
            }

            if (entries.Length == 0 || entries.Length % ResizeFactor == 0)
            {
                Array.Resize(ref entries, entries.Length * ResizeFactor);
            }

            var newEntry = new NetworkEventLogEntry { Timestamp = timestamp, EventId = eventId, Message = message };
            Array.Copy(entries, 0, entries, 1, entries.Length - 1);
            entries[0] = newEntry;
        }
    }

    public void FreeMemory()
    {
        lock (_lockObject)
        {
            foreach (var entry in _eventLogs.Values)
            {
                entry = null;
            }
            _eventLogs.Clear();
        }
    }

    public void SerializeToFile(string filename)
    {
        using var fileStream = File.Open(filename, FileMode.Create);
        using var writer = new BinaryWriter(fileStream);

        lock (_lockObject)
        {
            foreach (var entries in _eventLogs.Values)
            {
                foreach (var entry in entries)
                {
                    writer.Write(entry.Timestamp.Ticks);
                    writer.Write(entry.EventId);
                    writer.Write(entry.Message.Length);
                    writer.ReadBytes(entry.Message.ToCharArray());
                }
            }
        }
    }

    public void DeserializeFromFile(string filename)
    {
        using var fileStream = File.Open(filename, FileMode.Open);
        using var reader = new BinaryReader(fileStream);

        lock (_lockObject)
        {
            _eventLogs.Clear();

            int eventLogId;
            while ((eventLogId = reader.ReadInt32()) != -1)
            {
                NetworkEventLogEntry[] entries;
                if (!_eventLogs.TryGetValue(eventLogId, out entries))
                {
                    entries = new NetworkEventLogEntry[InitialCapacity];
                    _eventLogs.Add(eventLogId, entries);
                }

                DateTime timestamp = new DateTime(reader.ReadInt64());
                int eventId = reader.ReadInt32();
                int messageLength = reader.ReadInt32();

                var entry = new NetworkEventLogEntry { Timestamp = timestamp, EventId = eventId };
                byte[] messageBytes = reader.ReadBytes(messageLength);
                entry.Message = Encoding.UTF8.GetString(messageBytes);

                Array.Copy(entries, 0, entries, 1, entries.Length - 1);
                entries[0] = entry;
            }
        }
    }
}
