    pthread_mutex_t lock; // Lock for concurrent access
    long *offsets; // Array of long offset values
    int *keys; // Array of integer keys
    Record **records; // Array of record structures
    int *lastAccessed; // Secondary structure tracking last accessed indices
    int size; // Current size of the data structure
} DataManager;

// Function to initialize and resize the data manager
DataManager* initDataManager(int initialSize) {
    DataManager* dm = malloc(sizeof(DataManager));
    dm->size = initialSize;
    dm->offsets = malloc((dm->size + 1) * sizeof(long));
    dm->keys = malloc((dm->size + 1) * sizeof(int));
    dm->records = malloc((dm->size + 1) * sizeof(Record *));
    dm->lastAccessed = malloc((dm->size + 1) * sizeof(int));

    for (int i = 0; i <= dm->size; i++) {
        dm->offsets[i] = 0;
        dm->keys[i] = -1;
        dm->records[i] = NULL;
        dm->lastAccessed[i] = -1;
    }

    pthread_mutex_init(&dm->lock, NULL);
    return dm;
}

// Function to free the data manager
void freeDataManager(DataManager* dm) {
    free(dm->offsets);
    free(dm->keys);
    for (int i = 0; i <= dm->size; i++) {
        if (dm->records[i] != NULL)
            free(dm->records[i]);
    }
    free(dm->records);
    free(dm->lastAccessed);
    pthread_mutex_destroy(&dm->lock);
    free(dm);
}

// Function to serialize the data structure to a file
void serializeDataManager(DataManager* dm, const char* filename) {
    FILE* file = fopen(filename, "wb");

    // Write the size of the data structure
    fwrite(&dm->size, sizeof(int), 1, file);

    // Write the offsets array
    fwrite(dm->offsets, sizeof(long), dm->size + 1, file);

    // Write the keys array
    fwrite(dm->keys, sizeof(int), dm->size + 1, file);

    // Write the records array
    for (int i = 0; i <= dm->size; i++) {
        if (dm->records[i] != NULL) {
            Record* record = dm->records[i];
            fwrite(&record->value, sizeof(int), 1, file);
        }
    }

    // Write the last accessed array
    fwrite(dm->lastAccessed, sizeof(int), dm->size + 1, file);

    fclose(file);
}

// Function to deserialize the data structure from a file
DataManager* deserializeDataManager(const char* filename) {
    DataManager* dm = initDataManager(0);
    FILE* file = fopen(filename, "rb");

    // Read the size of the data structure
    fread(&dm->size, sizeof(int), 1, file);

    // Resize the arrays to match the read size
    dm->offsets = realloc(dm->offsets, (dm->size + 1) * sizeof(long));
    dm->keys = realloc(dm->keys, (dm->size + 1) * sizeof(int));
