#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_EVENTS 10000000
#define CACHE_SIZE 1000

typedef struct {
    int64_t timestamp;
    int id;
    char metadata[256];
} Event;

Event* events = NULL;
int events_size = 0;
int cache_offset = 0;
int cache_size = CACHE_SIZE;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
FILE* log_file = NULL;

void* cache = NULL;

void initialize() {
    events = (Event*)malloc(MAX_EVENTS * sizeof(Event));
}

void resize_events(int new_size) {
    Event* new_events = (Event*)realloc(events, new_size * sizeof(Event));
    if (!new_events) return;
    events = new_events;
    events_size = new_size;
}

int find_event(int id) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < cache_offset; i++) {
        if (events[i].id == id) {
            pthread_mutex_unlock(&lock);
            return i;
        }
    }
    pthread_mutex_unlock(&lock);
    return -1;
}

void insert_event(Event* event) {
    int index = find_event(event->id);
    if (index != -1) {
        // Update existing event
        memcpy(events + index, event, sizeof(Event));
    } else {
        // New event, add to cache
        pthread_mutex_lock(&lock);
        events[cache_offset++] = *event;
        if (cache_offset >= cache_size) {
            resize_events((cache_size *= 2) + 1);
        }
        pthread_mutex_unlock(&lock);
    }
}

void log_event(Event* event) {
    // Log the event
    fprintf(log_file, "%ld %d %s\n", event->timestamp, event->id, event->metadata);
}

int main() {
    initialize();

    // Open log file for writing
    log_file = fopen("event_log.txt", "w");
    if (!log_file) return 1;

    // Start threads
    pthread_t threads[100];
    for (int i = 0; i < 100; i++) {
        pthread_create(&threads[i], NULL, (void*)insert_event, NULL);
    }

    // Wait for threads to finish
    for (int i = 0; i < 100; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
