import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

import java.io.File;
import java.io.FileWriter;
import java.io.IOException;
import java.util.Arrays;

public class OrderService {

    private static final int MAX_CONCURRENT_ORDERS = 10000;
    private static final int RETRY_COUNT = 3;

    private OkHttpClient client;
    private OrderItem[] orderItems;
    private String[] keys;
    private double[] values;

    public OrderService() {
        this.client = new OkHttpClient();
        this.orderItems = new OrderItem[MAX_CONCURRENT_ORDERS];
        this.keys = new String[MAX_CONCURRENT_ORDERS];
        this.values = new double[MAX_CONCURRENT_ORDERS];

        for (int i = 0; i < MAX_CONCURRENT_ORDERS; i++) {
            orderItems[i] = new OrderItem();
            keys[i] = "order_" + i;
            values[i] = Math.random() * 100.00;
            setOrderItemFields(orderItems[i]);
        }
    }

    public void sendOrders() {
        int successfulResponses = 0;
        int networkDelays = 0;

        for (int i = 0; i < MAX_CONCURRENT_ORDERS; i++) {
            Request request = new Request.Builder()
                    .url("https://example.com/orders")
                    .post(new okhttp3.RequestBody.Companion.asRequestBody(JsonObject.create().put("orders", orderItems).toString()))
                    .build();

            try (Response response = client.newCall(request).execute()) {
                if (!response.isSuccessful()) {
                    networkDelays++;
                    retryRequest(request);
                } else {
                    successfulResponses++;
                }
            } catch (IOException e) {
                networkDelays++;
                retryRequest(request);
            }
        }

        logMetrics(successfulResponses, networkDelays);
    }

    private void setOrderItemFields(OrderItem orderItem) {
        orderItem.setItemId(Math.random() * 1000);
        orderItem.setQuantity((int) (Math.random() * 10));
        orderItem.setPrice(Math.random() * 50.00);
    }

    private void retryRequest(Request request) {
        for (int i = 0; i < RETRY_COUNT; i++) {
            try (Response response = client.newCall(request).execute()) {
                if (response.isSuccessful()) {
                    return;
                }
            } catch (IOException e) {
                // ignore
            }

            if (i == RETRY_COUNT - 1) {
                // log failure and graceful exit
            }
        }
    }

    private void logMetrics(int successfulResponses, int networkDelays) {
        try (FileWriter writer = new FileWriter(new File("metrics.log"), true)) {
            writer.write(String.format("Successful responses: %d\n", successfulResponses));
            writer.write(String.format("Network delays: %d\n", networkDelays));
            writer.write("\n");
        } catch (IOException e) {
            // ignore
        }
    }

    public static class OrderItem {
        private int itemId;
        private int quantity;
        private double price;

        public void setItemId(int itemId) {
            this.itemId = itemId;
        }

        public void setQuantity(int quantity) {
            this.quantity = quantity;
        }

        public void setPrice(double price) {
            this.price = price;
        }
    }
}

