// Function to manage memory allocation and initialization
long* manage_memory(int n, int hash_table_size, int min_val, int max_val, size_t memory_budget) {
    // Initialize random number generator with a seedable value
    srand(time(NULL));

    // Calculate the total required memory for arrays
    size_t total_required_memory = sizeof(long) * n + sizeof(int) * n;

    // Check if total required memory exceeds budget
    if (total_required_memory > memory_budget) {
        // Reduce data structure sizes to fit within budget
        n = (int) ((double) memory_budget / (sizeof(long) + sizeof(int))) - 1;
        printf("Reduced size of data structures due to memory constraints.\n");
    }

    // Allocate memory for offset values and keys
    long* offsets = (long*)malloc(n * sizeof(long));
    int* keys = (int*)malloc(n * sizeof(int));

    if (!offsets || !keys) {
        printf("Memory allocation failed. Exiting.\n");
        return NULL;
    }

    // Initialize offset values with random numbers within range
    for (int i = 0; i < n; i++) {
        offsets[i] = rand() % (max_val - min_val + 1) + min_val;
    }

    // Check if hash table size is a prime number and a power of two
    if (!is_prime(hash_table_size) || !is_power_of_two(hash_table_size)) {
        printf("Hash table size must be a prime number and a power of two. Adjusting...\n");
        hash_table_size = find_next_prime(get_next_power_of_two());
    }

    // Allocate memory for hash table
    int** records = (int**)malloc(hash_table_size * sizeof(int*));

    if (!records) {
        printf("Memory allocation failed. Exiting.\n");
        return NULL;
    }

    // Initialize hash table with random key values and set offset to the value of the key
    for (int i = 0; i < hash_table_size; i++) {
        records[i] = (int*)malloc(sizeof(int));
        if (!records[i]) {
            printf("Memory allocation failed. Exiting.\n");
            return NULL;
        }
        *records[i] = rand() % (max_val - min_val + 1) + min_val;
    }

    // Return pointer to array of records
    return offsets;
}

// Helper function to check if a number is prime
int is_prime(int num) {
    if (num <= 1)
        return 0;
    for (int i = 2; i * i <= num; i++)
        if (num % i == 0)
            return 0;
    return 1;
}

// Helper function to find the next prime number
int find_next_prime(int num) {
    while (!is_prime(num))
        num++;
    return num;
}

// Helper function to check if a number is a power of two
int is_power_of_two(int num) {
    return (num & (num - 1)) == 0;
}

// Helper function to find the next power of two
int get_next_power_of_two() {
    int num = 2;
    while (!is_power_of_two(num))
        num *= 2;
    return num;
}
