// Define the metric structure
typedef struct {
    double value;
    int timestamp;
    enum { OK, WARNING, ERROR } status;
} Metric;

// Function to process and manage metrics
void processAndManageMetrics() {
    // Initialize arrays for timestamps, values, and metrics
    int* timestamps = NULL;
    double* values = NULL;
    Metric** metrics = NULL;

    // Initialize last accessed index of each timestamp
    int* lastAccessedIndices = NULL;

    // Read list of numerical values and timestamps from standard input
    int numMetrics = 0;
    printf("Enter the number of metrics: ");
    scanf("%d", &numMetrics);

    // Allocate memory for arrays
    timestamps = (int*)malloc(numMetrics * sizeof(int));
    values = (double*)malloc(numMetrics * sizeof(double));
    metrics = (Metric**)malloc(numMetrics * sizeof(Metric*));
    lastAccessedIndices = (int*)malloc(numMetrics * sizeof(int));

    // Initialize arrays and last accessed indices
    for (int i = 0; i < numMetrics; i++) {
        scanf("%d %lf", &timestamps[i], &values[i]);
        metrics[i] = (Metric*)malloc(sizeof(Metric));
        metrics[i]->timestamp = timestamps[i];
        metrics[i]->value = values[i];
        metrics[i]->status = OK;
        lastAccessedIndices[i] = i;
    }

    // Implement concurrency-safe mechanisms
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Function to add new metrics
    void addMetric(int timestamp, double value) {
        pthread_mutex_lock(&mutex);
        // Check if the metric already exists
        for (int i = 0; i < numMetrics; i++) {
            if (metrics[i]->timestamp == timestamp) {
                free(metrics[i]);
                metrics[i] = (Metric*)malloc(sizeof(Metric));
                metrics[i]->timestamp = timestamp;
                metrics[i]->value = value;
                metrics[i]->status = OK;
                lastAccessedIndices[i] = i;
                break;
            }
        }

        // If the metric does not exist, add it
        if (i == numMetrics) {
            numMetrics++;
            timestamps = (int*)realloc(timestamps, numMetrics * sizeof(int));
            values = (double*)realloc(values, numMetrics * sizeof(double));
            metrics = (Metric**)realloc(metrics, numMetrics * sizeof(Metric*));
            lastAccessedIndices = (int*)realloc(lastAccessedIndices, numMetrics * sizeof(int));

            timestamps[numMetrics - 1] = timestamp;
            values[numMetrics - 1] = value;
            metrics[numMetrics - 1] = (Metric*)malloc(sizeof(Metric));
            metrics[numMetrics - 1]->timestamp = timestamp;
            metrics[numMetrics - 1]->value = value;
            metrics[numMetrics - 1]->status = OK;
            lastAccessedIndices[numMetrics - 1] = i;
        }

        pthread_mutex_unlock(&mutex);
    }

    // Function to filter and print metrics with a status of "ERROR"
    void printErrorMetrics() {
        pthread_mutex_lock(&mutex);

        for (int i = 0; i < numMetrics; i++) {
            if (metrics[i]->status == ERROR) {
                printf("Metric %d: Timestamp = %d, Value = %.2lf, Status = %s\n", i, metrics[i]->timestamp, metrics[i]->value, "ERROR");
            }
        }

        pthread_mutex_unlock(&mutex);
    }

    // Function to calculate the average metric value
    double calculateAverageValue() {
        double sum = 0.0;
        int count = 0;

        pthread_mutex_lock(&mutex);

        for (int i = 0; i < numMetrics; i++) {
            sum += metrics[i]->value;
            count++;
        }

        pthread_mutex_unlock(&mutex);

        return sum / count;
    }
}

// Function to serialize the data structure to a file
void serializeDataStructure() {
    FILE* file = fopen("metrics.bin", "wb");

    if (file != NULL) {
        fwrite(&numMetrics, sizeof(int), 1, file);
        for (int i = 0; i < numMetrics; i++) {
            fwrite(&timestamps[i], sizeof(int), 1, file);
            fwrite(&values[i], sizeof(double), 1, file);
            fwrite(&metrics[i]->timestamp, sizeof(int), 1, file);
            fwrite(&metrics[i]->value, sizeof(double), 1, file);
            fwrite(&metrics[i]->status, sizeof(enum { OK, WARNING, ERROR }), 1, file);
        }

        fclose(file);
    }
}

// Function to deserialize the data structure from a file
void deserializeDataStructure() {
    FILE* file = fopen("metrics.bin", "rb");

    if (file != NULL) {
        fread(&numMetrics, sizeof(int), 1, file);

        for (int i = 0; i < numMetrics; i++) {
            timestamps[i] = (int)fread(&timestamps[i], sizeof(int), 1, file);
            values[i] = (double)fread(&values[i], sizeof(double), 1, file);
            metrics[i]->timestamp = (int)fread(&metrics[i]->timestamp, sizeof(int), 1, file);
            metrics[i]->value = (double)fread(&metrics[i]->value, sizeof(double), 1, file);
            metrics[i]->status = (enum { OK, WARNING, ERROR })fread(&metrics[i]->status, sizeof(enum { OK, WARNING, ERROR }), 1, file);
        }

        fclose(file);
    }
}

int main() {
    processAndManageMetrics();
    serializeDataStructure();

    // Deserialize the data structure and perform operations
    deserializeDataStructure();
    printErrorMetrics();
    printf("Average metric value: %.2lf\n", calculateAverageValue());

    return 0;
}
