            for (int j = 0; j < numMetrics; j++) {
                if (lastAccessed[j] != -1 && lastAccessed[j] > newTimestamp) {
                    newTimestamp = lastAccessed[j];
                }
            }
            newTimestamp++;
        }

        // Update the timestamp and value in the metric
        for (int j = 0; j < numMetrics; j++) {
            if (metrics[j].timestamp == -1 || metrics[j].timestamp > newTimestamp) {
                metrics[j].timestamp = newTimestamp;
                metrics[j].value = value;
                lastAccessed[j] = timestamp;
                break;
            }
        }

        // Write the metric to file
        fprintf(file, "%lf %d %s\n", value, newTimestamp, (newTimestamp == -1) ? "ERROR" : "OK");
    }

    fclose(file);
}

int main() {
