// Define the 'record' structure
typedef struct {
    int key;
    long offset;
    short value;
} record;

// Function to expand graph structure dynamically
void expandGraphStructure(int** records, int* numRecords, int maxCapacity) {
    // Calculate new capacity based on current size and desired growth factor
    int newCapacity = *numRecords + (*numRecords / 2);
    if (newCapacity > maxCapacity) newCapacity = maxCapacity;

    // Resize arrays and record structures
    *records = realloc(*records, sizeof(record) * newCapacity);
    int* keys = realloc((int*)malloc(sizeof(int) * newCapacity), sizeof(int));
    long* offsets = realloc((long*)malloc(sizeof(long) * newCapacity), sizeof(long));

    // Initialize secondary structure for tracking last accessed index
    int* keyIndexTracker = (int*)calloc(newCapacity, sizeof(int));

    // Copy data from original arrays to resized arrays
    for (int i = 0; i < *numRecords; i++) {
        keys[i] = records[i]->key;
        offsets[i] = records[i]->offset;
        keyIndexTracker[records[i]->key] = i;
    }

    // Set the new capacity and free previous memory
    *numRecords = newCapacity;
    free(records);
}

