    int size;
    int capacity;
} DynamicStringList;

DynamicStringList* init_string_list() {
    DynamicStringList* list = (DynamicStringList*)malloc(sizeof(DynamicStringList));
    list->size = 0;
    list->capacity = INITIAL_LIST_SIZE;
    list->strings = (char**)calloc(list->capacity, sizeof(char*));
    return list;
}

void add_string_to_list(DynamicStringList* list, char* string) {
    if (list->size == list->capacity) {
        int new_capacity = list->capacity * 2;
        list->strings = (char**)realloc(list->strings, new_capacity * sizeof(char*));
        list->capacity = new_capacity;
    }
    list->strings[list->size] = string;
    list->size++;
}

void remove_string_from_list(DynamicStringList* list) {
    if (list->size > 0) {
        int i;
        for (i = 0; i < list->size - 1; i++) {
            list->strings[i] = list->strings[i + 1];
        }
        free(list->strings[list->size]);
        list->size--;
    }
}

char* get_string_from_list(DynamicStringList* list, int index) {
    if (index >= 0 && index < list->size)
        return list->strings[index];
    else
        return NULL;
}

void log_memory_usage() {
    // logging mechanism to track memory usage dynamically during runtime
}

void *string_list_thread_func(void *arg) {
    DynamicStringList* list = (DynamicStringList*)arg;

    // thread-safe operations for concurrent read and write access

    pthread_exit(NULL);
}

void start_string_list_threads(DynamicStringList* list, int num_threads) {
    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; i++) {
        pthread_create(&threads[i], NULL, string_list_thread_func, list);
    }
}

char* get_longest_string_in_list(DynamicStringList* list) {
    int max_length = 0;
    char* longest_string = NULL;

    for (int i = 0; i < list->size; i++) {
        if (strlen(list->strings[i]) > max_length) {
            max_length = strlen(list->strings[i]);
            longest_string = list->strings[i];
        }
    }

    return longest_string;
}

void free_string_list(DynamicStringList* list) {
    for (int i = 0; i < list->size; i++) {
        free(list->strings[i]);
    }
    free(list->strings);
    free(list);
}
