typedef enum {
    OK,
    WARNING,
    ERROR
} status_t;

typedef struct {
    double value;
    int timestamp;
    status_t status;
} metric_t;

metric_t* processAndManageMetrics(int* metricsCount, size_t** metricsBuffer, FILE* input) {
    // Initialize the data structures
    *metricsBuffer = (size_t*)malloc(1000 * sizeof(size_t));
    *metricsBuffer[0] = 1; // Initial capacity

    metric_t** metricsArray = (metric_t**)malloc(*metricsBuffer[0] * sizeof(metric_t*));
    for (int i = 0; i < *metricsBuffer[0]; i++) {
        metricsArray[i] = (metric_t*)malloc(sizeof(metric_t));
    }

    int lastTimestamp = -1;
    for (int i = 0; i < *metricsCount; i++) {
        double value;
        int timestamp;
        status_t status;

        // Read from standard input
        fscanf(input, "%lf %d %d", &value, &timestamp, &status);

        if (timestamp > lastTimestamp) {
            // Allocate new memory if necessary
            size_t newSize = *metricsBuffer[0] + 100;
            *metricsBuffer = (size_t*)realloc(*metricsBuffer, newSize * sizeof(size_t));
            for (int j = *metricsBuffer[0]; j < newSize; j++) {
                metricsArray[j] = (metric_t*)malloc(sizeof(metric_t));
            }
            lastTimestamp = timestamp;
        }

        // Update the metric structure
        metricsArray[*metricsCount]->value = value;
        metricsArray[*metricsCount]->timestamp = timestamp;
        metricsArray[*metricsCount]->status = status;

        (*metricsCount)++;

        if (*metricsCount >= *metricsBuffer[0] - 10) {
            size_t newSize = *metricsBuffer[0] + 100;
            *metricsBuffer = (size_t*)realloc(*metricsBuffer, newSize * sizeof(size_t));
            for (int j = *metricsBuffer[0]; j < newSize; j++) {
                metricsArray[j] = (metric_t*)malloc(sizeof(metric_t));
            }
        }
    }

    return metricsArray;
}

// Filter and print metrics with a status of "ERROR"
void filterErrorMetrics(metric_t** metrics, int count) {
    for (int i = 0; i < count; i++) {
        if (metrics[i]->status == ERROR) {
            printf("Error metric: timestamp %d, value %.2lf\n", metrics[i]->timestamp, metrics[i]->value);
        }
    }
}

// Calculate the average metric value
double calculateAverageMetric(metric_t** metrics, int count) {
    double sum = 0.0;
    for (int i = 0; i < count; i++) {
        sum += metrics[i]->value;
    }
    return sum / count;
}
