    for(int i = 0; i < max_transactions; i++) {
        transactions[i].transaction_id = i;
        transactions[i].amount = (double) rand() / RAND_MAX;

        // Set initial status to "pending"
        strcpy(transactions[i].status, "pending");
    }

    return transactions;
}

// Define the function to validate and update transaction status
int validateTransactionStatus(void* transactions, int transaction_id, char new_status[]) {
    Transaction *transaction = (Transaction*) transactions;

    // Check if the transaction exists in the log
    if(transaction_id < max_transactions) {
        strcpy(transaction[transaction_id].status, new_status);

        return 0;  // Successful update
    } else {
        return -1;  // Transaction not found
    }
}

// Define the function to serialize transaction data structure to a file
void serializeTransactions(void* transactions, const char* filename) {
    FILE *fp = fopen(filename, "wb");

    if(fp != NULL) {
        fwrite(transactions, sizeof(Transaction), max_transactions, fp);

        fclose(fp);
    } else {
        printf("Error writing to file: %s\n", filename);
    }
}

// Define the function to deserialize transaction data structure from a file
void* deserializeTransactions(const char* filename) {
    FILE *fp = fopen(filename, "rb");

    if(fp != NULL) {
        Transaction *transactions;

        // Dynamically allocate memory for transactions array
        int max_transactions = fread(&transactions, sizeof(Transaction), 1, fp);

        fclose(fp);

        return transactions;
    } else {
        printf("Error reading from file: %s\n", filename);

        return NULL;  // Error
    }
}

int main() {
    int max_transactions = 10000000;

    void* transactions = manageTransactionStream(max_transactions);

    // Simulate high-load period and validate transaction status updates
    for(int i = 0; i < max_transactions; i++) {
        char new_status[10];

        strcpy(new_status, "completed");

        int result = validateTransactionStatus(transactions, i, new_status);

        if(result == -1) {
            printf("Error updating transaction status: %d\n", i);
        }
    }

    // Serialize the transactions array to a file
    serializeTransactions(transactions, "transactions.dat");

    free(transactions);  // Free memory

    return 0;
}

