typedef enum {
    OK,
    WARNING,
    ERROR
} metric_status;

struct metric {
    double value;
    int timestamp;
    metric_status status;
};

void processAndManageMetrics(int num_metrics) {
    struct metric* metrics = NULL;
    int* timestamps = NULL;
    double* values = NULL;
    size_t capacity = 10; // Initial capacity
    int last_timestamp = -1;

    // Allocate initial memory for arrays
    metrics = (struct metric*) malloc(capacity * sizeof(struct metric));
    timestamps = (int*) malloc(capacity * sizeof(int));
    values = (double*) malloc(capacity * sizeof(double));

    if (!metrics || !timestamps || !values) {
        printf("Error: Memory allocation failed.\n");
        return;
    }

    // Initialize last_timestamp
    for (int i = 0; i < capacity; i++) {
        timestamps[i] = -1;
        last_timestamp = i;
    }

    while (num_metrics > 0) {
        int new_timestamps = 0;
        double value;
        metric_status status;

        // Read data from standard input
        printf("Enter metric value, timestamp, and status: ");
        scanf("%lf %d %d", &value, &status);
        if (feof(stdin)) {
            break; // Exit on end-of-file
        }

        // Check for duplicate timestamps
        int found = 0;
        for (int i = 0; i < capacity; i++) {
            if (timestamps[i] == status) {
                printf("Error: Duplicate timestamp detected.\n");
                found = 1;
                break;
            }
        }

        if (!found) {
            // Allocate new memory block
            size_t new_capacity = capacity + capacity / 2; // Resize with a growth factor of 0.5
            metrics = (struct metric*) realloc(metrics, new_capacity * sizeof(struct metric));
            timestamps = (int*) realloc(timestamps, new_capacity * sizeof(int));
            values = (double*) realloc(values, new_capacity * sizeof(double));

            if (!metrics || !timestamps || !values) {
                printf("Error: Memory reallocation failed.\n");
                return;
            }

            // Update last_timestamp and add new metric
            last_timestamp++;
            timestamps[last_timestamp] = status;
            metrics[last_timestamp].value = value;
            metrics[last_timestamp].timestamp = status;
            metrics[last_timestamp].status = status;

            num_metrics--;
        }
    }

    // Serialize data structure to file
    FILE* file = fopen("metrics.bin", "wb");
    if (file) {
        fwrite(metrics, sizeof(struct metric), last_timestamp + 1, file);
        fclose(file);
    } else {
        printf("Error: Unable to write to file.\n");
    }

    // Deserialize data structure from file
    file = fopen("metrics.bin", "rb");
    if (file) {
        int deserialized_last_timestamp;
        fread(&deserialized_last_timestamp, sizeof(int), 1, file);
        for (int i = 0; i <= deserialized_last_timestamp; i++) {
            printf("Metric %d: Value = %.2lf, Timestamp = %d, Status = %s\n",
                   i, metrics[i].value, metrics[i].timestamp,
                   (metrics[i].status == OK ? "OK" : metrics[i].status == WARNING ? "WARNING" : "ERROR"));
        }
        fclose(file);
    } else {
        printf("Error: Unable to read from file.\n");
    }

    // Filter and print metrics with status ERROR
    for (int i = 0; i <= last_timestamp; i++) {
        if (metrics[i].status == ERROR) {
            printf("Metric %d: Error\n", i);
        }
    }

    // Calculate average metric value
    double sum = 0.0;
    int count = 0;
    for (int i = 0; i <= last_timestamp; i++) {
        sum += metrics[i].value;
        count++;
    }
    printf("Average metric value: %.2lf\n", sum / count);

    // Clean up
    free(metrics);
    free(timestamps);
    free(values);
}
