// Define a struct to represent an item in the resource bundle
typedef struct {
    int key;
    int integerField;
} Item;

// Define a structure to represent the resource bundle
typedef struct {
    int itemCount;
    Item* items;
} ResourceBundle;

// Function to load a resource bundle from a file
int loadResourceBundle(const char* filePath, ResourceBundle** bundlePtr) {
    // Open the file and read its contents
    FILE* file = fopen(filePath, "rb");
    if (!file) {
        return -1;  // Error opening the file
    }

    // Read the number of items in the bundle from the file
    int itemCount;
    fread(&itemCount, sizeof(int), 1, file);

    // Allocate memory for the item array and read the items from the file
    *bundlePtr = (ResourceBundle*)malloc(sizeof(ResourceBundle));
    (*bundlePtr)->items = (Item*)malloc(itemCount * sizeof(Item));
    fread((*bundlePtr)->items, sizeof(Item), itemCount, file);

    fclose(file);
    return 0;  // Success
}

// Function to add a new item to the resource bundle
int addItem(ResourceBundle* bundle) {
    // Create a new item with a random integer value
    Item* newItem = (Item*)malloc(sizeof(Item));
    newItem->key = rand();
    newItem->integerField = rand() % 100;  // Random integer field value

    // Add the new item to the bundle
    bundle->itemCount++;
    if (bundle->items == NULL) {
        bundle->items = (Item*)malloc(bundle->itemCount * sizeof(Item));
    } else {
        Item* oldItems = bundle->items;
        bundle->items = (Item*)realloc(bundle->items, bundle->itemCount * sizeof(Item));
        memcpy(&bundle->items[bundle->itemCount - 1], newItem, sizeof(Item));
        free(oldItems);
    }

    return 0;  // Success
}

// Function to serialize the resource bundle to a file
int serializeResourceBundle(const ResourceBundle* bundle, const char* filePath) {
    // Open the file and write its contents
    FILE* file = fopen(filePath, "wb");
    if (!file) {
        return -1;  // Error opening the file
    }

    // Write the number of items in the bundle to the file
    fwrite(&bundle->itemCount, sizeof(int), 1, file);

    // Write the items from the bundle to the file
    fwrite(bundle->items, sizeof(Item), bundle->itemCount, file);

    fclose(file);
    return 0;  // Success
}

// Function to deserialize a resource bundle from a file
int deserializeResourceBundle(ResourceBundle** bundlePtr, const char* filePath) {
    // Open the file and read its contents
    FILE* file = fopen(filePath, "rb");
    if (!file) {
        return -1;  // Error opening the file
    }

    // Read the number of items in the bundle from the file
    int itemCount;
    fread(&itemCount, sizeof(int), 1, file);

    // Allocate memory for the item array and read the items from the file
    *bundlePtr = (ResourceBundle*)malloc(sizeof(ResourceBundle));
    (*bundlePtr)->items = (Item*)malloc(itemCount * sizeof(Item));
    fread((*bundlePtr)->items, sizeof(Item), itemCount, file);

    fclose(file);
    return 0;  // Success
}

// Function to free all allocated memory when the data structure is no longer needed
void freeResourceBundle(ResourceBundle* bundle) {
    if (bundle->items != NULL) {
        free(bundle->items);
    }
    free(bundle);
}
