#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the maximum number of sessions (1 million)
#define MAX_SESSIONS 1000000

// Define the session data structure
typedef struct {
    char* id;
    time_t expiration;
    time_t last_activity;
} Session;

// Define the session storage structure
typedef struct {
    int size; // Current number of sessions
    int capacity; // Maximum allowed sessions
    Session** sessions; // Array to store sessions
    int next_id; // Unique ID for new sessions
} SessionStorage;

// Function to initialize session storage
SessionStorage* init_session_storage(int initial_capacity) {
    SessionStorage* storage = (SessionStorage*) malloc(sizeof(SessionStorage));
    storage->size = 0;
    storage->capacity = initial_capacity;
    storage->sessions = (Session**)malloc(storage->capacity * sizeof(Session*));
    storage->next_id = 1; // Start with ID 1
    return storage;
}

// Function to add a new session
int add_session(SessionStorage* storage, const char* id, time_t expiration) {
    if (storage->size >= storage->capacity) {
        // Resize the array if it's full
        storage->capacity *= 2; // Double the capacity
        storage->sessions = (Session**)realloc(storage->sessions, storage->capacity * sizeof(Session*));
    }

    Session* session = (Session*)malloc(sizeof(Session));
    session->id = strdup(id);
    session->expiration = expiration;
    session->last_activity = time(NULL); // Set initial last activity timestamp

    // Add the new session to the storage
    storage->sessions[storage->size] = session;
    storage->size++;

    return 0; // Success
}

// Function to remove a session by ID
int remove_session(SessionStorage* storage, const char* id) {
    for (int i = 0; i < storage->size; i++) {
        if (strcmp(storage->sessions[i]->id, id) == 0) {
            // Remove the matching session
            free(storage->sessions[i]->id);
            free(storage->sessions[i]);
            memmove(&storage->sessions[i], &storage->sessions[i+1], (storage->size - i - 1) * sizeof(Session*));
            storage->size--;
            return 0; // Success
        }
    }

    return -1; // Session not found
}

// Function to update a session's expiration timestamp
int update_session_expiration(SessionStorage* storage, const char* id, time_t new_expiration) {
    for (int i = 0; i < storage->size; i++) {
        if (strcmp(storage->sessions[i]->id, id) == 0) {
            // Update the expiration timestamp
            storage->sessions[i]->expiration = new_expiration;
            return 0; // Success
        }
    }

    return -1; // Session not found
}

// Function to get a session by ID
Session* get_session(SessionStorage* storage, const char* id) {
    for (int i = 0; i < storage->size; i++) {
        if (strcmp(storage->sessions[i]->id, id) == 0) {
            return storage->sessions[i];
        }
    }

    return NULL; // Session not found
}

// Function to free all allocated memory when the session data structure is no longer needed
void free_session_storage(SessionStorage* storage) {
    for (int i = 0; i < storage->size; i++) {
        free(storage->sessions[i]->id);
        free(storage->sessions[i]);
    }

    free(storage->sessions);
    free(storage);
}
