#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

typedef struct {
    int key;
    int value;
} ResourceItem;

ResourceItem* load_resource_bundle(const char* path) {
    // Load the bundle from file
    int fd = open(path, O_RDONLY);
    if (fd == -1) return NULL;

    size_t bundle_size = 1024; // Initial buffer size
    void* bundle_ptr = malloc(bundle_size);

    // Read and parse the bundle
    off_t offset = lseek(fd, 0, SEEK_END);
    lseek(fd, 0, SEEK_SET);
    size_t read_bytes = read(fd, bundle_ptr, bundle_size);
    close(fd);

    // Initialize the resource bundle
    ResourceItem* bundle = (ResourceItem*)bundle_ptr;
    int item_count = 0;

    // Parse and initialize items in the bundle
    for (size_t i = 0; i < read_bytes / sizeof(ResourceItem); i++) {
        ResourceItem* item = &bundle[i];
        item->key = *(int*)(((char*)bundle + i * sizeof(ResourceItem)) + offsetof(struct, key));
        item->value = rand() % 100; // Random value within range
        item_count++;
    }

    free(bundle_ptr);

    return bundle;
}
