#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Define the structure for a dynamic resource bundle item
typedef struct {
    int key;
    int value;
} ResourceItem;

// Define the dynamic resource bundle
typedef struct {
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    ResourceItem* items;
    size_t* memoryPool;
    size_t memoryPoolSize;
} ResourceBundle;

// Function to initialize a new ResourceBundle instance
ResourceBundle* resourceBundleInit(size_t capacity) {
    ResourceBundle* bundle = (ResourceBundle*)malloc(sizeof(ResourceBundle));
    bundle->capacity = capacity;
    bundle->size = 0;
    pthread_mutex_init(&bundle->lock, NULL);
    bundle->items = (ResourceItem*)calloc(capacity, sizeof(ResourceItem));
    bundle->memoryPoolSize = capacity * sizeof(ResourceItem);
    bundle->memoryPool = (size_t*)malloc(bundle->memoryPoolSize);
    return bundle;
}

// Function to add a new item to the ResourceBundle
void resourceBundleAdd(ResourceBundle* bundle, int key, int value) {
    pthread_mutex_lock(&bundle->lock);

    // Check if the bundle needs to be resized
    if (bundle->size == bundle->capacity) {
        size_t newSize = bundle->capacity * 2;
        ResourceItem* newItems = (ResourceItem*)realloc(bundle->items, newSize * sizeof(ResourceItem));
        bundle->memoryPoolSize = newSize * sizeof(ResourceItem);
        bundle->memoryPool = (size_t*)realloc(bundle->memoryPool, bundle->memoryPoolSize);
        bundle->capacity = newSize;
    }

    // Add the new item
    ResourceItem* item = (ResourceItem*)malloc(sizeof(ResourceItem));
    item->key = key;
    item->value = value;
    size_t index = bundle->size++;
    memcpy(&bundle->items[index], item, sizeof(ResourceItem));
    free(item);

    pthread_mutex_unlock(&bundle->lock);
}

// Function to serialize the ResourceBundle
void resourceBundleSerialize(const ResourceBundle* bundle, FILE* file) {
    // Write the capacity and size of the bundle
    fwrite(&bundle->capacity, sizeof(size_t), 1, file);
    fwrite(&bundle->size, sizeof(size_t), 1, file);

    // Write each item in the bundle
    for (size_t i = 0; i < bundle->size; i++) {
        ResourceItem* item = &bundle->items[i];
        fwrite(&item->key, sizeof(int), 1, file);
        fwrite(&item->value, sizeof(int), 1, file);
    }
}

// Function to deserialize the ResourceBundle
ResourceBundle* resourceBundleDeserialize(FILE* file) {
    size_t capacity;
    size_t size;

    // Read the capacity and size of the bundle
    fread(&capacity, sizeof(size_t), 1, file);
    fread(&size, sizeof(size_t), 1, file);

    // Allocate memory for the bundle
    ResourceBundle* bundle = (ResourceBundle*)malloc(sizeof(ResourceBundle));
    bundle->capacity = capacity;
    bundle->size = size;
    pthread_mutex_init(&bundle->lock, NULL);
    bundle->items = (ResourceItem*)calloc(capacity, sizeof(ResourceItem));

    // Read each item in the bundle
    for (size_t i = 0; i < size; i++) {
        ResourceItem* item = &bundle->items[i];
        fread(&item->key, sizeof(int), 1, file);
        fread(&item->value, sizeof(int), 1, file);
    }

    return bundle;
}

// Function to query the ResourceBundle content
void resourceBundleQuery(const ResourceBundle* bundle) {
    // Print each item in the bundle
    for (size_t i = 0; i < bundle->size; i++) {
        ResourceItem* item = &bundle->items[i];
        printf("Key: %d, Value: %d\n", item->key, item->value);
    }
}

int main() {
    // Initialize the ResourceBundle
    ResourceBundle* bundle = resourceBundleInit(100);

    // Add some items to the ResourceBundle
    for (size_t i = 0; i < 50000; i++) {
        int key = rand() % 100000;
        int value = rand() % 100000;
        resourceBundleAdd(bundle, key, value);
    }

    // Serialize the ResourceBundle
    FILE* file = fopen("resource_bundle.bin", "wb");
    resourceBundleSerialize(bundle, file);
    fclose(file);

    // Deserialize the ResourceBundle
    FILE* file2 = fopen("resource_bundle.bin", "rb");
    ResourceBundle* bundle2 = resourceBundleDeserialize(file2);
    fclose(file2);

    // Query the ResourceBundle content
    printf("Resource Bundle Content:\n");
    resourceBundleQuery(bundle2);

    return 0;
}
