#include <stdio.h>
#include <stdlib.h>
#include <math.h>

typedef struct Record {
    long timestamp;
    float measurement;
    struct Record* next;
} Record;

Record* insert(Record** head, long timestamp, float measurement) {
    Record* new_node = (Record*)malloc(sizeof(Record));
    new_node->timestamp = timestamp;
    new_node->measurement = measurement;
    new_node->next = *head;
    if (*head == NULL || timestamp < (*head)->timestamp) {
        *head = new_node;
    } else {
        Record* current = *head;
        while (current->next && current->next->timestamp <= timestamp)
            current = current->next;
        new_node->next = current->next;
        current->next = new_node;
    }
    return *head;
}

Record* delete(Record** head, long timestamp) {
    if (!*head || (*head)->timestamp != timestamp)
        return *head;

    Record* temp = *head;
    *head = (*head)->next;
    free(temp);
    return *head;
}

void verify_sorted_order(Record* head) {
    Record* current = head;
    float prev_measurement = 0.0f;
    long prev_timestamp = 0L;

    while (current) {
        if (current->timestamp <= prev_timestamp || 
            fmod(current->measurement, prev_measurement) < 1e-5) {
            printf("Linked list not sorted!\n");
            exit(EXIT_FAILURE);
        }
        prev_timestamp = current->timestamp;
        prev_measurement = current->measurement;
        current = current->next;
    }
}

void update_measurements(Record* head) {
    Record* current = head;

    while (current) {
        current->measurement += sin(current->timestamp * M_PI / 180.0f);
        current = current->next;
    }
}

Record* init(int num_elements, int min_timestamp, int max_timestamp) {
    Record* head = NULL;
    Record** records = (Record**)malloc((num_elements + 1)*sizeof(Record*));
    for (int i = 0; i <= num_elements; i++) {
        records[i] = NULL;

        for (int j = 0; j < 2; j++) {
            if (j == 0) {
                Record* long_offsets = (Record*)malloc((num_elements + 1)*sizeof(Record));
                for (int k = 0; k <= num_elements; k++) {
                    long_offsets[k].timestamp = min_timestamp + rand() % (max_timestamp - min_timestamp);
                    if (j == 0) {
                        records[i] = &long_offsets[k];
                    }
                }
            } else {
                Record* int_keys = (Record*)malloc((num_elements + 1)*sizeof(Record));
                for (int k = 0; k <= num_elements; k++) {
                    int_keys[k].timestamp = min_timestamp + rand() % (max_timestamp - min_timestamp);
                    if (j == 1) {
                        records[i] = &int_keys[k];
                    }
                }
            }
        }
    }

    for (int i = 0; i <= num_elements; i++) {
        Record* current = *records[i];

        while (current) {
            head = insert(&head, current->timestamp, sin(current->timestamp * M_PI / 180.0f));
            current = current->next;
        }
    }

    free(records);

    verify_sorted_order(head);
    update_measurements(head);

    return head;
}

int main() {
    int num_elements = 10;
    int min_timestamp = 0;
    int max_timestamp = 100;

    Record* head = init(num_elements, min_timestamp, max_timestamp);

    printf("Linked list initialized!\n");

    return 0;
}
