// Function to initialize the KVS data structure
kvs_t* kvs_init(size_t initial_capacity) {
    kvs_t* kvs = (kvs_t*)malloc(sizeof(kvs_t));
    kvs->data = (kv_pair*)calloc(initial_capacity, sizeof(kv_pair));
    kvs->capacity = initial_capacity;
    kvs->size = 0;
    return kvs;
}

// Function to add a key-value pair to the KVS
void kvs_put(kvs_t* kvs, int key, long offset, int value) {
    if (kvs->size >= kvs->capacity * 0.7) {
        // Resize the data structure when 70% full
        size_t new_capacity = kvs->capacity * 2;
        kv_pair* new_data = (kv_pair*)realloc(kvs->data, new_capacity * sizeof(kv_pair));
        if (!new_data) {
            // Handle memory allocation failure
            printf("Memory allocation failed\n");
            return;
        }
        kvs->data = new_data;
        kvs->capacity = new_capacity;
    }
    kv_pair* pair = &kvs->data[kvs->size];
    pair->key = key;
    pair->offset = offset;
    pair->value = value;
    kvs->size++;
}

// Function to get the value for a given key
int kvs_get(kvs_t* kvs, int key) {
    for (size_t i = 0; i < kvs->size; i++) {
        if (kvs->data[i].key == key) {
            return kvs->data[i].value;
        }
    }
    // Handle key not found
