    fwrite(&kvs->size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < kvs->size; i++) {
        kv_pair pair = kvs->data[i];
        fwrite(&pair.key, sizeof(int), 1, file);
        fwrite(&pair.offset, sizeof(long), 1, file);
        fwrite(&pair.value, sizeof(int), 1, file);
    }
}

// Function to deserialize the KVS data structure
kvs_t* kvs_deserialize(FILE* file) {
