    // Convert JSON object to string
    PyObject* json_string = PyUnicode_AsUTF8String(json_object);

    // Copy serialized JSON string to C buffer
    strcpy(buffer, PyUnicode_AsUTF8String(json_string));

    return 0;
}

int DataStructureManager_deserialize_from_json(void* data, char* json_string) {
