    Record** records = (Record**)data;
    IndexTracker** trackers = ((Record**)data)[0]->trackers;

    for (int i = 0; i < *records_size; i++) {
        PyObject* record_dict = PyDict_GetItem(json_object, PyStr_FromString(str(i)));
        if (record_dict) {
            int key = PyLong_AsInt(PyDict_GetItem(record_dict, PyStr_FromString("key")));
            long int value = PyLong_AsLong(PyDict_GetItem(record_dict, PyStr_FromString("value")));
            // Update record and index tracker
            records[i]->key = key;
            records[i]->value = value;
            trackers[key]->offset = i;
        }
    }

    return 0;
}
