#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Profile {
    int id;
    char *username;
    char *email;
    int numNumbers;
    char **phoneNumbers;
} Profile;

Profile *profiles = NULL;
int profileCount = 0;
int maxProfileSize = 10000; // initial capacity

// Function to create a new profile
Profile *createProfile(int id) {
    Profile *profile = (Profile *)malloc(sizeof(Profile));
    profile->id = id;
    profile->username = (char *)malloc(64 * sizeof(char));
    profile->email = (char *)malloc(64 * sizeof(char));
    profile->numNumbers = 0;
    profile->phoneNumbers = NULL;

    return profile;
}

// Function to add a new profile
void addProfile(int id, char *username, char *email, int numNumbers, char **phoneNumbers) {
    Profile *profile = createProfile(id);
    strcpy(profile->username, username);
    strcpy(profile->email, email);

    // Reallocate memory if necessary
    if (profileCount >= maxProfileSize / 2) {
        maxProfileSize *= 2;
        profiles = (Profile *)realloc(profiles, maxProfileSize * sizeof(Profile));
    }

    profile->phoneNumbers = phoneNumbers;
    profile->numNumbers = numNumbers;

    // Check for uniqueness
    int i;
    for (i = 0; i < profileCount; i++) {
        if (strcmp(profiles[i]->username, username) == 0 || strcmp(profiles[i]->email, email) == 0) {
            printf("Error: Username or Email already exists.\n");
            freeProfile(profile);
            return;
        }
    }

    // Add the profile to the collection
    profiles = (Profile *)realloc(profiles, (profileCount + 1) * sizeof(Profile));
    profiles[profileCount] = profile;

    profileCount++;
}

// Function to find and print the profile with the longest username
void longestUsername() {
    char *longestName = NULL;
    int maxLength = 0;
    int i;
    for (i = 0; i < profileCount; i++) {
        if (strlen(profiles[i]->username) > maxLength) {
            longestName = profiles[i]->username;
            maxLength = strlen(longestName);
        }
    }

    printf("Profile with the longest username: %s\n", longestName);
}

// Function to serialize the collection to a file
void serializeToFile(char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        printf("Error: Unable to open file.\n");
        return;
    }

    int i;
    for (i = 0; i < profileCount; i++) {
        fwrite(&profiles[i]->id, sizeof(int), 1, file);
        fwrite(profiles[i]->username, strlen(profiles[i]->username) + 1, sizeof(char), 1, file);
        fwrite(profiles[i]->email, strlen(profiles[i]->email) + 1, sizeof(char), 1, file);

        int j;
        for (j = 0; j < profiles[i]->numNumbers; j++) {
            fwrite(&profiles[i]->phoneNumbers[j], strlen(profiles[i]->phoneNumbers[j]) + 1, sizeof(char), 1, file);
        }
    }

    fclose(file);
}

// Function to deserialize the collection from a file
void deserializeFromFile(char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        printf("Error: Unable to open file.\n");
        return;
    }

    int i;
    for (i = 0; i < profileCount; i++) {
        int id;
        fread(&id, sizeof(int), 1, file);
        char *username = (char *)malloc(64 * sizeof(char));
        char *email = (char *)malloc(64 * sizeof(char));

        fread(username, strlen(profiles[i]->username) + 1, sizeof(char), 1, file);
        fread(email, strlen(profiles[i]->email) + 1, sizeof(char), 1, file);

        // Allocate memory for the phone numbers array
        int numNumbers;
        fread(&numNumbers, sizeof(int), 1, file);
        char **phoneNumbers = (char **)malloc(numNumbers * sizeof(char *));
        for (int j = 0; j < numNumbers; j++) {
            char *phoneNumber = (char *)malloc(64 * sizeof(char));
            fread(phoneNumber, strlen(profiles[i]->phoneNumbers[j]) + 1, sizeof(char), 1, file);
            phoneNumbers[j] = phoneNumber;
        }

        // Add the profile to the collection
        profiles[profileCount].id = id;
        strcpy(profiles[profileCount].username, username);
        strcpy(profiles[profileCount].email, email);
        profiles[profileCount].numNumbers = numNumbers;
        profiles[profileCount].phoneNumbers = phoneNumbers;

        profileCount++;
    }

    fclose(file);
}

// Function to free all allocated memory
void freeProfile(Profile *profile) {
    if (profile == NULL)
        return;

    free(profile->username);
    free(profile->email);

    int i;
    for (i = 0; i < profile->numNumbers; i++) {
        free(profile->phoneNumbers[i]);
    }

    free(profile->phoneNumbers);
    free(profile);
}

// Helper function to free all allocated memory
void freeCollection() {
    int i;
    for (i = 0; i < profileCount; i++) {
        freeProfile(&profiles[i]);
    }

    free(profiles);
}
