    table->size = 0;
    table->offsets = (int*)malloc(initial_size * sizeof(int));
    table->records = (record**)malloc(initial_size * sizeof(record*));
    pthread_mutex_init(&table->mutex, NULL);
}

record* hash_table_insert(hash_table *table, uint32_t key, uint64_t offset) {
    int index;
    pthread_mutex_lock(&table->mutex);
    for (index = 0; index < table->size; index++) {
        if (table->offsets[index] == key) {
            // Collision detected, use a collision resolution strategy
            // ...
            break;
        }
    }
    if (index >= table->size) {
        if (table->size >= table->max_size) {
            // Resize the underlying arrays when necessary
            table->max_size *= 2;
            int *new_offsets = (int*)malloc(table->max_size * sizeof(int));
            record **new_records = (record**)malloc(table->max_size * sizeof(record*));
            pthread_memcpy(new_offsets, table->offsets, table->size * sizeof(int));
            pthread_memcpy(new_records, table->records, table->size * sizeof(record*));
            free(table->offsets);
            free(table->records);
            table->offsets = new_offsets;
            table->records = new_records;
        }
        index = table->size++;
        table->offsets[index] = key;
        table->records[index] = (record*)malloc(sizeof(record));
        *table->records[index] = (record){key, offset};
    }
    pthread_mutex_unlock(&table->mutex);
    return table->records[index];
}

int hash_table_delete(hash_table *table, uint32_t key) {
    int index;
    pthread_mutex_lock(&table->mutex);
    for (index = 0; index < table->size; index++) {
        if (table->offsets[index] == key) {
            // Remove the record and shrink the underlying arrays when necessary
            // ...
            break;
        }
    }
    if (index >= table->size) {
        pthread_mutex_unlock(&table->mutex);
        return -1;
    }
    pthread_mutex_unlock(&table->mutex);
    free(table->records[index]);
    for (int i = index; i < table->size - 1; i++) {
        table->offsets[i] = table->offsets[i + 1];
        table->records[i] = table->records[i + 1];
    }
    table->size--;
    return 0;
}

void hash_table_serialize(const char *filename, const hash_table *table) {
    int fd = open(filename, O_RDWR | O_CREAT | O_TRUNC, 0644);
    if (fd == -1) {
        // Handle error
    }
    size_t offset = lseek(fd, 0, SEEK_END);
    void *buffer = mmap(NULL, offset, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (buffer == MAP_FAILED) {
        // Handle error
    }
    // Serialize the hash table to disk
    // ...
    munmap(buffer, offset);
    close(fd);
}

hash_table* hash_table_deserialize(const char *filename) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        // Handle error
    }
    struct stat sb;
    fstat(fd, &sb);
    size_t size = sb.st_size;
    void *buffer = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (buffer == MAP_FAILED) {
        // Handle error
    }
    hash_table* table = (hash_table*)malloc(sizeof(hash_table));
    // Deserialize the hash table from disk
    // ...
    munmap(buffer, size);
    close(fd);
    return table;
}

void record_log_init() {
    // Initialize the log file
    int fd = open("record.log", O_RDWR | O_CREAT | O_TRUNC, 0644);
    if (fd == -1) {
        // Handle error
    }
    pthread_mutex_init(&log_mutex, NULL);
}

void record_log_insert(char *str) {
    pthread_mutex_lock(&log_mutex);
    // Convert the string to its MD5 hash and store alongside original string
    // ...
    pthread_mutex_unlock(&log_mutex);
}

void record_log_delete(char *str) {
    pthread_mutex_lock(&log_mutex);
    // Remove the log entry
    // ...
    pthread_mutex_unlock(&log_mutex);
}
