['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the record structure
typedef struct {
    int key;
    long offset;
    int value;
} Record;

// Define the data storage system's internal structure
typedef struct {
    Record *records;
    size_t capacity, size;
    pthread_mutex_t mutex; // for concurrency control
} DynamicDataStorage;

// Initialize the dynamic data storage system with an initial capacity
void initDynamicDataStorage(DynamicDataStorage *storage, int capacity) {
    storage->records = (Record *)malloc(capacity * sizeof(Record));
    storage->capacity = capacity;
    storage->size = 0;
    pthread_mutex_init(&storage->mutex, NULL);
}

// Insert a new record into the dynamic data storage system
void insertRecord(DynamicDataStorage *storage, int key, long offset, int value) {
    Record newRecord;
    newRecord.key = key;
    newRecord.offset = offset;
    newRecord.value = value;

    pthread_mutex_lock(&storage->mutex);

    // Resize the storage if necessary
    if (storage->size >= storage->capacity / 2) {
        storage->capacity *= 2;
        storage->records = (Record *)realloc(storage->records, storage->capacity * sizeof(Record));
    }

    // Insert the new record at the end of the array
    Record *newRecords = (Record *)malloc((storage->size + 1) * sizeof(Record));
    memcpy(newRecords, storage->records, storage->size * sizeof(Record));
    free(storage->records);
    storage->records = newRecords;
    storage->records[storage->size] = newRecord;

    storage->size++;

    pthread_mutex_unlock(&storage->mutex);
}

// Update the value of a record in the dynamic data storage system
void updateRecord(DynamicDataStorage *storage, int key, long offset, int newValue) {
    Record *record;
    pthread_mutex_lock(&storage->mutex);

    // Find and update the record with the given key and offset
    for (int i = 0; i < storage->size; i++) {
        if (storage->records[i].key == key && storage->records[i].offset == offset) {
            record = &storage->records[i];
            break;
        }
    }

    // If the record was found, update its value
    if (record) {
        record->value = newValue;
    } else {
        printf("Error: Record not found.\n");
    }

    pthread_mutex_unlock(&storage->mutex);
}

// Delete a record from the dynamic data storage system
void deleteRecord(DynamicDataStorage *storage, int key, long offset) {
    Record *newRecords;
    pthread_mutex_lock(&storage->mutex);

    // Find and remove the record with the given key and offset
    for (int i = 0; i < storage->size; i++) {
        if (storage->records[i].key == key && storage->records[i].offset == offset) {
            Record *recordToBeRemoved = &storage->records[i];
            Record *newRecords = (Record *)malloc((storage->size - 1) * sizeof(Record));
            memcpy(newRecords, storage->records, i * sizeof(Record));
            memcpy(&newRecords[i], recordToBeRemoved + 1, (storage->size - i - 1) * sizeof(Record));
            free(storage->records);
            storage->records = newRecords;
            break;
        }
    }

    if (i == storage->size) {
        printf("Error: Record not found.\n");
    } else {
        storage->size--;
    }

    pthread_mutex_unlock(&storage->mutex);
}

