class Record {
public:
    int key;
    long offset;
    int value;

    Record(int key, long offset, int value) : key(key), offset(offset), value(value) {}
};

class RecordSet {
private:
    std::mutex mtx;
    std::condition_variable cv;
    std::deque<Record> records;
    std::atomic<int> size(0);

public:
    void add(const Record& record) {
        std::unique_lock<std::mutex> lock(mtx);
        if (!isUnique(record.key, record.offset)) {
            return;
        }
        records.push_back(record);
        size++;
        lock.unlock();
        cv.notify_one();
    }

    bool remove(int key, long offset) {
        std::unique_lock<std::mutex> lock(mtx);
        auto it = records.begin();
        while (it != records.end()) {
            if (it->key == key && it->offset == offset) {
                size--;
                records.erase(it);
                return true;
            }
            ++it;
        }
        return false;
    }

    Record find(int key, long offset) {
        std::unique_lock<std::mutex> lock(mtx);
        auto it = records.begin();
        while (it != records.end()) {
            if (it->key == key && it->offset == offset) {
                return *it;
            }
            ++it;
        }
        return Record(-1, -1, -1); // not found
    }

private:
    bool isUnique(int key, long offset) {
        for (const auto& record : records) {
            if (record.key == key && record.offset == offset) {
                return false;
            }
        }
        return true;
    }
};

