// Define custom hash table with chaining
typedef struct _hash_node {
    LogData key;
    struct _hash_node* next;
} HashNode;

typedef struct {
    int size;
    HashNode** buckets;
} CustomHashMap;

CustomHashMap* create_hash_table(int size) {
    CustomHashMap* map = (CustomHashMap*)malloc(sizeof(CustomHashMap));
    map->size = size;
    map->buckets = (HashNode**)calloc(size, sizeof(HashNode*));
    for (int i = 0; i < size; i++) {
        map->buckets[i] = NULL;
    }
    return map;
}

// Function to process log stream
void process_log_stream(int num_logs, LogData logs[]) {
    CustomHashMap* hash_table = create_hash_table(10000);
    int event_type_freq[20] = {0}; // Initialize counter for event types

    for (int i = 0; i < num_logs; i++) {
        time_t timestamp = logs[i].timestamp;
        char event_type[20];
        strcpy(event_type, logs[i].event_type);

        // Parse timestamp to determine interval
        int interval = (int)((time(NULL) - timestamp) / 3600); // Hourly

        // Check if log exists in current interval
        HashNode* node = hash_table->buckets[interval % hash_table->size];
        while (node && node->key.timestamp != timestamp) {
            node = node->next;
        }
        if (!node) { // New log for the interval
            node = (HashNode*)malloc(sizeof(HashNode));
            node->key = logs[i];
            node->next = hash_table->buckets[interval % hash_table->size];
            hash_table->buckets[interval % hash_table->size] = node;
        } else {
            // Log already exists; increment event type counter
            for (int j = 0; j < strlen(event_type); j++) {
                if (event_type[j] == ' ') break;
            }
            int idx = atoi(&event_type[j]);
            event_type_freq[idx]++;
        }

        // Update event type counter
        event_type_freq[atoi(event_type)]++;
    }

    // Serialize data to persistent storage system
    FILE* file = fopen("log_data.bin", "wb");
    fwrite(hash_table, sizeof(CustomHashMap), 1, file);
    for (int i = 0; i < num_logs; i++) {
        LogData log = logs[i];
        fwrite(&log, sizeof(LogData), 1, file);
    }
    fclose(file);

    // Deserialize data from persistent storage system
    FILE* file2 = fopen("log_data.bin", "rb");
    CustomHashMap* deserialized_hash_table;
    fread(&deserialized_hash_table, sizeof(CustomHashMap), 1, file2);
    for (int i = 0; i < num_logs; i++) {
        LogData log;
        fread(&log, sizeof(LogData), 1, file2);
        // Process deserialized log data
    }
    fclose(file2);

    // Free allocated memory
    free_hash_table(hash_table);
}

// Function to summarize top N most frequent events per interval and total unique events
