// Union-Find data structure
typedef struct {
    int* parent;
    int* rank;
} uf;

uf uf_create(int n) {
    uf u = (uf)malloc(sizeof(*u));
    u->parent = (int*)malloc(n * sizeof(int));
    u->rank = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        u->parent[i] = -1;
        u->rank[i] = 0;
    }
    return u;
}

void uf_union(uf* u, int x, int y) {
    if (u->parent[x] == -1 && u->parent[y] == -1)
        u->parent[x] = y;
    else if (u->parent[x] != -1 && u->parent[y] != -1) {
        if (u->rank[x] > u->rank[y])
            u->parent[y] = x;
        else
            u->parent[x] = y;
        if (u->rank[x] == u->rank[y])
            u->rank[y]++;
    }
}

int uf_find(uf* u, int x) {
    if (u->parent[x] != -1)
        return u->parent[x];
    else
        return x;
}

// Function to process the dataset
void process_dataset(int num_elements, FILE* stream) {
    int i, key, value;
    srand(time(NULL)); // Seed random number generator

    // Initialize arrays and Union-Find data structure
