        fread(&key, sizeof(int), 1, stream);
        value = rand() % 100 + 1; // Randomly generate a value within [1, 100]
        while (value <= 0 || value > 100) { // Ensure no duplicates among keys
            value = rand() % 100 + 1;
        }
        record* rec = &records[i];
        rec->key = key;
        rec->offset = i * sizeof(record);
        rec->value = value;

        // Initialize the Union-Find data structure for disjoint sets
        uf u = uf_create(num_elements);
        int x = uf_find(&u, i);
        for (int j = 0; j < i; j++) {
            if (rec->key == records[j].key) { // If a duplicate key is found
                x = uf_find(&u, j);
                break;
            }
        }
    }

    // Find and print the largest integer in the dataset
    int max_value = 0;
    for (i = 0; i < num_elements; i++) {
        if (records[i].value > max_value)
            max_value = records[i].value;
    }
    printf("Largest value: %d\n", max_value);

    // Free allocated memory
    my_free(records);
    my_free(keys);
    my_free(offsets);
}

// Helper functions for memory management
void* my_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL && size > 0) { // Handle memory allocation failures gracefully
        printf("Memory allocation failure. Falling back to smaller data structures.\n");
        return my_malloc(size / 2);
    }
    else if (size > memory_budget)
        printf("Memory budget exceeded. Reducing data structure sizes.\n");
    return ptr;
}

void my_free(void* ptr) {
