#include <time.h>

typedef long offset_t;
typedef int key_t;

struct record_t {
    offset_t offset;
    key_t key;
    int data;
};

offset_t* generateOffsets(int size) {
    srand(time(NULL));
    offset_t* offsets = (offset_t*)malloc(size * sizeof(offset_t));

    for (int i = 0; i < size; i++) {
        offset_t offset = rand() % 2001 - 1000;
        while (i > 0 && memcmp(&offsets[i-1], &offset, sizeof(offset_t)) == 0) {
            offset = rand() % 2001 - 1000;
        }
        offsets[i] = offset;
    }

    return offsets;
}

key_t* generateKeys(int size) {
    srand(time(NULL));
    key_t* keys = (key_t*)malloc(size * sizeof(key_t));

    for (int i = 0; i < size; i++) {
        key_t key = rand() % 500 + 1;

        // If duplicate key is generated, retry
        int unique = 0;
        while (!unique) {
            for (int j = 0; j < i; j++) {
                if (keys[j] == key) {
                    key = rand() % 500 + 1;
                    break;
                }
            }

            if (j >= i) {
                unique = 1;
            }
        }

        keys[i] = key;
    }

    return keys;
}

struct record_t* generateRecords(int size, offset_t* offsets, key_t* keys) {
    struct record_t* records = (struct record_t*)malloc(size * sizeof(struct record_t));

    for (int i = 0; i < size; i++) {
        records[i].offset = offsets[i];
        records[i].key = keys[i];
        records[i].data = rand() % 1001;
    }

    return records;
}

void modifyRecords(struct record_t* records, int size) {
    for (int i = 0; i < size; i++) {
        records[i].data = (records[i].offset * 2 + records[i].key * 3) % 1001;
    }
}

struct record_t** allocateAndInitializeRecords(int size) {
    offset_t* offsets = generateOffsets(size);
    key_t* keys = generateKeys(size);

    struct record_t* records = generateRecords(size, offsets, keys);

    free(offsets);
    free(keys);

    return &records;
}

void processRecords(struct record_t** records, int size) {
    for (int i = 0; i < size; i++) {
        modifyRecords(records[i], size);
    }
}

struct record_t** allocateAndProcessRecords(int size) {
    struct record_t** records = allocateAndInitializeRecords(size);

    processRecords(records, size);

    return records;
}
