    add_project(&projects, &num_projects, "Project B", 2).dependencies = (project*)add_project(&projects, &num_projects, "Project C", 3);
    add_project(&projects, &num_projects, "Project D", 4);
    add_project(&projects, &num_projects, "Project E", 5);

    // Print project details
