        print_project_details(&projects[i]);
    }

    // Free memory
    for(int i = 0; i < num_projects; i++) {
        free(projects[i].name);
        if (projects[i].dependencies) {
            free(projects[i].dependencies->name);
            free(projects[i].dependencies);
        }
    }
    free(projects);

    return 0;
}

