        printf("Name: %s\n", project->name);
    } else {
        printf("No name available.\n");
    }
    printf("Priority: %d\n", project->priority);
    if (project->dependencies) {
        printf("Dependencies:\n");
        print_project_details(project->dependencies);
    } else {
        printf("No dependencies.\n");
    }
}

// Function to add a new project with its name and priority
project* add_project(project** projects, int* num_projects, const char* name, int priority) {
    // Check if memory is available for the next project
    if (*num_projects >= (int)sizeof(projects[0])) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    // Allocate memory for the new project and its dependencies
    project* new_project = (project*)malloc(sizeof(project));
    new_project->name = (char*)malloc((strlen(name) + 1) * sizeof(char));
    strcpy(new_project->name, name);
    new_project->priority = priority;
    new_project->dependencies = NULL;

    // Update the list with the new project
    (*projects)[*num_projects] = *new_project;
    (*num_projects)++;

    return &(*projects)[*num_projects - 1];
}
