    list.head = &nodes[0];
    list.tail = &nodes[MAX_NODES - 1];

    return 0;
}

void traverse_list() {
    node_t* current_node = list.head;
    int i;

    for (i = 0; i < MAX_NODES; i++) {
        if (current_node) {
            // Modify the data field based on the id value
            char new_data[MAX_LENGTH];
            sprintf(new_data, "%s - Modified", current_node->data);
            free(current_node->data);
            current_node->data = malloc(strlen(new_data) + 1);
            strcpy(current_node->data, new_data);

            current_node++;
        }
    }
}

int main() {
    if (init_linked_list()) {
        log_message("Failed to initialize the linked list.");
        return -1;
    }

    traverse_list();

    return 0;
}
