void manageMetricsSystem() {
    struct metric *metrics = NULL;
    int *timestamps = NULL;
    double *values = NULL;
    size_t capacity = 0;
    size_t last_timestamp_index = -1;

    // Initialize graph parameters
    int graph_max_metrics = 1000000; // Maximum number of metrics
    int min_status_value = 0, max_status_value = 2; // Range for generating random status values

    while (1) {
        printf("Enter the command: \n");
        printf("(A)dd new metric, (Q)uit, or (S)erialize and quit?\n");

        char command;
        scanf(" %c", &command);

        switch(command) {
            case 'A':
                // Add a new metric
                if (capacity >= graph_max_metrics) {
                    capacity *= 2; // Double the capacity when full
                }

                metrics = realloc(metrics, sizeof(struct metric) * capacity);
                timestamps = realloc(timestamps, sizeof(int) * capacity);
                values = realloc(values, sizeof(double) * capacity);

                last_timestamp_index++;
                int timestamp = rand() % (last_timestamp_index + 1);
                timestamps[last_timestamp_index] = timestamp;
                metrics[last_timestamp_index].value = 0.5; // Initial value
                metrics[last_timestamp_index].status = STARTED;

                break;
            case 'Q':
                // Quit the program
                free(metrics);
                free(timestamps);
                free(values);
                return;
            case 'S':
                // Serialize and quit
                printf("Serializing metrics...\n");
                serializeMetrics(metrics, capacity);
                free(metrics);
                free(timestamps);
                free(values);
                return;
        }
    }
}

void serializeMetrics(struct metric *metrics, size_t capacity) {
    FILE *file = fopen("metrics.dat", "wb");

    if (file == NULL) {
        printf("Error opening file.\n");
        return;
    }

    fwrite(&capacity, sizeof(size_t), 1, file);
    for (size_t i = 0; i < capacity; i++) {
        fwrite(&metrics[i], sizeof(struct metric), 1, file);
    }

    fclose(file);
}

void deserializeMetrics() {
    FILE *file = fopen("metrics.dat", "rb");

    if (file == NULL) {
        printf("Error opening file.\n");
        return;
    }

    size_t capacity;
    fread(&capacity, sizeof(size_t), 1, file);

    struct metric *metrics = malloc(sizeof(struct metric) * capacity);
    int *timestamps = malloc(sizeof(int) * capacity);
    double *values = malloc(sizeof(double) * capacity);

    for (size_t i = 0; i < capacity; i++) {
        fread(&metrics[i], sizeof(struct metric), 1, file);
    }

    fclose(file);
}
