typedef enum {
    PENDING,
    SUCCESS,
    FAILURE
} metric_status_t;

typedef struct {
    double value;
    int timestamp;
    metric_status_t status;
} metric_t;

metric_t* manageMetricsSystem(size_t capacity, pthread_mutex_t* lock) {
    // Initialize the metrics array with allocated memory
    metric_t* metrics = (metric_t*)malloc(sizeof(metric_t) * capacity);

    // Set initial capacity and current size to zero
    int capacity = 0;
    int size = 0;

    return metrics;
}

void addMetric(metric_t** metrics, pthread_mutex_t* lock, double value, int timestamp, metric_status_t status) {
    // Acquire the lock to ensure thread safety
    pthread_mutex_lock(lock);

    // Check for capacity overflow and reallocate if necessary
    if (size >= *capacity) {
        *metrics = realloc(*metrics, sizeof(metric_t) * 2 * capacity);
        capacity *= 2;
    }

    // Allocate space for the new metric
    metric_t* newMetric = (metric_t*)malloc(sizeof(metric_t));

    // Set the new metric's values and timestamp
    newMetric->value = value;
    newMetric->timestamp = timestamp;
    newMetric->status = status;

    // Add the new metric to the array and increment size
    metrics[size++] = newMetric;

    pthread_mutex_unlock(lock);
}

metric_t* getMetric(metric_t** metrics, int index) {
    if (index < 0 || index >= size) {
        return NULL;
    }

    return &metrics[index];
}

double calculateAverageMetricValue(metric_t** metrics) {
    double sum = 0.0;
    for (int i = 0; i < size; i++) {
        sum += metrics[i]->value;
    }
    return sum / size;
}

void printMetricsByStatus(metric_t** metrics, metric_status_t status) {
    for (int i = 0; i < size; i++) {
        if (metrics[i]->status == status) {
            printf("Value: %f, Timestamp: %d\n", metrics[i]->value, metrics[i]->timestamp);
        }
    }
}

void serializeMetrics(metric_t** metrics, FILE* file) {
    // Serialize the metrics array
    fwrite(&size, sizeof(int), 1, file);
    for (int i = 0; i < size; i++) {
        fwrite(&metrics[i], sizeof(metric_t), 1, file);
    }
}

metric_t* deserializeMetrics(FILE* file) {
    metric_t** metrics;
    int capacity;

    // Read the size of the metrics array
    fread(&size, sizeof(int), 1, file);

    // Allocate space for the metrics array
    metrics = (metric_t**)malloc(sizeof(metric_t*) * size);
    for (int i = 0; i < size; i++) {
        metrics[i] = (metric_t*)malloc(sizeof(metric_t));
        fread(&metrics[i], sizeof(metric_t), 1, file);
    }

