#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef enum {
    ACTIVE,
    EXPIRED
} status_t;

typedef struct {
    int user_id;
    int last_active_time;
    status_t status;
    char *session_token;
} session_t;

void manageUserSessions() {
    // Read configuration parameters from external data source
    int num_sessions = 10000; // Default number of sessions
    int max_status_value = 10; // Maximum value for random status generation

    // Initialize arrays and structures
    session_t **sessions = (session_t **)malloc(num_sessions * sizeof(session_t *));
    char **session_tokens = (char **)malloc(num_sessions * sizeof(char *));
    int *last_active_times = (int *)malloc(num_sessions * sizeof(int));

    for (int i = 0; i < num_sessions; i++) {
        sessions[i] = (session_t *)malloc(sizeof(session_t));
        session_tokens[i] = (char *)malloc(64); // Assume max token length is 64
        last_active_times[i] = 0;
    }

    int current_session_index = 0;

    while (1) {
        // Read user ID, last active time, and session token from standard input
        int user_id;
        scanf("%d", &user_id);
        int last_active_time;
        scanf("%d", &last_active_time);

        // Generate unique session token
        sprintf(session_tokens[current_session_index], "Session_%d", current_session_index + 1);

        sessions[current_session_index]->user_id = user_id;
        sessions[current_session_index]->last_active_time = last_active_time;
        sessions[current_session_index]->status = rand() % max_status_value == 0 ? EXPIRED : ACTIVE;
        sessions[current_session_index]->session_token = session_tokens[current_session_index];

        current_session_index++;

        if (current_session_index >= num_sessions) {
            // Resize arrays and structures when necessary
            num_sessions *= 2; // Double the size of the array
            sessions = (session_t **)realloc(sessions, num_sessions * sizeof(session_t *));
            session_tokens = (char **)realloc(session_tokens, num_sessions * sizeof(char *));
            last_active_times = (int *)realloc(last_active_times, num_sessions * sizeof(int));

            for (int i = 0; i < current_session_index; i++) {
                sessions[i]->session_token = session_tokens[i];
            }
        }

        // Handle errors gracefully
        if (ferror(stdin) || feof(stdin)) {
            printf("Error reading input. Aborting.\n");
            exit(1);
        }
    }

    // Serialize data structure to file for persistence
    FILE *file = fopen("sessions.dat", "wb");
    fwrite(sessions, sizeof(session_t), current_session_index, file);
    fclose(file);

    // Deserialize data structure from file into memory
    file = fopen("sessions.dat", "rb");
    session_t **deserialized_sessions = (session_t **)malloc(current_session_index * sizeof(session_t *));
    fread(deserialized_sessions, sizeof(session_t), current_session_index, file);
    fclose(file);

    // Filter and print sessions with status EXPIRED
    for (int i = 0; i < current_session_index; i++) {
        if (deserialized_sessions[i]->status == EXPIRED) {
