metric* manageMetricsSystem() {
    int n = 0, capacity = 10000; // Initial capacity and number of metrics
    metric* metrics = (metric*)malloc(capacity * sizeof(metric));
    if (!metrics) return NULL; // Handle memory allocation failure

    int* timestamps = (int*)malloc(capacity * sizeof(int));
    double* values = (double*)malloc(capacity * sizeof(double));

    for (int i = 0; i < capacity; i++) {
        metrics[i].timestamp = -1;
        metrics[i].status = OK;
    }

    // Initialize last accessed index for each timestamp
    int* lastAccessed = (int*)calloc(capacity, sizeof(int));
    if (!lastAccessed) return NULL; // Handle memory allocation failure

    FILE* file = fopen("initial_graph_parameters.txt", "r");
    if (!file) return NULL; // Handle file reading error

    while (fscanf(file, "%d %lf\n", &n, &values[n]) == 2) {
        n++;
    }
    fclose(file);

    for (int i = 0; i < capacity; i++) {
        metrics[i].value = values[i];
    }

    return metrics;
}

void printErrorMetrics(metric* metrics, int size) {
    for (int i = 0; i < size; i++) {
        if (metrics[i].status == ERROR) printf("%lf %d %s\n", metrics[i].value, metrics[i].timestamp, "ERROR");
    }
}

double calculateAverageMetricValue(metric* metrics, int size) {
    double sum = 0.0;
    for (int i = 0; i < size; i++) {
        sum += metrics[i].value;
    }
    return sum / size;
}

void serializeMetricsToFile(metric* metrics, int size, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return; // Handle file writing error

    for (int i = 0; i < size; i++) {
        fwrite(&metrics[i], sizeof(metric), 1, file);
    }
    fclose(file);
}

metric* deserializeMetricsFromFile(const char* filename) {
