    fseek(file, 0, SEEK_END);
    n = ftell(file) / sizeof(metric);

    metric* metrics = (metric*)malloc(n * sizeof(metric));
    for (int i = 0; i < n; i++) {
        fread(&metrics[i], sizeof(metric), 1, file);
    }
    fclose(file);

    return metrics;
}

