typedef struct {
    int key;
    long offset;
    short value;
} record;

record* expandGraphStructure(int initialCapacity, int minKey, int maxKey) {
    int capacity = initialCapacity;
    int size = 0;
    record* records = (record*)malloc(capacity * sizeof(record));
    record* keys = (int*)malloc(capacity * sizeof(int));
    long* offsets = (long*)malloc(capacity * sizeof(long));

    // Initialize arrays and tracking structure
    for (int i = 0; i < capacity; i++) {
        records[i].key = -1;
        records[i].offset = -1;
        records[i].value = 0;
    }

    int lastAccessedIndex[capacity] = {0};

    // Set value of each record's 'int' field to a random value within a given range
    for (int i = 0; i < capacity; i++) {
        if (records[i].key == -1) {
            records[i].value = rand() % ((maxKey - minKey + 1)) + minKey;
        }
    }

    return records;
}

void addRecord(record* records, int size, record newRecord) {
    // Check for key and offset uniqueness
    for (int i = 0; i < size; i++) {
        if (records[i].key == newRecord.key || records[i].offset == newRecord.offset) {
            printf("Error: Key or offset already exists.\n");
            return;
        }
    }

    // Resize array and reallocate memory if necessary
    if (size >= capacity) {
        int newCapacity = size * 2 + 1;
        record* newRecords = (record*)malloc(newCapacity * sizeof(record));
        int* newKeys = (int*)malloc(newCapacity * sizeof(int));
        long* newOffsets = (long*)malloc(newCapacity * sizeof(long));

        // Copy existing data to new arrays
        for (int i = 0; i < size; i++) {
            newRecords[i] = records[i];
            newKeys[i] = keys[i];
            newOffsets[i] = offsets[i];
        }

        free(records);
        free(keys);
        free(offsets);

        capacity = newCapacity;
        records = newRecords;
        keys = newKeys;
        offsets = newOffsets;
    }

    // Add new record to array
    records[size].key = newRecord.key;
    records[size].offset = newRecord.offset;
    records[size].value = newRecord.value;

    size++;
}

int findLargestKey(record* records, int size) {
    int maxKey = -1;

    for (int i = 0; i < size; i++) {
        if (records[i].key > maxKey) {
            maxKey = records[i].key;
        }
    }

    return maxKey;
}

void printLargestKey(int key, char* message) {
    printf("%s: %d\n", message, key);
}
