// Define a structure for user profiles
typedef struct {
    char* username;
    int age;
    char* email;
} UserProfile;

// Define a structure to represent the dynamic collection of user profiles
typedef struct {
    UserProfile** profiles;
    int size;
    int capacity;
    pthread_mutex_t mutex;
} ProfileCollection;

// Function to initialize and populate the profile collection with sample data
ProfileCollection* init_collection(int num_profiles) {
    // Allocate memory for the collection
    ProfileCollection* collection = (ProfileCollection*)malloc(sizeof(ProfileCollection));

    // Initialize mutex
    pthread_mutex_init(&collection->mutex, NULL);

    // Calculate initial capacity and size
    int capacity = 10;
    int size = 0;

    // Populate the collection with sample data
    for (int i = 0; i < num_profiles; i++) {
        UserProfile* profile = (UserProfile*)malloc(sizeof(UserProfile));

        // Generate random username within a specified range
        char* username = (char*)malloc(16);
        sprintf(username, "user_%d", rand() % 10000);

        // Set age and email randomly
        profile->age = rand() % 50 + 18;
        char* email = (char*)malloc(strlen("example.com") + 1);
        sprintf(email, "user_%s@example.com", username);

        // Add the profile to the collection
        if (size < capacity) {
            collection->profiles[size] = profile;
            size++;
        } else {
            // Resize the collection if necessary
            capacity *= 2;
            UserProfile** new_profiles = (UserProfile**)realloc(collection->profiles, sizeof(UserProfile*) * capacity);
            collection->profiles = new_profiles;
            collection->size = size + 1;
        }
    }

    return collection;
}

// Function to insert a user profile into the collection
void insert_profile(ProfileCollection* collection, UserProfile* profile) {
    pthread_mutex_lock(&collection->mutex);

    // Allocate memory for the new profile if necessary
    if (collection->size >= collection->capacity) {
        int new_capacity = 2 * collection->capacity;
        UserProfile** new_profiles = (UserProfile**)realloc(collection->profiles, sizeof(UserProfile*) * new_capacity);
        collection->profiles = new_profiles;
        collection->capacity = new_capacity;
    }

    // Add the profile to the collection
    collection->profiles[collection->size] = profile;
    collection->size++;

    pthread_mutex_unlock(&collection->mutex);
}

// Function to delete a user profile from the collection
void delete_profile(ProfileCollection* collection, char* username) {
    pthread_mutex_lock(&collection->mutex);

    // Find the profile to be deleted
    for (int i = 0; i < collection->size; i++) {
        if (!strcmp(collection->profiles[i]->username, username)) {
            // Shift remaining profiles forward
            for (int j = i + 1; j < collection->size; j++) {
                collection->profiles[j - 1] = collection->profiles[j];
            }

            // Update size and capacity
            collection->size--;
            if (collection->size <= collection->capacity / 4) {
                int new_capacity = collection->capacity / 2;
                UserProfile** new_profiles = (UserProfile**)realloc(collection->profiles, sizeof(UserProfile*) * new_capacity);
                collection->profiles = new_profiles;
                collection->capacity = new_capacity;
            }

            pthread_mutex_unlock(&collection->mutex);
            return;
        }
    }

    // Profile not found
    pthread_mutex_unlock(&collection->mutex);
}

// Function to retrieve a user profile by username or email
UserProfile* search_profile(ProfileCollection* collection, char* query) {
    pthread_mutex_lock(&collection->mutex);

    // Search for the profile by username or email
    for (int i = 0; i < collection->size; i++) {
        if (!strcmp(collection->profiles[i]->username, query) || !strcmp(collection->profiles[i]->email, query)) {
            pthread_mutex_unlock(&collection->mutex);
            return collection->profiles[i];
        }
    }

    // Profile not found
    pthread_mutex_unlock(&collection->mutex);
    return NULL;
}

// Function to paginate the user profile collection
UserProfile** paginate_profiles(ProfileCollection* collection, int page_size) {
    UserProfile** paginated_profiles = (UserProfile**)malloc(sizeof(UserProfile*) * page_size);
    for (int i = 0; i < page_size && i < collection->size; i++) {
        paginated_profiles[i] = collection->profiles[i];
    }

    return paginated_profiles;
}

// Function to serialize the profile collection to a file
void serialize_collection(ProfileCollection* collection, char* filename) {
    // Open the file for writing
    FILE* file = fopen(filename, "wb");

    // Write the size and capacity of the collection
    fwrite(&collection->size, sizeof(int), 1, file);
    fwrite(&collection->capacity, sizeof(int), 1, file);

    // Write each profile to the file
    for (int i = 0; i < collection->size; i++) {
        UserProfile* profile = collection->profiles[i];

        // Write username
        fwrite(profile->username, sizeof(char), strlen(profile->username) + 1, file);

        // Write age and email
        fwrite(&profile->age, sizeof(int), 1, file);
        fwrite(profile->email, sizeof(char), strlen(profile->email) + 1, file);
