void expandGraphStructure(record **records, int *numRecords) {
    int i, j;
    int newKeyRange = 1000; // adjust this value as needed
    int recordsPerBatch = 500; // adjust this value as needed
    int numNewRecords = rand() % (newKeyRange / recordsPerBatch) + 1;

    for(i = 0; i < numNewRecords; i++) {
        record *newRecord = (record *)malloc(sizeof(record));
        newRecord->key = rand() % newKeyRange;
        // ensure key uniqueness by re-generating until it's unique
        while(findRecordKey(*records, *numRecords, newRecord->key) != -1) {
            newRecord->key = rand() % newKeyRange;
        }
        newRecord->offset = i;
        newRecord->value = (short)(rand() % 256); // adjust this value as needed
        (*records) = realloc(*records, sizeof(record) * (*numRecords + 1));
        (*records)[*numRecords] = *newRecord;
        (*numRecords)++;
    }
}

int findRecordKey(record *records, int numRecords, int key) {
    for(int i = 0; i < numRecords; i++) {
        if(records[i].key == key)
            return i;
    }
    return -1;
}

void printLargestValue(record *records, int numRecords) {
    int maxVal = records[0].value;
    for(int i = 1; i < numRecords; i++) {
        if(records[i].value > maxVal)
            maxVal = records[i].value;
    }
    printf("Largest value: %d\n", maxVal);
}

void serializeGraphStructure(record *records, int numRecords, FILE *file) {
