#include <iostream>
#include <map>
#include <queue>
#include <thread>
#include <mutex>

class CombatStrategy {
public:
    void selectAttack() {
        std::lock_guard<std::mutex> lock(mutex_);
        auto attack = strategies_.empty() ? nullptr : *std::uniform_int_distribution<>(0, strategies_.size()-1)(rng_);
        if (attack) {
            std::cout << "Selected attack: " << attack + 1 << std::endl;
            // Execute the selected attack
            // ...
        }
    }

    void addStrategy(int attackId, int cooldown) {
        std::lock_guard<std::mutex> lock(mutex_);
        strategies_[attackId] = {cooldown};
        queue_.push({attackId});
    }

    void removeStrategy(int attackId) {
        std::lock_guard<std::mutex> lock(mutex_);
        strategies_.erase(attackId);
        // Remove the strategy from the selection queue
        while (!queue_.empty() && queue_.front().first == attackId) {
            queue_.pop();
        }
    }

    void resetCooldowns(int globalCoolPeriod) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto& pair : strategies_) {
            pair.second = globalCoolPeriod;
        }
    }

private:
    struct AttackStrategy {
        int cooldown;
        bool isAvailable;
    };

    std::mt19937 rng_;
    std::map<int, AttackStrategy> strategies_;
    std::priority_queue<std::pair<int, AttackStrategy>> queue_;
    std::mutex mutex_;
};

int main() {
    CombatStrategy strategy;
    strategy.addStrategy(0, 3);
    strategy.addStrategy(1, 2);
    strategy.selectAttack();  // Output: Selected attack: 1
    strategy.selectAttack();  // Output: Selected attack: 1
    std::this_thread::sleep_for(std::chrono::seconds(5));
    strategy.resetCooldowns(1);
    return 0;
}
