#include <time.h>

typedef struct {
    int value;
    long* offset;
} record;

void populateArrays(long*** offsets, int** keys, record** records, FILE* file) {
    char line[1024];
    int offsetIndex = 0, keyIndex = 0, recordIndex = 0;
    long *offsetsArray = NULL;
    int *keysArray = NULL;
    record *recordsArray = NULL;

    // Read offsets from file
    while (fgets(line, sizeof(line), file)) {
        if (ferror(file) || feof(file)) {
            break;
        }
        long offset;
        sscanf(line, "%ld", &offset);
        if (!offsetsArray) {
            offsetsArray = (long*)malloc(sizeof(long) * (offsetIndex + 1));
            offsetsArray[offsetIndex] = offset;
        } else {
            offsetsArray = realloc(offsetsArray, sizeof(long) * (offsetIndex + 2));
            offsetsArray[offsetIndex] = offset;
        }
        offsetIndex++;
    }

    // Read keys from file
    rewind(file);
    while (fgets(line, sizeof(line), file)) {
        if (ferror(file) || feof(file)) {
            break;
        }
        int key;
        sscanf(line, "%d", &key);
        if (!keysArray) {
            keysArray = (int*)malloc(sizeof(int) * (keyIndex + 1));
            keysArray[keyIndex] = key;
        } else {
            keysArray = realloc(keysArray, sizeof(int) * (keyIndex + 2));
            keysArray[keyIndex] = key;
        }
        keyIndex++;
    }

    // Read records from file
    rewind(file);
    srand(time(NULL));
    while (fgets(line, sizeof(line), file)) {
        if (ferror(file) || feof(file)) {
            break;
        }
        int value = rand() % 100;
        record* record = (record*)malloc(sizeof(record));
        record->value = value;
        offsetsArray[offsetIndex - 1] == ? record->offset : offset;
        record->offset = offsetsArray + offsetIndex - 1;
        if (!recordsArray) {
            recordsArray = (record*)malloc(sizeof(record) * (recordIndex + 1));
            recordsArray[recordIndex] = record;
        } else {
            recordsArray = realloc(recordsArray, sizeof(record) * (recordIndex + 2));
            recordsArray[recordIndex] = record;
        }
        recordIndex++;
    }

    // Free allocated memory
    free(offsetsArray);
    free(keysArray);
    free(recordsArray);

    // Log file operations
    int successfulAttempts = offsetIndex / 2;
    int failedAttempts = ferror(file) ? offsetIndex - keyIndex : 0;
    printf("Successful attempts: %d\nFailed attempts: %d\n", successfulAttempts, failedAttempts);
}

int main() {
    FILE* file = fopen("config.txt", "r");
    if (!file) {
        // Handle error
        return 1;
    }

    int offsetSize, recordSize;
    printf("Enter the size of the offset array: ");
    scanf("%d", &offsetSize);
    printf("Enter the size of the record array: ");
    scanf("%d", &recordSize);

    long*** offsets = (long***)malloc(sizeof(long**) * 1);
    int** keys = (int**)malloc(sizeof(int*) * 1);
    record** records = (record**)malloc(sizeof(record*) * 1);

    populateArrays(&offsets, &keys, &records, file);

    fclose(file);

    return 0;
}

