#include <iostream>
#include <map>
#include <mutex>
#include <thread>
#include <fstream>

class CombatStrategyManager {
private:
    std::map<int, struct Strategy> strategies;
    int globalCooldown = 0;
    std::mutex strategyMutex;
    std::ofstream logFile;

public:
    CombatStrategyManager(const std::string& logFilePath) : logFile(logFilePath) {}

    void addStrategy(int attackId, int cooldown, double weight) {
        strategyMutex.lock();
        strategies[attackId] = {cooldown, weight};
        strategyMutex.unlock();
    }

    void removeStrategy(int attackId) {
        strategyMutex.lock();
        if (strategies.find(attackId) != strategies.end()) {
            strategies.erase(attackId);
        }
        strategyMutex.unlock();
    }

    void setGlobalCooldown(int duration) {
        globalCooldown = duration;
    }

    int selectAttack() {
        int selectedAttack = 0;
        double totalWeight = 0.0;

        for (const auto& strategy : strategies) {
            if (strategy.second.cooldown <= 0 && strategy.second.weight > 0.0) {
                totalWeight += strategy.second.weight;
            }
        }

        if (totalWeight > 0.0) {
            double randomValue = static_cast<double>(rand()) / RAND_MAX * totalWeight;

            for (const auto& strategy : strategies) {
                if (strategy.second.cooldown <= 0 && strategy.second.weight > 0.0) {
                    randomValue -= strategy.second.weight;
                    if (randomValue <= 0.0) {
                        selectedAttack = strategy.first;
                        break;
                    }
                }
            }
        }

        return selectedAttack;
    }

    void updateCooldowns() {
        for (auto& strategy : strategies) {
            strategyMutex.lock();
            if (strategy.second.cooldown > 0) {
                strategy.second.cooldown--;
            }
            strategyMutex.unlock();
        }
    }

    void logSelection(int attackId) {
        logFile << "Selected Attack: " << attackId << std::endl;
    }
};

int main() {
    CombatStrategyManager manager("log.txt");

    for (int i = 0; i < 5; ++i) {
        manager.addStrategy(i, 3, static_cast<double>(i + 1));
    }

    while (true) {
        int selectedAttack = manager.selectAttack();
        manager.logSelection(selectedAttack);
        manager.updateCooldowns();

        std::this_thread::sleep_for(std::chrono::milliseconds(1000));
    }
}
