void optimizeImageProcessingPipeline(frame** frames, size_t* numFrames, size_t capacity) {
    if (*numFrames >= capacity) {
        // Dynamically resize the arrays
        *frames = realloc(*frames, (capacity * 2) * sizeof(frame));
        (*numFrames) *= 2;
        capacity *= 2;

        // Resize the secondary structures accordingly
        unsigned int* newTimestamps = malloc(capacity * sizeof(float));
        memcpy(newTimestamps, (*frames)[0].timestamp, *numFrames * sizeof(float));
        free((*frames)[0].timestamp);

        uint32_t* newIndex = malloc(capacity * sizeof(uint32_t));
        memcpy(newIndex, (*frames)[0].index, *numFrames * sizeof(uint32_t));
        free((*frames)[0].index);

        unsigned int** newPixels = malloc(capacity * sizeof(unsigned int*));
        for (size_t i = 0; i < *numFrames; i++) {
            newPixels[i] = (*frames)[i].pixels;
        }
        for (size_t i = *numFrames; i < capacity; i++) {
            newPixels[i] = NULL;
        }

        free((*frames)[0].timestamp);
        free((*frames)[0].index);

        *frames = (frame*) realloc(*frames, capacity * sizeof(frame));
        (*frames)[*numFrames].index = newIndex[(*numFrames) - 1];
        (*frames)[*numFrames].timestamp = newTimestamps[(*numFrames) - 1];

        // Free the temporary memory
        free(newIndex);
        free(newTimestamps);

        for (size_t i = 0; i < *numFrames; i++) {
            free((*frames)[i].pixels);
        }
    }

    // ... other logic ...
}

