#include <sys/stat.h>
#include <fcntl.h>

// Define the maximum number of profiles and interest tags
#define MAX_PROFILES 10000
#define MAX_INTERESTS 50

typedef struct {
    char* username;
    char* email;
    int* interests;
    int num_interests;
} Profile;

Profile* profiles = NULL;
int profile_count = 0;
int* next_free_profile_id = NULL;

// Function to initialize the data structure
void init_profiles() {
    // Initialize memory mapping for efficient storage and retrieval
    int fd = shm_open("/user_profiles", O_RDWR | O_CREAT, S_IRUSR);
    if (fd < 0) {
        perror("Failed to open shared memory");
    }

    profiles = mmap(NULL, sizeof(Profile)*MAX_PROFILES, PROT_READ|PROT_WRITE, MAP_SHARED, fd, 0);
    close(fd);

    next_free_profile_id = (int*)malloc(sizeof(int));
    *next_free_profile_id = 1;
}

// Function to create a new user profile
Profile* create_profile(char* username, char* email, int num_interests) {
    Profile* new_profile = &profiles[*next_free_profile_id - 1];
    new_profile->username = strdup(username);
    new_profile->email = strdup(email);
    new_profile->num_interests = num_interests;
    new_profile->interests = (int*)malloc(sizeof(int)*num_interests);

    // Randomly generate interest tags
    srand(time(NULL));
    for (int i = 0; i < num_interests; i++) {
        int random_tag = rand() % MAX_INTERESTS + 1;
        new_profile->interests[i] = random_tag;
    }

    (*next_free_profile_id)++;

    return new_profile;
}

// Function to prune inactive profiles
void prune_profiles(int threshold_days_inactive) {
    // Iterate through all profiles and check their last activity timestamp (not implemented)
    for (int i = 0; i < profile_count; i++) {
        Profile* profile = &profiles[i];
        // Check if the profile is inactive based on the threshold
        if (profile->last_activity_timestamp < time(NULL) - threshold_days_inactive * 24 * 60 * 60) {
            // Remove the profile from the data structure
            free(profile->username);
            free(profile->email);
            free(profile->interests);
            // Shift down all subsequent profiles to fill the gap
            for (int j = i; j < profile_count - 1; j++) {
                profiles[j] = profiles[j + 1];
            }
            profile_count--;
        }
    }
}

// Function to serialize the data structure to a file
void serialize_profiles(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
    }

    // Write the size of the profiles array
    fwrite(&profile_count, sizeof(int), 1, file);

    // Write each profile individually
    for (int i = 0; i < profile_count; i++) {
        Profile* profile = &profiles[i];
        // Write the username and email
        fwrite(profile->username, strlen(profile->username) + 1, 1, file);
        fwrite(profile->email, strlen(profile->email) + 1, 1, file);

        // Write the number of interests and interest tags
        fwrite(&profile->num_interests, sizeof(int), 1, file);
        fwrite(profile->interests, sizeof(int)*profile->num_interests, 1, file);
    }

    fclose(file);
}

// Function to deserialize the data structure from a file
void deserialize_profiles(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
    }

    // Read the size of the profiles array
    fread(&profile_count, sizeof(int), 1, file);

    // Read each profile individually
    for (int i = 0; i < profile_count; i++) {
        Profile* new_profile = &profiles[i];

        // Read the username and email
        fgets(new_profile->username, sizeof(char)*MAX_USERNAME_LENGTH + 2, file);
        fgets(new_profile->email, sizeof(char)*MAX_EMAIL_LENGTH + 2, file);

        // Read the number of interests and interest tags
        fread(&new_profile->num_interests, sizeof(int), 1, file);
        fread(new_profile->interests, sizeof(int)*new_profile->num_interests, 1, file);
    }

    fclose(file);
}

// Function to find and print the longest username among all profiles
void find_longest_username() {
    char* longest_username = NULL;
    int max_length = 0;

    for (int i = 0; i < profile_count; i++) {
        Profile* profile = &profiles[i];
        if (strlen(profile->username) > max_length) {
            max_length = strlen(profile->username);
            longest_username = strdup(profile->username);
        }
    }

    printf("Longest username: %s\n", longest_username);

    free(longest_username);
}

int main() {
    init_profiles();

    // Create some example profiles
    Profile* profile1 = create_profile("user1", "user1@example.com", 3);
    Profile* profile2 = create_profile("user2", "user2@example.com", 4);
    // ...

    // Periodically prune inactive profiles
    while (1) {
        prune_profiles(30); // Prune profiles that are more than 30 days inactive
        sleep(60 * 60 * 24); // Wait a day before pruning again
    }

    return 0;
}

