typedef struct {
    int key;
    long offset;
    short value;
} record_t;

void expandGraphStructure(int* keys, long* offsets, record_t** records, int max_records) {
    int i = 0;
    FILE* file = fopen("data.txt", "r");
    if (file == NULL) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }

    int last_index = -1;
    while (!feof(file)) {
        int key;
        fscanf(file, "%d", &key);
        if (key < 0 || key >= max_records) {
            break;
        }
        record_t* new_record = realloc(*records[key], sizeof(record_t));
        if (new_record == NULL) {
            printf("Memory allocation failed");
            exit(EXIT_FAILURE);
        }
        (*records[key])->offset = 1000000 + i++;
        fscanf(file, "%hd", &((*records[key]->value)));
        fclose(file);
    }

    record_t** new_records = malloc(max_records * sizeof(record_t*));
    for (int j = 0; j < max_records; j++) {
        if (j >= i) {
            new_record = malloc(sizeof(record_t));
            (*new_record).key = j;
            (*new_record).offset = 1000000 + j;
            fscanf(file, "%hd", &((*new_record).value));
            new_records[j] = new_record;
        } else {
            new_records[j] = *records[key];
        }
    }

    free(*records);
    *records = new_records;
}
