typedef struct {
    int* offsets;
    int* keys;
    void** records;
    int record_size;
    int count;
} MemoryAllocator;

MemoryAllocator* allocate_memory(int offset_count, int key_count) {
    MemoryAllocator* alloc = (MemoryAllocator*)malloc(sizeof(MemoryAllocator));
    if (alloc == NULL) return NULL;

    alloc->offsets = (int*)malloc(offset_count * sizeof(int));
    if (alloc->offsets == NULL) {
        free(alloc);
        return NULL;
    }

    alloc->keys = (int*)malloc(key_count * sizeof(int));
    if (alloc->keys == NULL) {
        free(alloc->offsets);
        free(alloc);
        return NULL;
    }

    alloc->records = (void**)malloc(offset_count * sizeof(void*));
    if (alloc->records == NULL) {
        free(alloc->offsets);
        free(alloc->keys);
        free(alloc);
        return NULL;
    }

    alloc->record_size = sizeof(struct record);
    alloc->count = offset_count;

    return alloc;
}

void fill_records(MemoryAllocator* alloc, int min_value, int max_value) {
    for (int i = 0; i < alloc->count; i++) {
        struct record* rec = (struct record*)malloc(alloc->record_size);
        if (rec == NULL) return;

        rec->value = (rand() % (max_value - min_value)) + min_value;
        alloc->records[i] = rec;
    }
}

int validate_arrays(MemoryAllocator* alloc) {
    if (alloc->count != sizeof(alloc->offsets) / sizeof(alloc->offsets[0]) ||
            alloc->count != sizeof(alloc->keys) / sizeof(alloc->keys[0])) {
        printf("Error: Offset and key array sizes mismatch\n");
        return 0;
    }

    return 1;
}

void free_memory(MemoryAllocator* alloc) {
    for (int i = 0; i < alloc->count; i++) {
        if (alloc->records[i] != NULL)
            free(alloc->records[i]);
    }

    free(alloc->records);
    free(alloc->keys);
    free(alloc->offsets);
    free(alloc);
}

struct record* get_record(MemoryAllocator* alloc, int index) {
    if (index >= 0 && index < alloc->count)
        return (struct record*)alloc->records[index];
    else
        return NULL;
}

void print_records(MemoryAllocator* alloc) {
    for (int i = 0; i < alloc->count; i++) {
        struct record* rec = get_record(alloc, i);
        if (rec != NULL)
            printf("Record %d: %d\n", i, rec->value);
    }
}

void* thread_function(void* arg) {
    MemoryAllocator* alloc = (MemoryAllocator*)arg;
    // Perform memory management operations here
    return NULL;
}

int main() {
    srand(time(NULL));

    MemoryAllocator* alloc = allocate_memory(10, 5);
    if (alloc == NULL) return -1;

    int min_value = 0;
    int max_value = 100;

