// Structure to represent a geometric shape
typedef struct {
    int id;
    char type[10];
    float x, y, width, height;
    int color;
} Shape;

// Structure to manage memory allocation details
typedef struct {
    Shape* shapes;
    int size;
} MemoryDetails;

void freeMemory(MemoryDetails* mem) {
    if (mem->shapes != NULL) {
        for (int i = 0; i < mem->size; i++) {
            free(mem->shapes[i].type);
        }
        free(mem->shapes);
    }
}

// Function to load shapes from a JSON file
MemoryDetails* loadShapes(const char* filename, int* totalArea, float* avgDim) {
    MemoryDetails* mem = NULL;
    json_object* root = NULL;
    Shape* shape = NULL;

    // Load the JSON file and initialize memory details
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: Unable to open file %s.\n", filename);
        return mem;
    }

    json_object* shapesJSON = json_object_from_file(file);
    fclose(file);

    // Process the JSON object
    int shapeCount = 0;
    for (int i = 0; i < json_object_array_length(shapesJSON); i++) {
        json_object* shapeJSON = json_object_get_array_item(shapesJSON, i);
        if (shapeJSON == NULL) {
            continue;
        }

        // Create a new Shape structure
        shapeCount++;
        shape = realloc(shape, sizeof(Shape) * (shapeCount + 1));
        if (shape == NULL) {
            printf("Error: Unable to allocate memory for shapes.\n");
            freeMemory(mem);
            return mem;
        }
        shape[shapeCount - 1].id = json_object_get_int_value(json_object_object_get(shapeJSON, "id"));
        strcpy(shape[shapeCount - 1].type, json_object_get_string_value(json_object_object_get(shapeJSON, "type")));
        shape[shapeCount - 1].x = json_object_get_double_value(json_object_object_get(shapeJSON, "x"));
        shape[shapeCount - 1].y = json_object_get_double_value(json_object_object_get(shapeJSON, "y"));
        shape[shapeCount - 1].width = json_object_get_double_value(json_object_object_get(shapeJSON, "width"));
        shape[shapeCount - 1].height = json_object_get_double_value(json_object_object_get(shapeJSON, "height"));
        shape[shapeCount - 1].color = json_object_get_int_value(json_object_object_get(shapeJSON, "color"));

        // Calculate the area of the current shape
        float area;
        if (strcmp(shape[shapeCount - 1].type, "circle") == 0) {
            area = M_PI * shape[shapeCount - 1].width * shape[shapeCount - 1].height;
        } else if (strcmp(shape[shapeCount - 1].type, "rectangle") == 0) {
            area = shape[shapeCount - 1].width * shape[shapeCount - 1].height;
        } else if (strcmp(shape[shapeCount - 1].type, "triangle") == 0) {
            // Calculate the area of a triangle
            float base = shape[shapeCount - 1].width;
            float height = shape[shapeCount - 1].height;
            area = 0.5f * base * height;
        } else {
            printf("Error: Unknown shape type %s.\n", shape[shapeCount - 1].type);
            continue;
        }

        // Add the calculated area to the total
        *totalArea += area;

        // Update the average dimension
        if (strcmp(shape[shapeCount - 1].type, "circle") == 0) {
            *avgDim = (*avgDim > shape[shapeCount - 1].width ? *avgDim : shape[shapeCount - 1].width);
        } else {
            *avgDim = (*avgDim > (shape[shapeCount - 1].width + shape[shapeCount - 1].height) / 2.0f ? *avgDim : (shape[shapeCount - 1].width + shape[shapeCount - 1].height) / 2.0f;
        }
    }

    // Clean up and return the memory details
    mem = malloc(sizeof(MemoryDetails));
    if (mem == NULL) {
        printf("Error: Unable to allocate memory for memory details.\n");
        freeMemory(NULL);
        return NULL;
    }
    mem->shapes = shape;
    mem->size = shapeCount;

    // Free the JSON object
    json_object_put(shapesJSON);

    return mem;
}

// Function to add a shape to the collection
void addShape(MemoryDetails* mem, int id, char type[], float x, y, width, height, int color) {
    Shape* newShape = malloc(sizeof(Shape));
    if (newShape == NULL) {
        printf("Error: Unable to allocate memory for new shape.\n");
        return;
    }

    newShape->id = id;
    strcpy(newShape->type, type);
    newShape->x = x;
    newShape->y = y;
    newShape->width = width;
    newShape->height = height;
    newShape->color = color;

    // Update the total area and average dimension
    float area;
    if (strcmp(newShape->type, "circle") == 0) {
        area = M_PI * newShape->width * newShape->height;
    } else if (strcmp(newShape->type, "rectangle") == 0) {
        area = newShape->width * newShape->height;
    } else if (strcmp(newShape->type, "triangle") == 0) {
        // Calculate the area of a triangle
        float base = newShape->width;
        float height = newShape->height;
        area = 0.5f * base * height;
    } else {
        printf("Error: Unknown shape type %s.\n", newShape->type);
        return;
    }

    // Add the calculated area to the total
    mem->shapes[mem->size].id = id;
    strcpy(mem->shapes[mem->size].type, type);
    mem->shapes[mem->size].x = x;
    mem->shapes[mem->size].y = y;
    mem->shapes[mem->size].width = width;
    mem->shapes[mem->size].height = height;
    mem->shapes[mem->size].color = color;

    // Update the average dimension
    if (strcmp(newShape->type, "circle") == 0) {
        *avgDim = (*avgDim > newShape->width ? *avgDim : newShape->width);
    } else {
        *avgDim = (*avgDim > (newShape->width + newShape->height) / 2.0f ? *avgDim : (newShape->width + newShape->height) / 2.0f;
    }

    // Increment the size of the shape array
    mem->size++;
}

// Function to remove a shape from the collection
void removeShape(MemoryDetails* mem, int id) {
    for (int i = 0; i < mem->size; i++) {
        if (mem->shapes[i].id == id) {
            // Shift elements down and update the size
            for (int j = i + 1; j < mem->size; j++) {
                mem->shapes[j - 1] = mem->shapes[j];
            }
            mem->size--;
            break;
        }
    }
}

// Function to query shapes based on their unique identifiers
Shape* getShape(MemoryDetails* mem, int id) {
    for (int i = 0; i < mem->size; i++) {
        if (mem->shapes[i].id == id) {
            return &mem->shapes[i];
        }
    }
    return NULL;
}

// Function to calculate the total area of all shapes combined
float getTotalArea(MemoryDetails* mem) {
    float total = 0.0f;
    for (int i = 0; i < mem->size; i++) {
        Shape shape = mem->shapes[i];
        if (strcmp(shape.type, "circle") == 0) {
            total += M_PI * shape.width * shape.height;
        } else if (strcmp(shape.type, "rectangle") == 0) {
            total += shape.width * shape.height;
        } else if (strcmp(shape.type, "triangle") == 0) {
            // Calculate the area of a triangle
            float base = shape.width;
            float height = shape.height;
            total += 0.5f * base * height;
        }
    }
    return total;
}

// Function to provide statistics about the average dimensions across different shapes
float getAvgDim(MemoryDetails* mem) {
    if (mem->size == 0) {
        return 0.0f;
    }

    float total = 0.0f;
    for (int i = 0; i < mem->size; i++) {
        Shape shape = mem->shapes[i];
        if (strcmp(shape.type, "circle") == 0) {
            total += shape.width;
        } else if (strcmp(shape.type, "rectangle") == 0 || strcmp(shape.type, "triangle") == 0) {
            // Calculate the average dimension for rectangles and triangles
            total += (shape.width + shape.height) / 2.0f;
        }
    }
    return total / mem->size;
}
