    if (file != NULL) {
        fwrite(records, sizeof(record), numRecords, file);
        fclose(file);
    }
}

record *deserializeData() {
    record *records = NULL;
    int numRecords = 0;

    FILE *file = fopen("graph_data.txt", "rb");

    if (file != NULL) {
        fseek(file, 0, SEEK_END);
        long fileSize = ftell(file);

        if (fileSize > 0) {
            numRecords = fileSize / sizeof(record);
            records = (record *)malloc(numRecords * sizeof(record));

            fseek(file, 0, SEEK_SET);
            fread(records, sizeof(record), numRecords, file);
            fclose(file);
        }
    }

    return records;
}

