    DynamicGraph *graph = malloc(sizeof(DynamicGraph));
    graph->nodes = calloc(MAX_NODES, sizeof(Node *));
    graph->edges = calloc(MAX_EDGES, sizeof(Edge *));
    graph->nodes_count = 0;
    graph->edges_count = 0;
    return graph;
}

void freeGraph(DynamicGraph *graph) {
    for (int i = 0; i < graph->nodes_count; i++) {
        free(graph->nodes[i]->name);
        free(graph->nodes[i]);
    }
    free(graph->nodes);

    for (int i = 0; i < graph->edges_count; i++) {
        free(graph->edges[i]->description);
        free(graph->edges[i]);
    }
    free(graph->edges);
    free(graph);
}

void addNode(DynamicGraph *graph, int id, const char *name) {
    Node *node = malloc(sizeof(Node));
    node->id = id;
    node->name = strdup(name);
    graph->nodes[graph->nodes_count++] = node;
}

