    Edge *edge = malloc(sizeof(Edge));
    edge->node1 = node1_id;
    edge->node2 = node2_id;
    edge->weight = weight;
    edge->description = strdup(description);
    graph->edges[graph->edges_count++] = edge;
}

void removeNode(DynamicGraph *graph, int id) {
    // find and free the node
    for (int i = 0; i < graph->nodes_count; i++) {
        if (graph->nodes[i]->id == id) {
            free(graph->nodes[i]->name);
            free(graph->nodes[i]);
            memmove(&graph->nodes[i], &graph->nodes[i + 1], sizeof(Node *) * (graph->nodes_count - i - 1));
            graph->nodes_count--;
            break;
        }
    }

    // remove edges connected to the node
    for (int i = 0; i < graph->edges_count; i++) {
        if ((graph->edges[i]->node1 == id || graph->edges[i]->node2 == id)) {
            free(graph->edges[i]->description);
            free(graph->edges[i]);
            memmove(&graph->edges[i], &graph->edges[i + 1], sizeof(Edge *) * (graph->edges_count - i - 1));
            graph->edges_count--;
        }
    }
}

void removeEdge(DynamicGraph *graph, int edge_id) {
    // find and free the edge
    for (int i = 0; i < graph->edges_count; i++) {
        if (graph->edges[i]->node1 == edge_id || graph->edges[i]->node2 == edge_id) {
            free(graph->edges[i]->description);
            free(graph->edges[i]);
            memmove(&graph->edges[i], &graph->edges[i + 1], sizeof(Edge *) * (graph->edges_count - i - 1));
            graph->edges_count--;
            break;
        }
    }
}

int shortestPath(DynamicGraph *graph, int start_id, int end_id) {
    // implement Dijkstra's algorithm
    return 0; // TO DO: implement the algorithm and return the shortest distance
}

void exportGraph(DynamicGraph *graph, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (file == NULL) {
        fprintf(stderr, "Error writing to file '%s'\n", filename);
        return;
    }

    // write nodes and edges to the file
    for (int i = 0; i < graph->nodes_count; i++) {
        Node *node = graph->nodes[i];
        fwrite(&node->id, sizeof(int), 1, file);
        fwrite(node->name, strlen(node->name) + 1, 1, file);
    }

    for (int i = 0; i < graph->edges_count; i++) {
        Edge *edge = graph->edges[i];
        fwrite(&edge->node1, sizeof(int), 1, file);
        fwrite(&edge->node2, sizeof(int), 1, file);
        fwrite(&edge->weight, sizeof(int), 1, file);
        fwrite(edge->description, strlen(edge->description) + 1, 1, file);
    }

    fclose(file);
}

int main() {
    DynamicGraph *graph = dynamicGraphManager();

    // add nodes and edges
    for (int i = 0; i < MAX_NODES; i++) {
        addNode(graph, i, "Node");
    }
    for (int i = 0; i < MAX_EDGES; i++) {
        int node1_id = rand() % MAX_NODES;
        int node2_id = rand() % MAX_NODES;
        int weight = rand() % 100;
        addEdge(graph, node1_id, node2_id, weight, "Edge");
    }

    // remove nodes and edges
    for (int i = 0; i < graph->nodes_count / 2; i++) {
        Node *node = graph->nodes[i];
        removeNode(graph, node->id);
    }
    for (int i = 0; i < graph->edges_count / 2; i++) {
        Edge *edge = graph->edges[i];
        removeEdge(graph, edge->node1);
    }

    // export the graph
    exportGraph(graph, "graph.csv");

    // free allocated memory
    freeGraph(graph);

    return 0;
}
