#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef enum {
    OK,
    WARNING,
    ERROR
} Status;

struct Metric {
    double value;
    int timestamp;
    Status status;
};

void processAndManageMetrics(struct Metric **metrics, int *metricCount, int **timestamps) {
    // Initialize last accessed index for each timestamp/key
    int *lastAccessedIndex = (int *)malloc(sizeof(int));
    *lastAccessedIndex = -1;

    while (1) {
        printf("Enter the number of new metrics to add (0 to stop): ");
        int numNewMetrics;
        scanf("%d", &numNewMetrics);

        if (numNewMetrics == 0) {
            break;
        }

        // Allocate memory for new metrics
        *metricCount += numNewMetrics;
        *metrics = (struct Metric *)realloc(*metrics, (*metricCount) * sizeof(struct Metric));

        // Generate random status/values and timestamps
        srand(time(NULL));
        for (int i = 0; i < numNewMetrics; i++) {
            struct Metric newMetric;
            newMetric.value = (double)(rand() % 100);
            newMetric.timestamp = rand();
            newMetric.status = (Status)((rand() % 3));

            // Ensure unique timestamps and keys
            int found = 0;
            for (int j = *lastAccessedIndex; j >= 0; j--) {
                if ((*metrics)[j].timestamp == newMetric.timestamp) {
                    found = 1;
                    break;
                }
            }

            if (!found) {
                (*metrics)[*metricCount - 1] = newMetric;
                *timestamps = (int *)realloc(*timestamps, (*metricCount) * sizeof(int));
                (*timestamps)[*metricCount - 1] = newMetric.timestamp;
                *lastAccessedIndex = *metricCount - 1;
            }
        }
    }

    // Print metrics with status "ERROR"
    for (int i = 0; i < *metricCount; i++) {
        if ((*metrics)[i].status == ERROR) {
            printf("Metric %d: Value %.2f, Timestamp %d, Status %s\n", i, (*metrics)[i].value, (*metrics)[i].timestamp, "ERROR");
        }
    }

    // Calculate average metric value
    double total = 0.0;
    for (int i = 0; i < *metricCount; i++) {
        total += (*metrics)[i].value;
    }
    printf("Average Metric Value: %.2f\n", total / *metricCount);
}

int main() {
    int metricCount = 0;
    struct Metric *metrics = NULL;
    int *timestamps = NULL;

    processAndManageMetrics(&metrics, &metricCount, &timestamps);

    return 0;
}
