typedef struct {
    int key;
    long offset;
    short value;
} record;

record *expandGraphStructure(int numRecords, int maxKey, int maxValue) {
    record *records = (record *)malloc(numRecords * sizeof(record));
    if (!records) return NULL; // Handle memory allocation failure

    long *offsets = (long *)malloc((numRecords + 1) * sizeof(long));
    if (!offsets) {
        free(records);
        return NULL;
    }

    int *keys = (int *)malloc((numRecords + 1) * sizeof(int));
    if (!keys) {
        free(offsets);
        free(records);
        return NULL;
    }

    for (int i = 0; i < numRecords; i++) {
        records[i].key = rand() % maxKey;
        while (findRecord(&records[0], numRecords, keys, offsets, records[i].key) != NULL) {
            records[i].key = rand() % maxKey;
        }
        records[i].offset = offsets[i] = i;
        records[i].value = rand() % maxValue;
    }

    return records;
}

void setRecordValues(record *records, int numRecords, int maxValue) {
    for (int i = 0; i < numRecords; i++) {
        records[i].value = rand() % maxValue;
    }
}

record *findLargestValueRecord(record *records, int numRecords) {
    record *maxRecord = &records[0];
    for (int i = 1; i < numRecords; i++) {
        if (records[i].value > maxRecord->value) {
            maxRecord = &records[i];
        }
    }
    return maxRecord;
}

record *findRecord(record *records, int numRecords, int *keys, long *offsets, int key) {
    for (int i = 0; i < numRecords; i++) {
        if (keys[i] == key || offsets[i] == key) {
            return &records[i];
        }
    }
    return NULL;
}

void serializeGraphStructure(record *records, int numRecords) {
    FILE *file = fopen("graph_structure.bin", "wb");
    fwrite(&numRecords, sizeof(int), 1, file);
    for (int i = 0; i < numRecords; i++) {
        fwrite(&records[i].key, sizeof(int), 1, file);
        fwrite(&records[i].offset, sizeof(long), 1, file);
        fwrite(&records[i].value, sizeof(short), 1, file);
    }
    fclose(file);
}

record *deserializeGraphStructure() {
    FILE *file = fopen("graph_structure.bin", "rb");
    int numRecords;
    fread(&numRecords, sizeof(int), 1, file);

    record *records = (record *)malloc(numRecords * sizeof(record));
    if (!records) return NULL; // Handle memory allocation failure

    for (int i = 0; i < numRecords; i++) {
        fread(&records[i].key, sizeof(int), 1, file);
        fread(&records[i].offset, sizeof(long), 1, file);
        fread(&records[i].value, sizeof(short), 1, file);
    }
    fclose(file);

    return records;
}
