#include <openssl/aes.h>
#include <openssl/rand.h>

// Define the enum for metric status
typedef enum {
    OK,
    WARNING,
    ERROR
} MetricStatus;

// Define the struct for a single metric
typedef struct {
    double value;
    time_t timestamp;
    MetricStatus status;
} Metric;

// Function to process metrics
void processMetrics(int numMetrics, char *passphrase) {
    // Initialize arrays
    int *timestamps = (int *)malloc(numMetrics * sizeof(int));
    double *values = (double *)malloc(numMetrics * sizeof(double));
    Metric *metrics = (Metric *)malloc(numMetrics * sizeof(Metric));

    // Initialize variables for AES-256-CBC cipher
    EVP_CIPHER_CTX *ctx;
    unsigned char key[AES_BLOCK_SIZE], iv[AES_BLOCK_SIZE];
    int len;

    // Generate random string and hash it
    char *randomString = generateRandomString(20);
    unsigned char hashed[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char *)randomString, strlen(randomString), hashed);

    // Initialize AES-256-CBC cipher
    ctx = EVP_CIPHER_CTX_new();
    EVP_CipherInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    EVP_CipherUpdate_ex(ctx, &hashed, SHA256_DIGEST_LENGTH);

    // Add new metrics to the existing array while maintaining unique timestamps
    for (int i = 0; i < numMetrics; i++) {
        int timestamp;
        do {
            timestamp = time(NULL) % (int)pow(2, 31);
        } while (findTimestamp(timestamps, numMetrics, timestamp));

        // Set up metric structure and add it to the arrays
        metrics[i].value = values[i] = rand() / (double)RAND_MAX;
        metrics[i].timestamp = timestamp;
        metrics[i].status = MetricStatus_OK;

        // Encrypt the timestamp and value using AES-256-CBC cipher
        unsigned char ciphertext[AES_BLOCK_SIZE];
        len = EVP_CipherUpdate_ex(ctx, &ciphertext, AES_BLOCK_SIZE);
    }

    // Serialize the data structure to a file for persistence
    FILE *file = fopen("metrics.txt", "wb");
    fwrite(&numMetrics, sizeof(int), 1, file);
    fwrite(timestamps, sizeof(int), numMetrics, file);
    fwrite(values, sizeof(double), numMetrics, file);
    fwrite(metrics, sizeof(Metric), numMetrics, file);

    // Close the file and free allocated memory
    fclose(file);
    free(timestamps);
    free(values);
    free(metrics);
}

// Function to generate a random string of specified length using a predefined character set
char *generateRandomString(int length) {
    static char chars[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    char *randomString = (char *)malloc(length + 1);
    for (int i = 0; i < length; i++) {
        randomString[i] = chars[rand() % strlen(chars)];
    }
    randomString[length] = '\0';
    return randomString;
}

// Function to find a timestamp in an array
int findTimestamp(int *timestamps, int numMetrics, int timestamp) {
    for (int i = 0; i < numMetrics; i++) {
        if (timestamps[i] == timestamp) {
            return 1;
        }
    }
    return 0;
}

// Function to filter and print metrics with a specific status
void filterAndPrintMetrics(Metric *metrics, int numMetrics, MetricStatus status) {
    for (int i = 0; i < numMetrics; i++) {
        if (metrics[i].status == status) {
            printf("Metric timestamp: %ld, value: %f, status: %s\n", metrics[i].timestamp, metrics[i].value, metric_status_to_string(status));
        }
    }
}

// Function to calculate the average metric value
double calculateAverageMetricValue(Metric *metrics, int numMetrics) {
    double sum = 0;
    for (int i = 0; i < numMetrics; i++) {
        sum += metrics[i].value;
    }
    return sum / numMetrics;
}

// Function to convert MetricStatus enum value to string
char *metric_status_to_string(MetricStatus status) {
    switch (status) {
        case OK:
            return "OK";
        case WARNING:
            return "WARNING";
        case ERROR:
            return "ERROR";
    }
}

int main() {
    int numMetrics = 1000;
    char *passphrase = "my_secret_passphrase";

    processMetrics(numMetrics, passphrase);

    Metric *metrics = (Metric *)malloc(numMetrics * sizeof(Metric));
    // Add new metrics to the existing array while maintaining unique timestamps
    for (int i = 0; i < numMetrics; i++) {
        int timestamp;
        do {
            timestamp = time(NULL) % (int)pow(2, 31);
        } while (findTimestamp(timestamps, numMetrics, timestamp));

        // Set up metric structure and add it to the arrays
        metrics[i].value = rand() / (double)RAND_MAX;
        metrics[i].timestamp = timestamp;
        metrics[i].status = MetricStatus_OK;

        // Encrypt the timestamp and value using AES-256-CBC cipher
        unsigned char ciphertext[AES_BLOCK_SIZE];
        len = EVP_CipherUpdate_ex(ctx, &ciphertext, AES_BLOCK_SIZE);
    }

    // Filter and print metrics with a specific status
    filterAndPrintMetrics(metrics, numMetrics, MetricStatus_ERROR);

    // Calculate the average metric value
    double averageValue = calculateAverageMetricValue(metrics, numMetrics);

    return 0;
}
