    Item** collection = (Item**) malloc(size * sizeof(Item*));
    for (int i = 0; i < size; i++) {
        collection[i] = (Item*) malloc(sizeof(Item));
        collection[i]->id = rand();
        // Set value to a random number within specified range
        collection[i]->value = (rand() % 100) + 1;
    }
    return collection;
}

// Function to find and return the index of an item with a specific id
int getItemIndex(Item** collection, int size, int targetId) {
    for (int i = 0; i < size; i++) {
        if (collection[i]->id == targetId) {
            return i;
        }
    }
    return -1;
}

// Function to perform bulk operations on the collection
void performBulkOperations(Item** collection, int size, char operation, ...) {
    va_list(ap);
    va_start(ap, operation);

    // Perform bulk insertion
    if (operation == 'i') {
        for (int i = 0; i < va_arg(ap, int); i++) {
            Item* newItem = (Item*) malloc(sizeof(Item));
            newItem->id = rand();
            // Set value to a random number within specified range
            newItem->value = (rand() % 100) + 1;
            collection[size + i] = newItem;
        }
    }

    // Perform bulk deletion
    else if (operation == 'd') {
        for (int i = va_arg(ap, int); i > 0; i--) {
            free(collection[size - i]);
        }
    }

    // Perform bulk modification based on certain criteria
    else if (operation == 'm') {
        for (int i = va_arg(ap, int); i > 0; i--) {
            Item* item = collection[size - i];
            item->value += (rand() % 10) + 1;
        }
    }

    va_end(ap);
}

// Function to log changes made to the collection
void logChanges(Item** collection, int size) {
    FILE* file = fopen("collection.log", "a");
    for (int i = 0; i < size; i++) {
        fprintf(file, "%d: %d\n", collection[i]->id, collection[i]->value);
    }
    fclose(file);
}

