record* expandAndManageGraphStructure(record** records, size_t* capacity, int newCapacity) {
    record* newRecords = (record*)realloc(*records, newCapacity * sizeof(record));
    if (!newRecords) return NULL; // handle memory allocation failure

    for (int i = *capacity; i < newCapacity; ++i) {
        newRecords[i].key = rand() % 1000000;
        newRecords[i].offset = rand();
        newRecords[i].value = (short)(rand() % 32768);
        newRecords[i].field = rand() % 2000000;

        for (int j = 0; j < i; ++j) {
            if (newRecords[j].key == newRecords[i].key || newRecords[j].offset == newRecords[i].offset) {
                i--; // duplicate found, shrink capacity and retry
                break;
            }
        }
    }

    *capacity = newCapacity;
    return newRecords;
}

// C# code snippet for AES-CBC decryption
public byte[] DecryptAESCBC(byte[] ciphertext, byte[] encryptionKey, byte[] initializationVector, int blocksize) {
    using (Aes aes = Aes.Create()) {
        aes.Key = encryptionKey;
        aes.IV = initializationVector;

        ICryptoTransform decryptor = aes.CreateDecryptor();

        MemoryStream ms = new MemoryStream(ciphertext);
        CryptoStream cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read);

        int readBytes = 0;
        byte[] plainText = new byte[ciphertext.Length];
        while (readBytes < ciphertext.Length) {
            int bytesRead = cs.Read(plainText, readBytes, blocksize - readBytes);
            readBytes += bytesRead;
        }

        return plainText;
    }
}
