void manageFileMetadata(int numFiles) {
    File** files = (File**)malloc(sizeof(File*) * numFiles);
    time_t* timestamps = (time_t*)malloc(sizeof(time_t) * numFiles);
    char** filenames = (char**)malloc(sizeof(char*) * numFiles);

    // Initialize file metadata
    for (int i = 0; i < numFiles; i++) {
        files[i] = malloc(sizeof(File));
        files[i]->filename = malloc(256 * sizeof(char));
        strcpy(files[i]->filename, "file");
        files[i]->timestamp = time(NULL);
        files[i]->size = rand() % 100 + 1;
    }

    // Initialize index
    int* indices = (int*)malloc(sizeof(int) * numFiles);
    for (int i = 0; i < numFiles; i++) {
        indices[i] = i;
    }

    // Serialize metadata to file
    FILE* file = fopen("metadata.bin", "wb");
    fwrite(files, sizeof(File), numFiles, file);
    fclose(file);

    // Deserialize metadata from file
    File** deserializedFiles = (File**)malloc(sizeof(File*) * numFiles);
    file = fopen("metadata.bin", "rb");
    fread(deserializedFiles, sizeof(File), numFiles, file);
    fclose(file);

    // Find largest file by size for given timestamp
    time_t targetTimestamp = time(NULL);
    File* largestFile = NULL;
    size_t maxSize = 0;
    for (int i = 0; i < numFiles; i++) {
        if (files[i]->timestamp == targetTimestamp && files[i]->size > maxSize) {
            largestFile = files[i];
            maxSize = files[i]->size;
        }
    }

    // Print largest file by size
    printf("Largest file by size for timestamp %lu: %s, size %zu\n",
           targetTimestamp, largestFile->filename, largestFile->size);

    // Free memory
    for (int i = 0; i < numFiles; i++) {
        free(files[i]->filename);
        free(files[i]);
    }
    free(files);
    free(timestamps);
    free(filenames);
    free(indices);
}

int main() {
    int numFiles = 1000000;
    manageFileMetadata(numFiles);
    return 0;
}
