void init_structure(structure** p, int size) {
    *p = (structure*)malloc(sizeof(structure));
    if (!(*p)) {
        printf("Memory allocation failed for structure!\n");
        return;
    }

    (*p)->offsets = (long int*)calloc(size, sizeof(long int));
    if (!(*p)->offsets) {
        free(*p);
        printf("Memory allocation failed for offsets array!\n");
        return;
    }

    (*p)->keys = (int*)calloc(size, sizeof(int));
    if (!(*p)->keys) {
        free((*p)->offsets);
        free(*p);
        printf("Memory allocation failed for keys array!\n");
        return;
    }

    (*p)->records = (record*)calloc(size, sizeof(record));
    if (!(*p)->records) {
        free((*p)->keys);
        free((*p)->offsets);
        free(*p);
        printf("Memory allocation failed for records array!\n");
        return;
    }
}

void hash_function(int key, record* r) {
    r->value = (long int)(key * 2654435769UL % ((1UL << 31) - 1));
}

void update_records(structure* s, int size) {
    for (int i = 0; i < size; i++) {
        hash_function(s->keys[i], &s->records[i]);
    }
}
