typedef struct {
    int val;
    long offset;
    char status;
} record_t;

record_t* allocate_records(int length) {
    if (length <= 0) {
        printf("Invalid length. Returning NULL.\n");
        return NULL;
    }

    // Allocate memory for the 'records' array
    record_t* records = (record_t*) malloc(length * sizeof(record_t));

    if (!records) {
        printf("Memory allocation failed. Returning NULL.\n");
        return NULL;
    }

    // Initialize each record’s ‘int’ field to a random value, 
    // ‘long’ field to the corresponding value from the 'offset' array, and ‘char’ field
    for (int i = 0; i < length; i++) {
        records[i].val = rand() % 2001 - 1000;
        records[i].offset = i * 2;
        records[i].status = rand() % 2 == 0 ? 'A' : 'B';
    }

    return records;
}

long* allocate_offsets(int length) {
    // Allocate memory for the 'offset' array
    long* offsets = (long*) malloc((length + 1) * sizeof(long));

    if (!offsets) {
        printf("Memory allocation failed. Returning NULL.\n");
        return NULL;
    }

    for (int i = 0; i <= length; i++) {
        offsets[i] = i;
    }

    return offsets;
}

int* allocate_keys(int length) {
    // Allocate memory for the 'keys' array
    int* keys = (int*) malloc((length + 1) * sizeof(int));

    if (!keys) {
        printf("Memory allocation failed. Returning NULL.\n");
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < length; i++) {
        keys[i] = rand() % 1001;
    }

    return keys;
}

void deallocate_arrays(int* keys, record_t* records) {
    if (!keys && !records) {
        printf("Both arrays are NULL. No memory needs to be freed.\n");
        return;
    }

    // Free the 'keys' array
    free(keys);

    // Free the 'records' array
    free(records);
}

// Function that manages memory for multiple dynamically allocated arrays
void* manage_memory(int length) {
    long* offsets = allocate_offsets(length);
    int* keys = allocate_keys(length);
    record_t* records = allocate_records(length);

    if (!offsets || !keys || !records) {
        // If any of the allocations failed, print an error message and free what was allocated
        deallocate_arrays(keys, records);
        return NULL;
    }

    void* result[] = {&keys, &records};

    // Ensure total memory usage does not exceed 1 MB
    printf("Total memory usage: %d bytes.\n", (long) (sizeof(long) * (length + 1)) + sizeof(int) * length + sizeof(record_t) * length);

    return result;
}
