#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a structure for the record and its metadata
typedef struct {
    int key;
    void* metadata;
} Record;

// Structure to manage memory allocation for records
typedef struct {
    Record** records;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} RecordManager;

RecordManager* record_manager_init(size_t initial_capacity) {
    RecordManager* manager = malloc(sizeof(RecordManager));
    manager->records = malloc(initial_capacity * sizeof(Record*));
    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void record_manager_free(RecordManager* manager) {
    for (size_t i = 0; i < manager->count; i++) {
        free(manager->records[i]->metadata);
    }
    free(manager->records);
    free(manager);
    pthread_mutex_destroy(&manager->mutex);
}

int record_manager_add_record(RecordManager* manager, int key, size_t metadata_size) {
    if (manager->count >= manager->capacity) {
        // Double the capacity when full
        Record** new_records = realloc(manager->records, 2 * manager->capacity * sizeof(Record*));
        if (!new_records) return -1; // Out of memory
        manager->records = new_records;
        manager->capacity *= 2;
    }
    Record* record = malloc(sizeof(Record));
    record->key = key;
    record->metadata = malloc(metadata_size);
    pthread_mutex_lock(&manager->mutex);
    manager->records[manager->count++] = record;
    pthread_mutex_unlock(&manager->mutex);
    return 0; // Success
}

int record_manager_serialize(RecordManager* manager, FILE* file) {
    for (size_t i = 0; i < manager->count; i++) {
        Record* record = manager->records[i];
        fwrite(&record->key, sizeof(int), 1, file);
        size_t metadata_size = strlen((char*)record->metadata) + 1;
        fwrite(&metadata_size, sizeof(size_t), 1, file);
        fwrite(record->metadata, 1, metadata_size, file);
    }
    return 0; // Success
}

int record_manager_deserialize(RecordManager* manager, FILE* file) {
    Record** records = malloc(manager->count * sizeof(Record*));
    for (size_t i = 0; i < manager->count; i++) {
        Record* record = &records[i];
        fread(&record->key, sizeof(int), 1, file);
        size_t metadata_size;
        fread(&metadata_size, sizeof(size_t), 1, file);
        record->metadata = malloc(metadata_size);
        fread(record->metadata, 1, metadata_size, file);
    }
    free(manager->records);
    manager->records = records;
    return 0; // Success
}

int main() {
    RecordManager* manager = record_manager_init(4);

    int key = 10;
    size_t metadata_size = strlen("Metadata") + 1;
    record_manager_add_record(manager, key, metadata_size);

    FILE* file = fopen("records", "wb");
    if (!file) return -1; // Error opening file
    record_manager_serialize(manager, file);
    fclose(file);

    return 0;
}
