        node->next = NULL;
        node->key = i + 1;
        node->active = false;
        if (i > 0)
            nodes[i - 1]->next = node;
        nodes[i] = node;
    }
}

void activateNodes(Node** nodes, int N) {
    for (int i = 0; i < N; i++) {
        Node* node = nodes[i];
        if ((node->key & 1) == 0) // even key
            node->active = true;
    }
}

int countActiveNodes(Node** nodes, int N) {
    int activeCount = 0;
    for (int i = 0; i < N; i++) {
        Node* node = nodes[i];
        if (node->active)
            activeCount++;
    }
    return activeCount;
