record* manage_memory(int max_records, void (*record_creator)(int, void*, record*), 
                       void (*offset_generator)(int, void*, long*), 
                       void (*value_generator)(int, void*, int*)) {

    if (max_records <= 0) {
        return NULL;
    }

    // Allocate memory for an array of offsets
    long* offsets = (long*)malloc(max_records * sizeof(long));
    if (!offsets) {
        errno = ENOMEM;
        return NULL;
    }

    // Allocate memory for an array of keys
    int* keys = (int*)malloc(max_records * sizeof(int));
    if (!keys) {
        free(offsets);
        errno = ENOMEM;
        return NULL;
    }

    // Allocate memory for an array of records
    record* records = (record*)malloc(max_records * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        errno = ENOMEM;
        return NULL;
    }

    for (int i = 0; i < max_records; i++) {
        // Generate offset, key and value
        long* offset_ptr = &offsets[i];
        int* key_ptr = &keys[i];
        int* value_ptr = &records[i].value;

        (*offset_generator)(i, NULL, offset_ptr);
        (*record_creator)(i, NULL, &records[i]);
        (*value_generator)(i, NULL, value_ptr);
    }

    // Free allocated memory
    free(offsets);
    free(keys);

    return records;
}

