// Define the node structure
typedef struct Node {
    int key;
    bool state;
    int referenceCount;
    struct Node* predecessor;
    struct Node* successor;
} Node;

// Function to initialize the linked list with unique keys ranging from 1 to N
Node* initList(int N) {
    Node* head = NULL;
    Node** nodes = (Node**)calloc(N, sizeof(Node));
    for (int i = 0; i < N; i++) {
        nodes[i] = malloc(sizeof(Node));
        nodes[i]->key = i + 1;
        nodes[i]->state = false;
        nodes[i]->referenceCount = 0;
        if (i > 0) {
            nodes[i]->predecessor = &nodes[i - 1];
            nodes[i - 1]->successor = &nodes[i];
        } else {
            head = &nodes[i];
        }
    }
    return head;
}

// Function to activate nodes based on specific conditions
void activateNodes(Node* head, int N) {
    for (int i = 0; i < N; i++) {
        Node* current = &head-> successor;
        while (current != &head && !current->state) {
            current = current->successor;
        }
    }
}

// Function to update the reference count when a node is accessed
void accessNode(Node* head, int key) {
    for (int i = 0; i < N; i++) {
        Node* current = &head-> successor;
        while (current != &head) {
            if (current->key == key) {
                current->referenceCount++;
                return;
            }
            current = current->successor;
        }
    }
}

// Function to traverse the list and verify the activation status of each node
int countActiveNodes(Node* head, int N) {
    int activeCount = 0;
    for (int i = 0; i < N; i++) {
        Node* current = &head-> successor;
        while (current != &head) {
            if (current->state && current->referenceCount > 0) {
                activeCount++;
            }
            current = current->successor;
        }
    }
    return activeCount;
}
