struct node {
    struct node* next;
    int key;
    bool active;
    long timestamp;
};

int activate_nodes(struct node** head, int n) {
    if (*head == NULL) return 0;

    struct node* curr = *head;
    while (curr != NULL) {
        if (curr->key % 2 == 0 && !curr->active) {
            curr->active = true;
            curr->timestamp = time(NULL);
            printf("Node with key %d activated at timestamp %ld.\n", curr->key, curr->timestamp);
        }
        curr = curr->next;
    }

    int active_count = 0;
    curr = *head;
    while (curr != NULL) {
        if (curr->active) active_count++;
        curr = curr->next;
    }
    return active_count;
}

int init_nodes(struct node** head, int n) {
    *head = NULL;

    for (int i = 1; i <= n; i++) {
        struct node* new_node = (struct node*)malloc(sizeof(struct node));
        new_node->key = i;
        new_node->active = false;
        new_node->next = (*head);
        (*head) = new_node;
    }

    return 0;
}

int main() {
    int n = 10; // number of nodes
    struct node* head = NULL;

    init_nodes(&head, n);

    int active_count = activate_nodes(&head, n);

