Entry* initializeSystem(int numEntries) {
    // Allocate memory for the system
    Entry* entries = (Entry*)malloc(numEntries * sizeof(Entry));
    int* nodes = (int*)malloc((numEntries + 1) * sizeof(int)); // Reserve space for node pointers
    int* values = (int*)malloc(numEntries * sizeof(int));

    return entries;
}

void loadInitialData(Entry* entries, FILE* file, int numEntries) {
    char line[1024];
    int i = 0;

    while (fgets(line, sizeof(line), file)) {
        // Parse the line and extract node identifier and value
        int nodeID;
        int val;
        sscanf(line, "%d,%d", &nodeID, &val);

        // Map the data to the entry structures
        entries[i].node = &nodes[nodeID];
        entries[i].value = val;

        i++;
    }
}

void populateEntries(Entry* entries, int numEntries) {
    for (int i = 0; i < numEntries; i++) {
        // Populate node pointers and values in the entry structures
        nodes[*(entries[i].node)] = i;
    }
}

// Example usage:
int main() {
    FILE* file = fopen("data.csv", "r");
    int numEntries = 1000000;

    Entry* entries = initializeSystem(numEntries);
    loadInitialData(entries, file, numEntries);

    populateEntries(entries, numEntries);

    fclose(file);

    return 0;
}
