    if (!records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        return NULL;
    }

    srand(time(NULL)); // Seed random number generator

    for (int i = 0; i < numRecords; i++) {
        Record* record = &records[i];
        int randomValue = rand() % 100 + 1; // Random value between 1 and 100
        record->value = randomValue;

        long* offset = (long*)malloc(sizeof(long));
        if (!offset) {
            fprintf(stderr, "Memory allocation failed for offsets\n");
            return NULL;
        }
        *offset = i % offsetSize; // Assign a unique offset value to each record
        record->offset = offset;
    }

    return records;
}

void freeRecords(Record* records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        Record* record = &records[i];
        free(record->offset);
    }
    free(records);
}

int main() {
    int numRecords = 10;
    int offsetSize = 5;

    long* offsets = (long*)malloc(offsetSize * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        return -1;
    }

    // Initialize offset values...
    for (int i = 0; i < offsetSize; i++) {
        offsets[i] = i;
    }

    Record* records = initRecords(numRecords, offsets, offsetSize);
    if (!records) {
        return -1;
    }

    freeRecords(records, numRecords);

    return 0;
}
