record_t* processDataAndExpandGraph(int*** graphInitParams, int numInitParams) {
    record_t* records = NULL;
    int recordsCount = 0;

    // Helper function to validate and store a list of integers and floating-point numbers from standard input
    int* storeInput() {
        int* values = NULL;
        int valuesCount = 0;

        while (1) {
            float f;
            scanf("%f", &f);

            if (feof(stdin)) break;

            // Validate the input to prevent storage of invalid data types
            if (!finite(f)) {
                printf("Invalid input. Please enter a valid number.\n");
                return NULL;
            }

            values = realloc(values, ++valuesCount * sizeof(int));
            int v = (int)f;
            values[valuesCount - 1] = v;
        }

        return values;
    }

    // Helper function to set the value of each record's int field to a random value within a given range
    void setRandomValues(record_t* records, int startValue, int endValue) {
        for (int i = 0; i < recordsCount; ++i) {
            records[i].value = rand() % (endValue - startValue + 1) + startValue;
        }
    }

    // Helper function to find and print the largest integer in the array
    void printLargestValue(record_t* records) {
        int max = INT_MIN;

        for (int i = 0; i < recordsCount; ++i) {
            if (records[i].value > max) {
                max = records[i].value;
            }
        }

        printf("The largest integer is %d.\n", max);
    }

    while (1) {
        int* values = storeInput();

        // Validate and process the input
        if (!values) continue;

        for (int i = 0; i < recordsCount; ++i) {
            if (records[i].key >= *values[0] && records[i].key <= *values[1]) {
                printf("Key already exists. Please enter a unique key.\n");
                free(values);
                return NULL;
            }
        }

        // Dynamically allocate memory for new records
        record_t* newRecords = realloc(records, ++recordsCount * sizeof(record_t));
        if (!newRecords) {
            printf("Memory allocation failed.\n");
            free(values);
            return NULL;
        }

        records = newRecords;
    }

    return records;
}
