        keys[i] = rand() % 100;
        offsets[i] = rand();
        records[i].key = keys[i];
        records[i].offset = offsets[i];
    }

    // Initialize u_char array for IP addresses
    uint8_t* ip_addresses = (uint8_t*)malloc(num_hosts * sizeof(uint8_t));

    // Resolve hostnames and populate IP addresses
    for (int i = 0; i < num_hosts; i++) {
        struct hostent* host = gethostbyname(hostnames[i]);
        if (!host) {
            free(ip_addresses);
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }
        memcpy(&ip_addresses[i], host->h_addr, sizeof(uint8_t));
    }

