void* init_and_allocate(int n, int min_val, int max_val, int hash_table_size) {
    // Allocate memory for offset values array
    long* offsets = (long*)malloc(n * sizeof(long));

    // Initialize the offset values with random numbers
    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        offsets[i] = min_val + rand() % ((max_val - min_val) + 1);
    }

    // Allocate memory for keys array
    int* keys = (int*)malloc(n * sizeof(int));

    // Initialize the key values with random numbers
    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        keys[i] = min_val + rand() % ((max_val - min_val) + 1);
    }

    // Validate hash table size is prime and within memory budget
    if (!is_prime(hash_table_size) || sizeof(record_t) * n > (size_t)memory_budget) {
        free(offsets);
        free(keys);

        // Handle memory allocation failure gracefully
        return NULL;
    }

    // Allocate memory for record array
    record_t* records = (record_t*)malloc(n * sizeof(record_t));

    // Initialize the record values with random numbers
    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        records[i].key = min_val + rand() % ((max_val - min_val) + 1);
    }

    return records;
}

// Custom hash function to map keys to unique indices in the hash table
size_t custom_hash(int key, int hash_table_size) {
    return (size_t)(key ^ (hash_table_size - 1));
}

// Validate if a number is prime
int is_prime(int num) {
    if (num <= 1) {
        return 0;
    }
    for (int i = 2; i * i <= num; i++) {
        if (num % i == 0) {
            return 0;
        }
    }
    return 1;
}
