void* query_records(int threshold, int max_age, int max_weight_sum) {
    for (int i = 0; i < record_count; i++) {
        record_t* record = records[i];
        if ((record->timestamp + (long)max_age) > rand() && 
            record->value <= max_weight_sum &&
            record->weight * record->value <= threshold)
            return record;
    }
    return NULL;
}

void update_metrics(int id, int value) {
    pthread_mutex_lock(&mutex);
    if (!records) {
        records = (record_t**)malloc(sizeof(record_t*)*capacity);
        cached_records = (record_t**)((char*)malloc(sizeof(record_t*)*capacity));
        record_count = 0;
    }
    for (int i = 0; i < record_count; i++) {
        if (records[i]->id == id) {
            records[i]->value = value;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void free_records() {
    for (int i = 0; i < record_count; i++) {
        free(records[i]);
    }
    free(records);
    free(cached_records);
}
