#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Custom thread-safe priority queue implementation
typedef struct {
    int key;
    long offset;
    unsigned int timestamp;
    int status;
} Record;

struct {
    Record* records;
    long* offsets;
    int* keys;
    time_t* timestamps;
    char* statuses;
} collection = {NULL, NULL, NULL, NULL, NULL};

void init_collection() {
    // Allocate memory for arrays
    collection.records = (Record*)malloc(sizeof(Record) * 1000);
    collection.offsets = (long*)malloc(sizeof(long) * 1000);
    collection.keys = (int*)malloc(sizeof(int) * 1000);
    collection.timestamps = (time_t*)malloc(sizeof(time_t) * 1000);
    collection.statuses = (char*)malloc(sizeof(char) * 100);

    // Initialize arrays
    memset(collection.records, 0, sizeof(Record) * 1000);
    memset(collection.offsets, 0, sizeof(long) * 1000);
    memset(collection.keys, 0, sizeof(int) * 1000);
    memset(collection.timestamps, 0, sizeof(time_t) * 1000);
    memset(collection.statuses, 0, sizeof(char) * 100);

    // Initialize collection
    collection.records[0].key = -1;
}

void add_record(long offset, int key, time_t timestamp, char status) {
    if (collection.records == NULL || collection.offsets == NULL || collection.keys == NULL || collection.timestamps == NULL || collection.statuses == NULL) {
        printf("Error: Collection not initialized.\n");
        return;
    }

    // Check for duplicate offset
    int i;
    for (i = 0; i < sizeof(collection.records) / sizeof(Record); i++) {
        if (collection.offsets[i] == offset && collection.records[i].key != -1) {
            printf("Error: Duplicate offset detected.\n");
            return;
        }
    }

    // Get the next available record index
    int idx = 0;
    while (idx < sizeof(collection.records) / sizeof(Record)) {
        if (collection.records[idx].key == -1) {
            break;
        }
        idx++;
    }

    // Add new record to collection
    if (idx >= sizeof(collection.records) / sizeof(Record)) {
        printf("Error: No available records in the collection.\n");
        return;
    }

    collection.records[idx].key = key;
    collection.offsets[idx] = offset;
    collection.timestamps[idx] = timestamp;
    collection.statuses[idx] = status;

    // Sort the records by timestamp and status
    for (i = 0; i < sizeof(collection.records) / sizeof(Record); i++) {
        for (int j = i + 1; j < sizeof(collection.records) / sizeof(Record); j++) {
            if (collection.timestamps[i] > collection.timestamps[j] || (collection.timestamps[i] == collection.timestamps[j] && strcmp(&collection.statuses[i], &collection.statuses[j]) > 0)) {
                Record temp = collection.records[i];
                long offsetTemp = collection.offsets[i];
                int keyTemp = collection.keys[i];
                time_t timestampTemp = collection.timestamps[i];
                char statusTemp = collection.statuses[i];

                collection.records[i] = collection.records[j];
                collection.offsets[i] = collection.offsets[j];
                collection.keys[i] = collection.keys[j];
                collection.timestamps[i] = collection.timestamps[j];
                collection.statuses[i] = collection.statuses[j];

                collection.records[j] = temp;
                collection.offsets[j] = offsetTemp;
                collection.keys[j] = keyTemp;
                collection.timestamps[j] = timestampTemp;
                collection.statuses[j] = statusTemp;
            }
        }
    }

    // Log the addition of new record
    FILE* logFile = fopen("record_log.txt", "a");
    fprintf(logFile, "Record added: offset=%ld, key=%d, timestamp=%ld, status='%c'\n", offset, key, timestamp, status);
    fclose(logFile);
}

void remove_record(long offset) {
    if (collection.records == NULL || collection.offsets == NULL) {
        printf("Error: Collection not initialized.\n");
        return;
    }

    // Find the record to be removed
    int i;
    for (i = 0; i < sizeof(collection.records) / sizeof(Record); i++) {
        if (collection.offsets[i] == offset && collection.records[i].key != -1) {
            break;
        }
    }

    if (i >= sizeof(collection.records) / sizeof(Record)) {
        printf("Error: Record not found in the collection.\n");
        return;
    }

    // Mark the record as inactive
    collection.statuses[i] = 'I';

    // Log the removal of record
    FILE* logFile = fopen("record_log.txt", "a");
    fprintf(logFile, "Record removed: offset=%ld\n", offset);
    fclose(logFile);
}

void free_collection() {
    if (collection.records == NULL || collection.offsets == NULL || collection.keys == NULL || collection.timestamps == NULL) {
        printf("Error: Collection not initialized.\n");
        return;
    }

    // Free the memory allocated for arrays
    free(collection.records);
    free(collection.offsets);
    free(collection.keys);
    free(collection.timestamps);

    // Set the collection to an uninitialized state
    collection.records = NULL;
    collection.offsets = NULL;
    collection.keys = NULL;
    collection.timestamps = NULL;
}

int main() {
    init_collection();

    add_record(1, 10, time(NULL), 'A');
    add_record(2, 20, time(NULL) + 1000, 'P');
    add_record(3, 30, time(NULL) + 2000, 'I');

    remove_record(2);

    free_collection();

    return 0;
}
