typedef struct {
    int value;
    long *offset;
    char **label;
} record;

record* init_records(int count, long *offsets, char **labels) {
    record *records = (record *)malloc(count * sizeof(record));
    if (!records) {
        printf("Memory allocation failed for records.\n");
        return NULL;
    }

    int i;
    srand(time(NULL)); // seed random number generator
    for (i = 0; i < count; i++) {
        records[i].value = rand() % 100; // generate a random value within the range [0, 100)
        records[i].offset = &offsets[i];
        records[i].label = &labels[i];
    }

    return records;
}

long* init_offsets(int count) {
    long *offsets = (long *)malloc(count * sizeof(long));
    if (!offsets) {
        printf("Memory allocation failed for offsets.\n");
        return NULL;
    }

    int i;
    for (i = 0; i < count; i++) {
        offsets[i] = i;
    }

    return offsets;
}

char** init_labels(int count) {
    char **labels = (char **)malloc(count * sizeof(char *));
    if (!labels) {
        printf("Memory allocation failed for labels.\n");
        return NULL;
    }

    int i;
    for (i = 0; i < count; i++) {
        labels[i] = (char *)malloc(strlen("label") + 1);
        sprintf(labels[i], "label%d", i);
    }

    return labels;
}

int main() {
    int count = 10;
    long *offsets = init_offsets(count);
    char **labels = init_labels(count);
    record *records = init_records(count, offsets, labels);

    // free allocated memory
    for (int i = 0; i < count; i++) {
        free(labels[i]);
    }
    free(labels);
    free(offsets);
    free(records);

    return 0;
}
