typedef struct {
    char* key;
    void* value;
} ConfigOption;

typedef struct {
    size_t capacity;
    ConfigOption** options;
} ConfigFile;

ConfigFile* config_file_alloc(size_t initial_capacity) {
    ConfigFile* file = (ConfigFile*)malloc(sizeof(ConfigFile));
    file->capacity = initial_capacity;
    file->options = (ConfigOption**)malloc(file->capacity * sizeof(ConfigOption*));
    return file;
}

void config_file_free(ConfigFile* file) {
    for(size_t i = 0; i < file->capacity; i++) {
        if(file->options[i] != NULL) {
            free(file->options[i]->key);
            free(file->options[i]->value);
            free(file->options[i]);
        }
    }
    free(file->options);
    free(file);
}

void config_file_add_option(ConfigFile* file, char* key, void* value, size_t length) {
    ConfigOption* option = (ConfigOption*)malloc(sizeof(ConfigOption));
    option->key = malloc((length + 1) * sizeof(char));
    strncpy(option->key, key, length);
    option->key[length] = '\0';
    option->value = value;
    file->options[file->capacity++] = option;
}

void config_file_serialize(const ConfigFile* file, char** buffer) {
    *buffer = (char*)malloc((file->capacity * 1024 + 1) * sizeof(char));
    for(size_t i = 0; i < file->capacity; i++) {
        sprintf(buffer[i], "%s:%p\n", file->options[i]->key, file->options[i]->value);
    }
    buffer[file->capacity] = NULL;
}

int main() {
    ConfigFile* config_file = config_file_alloc(10);
    // Add options
    config_file_add_option(config_file, "key1", (void*)123, 4);
    config_file_add_option(config_file, "bool_key", (void*)true, 9);
    config_file_add_option(config_file, "string_key", "value", 8);

    char* buffer;
    config_file_serialize(config_file, &buffer);
    printf("%s\n", buffer);

    free(buffer);
    config_file_free(config_file);
    return 0;
}

