        strings[i] = malloc((maxStringLen + 1) * sizeof(char));
        item* itemPtr = malloc(sizeof(item));

        // Validate string length and fill with random characters
        srand(time(NULL) + i); // Ensure each string is unique
        for (size_t j = 0; j < maxStringLen; j++) {
            strings[i][j] = (char)(rand() % ('Z' - 'A' + 1)) + 'A';
            if (j == maxStringLen - 1) strings[i][j] = '\0'; // Terminate the string
        }
        itemPtr->i = rand();
        itemPtr->d = doubles[i];
        strcpy(itemPtr->s, strings[i]);

        items[i] = itemPtr;
    }

    return items;
}
