#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int x;
    int y;
    float distance;
} point;

typedef struct {
    double value;
    int timestamp;
    enum { NEW, UPDATED, DELETED } status;
} metric;

typedef struct {
    point *points;
    int numPoints;
    metric *metrics;
    int numMetrics;
} trajectory;

void* manageAndProcessTrajectories(void* arg) {
    // Initialize thread-safe variables
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    int totalMetrics = 0;
    int maxNumPoints = 10000; // Default maximum number of points per trajectory

    while (1) {
        // Check for new metrics to add
        if (totalMetrics < 1000000) { // Add up to 1 million metrics
            pthread_mutex_lock(&mutex);
            int newMetrics = getNewMetrics(); // Call external function to determine the number of new metrics to add
            for (int i = 0; i < newMetrics; i++) {
                metric *newMetric = (metric*)malloc(sizeof(metric));
                newMetric->timestamp = totalMetrics;
                newMetric->value = rand() / (double)RAND_MAX; // Generate random value
                int status = getStatus(); // Call external function to determine the status (NEW, UPDATED, DELETED)
                newMetric->status = (enum { NEW, UPDATED, DELETED }) status;

                // Add the new metric to the existing array and update the total number of metrics
                if (totalMetrics >= sizeof(metric) * 10000) {
                    metric **metricsArray = (metric**)realloc(metricsArray, (totalMetrics + maxNumPoints) * sizeof(metric*));
                    for (int j = totalMetrics; j < totalMetrics + newMetrics; j++) {
                        metricsArray[j] = (metric*)malloc(sizeof(metric));
                        *metricsArray[j] = *newMetric;
                    }
                    totalMetrics += newMetrics;
                } else {
                    // Handle memory allocation failure
                    printf("Memory allocation failed\n");
                    break;
                }

                pthread_mutex_unlock(&mutex);
            }
        }

        // Process and update existing trajectories
        for (int i = 0; i < totalMetrics; i++) {
            trajectory *trajectory = getTrajectory(i); // Call external function to retrieve the trajectory
            if (trajectory->numPoints < maxNumPoints) { // Check if the trajectory has reached its maximum number of points
                point *newPoint = (point*)malloc(sizeof(point));
                newPoint->x = rand() % 100; // Generate random x-coordinate
                newPoint->y = rand() % 100; // Generate random y-coordinate
                newPoint->distance = sqrt(pow(newPoint->x, 2) + pow(newPoint->y, 2)); // Calculate the distance using the Pythagorean theorem

                trajectory->numPoints++;
                int* pointsArray = (int*)realloc(trajectory->points, trajectory->numPoints * sizeof(point));
                for (int j = trajectory->numPoints - 1; j > 0; j--) {
                    pointsArray[j] = pointsArray[j-1];
                }
                pointsArray[0] = *newPoint;
            }

            // Update the timestamp and status of each metric in the trajectory
            for (int j = 0; j < trajectory->numMetrics; j++) {
                if (trajectory->metrics[j].timestamp <= i) { // Check if the metric is older than the current iteration
                    trajectory->metrics[j].status = UPDATED;
