// Define a structure to hold bundle record
typedef struct {
    int key;
    long offset;
    int value;
} BundleRecord;

// Define a structure for the bundle resource
typedef struct {
    int max_size; // maximum size of the bundle
    int current_size; // current size of the bundle
    BundleRecord* records; // array to hold bundle records
    pthread_mutex_t lock; // lock for thread-safe access
} BundleResource;

// Function to create a new bundle resource
BundleResource* create_bundle_resource(int max_size) {
    BundleResource* bundle = (BundleResource*)malloc(sizeof(BundleResource));
    bundle->max_size = max_size;
    bundle->current_size = 0;
    bundle->records = (BundleRecord*)calloc(max_size, sizeof(BundleRecord));
    pthread_mutex_init(&bundle->lock, NULL);
    return bundle;
}

// Function to add a new record to the bundle resource
void add_record(BundleResource* bundle, int key, long offset, int value) {
    pthread_mutex_lock(&bundle->lock);
    if (bundle->current_size >= bundle->max_size) {
        // resize the bundle if it's full
        BundleResource* new_bundle = create_bundle_resource(bundle->max_size * 2);
        memcpy(new_bundle->records, bundle->records, bundle->max_size * sizeof(BundleRecord));
        free(bundle->records);
        bundle->records = new_bundle->records;
        free(bundle);
        bundle = new_bundle;
    }
    BundleRecord* record = &bundle->records[bundle->current_size];
    record->key = key;
    record->offset = offset;
    record->value = value;
    bundle->current_size++;
    pthread_mutex_unlock(&bundle->lock);
}

// Function to release all allocated resources
void free_bundle_resource(BundleResource* bundle) {
    pthread_mutex_lock(&bundle->lock);
    if (bundle->current_size > 0) {
        // free individual records first
        for (int i = 0; i < bundle->current_size; i++) {
            free(&bundle->records[i]);
        }
        // then free the array of records
        free(bundle->records);
    }
    pthread_mutex_unlock(&bundle->lock);
    free(bundle);
}

// Function to print the contents of the bundle resource
void print_bundle(BundleResource* bundle) {
    pthread_mutex_lock(&bundle->lock);
    for (int i = 0; i < bundle->current_size; i++) {
        BundleRecord* record = &bundle->records[i];
        printf("Key: %d, Offset: %ld, Value: %d\n", record->key, record->offset, record->value);
    }
    pthread_mutex_unlock(&bundle->lock);
}

int main() {
    // Create a new bundle resource
    BundleResource* bundle = create_bundle_resource(10);

    // Add some records to the bundle
    add_record(bundle, 1, 1000, 5);
    add_record(bundle, 2, 2000, 7);
    add_record(bundle, 3, 3000, 9);

    // Print the contents of the bundle
    print_bundle(bundle);

    // Release all allocated resources
    free_bundle_resource(bundle);

    return 0;
}
