typedef struct Key {
    int* arr;
    int size;
} Key;

typedef struct Record {
    int** ptrArr;
    int size;
} Record;

void init_and_populate(struct json_object *config) {
    // Parse configuration from JSON file
    int recordSize = json_object_get_int(config, "record_size");
    int keySize = json_object_get_int(config, "key_size");
    int offsetSize = json_object_get_int(config, "offset_size");

    // Initialize structures with zeroed memory
    Offset* offsets = (Offset*)calloc(recordSize, sizeof(Offset));
    Key* keys = (Key*)calloc(keySize, sizeof(Key));
    Record* records = (Record*)calloc(recordSize, sizeof(Record));

    // Populate structures with random data within specified range
    for (int i = 0; i < recordSize; i++) {
        records[i].size = keySize;
        records[i].ptrArr = (int**)malloc(keySize * sizeof(int*));
        for (int j = 0; j < keySize; j++) {
            keys[j].arr = (int*)calloc(1, sizeof(int));
            keys[j].size = offsetSize;
            offsets[i].arr = (long*)calloc(offsetSize, sizeof(long));
            offsets[i].size = offsetSize;
        }
    }

    // Log memory allocation and deallocation
    for (int i = 0; i < recordSize; i++) {
        log_info("Allocated %p for Record[%d]", records[i].ptrArr, i);
        log_info("Deallocated %p for Record[%d]", keys[i].arr, i);
    }

    // Log configuration and initialization
    log_info("Initialized with %d Records, %d Keys, and %d Offsets", recordSize, keySize, offsetSize);

    // Release memory
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    // Initialize JSON parser
    json_object *config = json_object_from_file("config.json");

    // Call the initialization function with parsed configuration
    init_and_populate(config);

    return 0;
}
