    if (!record) {
        printf("Error: failed to allocate memory for record\n");
        return NULL;
    }
    record->value = rand() % 100; // Initialize with a random value between 0 and 99
    return record;
}

void free_record(record_t* record) {
    free(record);
}

struct data_store {
    int* keys;
    long* offsets;
    record_t** records;
    record_t* head;
    pthread_mutex_t lock;
};

data_store* create_data_store(int num_records) {
    data_store* store = (data_store*)malloc(sizeof(data_store));
    if (!store) {
        printf("Error: failed to allocate memory for data store\n");
        return NULL;
    }

    store->keys = (int*)malloc(num_records * sizeof(int));
    if (!store->keys) {
        free(store);
        printf("Error: failed to allocate memory for keys array\n");
        return NULL;
    }

    store->offsets = (long*)malloc(num_records * sizeof(long));
    if (!store->offsets) {
        free(store->keys);
        free(store);
        printf("Error: failed to allocate memory for offsets array\n");
        return NULL;
    }

    store->records = (record_t**)malloc(num_records * sizeof(record_t*));
    if (!store->records) {
        free(store->offsets);
        free(store->keys);
        free(store);
        printf("Error: failed to allocate memory for records array\n");
        return NULL;
    }

    for (int i = 0; i < num_records; i++) {
        store->records[i] = create_record();
        if (!store->records[i]) {
            // Handle error
        }
    }

    store->head = NULL;
    pthread_mutex_init(&store->lock, NULL);
    return store;
}

void destroy_data_store(data_store* store) {
    for (int i = 0; i < store->num_records; i++) {
        free_record(store->records[i]);
    }
    free(store->offsets);
    free(store->keys);
    free(store->records);
    pthread_mutex_destroy(&store->lock);
    free(store);
}
