#include <stdlib.h>
#include <stdio.h>

typedef struct {
    long* integer_ptr;
    int key;
} Record;

Record* manage_memory(int n, int m, int k) {
    // Step 1: Allocate memory for n long integers
    long* long_integers = (long*)malloc(n * sizeof(long));
    if (!long_integers) {
        return NULL; // Handle allocation failure
    }
    for (int i = 0; i < n; i++) {
        long_integers[i] = i;
    }

    // Step 2: Allocate memory for m integer keys and check for duplicates
    int* integer_keys = (int*)malloc(m * sizeof(int));
    if (!integer_keys) {
        free(long_integers);
        return NULL; // Handle allocation failure
    }
    bool key_duplicates[m] = {false};
    for (int i = 0; i < m; i++) {
        int key;
        do {
            key = rand() % (m * 2); // Seedable random number generator
        } while (key_duplicates[key]);
        integer_keys[i] = key;
        key_duplicates[key] = true;
    }

    // Step 3: Create an array of k records and initialize them
    Record* records = (Record*)malloc(k * sizeof(Record));
    if (!records) {
        free(long_integers);
        free(integer_keys);
        return NULL; // Handle allocation failure
    }
    for (int i = 0; i < k; i++) {
        records[i].integer_ptr = &long_integers[i % n];
        int key_index = i % m;
        records[i].key = integer_keys[key_index];
    }

    // Step 4: Free allocated memory
    free(long_integers);
    free(integer_keys);

    return records;
}

int main() {
    Record* records = manage_memory(1000000, 1000000, 1000000);
    if (!records) {
        printf("Memory allocation failed.\n");
    } else {
        // Process the allocated records
        for (int i = 0; i < 10; i++) {
            Record record = records[i];
            printf("Record %d: Integer value = %ld, Key = %d\n", i, record.integer_ptr[0], record.key);
        }
    }

    return 0;
}
