#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    char* buffer;
} Record;

Record* createRecords(int count, int min_value, int max_value) {
    srand(time(NULL)); // seed random number generator

    Record* records = (Record*)malloc(count * sizeof(Record));

    for (int i = 0; i < count; i++) {
        Record record;

        record.value = rand() % ((max_value - min_value) + 1) + min_value;

        char buffer[10];
        sprintf(buffer, "record_%d", i);
        record.buffer = (char*)malloc(strlen(buffer) + 1);
        strcpy(record.buffer, buffer);

        records[i] = record;
    }

    return records;
}

void freeRecords(Record* records, int count) {
    for (int i = 0; i < count; i++) {
        if (records[i].buffer != NULL) {
            free(records[i].buffer);
        }
    }

    free(records);
}
