#define MAX_SENSOR_READINGS 1000

typedef struct {
    uint64_t timestamp;
    float measurement;
    int quality_flag;
} sensor_data;

typedef struct {
    sensor_data data[10]; // Assuming a maximum of 10 sensor_data objects per structure
    size_t count;
} sensor_reading;

sensor_reading* allocate_sensor_readings(const char* filename, int max_count) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        // Handle file access error
        fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        return NULL;
    }

    sensor_reading* readings = (sensor_reading*)calloc(max_count, sizeof(sensor_reading));
    if (!readings) {
        // Handle memory allocation error
        fclose(file);
        fprintf(stderr, "Error allocating memory for sensor_readings.\n");
        return NULL;
    }

    size_t reading_count = 0;

    while (fscanf(file, "{%" PRIu64 ",%.2f,%d}\n", &readings[reading_count].data[0].timestamp,
                    &readings[reading_count].data[0].measurement,
                    &readings[reading_count].data[0].quality_flag) == 3 && reading_count < max_count) {
        readings[reading_count].count = 1;
        for (int i = 1; i < 10; i++) {
            if (fscanf(file, ",{%" PRIu64 ",%.2f,%d}\n", &readings[reading_count].data[i].timestamp,
                        &readings[reading_count].data[i].measurement,
                        &readings[reading_count].data[i].quality_flag) != 3) {
                break;
            }
        }

        if (i < 10) {
            // Handle malformed data entry
            fclose(file);
            free(readings);
            return NULL;
        }

        reading_count++;
    }

    fclose(file);

    return readings;
}
