#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>

#define MAX_RECORDS 1000
#define MAX_KEY 1000
#define PRIORITY_WEIGHT 3.0
#define STATUS_THRESHOLD 0.5

typedef struct record {
    int value;
    float priority;
    char status;
} Record;

typedef struct node {
    Record data;
    struct node* next;
} Node;

Node* head = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Initialize a new record with random values
void initRecord(Record* record) {
    record->value = rand() % 1000;
    record->priority = (float)record->value / PRIORITY_WEIGHT + (rand() % 10) / 100.0;
    record->status = (char)((record->priority > STATUS_THRESHOLD) ? 'H' : 'L');
}

// Add a new record to the data store
void addRecord(Record* record) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = *record;
    newNode->next = head;
    pthread_mutex_lock(&mutex);
    head = newNode;
    pthread_mutex_unlock(&mutex);
}

// Filter records by key, status, and priority range
void queryRecords(int minPriority, int maxPriority, char minStatus, char maxStatus) {
    Node* current = head;
    while (current != NULL) {
        Record record = current->data;
        if ((record.value >= 0 && record.value <= MAX_KEY) &&
            (record.priority >= minPriority && record.priority <= maxPriority) &&
            (record.status >= minStatus && record.status <= maxStatus)) {
            printf("Record: %d, %.2f, %c\n", record.value, record.priority, record.status);
        }
        current = current->next;
    }
}

// Persistence layer for periodic disk storage
void persistRecords() {
    FILE* file = fopen("datastore.bin", "wb");
    if (file != NULL) {
        Node* current = head;
        while (current != NULL) {
            fwrite(&current->data, sizeof(Record), 1, file);
            current = current->next;
        }
        fclose(file);
    }
}

int main() {
    srand(time(NULL));

    for (int i = 0; i < MAX_RECORDS; i++) {
        Record record;
        initRecord(&record);
        addRecord(&record);
    }

    queryRecords(0.0, 1.0, 'L', 'H');

    persistRecords();

    return 0;
}
