#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int key;
    int value;
    struct record* next;
} record;

record* root = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int num_insertions = 0, num_deletions = 0, num_lookups = 0;

void insert(int key, int value) {
    pthread_mutex_lock(&lock);
    record* new_record = (record*)malloc(sizeof(record));
    new_record->key = key;
    new_record->value = value;
    new_record->next = root;
    if (!root) root = new_record;
    else {
        record* prev = NULL, *curr = root;
        while (curr && curr->key < key) {
            prev = curr;
            curr = curr->next;
        }
        if (curr && curr->key == key) {
            // Update existing record
            curr->value = value;
        } else {
            prev->next = new_record;
            new_record->next = curr;
        }
    }
    pthread_mutex_unlock(&lock);
    num_insertions++;
}

void delete(int key) {
    pthread_mutex_lock(&lock);
    record* curr = root, *prev = NULL;
    while (curr && curr->key != key) {
        prev = curr;
        curr = curr->next;
    }
    if (!curr) {
        // Record not found
        pthread_mutex_unlock(&lock);
        return;
    }
    if (prev) prev->next = curr->next;
    else root = curr->next;
    free(curr);
    num_deletions++;
    pthread_mutex_unlock(&lock);
}

int lookup(int key) {
    record* curr = root;
    while (curr && curr->key != key) {
        curr = curr->next;
    }
    if (!curr) return -1; // Record not found
    else return curr->value;
}

void* thread_func(void* arg) {
    // Perform concurrent operations on disjoint sets
    int num_sets = 5; // Adjust this to control the number of sets
    pthread_mutex_t set_locks[num_sets];
    for (int i = 0; i < num_sets; i++) pthread_mutex_init(&set_locks[i], NULL);

    // Simulate concurrent operations
    for (int i = 0; i < 10000; i++) {
        int set_id = i % num_sets;
        pthread_mutex_lock(&set_locks[set_id]);
        insert(i, i * 2); // Perform insertion on a random set
        pthread_mutex_unlock(&set_locks[set_id]);
    }

    return NULL;
}

int main() {
    // Initialize the record set and configure the system
    pthread_t threads[num_sets];
    for (int i = 0; i < num_sets; i++) pthread_create(&threads[i], NULL, thread_func, NULL);

    // Perform concurrent operations on disjoint sets
    for (int i = 0; i < 10000; i++) {
        int set_id = i % num_sets;
        pthread_mutex_lock(&set_locks[set_id]);
        lookup(i); // Perform lookup on a random set
        pthread_mutex_unlock(&set_locks[set_id]);
    }

    // Simulate garbage collection and logging
    for (int i = 0; i < 100; i++) {
        int set_id = i % num_sets;
        pthread_mutex_lock(&set_locks[set_id]);
        delete(i); // Perform deletion on a random set
        log_operation(i, "delete"); // Log the operation
        pthread_mutex_unlock(&set_locks[set_id]);
    }

    return 0;
}
