record_t* processDataAndExpandGraph(record_t** records, int* size, int newKey) {
    // Resize the array if necessary
    if (*size == 10000) {
        *size *= 2;
        records = (record_t**)realloc(*records, sizeof(record_t*) * (*size));
        for (int i = *size / 2; i < *size; i++) {
            records[i] = NULL;
        }
    }

    // Validate the new key and offset
    for (int i = 0; i < *size; i++) {
        if ((records[i]->key == newKey) || (records[i]->offset == newKey)) {
            return NULL; // Duplicate key or offset found
        }
    }

    // Allocate memory for the new record and add it to the array
    record_t* newRecord = (record_t*)malloc(sizeof(record_t));
    newRecord->key = newKey;
    *size += 1;
    records[*size - 1] = newRecord;

    return records;
}
