#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <json-c/json-c.h>

#define MAX_DIR_DEPTH 10
#define MAX_FILE_SIZE 1024

typedef struct {
    char name[64];
    off_t size;
    void **files; // Array of file entries (structs)
} dir_entry;

typedef struct {
    char name[64];
    off_t size;
    uint8_t *data;
} file_entry;

void init_file_system(dir_entry ***root, int depth) {
    *root = (dir_entry **)malloc((1 << depth) * sizeof(dir_entry *));
    for (int i = 0; i < (1 << depth); i++) {
        (*root)[i] = (dir_entry *)malloc(sizeof(dir_entry));
        sprintf((*root)[i]->name, "Dir_%d", i);
        (*root)[i]->size = 1024;
        (*root)[i]->files = (void **)malloc((1 + rand() % (depth > 3 ? 5 : depth)) * sizeof(void *));
    }
}

void populate_file_system(dir_entry ***root, int depth) {
    for (int i = 0; i < (1 << depth); i++) {
        dir_entry *dir = (*root)[i];
        for (int j = 0; j < (dir->size / 1024 + 1); j++) {
            file_entry *file = malloc(sizeof(file_entry));
            sprintf(file->name, "File_%d", j);
            file->size = rand() % MAX_FILE_SIZE;
            file->data = malloc(file->size);
            for (int k = 0; k < file->size; k++) {
                ((uint8_t *)file->data)[k] = (uint8_t)(rand() & 0xFF);
            }
            dir->files[j] = file;
        }
    }
}

off_t calculate_file_system_size(dir_entry *root, int depth) {
    off_t size = root->size;
    for (int i = 0; i < root->size / 1024 + 1; i++) {
        file_entry *file = root->files[i];
        if (file) {
            size += file->size;
            dir_entry **subdirs = (dir_entry **)malloc((1 << depth - 1) * sizeof(dir_entry *));
            for (int j = 0; j < (1 << depth - 1); j++) {
                subdirs[j] = &root->files[i]->files[j];
            }
            size += calculate_file_system_size(subdirs[0], depth - 1);
            free(subdirs);
        }
    }
    return size;
}

void cleanup(dir_entry *root, int depth) {
    for (int i = 0; i < root->size / 1024 + 1; i++) {
        file_entry *file = root->files[i];
        if (file) {
            for (int j = 0; j < file->size; j++) {
                free(((uint8_t *)file->data) + j);
            }
            free(file->data);
            free(file);
        }
    }
}

int main() {
    dir_entry ***root;
    init_file_system(&root, MAX_DIR_DEPTH);
    populate_file_system(root, MAX_DIR_DEPTH);
    off_t size = calculate_file_system_size(*root, MAX_DIR_DEPTH);
    printf("Total file system size: %ld bytes\n", size);
    cleanup(*root, MAX_DIR_DEPTH);
    free(*root);
    return 0;
}
