#include <stdlib.h>
#include <stdio.h>

typedef struct {
    double value;
    unsigned short timestamp;
} data_point;

data_point** initialize_memory(int initial_size) {
    data_point** records = (data_point**)malloc(initial_size * sizeof(data_point*));
    for (int i = 0; i < initial_size; i++) {
        records[i] = (data_point*)malloc(sizeof(data_point));
    }
    return records;
}

void add_record(data_point** records, int* size, data_point new_point) {
    if (*size == 10) { // dynamic resizing
        *size *= 2;
        data_point** temp = initialize_memory(*size);
        for (int i = 0; i < *size / 2; i++) {
            temp[i] = records[i];
        }
        free(records);
        records = temp;
    }
    records[(*size)++] = &new_point;
}

void serialize_data_points(data_point** records, int size, FILE* file) {
    for (int i = 0; i < size; i++) {
        fwrite(&records[i]->value, sizeof(double), 1, file);
        fwrite(&records[i]->timestamp, sizeof(unsigned short), 1, file);
    }
}

void deserialize_data_points(data_point** records, int* size, FILE* file) {
    *size = 0;
    data_point new_point;
    while (fread(&new_point.value, sizeof(double), 1, file) == 1 && fread(&new_point.timestamp, sizeof(unsigned short), 1, file) == 1) {
        add_record(records, size, new_point);
    }
}

void free_memory(data_point** records, int size) {
    for (int i = 0; i < size; i++) {
        free(records[i]);
    }
    free(records);
}
