    long* long_arr = NULL;
    int* int_arr = NULL;
    record* record_arr = NULL;

    // Calculate the maximum size that can be allocated
    size_t max_size = (size_t)(1ULL << 31); // 2^31

    // Allocate first array
    while(size > max_size) {
        printf("Reducing array size due to memory constraints.\n");
        size /= 2;
    }
    long_arr = malloc(sizeof(long) * size);
    if(!long_arr) return NULL;

    // Initialize second array with unique sequential numbers
    int_arr = malloc(sizeof(int) * (size / 2));
    if(!int_arr) {
        free(long_arr);
        return NULL;
    }

    for(size_t i = 0; i < size / 2; i++) {
        int_arr[i] = i + 1;
    }

    // Allocate third array and initialize record structures
    while(size * sizeof(long) + (size / 2) * sizeof(int) + (size / 4) * sizeof(record) > max_size) {
        printf("Reducing array size due to memory constraints.\n");
        size /= 2;
    }
    record_arr = malloc(sizeof(record) * size / 4);
    if(!record_arr) {
        free(long_arr);
        free(int_arr);
        return NULL;
    }

    for(size_t i = 0; i < size / 4; i++) {
        record_arr[i].val = rand() % (size / 2);
    }

    // Track and report memory usage
    printf("Peak memory usage: %zu bytes\n", (size * sizeof(long) + (size / 2) * sizeof(int) + (size / 4) * sizeof(record)));

    return long_arr;
}
