    for (int i = 0; i < MAX_RECORDS; i++) {
        (*data)[i] = (data_point *)malloc(sizeof(data_point));
    }

    srand(time(NULL));

    int count = 0;
    enum_event_type used_types[TOTAL_EVENT_TYPES];
    for (int i = 0; i < TOTAL_EVENT_TYPES; i++) {
        used_types[i] = -1;
    }

    for (int i = 0; i < MAX_RECORDS; i++) {
        (*data)[i]->value = (double)rand() / RAND_MAX;
        (*data)[i]->timestamp = count++;
        while (true) {
            int random_type = rand() % TOTAL_EVENT_TYPES;
            if (used_types[random_type] == -1) {
                used_types[random_type] = i;
                break;
            }
        }
        (*data)[i]->type = (enum_event_type)random_type;
    }
}

void free_data(data_point ***data, int *count) {
    for (int i = 0; i < *count; i++) {
        free((*data)[i]);
    }
    free(*data);
}
