            records[i].value = rand() % KEY_RANGE;
        }

        // Add data to queue
        pthread_mutex_lock(&lock);
        enqueue(queue, &records[0]);
        pthread_mutex_unlock(&lock);

        free(offsets);
        free(keys);
        free(records);
    }

    fclose(file);
    return NULL;
}

