#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

// Define the event structure
typedef struct {
    time_t timestamp;
    enum { TYPE_A, TYPE_B, TYPE_C } type;
    double* value;
} Event;

// Define the secondary structure for tracking last processed timestamps
typedef struct {
    int count;
    time_t* timestamps;
} TimestampTracker;

// Define the dynamic data structure
typedef struct {
    Event* events;
    char** strings;
    double* values;
    TimestampTracker* trackers;
    size_t capacity;
    size_t event_count;
} DynamicDataStructure;

// Function to resize the arrays and event structures
void resize(DynamicDataStructure* data, size_t new_capacity) {
    // Resize the event array
    Event* new_events = realloc(data->events, sizeof(Event) * new_capacity);
    if (new_events == NULL) {
        printf("Error: Failed to allocate memory for events.\n");
        exit(EXIT_FAILURE);
    }
    data->events = new_events;

    // Resize the string array
    char** new_strings = realloc(data->strings, sizeof(char*) * new_capacity);
    if (new_strings == NULL) {
        printf("Error: Failed to allocate memory for strings.\n");
        exit(EXIT_FAILURE);
    }
    data->strings = new_strings;

    // Resize the value array
    double* new_values = realloc(data->values, sizeof(double) * new_capacity);
    if (new_values == NULL) {
        printf("Error: Failed to allocate memory for values.\n");
        exit(EXIT_FAILURE);
    }
    data->values = new_values;

    // Resize the trackers array
    TimestampTracker* new_trackers = realloc(data->trackers, sizeof(TimestampTracker) * new_capacity);
    if (new_trackers == NULL) {
        printf("Error: Failed to allocate memory for trackers.\n");
        exit(EXIT_FAILURE);
    }
    data->trackers = new_trackers;

    // Update the capacity and event count
    data->capacity = new_capacity;
    data->event_count = 0;
}

// Function to add an event to the dynamic data structure
void add_event(DynamicDataStructure* data, Event* event) {
    if (data->event_count >= data->capacity) {
        resize(data, data->capacity * 2 + 1);
    }
    data->events[data->event_count] = *event;
    data->event_count++;
}

// Function to serialize the dynamic data structure
void serialize(DynamicDataStructure* data, FILE* file) {
    // Serialize the events array
    fwrite(&data->event_count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < data->event_count; i++) {
        Event event = data->events[i];
        fwrite(&event.timestamp, sizeof(time_t), 1, file);
        fwrite(&event.type, sizeof(enum { TYPE_A, TYPE_B, TYPE_C }), 1, file);
        fwrite(event.value, sizeof(double), 1, file);
    }

    // Serialize the strings array
    size_t string_count = data->event_count;
    fwrite(&string_count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < string_count; i++) {
        char* str = data->strings[i];
        size_t len = strlen(str) + 1;
        fwrite(&len, sizeof(size_t), 1, file);
        fwrite(str, sizeof(char), len, file);
    }

    // Serialize the values array
    fwrite(&data->event_count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < data->event_count; i++) {
        double value = data->values[i];
        fwrite(&value, sizeof(double), 1, file);
    }
}

// Function to deserialize the dynamic data structure
void deserialize(DynamicDataStructure* data, FILE* file) {
    // Deserialize the events array
    size_t event_count;
    fread(&event_count, sizeof(size_t), 1, file);
    data->events = malloc(sizeof(Event) * event_count);
    for (size_t i = 0; i < event_count; i++) {
        Event* event = &data->events[i];
        fread(&event->timestamp, sizeof(time_t), 1, file);
        fread(&event->type, sizeof(enum { TYPE_A, TYPE_B, TYPE_C }), 1, file);
        event->value = malloc(sizeof(double));
        fread(event->value, sizeof(double), 1, file);
    }

    // Deserialize the strings array
    size_t string_count;
    fread(&string_count, sizeof(size_t), 1, file);
    data->strings = malloc(sizeof(char*) * string_count);
    for (size_t i = 0; i < string_count; i++) {
        size_t len;
        fread(&len, sizeof(size_t), 1, file);
        char* str = malloc(len + 1);
        fread(str, sizeof(char), len, file);
        str[len] = '\0';
        data->strings[i] = str;
    }

    // Deserialize the values array
    fread(&event_count, sizeof(size_t), 1, file);
    data->values = malloc(sizeof(double) * event_count);
    for (size_t i = 0; i < event_count; i++) {
        double value;
        fread(&value, sizeof(double), 1, file);
        data->values[i] = value;
    }
}

// Function to free the allocated memory
void free_data(DynamicDataStructure* data) {
    // Free the events array
    for (size_t i = 0; i < data->event_count; i++) {
        Event* event = &data->events[i];
        free(event->value);
    }
    free(data->events);

    // Free the strings array
    for (size_t i = 0; i < data->event_count; i++) {
        char* str = data->strings[i];
        free(str);
    }
    free(data->strings);

    // Free the values array
    free(data->values);

    // Free the trackers array
    for (size_t i = 0; i < data->capacity; i++) {
        TimestampTracker* tracker = &data->trackers[i];
        if (tracker->timestamps) {
            free(tracker->timestamps);
        }
    }
    free(data->trackers);

    // Update the capacity and event count
    data->capacity = 0;
    data->event_count = 0;
}

int main() {
    // Initialize the random number generator
    srand(time(NULL));

    // Create a dynamic data structure with an initial capacity of 100,000 events
    DynamicDataStructure data;
    data.capacity = 100000;
    data.event_count = 0;
    data.events = malloc(sizeof(Event) * data.capacity);
    data.strings = malloc(sizeof(char*) * data.capacity);
    data.values = malloc(sizeof(double) * data.capacity);
    data.trackers = malloc(sizeof(TimestampTracker) * data.capacity);

    // Add some events to the dynamic data structure
    for (size_t i = 0; i < 50; i++) {
        Event event;
        time_t timestamp = (time_t)rand() % (time(NULL) - 31536000);
        event.timestamp = timestamp;
        event.type = (enum { TYPE_A, TYPE_B, TYPE_C })rand() % 3;
        double value = (double)rand();
        add_event(&data, &event);
    }

    // Serialize the dynamic data structure to a file
    FILE* file = fopen("data.bin", "wb");
    serialize(&data, file);
    fclose(file);

    // Deserialize the dynamic data structure from the file
    file = fopen("data.bin", "rb");
    deserialize(&data, file);
    fclose(file);

    // Free the allocated memory
    free_data(&data);

    return 0;
}
