#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <pthread.h>

typedef struct {
    int key;
    int value;
} Record;

typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t used;
    Record* data;
    size_t max_keys;
    pthread_cond_t cond;
} DataStore;

void* malloc_sized(size_t size) {
    return malloc(size);
}

DataStore* data_store_init(size_t capacity, size_t max_keys) {
    DataStore* ds = (DataStore*)malloc_sized(sizeof(DataStore));
    ds->capacity = capacity;
    ds->used = 0;
    ds->data = (Record*)malloc_sized(capacity * sizeof(Record));
    ds->max_keys = max_keys;
    pthread_mutex_init(&ds->lock, NULL);
    pthread_cond_init(&ds->cond, NULL);
    return ds;
}

void data_store_free(DataStore* ds) {
    free(ds->data);
    free(ds);
}

int data_store_set(DataStore* ds, int key, int value) {
    pthread_mutex_lock(&ds->lock);
    Record* current = &ds->data[0];
    for(size_t i = 0; i < ds->used; i++) {
        if(current[i].key == key) {
            current[i].value = value;
            pthread_mutex_unlock(&ds->lock);
            return 1;
        }
        current++;
    }
    if(ds->used >= ds->capacity) {
        Record* lru_entry = &ds->data[0];
        for(size_t i = 0; i < ds->used; i++) {
            if(lru_entry[i].key == -1) {
                // prune LRU entry
                memmove(&lru_entry[0], &lru_entry[1], (ds->used - 1) * sizeof(Record));
                ds->used--;
                break;
            }
            lru_entry++;
        }
    }
    if(ds->used < ds->capacity) {
        current = &ds->data[ds->used];
        current->key = key;
        current->value = value;
        ds->used++;
    } else {
        pthread_mutex_unlock(&ds->lock);
        return 0;
    }
    pthread_mutex_unlock(&ds->lock);
    return 1;
}

int data_store_get(DataStore* ds, int key) {
    pthread_mutex_lock(&ds->lock);
    Record* current = &ds->data[0];
    for(size_t i = 0; i < ds->used; i++) {
        if(current[i].key == key) {
            pthread_mutex_unlock(&ds->lock);
            return current[i].value;
        }
        current++;
    }
    pthread_mutex_unlock(&ds->lock);
    return -1;
}

void* log_malloc(size_t size) {
    // implement logging mechanism here
}

void data_store_prune(DataStore* ds) {
    // implement pruning mechanism here
}

int main() {
    DataStore* ds = data_store_init(1000000, 10000);
    // ...
    return 0;
}
