// Function to manage metrics and data sets
int manageMetricsAndDataSets(int numMetrics, int maxTimestamp) {
    // Initialize arrays and structures
    Metric *metrics = (Metric *)malloc(numMetrics * sizeof(Metric));
    unsigned long *timestamps = (unsigned long *)malloc(numMetrics * sizeof(unsigned long));
    double *values = (double *)malloc(numMetrics * sizeof(double));

    // Initialize Union-Find data structure
    int *parent = (int *)malloc(numMetrics * sizeof(int));
    int *rank = (int *)malloc(numMetrics * sizeof(int));

    // Fill arrays with random data
    for (int i = 0; i < numMetrics; i++) {
        metrics[i].value = rand() / (double)RAND_MAX;
        metrics[i].timestamp = rand() % maxTimestamp;
        metrics[i].status = OK;

        timestamps[i] = (unsigned long)metrics[i].timestamp;
        values[i] = metrics[i].value;
    }

    // Initialize disjoint sets
    for (int i = 0; i < numMetrics; i++) {
        parent[i] = i;
        rank[i] = 0;
    }

    // Perform Union-Find operations to identify disjoint sets
    int *setCounts = (int *)malloc(numMetrics * sizeof(int));
    int totalSets = 0;

    for (int i = 0; i < numMetrics; i++) {
        if (parent[i] == i) {
            setCounts[totalSets++] = 1;
        }
    }

    // Serialize and deserialize data structure to file
    FILE *file = fopen("data.txt", "wb");
    fwrite(metrics, sizeof(Metric), numMetrics, file);
    fclose(file);

    file = fopen("data.txt", "rb");
    Metric *deserializedMetrics = (Metric *)malloc(numMetrics * sizeof(Metric));
    fread(deserializedMetrics, sizeof(Metric), numMetrics, file);
    fclose(file);

    // Calculate average metric value
    double sum = 0;
    for (int i = 0; i < numMetrics; i++) {
        sum += metrics[i].value;
    }
    double average = sum / numMetrics;

    // Filter and print metrics with specific status
    int count = 0;
    for (int i = 0; i < numMetrics; i++) {
        if (metrics[i].status == ERROR) {
            printf("Error metric: %f at timestamp %d\n", metrics[i].value, metrics[i].timestamp);
            count++;
        }
    }

    // Calculate time taken to identify disjoint sets
    int startTime = clock();
    for (int i = 0; i < numMetrics; i++) {
        if (parent[i] == i) {
            setCounts[totalSets++] = 1;
        }
    }
    int endTime = clock();

    // Free allocated memory
    free(metrics);
    free(timestamps);
    free(values);
    free(parent);
    free(rank);
    free(setCounts);

    return totalSets;
}

int main() {
    int numMetrics = 1000000;
    int maxTimestamp = 1000000;

    manageMetricsAndDataSets(numMetrics, maxTimestamp);

    return 0;
}
