// Define the record structure
typedef struct {
    int key;
    int value;
} record_t;

// Define the list structure
typedef struct {
    record_t *records;
    size_t capacity;
    pthread_mutex_t lock;
} list_t;

// Initialize a new list with the given capacity
list_t* list_init(size_t capacity) {
    list_t* list = malloc(sizeof(list_t));
    if (!list) return NULL; // Handle memory allocation failure

    list->records = malloc(sizeof(record_t) * capacity);
    if (!list->records) {
        free(list); return NULL; // Handle memory allocation failure
    }

    list->capacity = capacity;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

// Add a new record to the list
int list_add(list_t* list, int key, int value) {
    pthread_mutex_lock(&list->lock);

    // Check for duplicate keys and remove duplicates
    size_t i;
    for (i = 0; i < list->capacity; i++) {
        if (list->records[i].key == key) {
            free(list->records);
            list->records = realloc(list->records, sizeof(record_t) * --list->capacity);
            memmove(&list->records[i], &list->records[i + 1], sizeof(record_t) * (list->capacity - i));
            break;
        }
    }

    if (i == list->capacity) {
        // Insert the new record
        size_t j = 0;
        while (j < i && list->records[j].key <= key) j++;
        memmove(&list->records[j + 1], &list->records[j], sizeof(record_t) * (i - j));
        list->records[j].key = key;
        list->records[j].value = value;

        // Update the capacity if necessary
        if (++j >= list->capacity * 0.75) {
            list->capacity *= 2;
            record_t* new_records = malloc(sizeof(record_t) * list->capacity);
            memcpy(new_records, list->records, sizeof(record_t) * j);
            free(list->records);
            list->records = new_records;
        }
    }

    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

// Remove the record with the given key from the list
int list_remove(list_t* list, int key) {
    pthread_mutex_lock(&list->lock);

    size_t i;
    for (i = 0; i < list->capacity; i++) {
        if (list->records[i].key == key) {
            memmove(&list->records[i], &list->records[i + 1], sizeof(record_t) * (list->capacity - i));
            break;
        }
    }

    if (i < list->capacity) {
        // Update the capacity if necessary
        size_t j = i;
        while (++j < list->capacity && list->records[j].key <= key) j++;
        if (j >= list->capacity * 0.25) {
            list->capacity /= 2;
            record_t* new_records = malloc(sizeof(record_t) * list->capacity);
            memcpy(new_records, &list->records[0], sizeof(record_t) * i);
            memmove(&new_records[i], &list->records[j], sizeof(record_t) * (list->capacity - i));
            free(list->records);
            list->records = new_records;
        }
    }

    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

// Log an operation on the list
void list_log(list_t* list, int operation, int key, int value) {
    FILE* log_file = fopen("list.log", "a");
    if (!log_file) {
        perror("Failed to open log file"); return;
    }

    fprintf(log_file, "%ld: %d %s record with key %d and value %d\n",
            time(NULL), operation,
            (operation == 0) ? "added" : ((operation == 1) ? "removed" : "updated"),
            key, value);

    fclose(log_file);
}

// Serialize the list to a string
char* list_serialize(list_t* list) {
    size_t len = 0;
    size_t i;

    // Calculate the length of the serialized string
    for (i = 0; i < list->capacity; i++) {
        len += sprintf(NULL, "{\"key\": %d, \"value\": %d},", list->records[i].key, list->records[i].value);
    }

    char* buffer = malloc(len + 1);
    if (!buffer) return NULL; // Handle memory allocation failure

    // Serialize the list
    for (i = 0; i < list->capacity; i++) {
        sprintf(buffer + len - strlen(",") - 1, "{\"key\": %d, \"value\": %d},", list->records[i].key, list->records[i].value);
        len += strlen(",") + 2;
    }

    buffer[len] = '\0';

    return buffer;
}

// Deserialize the list from a string
list_t* list_deserialize(char* serialized) {
    size_t capacity = 0;
    char* token = strtok(serialized, ",");
    while (token) {
        int key = atoi(strtok(NULL, "\""));
        int value = atoi(strtok(NULL, "\""));
        record_t* new_record = malloc(sizeof(record_t));
        if (!new_record) return NULL; // Handle memory allocation failure
        new_record->key = key;
        new_record->value = value;
        capacity++;

        token = strtok(NULL, ",");
    }

    list_t* list = list_init(capacity);
    if (!list) return NULL; // Handle memory allocation failure

    // Deserialize the records
    size_t i;
    for (i = 0; i < capacity; i++) {
        memcpy(&list->records[i], new_record, sizeof(record_t));
        free(new_record);
    }

    return list;
}

// Set the seed for the random number generator
void list_set_seed(long int seed) {
    srand(seed);
}
