typedef struct {
    pthread_mutex_t lock; // Concurrency-safe lock
    Metric* metrics[MAX_METRICS];
    Record* records[MAX_RECORDS];
    int current_metric_index;
    int current_record_index;
} HybridDataStructure;

// Function to handle metrics and records, ensuring thread safety and atomicity
void* handleMetricsAndRecords(void* args) {
    HybridDataStructure* hd = (HybridDataStructure*)args;

    // Initialize the hybrid data structure
    pthread_mutex_init(&hd->lock, NULL);
    hd->current_metric_index = 0;
    hd->current_record_index = 0;

    // Add new metrics and records concurrently, ensuring thread safety
    for (int i = 0; i < MAX_METRICS; i++) {
        Metric* metric = &hd->metrics[i];
        pthread_mutex_lock(&hd->lock);
        while (i >= hd->current_metric_index) {
            hd->current_metric_index++;
        }
        metric->timestamp = i;
        pthread_mutex_unlock(&hd->lock);
    }

    for (int i = 0; i < MAX_RECORDS; i++) {
        Record* record = &hd->records[i];
        pthread_mutex_lock(&hd->lock);
        while (i >= hd->current_record_index) {
            hd->current_record_index++;
        }
        record->key = i;
        pthread_mutex_unlock(&hd->lock);
    }

    // Helper function to find and print the largest integer among records
    int getLargestRecordKey(HybridDataStructure* hd) {
        int max_key = 0;
        for (int i = 0; i < MAX_RECORDS; i++) {
            if (hd->records[i]->key > max_key) {
                max_key = hd->records[i]->key;
            }
        }
        return max_key;
    }

    // Serialize and deserialize data for persistence
    void serializeData(HybridDataStructure* hd, FILE* file) {
        fwrite(&hd->current_metric_index, sizeof(int), 1, file);
        fwrite(&hd->current_record_index, sizeof(int), 1, file);

        for (int i = 0; i < MAX_METRICS; i++) {
            Metric* metric = &hd->metrics[i];
            fwrite(&metric->value, sizeof(double), 1, file);
            fwrite(&metric->timestamp, sizeof(int), 1, file);
            fwrite(&metric->status, sizeof(enum MetricStatus), 1, file);
        }

        for (int i = 0; i < MAX_RECORDS; i++) {
            Record* record = &hd->records[i];
            fwrite(&record->key, sizeof(int), 1, file);
            fwrite(&record->value, sizeof(int), 1, file);
        }
    }

    void deserializeData(HybridDataStructure* hd, FILE* file) {
        fread(&hd->current_metric_index, sizeof(int), 1, file);
        fread(&hd->current_record_index, sizeof(int), 1, file);

        for (int i = 0; i < MAX_METRICS; i++) {
            Metric* metric = &hd->metrics[i];
            fread(&metric->value, sizeof(double), 1, file);
            fread(&metric->timestamp, sizeof(int), 1, file);
            fread(&metric->status, sizeof(enum MetricStatus), 1, file);
        }

        for (int i = 0; i < MAX_RECORDS; i++) {
            Record* record = &hd->records[i];
            fread(&record->key, sizeof(int), 1, file);
            fread(&record->value, sizeof(int), 1, file);
        }
    }

    return NULL;
}
