#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 10000
#define SEM_POOL_SIZE 50

typedef struct {
    int value;
    pthread_mutex_t lock;
} record_t;

record_t *records = NULL;
int records_count = 0;
int semaphore_pool[SEM_POOL_SIZE];
int semaphores_available = SEM_POOL_SIZE;

void log_operation(const char *op, int key) {
    FILE *fp = fopen("log.txt", "a");
    if (fp != NULL) {
        fprintf(fp, "%s: %d\n", op, key);
        fclose(fp);
    }
}

int acquire_semaphore(int key) {
    int i;
    for (i = 0; i < semaphores_available; i++) {
        if (semaphore_pool[i] == key) {
            pthread_mutex_lock(&records[key].lock);
            return 1;
        }
    }
    return -1;
}

void release_semaphore(int key) {
    int i;
    for (i = 0; i < semaphores_available; i++) {
        if (semaphore_pool[i] == key) {
            pthread_mutex_unlock(&records[key].lock);
            return;
        }
    }
}

int add_record(int key, int value) {
    record_t *new_rec = NULL;

    new_rec = (record_t *)malloc(sizeof(record_t));
    if (new_rec != NULL) {
        new_rec->value = value;
        pthread_mutex_init(&new_rec->lock, NULL);

        records[records_count] = *new_rec;
        semaphore_pool[semaphores_available] = key;
        semaphores_available++;
        log_operation("ADD", key);
        return 1;
    }

    return -1;
}

int remove_record(int key) {
    int i;

    for (i = 0; i < records_count; i++) {
        if (records[i].value == key) {
            pthread_mutex_destroy(&records[i].lock);
            free(records + i);
            memmove(records + i, records + i + 1, sizeof(record_t) * (records_count - i - 1));
            records_count--;
            log_operation("REMOVE", key);
            return 1;
        }
    }

    return -1;
}

int update_record(int key, int value) {
    int i;

    for (i = 0; i < records_count; i++) {
        if (records[i].value == key) {
            pthread_mutex_lock(&records[i].lock);
            records[i].value = value;
            pthread_mutex_unlock(&records[i].lock);
            log_operation("UPDATE", key);
            return 1;
        }
    }

    return -1;
}

int scan_duplicates() {
    int i, j, duplicate_count = 0;

    for (i = 0; i < records_count; i++) {
        for (j = i + 1; j < records_count; j++) {
            if (records[i].value == records[j].value) {
                pthread_mutex_lock(&records[j].lock);
                remove_record(records[j].value);
                duplicate_count++;
            }
        }
    }

    return duplicate_count;
}

void serialize_records(char *buffer, int size) {
    int i;

    for (i = 0; i < records_count; i++) {
        sprintf(buffer, "%d %d\n", i, records[i].value);
        buffer += strlen(buffer) + 1;
        if (strlen(buffer) >= size) {
            break;
        }
    }

    *buffer = '\0';
}

int main() {
    // Initialize semaphore pool
    int i;
    for (i = 0; i < SEM_POOL_SIZE; i++) {
        semaphore_pool[i] = -1;
    }

    // Initialize records array
    records = (record_t *)malloc(sizeof(record_t) * MAX_RECORDS);
    if (records == NULL) {
        printf("Memory allocation failure.\n");
        return -1;
    }

    // Initialize record count
    records_count = 0;

    // Main program loop
    while (1) {
        // Acquire semaphore for new record
        int key = acquire_semaphore(records_count);
        if (key == -1) {
            printf("Semaphore pool exhausted.\n");
            break;
        }

        // Add a new record
        add_record(key, records_count);

        // Scan for duplicates every 1000 records
        if ((records_count % 1000) == 0) {
            int duplicate_count = scan_duplicates();
            printf("Duplicates found: %d\n", duplicate_count);
        }
    }

    // Release all semaphores
    for (i = 0; i < semaphores_available; i++) {
        release_semaphore(semaphore_pool[i]);
    }

    return 0;
}
