#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct record {
    int key;
    long offset;
} Record;

Record* create_records(int num_records, int max_key, int max_offset, int* num_allocated) {
    Record* records = NULL;
    *num_allocated = 0;

    for (int i = 0; i < num_records && *num_allocated <= max_offset; i++) {
        Record* record = malloc(sizeof(Record));
        if (!record) break;

        int key = rand() % (max_key + 1);
        long offset = (long)rand() % (max_offset + 1);
        record->key = key;
        record->offset = offset;

        records = realloc(records, (*num_allocated + 1) * sizeof(Record));
        if (!records) {
            free(record);
            break;
        }

        records[*num_allocated] = *record;
        (*num_allocated)++;
    }

    return records;
}

void create_arrays(int num_records, int max_key, int max_offset, int* num_allocated, long** offsets, int** keys) {
    *num_allocated = 0;

    for (int i = 0; i < num_records && *num_allocated <= max_offset; i++) {
        Record record;
        int key = rand() % (max_key + 1);
        long offset = (long)rand() % (max_offset + 1);
        record.key = key;
        record.offset = offset;

        *offsets = realloc(*offsets, (*num_allocated + 1) * sizeof(long));
        if (!*offsets) break;

        *keys = realloc(*keys, (*num_allocated + 1) * sizeof(int));
        if (!*keys) {
            free(*offsets);
            *offsets = NULL;
            break;
        }

        (*offsets)[*num_allocated] = offset;
        (*keys)[*num_allocated] = key;
        (*num_allocated)++;
    }
}

int main() {
    srand(time(NULL));

    int num_records = 1000;
    int max_key = 1000;
    int max_offset = 1000000;

    long* offsets = NULL;
    int* keys = NULL;
    int num_allocated = 0;

    create_arrays(num_records, max_key, max_offset, &num_allocated, &offsets, &keys);

    for (int i = 0; i < num_allocated; i++) {
        printf("Key: %d, Offset: %ld\n", keys[i], offsets[i]);
    }

    free(offsets);
    free(keys);

    return 0;
}
