#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define PROJECT_MAX 10000
#define MAX_NAME_LENGTH 256
#define MAX_DEPENDENCIES 10

typedef struct {
    char name[MAX_NAME_LENGTH];
    int priority;
    int dependencies;
    pthread_mutex_t lock; // thread safety
} Project;

Project* projects[PROJECT_MAX];
int project_count = 0;

// Create a new project with given name and priority.
void create_project(const char* name, int priority) {
    Project* new_project = (Project*)malloc(sizeof(Project));
    strcpy(new_project->name, name);
    new_project->priority = priority;
    new_project->dependencies = 0;
    projects[project_count] = new_project;
    project_count++;
}

// Find a project by its name.
Project* find_project(const char* name) {
    for (int i = 0; i < project_count; i++) {
        if (!strcmp(projects[i]->name, name)) {
            return projects[i];
        }
    }
    return NULL;
}

// Add a dependency between two projects.
void add_dependency(const char* dependent_project_name, const char* prerequisite_project_name) {
    Project* dependent_project = find_project(dependent_project_name);
    Project* prerequisite_project = find_project(prerequisite_project_name);

    if (dependent_project && prerequisite_project) {
        dependent_project->dependencies++;
        prerequisite_project->dependencies++;
    }
}

// Check for cyclic dependencies.
int check_for_cyclic_dependencies(const char* project_name) {
    Project* project = find_project(project_name);
    if (!project) return 0; // No cyclic dependencies found

    pthread_mutex_lock(&project->lock); // Acquire the lock
    int visited[PROJECT_MAX];
    for (int i = 0; i < project_count; i++) visited[i] = 0;

    void dfs(int node) {
        if (!visited[node]) {
            visited[node] = 1;
            for (int i = 0; i < project[node]->dependencies; i++) {
                int next_node = project[node]->dependencies + i;
                if (!visited[next_node]) {
                    dfs(next_node);
                } else {
                    return 1; // Cyclic dependency found
                }
            }
        }
        return 0; // No cyclic dependency found
    }

    for (int i = 0; i < project_count; i++) {
        if (project[i]->name == project_name) {
            if (dfs(i)) {
                pthread_mutex_unlock(&project->lock); // Release the lock
                return 1; // Cyclic dependency found
            }
            break;
        }
    }

    pthread_mutex_unlock(&project->lock); // Release the lock
    return 0; // No cyclic dependencies found
}

// Serialize projects to a file.
void serialize_projects(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    int project_count;
    for (int i = 0; i < PROJECT_MAX; i++) {
        Project* project = projects[i];
        if (!project) continue;
        fwrite(&project->name, sizeof(char), strlen(project->name), file);
        fwrite(&project->priority, sizeof(int), 1, file);
        fwrite(&project->dependencies, sizeof(int), 1, file);
    }
    fclose(file);
}

// Deserialize projects from a file.
void deserialize_projects(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return;

    int project_count;
    for (int i = 0; i < PROJECT_MAX; i++) {
        Project* project = projects[i];
        if (!project) continue;
        fread(&project->name, sizeof(char), strlen(project->name), file);
        fread(&project->priority, sizeof(int), 1, file);
        fread(&project->dependencies, sizeof(int), 1, file);
    }
    fclose(file);
}

int main() {
    // Initialize projects
    create_project("Project A", 5);
    create_project("Project B", 3);
    create_project("Project C", 4);

    // Add dependencies
    add_dependency("Project B", "Project A");
    add_dependency("Project C", "Project B");

    // Check for cyclic dependencies
    if (check_for_cyclic_dependencies("Project B")) {
        printf("Cyclic dependency detected.\n");
    }

    // Serialize projects to file
    serialize_projects("projects.bin");

    return 0;
}

