#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef enum {
    OK,
    WARNING,
    ERROR
} status_t;

typedef struct {
    double value;
    int timestamp;
    status_t status;
} metric_t;

void processAndManageMetrics(metric_t** metrics, size_t* capacity) {
    // Allocate initial memory for metrics array and resize as needed
    *metrics = realloc(NULL, sizeof(metric_t));
    (*capacity) = 1; // Start with a single element

    int last_timestamp = -1;
    while (fscanf(stdin, "%lf %d", &metrics[*capacity]->value, &metrics[*capacity]->timestamp) == 2) {
        if (metrics[*capacity]->timestamp != last_timestamp + 1) {
            metrics[*capacity]->status = OK; // Initialize status
            last_timestamp = metrics[*capacity]->timestamp;
            (*capacity)++;
            metrics = realloc(metrics, sizeof(metric_t) * (*capacity));
        }
    }

    metrics[(*capacity) - 1].status = WARNING; // Mark the last metric with a warning

    // Serialize and deserialize for persistence
    void serialize(metric_t* metrics, FILE* file) {
        fwrite(metrics, sizeof(metric_t), *capacity, file);
    }

    void deserialize(metric_t** metrics, FILE* file) {
        size_t capacity;
        fread(&capacity, sizeof(size_t), 1, file);
        *metrics = realloc(NULL, sizeof(metric_t) * capacity);
        fread(*metrics, sizeof(metric_t), capacity, file);
    }
}

void filterAndPrintErrorMetrics(metric_t* metrics, size_t capacity) {
    for (size_t i = 0; i < capacity; i++) {
        if (metrics[i].status == ERROR) {
            printf("Metric at timestamp %d has error: %.2f\n", metrics[i].timestamp, metrics[i].value);
        }
    }
}

double calculateAverageMetricValue(metric_t* metrics, size_t capacity) {
    double sum = 0;
    for (size_t i = 0; i < capacity; i++) {
        sum += metrics[i].value;
    }
    return sum / capacity;
}
