#include <time.h>

typedef struct {
    int key;
    long offset;
    short value;
} record;

record* expandGraphStructure(int **graphKeys, long **graphOffsets) {
    // Initialize arrays
    int *keys = NULL;
    long *offsets = NULL;
    record *records = NULL;
    int *lastAccessed = NULL;

    int capacity = 10; // Initial capacity for arrays
    int count = 0; // Number of records

    while (1) {
        int key, numRecords;
        scanf("%d", &key);
        if (feof(stdin)) break;

        // Resize arrays if necessary
        if (count >= capacity) {
            capacity *= 2;
            keys = realloc(keys, sizeof(int) * capacity);
            offsets = realloc(offsets, sizeof(long) * capacity);
            records = realloc(records, sizeof(record) * capacity);
            lastAccessed = realloc(lastAccessed, sizeof(int) * capacity);
        }

        // Add new record
        int i;
        for (i = 0; i < count; i++) {
            if (keys[i] == key || offsets[i] == numRecords) {
                printf("Key or offset already exists. Please enter a unique value.\n");
                return NULL;
            }
        }

        // Allocate memory for new record
        keys[count] = key;
        offsets[count] = 0; // Initialize with default value
        records[count].key = key;
        records[count].offset = 0; // Initialize with default value
        records[count].value = rand() % 100 + 1; // Random short value

        lastAccessed[count] = i;

        count++;
    }

    *graphKeys = keys;
    *graphOffsets = offsets;
    return records;
}

void setRecordValues(record *records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        // Set the value of each record's 'int' field to a random value within a given range
        records[i].value = rand() % 100 + 1;
    }
}

void printLargestInteger(record *records, int count) {
    int max = INT_MIN;
    for (int i = 0; i < count; i++) {
        if (records[i].value > max)
            max = records[i].value;
    }
    printf("The largest integer is %d.\n", max);
}

// Serialization function
void serialize(record *records, FILE *file) {
    fwrite(&count, sizeof(int), 1, file); // Serialize the number of records
    for (int i = 0; i < count; i++) {
        fwrite(&records[i].key, sizeof(int), 1, file);
        fwrite(&records[i].offset, sizeof(long), 1, file);
        fwrite(&records[i].value, sizeof(short), 1, file);
    }
}

// Deserialization function
record* deserialize(FILE *file) {
    record *records = NULL;
    int numRecords;

    // Read the number of records from the file
    fread(&numRecords, sizeof(int), 1, file);

    // Allocate memory for records array
    records = (record *)malloc(sizeof(record) * numRecords);
    for (int i = 0; i < numRecords; i++) {
        fread(&records[i].key, sizeof(int), 1, file);
        fread(&records[i].offset, sizeof(long), 1, file);
        fread(&records[i].value, sizeof(short), 1, file);
    }

    return records;
}
