} UserProfile;

UserProfile *profiles = NULL;
int profile_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void serialize_profiles(char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    for (int i = 0; i < profile_count; i++) {
        UserProfile *profile = &profiles[i];
        fwrite(profile->username, sizeof(char), strlen(profile->username), file);
        fwrite(&profile->email, sizeof(char), strlen(profile->email), file);
        fwrite(&profile->interest_count, sizeof(int), 1, file);
        for (int j = 0; j < profile->interest_count; j++) {
            fwrite(profile->interests[j], sizeof(char), strlen(profile->interests[j]), file);
        }
    }

    fclose(file);
}

void deserialize_profiles(char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    fseek(file, 0, SEEK_END);
    int fileSize = ftell(file);
    rewind(file);

    UserProfile *new_profiles = (UserProfile *)malloc((fileSize / sizeof(UserProfile)) + 1);
    fread(new_profiles, sizeof(UserProfile), fileSize / sizeof(UserProfile), file);

    profile_count = fileSize / sizeof(UserProfile);
    for (int i = 0; i < profile_count; i++) {
        UserProfile *profile = &new_profiles[i];
        profile->username = malloc(strlen(profile->username) + 1);
        strcpy(profile->username, (char *)malloc(strlen(profile->username) + 1));
        strcpy(profile->username, (char *)malloc(strlen(profile->username) + 1));
        profile->email = (char *)malloc(strlen(profile->email) + 1);

        int interest_count = fread(&profile->interest_count, sizeof(int), 1, file);
        for (int j = 0; j < profile->interest_count; j++) {
            char *interest = malloc((strlen(profile->interests[j]) + 1));
            strcpy(interest, (char *)malloc(strlen(profile->interests[j]) + 1));
            profile->interests = interest;
        }
    }

    free(new_profiles);
    fclose(file);
}

UserProfile *get_profile(char *username) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < profile_count; i++) {
        if (strcmp(profiles[i].username, username) == 0) {
            UserProfile *profile = &profiles[i];
            profile->interest_count = fread(profile->interest_count, sizeof(int), 1, file);
            return profile;
        }
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}

void update_profile(char *username, char *new_email, int new_interests) {
    UserProfile *profile = get_profile(username);
    if (!profile) return;

    pthread_mutex_lock(&lock);
    strcpy(profile->email, new_email);
    profile->interest_count = new_interests;
    pthread_mutex_unlock(&lock);
}

void add_interest(char *username, char *new_interest) {
    UserProfile *profile = get_profile(username);
    if (!profile) return;

    pthread_mutex_lock(&lock);
    profile->interests[profile->interest_count++] = malloc(strlen(new_interest) + 1);
    strcpy(profile->interests[profile->interest_count - 1], new_interest);
    pthread_mutex_unlock(&lock);
}

void remove_interest(char *username, char *old_interest) {
    UserProfile *profile = get_profile(username);
    if (!profile) return;

    pthread_mutex_lock(&lock);
    int interest_index = -1;
    for (int i = 0; i < profile->interest_count; i++) {
        if (strcmp(profile->interests[i], old_interest) == 0) {
            interest_index = i;
            break;
        }
    }

    if (interest_index != -1) {
        memmove(profile->interests + interest_index, profile->interests + interest_index + 1, sizeof(char *) * (profile->interest_count - interest_index));
        profile->interest_count--;
    }
    pthread_mutex_unlock(&lock);
}

int generate_username(int length) {
