['Here is the C code for managing a scalable and efficient in-memory data structure for storing temperature measurements from various sensors:

```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Define the maximum number of entries (10 million)
#define MAX_ENTRIES 10000000

// Define the size of each entry (64-bit unsigned integer + double)
#define ENTRY_SIZE sizeof(uint64_t) + sizeof(double)

typedef struct {
    uint64_t key;
    double value;
} Entry;

typedef struct {
    Entry* data;
    uint32_t size;
    uint32_t capacity;
    pthread_mutex_t lock; // Mutex for concurrent access
} TemperatureData;

// Function to initialize the temperature data structure
TemperatureData* init_temperature_data() {
    TemperatureData* data = (TemperatureData*)malloc(sizeof(TemperatureData));
    data->size = 0;
    data->capacity = MAX_ENTRIES / 4; // Start with 1/4th of maximum capacity
    data->data = (Entry*)calloc(data->capacity * ENTRY_SIZE, 1);
    pthread_mutex_init(&data->lock, NULL); // Initialize mutex for concurrent access
    return data;
}

// Function to insert a new temperature measurement into the data structure
void insert_temperature(TemperatureData* data, uint64_t key, double value) {
    if (data->size >= data->capacity * 3 / 4) { // Resize when 75% full
        resize_data(data);
    }

    pthread_mutex_lock(&data->lock); // Acquire lock for concurrent access

    int index = key % data->capacity; // Calculate the index using a simple hash function
    Entry* entry = &data->data[index * ENTRY_SIZE / sizeof(Entry)];
    if (entry->key != 0) { // Check if the slot is empty
        uint64_t next_index = (index + 1) % data->capacity;
        while (data->data[next_index * ENTRY_SIZE / sizeof(Entry)].key != 0) {
            next_index = (next_index + 1) % data->capacity; // Find an empty slot
        }
        index = next_index;
    }

    entry->key = key;
    entry->value = value;
    data->size++;

    pthread_mutex_unlock(&data->lock); // Release lock for concurrent access
}

// Function to look up a temperature measurement in the data structure
double lookup_temperature(TemperatureData* data, uint64_t key) {
    int index = key % data->capacity; // Calculate the index using a simple hash function

    pthread_mutex_lock(&data->lock); // Acquire lock for concurrent access

    Entry* entry = &data->data[index * ENTRY_SIZE / sizeof(Entry)];
    while (entry->key != 0) {
        if (entry->key == key) { // Found the desired temperature measurement
            pthread_mutex_unlock(&data->lock); // Release lock for concurrent access
            return entry->value;
        }
        index = (index + 1) % data->capacity; // Move to the next slot
    }

    pthread_mutex_unlock(&data->lock); // Release lock for concurrent access

    return -1.0; // Temperature measurement not found
}

// Function to delete a temperature measurement from the data structure
void remove_temperature(TemperatureData* data, uint64_t key) {
    int index = key % data->capacity; // Calculate the index using a simple hash function

    pthread_mutex_lock(&data->lock); // Acquire lock for concurrent access

    Entry* entry = &data->data[index * ENTRY_SIZE / sizeof(Entry)];
    while (entry->key != 0) {
        if (entry->key == key) { // Found the desired temperature measurement
            entry->key = 0; // Mark as deleted
            data->size--;
            pthread_mutex_unlock(&data->lock); // Release lock for concurrent access
            return;
        }
        index = (index + 1) % data->capacity; // Move to the next slot
    }

    pthread_mutex_unlock(&data->lock); // Release lock for concurrent access

    // Temperature measurement not found
}

// Function to serialize the temperature data structure to disk
void serialize_temperature_data(TemperatureData* data, FILE* file) {
    fwrite((void*)&data->size, sizeof(uint32_t), 1, file);
    fwrite((void*)&data->capacity, sizeof(uint32_t), 1, file);

    for (uint32_t i = 0; i < data->capacity; i++) {
        Entry* entry = &data->data[i * ENTRY_SIZE / sizeof(Entry)];
        if (entry->key != 0) {
            fwrite((void*)&entry->key, sizeof(uint64_t), 1, file);
            fwrite((void*)&entry->value, sizeof(double), 1, file);
        }
    }
}

// Function to deserialize the temperature data structure from disk
TemperatureData* deserialize_temperature_data(FILE* file) {
    TemperatureData* data = init_temperature_data();

    fread((void*)&data->size, sizeof(uint32_t), 1, file);
    fread((void*)&data->capacity, sizeof(uint32_t), 1, file);

    for (uint32_t i = 0; i < data->capacity; i++) {
        Entry* entry = &data->data[i * ENTRY_SIZE / sizeof(Entry)];
        if (entry->key != 0) {
            fread((void*)&entry->key, sizeof(uint64_t), 1, file);
            fread((void*)&entry->value, sizeof(double), 1, file);
        }
    }

    return data;
}

// Function to resize the temperature data structure
void resize_data(TemperatureData* data) {
    uint32_t new_capacity = data->capacity * 2; // Double the current capacity

    Entry* new_data = (Entry*)calloc(new_capacity * ENTRY_SIZE, 1);

    for (uint32_t i = 0; i < data->size; i++) {
        int index = data->data[i * ENTRY_SIZE / sizeof(Entry)].key % data->capacity;
        new_data[index * ENTRY_SIZE / sizeof(Entry)] = data->data[i * ENTRY_SIZE / sizeof(Entry)];
    }

    free(data->data);
    data->data = new_data;
    data->capacity = new_capacity;
}
