    srand(time(NULL));
} RecordManager;

RecordManager* record_manager_create(int initial_capacity) {
    RecordManager* manager = (RecordManager*)malloc(sizeof(RecordManager));
    manager->size = 0;
    manager->capacity = initial_capacity;
    manager->records = (Record*)calloc(initial_capacity, sizeof(Record));
    manager->keys = (int*)calloc(initial_capacity, sizeof(int));
    for (int i = 0; i < initial_capacity; i++) {
        manager->last_accessed[i] = -1;
    }
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void record_manager_insert(RecordManager* manager, int key, long offset) {
    if (key >= manager->capacity) {
        // resize array
        manager->capacity *= 2;
        manager->records = (Record*)realloc(manager->records, sizeof(Record) * manager->capacity);
        manager->keys = (int*)realloc(manager->keys, sizeof(int) * manager->capacity);
        for (int i = 0; i < manager->size; i++) {
            manager->last_accessed[i] = -1;
        }
    }
    Record record = {key, offset};
    manager->records[manager->size] = record;
    manager->keys[manager->size] = key;
    manager->last_accessed[key] = manager->size++;
}

Record* record_manager_get(RecordManager* manager, int key) {
    for (int i = 0; i < manager->size; i++) {
        if (manager->keys[i] == key) {
            return &manager->records[i];
        }
    }
    return NULL;
}

void record_manager_delete(RecordManager* manager, int key) {
    for (int i = 0; i < manager->size; i++) {
        if (manager->keys[i] == key) {
            // move last record to the current position
            Record temp = manager->records[manager->size - 1];
            manager->records[i] = temp;
            manager->keys[i] = manager->keys[manager->size - 1];
            // update last accessed index
            manager->last_accessed[key] = i;
            manager->size--;
            return;
        }
    }
}

int record_manager_get_most_frequent(RecordManager* manager) {
    int max_count = 0;
    int most_frequent_key = -1;
    for (int i = 0; i < manager->capacity; i++) {
        if (manager->last_accessed[i] > max_count) {
            max_count = manager->last_accessed[i];
            most_frequent_key = i;
        }
    }
    return most_frequent_key;
}

void record_manager_serialize(RecordManager* manager, FILE* file) {
    fwrite(&manager->size, sizeof(int), 1, file);
    for (int i = 0; i < manager->size; i++) {
        Record record = manager->records[i];
        fwrite(&record.key, sizeof(int), 1, file);
        fwrite(&record.offset, sizeof(long), 1, file);
    }
}

RecordManager* record_manager_deserialize(FILE* file) {
    int size;
    fread(&size, sizeof(int), 1, file);
    RecordManager* manager = (RecordManager*)malloc(sizeof(RecordManager));
    manager->size = size;
    manager->capacity = size * 2;
    manager->records = (Record*)calloc(manager->capacity, sizeof(Record));
    manager->keys = (int*)calloc(manager->capacity, sizeof(int));
    for (int i = 0; i < manager->size; i++) {
