        fread(&record.offset, sizeof(long), 1, file);
        manager->records[i] = record;
        manager->keys[i] = record.key;
    }
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void record_manager_close(RecordManager* manager) {
    free(manager->records);
    free(manager->keys);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
