#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int value;
} Record;

typedef struct DynamicRecordManager {
    long *offsets;
    int *keys;
    Record **records;
    int numRecords;
    int capacity;
    struct {
        int minFreq;
        time_t lastAccessTime;
    } *keyStats;
    int numKeyStats;
    int capacityKeyStats;
} DynamicRecordManager;

DynamicRecordManager* dynamicRecordManagerCreate(int initialCapacity) {
    DynamicRecordManager* manager = (DynamicRecordManager*)malloc(sizeof(DynamicRecordManager));
    manager->offsets = (long*)malloc(initialCapacity * sizeof(long));
    manager->keys = (int*)malloc(initialCapacity * sizeof(int));
    manager->records = (Record**)malloc(initialCapacity * sizeof(Record*));
    manager->numRecords = 0;
    manager->capacity = initialCapacity;
    manager->keyStats = (struct { int minFreq; time_t lastAccessTime; } *)malloc(initialCapacity * sizeof(struct { int minFreq; time_t lastAccessTime; }));
    manager->numKeyStats = 0;
    manager->capacityKeyStats = initialCapacity;
    return manager;
}

void dynamicRecordManagerDestroy(DynamicRecordManager* manager) {
    free(manager->offsets);
    free(manager->keys);
    for (int i = 0; i < manager->numRecords; i++) {
        free(manager->records[i]);
    }
    free(manager->records);
    free(manager->keyStats);
    free(manager);
}

void dynamicRecordManagerInsert(DynamicRecordManager* manager, int key, int value) {
    if (manager->numRecords >= manager->capacity) {
        manager->capacity *= 2;
        manager->offsets = (long*)realloc(manager->offsets, manager->capacity * sizeof(long));
        manager->keys = (int*)realloc(manager->keys, manager->capacity * sizeof(int));
        manager->records = (Record**)realloc(manager->records, manager->capacity * sizeof(Record*));
        manager->keyStats = (struct { int minFreq; time_t lastAccessTime; } *)realloc(manager->keyStats, manager->capacity * sizeof(struct { int minFreq; time_t lastAccessTime; }));
    }
    Record* newRecord = (Record*)malloc(sizeof(Record));
    newRecord->value = value;
    manager->offsets[manager->numRecords] = (long)manager->keys[manager->numRecords];
    manager->keys[manager->numRecords] = key;
    manager->records[manager->numRecords] = newRecord;
    manager->keyStats[manager->numRecords].minFreq = 1;
    manager->keyStats[manager->numRecords].lastAccessTime = time(NULL);
    manager->numRecords++;
}

void dynamicRecordManagerDelete(DynamicRecordManager* manager, int key) {
    for (int i = 0; i < manager->numRecords; i++) {
        if (manager->keys[i] == key) {
            free(manager->records[i]);
            for (int j = i + 1; j < manager->numRecords; j++) {
                manager->offsets[j - 1] = manager->offsets[j];
                manager->keys[j - 1] = manager->keys[j];
                manager->keyStats[j - 1].minFreq = manager->keyStats[j].minFreq;
            }
            manager->numRecords--;
            i--;
        }
    }
}

int dynamicRecordManagerGet(DynamicRecordManager* manager, int key) {
    for (int i = 0; i < manager->numRecords; i++) {
        if (manager->keys[i] == key) {
            return manager->records[i]->value;
        }
    }
    return -1;
}

void dynamicRecordManagerPurge(DynamicRecordManager* manager, int minFreq, time_t ageLimit) {
    for (int i = 0; i < manager->numRecords; i++) {
        if (manager->keyStats[i].minFreq < minFreq || time(NULL) - manager->keyStats[i].lastAccessTime > ageLimit) {
            free(manager->records[i]);
            for (int j = i + 1; j < manager->numRecords; j++) {
                manager->offsets[j - 1] = manager->offsets[j];
                manager->keys[j - 1] = manager->keys[j];
                manager->keyStats[j - 1].minFreq = manager->keyStats[j].minFreq;
            }
            manager->numRecords--;
            i--;
        }
    }
}

int dynamicRecordManagerGetMostFrequentlyAccessedKey(DynamicRecordManager* manager) {
    int maxFreq = 0;
    int mostFrequentKey = -1;
    for (int i = 0; i < manager->numRecords; i++) {
        if (manager->keyStats[i].minFreq > maxFreq) {
            maxFreq = manager->keyStats[i].minFreq;
            mostFrequentKey = manager->keys[i];
        }
    }
    return mostFrequentKey;
}

int dynamicRecordManagerGenerateRandomKey(int min, int max, int seed) {
    srand(seed);
    return rand() % (max - min + 1) + min;
}
