#define MAX_RECORDS 10000
#define RECORD_SIZE sizeof(struct Record)

typedef struct {
    int key;
    uint8_t data;
} Record;

typedef struct {
    Record *records;
    int *offsets;
    int *last_accessed;
    int size;
    int capacity;
} RecordManager;

RecordManager* record_manager_new(int capacity) {
    RecordManager* manager = malloc(sizeof(RecordManager));
    manager->size = 0;
    manager->capacity = capacity;
    manager->records = malloc(capacity * RECORD_SIZE);
    manager->offsets = malloc((capacity + 1) * sizeof(int));
    manager->last_accessed = malloc((capacity + 1) * sizeof(int));
    return manager;
}

void record_manager_free(RecordManager* manager) {
    free(manager->records);
    free(manager->offsets);
    free(manager->last_accessed);
    free(manager);
}

int record_manager_insert(RecordManager* manager, int key, uint8_t data) {
    if (manager->size == manager->capacity) {
        // Resize the arrays
        manager->capacity *= 2;
        RecordManager* new_manager = record_manager_new(manager->capacity);
        memcpy(new_manager->records, manager->records, RECORD_SIZE * manager->size);
        memcpy(new_manager->offsets, manager->offsets, (manager->capacity + 1) * sizeof(int));
        memcpy(new_manager->last_accessed, manager->last_accessed, (manager->capacity + 1) * sizeof(int));

        // Update the last accessed index for the new record
        int new_last_accessed = manager->size;
        if (new_manager->offsets[0] == -1) {
            new_manager->last_accessed[0] = new_last_accessed;
        } else {
            new_manager->last_accessed[new_manager->offsets[0]] = new_last_accessed;
        }

        // Free the old manager
        record_manager_free(manager);
        manager = new_manager;
    }

    int offset = manager->size;
    if (manager->offsets[offset] == -1) {
        manager->last_accessed[offset] = 0;
    } else {
        manager->last_accessed[manager->offsets[offset]] = 0;
    }
    manager->records[offset].key = key;
    manager->records[offset].data = data;
    manager->offsets[++manager->size] = offset;
    return offset;
}

int record_manager_delete(RecordManager* manager, int key) {
    for (int i = 0; i < manager->size; i++) {
        if (manager->records[i].key == key) {
            // Update the last accessed index
            if (i == manager->offsets[0]) {
                manager->last_accessed[0] = 0;
            } else {
                int new_last_accessed = i;
                for (int j = 0; j < manager->size; j++) {
                    if (manager->records[j].key == key) {
                        manager->last_accessed[new_last_accessed] = j;
                        break;
                    }
                }
            }

            // Shift the records and offsets
            for (int j = i + 1; j < manager->size; j++) {
                int new_offset = j - 1;
                if (j == manager->offsets[0]) {
                    manager->last_accessed[0] = j;
                } else {
                    manager->last_accessed[new_offset] = j;
                }
                manager->offsets[j] = new_offset;
            }

            // Update the size
            manager->size--;
            return 1;
        }
    }
    return 0;
}

int record_manager_get(RecordManager* manager, int key) {
    for (int i = 0; i < manager->size; i++) {
        if (manager->records[i].key == key) {
            return manager->last_accessed[i];
        }
    }
    return -1;
}

void record_manager_serialize(RecordManager* manager, FILE* file) {
    fwrite(&manager->size, sizeof(int), 1, file);
    for (int i = 0; i < manager->size; i++) {
        fwrite(&manager->records[i].key, sizeof(int), 1, file);
        fwrite(&manager->records[i].data, RECORD_SIZE - sizeof(int), 1, file);
    }
}

RecordManager* record_manager_deserialize(FILE* file) {
    RecordManager* manager = malloc(sizeof(RecordManager));
    int size;
    fread(&size, sizeof(int), 1, file);
    manager->size = size;
    manager->records = malloc(size * RECORD_SIZE);
    manager->offsets = malloc((size + 1) * sizeof(int));
    manager->last_accessed = malloc((size + 1) * sizeof(int));

    for (int i = 0; i < size; i++) {
        Record record;
        fread(&record.key, sizeof(int), 1, file);
        fread(record.data, RECORD_SIZE - sizeof(int), 1, file);
        manager->records[i] = record;
    }

    return manager;
}

int random_key_generator_set_seed(int seed) {
    srand(seed);
}

void random_key_generator_reset_seed() {
    srand(time(NULL));
}

int random_key_generator_get_random_key(int min, int max) {
    while (1) {
        int key = rand() % (max - min + 1) + min;
        for (int i = 0; i < manager->size; i++) {
            if (manager->records[i].key == key) {
                return random_key_generator_get_random_key(min, max);
            }
        }
        return key;
    }
}

