typedef struct {
    char* username;
    char* email;
    int role_count;
    struct {
        char** roles;
        int size;
    } role_list;
} UserProfile;

typedef struct {
    UserProfile* profiles;
    int count;
    int capacity;
} UserProfiles;

void resize(UserProfiles* profiles, int new_capacity) {
    if (new_capacity < 1) return;

    UserProfile* new_profiles = (UserProfile*) realloc(profiles->profiles, sizeof(*new_profiles) * new_capacity);
    if (!new_profiles) return;

    profiles->capacity = new_capacity;
    profiles->profiles = new_profiles;
}

void add_profile(UserProfiles* profiles, char* username, char* email) {
    UserProfile* profile = (UserProfile*) malloc(sizeof(*profile));
    if (!profile) return;

    profile->username = strdup(username);
    profile->email = strdup(email);

    int role_count = rand() % 10 + 1;
    profile->role_list.roles = (char**) malloc(sizeof(char*) * role_count);
    profile->role_list.size = role_count;

    for (int i = 0; i < role_count; i++) {
        char* role = (char*) malloc(strlen("Role") + strlen("/role") + 1);
        sprintf(role, "Role/%d", i);
        profile->role_list.roles[i] = role;
    }

    int insert_index = profiles->count++;
    if (profiles->count >= profiles->capacity) resize(profiles, profiles->capacity * 2);

    if (profiles->count > 0 && insert_index < profiles->count - 1) {
        UserProfile* prev_profile = &profiles->profiles[insert_index - 1];
        UserProfile* next_profile = &profiles->profiles[insert_index];

        int prev_role_count = prev_profile->role_list.size;
        int next_role_count = next_profile->role_list.size;

        profile->role_list.roles[0] = prev_profile->role_list.roles[prev_role_count - 1];
        prev_profile->role_list.size--;

        if (next_role_count > 0) {
            strcpy(profile->role_list.roles[profile->role_list.size - 1], next_profile->role_list.roles[0]);
            profile->role_list.size++;
            next_profile->role_list.size--;
        }
    }

    UserProfile* prev_profile = &profiles->profiles[insert_index];
    int i;
    for (i = 0; i < role_count; i++) {
        free(prev_profile->role_list.roles[i]);
    }
    free(profile);
}

void remove_profile(UserProfiles* profiles, char* username) {
    int index = -1;

    for (int i = 0; i < profiles->count; i++) {
        if (!strcmp(profiles->profiles[i]->username, username)) {
            index = i;
            break;
        }
    }

    if (index >= 0) {
        UserProfile* profile = &profiles->profiles[index];

        for (int i = 0; i < profile->role_list.size; i++) {
            free(profile->role_list.roles[i]);
        }

        free(profile->username);
        free(profile->email);

        int last_index = profiles->count - 1;
        if (index != last_index) {
            UserProfile* prev_profile = &profiles->profiles[last_index];
            *profile = *prev_profile;

            for (int i = index; i < last_index; i++) {
                profiles->profiles[i] = profiles->profiles[i + 1];
            }

            profiles->count--;
        } else {
            free(profile);
        }
    }
}

void free_profiles(UserProfiles* profiles) {
    for (int i = 0; i < profiles->count; i++) {
        UserProfile* profile = &profiles->profiles[i];

        for (int j = 0; j < profile->role_list.size; j++) {
            free(profile->role_list.roles[j]);
        }

        free(profile->username);
        free(profile->email);

        free(profile);
    }

    free(profiles->profiles);
}

int main() {
    srand(time(NULL));

    UserProfiles profiles;
    profiles.count = 0;

    for (int i = 0; i < 10000; i++) {
        char* username = (char*) malloc(20);
        sprintf(username, "User-%d", i);

        add_profile(&profiles, username, "user@example.com");

        free(username);
    }

    return 0;
}

