#define MAX_ENTRIES 1000000
#define MAX_KEY_SIZE 64
#define TIMESTAMP_RESOLUTION 1 // seconds
#define DEFAULT_CACHE_SIZE 10000
#define DEFAULT_EVICTION_THRESHOLD 10

typedef struct {
    uint64_t key;
    size_t value;
    time_t timestamp;
} cache_entry;

// Dynamic array of cache entries
cache_entry* cache_entries = NULL;
size_t cache_size = DEFAULT_CACHE_SIZE;
size_t cache_entries_allocated = 0;

// Hash table for fast lookups
unsigned char* hash_table = NULL;
size_t hash_table_allocated = 0;
size_t hash_table_capacity = 10000; // Initial capacity

// LRU eviction policy configuration
int eviction_threshold = DEFAULT_EVICTION_THRESHOLD;

void init_cache(size_t desired_cache_size) {
    cache_size = desired_cache_size;
    cache_entries = (cache_entry*)malloc(cache_size * sizeof(cache_entry));
    cache_entries_allocated = cache_size;

    hash_table_capacity = desired_cache_size / 10 + 1; // Initial capacity
    hash_table = (unsigned char*)malloc(hash_table_capacity * sizeof(unsigned char));
    hash_table_allocated = hash_table_capacity;
}

void resize_hash_table(size_t new_capacity) {
    unsigned char* new_hash_table = (unsigned char*)malloc(new_capacity * sizeof(unsigned char));
    size_t i;
    for (i = 0; i < new_capacity; i++) {
        new_hash_table[i] = hash_table[i];
    }
    free(hash_table);
    hash_table = new_hash_table;
    hash_table_allocated = new_capacity;
}

void resize_cache_entries(size_t new_size) {
    cache_entry* new_cache_entries = (cache_entry*)malloc(new_size * sizeof(cache_entry));
    size_t i;
    for (i = 0; i < new_size; i++) {
        new_cache_entries[i] = cache_entries[i];
    }
    free(cache_entries);
    cache_entries = new_cache_entries;
    cache_entries_allocated = new_size;
}

void add_entry(uint64_t key, size_t value) {
    // Find the next available slot in the hash table
    size_t index = key % hash_table_capacity;

    // Check if there's an existing entry at this position
    while (hash_table[index]) {
        index = (index + 1) % hash_table_capacity;
    }

    // Add the new entry to the cache and update the timestamp
    size_t i;
    for (i = 0; i < cache_size; i++) {
        if (!cache_entries[i].key) {
            cache_entries[i].key = key;
            cache_entries[i].value = value;
            cache_entries[i].timestamp = time(NULL);
            break;
        }
    }

    // Update the hash table with the new entry's index
    hash_table[index] = i;
}

void evict_entry() {
    size_t oldest_index = 0; // LRU policy: eviction is based on timestamp
    for (size_t i = 1; i < cache_size; i++) {
        if (cache_entries[i].timestamp < cache_entries[oldest_index].timestamp) {
            oldest_index = i;
        }
    }

    // Evict the oldest entry and update the hash table
    uint64_t key = cache_entries[oldest_index].key;
    size_t value = cache_entries[oldest_index].value;
    hash_table[hash_table[(int)key % hash_table_capacity]] = 0;
}

