        if (file == NULL) return;

        int frameCount = 0;
        fread(&frameCount, sizeof(int), 1, file);

        frames = (frame**)malloc(frameCount * sizeof(frame*));
        buffers = (unsigned char**)malloc(frameCount * sizeof(unsigned char*));
        lengths = (size_t*)malloc(frameCount * sizeof(size_t));

        for (int i = 0; i < frameCount; i++) {
            fread(&frames[i]->timestamp, sizeof(uint32_t), 1, file);
            fread(&frames[i]->length, sizeof(size_t), 1, file);

            buffers[i] = (unsigned char*)malloc(frames[i]->length * sizeof(unsigned char));
            fread(buffers[i], sizeof(unsigned char), frames[i]->length, file);

            lengths[i] = frames[i]->length;
        }

        fclose(file);
    }

    // Function to serialize the data structure to a file
    void serialize(char* filename) {
        FILE* file = fopen(filename, "wb");
        if (file == NULL) return;

        fwrite(&frameCount, sizeof(int), 1, file);

        for (int i = 0; i < frameCount; i++) {
            fwrite(&frames[i]->timestamp, sizeof(uint32_t), 1, file);
            fwrite(&frames[i]->length, sizeof(size_t), 1, file);

            fwrite(frames[i]->buffer, sizeof(unsigned char), frames[i]->length, file);
        }

        fclose(file);
    }
