Record* record_array = NULL;
int* key_array = NULL;
long* offset_array = NULL;
HashTable* hash_table = NULL;
unsigned long record_count = 0;

void initialize_arrays(int array_size) {
    record_array = (Record*)malloc(array_size * sizeof(Record));
    key_array = (int*)malloc(array_size * sizeof(int));
    offset_array = (long*)malloc(array_size * sizeof(long));

    for (int i = 0; i < array_size; i++) {
        record_array[i].value = rand() % 100;
        record_array[i].timestamp = time(NULL);
        record_array[i].ref_count = 1;

        key_array[i] = i;
        offset_array[i] = i * 10;
    }
}

void insert_record(int key, int value) {
    if (hash_table_insert(hash_table, key, &record_array[key])) {
        printf("Error: Duplicate key inserted\n");
        return;
    }

    record_array[key].value = value;
    record_array[key].timestamp = time(NULL);
}

int get_record_value(int key) {
    HashEntry* entry = hash_table_lookup(hash_table, key);

    if (entry == NULL) {
        printf("Error: Key not found\n");
        return -1;
    }

    return ((Record*)entry->value)->value;
}

void update_record_value(int key, int value) {
    HashEntry* entry = hash_table_lookup(hash_table, key);

    if (entry == NULL) {
        printf("Error: Key not found\n");
        return;
    }

    ((Record*)entry->value)->value = value;
}

void increment_ref_count(int key) {
    record_array[key].ref_count++;
}

void decrement_ref_count_and_delete(int key) {
    HashEntry* entry = hash_table_lookup(hash_table, key);

    if (entry == NULL) {
        printf("Error: Key not found\n");
        return;
    }

    ((Record*)entry->value)->ref_count--;

    if (((Record*)entry->value)->ref_count == 0) {
        free((Record*)entry->value);
        hash_table_delete(hash_table, key);

        // Rebalance the hash table to maintain performance
        // ...
    }
}

void cleanup() {
    for (int i = 0; i < record_count; i++) {
        if (record_array[i].ref_count == 0) {
            free(&record_array[i]);
        }
    }

    free(record_array);
    free(key_array);
    free(offset_array);

    hash_table_cleanup(hash_table);
}
