typedef struct {
    float *float_array;
    double *double_array;
    char **char_array;
} MemoryStruct;

MemoryStruct* manage_memory(size_t float_length, size_t double_length, size_t char_rows, size_t char_cols, unsigned int seed) {
    MemoryStruct* memory = (MemoryStruct*)malloc(sizeof(MemoryStruct));
    if (!memory) return NULL; // Handle allocation failure

    memory->float_array = (float*)malloc(float_length * sizeof(float));
    if (!memory->float_array) {
        free(memory);
        return NULL;
    }

    memory->double_array = (double*)malloc(double_length * sizeof(double));
    if (!memory->double_array) {
        free(memory->float_array);
        free(memory);
        return NULL;
    }

    memory->char_array = (char**)malloc(char_rows * sizeof(char*));
    for (size_t i = 0; i < char_rows; i++) {
        memory->char_array[i] = (char*)malloc((1 << (char_cols - __builtin_ctz(i) % char_cols)) * sizeof(char));
        if (!memory->char_array[i]) {
            for (size_t j = i; j > 0; j--) {
                free(memory->char_array[j-1]);
            }
            for (size_t j = 0; j < i; j++) {
                free(memory->char_array[j]);
            }
            free(memory->double_array);
            free(memory->float_array);
            free(memory);
            return NULL;
        }

        srand(seed); // Seed random number generator
        for (size_t j = 0; j < (1 << (char_cols - __builtin_ctz(i) % char_cols)); j++) {
            memory->char_array[i][j] = (char)(i + j);
        }
    }

    return memory;
}

void free_memory(MemoryStruct* memory) {
    if (!memory) return;

    for (size_t i = 0; i < memory->char_rows; i++) {
        free(memory->char_array[i]);
    }
    free(memory->char_array);
    free(memory->double_array);
    free(memory->float_array);
    free(memory);
}
