#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Structure representing a database record
typedef struct {
    int key;
    int value;
    char* string;
} Record;

// Function to dynamically allocate memory for and initialize multiple records
Record** allocateRecords(int numRecords, int* budget) {
    Record** records = (Record**)malloc(numRecords * sizeof(Record*));
    if (!records) return NULL;  // Handle insufficient memory

    for (int i = 0; i < numRecords; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) return NULL;  // Handle insufficient memory
        records[i]->key = -1;
        records[i]->value = -1;
        records[i]->string = (char*)calloc(257, sizeof(char));  // 256 + null terminator
        strcpy(records[i]->string, "");
    }

    *budget -= numRecords * sizeof(Record) + numRecords * 257;  // Update memory budget

    return records;
}

// Function to retrieve a specific record by its key
Record* findRecord(int key, Record** records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        if (records[i]->key == key) return records[i];
    }
    // Key not found, return "not found" structure
    Record* record = (Record*)malloc(sizeof(Record));
    record->key = -1;
    record->value = -1;
    record->string = (char*)calloc(257, sizeof(char));  // 256 + null terminator
    strcpy(record->string, "Not Found");
    return record;
}

// Function to handle memory pressure by evicting less frequently accessed records
void evictRecords(int threshold, Record** records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        if (!records[i]->key && !records[i]->value) {  // Less frequently accessed record
            free(records[i]->string);  // Evict the record by freeing its string
            free(records[i]);
        }
    }
}

// Function to concurrently read and write records while managing memory fragmentation
void* databaseThreadFunc(void* arg) {
    Record** records = (Record**)arg;
    int numRecords = *records;  // Number of records

    // Simulate concurrent operations
    for (int i = 0; i < 10000; i++) {  // Example: simulate 10,000 read and write operations
        int key = rand() % numRecords;  // Randomly select a record to access
        Record* record = findRecord(key, records, numRecords);
        if (record) {
            printf("Accessed record with key %d\n", key);
            free(record->string);  // Clean up after accessing the record
            free(record);
        }
    }

    return NULL;
}

// Function to coalesce free blocks into larger contiguous spaces
void* compactionThreadFunc(void* arg) {
    Record** records = (Record**)arg;
    int numRecords = *records;  // Number of records

    // Simulate compaction by merging adjacent free blocks
    for (int i = 0; i < numRecords - 1; i++) {
        if (!records[i]->key && !records[i+1]->key) {  // Two consecutive free blocks
            free(records[i]->string);  // Merge the blocks by freeing one of them
        }
    }

    return NULL;
}

int main() {
    int numRecords = 100;  // Example: allocate memory for 100 records
    int budget = 1024 * 1024;  // Example: set a memory budget of 1 MB

    Record** records = allocateRecords(numRecords, &budget);
    if (!records) return -1;  // Handle insufficient memory

    pthread_t threads[2];  // Create two threads for concurrent operations
    pthread_create(&threads[0], NULL, databaseThreadFunc, records);
    pthread_create(&threads[1], NULL, compactionThreadFunc, records);

    for (int i = 0; i < numRecords; i++) {
        free(records[i]->string);  // Clean up after using the records
        free(records[i]);
    }

    return 0;
}

