    for (int i = 0; i < numRecords; i++) {
        (*records)[i] = (record *)malloc(sizeof(record));
        (*records)[i]->key = newKeys[i];
        (*records)[i]->offset = newOffsets[i];
        (*records)[i]->type = newTypes[i];
    }

    return *records;
}

