        logArray[i] = (logEntry*)malloc(sizeof(logEntry));
    }

    int* timestampArr = (int*)malloc(numEntries * sizeof(int));
    enum severityLevel* levelArr = (enum severityLevel*)malloc(numEntries * sizeof(enum severityLevel));
    char** messageArr = (char**)malloc(numEntries * sizeof(char*));

    for(int i=0; i<numEntries; i++) {
