        scanf("%d %d %s", &timestampArr[i], &levelArr[i], messageArr[i]);
        logArray[i]->timestamp = timestampArr[i];
        logArray[i]->level = levelArr[i];
        logArray[i]->message = messageArr[i];
    }

    int* lastAccessedIndexArr = (int*)malloc(numEntries * sizeof(int));
    for(int i=0; i<numEntries; i++) {
