    }

    return logArray;
}

void freeLogSystem(logEntry** logArray, int numEntries) {
    for(int i=0; i<numEntries; i++) {
        if(logArray[i]->message != NULL)
            free(logArray[i]->message);
        free(logArray[i]);
    }
    free(logArray);

    free(lastAccessedIndexArr);
}

void serializeLogSystem(logEntry** logArray, int numEntries) {
    FILE* file = fopen("logsystem.dat", "wb");
    for(int i=0; i<numEntries; i++) {
        fwrite(&logArray[i]->timestamp, sizeof(int), 1, file);
        fwrite(&logArray[i]->level, sizeof(enum severityLevel), 1, file);
        size_t len = strlen(logArray[i]->message);
        fwrite(&len, sizeof(size_t), 1, file);
        fwrite(logArray[i]->message, sizeof(char), len, file);
    }
    fclose(file);
}

void deserializeLogSystem() {
    FILE* file = fopen("logsystem.dat", "rb");
    int numEntries;
    fread(&numEntries, sizeof(int), 1, file);

    logEntry** logArray = (logEntry**)malloc(numEntries * sizeof(logEntry*));
    for(int i=0; i<numEntries; i++) {
        logArray[i] = (logEntry*)malloc(sizeof(logEntry));
    }

    int* timestampArr = (int*)malloc(numEntries * sizeof(int));
    enum severityLevel* levelArr = (enum severityLevel*)malloc(numEntries * sizeof(enum severityLevel));
    char** messageArr = (char**)malloc(numEntries * sizeof(char*));

    for(int i=0; i<numEntries; i++) {
        fread(&logArray[i]->timestamp, sizeof(int), 1, file);
        fread(&logArray[i]->level, sizeof(enum severityLevel), 1, file);
        size_t len;
        fread(&len, sizeof(size_t), 1, file);
        logArray[i]->message = (char*)malloc(len+1);
        fread(logArray[i]->message, sizeof(char), len, file);
        logArray[i]->message[len] = '\0';
    }

    fclose(file);

    // Implement the filter and print method
    void filterAndPrint(enum severityLevel level) {
        for(int i=0; i<numEntries; i++) {
            if(logArray[i]->level == level)
                printf("%d: %s\n", logArray[i]->timestamp, logArray[i]->message);
        }
    }

    // Implement the frequency method
    void calculateFrequency() {
        int frequencies[4] = {0, 0, 0, 0};
        for(int i=0; i<numEntries; i++) {
            switch(logArray[i]->level) {
                case DEBUG:
                    frequencies[0]++;
                    break;
                case INFO:
                    frequencies[1]++;
                    break;
                case WARNING:
                    frequencies[2]++;
                    break;
                case ERROR:
                    frequencies[3]++;
                    break;
            }
        }
        for(int i=0; i<4; i++) {
            printf("Frequency of %s: %d\n", (i==0)?"DEBUG":(i==1)?"INFO":(i==2)?"WARNING":"ERROR", frequencies[i]);
        }
    }

    // Implement the error handling mechanism
    void handleErrors() {
        // Add your error handling code here
    }
}

int main() {
    logEntry** logArray = manageLogSystem();
    // Call other methods as needed

    freeLogSystem(logArray, numEntries);

    return 0;
}
