#include <string.h>

typedef struct {
    double value;
    int timestamp;
    enum { UP, DOWN, OK } status;
} metric_t;

metric_t* processAndManageMetrics(int* num_metrics) {
    *num_metrics = 0;

    // Initialize arrays
    int* timestamps = (int*)malloc(sizeof(int));
    double* values = (double*)malloc(sizeof(double));
    metric_t** metrics = (metric_t**)malloc(sizeof(metric_t*));

    while (*num_metrics < 10000000) { // 10 million metrics limit
        int timestamp;
        double value;

        // Read values from standard input
        scanf("%d %lf", &timestamp, &value);

        // Ensure unique timestamps
        for (int i = 0; i < *num_metrics; i++) {
            if (timestamps[i] == timestamp) {
                printf("Error: Duplicate timestamp detected. Skipping.\n");
                continue;
            }
        }

        // Allocate memory for new metric
        int* new_timestamps = (int*)realloc(timestamps, (*num_metrics + 1) * sizeof(int));
        double* new_values = (double*)realloc(values, (*num_metrics + 1) * sizeof(double));
        metric_t** new_metrics = (metric_t**)realloc(metrics, (*num_metrics + 1) * sizeof(metric_t*));

        // Initialize new metric
        timestamps = new_timestamps;
        values = new_values;
        metrics = new_metrics;
        *num_metrics += 1;
        metrics[*num_metrics - 1] = (metric_t*)malloc(sizeof(metric_t));
        metrics[*num_metrics - 1]->value = value;
        metrics[*num_metrics - 1]->timestamp = timestamp;

        // Update last accessed index for each timestamp
        int* last_accessed_timestamps = (int*)malloc(sizeof(int) * (*num_metrics + 1));
        for (int i = 0; i < *num_metrics; i++) {
            last_accessed_timestamps[i] = timestamps[i];
        }

        // Free memory if necessary
        free(timestamps);
    }

    return metrics;
}
