void initAESCipher(char* passphrase, unsigned char** key, unsigned char** iv) {
    // Initialize OpenSSL library
    EVP_add_protocol(EVP_PKEY_METHOD);

    // Generate a random 32-byte key using the given passphrase
    unsigned char* key_bytes = (unsigned char*)malloc(32);
    const EVP_MD *md = EVP_md5();
    EVP_MD_CTX md_ctx;
    unsigned char* digest = (unsigned char*)malloc(EVP_MAX_DIGEST_SIZE);
    int len = EVP_MD_size(md);

    EVP_MD_CTX_init(&md_ctx);
    EVP_DigestInit_ex(&md_ctx, md, NULL);
    EVP_DigestUpdate(&md_ctx, passphrase, strlen(passphrase));
    EVP_DigestFinal_ex(&md_ctx, digest, &len);

    // Derive the key from the digest
    const char* salt = "salt_string";
    int iterations = 100000;
    unsigned char* derived_key = (unsigned char*)malloc(32);
    PBKDF2(key_bytes, len, salt, strlen(salt), iterations, 32, derived_key);

    // Initialize AES-256-CBC cipher
    AES_KEY aes_key;
    AES_cbc_encrypt(NULL, &aes_key, NULL, iv, NULL, 0);

    *key = key_bytes;
    *iv = (unsigned char*)malloc(16);
}
