            if( datapoint->timestamp == timestamps[j] || 
               datapoint->sensorId == sensorIds[j]) {
                i--;  // data point already exists, roll back
                break;
            }
        }
    }

    (*dataPointsCount) += newPointsCount;

    // Real-time updates on sensor configurations
    int sensorConfigUpdate = rand() % 10;  // fetch update frequency
    if(sensorConfigUpdate < 5) {
        int newSensorsAdded = rand() % 100;
        for(int i=0; i<newSensorsAdded; i++) {
            values[(*dataPointsCount)+i] = (float)rand() / RAND_MAX;
            sensorIds[(*dataPointsCount)+i] = rand();
            timestamps[(*dataPointsCount)+i] = (double)rand() / RAND_MAX;

