    int hash_table_size = 1021;
    unsigned int *hash_table = (unsigned int *)malloc(hash_table_size * sizeof(unsigned int));
    for (int i = 0; i < hash_table_size; i++) {
        hash_table[i] = -1; // Initialize all slots to -1
