typedef struct {
    int key;
    long offset;
    short value;
} record;

record *expandGraphStructure(int **keys, long **offsets, record ***records) {
    int records_count = 0;
    int keys_capacity = 10000;
    int offsets_capacity = 10000;
    record *records_array = (record *)malloc(keys_capacity * sizeof(record));

    // Track the last accessed index of each key
    int *keys_last_index = (int *)malloc(keys_capacity * sizeof(int));
    for (int i = 0; i < keys_capacity; i++) {
        keys_last_index[i] = -1;
    }

    // Read a list of integers from standard input, storing them in an array
    int current_key;
    long current_offset;
    record new_record;
    while (scanf("%d %ld", &current_key, &current_offset) == 2) {
        // Check if the key or offset already exists in the records array
        int existing_index = -1;
        for (int i = 0; i < records_count; i++) {
            if (records_array[i].key == current_key || records_array[i].offset == current_offset) {
                existing_index = i;
                break;
            }
        }

        // If the key or offset does not exist, add a new record
        if (existing_index == -1) {
            if (records_count >= keys_capacity) {
                keys_capacity *= 2;
                offsets_capacity *= 2;
                records_array = (record *)realloc(records_array, keys_capacity * sizeof(record));
            }

            // Initialize the new record with random value
            new_record.key = current_key;
            new_record.offset = current_offset;
            new_record.value = rand() % 100;

            // Check if a key or offset is already used by another record
            int i;
            for (i = 0; i < records_count; i++) {
                if (new_record.key == records_array[i].key || new_record.offset == records_array[i].offset) {
                    break;
                }
            }

            // If a key or offset is already used, try to find the last index of the existing record
            if (i < records_count) {
                int existing_last_index = keys_last_index[records_array[i].key];
                new_record.key = i + 1;
                new_record.offset = records_array[existing_last_index].offset + 1;
            }

            // Add the new record to the array
            records_array[records_count] = new_record;
            keys_last_index[current_key] = records_count;
            records_count++;
        } else {
            // If a key or offset exists, update its last accessed index
            keys_last_index[current_key] = existing_index;
        }
    }

    *keys = (int *)malloc(keys_capacity * sizeof(int));
    for (int i = 0; i < keys_capacity; i++) {
        (*keys)[i] = i;
    }

    *offsets = (long *)malloc(offsets_capacity * sizeof(long));
    for (int i = 0; i < offsets_capacity; i++) {
        (*offsets)[i] = i;
    }

    *records = &records_array[0];

    return records_array;
}
