        *offsets = (long*) realloc(*offsets, newSize * sizeof(long));

        // Initialize the record and key arrays for a dynamic array of records
        temp[newSize-1].key = i;
        temp[newSize-1].offset = 0;
        temp[newSize-1].value = 0;

        // Update the new size with the actual number of records
        *numRecords = newSize;

        return temp;
    } else {
        return NULL;
    }
}

