// Function to create and initialize the session manager
SessionManager* createSessionManager(int initialCapacity) {
    SessionManager* manager = (SessionManager*)malloc(sizeof(SessionManager));
    manager->sessions = (SessionRecord**)malloc(initialCapacity * sizeof(SessionRecord*));
    manager->capacity = initialCapacity;
    manager->count = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

// Function to add a new session record
int addSession(SessionManager* manager, SessionRecord* session) {
    if (manager->count >= manager->capacity) {
        // Dynamically resize the storage structure when full
        int newCapacity = manager->capacity * 2;
        SessionManager* newManager = createSessionManager(newCapacity);
        for (int i = 0; i < manager->capacity; i++) {
            if (manager->sessions[i] != NULL) {
                addSession(newManager, manager->sessions[i]);
            }
        }
        free(manager->sessions);
        manager = newManager;
    }
    // Add the session record to the data structure
    manager->sessions[manager->count] = session;
    manager->count++;
    return 0;
}

// Function to remove a session record by ID
int removeSession(SessionManager* manager, char* sessionId) {
    for (int i = 0; i < manager->count; i++) {
        if (strcmp(manager->sessions[i]->sessionId, sessionId) == 0) {
            // Move the last session record to the current position and decrement count
            manager->sessions[i] = manager->sessions[--manager->count];
            return 0;
        }
    }
    return -1; // Session not found
}

