int deserializeSessionManager(SessionManager* manager, char* filename) {
    // Implement your own deserialization strategy here
    return 0;
}

// Function to terminate and clean up resources when no longer needed
void cleanupSessionManager(SessionManager* manager) {
    for (int i = 0; i < manager->capacity; i++) {
        free(manager->sessions[i]->sessionId);
        free(manager->sessions[i]);
    }
    free(manager->sessions);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

