#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

// Define the product structure
typedef struct {
    int id;
    char name[50];
    double price;
} Product;

// Define the dynamic list of products
typedef struct {
    int size;
    int capacity;
    Product* products;
} Products;

// Function to create a new products list
Products* products_new(int initial_capacity) {
    Products* list = (Products*)malloc(sizeof(Products));
    list->size = 0;
    list->capacity = initial_capacity;
    list->products = (Product*)calloc(initial_capacity, sizeof(Product));
    return list;
}

// Function to add a new product to the list
void products_add(Products* list, int id, const char* name, double price) {
    if (list->size >= list->capacity) {
        // Resize the internal storage when the current capacity is reached
        list->products = (Product*)realloc(list->products, (list->capacity *= 2) * sizeof(Product));
    }
    Product product = {id, name, price};
    list->products[list->size++] = product;
}

// Function to retrieve a product by its ID
Product* products_get(Products* list, int id) {
    for (int i = 0; i < list->size; i++) {
        if (list->products[i].id == id) {
            return &list->products[i];
        }
    }
    return NULL;
}

// Function to update the price of an existing product
void products_update_price(Products* list, int id, double new_price) {
    Product* product = products_get(list, id);
    if (product != NULL) {
        product->price = new_price;
    } else {
        printf("Product not found\n");
    }
}

// Function to serialize the products list to a file
void products_serialize(Products* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file != NULL) {
        int size = list->size;
        fwrite(&size, sizeof(int), 1, file);
        for (int i = 0; i < size; i++) {
            Product product = list->products[i];
            fwrite(&product.id, sizeof(int), 1, file);
            fwrite(product.name, sizeof(char), strlen(product.name) + 1, file);
            fwrite(&product.price, sizeof(double), 1, file);
        }
        fclose(file);
    } else {
        printf("Failed to serialize products\n");
    }
}

// Function to deserialize the products list from a file
Products* products_deserialize(const char* filename) {
    Products* list = NULL;
    FILE* file = fopen(filename, "rb");
    if (file != NULL) {
        int size;
        fread(&size, sizeof(int), 1, file);
        list = products_new(size);
        for (int i = 0; i < size; i++) {
            Product product;
            fread(&product.id, sizeof(int), 1, file);
            product.name[49] = '\0'; // Null-terminate the name
            fread(product.name, sizeof(char), 50, file);
            fread(&product.price, sizeof(double), 1, file);
            products_add(list, product.id, product.name, product.price);
        }
        fclose(file);
    } else {
        printf("Failed to deserialize products\n");
    }
    return list;
}

// Function to calculate the total value of all products
double products_get_total_value(Products* list) {
    double total = 0.0;
    for (int i = 0; i < list->size; i++) {
        total += list->products[i].price;
    }
    return total;
}

// Function to find the average price of products within a specified range
double products_get_average_price(Products* list, double min_price, double max_price) {
    int count = 0;
    double sum = 0.0;
    for (int i = 0; i < list->size; i++) {
        if (list->products[i].price >= min_price && list->products[i].price <= max_price) {
            sum += list->products[i].price;
            count++;
        }
    }
    return (count > 0) ? sum / count : 0.0;
}

int main() {
    // Example usage
    Products* list = products_new(5);
