    pthread_mutex_t mutex;
    size_t capacity;
    KeyValuePair** key_value_pairs;
} KeyValuePairsHashTable;

SessionsHashTable* create_sessions_hash_table(size_t capacity) {
    SessionsHashTable* session_hash_table = (SessionsHashTable*)malloc(sizeof(SessionsHashTable));
    session_hash_table->capacity = capacity;
    session_hash_table->sessions = (SessionRecord**)calloc(capacity, sizeof(SessionRecord*));
    pthread_mutex_init(&session_hash_table->mutex, NULL);
    return session_hash_table;
}

KeyValuePairsHashTable* create_key_value_pairs_hash_table(size_t capacity) {
    KeyValuePairsHashTable* key_value_pairs_hash_table = (KeyValuePairsHashTable*)malloc(sizeof(KeyValuePairsHashTable));
    key_value_pairs_hash_table->capacity = capacity;
    key_value_pairs_hash_table->key_value_pairs = (KeyValuePair**)calloc(capacity, sizeof(KeyValuePair*));
    pthread_mutex_init(&key_value_pairs_hash_table->mutex, NULL);
    return key_value_pairs_hash_table;
}

