    SessionsHashTable* sessions_hash_table = create_sessions_hash_table(10000);
    size_t index = hash_function(session->session_id) % sessions_hash_table->capacity;
    pthread_mutex_lock(&sessions_hash_table->mutex);
    sessions_hash_table->sessions[index] = session;
    pthread_mutex_unlock(&sessions_hash_table->mutex);
}

