#define MAX_RECORDS 10000000
#define TABLE_SIZE 1000

typedef struct {
    int key;
    long offset;
    void* metadata;
} record_t;

record_t** records = NULL;
long* offsets = NULL;
int* last_accessed = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int current_size = 0;

void init_table() {
    if (records == NULL) {
        records = (record_t**)malloc(TABLE_SIZE * sizeof(record_t*));
        offsets = (long*)malloc(TABLE_SIZE * sizeof(long));
        last_accessed = (int*)malloc(TABLE_SIZE * sizeof(int));
        for (int i = 0; i < TABLE_SIZE; i++) {
            records[i] = NULL;
            offsets[i] = -1;
            last_accessed[i] = -1;
        }
    }
}

void insert_record(record_t* record) {
    pthread_mutex_lock(&lock);
    if (current_size >= TABLE_SIZE) {
        // resize table
        records = (record_t**)realloc(records, 2 * TABLE_SIZE * sizeof(record_t*));
        offsets = (long*)realloc(offsets, 2 * TABLE_SIZE * sizeof(long));
        last_accessed = (int*)realloc(last_accessed, 2 * TABLE_SIZE * sizeof(int));
    }
    int index = record->key % TABLE_SIZE;
    if (records[index] == NULL) {
        records[index] = record;
        offsets[index] = record->offset;
        last_accessed[index] = current_size++;
    } else {
        // update existing record
        record_t* old_record = records[index];
        old_record->offset = record->offset;
        old_record->metadata = record->metadata;
        last_accessed[index] = current_size++;
    }
    pthread_mutex_unlock(&lock);
}

void print_largest_integer() {
    int max_key = 0;
    long max_offset = 0;
    for (int i = 0; i < TABLE_SIZE; i++) {
        if (records[i] != NULL && records[i]->offset > max_offset) {
            max_offset = records[i]->offset;
            max_key = records[i]->key;
        }
    }
    printf("Largest integer: %d, Offset: %ld\n", max_key, max_offset);
}

void* deserialize(void* ptr) {
    // implement deserialization logic
}

int main() {
    init_table();
    // read data from standard input and insert records
    record_t record;
    while (scanf("%d %ld", &record.key, &record.offset) == 2) {
        record.metadata = malloc(record.metadata_size);
        // handle metadata parsing and processing
        insert_record(&record);
        free(record.metadata);
    }
    print_largest_integer();
    return 0;
}
