    if (!newRecords) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    int* newKeys = realloc(keys, sizeof(int) * newSize);
    if (!newKeys) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    long* newOffsets = realloc(offsets, sizeof(long) * newSize);
    if (!newOffsets) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    records = newRecords;
    keys = newKeys;
    offsets = newOffsets;
