    fwrite(&keys, sizeof(int), 10000, file);
    fwrite(&offsets, sizeof(long), 10000, file);
    // Serialize strings
    for (int i = 0; i < 10000; i++) {
        fwrite(records[i]->str, strlen(records[i]->str) + 1, file);
    }
    fclose(file);
}

// Function to prune outdated records based on age threshold
void prune(int threshold) {
    // Iterate over records and remove those older than the threshold
    for (int i = 0; i < 10000; i++) {
        if (records[i]->val > threshold) {
            free(records[i]->str);
            free(records[i]);
            records[i] = NULL;
        }
    }
}

// Function to free all allocated memory
