void manage_data(int n) {
    if (n <= 0) {
        fprintf(stderr, "Invalid input: n must be greater than 0.\n");
        return;
    }

    // Step 1: Allocate memory for offsets
    long* offsets = calloc(n, sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Error allocating memory for offsets.\n");
        return;
    }
    for (int i = 0; i < n; i++) {
        offsets[i] = 0;
    }

    // Step 2: Allocate memory for keys
    int* keys = calloc(n, sizeof(int));
    if (!keys) {
        fprintf(stderr, "Error allocating memory for keys.\n");
        free(offsets);
        return;
    }
    for (int i = 0; i < n; i++) {
        keys[i] = i;
    }

    // Step 3: Allocate memory for records
