```csharp
using System;
using System.Threading;
using System.Runtime.InteropServices;

public sealed class GraphDataManager : IDisposable
{
    private readonly MemoryPool _memoryPool = new MemoryPool();
    private readonly ConcurrentDictionary<int, (int, long, short, int)> _graphData = new ConcurrentDictionary<int, (int, long, short, int)>();
    private readonly ConcurrentDictionary<int, int> _lastAccessedIndexMap = new ConcurrentDictionary<int, int>();
    private readonly Cache<string, string> _dataCache = new Cache<string, string>(new MemoryPool());
    private readonly RandomValueGenerator _randomValueGenerator = new RandomValueGenerator();

    public void ExpandGraphStructure()
    {
        while (true)
        {
            try
            {
                var keyValue = int.Parse(Console.ReadLine());
                if (_graphData.ContainsKey(keyValue))
                {
                    continue;
                }
                var offset = _memoryPool.Allocate(sizeof(long));
                var value = _randomValueGenerator.NextShort();
                _graphData.TryAdd(keyValue, (keyValue, offset, value, 0));
                _lastAccessedIndexMap.AddOrUpdate(keyValue, keyValue, (k, v) => k);
            }
            catch
            {
                break;
            }
        }
    }

    public void Dispose()
    {
        _memoryPool.Dispose();
    }

    [DllImport("kernel32")]
    private static extern IntPtr GlobalMemoryStatusEx(out int lpBuffer);

    private sealed class MemoryPool : IDisposable
    {
        private const int PoolSize = 1024 * 1024;
        private readonly int[] _poolBuffers = new int[PoolSize];
        private readonly int _currentFreeSpace;

        public MemoryPool()
        {
            var status = 0;
            GlobalMemoryStatusEx(out status);
            _currentFreeSpace = (status >> 16) & 0xFFFF;
        }

        public IntPtr Allocate(int size)
        {
            if (_currentFreeSpace < size)
            {
                throw new OutOfMemoryException();
            }
            var address = GCHandle.Alloc(_poolBuffers, GCHandleType.Pinned).AddrOfPinnedBlock();
            _currentFreeSpace -= size;
            return address;
        }

        public void Dispose()
        {
            GC.SuppressFinalize(this);
        }
    }

    private sealed class ConcurrentDictionary<TKey, TValue>
    {
        private readonly Dictionary<TKey, TValue> _dictionary = new Dictionary<TKey, TValue>();

        public bool TryAdd(TKey key, TValue value)
        {
            lock (_dictionary)
            {
                return _dictionary.Add(key, value);
            }
        }

        public TValue this[TKey key]
        {
            get
            {
                lock (_dictionary)
                {
                    return _dictionary[key];
                }
            }
        }
    }

    private sealed class Cache<TKey, TValue>
    {
        private readonly Dictionary<TKey, TValue> _cache = new Dictionary<TKey, TValue>();
        private readonly MemoryPool _memoryPool;

        public Cache(MemoryPool memoryPool)
        {
            _memoryPool = memoryPool;
        }

        public void Add(TKey key, TValue value)
        {
            lock (_cache)
            {
                _cache.Add(key, value);
            }
        }
    }

    private sealed class RandomValueGenerator
    {
        private readonly Random _random;

        public RandomValueGenerator()
        {
            _random = new Random();
        }

        public short NextShort(int min = 0, int max = 10000)
        {
            return (short)_random.Next(min, max);
        }
    }
}
