#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the custom data structure
typedef struct {
    int *offsets;
    char **metadata;
    pthread_mutex_t lock;
} Dataset;

// Function to initialize and load dataset from disk
Dataset* init_dataset(int size) {
    Dataset* ds = (Dataset*)malloc(sizeof(Dataset));
    ds->offsets = (int*)malloc(size * sizeof(int));
    ds->metadata = (char**)malloc(size * sizeof(char*));
    pthread_mutex_init(&ds->lock, NULL);
    return ds;
}

// Function to insert record into dataset
void insert_record(Dataset* ds, int key, int offset, char* metadata) {
    pthread_mutex_lock(&ds->lock);
    // Handle duplicate key insertion
    for (int i = 0; i < ds->offsets[ds->last_index]; i++) {
        if (key == ds->offsets[i]) {
            ds->offsets[i] = offset;
            strcpy(ds->metadata[i], metadata);
            pthread_mutex_unlock(&ds->lock);
            return;
        }
    }
    // Insert new record
    ds->offsets[ds->last_index] = offset;
    ds->metadata[ds->last_index] = (char*)malloc(strlen(metadata) + 1);
    strcpy(ds->metadata[ds->last_index], metadata);
    pthread_mutex_unlock(&ds->lock);
}

// Function to serialize dataset to disk
void serialize_dataset(Dataset* ds, FILE* file) {
    // Serialize offsets and metadata
    fwrite(&ds->offsets, sizeof(int), ds->last_index + 1, file);
    for (int i = 0; i <= ds->last_index; i++) {
        fwrite(ds->metadata[i], strlen(ds->metadata[i]) + 1, 1, file);
    }
}

// Function to deserialize dataset from disk
Dataset* deserialize_dataset(FILE* file) {
    Dataset* ds = init_dataset(10); // Initialize with a default size
    int size;
    fread(&size, sizeof(int), 1, file);
    for (int i = 0; i <= size; i++) {
        char *metadata = (char*)malloc(1024);
        fread(metadata, strlen(metadata) + 1, 1, file);
        // Update last_index and metadata
        ds->last_index = i;
        ds->metadata[i] = metadata;
    }
    return ds;
}

// Function to find the largest integer along with its associated metadata
int largest_integer(Dataset* ds) {
    int max_key = 0;
    for (int i = 0; i <= ds->last_index; i++) {
        if (ds->offsets[i] > max_key) {
            max_key = ds->offsets[i];
        }
    }
    return max_key;
}

// Function to print the largest integer along with its associated metadata
void print_largest_integer(Dataset* ds) {
    int max_key = largest_integer(ds);
    for (int i = 0; i <= ds->last_index; i++) {
        if (ds->offsets[i] == max_key) {
            printf("Key: %d, Offset: %d, Metadata: %s\n", i, ds->offsets[i], ds->metadata[i]);
        }
    }
}

// Main function to demonstrate usage
int main() {
    Dataset* ds = init_dataset(10);
    // Example record insertion
    insert_record(ds, 5, 100, "Record metadata");
    insert_record(ds, 3, 200, "Another record metadata");
    // Example serialization and deserialization
    FILE* file = fopen("dataset.dat", "wb");
    serialize_dataset(ds, file);
    fclose(file);
    ds = deserialize_dataset(fopen("dataset.dat", "rb"));
    print_largest_integer(ds);
    return 0;
}

