// Function to optimize data processing pipeline
void* optimizeDataProcessingPipeline(void* ptr) {
    // Allocate memory for arrays and initialize variables
    transaction** transactions = (transaction**)malloc(sizeof(transaction*) * 1000000);
    double* amounts = (double*)malloc(sizeof(double) * 1000000);
    uint64_t* ids = (uint64_t*)malloc(sizeof(uint64_t) * 1000000);
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    // Initialize secondary structure to track last accessed timestamp
    long long* last_accessed_timestamps = (long long*)calloc(1000000, sizeof(long long));

    // Process transactions from standard input
    transaction current_transaction;
    while (fscanf(stdin, "%d %lf %lld", &current_transaction.key, &current_transaction.amount, &current_transaction.timestamp) == 3) {
        pthread_mutex_lock(&mutex);
        int index = current_transaction.key % 1000000; // Simple modulo-based indexing for now
        transaction* new_transaction = (transaction*)malloc(sizeof(transaction));
        *new_transaction = current_transaction;
        transactions[index] = new_transaction;

        // Update last accessed timestamp
        last_accessed_timestamps[index] = current_transaction.timestamp;

        pthread_mutex_unlock(&mutex);
    }

    // Free allocated memory
    for (int i = 0; i < 1000000; i++) {
        if (transactions[i]) {
            free(transactions[i]);
        }
    }
    free(transactions);

    // Serialize transactions to a file
    FILE* file = fopen("output.txt", "wb");
    fwrite(transactions, sizeof(transaction), 1000000, file);
    fclose(file);

    return NULL;
}

int main() {
    pthread_t thread;
    pthread_create(&thread, NULL, optimizeDataProcessingPipeline, NULL);
    pthread_join(thread, NULL);
