record* expandGraphStructure(int* keys, int* offsets) {
    // Initialize arrays and records
    int numRecords = 10000; // Maximum capacity
    int* keyArray = (int*)malloc(numRecords * sizeof(int));
    long* offsetArray = (long*)malloc(numRecords * sizeof(long));
    record* records = (record*)malloc(numRecords * sizeof(record));

    // Initialize tracking structure for last accessed index of each key
    int* keyTrack = (int*)calloc(numRecords, sizeof(int));
    for (int i = 0; i < numRecords; i++) {
        keyTrack[i] = -1;
    }

    // Read integers from standard input and store in array
    int i = 0;
    while (scanf("%d", &keys[i]) == 1) {
        i++;
    }
    keys = realloc(keys, (i + 1) * sizeof(int));
    keys[i] = -1; // Sentinel value

    i = 0;
    while (scanf("%ld", &offsets[i]) == 1) {
        i++;
    }
    offsets = realloc(offsets, (i + 1) * sizeof(long));
    offsets[i] = -1; // Sentinel value

    // Initialize records with random values
    for (int j = 0; j < numRecords; j++) {
        records[j].key = keys[j % i];
        records[j].offset = offsets[j % i];
        records[j].value = rand() % 100;
    }

    return records;
}

