    record* records;
    int numRecords;

    FILE* file = fopen(filename, "rb");
    fread(&numRecords, sizeof(int), 1, file);
    records = (record*)malloc(numRecords * sizeof(record));
    fread(records, sizeof(record), numRecords, file);
    fclose(file);

    return records;
}

// Set the value of each record's int field to a random value within a given range
void setRecordValues(record* records, int min, int max) {
    for (int i = 0; i < numRecords; i++) {
        records[i].value = rand() % (max - min + 1) + min;
    }
}

