    unsigned long **keys = (unsigned long **)malloc((int *) sizeof(unsigned long *));
    time_t **timestamps = (time_t **)malloc((int *)sizeof(time_t *));

    // Initialize array of records
    record **records = (record **)malloc((int *)sizeof(record *));

    int i;
    for (i = 0; i < *num_records; i++) {
        record *r = (record *)malloc(sizeof(record));
        r->key = (unsigned long)rand();
        r->timestamp = time(NULL);
        r->value = (double)rand() / RAND_MAX;

        // Add the record to the end of the array
        if (*num_records == 0) {
            *records = &r;
        } else {
            for (int j = *num_records - 1; j > 0; j--) {
                records[j] = records[j-1];
            }
            records[0] = r;
        }

        // Resize the arrays if needed
        if (*num_records >= *max_records) {
            *max_records *= 2;
            keys = (unsigned long **)realloc(keys, (int *) sizeof(unsigned long *));
            timestamps = (time_t **)realloc(timestamps, (int *)sizeof(time_t *));
            records = (record **)realloc(records, (int *)sizeof(record *));
        }

        (*num_records)++;
    }

    return records;
}
