    float latency;
} network_t;

void manageNetworkConfig(network_t **networks, int **lastAccessedIndex, size_t ***charInterfaceNames) {
    // Initialize the arrays
    size_t capacity = 5000;
    networks[0] = (network_t *)malloc(capacity * sizeof(network_t));
    lastAccessedIndex[0] = (int *)malloc(capacity * sizeof(int));
    char **interfaceNames = (char **)malloc(capacity * sizeof(char *));

    int numConfigurations = 0;
    for (int i = 0; i < capacity; i++) {
        networks[i]->id = -1;
        networks[i]->interfaceName = NULL;
        interfaceNames[i] = NULL;
    }

    while (1) {
        // Read a new configuration from standard input
        network_t newConfig;
        printf("Enter id, interface name, port, bandwidth, and latency: ");
        scanf("%d %s %hd %lf %f", &newConfig.id, newConfig.interfaceName, &newConfig.port, &newConfig.bandwidth, &newConfig.latency);

        // Check for duplicate id or interface name
        int found = 0;
        for (int i = 0; i < numConfigurations; i++) {
            if (newConfig.id == networks[i]->id || strcmp(newConfig.interfaceName, networks[i]->interfaceName) == 0) {
                found = 1;
                break;
            }
        }

        // Handle new configuration
        if (!found) {
            networks[numConfigurations] = &newConfig;
            lastAccessedIndex[numConfigurations] = numConfigurations;
            interfaceNames[numConfigurations] = strdup(newConfig.interfaceName);
            numConfigurations++;

            // Resize the arrays as needed
            if (numConfigurations >= capacity) {
                size_t newCapacity = capacity * 2;
                networks = realloc(networks, newCapacity * sizeof(network_t *));
                lastAccessedIndex = realloc(lastAccessedIndex, newCapacity * sizeof(int *));
                interfaceNames = realloc(interfaceNames, newCapacity * sizeof(char *));
                capacity = newCapacity;
            }
        } else {
            printf("Duplicate id or interface name. Please try again.\n");
        }
    }
}

void serializeNetworkConfig(network_t **networks) {
    FILE *file = fopen("configurations.txt", "wb");
    if (file != NULL) {
        for (int i = 0; i < numConfigurations; i++) {
            fwrite(&networks[i]->id, sizeof(int), 1, file);
            fwrite(networks[i]->interfaceName, strlen(networks[i]->interfaceName) + 1, 1, file);
            fwrite(&networks[i]->port, sizeof(short), 1, file);
            fwrite(&networks[i]->bandwidth, sizeof(double), 1, file);
            fwrite(&networks[i]->latency, sizeof(float), 1, file);
        }
        fclose(file);
    } else {
        printf("Error writing to file.\n");
    }
}

void deserializeNetworkConfig(network_t **networks) {
    FILE *file = fopen("configurations.txt", "rb");
    if (file != NULL) {
        fseek(file, 0, SEEK_END);
        size_t fileSize = ftell(file);
        rewind(file);

        for (int i = 0; i < numConfigurations; i++) {
            fread(&networks[i]->id, sizeof(int), 1, file);
            networks[i]->interfaceName = malloc(strlen(networks[i]->interfaceName) + 2);
            fread(networks[i]->interfaceName, strlen(networks[i]->interfaceName) + 1, 1, file);
            fread(&networks[i]->port, sizeof(short), 1, file);
            fread(&networks[i]->bandwidth, sizeof(double), 1, file);
