typedef enum {
    SUCCESS,
    FAILURE,
} Status;

typedef struct {
    double value;
    int timestamp;
    Status status;
} Metric;

void metricsManager() {
    // Initialize the metric array
    Metric* metrics = NULL;
    int numMetrics = 0;
    int capacity = 10; // Initial capacity

    // Function to dynamically resize the array
    void resizeArray(int newSize) {
        Metric* newMetrics = (Metric*) realloc(metrics, sizeof(Metric) * newSize);
        if (newMetrics == NULL) {
            printf("Memory allocation failed.\n");
            exit(1);
        }
        metrics = newMetrics;
        capacity = newSize;
    }

    // Function to add a new metric
    int addMetric(double value, int timestamp, Status status) {
        if (numMetrics >= capacity) {
            resizeArray(capacity * 2); // Double the capacity when full
        }
        metrics[numMetrics].value = value;
        metrics[numMetrics].timestamp = timestamp;
        metrics[numMetrics].status = status;
        return numMetrics++;
    }

    // Function to print all metrics with a specific status
    void printMetricsByStatus(Status status) {
        for (int i = 0; i < numMetrics; i++) {
            if (metrics[i].status == status) {
                printf("Metric %d: value=%f, timestamp=%d, status=%s\n", i, metrics[i].value, metrics[i].timestamp, ((status == SUCCESS) ? "SUCCESS" : "FAILURE"));
            }
        }
    }

    // Function to calculate the average metric value
    double getAverageValue() {
        double sum = 0;
        for (int i = 0; i < numMetrics; i++) {
            sum += metrics[i].value;
        }
        return sum / numMetrics;
    }

    int main() {
        // Example usage:
        addMetric(10.5, 1643723400, SUCCESS);
        addMetric(20.8, 1643723410, FAILURE);
        addMetric(30.1, 1643723420, SUCCESS);

        printMetricsByStatus(SUCCESS);

        printf("Average value: %f\n", getAverageValue());

        return 0;
    }
