typedef struct {
    void** blocks;
    int capacity, used;
} MemoryPool;

// Initialize the memory pool
void initMemoryPool(MemoryPool* pool, int capacity) {
    pool->blocks = (void**)malloc(capacity * sizeof(void*));
    pool->capacity = capacity;
    pool->used = 0;
}

// Reclaim a block in the memory pool
void reclaimBlock(MemoryPool* pool, void* block) {
    pool->blocks[pool->used++] = block;
}

// Initialize the key index structure
KeyIndex initKeyIndex(int size) {
    KeyIndex ki = {malloc(size * sizeof(int)), size};
    return ki;
}

// Insert a record into the queue
void enqueue(Queue* queue, Record record) {
    pthread_mutex_lock(&queue->lock);
    if (queue->rear >= queue->capacity) {
        // Resize the array when full
        queue->records = realloc(queue->records, queue->capacity * 2 * sizeof(Record));
        queue->capacity *= 2;
    }
    queue->records[queue->rear++] = record;
    pthread_mutex_unlock(&queue->lock);
}

// Remove a record from the queue
void dequeue(Queue* queue) {
    pthread_mutex_lock(&queue->lock);
    if (queue->front == queue->rear) {
        // Empty queue, nothing to remove
        pthread_mutex_unlock(&queue->lock);
        return;
    }
    Record removed = queue->records[queue->front++];
    free(queue->records[--queue->rear]);
    pthread_mutex_unlock(&queue->lock);
}

// Serialize the records into a file
void serializeRecords(Queue* queue, FILE* file) {
    fwrite(&queue->capacity, sizeof(int), 1, file);
    for (int i = 0; i < queue->rear; i++) {
        Record record = queue->records[i];
        fwrite(&record.offset, sizeof(long), 1, file);
        fwrite(&record.key, sizeof(int), 1, file);
    }
}

// Deserialize the records from a file
Queue deserializeRecords(FILE* file) {
    Queue queue = {malloc(10 * sizeof(Record)), 10, 0, 0};
    int capacity;
    fread(&capacity, sizeof(int), 1, file);
    for (int i = 0; i < capacity; i++) {
        Record record;
        fread(&record.offset, sizeof(long), 1, file);
        fread(&record.key, sizeof(int), 1, file);
        enqueue(&queue, record);
    }
    return queue;
}

