    int len = 0, capacity = 10; 
    imageInfo** images = (imageInfo**)malloc(capacity * sizeof(imageInfo*));

    // Function to add a new image metadata entry
    void addImage(char* filename, size_t file_size) {
        imageInfo* img = (imageInfo*)malloc(sizeof(imageInfo));
        img->filename = filename;
        img->file_size = file_size;
        gettimeofday(&img->last_access_time, NULL);

        // Check for uniqueness of filenames and last_access_time values
        int unique = 1;
        for(int i = 0; i < len; i++) {
            if(strcmp(img->filename, images[i]->filename) == 0 || 
               (img->last_access_time.tv_sec == images[i]->last_access_time.tv_sec &&
                img->last_access_time.tv_usec == images[i]->last_access_time.tv_usec)) {
                unique = 0;
                break;
            }
        }

        if(unique) {
            images[len++] = img;
            // Check for array resizing
            if(len >= capacity) {
                capacity *= 2;
                imageInfo** new_images = (imageInfo**)realloc(images, capacity * sizeof(imageInfo*));
                images = new_images;
            }
        } else {
            free(img);
        }
    }

    return images;
}
