#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define structure for a product order
typedef struct {
    int orderId;
    char customerName[256];
    time_t purchaseDate;
    double totalAmount;
} Order;

// Define structure to hold the dynamic collection of orders
typedef struct {
    Order* orders;
    int capacity;
    int size;
} OrderCollection;

// Function to initialize an empty order collection with a specified initial capacity
OrderCollection* initOrderCollection(int capacity) {
    OrderCollection* collection = (OrderCollection*)malloc(sizeof(OrderCollection));
    collection->orders = (Order*)malloc(capacity * sizeof(Order));
    collection->capacity = capacity;
    collection->size = 0;
    return collection;
}

// Function to insert a new order into the collection
void insertOrder(OrderCollection* collection, Order* order) {
    if(collection->size == collection->capacity) {
        // Resize the collection when full
        int newSize = collection->capacity * 2;
        Order* newOrders = (Order*)malloc(newSize * sizeof(Order));
        memcpy(newOrders, collection->orders, collection->capacity * sizeof(Order));
        free(collection->orders);
        collection->orders = newOrders;
        collection->capacity = newSize;
    }
    // Copy the order into the first available slot
    int index = 0;
    while(index < collection->size) {
        if(strcmp(collection->orders[index].customerName, order->customerName) > 0) {
            break; // Found a gap to insert the new order
        }
        index++;
    }
    for(int i = collection->size; i > index; i--) {
        memcpy(&collection->orders[i], &collection->orders[i-1], sizeof(Order));
    }
    memcpy(&collection->orders[index], order, sizeof(Order));
    collection->size++;
}

// Function to remove an order from the collection by its ID
void removeOrder(OrderCollection* collection, int orderId) {
    for(int i = 0; i < collection->size; i++) {
        if(collection->orders[i].orderId == orderId) {
            // Move all orders after the removed one down one slot
            for(int j = i+1; j < collection->size; j++) {
                memcpy(&collection->orders[i], &collection->orders[j], sizeof(Order));
            }
            collection->size--;
            return;
        }
    }
}

// Function to retrieve an order by its ID
Order* getOrder(OrderCollection* collection, int orderId) {
    for(int i = 0; i < collection->size; i++) {
        if(collection->orders[i].orderId == orderId) {
            return &collection->orders[i];
        }
    }
    return NULL;
}

// Function to serialize the order collection to disk
void serializeOrderCollection(OrderCollection* collection, char* filename) {
    FILE* file = fopen(filename, "wb");
    for(int i = 0; i < collection->size; i++) {
        fwrite(&collection->orders[i], sizeof(Order), 1, file);
    }
    fclose(file);
}

// Function to deserialize the order collection from disk
OrderCollection* deserializeOrderCollection(char* filename) {
    OrderCollection* collection = initOrderCollection(16); // Start with a small capacity
    FILE* file = fopen(filename, "rb");
    for(int i = 0; i < collection->capacity; i++) {
        fread(&collection->orders[i], sizeof(Order), 1, file);
    }
    fclose(file);
    return collection;
}

int main() {
    // Initialize an empty order collection
    OrderCollection* collection = initOrderCollection(16);

    // Insert sample orders
    srand(time(NULL));
    for(int i = 0; i < 1000; i++) {
        Order order;
        order.orderId = rand() % 1000000 + 1;
        strcpy(order.customerName, "Customer ");
        order.purchaseDate = time(NULL);
        order.totalAmount = (double)rand() / RAND_MAX * 100.00;
        insertOrder(collection, &order);
    }

    // Remove an order
    removeOrder(collection, 500000);

    // Retrieve and print an order
    Order* order = getOrder(collection, 750000);
    printf("OrderId: %d, CustomerName: %s, PurchaseDate: %ld, TotalAmount: %.2f\n", 
           order->orderId, order->customerName, order->purchaseDate, order->totalAmount);

    // Serialize the collection to disk
    serializeOrderCollection(collection, "orders.dat");

    // Deserialize and print the collection from disk
    OrderCollection* deserializedCollection = deserializeOrderCollection("orders.dat");
    for(int i = 0; i < deserializedCollection->size; i++) {
        printf("OrderId: %d, CustomerName: %s, PurchaseDate: %ld, TotalAmount: %.2f\n", 
               deserializedCollection->orders[i].orderId, deserializedCollection->orders[i].customerName, 
               deserializedCollection->orders[i].purchaseDate, deserializedCollection->orders[i].totalAmount);
