DynamicMemoryStruct* createDynamicMemory(int num_records, int key_range) {
    DynamicMemoryStruct* mem = (DynamicMemoryStruct*)malloc(sizeof(DynamicMemoryStruct));

    mem->data = (long*)calloc(num_records, sizeof(long));
    mem->keys = (int*)calloc(key_range + 1, sizeof(int));

    for (int i = 0; i <= key_range; i++) {
        mem->last_accessed[i] = -1;
    }

