}

void freeDynamicMemory(DynamicMemoryStruct* mem) {
    if (mem) {
        free(mem->data);
        free(mem->keys);
        free(mem);
    }
}

int serializeDynamicMemory(const DynamicMemoryStruct* mem, FILE* file) {
    fwrite(&num_records, sizeof(int), 1, file);
    fwrite(&key_range, sizeof(int), 1, file);

    for (int i = 0; i < num_records; i++) {
        fwrite(&mem->data[i], sizeof(long), 1, file);
    }

    for (int i = 0; i <= key_range; i++) {
        fwrite(&mem->keys[i], sizeof(int), 1, file);
    }

    return 0;
}

DynamicMemoryStruct* deserializeDynamicMemory(FILE* file) {
    DynamicMemoryStruct* mem = createDynamicMemory(0, 0);

    int num_records, key_range;

    fread(&num_records, sizeof(int), 1, file);
    fread(&key_range, sizeof(int), 1, file);

    mem->data = (long*)realloc(mem->data, num_records * sizeof(long));
    mem->keys = (int*)realloc(mem->keys, (key_range + 1) * sizeof(int));

    for (int i = 0; i < num_records; i++) {
        fread(&mem->data[i], sizeof(long), 1, file);
    }

    for (int i = 0; i <= key_range; i++) {
        fread(&mem->keys[i], sizeof(int), 1, file);
