#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>

// Define a structure to represent a user profile
typedef struct {
    char username[64];
    int age;
    char email[128];
    struct {
        int key;
        long offset;
    } record[];
} UserProfile;

// Define the library's data structure for managing user profiles
typedef struct {
    UserProfile *profiles; // Array of user profiles
    pthread_mutex_t lock; // Mutex for concurrent access
    size_t capacity; // Maximum number of profiles
    size_t size; // Current number of profiles
} UserProfiles;

// Function to initialize the library's data structure
UserProfiles* user_profiles_init(size_t capacity) {
    UserProfiles *profiles = (UserProfiles*)malloc(sizeof(UserProfiles));
    profiles->profiles = (UserProfile*)calloc(capacity, sizeof(UserProfile));
    profiles->capacity = capacity;
    profiles->size = 0;
    pthread_mutex_init(&profiles->lock, NULL);
    return profiles;
}

// Function to add a new user profile
int user_profiles_add(UserProfiles *profiles, const char *username, int age, const char *email) {
    // Check if the library is full before adding a new profile
    if (profiles->size >= profiles->capacity) return -1;

    // Create a new user profile and add it to the array
    UserProfile *profile = &profiles->profiles[profiles->size++];
    strcpy(profile->username, username);
    profile->age = age;
    strcpy(profile->email, email);

    return 0;
}

// Function to remove a user profile
int user_profiles_remove(UserProfiles *profiles, const char *username) {
    // Find the index of the profile to be removed
    size_t i;
    for (i = 0; i < profiles->size; ++i) {
        if (!strcmp(profiles->profiles[i].username, username)) break;
    }
    if (i >= profiles->size) return -1;

    // Shift all subsequent profiles up by one position
    memmove(&profiles->profiles[i], &profiles->profiles[i+1], sizeof(UserProfile) * (profiles->size - i));

    // Decrement the size of the library
    --profiles->size;

    return 0;
}

// Function to print all user profiles
void user_profiles_print(const UserProfiles *profiles) {
    size_t i;
    for (i = 0; i < profiles->size; ++i) {
        printf("Username: %s, Age: %d, Email: %s\n", profiles->profiles[i].username, profiles->profiles[i].age, profiles->profiles[i].email);
    }
}

// Define a function to serialize the user profiles to a file
void user_profiles_serialize(const UserProfiles *profiles, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    // Write the size of the library and each profile
    fwrite(&profiles->size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < profiles->size; ++i) {
        UserProfile *profile = &profiles->profiles[i];
        fwrite(profile->username, sizeof(char), strlen(profile->username)+1, file);
        fwrite(&profile->age, sizeof(int), 1, file);
        fwrite(profile->email, sizeof(char), strlen(profile->email)+1, file);
    }

    fclose(file);
}

// Define a function to deserialize the user profiles from a file
UserProfiles* user_profiles_deserialize(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return NULL;

    // Read the size of the library and each profile
    UserProfiles *profiles = (UserProfiles*)malloc(sizeof(UserProfiles));
    fread(&profiles->size, sizeof(size_t), 1, file);
    profiles->profiles = (UserProfile*)calloc(profiles->size, sizeof(UserProfile));
    for (size_t i = 0; i < profiles->size; ++i) {
        UserProfile *profile = &profiles->profiles[i];
        fread(profile->username, sizeof(char), strlen(profile->username)+1, file);
        fread(&profile->age, sizeof(int), 1, file);
        fread(profile->email, sizeof(char), strlen(profile->email)+1, file);
    }

    fclose(file);

    return profiles;
}

// Define the main function
int main() {
    UserProfiles *profiles = user_profiles_init(1000); // Initialize the library with a capacity of 1000

    // Add some user profiles
    user_profiles_add(profiles, "John", 30, "john@example.com");
    user_profiles_add(profiles, "Jane", 25, "jane@example.com");

    // Serialize the user profiles to a file
    user_profiles_serialize(profiles, "user_profiles.bin");

    // Deserialize the user profiles from the file
    UserProfiles *deserialized_profiles = user_profiles_deserialize("user_profiles.bin");
    user_profiles_print(deserialized_profiles);

    return 0;
}

