typedef enum {
    OK,
    WARNING,
    ERROR
} status_t;

typedef struct {
    double value;
    int timestamp;
    status_t status;
} metric_t;

void processAndManageMetrics() {
    FILE *fp = fopen("graph_params.txt", "r");
    if (fp == NULL) {
        printf("Failed to open file.\n");
        return;
    }

    // Read initial graph parameters
    int num_metrics, start_timestamp, end_timestamp;
    fscanf(fp, "%d %d %d\n", &num_metrics, &start_timestamp, &end_timestamp);
    fclose(fp);

    metric_t *metrics = NULL;
    int *timestamps = NULL;
    double *values = NULL;
    int last_timestamp_index[1024] = {0};
    int last_timestamp = -1;

    for (int i = 0; i < num_metrics; i++) {
        if ((metrics = realloc(metrics, (i + 1) * sizeof(metric_t))) == NULL) {
            printf("Memory allocation failed.\n");
            return;
        }

        if ((timestamps = realloc(timestamps, (i + 1) * sizeof(int))) == NULL) {
            printf("Memory allocation failed.\n");
            free(metrics);
            return;
        }

        if ((values = realloc(values, (i + 1) * sizeof(double))) == NULL) {
            printf("Memory allocation failed.\n");
            free(metrics);
            free(timestamps);
            return;
        }

        int timestamp;
        double value;
        status_t status;
        // Read new metric from standard input
        fscanf(stdin, "%d %lf %d\n", &timestamp, &value, &status);

        if (timestamp > last_timestamp) {
            last_timestamp = timestamp;
        } else {
            for (int j = 0; j < i; j++) {
                if (timestamps[j] == timestamp) {
                    printf("Timestamp conflict detected.\n");
                    return;
                }
            }
        }

        metrics[i].value = value;
        metrics[i].timestamp = timestamp;
        metrics[i].status = status;

        timestamps[i] = timestamp;
        values[i] = value;
    }

    // Serialize the data structure to a file
    FILE *fp2 = fopen("metrics.txt", "w");
    if (fp2 == NULL) {
        printf("Failed to open file.\n");
        return;
    }

    for (int i = 0; i < num_metrics; i++) {
        fprintf(fp2, "%d %lf %d\n", metrics[i].timestamp, metrics[i].value, metrics[i].status);
    }
    fclose(fp2);

    // Filter and print metrics with a status of "ERROR"
    for (int i = 0; i < num_metrics; i++) {
        if (metrics[i].status == ERROR) {
            printf("Metric %d: Value %.2f, Timestamp %d, Status ERROR\n", i + 1, values[i], timestamps[i]);
        }
    }

    // Calculate the average metric value
    double total = 0.0;
    for (int i = 0; i < num_metrics; i++) {
        total += values[i];
    }
    printf("Average metric value: %.2f\n", total / num_metrics);
}

