```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>

typedef struct {
    char* name;
    int priority;
    double estimated_loading_time;
    struct webpage** sub_pages;
} webpage;

// Initialize the webpage hierarchy with predefined pages and their details.
void init_webpage_hierarchy(webpage** main_pages, int num_main_pages) {
    // Create a list of 5 levels of nested sub-pages per page
    for (int i = 0; i < num_main_pages; i++) {
        (*main_pages)[i].name = malloc(strlen("Page ") + 10);
        sprintf((*main_pages)[i].name, "Page %d", i+1);
        (*main_pages)[i].priority = rand() % 100;
        (*main_pages)[i].estimated_loading_time = (double)rand() / RAND_MAX;

        // Allocate memory for the sub-pages
        int num_sub_pages = 1 << (5 - i); // 2^(5-i)
        (*main_pages)[i].sub_pages = malloc(sizeof(struct webpage*) * num_sub_pages);

        // Initialize sub-pages recursively
        for (int j = 0; j < num_sub_pages; j++) {
            (*main_pages)[i].sub_pages[j] = malloc(sizeof(struct webpage));
            (*main_pages)[i].sub_pages[j]->name = malloc(strlen("Sub-page ") + 10);
            sprintf((*main_pages)[i].sub_pages[j]->name, "Sub-page %d", i+1);
            (*main_pages)[i].sub_pages[j]->priority = rand() % 100;
            (*main_pages)[i].sub_pages[j]->estimated_loading_time = (double)rand() / RAND_MAX;
        }
    }
}

// Traverse the webpage hierarchy and print page details.
void traverse_webpage_hierarchy(webpage* main_pages, int num_main_pages) {
    for (int i = 0; i < num_main_pages; i++) {
        printf("Page %s:\n", main_pages[i].name);
        printf("Priority: %d\n", main_pages[i].priority);
        printf("Estimated loading time: %.2f seconds\n", main_pages[i].estimated_loading_time);

        if (main_pages[i].sub_pages) {
            for (int j = 0; j < sizeof(main_pages[i].sub_pages) / sizeof(main_pages[i].sub_pages[0]); j++) {
                printf("Sub-page %s:\n", main_pages[i].sub_pages[j]->name);
                printf("Priority: %d\n", main_pages[i].sub_pages[j]->priority);
                printf("Estimated loading time: %.2f seconds\n", main_pages[i].sub_pages[j]->estimated_loading_time);
            }
        }

        printf("\n");
    }
}

// Free dynamically allocated memory for the webpage hierarchy.
void free_webpage_hierarchy(webpage** main_pages, int num_main_pages) {
    for (int i = 0; i < num_main_pages; i++) {
        if (main_pages[i].sub_pages) {
            for (int j = 0; j < sizeof(main_pages[i].sub_pages) / sizeof(main_pages[i].sub_pages[0]); j++) {
                free(main_pages[i].sub_pages[j]->name);
                free(main_pages[i].sub_pages[j]);
            }
            free(main_pages[i].sub_pages);
        }

        free(main_pages[i]->name);

        // Reset main page structure
        main_pages[i] = NULL;
    }
}

