#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <uuid/uuid.h>
#include <pthread.h>

// Define a structure to represent cache entries
typedef struct {
    uuid_t id;
    char filename[256];
    time_t lastModified;
    int size;
    char contentType[32];
    int64_t sourceServerId;
} CacheEntry;

// Define a structure to manage the in-memory cache
typedef struct {
    int capacity;
    int hitCount;
    int missCount;
    int evictionCount;
    pthread_mutex_t lock;
    CacheEntry** entries;
} CacheManager;

// Initialize the cache manager with a specified capacity and locking mechanism
CacheManager* initCache(int capacity) {
    CacheManager* cm = (CacheManager*)malloc(sizeof(CacheManager));
    cm->capacity = capacity;
    cm->hitCount = 0;
    cm->missCount = 0;
    cm->evictionCount = 0;
    pthread_mutex_init(&cm->lock, NULL);
    cm->entries = (CacheEntry**)malloc((capacity+1)*sizeof(CacheEntry*));
    return cm;
}

// Insert a new cache entry with the provided metadata and TTL
void insertEntry(CacheManager* cm, uuid_t id, const char* filename, time_t lastModified, int size, const char* contentType, int64_t sourceServerId) {
    pthread_mutex_lock(&cm->lock);

    // Check if the cache is full
    if (cm->hitCount + 1 > cm->capacity) {
        // Evict the least recently used entry based on TTL or size
        int oldestEntry = -1;
        time_t oldestTimestamp = 0;
        for (int i = 0; i < cm->capacity; i++) {
            if ((oldestEntry == -1 || cm->entries[i]->lastModified < oldestTimestamp) && 
                (cm->entries[i]->size <= size || lastModified <= cm->entries[oldestEntry]->lastModified)) {
                oldestEntry = i;
                oldestTimestamp = cm->entries[i]->lastModified;
            }
        }

        // Evict the selected entry
        if (oldestEntry != -1) {
            free(cm->entries[oldestEntry]);
            for (int i = oldestEntry; i < cm->capacity - 1; i++) {
                cm->entries[i] = cm->entries[i+1];
            }
            cm->entries[--cm->capacity] = NULL;
            cm->evictionCount++;
        }
    }

    // Insert the new entry
    CacheEntry* newEntry = (CacheEntry*)malloc(sizeof(CacheEntry));
    newEntry->id = id;
    strcpy(newEntry->filename, filename);
    newEntry->lastModified = lastModified;
    newEntry->size = size;
    strcpy(newEntry->contentType, contentType);
    newEntry->sourceServerId = sourceServerId;
    cm->entries[cm->hitCount] = newEntry;
    cm->hitCount++;

    pthread_mutex_unlock(&cm->lock);
}

// Retrieve a cache entry by its unique UUID
CacheEntry* getEntry(CacheManager* cm, uuid_t id) {
    CacheEntry** entries = NULL;
    int size = 0;

    // Find the requested entry in the cache
    for (int i = 0; i < cm->hitCount; i++) {
        if (cm->entries[i]->id == id) {
            // Lock the entire cache while accessing this entry
            pthread_mutex_lock(&cm->lock);

            // Move the entry to the front of the array for O(1) lookup
            CacheEntry* temp = cm->entries[0];
            for (int j = 1; j <= i; j++) {
                cm->entries[j-1] = cm->entries[j];
            }
            cm->entries[i] = NULL;

            // Update the cache statistics
            cm->hitCount--;
            size = i + 1;
            break;
        }
    }

    // If not found, return a new entry with an error indicator set to true
    if (!size) {
        CacheEntry* newEntry = (CacheEntry*)malloc(sizeof(CacheEntry));
        newEntry->id = id;
        strcpy(newEntry->filename, "NOT_FOUND");
        newEntry->lastModified = time(NULL);
        newEntry->size = -1;
        strcpy(newEntry->contentType, "application/octet-stream");
        newEntry->sourceServerId = 0;
        return newEntry;
    }

    // Lock the entire cache while accessing this entry
    pthread_mutex_unlock(&cm->lock);

    // Return the requested entry
    CacheEntry* entry = (CacheEntry*)malloc(sizeof(CacheEntry));
    memcpy(entry, cm->entries[0], sizeof(CacheEntry));
    free(cm->entries[0]);
    return entry;
}

// Serialize the cache to disk for persistence
void serializeCache(CacheManager* cm) {
    // Open a file for writing
    FILE* file = fopen("cache.ser", "wb");

    // Write the serialized cache entries
    fwrite(&cm->hitCount, sizeof(int), 1, file);
    fwrite(&cm->missCount, sizeof(int), 1, file);
    fwrite(&cm->evictionCount, sizeof(int), 1, file);
    for (int i = 0; i < cm->capacity; i++) {
        if (cm->entries[i]) {
            fwrite(&cm->entries[i]->id, sizeof(uuid_t), 1, file);
            fwrite(cm->entries[i]->filename, strlen(cm->entries[i]->filename)+1, 1, file);
            fwrite(&cm->entries[i]->lastModified, sizeof(time_t), 1, file);
            fwrite(&cm->entries[i]->size, sizeof(int), 1, file);
            fwrite(cm->entries[i]->contentType, strlen(cm->entries[i]->contentType)+1, 1, file);
            fwrite(&cm->entries[i]->sourceServerId, sizeof(int64_t), 1, file);
        }
    }

    // Close the file
    fclose(file);
}

// Deserialize the cache from disk for persistence
void deserializeCache(CacheManager* cm) {
    // Open a file for reading
    FILE* file = fopen("cache.ser", "rb");

    // Read the serialized cache entries
    fread(&cm->hitCount, sizeof(int), 1, file);
    fread(&cm->missCount, sizeof(int), 1, file);
    fread(&cm->evictionCount, sizeof(int), 1, file);
    for (int i = 0; i < cm->capacity; i++) {
        if (i < cm->hitCount) {
            uuid_t id;
            char filename[256];
            time_t lastModified;
            int size;
            char contentType[32];
            int64_t sourceServerId;

            // Read the entry metadata
            fread(&id, sizeof(uuid_t), 1, file);
            fread(filename, strlen(""), 1, file);
            fread(&lastModified, sizeof(time_t), 1, file);
            fread(&size, sizeof(int), 1, file);
            fread(contentType, strlen(""), 1, file);
            fread(&sourceServerId, sizeof(int64_t), 1, file);

            // Update the cache with the deserialized entry
            CacheEntry* newEntry = (CacheEntry*)malloc(sizeof(CacheEntry));
            memcpy(newEntry->id, &id, sizeof(uuid_t));
            strcpy(newEntry->filename, filename);
            newEntry->lastModified = lastModified;
            newEntry->size = size;
            strcpy(newEntry->contentType, contentType);
            newEntry->sourceServerId = sourceServerId;
            cm->entries[i] = newEntry;
        }
    }

    // Close the file
    fclose(file);
}

