// Define the metric structure
typedef struct {
    double value;
    int timestamp;
    enum { OK, WARNING, ERROR } status;
} Metric;

// Function to manage metrics system
void manageMetricsSystem(int maxMetrics) {
    // Initialize arrays for timestamps and values
    int* timestamps = (int*)malloc(sizeof(int) * maxMetrics);
    double* values = (double*)malloc(sizeof(double) * maxMetrics);

    // Initialize array of metric structures
    Metric* metrics = (Metric*)malloc(sizeof(Metric) * maxMetrics);

    // Initialize last accessed index for each timestamp
    int* lastAccessedTimestamps = (int*)malloc(sizeof(int) * 1000000);
    memset(lastAccessedTimestamps, -1, sizeof(int) * 1000000);

    // Read values and timestamps from standard input
    int i = 0;
    while (i < maxMetrics && scanf("%lf %d", &values[i], &timestamps[i]) == 2) {
        metrics[i].value = values[i];
        metrics[i].timestamp = timestamps[i];
        memset(&metrics[i].status, 0, sizeof(metrics[i].status));
        i++;
    }

    // Resize arrays and metrics if necessary
    while (i < maxMetrics && scanf("%lf %d", &values[i], &timestamps[i]) == 2) {
        for (int j = 0; j < i; j++) {
            if (lastAccessedTimestamps[timestamps[j]] != -1) {
                // Update last accessed index
                lastAccessedTimestamps[timestamps[j]] = i;
            }
        }
        metrics[i].value = values[i];
        metrics[i].timestamp = timestamps[i];
        memset(&metrics[i].status, 0, sizeof(metrics[i].status));
        i++;
    }

    // Fetch initial graph parameters from data source
    int numMetricsToFetch = (int)fmod(i, maxMetrics);
    double minValue = INFINITY;
    double maxValue = -INFINITY;
    for (int j = 0; j < numMetricsToFetch; j++) {
        int timestamp = (int)(rand() * (double)1 / RAND_MAX * 1000000);
        double value = (double)(rand() * (double)1 / RAND_MAX);
        if (value > maxValue) {
            maxValue = value;
        }
        if (value < minValue) {
            minValue = value;
        }
    }

    // Filter and print metrics with status of "ERROR"
    for (int j = 0; j < i; j++) {
        if (metrics[j].status == ERROR) {
            printf("%f %d %d\n", metrics[j].value, metrics[j].timestamp, metrics[j].status);
        }
    }

    // Calculate average metric value
    double sum = 0;
    for (int j = 0; j < i; j++) {
        sum += metrics[j].value;
    }
    printf("Average: %f\n", sum / i);

    // Serialize data structure to file
    FILE* file = fopen("metrics.bin", "wb");
    fwrite(metrics, sizeof(Metric), i, file);
    fclose(file);

    // Deserialize data structure from file
    file = fopen("metrics.bin", "rb");
    Metric* deserializedMetrics = (Metric*)malloc(sizeof(Metric) * i);
    fread(deserializedMetrics, sizeof(Metric), i, file);
    fclose(file);
}
