#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

typedef struct {
    int id;
    char path[256];
    long long version;
    long long size;
    time_t modify_time;
    mode_t perms;
    uid_t owner;
} Entry;

typedef struct Node {
    Entry entry;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct HashTable {
    unsigned int size;
    Node** buckets;
} HashTable;

HashTable* create_hash_table(int size) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->size = size;
    table->buckets = (Node**)calloc(size, sizeof(Node*));
    for (int i = 0; i < size; i++) {
        table->buckets[i] = NULL;
    }
    return table;
}

void insert_entry(HashTable* table, Entry entry) {
    int index = entry.id % table->size;
    Node* node = (Node*)malloc(sizeof(Node));
    node->entry = entry;
    node->prev = NULL;
    node->next = table->buckets[index];
    if (table->buckets[index] != NULL) {
        table->buckets[index]->prev = node;
    }
    table->buckets[index] = node;
}

Entry* find_entry(HashTable* table, int id) {
    int index = id % table->size;
    Node* node = table->buckets[index];
    while (node != NULL) {
        if (node->entry.id == id) {
            return &node->entry;
        }
        node = node->next;
    }
    return NULL;
}

void print_largest_file_size(HashTable* table) {
    Entry* entry = NULL;
    long long max_size = 0;
    for (int i = 0; i < table->size; i++) {
        Node* node = table->buckets[i];
        while (node != NULL) {
            if (node->entry.size > max_size) {
                max_size = node->entry.size;
                entry = &node->entry;
            }
            node = node->next;
        }
    }
    printf("Largest file size: %lld bytes - Path: %s\n", entry->size, entry->path);
}

void print_most_recently_accessed(HashTable* table) {
    Entry* entry = NULL;
    time_t max_time = 0;
    for (int i = 0; i < table->size; i++) {
        Node* node = table->buckets[i];
        while (node != NULL) {
            if (node->entry.modify_time > max_time) {
                max_time = node->entry.modify_time;
                entry = &node->entry;
            }
            node = node->next;
        }
    }
    printf("Most recently accessed file: %s\n", entry->path);
}

void prune_inactive_entries(HashTable* table, int threshold) {
    for (int i = 0; i < table->size; i++) {
        Node* node = table->buckets[i];
        while (node != NULL) {
            if (node->entry.modify_time <= time(NULL) - threshold) {
                // prune inactive entry
            }
            node = node->next;
        }
    }
}

void serialize_data(HashTable* table, char* filename) {
    FILE* file = fopen(filename, "wb");
    fwrite(&table->size, sizeof(int), 1, file);
    for (int i = 0; i < table->size; i++) {
        Node* node = table->buckets[i];
        while (node != NULL) {
            Entry entry = node->entry;
            fwrite(&entry.id, sizeof(int), 1, file);
            fwrite(entry.path, sizeof(char), strlen(entry.path) + 1, file);
            fwrite(&entry.version, sizeof(long long), 1, file);
            fwrite(&entry.size, sizeof(long long), 1, file);
            fwrite(&entry.modify_time, sizeof(time_t), 1, file);
            fwrite(&entry.perms, sizeof(mode_t), 1, file);
            fwrite(&entry.owner, sizeof(uid_t), 1, file);
        }
    }
    fclose(file);
}

HashTable* deserialize_data(char* filename) {
    HashTable* table = create_hash_table(1000);
    FILE* file = fopen(filename, "rb");
    fread(&table->size, sizeof(int), 1, file);
    for (int i = 0; i < table->size; i++) {
        Node* node = NULL;
        Entry entry;
        fread(&entry.id, sizeof(int), 1, file);
        fread(entry.path, sizeof(char), strlen(entry.path) + 1, file);
        fread(&entry.version, sizeof(long long), 1, file);
        fread(&entry.size, sizeof(long long), 1, file);
        fread(&entry.modify_time, sizeof(time_t), 1, file);
        fread(&entry.perms, sizeof(mode_t), 1, file);
        fread(&entry.owner, sizeof(uid_t), 1, file);
    }
    fclose(file);
}

int main() {
    // Initialize the hash table
    HashTable* table = create_hash_table(1000);

    // Insert entries
    insert_entry(table, ...); // add your entries here

    // Find and print the largest file size
    print_largest_file_size(table);

    // Find and print the most recently accessed entry
    print_most_recently_accessed(table);

    // Prune inactive entries
    prune_inactive_entries(table, 3600); // prune entries older than 1 hour

    // Serialize the data to disk
    serialize_data(table, "file_paths.bin");

    // Deserialize the data from disk
    HashTable* table2 = deserialize_data("file_paths.bin");

    return 0;
}
