typedef struct {
    int key;
    long offset;
    short value;
} record;

record* expandGraphStructure(int* keys, int numKeys) {
    // Calculate required size for arrays
    int newSize = (numKeys / 10 + 1) * 10;

    // Allocate memory for new arrays and records
    int* newKeys = realloc(keys, sizeof(int) * newSize);
    long* offsets = realloc(NULL, sizeof(long) * newSize);
    record* newRecords = realloc(NULL, sizeof(record) * newSize);

    // Initialize last accessed indices for keys and offsets
    int* keyIndices = malloc(sizeof(int) * newSize);
    long* offsetIndices = malloc(sizeof(long) * newSize);

    // Copy existing data to new arrays
    if (keys != NULL) {
        for (int i = 0; i < numKeys; i++) {
            newKeys[i] = keys[i];
            offsets[i] = -1;
            keyIndices[i] = i;
            offsetIndices[i] = i;
        }
    }

    return newRecords;
}

void setRecordValue(record* records, int recordIndex, int min, int max) {
    // Set the value of each record's 'int' field to a random value within a given range
    records[recordIndex].value = rand() % (max - min + 1) + min;
}

int findLargestInteger(record* records, int numRecords) {
    int largest = INT_MIN;

    // Find the largest integer in the array
    for (int i = 0; i < numRecords; i++) {
        if (records[i].value > largest)
            largest = records[i].value;
    }

    return largest;
}

// Serialize data structure to file
void serializeData(record* records, FILE* file) {
    fwrite(&numRecords, sizeof(int), 1, file);
    for (int i = 0; i < numRecords; i++) {
        fwrite(&records[i].key, sizeof(int), 1, file);
        fwrite(&records[i].offset, sizeof(long), 1, file);
        fwrite(&records[i].value, sizeof(short), 1, file);
    }
}

// Deserialize data from file
record* deserializeData(FILE* file) {
    int numRecords;
    fread(&numRecords, sizeof(int), 1, file);

    record* records = malloc(sizeof(record) * numRecords);

    for (int i = 0; i < numRecords; i++) {
        fread(&records[i].key, sizeof(int), 1, file);
        fread(&records[i].offset, sizeof(long), 1, file);
        fread(&records[i].value, sizeof(short), 1, file);
    }

    return records;
}
