// Define the structure for a record pool
typedef struct {
    pthread_mutex_t mutex; // Mutex for synchronization
    size_t capacity; // Capacity of the pool
    Record** records; // Array of pointers to records
    size_t size; // Number of used slots in the pool
} RecordPool;

// Function to create and initialize a record pool
RecordPool* record_pool_create(size_t capacity) {
    RecordPool* pool = (RecordPool*)malloc(sizeof(RecordPool));
    pthread_mutex_init(&pool->mutex, NULL);
    pool->capacity = capacity;
    pool->records = (Record**)(calloc(capacity, sizeof(void*)));
    pool->size = 0;
    return pool;
}

// Function to add a record to the pool
void record_pool_add(RecordPool* pool, Record* record) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->size >= pool->capacity) {
        printf("Error: Record pool is full.\n");
        exit(EXIT_FAILURE);
    }
    pool->records[pool->size] = record;
    pool->size++;
    pthread_mutex_unlock(&pool->mutex);
}

// Function to get a record from the pool
Record* record_pool_get(RecordPool* pool, int key) {
    pthread_mutex_lock(&pool->mutex);
    for (int i = 0; i < pool->size; i++) {
        if (pool->records[i]->key == key) {
            Record* record = pool->records[i];
            pthread_mutex_unlock(&pool->mutex);
            return record;
        }
    }
    pthread_mutex_unlock(&pool->mutex);
    return NULL;
}

// Function to log errors
