// Custom file_info structure
typedef struct {
    char filename[256];
    int size;
    time_t last_modified;
} file_info;

// Node in the directory tree
typedef struct node {
    file_info *file_info;
    struct node **children;
    int num_children;
    int is_dir;
} node;

// Initialize a new node with given metadata and no children
node* create_node(char* filename, int size, time_t last_modified) {
    node* new_node = (node*)malloc(sizeof(node));
    new_node->file_info = (file_info*)malloc(sizeof(file_info));
    strcpy(new_node->file_info->filename, filename);
    new_node->file_info->size = size;
    new_node->file_info->last_modified = last_modified;
    new_node->children = NULL;
    new_node->num_children = 0;
    new_node->is_dir = 1; // Default to directory
    return new_node;
}

// Create a new node with no metadata and no children
node* create_directory() {
    return create_node("", 0, 0);
}

// Traverse the tree recursively
void traverse_tree(node* root) {
    if (root == NULL)
        return;

    // Perform operations on this node
    printf("%s\n", root->file_info->filename);

    // Recursively traverse child nodes
    for (int i = 0; i < root->num_children; i++) {
        traverse_tree(root->children[i]);
    }
}

// Calculate the total size of all files in a directory
long long get_total_size(node* root) {
    if (root == NULL)
        return 0;

    long long total_size = root->file_info->size;
    for (int i = 0; i < root->num_children; i++) {
        total_size += get_total_size(root->children[i]);
    }
    return total_size;
}

// Main function to create a directory hierarchy and perform operations
int main() {
    // Create the directory structure dynamically
    node* root = create_directory();
    node* dir1 = create_directory();
    node* file1 = create_node("file1.txt", 1024, time(NULL));
    node* file2 = create_node("file2.txt", 2048, time(NULL));
    node* dir2 = create_directory();

    // Set up the hierarchy
    root->children[0] = dir1;
    root->children[1] = file1;
    root->children[2] = file2;
    root->children[3] = dir2;

    // Perform operations on the directory tree
    traverse_tree(root);
    long long total_size = get_total_size(root);
    printf("Total size: %lld\n", total_size);

    return 0;
}
