#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the maximum number of offsets
#define MAX_OFFSETS 1000

// Define the range for offset values
#define OFFSET_MIN 0
#define OFFSET_MAX 1000000

// Define the maximum number of keys
#define MAX_KEYS 10000

// Define the range for key values
#define KEY_MIN 1
#define KEY_MAX 10000

// Define a structure for records
typedef struct {
    int value;
    char letter;
} record;

record* initRecords(int count) {
    record *records = (record*)malloc(count * sizeof(record));
    if (!records) return NULL; // Allocation failed, return NULL

    srand(time(NULL)); // Initialize random number generator

    for (int i = 0; i < count; i++) {
        records[i].value = rand() % (100 + 1) - 100; // Generate a random value
        records[i].letter = 'A' + rand() % 26; // Generate a random uppercase letter
    }

    return records;
}

long* initOffsets(int count) {
    long *offsets = (long*)malloc(count * sizeof(long));
    if (!offsets) return NULL; // Allocation failed, return NULL

    for (int i = 0; i < count; i++) {
        offsets[i] = rand() % (OFFSET_MAX - OFFSET_MIN + 1) + OFFSET_MIN; // Generate a random offset
    }

    return offsets;
}

int* initKeys(int count) {
    int *keys = (int*)malloc(count * sizeof(int));
    if (!keys) return NULL; // Allocation failed, return NULL

    for (int i = 0; i < count; i++) {
        keys[i] = rand() % (KEY_MAX - KEY_MIN + 1) + KEY_MIN; // Generate a random key
        // Check for collisions and generate a new key if needed
        for (int j = 0; j < i; j++) {
            if (keys[j] == keys[i]) {
                keys[i] = rand() % (KEY_MAX - KEY_MIN + 1) + KEY_MIN;
                break;
            }
        }
    }

    return keys;
}

int main() {
    int count;

    printf("Enter the number of components: ");
    scanf("%d", &count);

    if (count > MAX_OFFSETS || count > MAX_KEYS) {
        printf("Error: Input exceeds maximum limit.\n");
        return 1; // Return error code
    }

    long *offsets = initOffsets(count);
    int *keys = initKeys(count);
    record *records = initRecords(count);

    if (!offsets || !keys || !records) {
        printf("Error: Memory allocation failed for one or more components.\n");
        return 2; // Return error code
    }

    printf("Initialization successful!\n");

    // Free dynamically allocated memory when done
    free(offsets);
    free(keys);
    free(records);

    return 0;
}
