// Data structure for storing and retrieving records
typedef struct Record {
    int id;
    long offset;
    int value;
} Record;

Record* records = NULL;
int record_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new record
void add_record(int id, long offset, int value) {
    pthread_mutex_lock(&mutex);
    Record* new_record = (Record*) my_malloc(sizeof(Record));
    new_record->id = id;
    new_record->offset = offset;
    new_record->value = value;
    records = realloc(records, (record_count + 1) * sizeof(Record));
    records[record_count] = *new_record;
    record_count++;
    pthread_mutex_unlock(&mutex);
}

// Function to retrieve a record by ID
Record* get_record(int id) {
    Record* target_record = NULL;
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < record_count; i++) {
        if (records[i].id == id) {
            target_record = &records[i];
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
    return target_record;
}

// Function to delete a record by ID
void delete_record(int id) {
    int index_to_delete = -1;
    Record* target_record = NULL;
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < record_count; i++) {
        if (records[i].id == id) {
            target_record = &records[i];
            index_to_delete = i;
            break;
        }
    }
    if (index_to_delete != -1) {
        memmove(&records[index_to_delete], &records[index_to_delete + 1], (record_count - index_to_delete - 1) * sizeof(Record));
        record_count--;
        free(target_record);
    }
    pthread_mutex_unlock(&mutex);
}

