        trajectories[i]->points = (point *)malloc(trajectories[i]->num_points * sizeof(point));
    }

    int status = 0;
    trajectory **result = (trajectory **)malloc((num_trajectories + 1) * sizeof(trajectory *));
    *result = trajectories;
    for (int i = 0; i < num_trajectories; i++) {
        result[i] = &trajectories[i];
    }
    return status, result;
}
