    free(connection);
}

// Define structure to represent a connection list
typedef struct {
    Connection** connections;
    int size;
    pthread_mutex_t mutex;
} ConnectionList;

// Initialize connection list with default size and initialize mutex
ConnectionList* init_connection_list(int initial_size) {
    ConnectionList* list = (ConnectionList*)malloc(sizeof(ConnectionList));
    list->connections = (Connection**)malloc(initial_size * sizeof(Connection*));
    list->size = initial_size;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

// Add a new connection to the list
void add_connection(ConnectionList* list, Connection* connection) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->size; i++) {
        if (!list->connections[i]) {
            list->connections[i] = connection;
            break;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

// Remove a connection from the list
void remove_connection(ConnectionList* list, Connection* connection) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->size; i++) {
        if (list->connections[i] == connection) {
            list->connections[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

