// Enum for priority levels
enum {
    LOW,
    MEDIUM,
    HIGH
};

// Structure to represent a log entry
typedef struct {
    int timestamp;
    char message[256];
    enum {LOW, MEDIUM, HIGH} priority;
} logEntry;

// Function to manage and process logs
void manageAndProcessLogs(int maxEntries) {
    // Initialize arrays for timestamps, messages, and log entries
    int* timestamps = NULL;
    char** messages = NULL;
    logEntry* logs = NULL;

    // Allocate initial memory
    timestamps = (int*)malloc(maxEntries * sizeof(int));
    messages = (char**)malloc(maxEntries * sizeof(char*));
    logs = (logEntry*)malloc(maxEntries * sizeof(logEntry));

    int timestampCount = 0;
    for (int i = 0; i < maxEntries; i++) {
        // Read log entry from standard input
        int newTimestamp;
        char newMessage[256];
        enum {LOW, MEDIUM, HIGH} priority;

        // Check if we have reached the maximum entries
        if (timestampCount >= maxEntries) {
            // Resize arrays and allocate more memory
            maxEntries *= 2;
            timestamps = (int*)realloc(timestamps, maxEntries * sizeof(int));
            messages = (char**)realloc(messages, maxEntries * sizeof(char*));
            logs = (logEntry*)realloc(logs, maxEntries * sizeof(logEntry));

            // Shift existing data to the beginning of the arrays
            memmove(timestamps, timestamps + timestampCount, timestampCount * sizeof(int));
            for (int j = 0; j < timestampCount; j++) {
                messages[j] = (char*)realloc(messages[j], strlen(messages[j]) + 1);
                if (!messages[j]) {
                    perror("Reallocation failed");
                    exit(EXIT_FAILURE);
                }
            }

            // Update maxEntries
            timestampCount = i;
        }

        // Read log entry from standard input and store it in the arrays
        scanf("%d %s %hhu", &newTimestamp, newMessage, &priority);

        timestamps[timestampCount] = newTimestamp;
        messages[timestampCount] = (char*)strdup(newMessage);
        logs[timestampCount].timestamp = newTimestamp;
        logs[timestampCount].message = newMessage;
        logs[timestampCount].priority = priority;

        timestampCount++;
    }

    // Serialize the log entries to a file
    FILE* file = fopen("logs.bin", "wb");
    if (!file) {
        perror("File not found");
        exit(EXIT_FAILURE);
    }
    fwrite(logs, sizeof(logEntry), timestampCount, file);
    fclose(file);

    // Deserialize the log entries from a file
    file = fopen("logs.bin", "rb");
    if (!file) {
        perror("File not found");
        exit(EXIT_FAILURE);
    }
    fseek(file, 0, SEEK_END);
    size_t fileSize = ftell(file);
    rewind(file);
    logEntry* deserializedLogs = (logEntry*)malloc(fileSize / sizeof(logEntry));
    fread(deserializedLogs, sizeof(logEntry), fileSize / sizeof(logEntry), file);
    fclose(file);

    // Print logs with a specific priority level
    enum {LOW, MEDIUM, HIGH} priorityLevel;
    printf("Enter the priority level: ");
    scanf("%hhu", &priorityLevel);

    for (int i = 0; i < timestampCount; i++) {
        if (logs[i].priority == priorityLevel) {
            printf("Timestamp: %d, Message: %s, Priority: %hhu\n",
                   logs[i].timestamp, logs[i].message, logs[i].priority);
        }
    }

    // Calculate the average log length
    int totalLength = 0;
    for (int i = 0; i < timestampCount; i++) {
        totalLength += strlen(logs[i].message);
    }
    printf("Average log length: %d\n", totalLength / timestampCount);

    free(timestamps);
    free(messages);
    free(logs);
}

int main() {
    int maxEntries = 1000000;
    manageAndProcessLogs(maxEntries);
    return 0;
}
