#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 10000000
#define THRESHOLD 5000
#define SERIALIZATION_FORMAT_VERSION 1

typedef struct {
    int key;
    int value;
    long timestamp;
    int active;
} record_t;

record_t *records = NULL;
int records_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void* serialize_data(void) {
    FILE *fp = fopen("data.bin", "wb");
    if (!fp) return NULL;

    int version = SERIALIZATION_FORMAT_VERSION;
    fwrite(&version, sizeof(int), 1, fp);
    fwrite(&records_count, sizeof(int), 1, fp);
    for (int i = 0; i < records_count; i++) {
        record_t rec = records[i];
        fwrite(&rec.key, sizeof(int), 1, fp);
        fwrite(&rec.value, sizeof(int), 1, fp);
        fwrite(&rec.timestamp, sizeof(long), 1, fp);
        fwrite(&rec.active, sizeof(int), 1, fp);
    }

    fclose(fp);
    return NULL;
}

int deserialize_data() {
    FILE *fp = fopen("data.bin", "rb");
    if (!fp) return -1;

    int version;
    fread(&version, sizeof(int), 1, fp);
    if (version != SERIALIZATION_FORMAT_VERSION) return -2;

    int count;
    fread(&count, sizeof(int), 1, fp);
    records_count = count;

    records = realloc(records, records_count * sizeof(record_t));
    for (int i = 0; i < records_count; i++) {
        record_t rec;
        fread(&rec.key, sizeof(int), 1, fp);
        fread(&rec.value, sizeof(int), 1, fp);
        fread(&rec.timestamp, sizeof(long), 1, fp);
        fread(&rec.active, sizeof(int), 1, fp);
        records[i] = rec;
    }

    fclose(fp);
    return 0;
}

void* update_timestamp(void* key) {
    int k = *(int*)key;
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < records_count; i++) {
        if (records[i].key == k) {
            records[i].timestamp = time(NULL);
            break;
        }
    }
    pthread_mutex_unlock(&mutex);

    return NULL;
}

void* add_record(void* key, void* value) {
    int k = *(int*)key;
    int v = *(int*)value;

    if (records_count >= THRESHOLD) {
        records = realloc(records, (THRESHOLD * 2 + 1) * sizeof(record_t));
        THRESHOLD *= 2;
    }

    record_t rec;
    rec.key = k;
    rec.value = v;
    rec.timestamp = time(NULL);
    rec.active = 1;

    records[records_count] = rec;
    records_count++;

    return NULL;
}

void* find_largest_value(void) {
    int max_val = INT_MIN;
    for (int i = 0; i < records_count; i++) {
        if (records[i].active && records[i].value > max_val) {
            max_val = records[i].value;
        }
    }

    return &max_val;
}

void* print_records(void) {
    for (int i = 0; i < records_count; i++) {
        printf("%d: %d, %ld, %d\n", records[i].key, records[i].value, records[i].timestamp, records[i].active);
    }

    return NULL;
}

void* handle_write(void) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < records_count; i++) {
        if (records[i].key == *(int*)pthread_getspecific(pthread_self())) {
            records[i].timestamp = time(NULL);
            break;
        }
    }
    pthread_mutex_unlock(&mutex);

    return NULL;
}

void* handle_read(void) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < records_count; i++) {
        if (records[i].key == *(int*)pthread_getspecific(pthread_self())) {
            printf("%d: %d, %ld, %d\n", records[i].key, records[i].value, records[i].timestamp, records[i].active);
            break;
        }
    }
    pthread_mutex_unlock(&mutex);

    return NULL;
}

void* handle_delete(void) {
    int k = *(int*)pthread_getspecific(pthread_self());
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < records_count; i++) {
        if (records[i].key == k) {
            records[i].active = 0;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);

    return NULL;
}

void main() {
    int keys[MAX_RECORDS];
    int key_count;

    printf("Enter a list of integer keys: ");
    scanf("%d", &key_count);

    for (int i = 0; i < key_count; i++) {
        scanf("%d", &keys[i]);
    }

    pthread_t threads[key_count];

    for (int i = 0; i < key_count; i++) {
        pthread_create(&threads[i], NULL, add_record, &keys[i]);
    }

    for (int i = 0; i < key_count; i++) {
        pthread_join(threads[i], NULL);
    }

    printf("Records count: %d\n", records_count);

    int max_val;
    pthread_t thread;

    pthread_create(&thread, NULL, find_largest_value, NULL);
    pthread_join(thread, &max_val);
    printf("Largest value: %d\n", *max_val);

    for (int i = 0; i < key_count; i++) {
        pthread_create(&threads[i], NULL, print_records, NULL);
    }

    for (int i = 0; i < key_count; i++) {
        pthread_join(threads[i], NULL);
    }
}
