#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a struct to represent a user profile
typedef struct {
    char *username;
    int numFriends;
    int *privacySettings; // Array of size 5 (public, friends, followers, private)
} UserProfile;

// Define a struct to represent a linked list node
typedef struct Node {
    UserProfile *profile;
    struct Node *next;
} Node;

// Hash map to store user profiles by username
typedef struct {
    int capacity;
    Node **buckets;
} HashMap;

HashMap *createHashMap(int capacity) {
    HashMap *map = (HashMap *)malloc(sizeof(HashMap));
    map->capacity = capacity;
    map->buckets = (Node **)malloc(capacity * sizeof(Node *));
    for (int i = 0; i < capacity; i++) {
        map->buckets[i] = NULL;
    }
    return map;
}

void freeHashMap(HashMap *map) {
    for (int i = 0; i < map->capacity; i++) {
        Node *current = map->buckets[i];
        while (current != NULL) {
            Node *next = current->next;
            free(current);
            current = next;
        }
    }
    free(map->buckets);
    free(map);
}

// Function to add a user profile to the hash map
void addUser(HashMap *map, UserProfile *profile) {
    int index = profile->username[0] % map->capacity; // Simple hashing function
    Node **bucket = &map->buckets[index];
    Node *newNode = (Node *)malloc(sizeof(Node));
    newNode->profile = profile;
    newNode->next = *bucket;
    *bucket = newNode;
}

// Function to find a user by username and return their profile
UserProfile *findUser(HashMap *map, char *username) {
    int index = username[0] % map->capacity; // Simple hashing function
    Node *current = map->buckets[index];
    while (current != NULL && strcmp(current->profile->username, username) != 0) {
        current = current->next;
    }
    return current == NULL ? NULL : current->profile;
}

// Function to remove a user by username and free their profile
void removeUser(HashMap *map, char *username) {
    int index = username[0] % map->capacity; // Simple hashing function
    Node **bucket = &map->buckets[index];
    Node *current = *bucket;
    Node *previous = NULL;
    while (current != NULL && strcmp(current->profile->username, username) != 0) {
        previous = current;
        current = current->next;
    }
    if (current == NULL) return; // User not found
    if (previous == NULL) {
        *bucket = current->next;
    } else {
        previous->next = current->next;
    }
    free(current);
}

// Function to serialize the hash map to a file
void serializeHashMap(HashMap *map, FILE *file) {
    for (int i = 0; i < map->capacity; i++) {
        Node *current = map->buckets[i];
        while (current != NULL) {
            UserProfile *profile = current->profile;
            fwrite(&profile->username, sizeof(char), strlen(profile->username), file);
            fwrite(&profile->numFriends, sizeof(int), 1, file);
            fwrite(profile->privacySettings, sizeof(int), 5, file);
            current = current->next;
        }
    }
}

// Function to deserialize the hash map from a file
HashMap *deserializeHashMap(FILE *file) {
    HashMap *map = createHashMap(100); // Default capacity
    int size;
    fscanf(file, "%d", &size);
    for (int i = 0; i < size; i++) {
        UserProfile *profile = (UserProfile *)malloc(sizeof(UserProfile));
        profile->username = (char *)malloc(strlen(profile->username) + 1);
        profile->numFriends = 0;
        profile->privacySettings = (int *)malloc(5 * sizeof(int));
        for (int j = 0; j < 5; j++) {
            fscanf(file, "%d", &profile->privacySettings[j]);
        }
        addUser(map, profile);
    }
    return map;
}

// Function to clean up unused resources
void cleanupUnusedResources(HashMap *map) {
    for (int i = 0; i < map->capacity; i++) {
        Node *current = map->buckets[i];
        Node *previous = NULL;
        while (current != NULL) {
            UserProfile *profile = current->profile;
            if (profile->numFriends == 0) {
                removeUser(map, profile->username);
            }
            current = current->next;
        }
    }
}

// Function to print the user with the highest number of friends
void printHighestFriendCount(HashMap *map) {
    UserProfile *highestFriendProfile = NULL;
    int highestFriendCount = 0;
    for (int i = 0; i < map->capacity; i++) {
        Node *current = map->buckets[i];
        while (current != NULL) {
            UserProfile *profile = current->profile;
            if (profile->numFriends > highestFriendCount) {
                highestFriendProfile = profile;
                highestFriendCount = profile->numFriends;
            }
            current = current->next;
        }
    }
    printf("User with the highest friend count: %s (%d friends)\n", highestFriendProfile->username, highestFriendCount);
}

int main() {
    HashMap *map = createHashMap(100);
    // Add user profiles and perform operations...
    serializeHashMap(map, fopen("user_profiles.txt", "wb"));
    return 0;
}
