#define MAX_CONNECTIONS 10000
#define PORT_RANGE 1,65535
#define IP_ADDRESS_LENGTH 15

typedef struct {
    int id;
    char ip[IP_ADDRESS_LENGTH];
    int port;
    time_t last_activity;
} Connection;

Connection* connections = NULL;
int connection_count = 0;

// Initialize the connection object
void initialize_connection(Connection* connection) {
    connection->id = connection_count++;
    srand(time(NULL));
    for (int i = 0; i < IP_ADDRESS_LENGTH; i++) {
        connection->ip[i] = (char)(rand() % 256);
    }
    connection->port = rand() % (PORT_RANGE[1] - PORT_RANGE[0]) + PORT_RANGE[0];
    connection->last_activity = time(NULL);
}

// Add a new connection to the collection
void add_connection(Connection* new_connection) {
    if (!connections || connection_count >= MAX_CONNECTIONS) {
        connections = realloc(connections, sizeof(Connection) * (connection_count * 2));
        if (!connections) {
            printf("Memory allocation failure.\n");
            return;
        }
        connection_count *= 2;
    }
    new_connection->id = connection_count++;
    connections[connection_count - 1] = *new_connection;
}

// Update the last activity timestamp for an existing connection
void update_connection(int id) {
    for (int i = 0; i < connection_count; i++) {
        if (connections[i].id == id) {
            connections[i].last_activity = time(NULL);
            return;
        }
    }
    printf("Connection not found.\n");
}

// Remove disconnected connections
void remove_disconnected_connections() {
    for (int i = 0; i < connection_count; i++) {
        if ((time(NULL) - connections[i].last_activity) > 60 * 5) { // 5 minutes
            connection_count--;
            memmove(&connections[i], &connections[i + 1], sizeof(Connection) * (connection_count - i));
            i--;
        }
    }
}

// Serialize the connection data structure to a file
void serialize_connections(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        printf("File operation failure.\n");
        return;
    }
    fwrite(&connection_count, sizeof(int), 1, file);
    for (int i = 0; i < connection_count; i++) {
        fwrite(&connections[i], sizeof(Connection), 1, file);
    }
    fclose(file);
}

// Deserialize the connection data structure from a file
void deserialize_connections(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        printf("File operation failure.\n");
        return;
    }
    fread(&connection_count, sizeof(int), 1, file);
    connections = realloc(connections, sizeof(Connection) * connection_count);
    for (int i = 0; i < connection_count; i++) {
        fread(&connections[i], sizeof(Connection), 1, file);
    }
    fclose(file);
}

// Initialize the connection collection
void init_connections() {
    connections = malloc(sizeof(Connection));
    connection_count = 1;
    initialize_connection(connections);
}

int main() {
    init_connections();
    // Add new connections
    add_connection((Connection){.ip="192.168.1.100", .port=8080, .last_activity=time(NULL)});
    add_connection((Connection){.ip="10.0.0.5", .port=8443, .last_activity=time(NULL)});

    // Update connection timestamps
    update_connection(0);
    update_connection(1);

    // Remove disconnected connections
    remove_disconnected_connections();

    // Serialize and deserialize the connection data structure
    serialize_connections("connections.bin");
    deserialize_connections("connections.bin");

    return 0;
}
