// Define a node structure with an integer key and a pointer to the next node
typedef struct Node {
    int key;
    struct Node* next;
} Node;

// Function to create a new node with given key
Node* newNode(int key) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->key = key;
    node->next = NULL;
    return node;
}

// Function to insert a node at the head of the list
void insertAtHead(Node** head, int key) {
    Node* node = newNode(key);
    node->next = *head;
    *head = node;
}

// Function to insert a node at the specified position in the list
void insertAtPosition(Node** head, int key, int position) {
    if (position == 0) {
        insertAtHead(head, key);
        return;
    }

    Node* current = *head;
    for (int i = 0; i < position - 1 && current->next != NULL; i++) {
        current = current->next;
    }

    if (current->next == NULL) {
        current->next = newNode(key);
    } else {
        Node* node = newNode(key);
        node->next = current->next;
        current->next = node;
    }
}

// Function to print the keys of all nodes in the list
void printList(Node* head) {
    while (head != NULL) {
        printf("%d ", head->key);
        head = head->next;
    }
    printf("\n");
}

int main() {
    // Example usage:
    Node* head = NULL;

    insertAtHead(&head, 1);
    insertAtPosition(&head, 2, 0);
    insertAtPosition(&head, 3, 1);
    printList(head);  // Output: 2 1 3

    return 0;
}
