    // Populate the offsets array with sequential integers
    for(int i = 0; i < 10000; i++) {
        offsets[i] = i + 1;
    }

    // Populate the keys array with random integers
    for(int i = 0; i < 5000; i++) {
        keys[i] = rand() % 9999;
    }

    // Define and allocate memory for record structures
