typedef struct Node {
    int key;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct DLL {
    Node* head;
    Node* tail;
    int size;
} DLL;

DLL* dllCreate() {
    DLL* list = (DLL*)malloc(sizeof(DLL));
    if (!list) return NULL;
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    return list;
}

void dllInsert(DLL* list, int key) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        printf("Memory allocation failed!\n");
        return;
    }
    newNode->key = key;
    if (list->head == NULL) {
        list->head = newNode;
        list->tail = newNode;
    } else {
        newNode->next = list->head;
        list->head->prev = newNode;
        list->head = newNode;
    }
    list->size++;
}

void dllRemove(DLL* list, int key) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->key == key) {
            if (current->prev != NULL) {
                current->prev->next = current->next;
            } else {
                list->head = current->next;
            }
            if (current->next != NULL) {
                current->next->prev = current->prev;
            } else {
                list->tail = current->prev;
            }
            free(current);
            list->size--;
            return;
        }
        current = current->next;
    }
    printf("Key not found!\n");
}

int dllSearch(DLL* list, int key) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->key == key) {
            return 1;
        }
        current = current->next;
    }
    return -1;
}

void dllDestroy(DLL* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}
