['Here is a basic implementation of a binary search tree in C:

```c
#include <stdio.h>
#include <stdlib.h>

// Structure for each node
typedef struct Node {
    int key;
    struct Node* left;
    struct Node* right;
} Node;

// Function to create a new node with given key
Node* createNode(int key) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        printf("Memory error\n");
        return NULL;
    }
    newNode->key = key;
    newNode->left = newNode->right = NULL;
    return newNode;
}

// Function to insert a new node with given key
void insertNode(Node** root, int key) {
    if (*root == NULL) {
        *root = createNode(key);
        return;
    }

    Node* current = *root;
    Node* previous = NULL;

    while (current != NULL) {
        previous = current;
        if (key < current->key) {
            current = current->left;
        } else if (key > current->key) {
            current = current->right;
        } else {
            printf("Key already exists in the tree\n");
            return;
        }
    }

    if (previous != NULL && key < previous->key) {
        previous->left = createNode(key);
    } else if (previous != NULL && key > previous->key) {
        previous->right = createNode(key);
    }
}

// Function to print the keys of all nodes in order
void printTree(Node* root) {
    if (root == NULL)
        return;

    printTree(root->left);
    printf("%d ", root->key);
    printTree(root->right);
}

int main() {
    Node* root = NULL;

    // Insert nodes into the tree
    insertNode(&root, 5);
    insertNode(&root, 2);
    insertNode(&root, 8);
    insertNode(&root, 3);
    insertNode(&root, 9);

    // Print the keys of all nodes in order
    printTree(root);

    return 0;
}
```

This code creates a binary search tree where each node contains an integer key and pointers to its left and right children. It includes functions to create a new node, insert a new node into the tree based on its key value, and print the keys of all nodes in order.']

