// Define a structure to manage the hash table
typedef struct {
    size_t capacity;
    size_t size;
    struct profile** profiles;
    unsigned long seed;
} HashTable;

// Function to initialize the hash table
HashTable* init_hash_table(size_t capacity) {
    HashTable* ht = (HashTable*)malloc(sizeof(HashTable));
    ht->capacity = capacity;
    ht->size = 0;
    ht->profiles = (struct profile**)calloc(capacity, sizeof(struct profile*));
    return ht;
}

// Function to hash a username into an index for the hash table
unsigned int hash_username(const char* username, HashTable* ht) {
    unsigned long hash = 5381;
    while (*username) {
        hash = (hash << 5) + *username;
        username++;
    }
    return (unsigned int)(ht->seed + hash % ht->capacity);
}

// Function to insert a profile into the hash table
void insert_profile(HashTable* ht, const char* username, const char* email, int record) {
    unsigned int index = hash_username(username, ht);
    Profile* profile = (Profile*)malloc(sizeof(Profile));
    strcpy(profile->username, username);
    strcpy(profile->email, email);
    profile->record = record;
    profile->roles = NULL;

    // Add the profile to the linked list if it doesn't exist
    for (size_t i = 0; i < ht->capacity; i++) {
        if (!ht->profiles[i]) {
            ht->profiles[i] = profile;
            return;
        }
    }

    // Resize the hash table if necessary
    if (ht->size >= ht->capacity / 2) {
        size_t new_capacity = ht->capacity * 2;
        HashTable* new_ht = init_hash_table(new_capacity);
        for (size_t i = 0; i < ht->capacity; i++) {
            if (ht->profiles[i]) {
                unsigned int new_index = hash_username(ht->profiles[i]->username, new_ht);
                new_ht->profiles[new_index] = ht->profiles[i];
            }
        }
        free(ht->profiles);
        ht->profiles = new_ht->profiles;
        ht->capacity = new_capacity;
        ht->size = 0;
    }

    // Add the profile to the hash table
    ht->profiles[index] = profile;
}

