    if (!profile) return;

    // Remove the profile's roles
    RoleNode* current = profile->roles;
    while (current) {
        RoleNode* next = current->next;
        free(current);
        current = next;
    }
    free(profile);

    // Update the hash table and resize if necessary
    ht->profiles[index] = NULL;
    ht->size--;
    if (ht->size <= ht->capacity / 4) {
        size_t new_capacity = ht->capacity / 2;
        HashTable* new_ht = init_hash_table(new_capacity);
        for (size_t i = 0; i < ht->capacity; i++) {
            if (ht->profiles[i]) {
                unsigned int new_index = hash_username(ht->profiles[i]->username, new_ht);
                new_ht->profiles[new_index] = ht->profiles[i];
            }
        }
        free(ht->profiles);
