#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the maximum number of active user profiles
#define MAX_USER_PROFILES 50000

// Define the maximum number of historical versions per profile
#define MAX_HISTORICAL_VERSIONS 100000

// Define the structure for a single record within a profile
typedef struct {
    int value;
} record_t;

// Define the structure for a user profile, containing username, email, and roles
typedef struct {
    char* username;
    char* email;
    int numRoles;
    record_t** roles;
    int historicalVersions[MAX_HISTORICAL_VERSIONS];
} profile_t;

// Define the hash table structure for fast lookups
typedef struct {
    int size;
    profile_t** profiles;
} hashtable_t;

// Define the linked list structure for managing roles
typedef struct node {
    char* roleName;
    struct node* next;
} node_t;

// Function to create a new user profile
profile_t* createProfile(char* username, char* email) {
    // Allocate memory for the profile structure
    profile_t* profile = (profile_t*)malloc(sizeof(profile_t));

    // Initialize fields and return the new profile
    profile->username = username;
    profile->email = email;
    profile->numRoles = 0;
    profile->roles = NULL;

    return profile;
}

// Function to add a role to a user profile
void addRole(profile_t* profile, char* roleName) {
    // Create a new node for the role and append it to the linked list
    node_t* newNode = (node_t*)malloc(sizeof(node_t));
    newNode->roleName = roleName;
    newNode->next = profile->roles[profile->numRoles];
    profile->roles[profile->numRoles] = newNode;

    // Increment the number of roles for this profile
    profile->numRoles++;
}

// Function to remove a role from a user profile
void removeRole(profile_t* profile, char* roleName) {
    // Find the node with the specified role name and remove it from the linked list
    node_t* current = profile->roles[0];
    node_t* prev = NULL;

    while (current != NULL) {
        if (strcmp(current->roleName, roleName) == 0) {
            if (prev == NULL) {
                profile->roles[profile->numRoles - 1] = current->next;
            } else {
                prev->next = current->next;
            }

            // Decrement the number of roles for this profile
            profile->numRoles--;
            break;
        }

        prev = current;
        current = current->next;
    }
}

// Function to get a user profile by username
profile_t* getUserProfile(hashtable_t* table, char* username) {
    // Iterate through the hash table to find the desired profile
    for (int i = 0; i < table->size; i++) {
        if (strcmp(table->profiles[i]->username, username) == 0) {
            return table->profiles[i];
        }
    }

    // Profile not found, return NULL
    return NULL;
}

// Function to add a new user profile to the hash table
void addUserProfile(hashtable_t* table, char* username, char* email) {
    // Create a new user profile and insert it into the hash table
    profile_t* profile = createProfile(username, email);

    // Hash function for indexing the hash table
    int index = strlen(username) % table->size;

    // Insert the profile at the computed index
    for (int i = 0; i < table->size; i++) {
        if (table->profiles[i] == NULL) {
            table->profiles[i] = profile;
            break;
        }
    }
}

// Function to free all allocated resources when the collection is no longer needed
void freeResources(hashtable_t* table) {
    // Iterate through the hash table and free each user profile
    for (int i = 0; i < table->size; i++) {
        if (table->profiles[i] != NULL) {
            // Free the roles linked list and the profile itself
            node_t* current = table->profiles[i]->roles[0];
            while (current != NULL) {
                node_t* next = current->next;
                free(current);
                current = next;
            }

            free(table->profiles[i]);
        }
    }

    // Free the hash table structure itself
    free(table);
}
