typedef struct Record {
    int key;
    int value;
    char* string;
} Record;

Record* initializeRecords(int capacity) {
    Record* records = (Record*)malloc(capacity * sizeof(Record));
    if (!records) {
        LOG_ERROR("Memory allocation failed");
        return NULL;
    }

    for (int i = 0; i < capacity; i++) {
        records[i].key = rand() % 100 + 1; // Initialize key with random number between 1 and 100
        records[i].value = rand() % 100 + 1; // Initialize value with random number between 1 and 100

        // Allocate memory for string dynamically
        char* str = (char*)malloc(20 * sizeof(char)); // assuming maximum length of string is 20 characters
        if (!str) {
            LOG_ERROR("Memory allocation failed");
            return NULL;
        }

        sprintf(str, "Record %d", i); // Initialize string with record number

        records[i].string = str; // Set the dynamically allocated string in the record structure
    }

    return records;
}

void deallocateRecords(Record* records, int capacity) {
    for (int i = 0; i < capacity; i++) {
        free(records[i].string); // Free memory allocated for strings
    }
    free(records); // Free memory allocated for the array of record structures
}
