#define INPUT_DATA_SIZE 1000000
#define PROCESSING_STATE_SIZE 500000
#define OUTPUT_RESULTS_SIZE 250000

typedef struct {
    double* data;
    int size;
} MemoryPool;

MemoryPool create_memory_pool(int size) {
    MemoryPool pool = (MemoryPool)malloc(sizeof(struct));
    pool->data = (double*)malloc(size * sizeof(double));
    pool->size = size;
    return pool;
}

void free_memory_pool(MemoryPool* pool) {
    if (pool != NULL && pool->data != NULL) {
        free(pool->data);
        free((void*)pool);
    }
}

int main() {
    MemoryPool memory_pool;

    // Create the memory pool for the datasets
    memory_pool = create_memory_pool(INPUT_DATA_SIZE + PROCESSING_STATE_SIZE + OUTPUT_RESULTS_SIZE);

    // Initialize and populate the datasets
    double* inputData = memory_pool.data;
    char* processingState = (char*)((void*)inputData + INPUT_DATA_SIZE * sizeof(double));
    float* outputResults = (float*)((void*)processingState + PROCESSING_STATE_SIZE * sizeof(char));

    for (int i = 0; i < INPUT_DATA_SIZE; i++) {
        inputData[i] = (double)(rand() / (RAND_MAX / 1000.0) - 1);
    }

    for (int i = 0; i < PROCESSING_STATE_SIZE; i++) {
        processingState[i] = rand() % 2;
    }

    // Perform the complex transformation
    for (int i = 0; i < OUTPUT_RESULTS_SIZE; i++) {
        outputResults[i] = cos(inputData[(i * 3) % INPUT_DATA_SIZE]) + log(processingState[(i * 5) % PROCESSING_STATE_SIZE] ? 2 : 1);
    }

    // Free the allocated memory
    free_memory_pool(&memory_pool);

    return 0;
}
