#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>

// Define the maximum number of records that can be stored in memory
#define MAX_RECORDS 10000000

// Structure to represent a record with offset, key, and value
typedef struct {
    long offset;
    int key;
    double value;
} Record;

// Data structure to store and manage records
typedef struct {
    Record* records; // Array of records
    size_t capacity; // Capacity of the array
    size_t size; // Current number of records stored
    pthread_mutex_t lock; // Mutex for concurrent access
} RecordSet;

// Function to create a new record set with initial capacity
RecordSet* record_set_create() {
    RecordSet* set = (RecordSet*) malloc(sizeof(RecordSet));
    set->records = (Record*) malloc(MAX_RECORDS * sizeof(Record));
    set->capacity = MAX_RECORDS;
    set->size = 0;
    pthread_mutex_init(&set->lock, NULL);
    return set;
}

// Function to resize the record array when necessary
void record_set_resize(RecordSet* set) {
    if (set->size >= set->capacity * 0.75) {
        set->capacity *= 2;
        set->records = (Record*) realloc(set->records, set->capacity * sizeof(Record));
    }
}

// Function to add a new record to the data structure
void record_set_insert(RecordSet* set, long offset, int key, double value) {
    pthread_mutex_lock(&set->lock);
    record_set_resize(set);

    Record new_record = {offset, key, value};
    set->records[set->size] = new_record;
    set->size++;
    pthread_mutex_unlock(&set->lock);
}

// Function to update the value of a specific record
void record_set_update(RecordSet* set, int key, double value) {
    pthread_mutex_lock(&set->lock);

    for (int i = 0; i < set->size; i++) {
        if (set->records[i].key == key) {
            set->records[i].value = value;
            break;
        }
    }

    pthread_mutex_unlock(&set->lock);
}

// Function to remove a record by its key
void record_set_remove(RecordSet* set, int key) {
    pthread_mutex_lock(&set->lock);

    for (int i = 0; i < set->size; i++) {
        if (set->records[i].key == key) {
            Record temp = set->records[set->size - 1];
            set->records[i] = temp;
            set->size--;
            break;
        }
    }

    pthread_mutex_unlock(&set->lock);
}

// Function to serialize the record set to disk
void record_set_serialize(RecordSet* set, const char* filename) {
    FILE* file = fopen(filename, "wb");

    if (file != NULL) {
        fwrite(&set->size, sizeof(size_t), 1, file);
        for (int i = 0; i < set->size; i++) {
            fwrite(&set->records[i], sizeof(Record), 1, file);
        }
        fclose(file);
    }
}

// Function to deserialize the record set from disk
RecordSet* record_set_deserialize(const char* filename) {
    RecordSet* set = (RecordSet*) malloc(sizeof(RecordSet));
    FILE* file = fopen(filename, "rb");

    if (file != NULL) {
        fread(&set->size, sizeof(size_t), 1, file);
        set->records = (Record*) malloc(set->size * sizeof(Record));
        for (int i = 0; i < set->size; i++) {
            fread(&set->records[i], sizeof(Record), 1, file);
        }
        fclose(file);

        return set;
    }

    return NULL;
}

// Function to log changes to the record set
void record_set_log(RecordSet* set, const char* message) {
    // Implement logging mechanism here
}
