class UserSession {
public:
    int sessionId;
    std::string userName;
    long lastLoginTime;
    long expirationTimestamp;

    // Constructor
    UserSession(int session_id, const std::string& user_name, long login_time, long exp_timestamp) 
        : sessionId(session_id), userName(user_name), lastLoginTime(login_time), expirationTimestamp(exp_timestamp) {}
};

class SessionManager {
private:
    std::vector<UserSession> sessions;
    std::mutex sessionMutex;

public:
    // Add a new session
    void addSession(int session_id, const std::string& user_name, long login_time, long exp_timestamp) {
        UserSession new_session(session_id, user_name, login_time, exp_timestamp);
        {
            std::lock_guard<std::mutex> lock(sessionMutex);
            sessions.push_back(new_session);
        }
    }

    // Update an existing session
    void updateSession(int session_id, const std::string& user_name, long login_time, long exp_timestamp) {
        for (UserSession& session : sessions) {
            if (session.sessionId == session_id) {
                {
                    std::lock_guard<std::mutex> lock(sessionMutex);
                    session.userName = user_name;
                    session.lastLoginTime = login_time;
                    session.expirationTimestamp = exp_timestamp;
                }
                return;
            }
        }
    }

    // Expire a session
    void expireSession(int session_id) {
        for (UserSession& session : sessions) {
            if (session.sessionId == session_id && session.expirationTimestamp <= time(nullptr)) {
                {
                    std::lock_guard<std::mutex> lock(sessionMutex);
                    auto it = std::remove_if(sessions.begin(), sessions.end(), [session_id](const UserSession& s) { return s.sessionId == session_id; });
                    sessions.erase(it, sessions.end());
                }
                return;
            }
        }
    }

