typedef enum { INFO, WARNING, ERROR } Severity;

typedef struct {
    int timestamp;
    char* message;
    Severity severity;
} logEvent;

void manageLogEvents(logEvent** logEvents, int* lastTimestamps, int size) {
    // Dynamic memory allocation for the arrays
    logEvent** newLogEvents = realloc(logEvents, sizeof(logEvent*) * (size + 1));
    if (newLogEvents == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }
    logEvents = newLogEvents;

    int* newLastTimestamps = realloc(lastTimestamps, sizeof(int) * (size + 1));
    if (newLastTimestamps == NULL) {
        printf("Memory allocation failed.\n");
        free(logEvents);
        return;
    }
    lastTimestamps = newLastTimestamps;

    // Resize the arrays as needed
    for (int i = size; i > 0; --i) {
        logEvent* logEvent = &logEvents[i - 1];
        int timestamp = logEvent->timestamp;
        if (i < size + 1 && timestamp != lastTimestamps[i]) {
            // Move the current event to the new position
            memmove(&logEvents[i], &logEvents[i - 1], sizeof(logEvent));
            memmove(lastTimestamps + i, lastTimestamps + i - 1, sizeof(int));

            logEvent = &logEvents[i - 1];
        }
        // Adjust the timestamp and message of the moved event
        logEvent->timestamp -= 1;
    }

    // Add a new event to the end of the array
    logEvent* newLogEvent = (logEvent*)malloc(sizeof(logEvent));
    if (newLogEvent == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }
    strcpy(newLogEvent->message, "New message");
    newLogEvent->timestamp = size + 1;
    newLogEvent->severity = ERROR;

    logEvents[size] = newLogEvent;
    lastTimestamps[size] = newLogEvent->timestamp;
}

int main() {
    // Initialize the arrays
    int size = 0;
    logEvent* logEvents = NULL;
    int* lastTimestamps = NULL;

    while (1) {
        // Read a list of log messages and timestamps from standard input
        char line[1024];
        fgets(line, sizeof(line), stdin);

        if (line[0] == 'q') {
            break;
        }

        // Handle the addition of new log events to an existing array
        manageLogEvents(&logEvents, lastTimestamps, size);
    }

    // Serialize the data structure to a file for persistence
    FILE* file = fopen("log_events.txt", "wb");
    if (file == NULL) {
        printf("File opening failed.\n");
        return;
    }
    fwrite(logEvents, sizeof(logEvent), size, file);
    fclose(file);

    // Deserialize the data structure back into memory
    file = fopen("log_events.txt", "rb");
    if (file == NULL) {
        printf("File opening failed.\n");
        return;
    }
    logEvents = (logEvent*)malloc(sizeof(logEvent) * size);
    fread(logEvents, sizeof(logEvent), size, file);
    fclose(file);

    // Filter and print log events with a severity level of "ERROR"
    for (int i = 0; i < size; ++i) {
        if (logEvents[i].severity == ERROR) {
            printf("%d: %s\n", logEvents[i].timestamp, logEvents[i].message);
        }
    }

    // Calculate the total number of log events
    int totalLogEvents = size;
    printf("Total log events: %d\n", totalLogEvents);

    return 0;
}
