// Define a record structure
typedef struct {
    long offset;
    int key;
    int value;
} Record;

// Define a hash table with dynamic resizing and thread safety
typedef struct {
    Record** records;
    int capacity;
    int size;
    pthread_mutex_t mutex;
} HashTable;

HashTable* create_hash_table(int initial_capacity) {
    HashTable* ht = (HashTable*)malloc(sizeof(HashTable));
    ht->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    ht->capacity = initial_capacity;
    ht->size = 0;
    pthread_mutex_init(&ht->mutex, NULL);
    return ht;
}

void resize_hash_table(HashTable* ht, int new_capacity) {
    Record** new_records = (Record**)realloc(ht->records, new_capacity * sizeof(Record*));
    ht->capacity = new_capacity;
    pthread_mutex_lock(&ht->mutex);
    // Rehash all existing records
    for (int i = 0; i < ht->size; i++) {
        int index = ht->records[i]->key % ht->capacity;
        new_records[index] = ht->records[i];
    }
    free(ht->records);
    ht->records = new_records;
    pthread_mutex_unlock(&ht->mutex);
}

void insert_record(HashTable* ht, long offset, int key, int value) {
    Record* record = (Record*)malloc(sizeof(Record));
    record->offset = offset;
    record->key = key;
    record->value = value;
    pthread_mutex_lock(&ht->mutex);
    if (ht->size >= ht->capacity * 0.75) {
        resize_hash_table(ht, ht->capacity * 2);
    }
    int index = key % ht->capacity;
    record->next = ht->records[index];
    ht->records[index] = record;
    ht->size++;
    pthread_mutex_unlock(&ht->mutex);
}

void remove_record(HashTable* ht, long offset) {
    // Find and remove the record
    pthread_mutex_lock(&ht->mutex);
    for (int i = 0; i < ht->capacity; i++) {
        Record* current = ht->records[i];
        while (current != NULL) {
            if (current->offset == offset) {
                // Remove and free the record
                Record* next = current->next;
                free(current);
                ht->records[i] = next;
                break;
            }
            current = current->next;
        }
    }
    pthread_mutex_unlock(&ht->mutex);
}

// Serialize records to disk
void serialize_records(HashTable* ht, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file != NULL) {
        for (int i = 0; i < ht->capacity; i++) {
            Record* current = ht->records[i];
            while (current != NULL) {
                fwrite(&current->offset, sizeof(long), 1, file);
                fwrite(&current->key, sizeof(int), 1, file);
                fwrite(&current->value, sizeof(int), 1, file);
                current = current->next;
            }
        }
        fclose(file);
    }
}

// Deserialize records from disk
HashTable* deserialize_records(const char* filename) {
    HashTable* ht = create_hash_table(16);
    FILE* file = fopen(filename, "rb");
    if (file != NULL) {
        Record* record = NULL;
        while (fread(&record->offset, sizeof(long), 1, file) == 1) {
            fread(&record->key, sizeof(int), 1, file);
            fread(&record->value, sizeof(int), 1, file);
            // Add the record to the hash table
        }
        fclose(file);
    }
    return ht;
}
