// Custom memory pool structure
typedef struct {
    void** buffer;
    size_t capacity;
    size_t used;
} MemoryPool;

// Function to initialize and populate record structures with random integer values
void initRecords(MemoryPool* mp, int numRecords) {
    srand(time(NULL)); // Initialize random seed using local stack variable

    for (int i = 0; i < numRecords; i++) {
        Record* rec = mp->buffer[i];
        rec->val = rand() % 100; // Random integer value within range [0, 99]
        rec->offset = (long)i;
        rec->key = i; // Simple key initialization
    }
}

// Function to search for a specific record by its key using a hash table
Record* searchByKey(MemoryPool* mp, int targetKey) {
    Record* rec;
    unsigned long hash = targetKey % mp->capacity;

    for (int i = 0; i < mp->used; i++) {
        rec = mp->buffer[hash];
        if (rec && rec->key == targetKey)
            return rec;
        hash = (hash + 1) % mp->capacity;
    }

    return NULL;
}

// Function to serialize the collection of record structures to a file
void serializeRecords(MemoryPool* mp, const char* filename) {
    FILE* f = fopen(filename, "wb");
    if (!f)
        return; // Handle error

    size_t numRecs = mp->used;
    fwrite(&numRecs, sizeof(size_t), 1, f); // Write number of records
    for (int i = 0; i < numRecs; i++) {
        Record* rec = mp->buffer[i];
        fwrite(&rec->val, sizeof(int), 1, f);
        fwrite(&rec->offset, sizeof(long), 1, f);
        fwrite(&rec->key, sizeof(int), 1, f); // Serialize record
    }
    fclose(f);
}

// Function to safely release all allocated resources
void cleanup(MemoryPool* mp) {
    for (int i = 0; i < mp->used; i++) {
        free(mp->buffer[i]);
    }
    free(mp->buffer);
}

// Function to initialize and configure the memory pool with a specified capacity
MemoryPool* initMemoryPool(size_t capacity) {
    MemoryPool* mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->buffer = (void**)malloc(capacity * sizeof(void*));
    mp->capacity = capacity;
    mp->used = 0;
    return mp;
}

