    int key;
    long offset;
} Record;

// Function prototype for dynamic memory allocation
void* malloc_checked(size_t size);

// Global variables
Record** records = NULL;
int num_records = 0;
int max_records = 10; // Initial maximum number of records
long cumulative_offset = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Add a new record to the collection
void add_record(int key, long offset) {
    Record* new_record = (Record*)malloc_checked(sizeof(Record));
    new_record->key = key;
    new_record->offset = offset;
    records = realloc(records, (num_records + 1) * sizeof(Record*));
    records[num_records] = new_record;
    cumulative_offset += offset;
    num_records++;
}

// Remove a record from the collection
void remove_record(int key) {
    for (int i = 0; i < num_records; i++) {
        if (records[i]->key == key) {
            free(records[i]);
            memmove(&records[i], &records[i + 1], (num_records - i - 1) * sizeof(Record*));
            num_records--;
            break;
        }
    }
}

// Function to manage dynamic memory allocation and initialization
void* malloc_checked(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    return ptr;
}

// Function to reallocate memory when the number of records exceeds the threshold
void re_allocate() {
    if (num_records >= max_records * 2) {
        max_records *= 2;
        records = realloc(records, max_records * sizeof(Record*));
    }
}
