#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the maximum number of records
#define MAX_RECORDS 10000

// Define the structure for a record
typedef struct {
    int key;
    long offset;
} Record;

// Define the data store structure
typedef struct {
    Record* records;
    int size;
    pthread_mutex_t mutex;
    FILE* logFile;
} DataStore;

// Initialize the data store
DataStore* init_data_store() {
    DataStore* ds = (DataStore*)malloc(sizeof(DataStore));
    ds->records = (Record*)malloc(MAX_RECORDS * sizeof(Record));
    ds->size = 0;
    pthread_mutex_init(&ds->mutex, NULL);
    return ds;
}

// Add a record to the data store
void add_record(DataStore* ds, int key, long offset) {
    pthread_mutex_lock(&ds->mutex);

    // Resize the array if it's full
    if (ds->size >= MAX_RECORDS) {
        Record* newRecords = (Record*)realloc(ds->records, (MAX_RECORDS * 2) * sizeof(Record));
        ds->records = newRecords;
        ds->size *= 2;
    }

    // Add the record to the end of the array
    ds->records[ds->size].key = key;
    ds->records[ds->size].offset = offset;
    ds->size++;

    pthread_mutex_unlock(&ds->mutex);
}

// Serialize the data store and write it to disk
void serialize_data_store(DataStore* ds) {
    FILE* file = fopen("datastore.bin", "wb");
    if (file == NULL) {
        perror("Error opening file");
        return;
    }

    // Compress the data using zlib
    int compressionLevel = 6; // Adjust this value for different compression levels
    int ret;
    uLongleng = sizeof(Record) * ds->size;
    byte* buffer = (byte*)malloc((leng + 12) * sizeof(byte));
    Bytef outBuff = (Bytef)buffer;
    deflateInit2(&zStream, compressionLevel, Z_DEFLATED, 8, 15, 0);
    ret = deflate(&zStream, Z_NOCOMPRESS, &outBuff, &leng);

    if (ret != Z_OK) {
        perror("Error compressing data");
        return;
    }

    // Write the compressed data to disk
    fwrite(buffer, sizeof(byte), leng, file);
    fclose(file);

    free(buffer);
}

// Deserialize the data store from disk
void deserialize_data_store(DataStore* ds) {
    FILE* file = fopen("datastore.bin", "rb");
    if (file == NULL) {
        perror("Error opening file");
        return;
    }

    // Decompress the data using zlib
    int ret;
    uLongleng = 0;
    byte* buffer = (byte*)malloc(MAX_RECORDS * sizeof(Record));
    Bytef inBuff = (Bytef)buffer;
    inflateInit2(&zStream, Z_DEFLATED, 8, 15, 0);
    ret = inflate(&zStream, Z_NOCOMPRESS, &inBuff, &leng);

    if (ret != Z_OK) {
        perror("Error decompressing data");
        return;
    }

    // Deserialize the data
    ds->size = leng / sizeof(Record);
    for (int i = 0; i < ds->size; i++) {
        ds->records[i].key = ((byte*)buffer)[i * sizeof(byte)];
        ds->records[i].offset = (((byte*)buffer) + (sizeof(byte))) + (i * sizeof(byte));
    }

    free(buffer);
}

// Log an event
void log_event(const char* message) {
    if (ds->logFile == NULL) {
        ds->logFile = fopen("datastore.log", "wb");
    }
    fprintf(ds->logFile, "%s\n", message);
}

int main() {
    DataStore* ds = init_data_store();
    add_record(ds, 1, 1000);
    add_record(ds, 2, 2000);
    serialize_data_store(ds);
    deserialize_data_store(ds);

    // Clean up
    pthread_mutex_destroy(&ds->mutex);
    free(ds->records);
    fclose(ds->logFile);
    return 0;
}
