// Function to add a record to the system
void addRecord(DataManagementSystem* dms, long offset, int key, int value) {
    if (dms->size >= dms->capacity) {
        // Resize the array if it's full
        dms->records = (Record**)realloc(dms->records, 2 * dms->capacity * sizeof(Record*));
        dms->capacity *= 2;
    }
    Record* record = (Record*)malloc(sizeof(Record));
    record->offset = offset;
    record->key = key;
    record->value = value;
    dms->records[dms->size] = record;
    dms->size++;
}

