Record* getRecord(DataManagementSystem* dms, long offset) {
    pthread_mutex_lock(&dms->lock);
    for (int i = 0; i < dms->size; i++) {
        if (dms->records[i]->offset == offset) {
            Record* record = dms->records[i];
            pthread_mutex_unlock(&dms->lock);
            return record;
        }
    }
    pthread_mutex_unlock(&dms->lock);
    return NULL;
}

