#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int key;
    long offset;
    short value;
} record;

void expandGraphStructure(int maxRecords, int minKey, int maxKey) {
    int i, j, keyCount = 0;
    long *offsets;
    int *keys;
    record *records;
    int recordIndex;

    // Determine the number of new records to add
    int numNewRecords = (maxRecords - 10000) / 2 + 1;

    // Allocate memory for offsets and keys arrays
    offsets = (long *)malloc((numNewRecords + 1) * sizeof(long));
    keys = (int *)malloc((numNewRecords + 1) * sizeof(int));

    // Initialize offset values
    for (i = 0; i < numNewRecords; i++) {
        offsets[i] = rand() % ((maxKey - minKey) + 1) + minKey;
    }
    offsets[numNewRecords] = 0;

    // Allocate memory for the records array
    recordIndex = 10000;
    records = (record *)malloc((recordIndex + numNewRecords) * sizeof(record));

    // Initialize and copy existing data to new arrays
    if (keyCount > 0) {
        j = 0;
        for (i = 0; i < keyCount; i++) {
            records[recordIndex - 1].key = keys[j];
            records[recordIndex - 1].offset = offsets[j];
            records[recordIndex - 1].value = rand() % ((maxKey - minKey) + 1) + minKey;
            j++;
        }
    }

    // Update the record count
    keyCount += numNewRecords;

    // Free memory allocated for previous keys and offsets arrays
    if (keys != NULL)
        free(keys);
    if (offsets != NULL)
        free(offsets);

    printf("Graph structure expanded to %d records.\n", keyCount);
}
