void printErrorMetrics(metric_t* metrics, int metricCount) {
    for(int i = 0; i < metricCount; i++) {
        if(metrics[i].status == ERROR) {
            printf("Metric %d has error: %.2f at timestamp %d\n", i+1, metrics[i].value, metrics[i].timestamp);
        }
    }
}

// Function to calculate the average metric value
double calculateAverageMetricValue(metric_t* metrics, int metricCount) {
    double sum = 0.0;
    for(int i = 0; i < metricCount; i++) {
        sum += metrics[i].value;
    }
    return sum / metricCount;
}

