    scanf("%d", &metricCount);

    // Initialize arrays
    int* timestamps = (int*)malloc(sizeof(int) * metricCount);
    double* values = (double*)malloc(sizeof(double) * metricCount);
    metric_t* metrics = (metric_t*)malloc(sizeof(metric_t) * metricCount);

    // Process and manage metrics
    processAndManageMetrics(&metricCount, &timestamps, &values);

    // Filter and print error metrics
    printErrorMetrics(metrics, metricCount);

    // Calculate average metric value
    double averageValue = calculateAverageMetricValue(metrics, metricCount);
    printf("Average Metric Value: %.2f\n", averageValue);

