Records* initialize_records(int num_records) {
    Records* records = malloc(sizeof(Records));
    if (!records) return NULL; // Handle memory allocation failure

    records->data = malloc(num_records * sizeof(Record));
    if (!records->data) {
        free(records);
        return NULL;
    }

    records->capacity = num_records;
    records->used = 0;
    records->last_accessed = calloc(num_records, sizeof(size_t));

    for (int i = 0; i < num_records; i++) {
        Record* record = &records->data[i];
        record->key = rand() % 10000; // Initialize with a random value
        record->offset = (long)rand();
    }

    return records;
}

void serialize_records(Records* records, FILE* file) {
    fwrite(&records->capacity, sizeof(size_t), 1, file);
    fwrite(&records->used, sizeof(size_t), 1, file);

    for (size_t i = 0; i < records->used; i++) {
        Record record = records->data[i];
        fwrite(&record.key, sizeof(int), 1, file);
        fwrite(&record.offset, sizeof(long), 1, file);
    }
}

