typedef struct {
    int key;
    long offset;
} Record;

Record* record_manager_init(size_t capacity) {
    Record* records = (Record*)malloc(capacity * sizeof(Record));
    size_t last_accessed_index = -1;
    return (Record*){records, last_accessed_index};
}

void record_manager_insert(Record* self, int key, long offset) {
    if (self->last_accessed_index == -1 || key != self->records[self->last_accessed_index].key) {
        for (size_t i = 0; i < self->capacity; ++i) {
            if (!self->records[i].key) {
                self->records[i].key = key;
                self->records[i].offset = offset;
                self->last_accessed_index = i;
                return;
            }
        }
    } else {
        self->records[self->last_accessed_index].offset = offset;
    }
}

void record_manager_serialize(Record* self, FILE* file) {
    fwrite(&self->capacity, sizeof(size_t), 1, file);
    fwrite(self->records, sizeof(Record), self->capacity, file);
    fwrite(&self->last_accessed_index, sizeof(size_t), 1, file);
}

void record_manager_deserialize(Record* self, FILE* file) {
    fread(&self->capacity, sizeof(size_t), 1, file);
    self->records = (Record*)malloc(self->capacity * sizeof(Record));
    fread(self->records, sizeof(Record), self->capacity, file);
    fread(&self->last_accessed_index, sizeof(size_t), 1, file);
}

void record_manager_log_event(FILE* log_file, const char* event) {
