void evict_least_recently_used() {
    int i, min_index = -1, min_time = 0;
    time_t current_time = time(NULL);

    pthread_mutex_lock(&lock);
    for (i = 0; i < num_records; i++) {
        if (index[i].last_accessed < min_time || min_index == -1) {
            min_index = i;
            min_time = index[i].last_accessed;
        }
    }

    // evict record
    Record* temp = records + min_index * RECORD_SIZE;
    memmove(records + min_index * RECORD_SIZE, records + (min_index + 1) * RECORD_SIZE, (num_records - min_index - 1) * RECORD_SIZE);
    num_records--;

    pthread_mutex_unlock(&lock);

    // update index
    for (i = min_index; i < num_records; i++) {
        index[i].last_accessed = current_time;
    }
}

