void init_data(int num_offsets, int num_keys) {
    if (num_offsets > 10000 || num_keys > 10000) {
        printf("Error: Array sizes exceed maximum allowed.\n");
        exit(1);
    }

    // Allocate memory for offset and key arrays
    long *offsets = (long *)malloc(num_offsets * sizeof(long));
    int *keys = (int *)malloc(num_keys * sizeof(int));

    if (!offsets || !keys) {
        printf("Error: Memory allocation failed.\n");
        exit(1);
    }

    // Initialize offset and key arrays
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = i;
    }
    for (int j = 0; j < num_keys; j++) {
        keys[j] = j;
    }

    // Allocate memory for record array
    record_t *records = (record_t *)malloc(num_keys * sizeof(record_t));

    if (!records) {
        printf("Error: Memory allocation failed.\n");
        exit(1);
    }

    // Initialize records with random values
    for (int i = 0; i < num_keys; i++) {
        int val;
        do {
            val = rand() % 10000;
        } while (val % 2 == 0); // Ensure unique values
        records[i].value = val;
    }

    // Log initialization process and statistics
    printf("Initialization complete.\n");
    printf("Random value range: 0-9999\n");
    printf("Number of unique values generated: %d\n", num_keys);

    // Export initialized data to file (optional)
    if (num_offsets > 100 && num_keys < 10000) {
        FILE *fp = fopen("initialized_data.csv", "w");
        if (!fp) {
            printf("Error: File opening failed.\n");
            exit(1);
        }
        for (int i = 0; i < num_keys; i++) {
            fprintf(fp, "%d,%d\n", keys[i], records[i].value);
        }
        fclose(fp);
    }

    // Clean up memory allocations
    free(offsets);
    free(keys);
    free(records);

    return;
}
