typedef enum {
    SUCCESS,
    ERROR,
    WARNING
} Status;

typedef struct {
    double value;
    int timestamp;
    Status status;
} Metric;

void processAndManageMetrics(Metric** metrics, size_t* metricsCount) {
    // Initialize data structures
    *metrics = (Metric*)malloc(1 * sizeof(Metric));
    *metricsCount = 0;
    size_t maxMetrics = 1000000; // Maximum number of metrics

    Metric* timestamps = (Metric*)malloc(maxMetrics * sizeof(Metric));
    double* values = (double*)malloc(maxMetrics * sizeof(double));

    // Allocate memory for the first metric
    if (*metricsCount < maxMetrics) {
        (*metrics)++*metricsCount;
    } else {
        size_t newMaxMetrics = *metricsCount * 2;
        Metric* newTimestamps = (Metric*)realloc(timestamps, newMaxMetrics * sizeof(Metric));
        double* newValueValues = (double*)realloc(values, newMaxMetrics * sizeof(double));

        // Update the pointers
        timestamps = newTimestamps;
        values = newValueValues;
        maxMetrics = newMaxMetrics;
    }

    // Read and process metrics from standard input
    while (true) {
        int timestamp;
        double value;

        // Read metric data
        scanf("%lf %d", &value, &timestamp);

        // Check for end of file
        if (feof(stdin)) break;

        // Add the new metric to the array
        size_t idx = *metricsCount;
        (*metrics)[idx].value = value;
        (*metrics)[idx].timestamp = timestamp;

        // Update timestamps array
        if (!timestamps[idx].timestamp) {
            timestamps[idx].timestamp = timestamp;
        }

        // Increment metrics count
        (*metricsCount)++;
    }
}

// Function to filter and print metrics with a status of "ERROR"
void printErrorMetrics(Metric** metrics, size_t metricsCount) {
    for (size_t i = 0; i < metricsCount; i++) {
        if ((*metrics)[i].status == ERROR) {
            printf("Timestamp: %d, Value: %.2lf\n", (*metrics)[i].timestamp, (*metrics)[i].value);
        }
    }
}

// Function to calculate the average metric value
double calculateAverageMetricValue(Metric** metrics, size_t metricsCount) {
    double sum = 0.0;
    for (size_t i = 0; i < metricsCount; i++) {
        sum += (*metrics)[i].value;
    }
    return sum / metricsCount;
}

int main() {
    // Initialize the data structure
    Metric* metrics = NULL;
    size_t metricsCount = 0;

    processAndManageMetrics(&metrics, &metricsCount);

    // Print error metrics
    printErrorMetrics(&metrics, metricsCount);

    // Calculate and print average metric value
    double avgValue = calculateAverageMetricValue(&metrics, metricsCount);
    printf("Average Metric Value: %.2lf\n", avgValue);

    return 0;
}

