#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the maximum number of records
#define MAX_RECORDS 10000

// Define the structure for data records
typedef struct {
    long offset;
    int key;
    int value;
} record;

// Define the structure for data management
typedef struct {
    record *records;
    int keys[MAX_RECORDS];
    long offsets[MAX_RECORDS];
    pthread_mutex_t mutex;
    int last_accessed_index;
} dynamic_data_management;

// Function to create a new data management structure
dynamic_data_management* dynamicDataManagementCreate() {
    dynamic_data_management* dd = (dynamic_data_management*)malloc(sizeof(dynamic_data_management));
    dd->records = (record*)calloc(MAX_RECORDS, sizeof(record));
    dd->keys = (int*)calloc(MAX_RECORDS, sizeof(int));
    dd->offsets = (long*)calloc(MAX_RECORDS, sizeof(long));
    pthread_mutex_init(&dd->mutex, NULL);
    dd->last_accessed_index = -1;
    return dd;
}

// Function to add a new record with unique key
void dynamicDataManagementAdd(dynamic_data_management* dd, int key, int value) {
    if (dd->last_accessed_index >= MAX_RECORDS) {
        // Resize the arrays and records when necessary
        MAX_RECORDS *= 2;
        dd->records = (record*)realloc(dd->records, MAX_RECORDS * sizeof(record));
        dd->keys = (int*)realloc(dd->keys, MAX_RECORDS * sizeof(int));
        dd->offsets = (long*)realloc(dd->offsets, MAX_RECORDS * sizeof(long));
    }

    pthread_mutex_lock(&dd->mutex);
    for (int i = 0; i <= dd->last_accessed_index; i++) {
        if (dd->keys[i] == key) {
            // Key already exists
            pthread_mutex_unlock(&dd->mutex);
            return;
        }
    }

    // Add the new record with unique key
    dd->records[dd->last_accessed_index + 1].key = key;
    dd->records[dd->last_accessed_index + 1].value = value;
    dd->keys[dd->last_accessed_index + 1] = key;
    dd->offsets[dd->last_accessed_index + 1] = (long)(dd->last_accessed_index + 1);
    dd->last_accessed_index++;

    pthread_mutex_unlock(&dd->mutex);
}

// Function to serialize the data structure to a file
void dynamicDataManagementSerialize(dynamic_data_management* dd, char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        // Handle error
        return;
    }

    for (int i = 0; i <= dd->last_accessed_index; i++) {
        fwrite(&dd->records[i], sizeof(record), 1, file);
    }

    fclose(file);
}

// Function to deserialize the data structure from a file
dynamic_data_management* dynamicDataManagementDeserialize(char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        // Handle error
        return NULL;
    }

    dynamic_data_management* dd = dynamicDataManagementCreate();

    for (int i = 0; i <= MAX_RECORDS; i++) {
        record r;
        fread(&r, sizeof(record), 1, file);
        dd->records[i] = r;
    }

    fclose(file);
    return dd;
}

// Function to free all allocated memory
void dynamicDataManagementFree(dynamic_data_management* dd) {
    if (dd != NULL) {
        pthread_mutex_destroy(&dd->mutex);
        free(dd->keys);
        free(dd->offsets);
        free(dd->records);
        free(dd);
    }
}
