```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_CLIENTS 10000
#define TABLE_SIZE 1024

typedef struct {
    int *keys;
    int *values;
    int size;
} HashTable;

HashTable *hash_table = NULL;
sem_t semaphore;

void* process_stream(void* arg) {
    int client_socket = *(int*)arg;
    free(arg);

    // Receive integers from the network socket
    int integer;
    while (recv(client_socket, &integer, sizeof(int), 0) == sizeof(int)) {
        // Insert into the hash table
        insert_into_hash_table(integer);
    }

    close(client_socket);
    return NULL;
}

void insert_into_hash_table(int integer) {
    if (!hash_table) {
        hash_table = malloc(sizeof(HashTable));
        hash_table->keys = malloc(TABLE_SIZE * sizeof(int));
        hash_table->values = malloc(TABLE_SIZE * sizeof(int));
        hash_table->size = 0;

        sem_init(&semaphore, 0, 1);
    }

    int index = integer % TABLE_SIZE;
    if (hash_table->size == TABLE_SIZE) {
        // Resize the hash table
        TABLE_SIZE *= 2;
        hash_table->keys = realloc(hash_table->keys, TABLE_SIZE * sizeof(int));
        hash_table->values = realloc(hash_table->values, TABLE_SIZE * sizeof(int));

        sem_wait(&semaphore);
    }

    hash_table->keys[hash_table->size] = integer;
    hash_table->values[hash_table->size] = 1;

    sem_post(&semaphore);
}

int main() {
    int server_socket = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in server_address;
    server_address.sin_family = AF_INET;
    server_address.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &server_address.sin_addr);

    bind(server_socket, (struct sockaddr*)&server_address, sizeof(server_address));
    listen(server_socket, MAX_CLIENTS);

    while (1) {
        int client_socket = accept(server_socket, NULL, NULL);
        pthread_t thread;
        pthread_create(&thread, NULL, process_stream, &client_socket);
    }

    return 0;
}
