#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    struct tm timeStamp;
    int eventId;
    char* message;
} logEntry;

void processAndPersistLogEntries() {
    // Declare variables
    int numEntries = 0, capacity = 10000;
    logEntry* logs = (logEntry*)malloc(capacity * sizeof(logEntry));
    logEntry** lastAccessedIndices = (logEntry**)malloc(capacity * sizeof(logEntry*));
    struct tm* timestamps = (struct tm*)malloc(capacity * sizeof(struct tm));
    char** messages = (char**)malloc(capacity * sizeof(char*));

    // Initialize
    for (int i = 0; i < capacity; i++) {
        lastAccessedIndices[i] = &logs[i];
        logs[i].eventId = -1;
    }

    // Read log entries from standard input
    while (1) {
        int eventId, timeStampSecs, timeStampNanos;
        char message[1024];

        scanf("%d %ld %s", &eventId, &timeStampSecs, message);

        // Validate and filter out invalid or duplicate entries
        if (eventId < 0 || timeStampSecs < 0 || strlen(message) > 1000) {
            continue;
        }

        int logIndex = -1;

        for (int i = 0; i < numEntries; i++) {
            if (logs[i].eventId == eventId && memcmp(&logs[i].timeStamp, &timestamps[i], sizeof(struct tm)) == 0) {
                logIndex = i;
                break;
            }
        }

        if (logIndex != -1) {
            continue;
        }

        // Allocate memory for new entry
        if (numEntries >= capacity) {
            capacity *= 2;
            logs = realloc(logs, capacity * sizeof(logEntry));
            lastAccessedIndices = realloc(lastAccessedIndices, capacity * sizeof(logEntry*));
            timestamps = realloc(timestamps, capacity * sizeof(struct tm));
            messages = realloc(messages, capacity * sizeof(char*));
        }

        // Initialize new entry
        logIndex = numEntries;
        logs[logIndex].eventId = eventId;
        logs[logIndex].timeStamp = *(struct tm*)malloc(sizeof(struct tm));
        strftime((char*)logs[logIndex].timeStamp, 80, "%Y-%m-%d %H:%M:%S", localtime());
        logs[logIndex].message = strdup(message);

        // Update last accessed indices
        for (int i = logIndex; i > 0; i--) {
            lastAccessedIndices[i] = &logs[--i];
        }

        numEntries++;
    }
}

void freeMemory() {
    // Free allocated memory
    for (int i = 0; i < numEntries; i++) {
        free(logs[i].message);
        free((char*)logs[i].timeStamp);
    }
    free(lastAccessedIndices);
    free(timestamps);
    free(messages);
    free(logs);
}

void printEarliestAndLatest() {
    // Find and print the earliest and latest log entries
    int earliestIndex = -1, latestIndex = -1;
    time_t earliestTime = 0, latestTime = 0;

    for (int i = 0; i < numEntries; i++) {
        if (logs[i].timeStamp.tm_sec < earliestTime || earliestIndex == -1) {
            earliestIndex = i;
            earliestTime = logs[i].timeStamp.tm_sec;
        }

        if (logs[i].timeStamp.tm_sec > latestTime) {
            latestIndex = i;
            latestTime = logs[i].timeStamp.tm_sec;
        }
    }

    printf("Earliest log entry: %s, Event ID: %d\n", logs[earliestIndex].message, logs[earliestIndex].eventId);
    printf("Latest log entry: %s, Event ID: %d\n", logs[latestIndex].message, logs[latestIndex].eventId);
}

int main() {
    processAndPersistLogEntries();
    freeMemory();
    printEarliestAndLatest();
    return 0;
}
