// Define a struct for a dynamic array
typedef struct {
    int* data;
    size_t capacity;
    size_t size;
} DynamicArray;

// Function to create a new dynamic array with initial capacity
DynamicArray* createDynamicArray(size_t capacity) {
    DynamicArray* arr = (DynamicArray*)malloc(sizeof(DynamicArray));
    arr->data = (int*)calloc(capacity, sizeof(int));
    arr->capacity = capacity;
    arr->size = 0;
    return arr;
}

// Function to resize the dynamic array
void resizeDynamicArray(DynamicArray* arr, size_t newCapacity) {
    int* newData = (int*)calloc(newCapacity, sizeof(int));
    memcpy(newData, arr->data, arr->size * sizeof(int));
    free(arr->data);
    arr->data = newData;
    arr->capacity = newCapacity;
}

// Function to add an integer to the dynamic array
void addElement(DynamicArray* arr, int value) {
    if (arr->size >= arr->capacity / 2) {
        resizeDynamicArray(arr, arr->capacity * 2);
    }
    arr->data[arr->size++] = value;
}

// Define a struct for a hash table with dynamic resizing
typedef struct {
    DynamicArray** buckets;
    size_t numBuckets;
    size_t capacity;
} HashTable;

// Function to create a new hash table with initial capacity and number of buckets
HashTable* createHashTable(size_t capacity, size_t numBuckets) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->buckets = (DynamicArray**)calloc(numBuckets, sizeof(DynamicArray*));
    table->numBuckets = numBuckets;
    table->capacity = capacity;
    return table;
}

// Function to resize the hash table
void resizeHashTable(HashTable* table, size_t newCapacity, size_t newNumBuckets) {
    HashTable* newTable = (HashTable*)malloc(sizeof(HashTable));
    newTable->buckets = (DynamicArray**)calloc(newNumBuckets, sizeof(DynamicArray*));
    for (size_t i = 0; i < newNumBuckets; i++) {
        newTable->buckets[i] = createDynamicArray(newCapacity / newNumBuckets);
    }
    newTable->numBuckets = newNumBuckets;
    newTable->capacity = newCapacity;

    // Rehash all elements
    for (size_t i = 0; i < table->numBuckets; i++) {
        DynamicArray* bucket = table->buckets[i];
        for (size_t j = 0; j < bucket->size; j++) {
            int value = bucket->data[j];
            size_t newBucketIndex = hashFunction(value) % newTable->numBuckets;
            addElement(&newTable->buckets[newBucketIndex], value);
        }
    }

    free(table->buckets);
    table->buckets = newTable->buckets;
    table->capacity = newCapacity;
}

// Function to hash an integer and get the bucket index
size_t hashFunction(int value) {
    return value % 127; // Simple hash function for demonstration purposes
}

