    // Process each socket
    for (int i = 0; i < numSockets; i++) {
        SocketData* data = &socketData[i];
        while (data->sock > -1) {
            int value;
            // Read integer from socket...
            addElement(&table->buckets[hashFunction(data->value)], value);

            // Process other tasks...
        }
    }

    // Rehash all elements
    for (size_t i = 0; i < table->numBuckets; i++) {
        DynamicArray* bucket = table->buckets[i];
        for (size_t j = 0; j < bucket->size; j++) {
            int value = bucket->data[j];
            size_t newBucketIndex = hashFunction(value) % table->numBuckets;
            addElement(&table->buckets[newBucketIndex], value);
        }
    }

    // Free the hash table
    for (size_t i = 0; i < table->numBuckets; i++) {
        free(table->buckets[i]->data);
        free(table->buckets[i]);
    }
    free(table->buckets);
    free(table);

    // Other tasks...
}

int main() {
