#define MIN_VALUE 1
#define MAX_VALUE 1000

// Structure to represent a Node with a pointer to another Node, string key, and integer value
typedef struct Node {
    char *key;
    int value;
    struct Node *next;
} Node;

// Function to initialize the linked list and populate it with nodes
Node *initNodes(char *inputString) {
    // Initialize the head of the linked list
    Node *head = NULL;
    Node *current = NULL;

    // Generate random integers within the specified range
    srand(time(NULL));

    for (int i = 0; i < MAX_NODES && inputString[i]; i++) {
        // Extract a substring of up to 8 characters from the input string
        int keyLength = rand() % (MAX_KEY_LENGTH + 1);
        char *key = malloc((keyLength + 1) * sizeof(char));
        strncpy(key, &inputString[i], keyLength);
        key[keyLength] = '\0';

        // Generate a random integer value within the specified range
        int value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;

        Node *newNode = malloc(sizeof(Node));
        newNode->key = key;
        newNode->value = value;
        newNode->next = NULL;

        if (!head) {
            head = newNode;
        } else {
            current->next = newNode;
        }
        current = newNode;
    }

    // Ensure no two consecutive nodes share the same substring key
    Node *prevNode = head;
    while (prevNode && prevNode->next) {
        if (!strcmp(prevNode->key, prevNode->next->key)) {
            free(prevNode->next->key);
            free(prevNode->next);
            prevNode->next = NULL;
        } else {
            prevNode = prevNode->next;
        }
    }

    return head;
}

// Function to traverse the linked list and print node details
void traverseNodes(Node *head) {
    Node *current = head;
    while (current) {
        printf("Key: %s, Value: %d\n", current->key, current->value);
        free(current->key);
        current = current->next;
    }
}

// Function to search for a node by its substring key and return its integer value
int searchNode(Node *head, char *targetKey) {
    Node *current = head;
    while (current && strcmp(current->key, targetKey)) {
        current = current->next;
    }

    if (!current) {
        return -1;
    } else {
        free(targetKey);
        return current->value;
    }
}

// Function to log activity to a file for auditing purposes
void logActivity(char *logMessage) {
    FILE *logFile = fopen("activity.log", "a");
    fprintf(logFile, "%s\n", logMessage);
    fclose(logFile);
}

int main() {
    // Initialize the linked list with nodes from an input string
    Node *head = initNodes("exampleinputstring");

    // Traverse and print node details
    traverseNodes(head);

    // Search for a node by its substring key
    char *targetKey = "targetkey";
    int targetValue = searchNode(head, targetKey);

    if (targetValue != -1) {
        printf("Found node with key '%s' and value %d.\n", targetKey, targetValue);
    } else {
        printf("Node not found.\n");
    }

    // Log activity
    logActivity("Completed node initialization, traversal, and search.");

    return 0;
}

