#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>

// Define the 'item' structure
typedef struct {
    int id;
    bool status;
    char* data;
} item_t;

// Define the 'collection' structure to manage items
typedef struct {
    item_t* items;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} collection_t;

// Initialize a new collection with an initial capacity of 10 items
collection_t* collection_create() {
    collection_t* col = (collection_t*)malloc(sizeof(collection_t));
    col->items = (item_t*)calloc(10, sizeof(item_t));
    col->capacity = 10;
    col->size = 0;
    pthread_mutex_init(&col->mutex, NULL);
    return col;
}

// Add a new item to the collection
bool collection_add(collection_t* col, int id, const char* data) {
    if (col->size == col->capacity) {
        // Reallocate memory with double the capacity when full
        col->items = (item_t*)realloc(col->items, sizeof(item_t) * (col->capacity *= 2));
    }
    item_t* new_item = &col->items[col->size++];
    new_item->id = id;
    new_item->status = false;
    new_item->data = (char*)malloc(strlen(data) + 1);
    strcpy(new_item->data, data);
    return true;
}

// Retrieve an item by ID from the collection
item_t* collection_get(collection_t* col, int id) {
    pthread_mutex_lock(&col->mutex);
    for (size_t i = 0; i < col->size; i++) {
        if (col->items[i].id == id) {
            pthread_mutex_unlock(&col->mutex);
            return &col->items[i];
        }
    }
    pthread_mutex_unlock(&col->mutex);
    return NULL;
}

// Release resources and free memory when done
void collection_destroy(collection_t* col) {
    for (size_t i = 0; i < col->size; i++) {
        if (col->items[i].data != NULL) {
            free(col->items[i].data);
        }
    }
    free(col->items);
    pthread_mutex_destroy(&col->mutex);
    free(col);
}

// Example usage
int main() {
    collection_t* col = collection_create();

    // Add items to the collection
    collection_add(col, 1, "Data for item 1");
    collection_add(col, 2, "Data for item 2");
    collection_add(col, 3, "Data for item 3");

    // Retrieve an item by ID
    item_t* retrieved_item = collection_get(col, 2);
    if (retrieved_item != NULL) {
        printf("Retrieved item: %d - '%s'\n", retrieved_item->id, retrieved_item->data);
    } else {
        printf("Item not found\n");
    }

    // Release resources
    collection_destroy(col);
    return 0;
}

