int insertEntry(struct List* list, char* key, Value* value) {
    if (list->size >= list->capacity / 2) {
        // Resize the list when it reaches half its capacity
        int newCapacity = list->capacity + (list->capacity >> 1);
        Entry** newEntries = (Entry**)realloc(list->entries, newCapacity * sizeof(Entry*));
        if (!newEntries) return -1; // Handle memory allocation failure
        list->entries = newEntries;
        list->capacity = newCapacity;
    }
    Entry* entry = (Entry*)malloc(sizeof(Entry));
    if (!entry) return -1; // Handle memory allocation failure
    entry->key = key;
    entry->value = value;
    entry->timestamp = time(NULL);
    list->entries[list->size++] = entry;
    return 0;
}

