// Define a struct to manage memory for products
typedef struct {
    int capacity;
    int size;
    Product* products;
} Products;

void products_init(Products* products, int initial_capacity) {
    products->capacity = initial_capacity;
    products->size = 0;
    products->products = (Product*)malloc(initial_capacity * sizeof(Product));
}

int products_grow(Products* products) {
    int new_capacity = products->capacity * 2;
    Product* new_products = (Product*)realloc(products->products, new_capacity * sizeof(Product));
    if (!new_products) return -1; // Allocation failure

    products->products = new_products;
    products->capacity = new_capacity;

    return 0;
}

void products_add(Products* products, double price, const char* description, int num_tags, const char** tags) {
    if (products->size >= products->capacity) {
        if (products_grow(products)) {
            printf("Error: failed to grow products array\n");
            return;
        }
    }

    Product* product = &products->products[products->size];
    product->price = price;
    product->description = strdup(description);
    product->tags_size = num_tags;
    product->tags = (char**)malloc(num_tags * sizeof(char*));
    for (int i = 0; i < num_tags; i++) {
        product->tags[i] = strdup(tags[i]);
    }
    products->size++;
}

void products_free(Products* products) {
    for (int i = 0; i < products->size; i++) {
        Product* product = &products->products[i];
        free(product->description);
        for (int j = 0; j < product->tags_size; j++) {
            free(product->tags[j]);
        }
        free(product->tags);
    }
    free(products->products);
}
