#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sys/mman.h>

typedef struct {
    long offset;
    int key;
    int value;
} record;

void* alloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL && !retry_malloc()) {
        return NULL;
    }
    return ptr;
}

int retry_malloc() {
    // Exponential backoff for transient failures
    int retries = 0;
    while (retries < MAX_RETRIES) {
        usleep(100000); // 100ms delay
        if ((ptr = malloc(size)) != NULL)
            return 1;
        retries++;
    }
    return 0;
}

void init_records(record** records, size_t size) {
    srand(time(NULL)); // Periodic reseeding for randomness

    for (size_t i = 0; i < size; i++) {
        record* r = alloc(sizeof(record));
        if (r == NULL)
            continue;

        // Unique key initialization
        r->key = i;

        // Random offset initialization with custom hash function
        r->offset = hash_function(i);

        // Random value initialization within a specified range
        r->value = rand() % MAX_VALUE + MIN_VALUE;

        records[i] = r;
    }
}

long hash_function(size_t key) {
    long result = 0;
    for (int i = 0; i < KEY_SIZE; i++) {
        // Adaptive strategy to adjust hash function parameters
        result += (key >> i) * HASH_FACTOR;
    }
    return result % OFFSET_RANGE;
}
