void serialize(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Error opening file for writing");
        return;
    }

    pthread_mutex_lock(&lock);
    fwrite(&current_capacity, sizeof(int), 1, file);
    fwrite(keys, sizeof(KeyRecord), current_capacity, file);
    fwrite(offsets, sizeof(long), current_capacity, file);
    fwrite(records, sizeof(Record), current_capacity, file);
    for (int i = 0; i < KEY_RANGE; i++) {
        fwrite(&last_accessed[i], sizeof(int), 1, file);
    }
    pthread_mutex_unlock(&lock);
    fclose(file);
}

