#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_ENTRIES 10000
#define RECORD_SIZE sizeof(struct record)
#define TIMESTAMP_FORMAT "%lld"

typedef struct {
    int value;
} struct record;

struct data_structure {
    long *offsets;
    int *keys;
    struct record **records;
    time_t *timestamps;
    int *last_accessed;
};

void resize_data_structure(struct data_structure *ds, size_t new_size) {
    ds->offsets = realloc(ds->offsets, sizeof(long) * new_size);
    ds->keys = realloc(ds->keys, sizeof(int) * new_size);
    ds->records = realloc(ds->records, sizeof(struct record *) * new_size);
    ds->timestamps = realloc(ds->timestamps, sizeof(time_t) * new_size);
    ds->last_accessed = realloc(ds->last_accessed, sizeof(int) * new_size);
}

void serialize_data_structure(struct data_structure *ds, FILE *file) {
    fwrite(&ds->offsets, sizeof(long), MAX_ENTRIES, file);
    fwrite(&ds->keys, sizeof(int), MAX_ENTRIES, file);
    for (int i = 0; i < ds->last_accessed[MAX_ENTRIES - 1]; i++) {
        struct record *record = ds->records[i];
        if (record) {
            fwrite(record, RECORD_SIZE, 1, file);
        }
    }
    fwrite(&ds->timestamps, sizeof(time_t), MAX_ENTRIES, file);
}

int deserialize_data_structure(struct data_structure *ds, FILE *file) {
    for (int i = 0; i < ds->last_accessed[MAX_ENTRIES - 1]; i++) {
        struct record *record;
        if (fread(&record, RECORD_SIZE, 1, file) != 1) {
            return -1;
        }
        ds->records[i] = record;
    }
    return 0;
}

int main() {
    // Initialize random number generator
    srand(time(NULL));

    struct data_structure ds;
    ds.offsets = malloc(sizeof(long) * MAX_ENTRIES);
    ds.keys = malloc(sizeof(int) * MAX_ENTRIES);
    ds.records = malloc(sizeof(struct record *) * MAX_ENTRIES);
    ds.timestamps = malloc(sizeof(time_t) * MAX_ENTRIES);
    ds.last_accessed = malloc(sizeof(int) * MAX_ENTRIES);

    // Initialize data structure
    for (int i = 0; i < MAX_ENTRIES; i++) {
        ds.offsets[i] = i;
        ds.keys[i] = rand() % 10000;
        struct record *record = malloc(RECORD_SIZE);
        record->value = rand() % 100;
        ds.records[i] = record;
        ds.timestamps[i] = time(NULL);
    }

    // Serialize data structure
    FILE *file = fopen("data.bin", "wb");
    serialize_data_structure(&ds, file);
    fclose(file);

    return 0;
}

