    char *email;
    int num_preferences;
    char **preferences;
} UserProfile;

typedef struct {
    pthread_mutex_t mutex;
    int size;
    UserProfile **profiles;
} UserProfiles;

void init_user_profiles(UserProfiles *up) {
    up->size = 0;
    up->profiles = NULL;
}

UserProfile *create_profile(char *username, char *email, int num_preferences, char **preferences) {
    UserProfile *profile = malloc(sizeof(UserProfile));
    profile->username = strdup(username);
    profile->email = strdup(email);
    profile->num_preferences = num_preferences;
    profile->preferences = malloc(num_preferences * sizeof(char *));
    for (int i = 0; i < num_preferences; i++) {
        profile->preferences[i] = strdup(preferences[i]);
    }
    return profile;
}

void insert_profile(UserProfiles *up, UserProfile *profile) {
    pthread_mutex_lock(&up->mutex);
    up->profiles = realloc(up->profiles, (up->size + 1) * sizeof(UserProfile *));
    up->profiles[up->size++] = profile;
    pthread_mutex_unlock(&up->mutex);
}

void delete_profile(UserProfiles *up, char *username) {
    pthread_mutex_lock(&up->mutex);
    for (int i = 0; i < up->size; i++) {
        if (strcmp(up->profiles[i]->username, username) == 0) {
            free(up->profiles[i]);
            memmove(&up->profiles[i], &up->profiles[i + 1], (up->size - i - 1) * sizeof(UserProfile *));
            up->size--;
            break;
        }
    }
    pthread_mutex_unlock(&up->mutex);
}

UserProfile *lookup_profile(UserProfiles *up, char *username) {
    pthread_mutex_lock(&up->mutex);
    for (int i = 0; i < up->size; i++) {
        if (strcmp(up->profiles[i]->username, username) == 0) {
            return up->profiles[i];
        }
    }
    pthread_mutex_unlock(&up->mutex);
    return NULL;
}

void serialize_user_profiles(UserProfiles *up, FILE *file) {
    pthread_mutex_lock(&up->mutex);
    fwrite(&up->size, sizeof(int), 1, file);
    for (int i = 0; i < up->size; i++) {
        fwrite(up->profiles[i]->username, strlen(up->profiles[i]->username) + 1, 1, file);
        fwrite(up->profiles[i]->email, strlen(up->profiles[i]->email) + 1, 1, file);
        fwrite(&up->profiles[i]->num_preferences, sizeof(int), 1, file);
        for (int j = 0; j < up->profiles[i]->num_preferences; j++) {
            fwrite(up->profiles[i]->preferences[j], strlen(up->profiles[i]->preferences[j]) + 1, 1, file);
        }
    }
    pthread_mutex_unlock(&up->mutex);
}

void deserialize_user_profiles(UserProfiles *up, FILE *file) {
