// Define the structure of a 'record'
typedef struct {
    int key;
    long offset;
} Record;

// Define the structure of the dynamic data structure
typedef struct {
    // Hash table with separate chaining for collision resolution
    unsigned int *hashTable;
    size_t hashTableSize;
    size_t loadFactorThreshold;

    // Linked list to track access sequence
    Record **accessSequence;
    size_t accessSequenceSize;
    size_t accessSequenceIndex;

    // Secondary array to maintain last accessed index of each key
    size_t *lastAccessedIndex;
} DynamicDataStructure;

// Function to initialize the dynamic data structure
DynamicDataStructure* initDynamicDataStructure(size_t hashTableSize, size_t loadFactorThreshold) {
    DynamicDataStructure* dds = (DynamicDataStructure*)malloc(sizeof(DynamicDataStructure));
    dds->hashTable = (unsigned int *)malloc(hashTableSize * sizeof(unsigned int));
    dds->hashTableSize = hashTableSize;
    dds->loadFactorThreshold = loadFactorThreshold;

    // Initialize linked list and secondary array
    dds->accessSequence = (Record **)malloc(sizeof(Record*) * 10000); // assuming max of 10,000 unique keys
    dds->accessSequenceSize = 0;
    dds->accessSequenceIndex = -1;
    dds->lastAccessedIndex = (size_t *)malloc(sizeof(size_t) * hashTableSize);

    return dds;
}

// Function to insert a new record into the dynamic data structure
void insertRecord(DynamicDataStructure* dds, int key, long offset) {
    // Calculate the hash value for the given key
    unsigned int hash = (unsigned int)(key % dds->hashTableSize);

    // Check if the key is already present in the hash table
    size_t index = hash & (dds->hashTableSize - 1);
    Record* record = (Record*)malloc(sizeof(Record));
    record->key = key;
    record->offset = offset;

    // Insert the new record into the linked list and update last accessed index
    dds->accessSequence[dds->accessSequenceIndex] = record;
    dds->lastAccessedIndex[index] = dds->accessSequenceSize++;

    if (dds->loadFactorThreshold > 0.75 && dds->loadFactorThreshold < 1.25) {
        // Resize the hash table and linked list
        resizeDynamicDataStructure(dds);
    }
}

// Function to deserialize the dynamic data structure from a file
int deserialize(DynamicDataStructure* dds, FILE* file) {
    // Read the serialized data structure from the file
    fread(&dds->hashTableSize, sizeof(size_t), 1, file);
    fread(&dds->loadFactorThreshold, sizeof(double), 1, file);

    // Initialize linked list and secondary array
    dds->accessSequence = (Record **)malloc(sizeof(Record*) * 10000); // assuming max of 10,000 unique keys
    dds->accessSequenceSize = 0;
    dds->accessSequenceIndex = -1;
    dds->lastAccessedIndex = (size_t *)malloc(sizeof(size_t) * dds->hashTableSize);

    // Read and deserialize the record data from the file
    size_t numRecords;
    fread(&numRecords, sizeof(size_t), 1, file);
    for (size_t i = 0; i < numRecords; i++) {
        Record* record = (Record*)malloc(sizeof(Record));
        fread(&record->key, sizeof(int), 1, file);
        fread(&record->offset, sizeof(long), 1, file);

        // Insert the deserialized record into the linked list
        dds->accessSequence[dds->accessSequenceIndex] = record;
        dds->lastAccessedIndex[index] = dds->accessSequenceSize++;

        if (i % 1000 == 0) {
            printf("Deserializing... (%lu/%lu)\n", i, numRecords);
        }
    }

    return 0;
}

// Function to serialize the dynamic data structure into a file
int serialize(DynamicDataStructure* dds, FILE* file) {
    // Write the serialized data structure to the file
    fwrite(&dds->hashTableSize, sizeof(size_t), 1, file);
    fwrite(&dds->loadFactorThreshold, sizeof(double), 1, file);

    // Serialize the record data from the linked list and write it to the file
    size_t numRecords = dds->accessSequenceSize;
    fwrite(&numRecords, sizeof(size_t), 1, file);
    for (size_t i = 0; i < numRecords; i++) {
        Record* record = dds->accessSequence[i];
        fwrite(&record->key, sizeof(int), 1, file);
        fwrite(&record->offset, sizeof(long), 1, file);

        if (i % 1000 == 0) {
            printf("Serializing... (%lu/%lu)\n", i, numRecords);
        }
    }

    return 0;
}

// Function to release all allocated resources when the data structure is no longer needed
void releaseResources(DynamicDataStructure* dds) {
    // Free memory for hash table and linked list
    free(dds->hashTable);
    free(dds->accessSequence);

    // Free memory for secondary array
    free(dds->lastAccessedIndex);

    // Free the dynamic data structure itself
    free(dds);
}

// Function to generate random 'offset' values within a specified range
long generateRandomOffset(long min, long max) {
    return (rand() % ((max - min + 1) * 1000)) + min;
}

// Function to track memory usage and report metrics
void trackMetrics(DynamicDataStructure* dds) {
    printf("Memory Usage: %lu bytes\n", getMemoryUsage());
    printf("Peak Memory Consumption: %lu bytes\n", getPeakMemoryConsumption());
    printf("Frequency of Resizing Operations: %lu\n", getResizeFrequency());

    // Monitor and report other metrics such as average search time and space complexity
}

int main() {
