#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define structure for database record
typedef struct {
    long offset;
    int key;
    double value;
} Record;

// Define custom data structure for efficient key lookups and value retrievals
typedef struct {
    int* keys;
    Record** records;
    int size;
} Database;

// Initialize database with initial capacity
Database* init_database(int initial_capacity) {
    Database* db = (Database*)malloc(sizeof(Database));
    db->size = 0;
    db->keys = (int*)malloc(initial_capacity * sizeof(int));
    db->records = (Record**)malloc(initial_capacity * sizeof(Record*));
    return db;
}

// Insert record into database
void insert_record(Database* db, int key, long offset, double value) {
    // Resize database if necessary
    if (db->size >= db->keys->size) {
        int new_size = db->size * 2 + 1;
        int* new_keys = (int*)realloc(db->keys, new_size * sizeof(int));
        Record** new_records = (Record**)realloc(db->records, new_size * sizeof(Record*));
        db->keys = new_keys;
        db->records = new_records;
    }

    // Insert record into database
    int idx = linear_search(db, key);
    if (idx == -1) {
        db->keys[db->size] = key;
        db->records[db->size] = (Record*)malloc(sizeof(Record));
        db->records[db->size]->offset = offset;
        db->records[db->size]->key = key;
        db->records[db->size]->value = value;
        db->size++;
    } else {
        // Update existing record
        db->records[idx]->offset = offset;
        db->records[idx]->value = value;
    }
}

// Delete record from database
void delete_record(Database* db, int key) {
    // Find record index
    int idx = linear_search(db, key);
    if (idx != -1) {
        // Shift records to fill gap
        for (int i = idx; i < db->size - 1; i++) {
            db->keys[i] = db->keys[i + 1];
            db->records[i] = db->records[i + 1];
        }
        free(db->records[db->size - 1]);
        db->size--;
    }
}

// Serialize database to file
void serialize_database(Database* db, FILE* file) {
    // Write header with database size and capacity
    fwrite(&db->size, sizeof(int), 1, file);
    fwrite(&db->keys[0], sizeof(int), 1, file);

    // Write records
    for (int i = 0; i < db->size; i++) {
        Record* record = db->records[i];
        fwrite(&record->offset, sizeof(long), 1, file);
        fwrite(&record->key, sizeof(int), 1, file);
        fwrite(&record->value, sizeof(double), 1, file);
    }
}

// Deserialize database from file
Database* deserialize_database(FILE* file) {
    int size;
    fread(&size, sizeof(int), 1, file);
    int capacity;
    fread(&capacity, sizeof(int), 1, file);

    Database* db = init_database(capacity);
    for (int i = 0; i < size; i++) {
        Record* record = (Record*)malloc(sizeof(Record));
        fread(&record->offset, sizeof(long), 1, file);
        fread(&record->key, sizeof(int), 1, file);
        fread(&record->value, sizeof(double), 1, file);
        db->records[db->size++] = record;
    }
    return db;
}

// Linear search for key
int linear_search(Database* db, int key) {
    for (int i = 0; i < db->size; i++) {
        if (db->keys[i] == key) {
            return i;
        }
    }
    return -1;
}
