// Define the structure for user profile
typedef struct {
    char* username;
    char* email;
    int numPreferences;
    char** preferences;
} UserProfile;

// Define the function to manage user profiles
UserProfile* createUserProfiles(int size) {
    UserProfile* profiles = (UserProfile*)malloc(size * sizeof(UserProfile));

    // Initialize each profile with random data
    for (int i = 0; i < size; i++) {
        profiles[i].username = (char*)malloc(16 * sizeof(char));
        profiles[i].email = (char*)malloc(32 * sizeof(char));
        int numPrefs = rand() % 10 + 1;
        profiles[i].numPreferences = numPrefs;
        profiles[i].preferences = (char**)malloc(numPrefs * sizeof(char*));

        // Generate random username and email
        sprintf(profiles[i].username, "user%d", i);
        for (int j = 0; j < 16; j++) {
            profiles[i].email[j] = 'a' + rand() % 26;
        }
        profiles[i].email[16] = '\0';

        // Generate random preferences
        char* pref = (char*)malloc(16 * sizeof(char));
        for (int j = 0; j < numPrefs; j++) {
            sprintf(pref, "pref%d", j);
            profiles[i].preferences[j] = pref;
            free(pref);
        }
    }

    return profiles;
}

// Define the function to serialize user profiles
void serializeUserProfiles(UserProfile* profiles, int size) {
    FILE* file = fopen("user_profiles.txt", "wb");

    // Write the number of profiles and each profile's data
    fwrite(&size, sizeof(int), 1, file);
    for (int i = 0; i < size; i++) {
        fwrite(profiles[i].username, sizeof(char), 16, file);
        fwrite(profiles[i].email, sizeof(char), 32, file);
        fwrite(&profiles[i].numPreferences, sizeof(int), 1, file);

        // Write each preference separately
        for (int j = 0; j < profiles[i].numPreferences; j++) {
            fwrite(profiles[i].preferences[j], sizeof(char), 16, file);
        }
    }

    fclose(file);
}

// Define the function to deserialize user profiles
UserProfile* deserializeUserProfiles() {
    FILE* file = fopen("user_profiles.txt", "rb");

    // Read the number of profiles and each profile's data
    int size;
    fread(&size, sizeof(int), 1, file);
    UserProfile* profiles = (UserProfile*)malloc(size * sizeof(UserProfile));

    for (int i = 0; i < size; i++) {
        profiles[i].username = (char*)malloc(16 * sizeof(char));
        profiles[i].email = (char*)malloc(32 * sizeof(char));
        fread(profiles[i].username, sizeof(char), 16, file);
        fread(profiles[i].email, sizeof(char), 32, file);
        fread(&profiles[i].numPreferences, sizeof(int), 1, file);

        // Read each preference separately
        profiles[i].preferences = (char**)malloc(profiles[i].numPreferences * sizeof(char*));
        for (int j = 0; j < profiles[i].numPreferences; j++) {
            char* pref = (char*)malloc(16 * sizeof(char));
            fread(pref, sizeof(char), 16, file);
            profiles[i].preferences[j] = pref;
        }
    }

    fclose(file);
    return profiles;
}

// Define the function to free allocated memory
void freeMemory(UserProfile* profiles, int size) {
    for (int i = 0; i < size; i++) {
        free(profiles[i].username);
        free(profiles[i].email);

        // Free each preference separately
        for (int j = 0; j < profiles[i].numPreferences; j++) {
            free(profiles[i].preferences[j]);
        }
        free(profiles[i].preferences);
    }
    free(profiles);
}
