['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

typedef struct Document {
    char* id;
    int priority;
    int last_accessed;
} Document;

typedef struct Node {
    Document document;
    struct Node* left;
    struct Node* right;
} Node;

typedef struct HashTable {
    size_t size;
    Node** buckets;
} HashTable;

HashTable* create_hash_table(size_t size) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->size = size;
    table->buckets = (Node**)malloc(sizeof(Node*) * size);
    for (int i = 0; i < size; i++) {
        table->buckets[i] = NULL;
    }
    return table;
}

void insert_document(HashTable* table, Document document) {
    // Hash function to determine the bucket index
    size_t index = hash(document.id, table->size);
    Node* node = (Node*)malloc(sizeof(Node));
    node->document = document;
    if (table->buckets[index] == NULL) {
        table->buckets[index] = node;
    } else {
        // Insert into the BST
        insert_bst(&node, table->buckets[index]);
    }
}

int hash(const char* id, size_t size) {
    int sum = 0;
    for (int i = 0; id[i]; i++) {
        sum += id[i];
    }
    return sum % size;
}

void insert_bst(Node** root, Node* node) {
    if (*root == NULL) {
        *root = node;
    } else if (node->document.priority < (*root)->document.priority) {
        if ((*root)->left == NULL) {
            (*root)->left = node;
        } else {
            insert_bst(&((*root)->left), node);
        }
    } else {
        if ((*root)->right == NULL) {
            (*root)->right = node;
        } else {
            insert_bst(&((*root)->right), node);
        }
    }
}

void delete_document(HashTable* table, Document document) {
    size_t index = hash(document.id, table->size);
    Node* node = table->buckets[index];
    while (node != NULL && node->document.id != document.id) {
        node = node->left ? node->left : node->right;
    }
    if (node == NULL) return; // Document not found

    // Remove from the BST
    remove_bst(&table->buckets[index], node);

    free(node);
}

void remove_bst(Node** root, Node* node) {
    if (*root == node) {
        *root = node->left ? node->left : node->right;
    } else if (node->document.priority < (*root)->document.priority) {
        remove_bst(&((*root)->left), node);
    } else {
        remove_bst(&((*root)->right), node);
    }
}

void retrieve_document(HashTable* table, Document document) {
    size_t index = hash(document.id, table->size);
    Node* node = table->buckets[index];
    while (node != NULL && node->document.id != document.id) {
        node = node->left ? node->left : node->right;
    }
    if (node == NULL) return; // Document not found

    printf("Retrieved document: %s, priority: %d\n", document.id, document.priority);
}

void serialize_data(HashTable* table, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) return;

    fwrite(&table->size, sizeof(size_t), 1, file);
    for (int i = 0; i < table->size; i++) {
        Node* node = table->buckets[i];
        while (node != NULL) {
            Document document = node->document;
            fwrite(&document.id, sizeof(char*), 1, file);
            fwrite(&document.priority, sizeof(int), 1, file);
            fwrite(&document.last_accessed, sizeof(int), 1, file);
            node = node->left ? node->left : node->right;
        }
    }

    fclose(file);
}

void deserialize_data(HashTable* table, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) return;

    fread(&table->size, sizeof(size_t), 1, file);
    table->buckets = (Node**)malloc(sizeof(Node*) * table->size);
    for (int i = 0; i < table->size; i++) {
        Node* node = NULL;
        while (node == NULL) {
            Document document;
            fread(&document.id, sizeof(char*), 1, file);
            fread(&document.priority, sizeof(int), 1, file);
            fread(&document.last_accessed, sizeof(int), 1, file);

            if (node == NULL) node = (Node*)malloc(sizeof(Node));
            node->document = document;

            table->buckets[i] = node;
        }
    }

    fclose(file);
}

int main() {
    HashTable* table = create_hash_table(1000000); // Initialize the hash table

    Document doc1 = {"doc1", 10, 1643723400};
    Document doc2 = {"doc2", 5, 1643723410};
    insert_document(table, doc1);
    insert_document(table, doc2);

    retrieve_document(table, doc1); // Retrieve a document
    retrieve_document(table, doc2);

    serialize_data(table, "data.bin"); // Serialize the data

    HashTable* table_copy = create_hash_table(1000000);
    deserialize_data(table_copy, "data.bin");

    return 0;
}
