#include <stdlib.h>
#include <stdio.h>

typedef struct {
    unsigned long key;
    long offset;
} Record;

void *safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

int generateUniqueKey(unsigned long max_key, unsigned long *keys, int len) {
    for (int i = 0; i < 10; i++) {
        unsigned long key = rand() % (max_key + 1);
        bool found = false;
        for (int j = 0; j < len; j++) {
            if (key == keys[j]) {
                found = true;
                break;
            }
        }
        if (!found) return key;
    }
    fprintf(stderr, "Warning: Unique key not found after 10 attempts\n");
    return -1;
}

void freeRecords(Record **records, int len) {
    for (int i = 0; i < len; i++) {
        free(records[i]);
    }
    free(records);
}

Record **manageRecords(int min_offset, int max_offset, unsigned long max_key, int *len) {
    Record **records = NULL;
    int allocated_len = 1;

    for (int offset = min_offset; offset <= max_offset; offset++) {
        unsigned long keys[10];
        int key_count = 0;

        while (key_count < 10) {
            unsigned long unique_key = generateUniqueKey(max_key, keys, key_count);
            if (unique_key == -1) break;
            Record *record = safe_malloc(sizeof(Record));
            record->key = unique_key;
            record->offset = offset;
            records = realloc(records, sizeof(Record *) * allocated_len + 10);
            records[allocated_len++] = record;
            keys[key_count++] = unique_key;
        }
    }

    *len = allocated_len;
    return records;
}
