#include <stdlib.h>
#include <string.h>

typedef struct {
    char* str;
    unsigned int id;
    struct node* next;
} Node;

Node* create_node(const char* str) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        return NULL;
    }
    new_node->str = strdup(str);
    if (!new_node->str) {
        free(new_node);
        return NULL;
    }
    new_node->id = 0;
    new_node->next = NULL;
    return new_node;
}

void delete_node(Node* node) {
    if (node->str) {
        free(node->str);
    }
    free(node);
}

Node* insert_node(Node** head, const char* str) {
    Node* new_node = create_node(str);
    if (!new_node) {
        return *head;
    }
    if (*head == NULL || strcmp((*head)->str, str) < 0) {
        new_node->next = *head;
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next && strcmp(current->next->str, str) < 0) {
            current = current->next;
        }
        if (!current->next || strcmp(current->next->str, str) >= 0) {
            new_node->next = current->next;
            current->next = new_node;
        } else {
            current->next = new_node;
        }
    }
    return *head;
}

Node* delete_node_by_id(Node** head, unsigned int id) {
    if (*head == NULL) {
        return *head;
    }
    if ((*head)->id == id) {
        Node* temp = *head;
        *head = (*head)->next;
        delete_node(temp);
        return *head;
    }
    Node* current = *head;
    while (current->next && current->next->id != id) {
        current = current->next;
    }
    if (current->next && current->next->id == id) {
        Node* temp = current->next;
        current->next = current->next->next;
        delete_node(temp);
        return *head;
    }
    return *head;
}

void print_list(Node* head) {
    while (head) {
        printf("%s - %u\n", head->str, head->id);
        head = head->next;
    }
}
