#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

// Metadata structure
typedef struct {
    int some_data;
} metadata_t;

// Hash table entry structure
typedef struct {
    char* key;
    metadata_t data;
} hash_entry_t;

// Hash table structure
typedef struct {
    uint32_t size;
    uint32_t capacity;
    float load_factor;
    float resize_threshold;
    hash_entry_t** entries;
    int num_entries;
    int threshold;
    int is_resizing;
    int is_logging_enabled;
    // Other metadata fields...
} hash_table_t;

// Function to create a new hash table
hash_table_t* create_hash_table(uint32_t initial_size, float max_load_factor, uint32_t resize_threshold) {
    hash_table_t* ht = (hash_table_t*)malloc(sizeof(hash_table_t));
    ht->size = initial_size;
    ht->capacity = initial_size * 2; // Initial capacity is double the size
    ht->load_factor = max_load_factor;
    ht->resize_threshold = resize_threshold;
    ht->entries = (hash_entry_t**)calloc(ht->capacity, sizeof(hash_entry_t*));
    ht->num_entries = 0;
    ht->threshold = initial_size * 3 / 4; // Initial threshold is 75% of the size
    ht->is_resizing = 0;
    ht->is_logging_enabled = 1; // Enable logging by default
    return ht;
}

// Function to resize the hash table
void resize_hash_table(hash_table_t* ht) {
    if (ht->is_resizing) return; // Avoid recursive resizing
    ht->is_resizing = 1;

    uint32_t new_size = ht->capacity * 2;
    uint32_t new_capacity = new_size * 2;
    hash_entry_t** new_entries = (hash_entry_t**)calloc(new_capacity, sizeof(hash_entry_t*));

    for (int i = 0; i < ht->size; i++) {
        hash_entry_t* entry = ht->entries[i];
        if (entry) {
            uint32_t index = hash_function(entry->key, new_size);
            while (new_entries[index]) {
                index = (index + 1) % new_size;
            }
            new_entries[index] = entry;
        }
    }

    free(ht->entries);
    ht->entries = new_entries;
    ht->size = new_size;
    ht->capacity = new_capacity;
    ht->is_resizing = 0;

    if (ht->num_entries > ht->threshold) {
        ht->threshold *= 1.5; // Increase threshold to accommodate more entries
    }
}

// Function to add an entry to the hash table
int add_entry(hash_table_t* ht, char* key, metadata_t data) {
    uint32_t index = hash_function(key, ht->size);
    while (ht->entries[index]) {
        if (strcmp(ht->entries[index]->key, key) == 0) return -1; // Entry already exists
        index = (index + 1) % ht->size;
    }
    ht->entries[index] = (hash_entry_t*)malloc(sizeof(hash_entry_t));
    ht->entries[index]->key = strdup(key);
    ht->entries[index]->data = data;
    ht->num_entries++;
    if ((float)ht->num_entries / ht->capacity > ht->load_factor) {
        resize_hash_table(ht); // Resize the hash table if load factor exceeds threshold
    }
    return 0;
}

// Function to remove an entry from the hash table
int remove_entry(hash_table_t* ht, char* key) {
    uint32_t index = hash_function(key, ht->size);
    while (ht->entries[index]) {
        if (strcmp(ht->entries[index]->key, key) == 0) {
            free(ht->entries[index]->key);
            free(ht->entries[index]);
            ht->entries[index] = NULL;
            ht->num_entries--;
            return 0; // Entry removed
        }
        index = (index + 1) % ht->size;
    }
    return -1; // Entry not found
}

// Hash function to generate unique keys
uint32_t hash_function(char* key, uint32_t size) {
    uint32_t hash = 0;
    for (int i = 0; key[i]; i++) {
        hash = (hash * 31 + key[i]) % size;
    }
    return hash;
}

// Function to log events
void log_event(hash_table_t* ht, char* message) {
    if (!ht->is_logging_enabled) return; // Skip logging if disabled

    printf("%s: Hash table has %d entries and a load factor of %.2f\n", message, ht->num_entries, (float)ht->num_entries / ht->capacity);
}

// Example usage
int main() {
    hash_table_t* ht = create_hash_table(16, 0.75, 128);
    char* key1 = "key1";
    metadata_t data1;
    // ... add entries ...

    log_event(ht, "Initial population");

    // ... remove entries ...

    log_event(ht, "After removal");
    return 0;
}
