typedef struct {
    int** keys;
    long* offsets;
    record_t** records;
    int* last_accessed;
    size_t capacity;
    size_t used;
} data_t;

// Initialize the data structure
data_t* init_data(size_t capacity) {
    data_t* d = malloc(sizeof(data_t));
    d->keys = malloc(capacity * sizeof(int *));
    d->offsets = malloc(capacity * sizeof(long));
    d->records = malloc(capacity * sizeof(record_t *));
    d->last_accessed = malloc(capacity * sizeof(int));
    d->capacity = capacity;
    d->used = 0;
    return d;
}

// Add a new record to the data structure
void add_record(data_t* d, int key, long offset, int value) {
    if (d->used >= d->capacity) {
        // Reallocate memory and update capacity
        size_t new_capacity = d->capacity * 2 + 1;
        d->keys = realloc(d->keys, new_capacity * sizeof(int *));
        d->offsets = realloc(d->offsets, new_capacity * sizeof(long));
        d->records = realloc(d->records, new_capacity * sizeof(record_t *));
        d->last_accessed = realloc(d->last_accessed, new_capacity * sizeof(int));
        d->capacity = new_capacity;
    }
    int* k = &d->keys[d->used];
    long* o = &d->offsets[d->used];
    record_t* r = &d->records[d->used];
    *k = key;
    *o = offset;
    r->value = value;
    d->last_accessed[d->used] = -1; // Mark as not accessed
    d->used++;
}

// Serialize the data structure to disk
void serialize_data(const char* filename, data_t* d) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        printf("Error opening file for writing\n");
        return;
    }
    fwrite(&d->capacity, sizeof(size_t), 1, file);
    fwrite(d->keys, sizeof(int*), d->used, file);
    fwrite(d->offsets, sizeof(long), d->used, file);
    fwrite(d->records, sizeof(record_t*), d->used, file);
    fwrite(d->last_accessed, sizeof(int), d->used, file);
    fclose(file);
}

// Deserialize the data structure from disk
data_t* deserialize_data(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        printf("Error opening file for reading\n");
        return NULL;
    }
    size_t capacity;
    fread(&capacity, sizeof(size_t), 1, file);
    data_t* d = init_data(capacity);
    fread(d->keys, sizeof(int*), capacity, file);
    fread(d->offsets, sizeof(long), capacity, file);
    fread(d->records, sizeof(record_t*), capacity, file);
    fread(d->last_accessed, sizeof(int), capacity, file);
    fclose(file);
    return d;
}

// Generate unique keys based on user-provided hashing function
