void manage_memory(char* file_name) {
    FILE* file = fopen(file_name, "r");
    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", file_name);
        return;
    }

    long* offsets = NULL;
    int* keys = NULL;
    record** records = NULL;

    size_t offset_count = 0;
    size_t key_count = 0;

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        char* token = strtok(line, ",");
        if (!token) continue;
        long offset = strtol(token, NULL, 10);
        token = strtok(NULL, ",");
        int key = strtol(token, NULL, 10);

        offsets = realloc(offsets, (offset_count + 1) * sizeof(long));
        keys = realloc(keys, (key_count + 1) * sizeof(int));

        offsets[offset_count] = offset;
        keys[key_count] = key;

        offset_count++;
        key_count++;

        // Initialize random number generator
        srand(time(NULL));
    }

    fclose(file);

    file = fopen("records.txt", "w");
    for (size_t i = 0; i < offset_count; i++) {
        record* record = malloc(sizeof(record));

        char str[32];
        sprintf(str, "%d", rand() % 100);
        size_t str_len = strlen(str) + 1;
        record->str = malloc(str_len);
        strcpy(record->str, str);

        record->key = keys[i];
        record->offset = offsets[i];
        record->value = rand() % 10;

        records = realloc(records, (i + 1) * sizeof(record*));
        records[i] = record;
    }

    fclose(file);
}
