    size_t capacity;  // Current allocated memory
    size_t size;      // Number of actual records
} RecordCollection;

// Function to initialize the record collection
RecordCollection* create_collection(size_t initial_capacity) {
    RecordCollection* coll = (RecordCollection*)malloc(sizeof(RecordCollection));
    coll->records = (Record*)malloc(initial_capacity * sizeof(Record));
    coll->capacity = initial_capacity;
    coll->size = 0;
    return coll;
}

// Function to add a record to the collection
void add_record(RecordCollection* coll, long offset, int key, int value) {
    if (coll->size == coll->capacity) {
        // Resize the array if it's full
        coll->capacity *= 2;
        coll->records = (Record*)realloc(coll->records, coll->capacity * sizeof(Record));
    }
    Record* new_rec = &coll->records[coll->size++];
    new_rec->offset = offset;
    new_rec->key = key;
    new_rec->value = value;
}

// Function to remove a record from the collection
void remove_record(RecordCollection* coll, long offset) {
    int i;
    for (i = 0; i < coll->size; i++) {
        if (coll->records[i].offset == offset) {
            // Shift down all records after the removed one
            memmove(&coll->records[i], &coll->records[i + 1],
                    (coll->size - i - 1) * sizeof(Record));
            coll->size--;
            return;
        }
    }
}

