#include <pthread.h>
#include <time.h>

#define RECORDS_PER_SECOND 1000
#define MAX_RECORDS 10000
#define ALIGNMENT 32
#define LOGGING_ENABLED 1

typedef struct {
    int timestamp;
} Record;

Record* create_records(int count) {
    Record* records = NULL;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    if (count > MAX_RECORDS) {
        fprintf(stderr, "Error: Attempted to create more than %d records.\n", MAX_RECORDS);
        return NULL;
    }

    records = (Record*) aligned_alloc(ALIGNMENT, count * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    pthread_mutex_lock(&lock);

    for (int i = 0; i < count; i++) {
        records[i].timestamp = time(NULL) % 10000; // timestamp in milliseconds
    }

    pthread_mutex_unlock(&lock);

    return records;
}

void* create_records_thread(void* arg) {
    int count = *((int*) arg);
    Record* records = create_records(count);
    free(arg);
    return (void*) records;
}

int main() {
    int count = RECORDS_PER_SECOND * 2; // create a temporary buffer of 2000 records
    pthread_t thread;

    if (pthread_create(&thread, NULL, create_records_thread, &count) != 0) {
        perror("Failed to create thread");
        return 1;
    }

    int status = pthread_join(thread, NULL);

    if (status != 0) {
        perror("Failed to join thread");
        return 1;
    }

    Record* records = (Record*) pthread_get_specific(NULL); // get the records from the thread
    free(records); // free the allocated memory

    return 0;
}

