    if (record_count >= capacity) {
        capacity *= 2; // Double the capacity
        record_collection = resize_collection(capacity);
    }

    Record* new_record = &((Record*)malloc(sizeof(Record)))[record_count];
    new_record->offset = offset;
    new_record->key = key;
