// Record structure containing an integer value
typedef struct {
    int value;
} Record;

// Hash table record node
typedef struct {
    long offset;
    int key;
    Record data;
    struct {
        struct hash_node* next;
    } prev, next;
} HashNode;

// Hash table structure
typedef struct {
    HashNode** buckets;
    int size;
    double load_factor;
} HashTable;

HashTable* create_hash_table(int capacity) {
    HashTable* hash_table = (HashTable*)malloc(sizeof(HashTable));
    hash_table->buckets = (HashNode**)calloc(capacity, sizeof(HashNode*));
    hash_table->size = capacity;
    hash_table->load_factor = 0.7; // Adjustable load factor
    return hash_table;
}

void insert_hash_node(HashTable* hash_table, long offset, int key) {
    HashNode* node = (HashNode*)malloc(sizeof(HashNode));
    node->offset = offset;
    node->key = key;
    Record record;
    record.value = rand() % RANDOM_RANGE; // Initialize with random value
    node->data = record;

    int index = hash(key) % hash_table->size;
    if (hash_table->buckets[index] == NULL) {
        hash_table->buckets[index] = node;
    } else {
        HashNode* current = hash_table->buckets[index];
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = node;
    }
}

int hash(int key) {
    return key % MAX_CAPACITY;
}

void free_hash_table(HashTable* hash_table) {
    for (int i = 0; i < hash_table->size; i++) {
        HashNode* current = hash_table->buckets[i];
        while (current != NULL) {
            HashNode* next = current->next;
            free(current);
            current = next;
        }
    }
    free(hash_table->buckets);
    free(hash_table);
}

