// Custom hash function
unsigned int custom_hash(int key) {
    return (key * 1103515245 + 12345) % 100000;
}

// Hash table structure
typedef struct {
    unsigned int size;
    pthread_mutex_t lock;
    struct linked_list **buckets;
} hashtable;

// Linked list node structure
typedef struct node {
    int key;
    record value;
    struct node *next;
} node;

// Initialize the hash table
hashtable* init_hashtable(int size) {
    hashtable* ht = (hashtable*)malloc(sizeof(hashtable));
    ht->size = size;
    ht->buckets = (struct linked_list**)malloc(sizeof(struct linked_list*) * size);
    for (int i = 0; i < size; i++) {
        ht->buckets[i] = (struct linked_list*)malloc(sizeof(struct linked_list));
        ht->buckets[i]->head = NULL;
    }
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

// Insert a key-value pair into the hash table
void insert_hashtable(hashtable* ht, int key, record value) {
    unsigned int index = custom_hash(key) % ht->size;
    node* new_node = (node*)malloc(sizeof(node));
    new_node->key = key;
    new_node->value = value;
    new_node->next = ht->buckets[index]->head;
    ht->buckets[index]->head = new_node;
}

// Search for a key in the hash table
record search_hashtable(hashtable* ht, int key) {
    unsigned int index = custom_hash(key) % ht->size;
    node* current = ht->buckets[index]->head;
    while (current != NULL && current->key != key) {
        current = current->next;
    }
    if (current == NULL || current->key != key) {
        return NULL; // Not found
    }
    return current->value;
}

// Free the hash table
void free_hashtable(hashtable* ht) {
    for (int i = 0; i < ht->size; i++) {
        node* current = ht->buckets[i]->head;
        while (current != NULL) {
            node* next = current->next;
            free(current);
            current = next;
        }
        free(ht->buckets[i]);
    }
    free(ht->buckets);
    free(ht);
}

