#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int value;
    int* key;
    long* offset;
} record_t;

typedef struct {
    int* keys;
    long* offsets;
    record_t** records;
    int* last_accessed;
    int size;
    int capacity;
} data_structure_t;

void init_data_structure(data_structure_t* ds, int initial_capacity) {
    ds->keys = (int*)malloc(initial_capacity * sizeof(int));
    ds->offsets = (long*)malloc(initial_capacity * sizeof(long));
    ds->records = (record_t**)malloc(initial_capacity * sizeof(record_t*));
    ds->last_accessed = (int*)malloc(initial_capacity * sizeof(int));
    ds->size = 0;
    ds->capacity = initial_capacity;
}

void resize_data_structure(data_structure_t* ds, int new_capacity) {
    if (new_capacity <= ds->capacity) return;

    ds->keys = (int*)realloc(ds->keys, new_capacity * sizeof(int));
    ds->offsets = (long*)realloc(ds->offsets, new_capacity * sizeof(long));
    ds->records = (record_t**)realloc(ds->records, new_capacity * sizeof(record_t*));
    ds->last_accessed = (int*)realloc(ds->last_accessed, new_capacity * sizeof(int));

    ds->capacity = new_capacity;
}

void serialize_data_structure(const data_structure_t* ds, FILE* file) {
    int i;

    fwrite(&ds->size, sizeof(int), 1, file);
    fwrite(&ds->capacity, sizeof(int), 1, file);

    for (i = 0; i < ds->size; i++) {
        fwrite(ds->keys + i, sizeof(int), 1, file);
        fwrite(&ds->offsets[i], sizeof(long), 1, file);
        fwrite(&ds->records[i]->value, sizeof(int), 1, file);
        fwrite(&ds->records[i]->key, sizeof(int), 1, file);
        fwrite(&ds->records[i]->offset, sizeof(long), 1, file);
    }

    for (i = 0; i < ds->capacity; i++) {
        fwrite(&ds->last_accessed[i], sizeof(int), 1, file);
    }
}

void deserialize_data_structure(data_structure_t* ds, FILE* file) {
    int i;
    size_t size;

    fread(&size, sizeof(int), 1, file);
    fread(&ds->capacity, sizeof(int), 1, file);

    ds->keys = (int*)malloc(ds->capacity * sizeof(int));
