// Define a record structure
typedef struct {
    int key;
    int value;
} Record;

// Define a data structure containing 'long' offset values, 'int' keys, and 'record' structures
typedef struct {
    long* offsets;
    int* keys;
    Record** records;
    int numRecords;
    FILE* file;
} DataStructure;

// Function to initialize the data structure
DataStructure* initDataStructure() {
    DataStructure* ds = (DataStructure*)malloc(sizeof(DataStructure));
    ds->offsets = NULL;
    ds->keys = NULL;
    ds->records = NULL;
    ds->numRecords = 0;
    return ds;
}

// Function to add a new record to the data structure
void addRecord(DataStructure* ds, int key, int value) {
    // Allocate memory for the new record
    Record* newRecord = (Record*)malloc(sizeof(Record));
    newRecord->key = key;
    newRecord->value = value;

    // Update the offsets and keys arrays
    if (ds->numRecords > 0) {
        ds->offsets = (long*)realloc(ds->offsets, (ds->numRecords + 1) * sizeof(long));
        ds->keys = (int*)realloc(ds->keys, (ds->numRecords + 1) * sizeof(int));
    } else {
        ds->offsets = (long*)malloc(sizeof(long));
        ds->keys = (int*)malloc(sizeof(int));
    }
    ds->offsets[ds->numRecords] = ftell(ds->file);
    ds->keys[ds->numRecords] = key;

    // Add the new record to the array
    if (ds->records != NULL) {
        Record** temp = (Record**)realloc(ds->records, (ds->numRecords + 1) * sizeof(Record*));
        temp[ds->numRecords] = newRecord;
        ds->records = temp;
    } else {
        ds->records = (Record**)malloc(sizeof(Record*) * (ds->numRecords + 1));
        ds->records[ds->numRecords] = newRecord;
    }
    ds->numRecords++;
}

// Function to serialize the data structure to a file
void serializeDataStructure(DataStructure* ds) {
    // Write the metadata to the file
    fwrite(&ds->numRecords, sizeof(int), 1, ds->file);
    fwrite(ds->offsets, sizeof(long), ds->numRecords, ds->file);
    fwrite(ds->keys, sizeof(int), ds->numRecords, ds->file);

    // Write each record to the file
    for (int i = 0; i < ds->numRecords; i++) {
        Record* record = ds->records[i];
        fwrite(&record->key, sizeof(int), 1, ds->file);
        fwrite(&record->value, sizeof(int), 1, ds->file);
    }
}

// Function to deserialize the data structure from a file
DataStructure* deserializeDataStructure(FILE* file) {
    DataStructure* ds = initDataStructure();
    ds->file = file;

    // Read the metadata from the file
    int numRecords;
    fread(&numRecords, sizeof(int), 1, file);
    ds->offsets = (long*)malloc(sizeof(long) * numRecords);
    ds->keys = (int*)malloc(sizeof(int) * numRecords);

    for (int i = 0; i < numRecords; i++) {
        fread(ds->offsets + i, sizeof(long), 1, file);
        fread(&ds->keys[i], sizeof(int), 1, file);
    }

    // Read each record from the file
    ds->records = (Record**)malloc(sizeof(Record*) * numRecords);
    for (int i = 0; i < numRecords; i++) {
        Record* record = (Record*)malloc(sizeof(Record));
        fread(&record->key, sizeof(int), 1, file);
        fread(&record->value, sizeof(int), 1, file);
        ds->records[i] = record;
    }

    return ds;
}

