    fwrite(&num_products, sizeof(int), 1, file);
    for (int i = 0; i < num_products; i++) {
        Product product = inventory->products[i];
        fwrite(&product.id, sizeof(int), 1, file);
        fwrite(product.name, sizeof(char), strlen(product.name) + 1, file);
        fwrite(&product.price, sizeof(float), 1, file);
        int num_locations = sizeof(product.stock_locations) / sizeof(product.stock_locations[0]);
        fwrite(&num_locations, sizeof(int), 1, file);
        for (int j = 0; j < num_locations; j++) {
            fwrite(&product.stock_locations[j].region_id, sizeof(int), 1, file);
            fwrite(&product.stock_locations[j].quantity, sizeof(int), 1, file);
