    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->data = (int*)calloc(initial_capacity, sizeof(int));
    array->capacity = initial_capacity;
    array->last_accessed_index = -1;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void insert_into_dynamic_array(DynamicArray* array, int value) {
    pthread_mutex_lock(&array->mutex);
    if (array->last_accessed_index >= array->capacity) {
        array->data = (int*)realloc(array->data, (array->capacity * 2 + 1) * sizeof(int));
        array->capacity *= 2;
    }
    array->data[array->last_accessed_index + 1] = value;
    array->last_accessed_index++;
    pthread_mutex_unlock(&array->mutex);
}

int get_value_from_dynamic_array(DynamicArray* array, size_t index) {
    pthread_mutex_lock(&array->mutex);
    if (index > array->last_accessed_index) {
        // Handle out-of-range access
    }
    int value = array->data[index];
    pthread_mutex_unlock(&array->mutex);
    return value;
