    pthread_mutex_t lock;
} pair_t;

pair_t* table[TABLE_SIZE];

void init_table() {
    int i;
    for (i = 0; i < TABLE_SIZE; i++) {
        table[i] = NULL;
    }
}

long hash_function(int key) {
    // implement custom hash function
    return key % TABLE_SIZE;
}

int insert_pair(int key, long offset) {
    int index = hash_function(key);
    pair_t* p = (pair_t*)malloc(sizeof(pair_t));
    p->offset = offset;
    pthread_mutex_init(&p->lock, NULL);

    if (table[index] == NULL) {
        table[index] = p;
    } else {
        // handle collision
    }

    return 0;
}

long get_pair(int key) {
    int index = hash_function(key);
    pair_t* p = table[index];

    while (p != NULL && p->offset > 0) {
        if (p->key == key) {
            return p->offset;
        }
        p = p->next;
    }

    return -1;
}

void init_pair(pair_t* p, long offset) {
    p->offset = offset;
}

int remove_pair(int key) {
    int index = hash_function(key);
    pair_t* p = table[index];

    while (p != NULL && p->key != key) {
        if (p->next == NULL) {
            return -1;  // not found
        }
        p = p->next;
    }

    if (p->next == NULL) {
        free(p);
        table[index] = NULL;
    } else {
        pair_t* temp = p;
        p = p->next;
        free(temp);
    }

    return 0;
}

void* thread_function(void* arg) {
    int i;
    for (i = 0; i < 10; i++) {
        insert_pair(i, i * 10000);
    }
    return NULL;
}

int main() {
    init_table();
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, thread_function, NULL);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
