// Structure for user sessions
typedef struct {
    char* session_id;
    time_t last_activity;
    int status; // 0: inactive, 1: active
} Session;

// Function to manage dynamic list of user sessions
Session** manage_sessions(int capacity) {
    // Initialize session array with given capacity
    Session** sessions = (Session**)malloc(capacity * sizeof(Session*));
    for (int i = 0; i < capacity; i++) {
        sessions[i] = NULL;
    }

    return sessions;
}

// Function to add new user session to the list
void add_session(Session** sessions, int capacity) {
    // Create a new session structure and initialize it
    Session* new_session = (Session*)malloc(sizeof(Session));
    new_session->session_id = "";
    new_session->last_activity = time(NULL);
    new_session->status = 1; // Initial status is active

    // Find the next available slot in the session array
    int i;
    for (i = 0; i < capacity; i++) {
        if (!sessions[i]) {
            break;
        }
    }

    // Add the new session to the array
    sessions[i] = new_session;
}

// Function to save session data to disk
void serialize_sessions(Session** sessions, int capacity) {
    FILE* file = fopen("session_data.txt", "wb");
    if (file != NULL) {
        for (int i = 0; i < capacity; i++) {
            Session* session = sessions[i];
            if (session) {
                fwrite(&session->last_activity, sizeof(time_t), 1, file);
                fwrite(&session->status, sizeof(int), 1, file);
                // Write the session ID as a null-terminated string
                size_t len = strlen(session->session_id);
                fwrite(&len, sizeof(size_t), 1, file);
                fwrite(session->session_id, sizeof(char), len + 1, file);
            }
        }
        fclose(file);
    }
}

// Function to deserialize session data from disk
Session** deserialize_sessions(int capacity) {
    Session** sessions = manage_sessions(capacity);
    FILE* file = fopen("session_data.txt", "rb");
    if (file != NULL) {
        for (int i = 0; i < capacity; i++) {
            Session* session;
            if (!sessions[i]) continue;

            // Read the last activity timestamp
            fread(&session->last_activity, sizeof(time_t), 1, file);
            // Read the status flag
            fread(&session->status, sizeof(int), 1, file);

            // Read the session ID length and string data
            size_t len;
            fread(&len, sizeof(size_t), 1, file);
            session->session_id = (char*)malloc((len + 1) * sizeof(char));
            fread(session->session_id, sizeof(char), len + 1, file);

            // Initialize the session pointer to the current slot
            sessions[i] = session;
        }
        fclose(file);
    }

    return sessions;
}

// Function to evict stale sessions based on inactivity threshold
void evict_stale_sessions(Session** sessions, int capacity) {
    time_t threshold = time(NULL) - 3600; // 1 hour inactivity threshold
    for (int i = 0; i < capacity; i++) {
        Session* session = sessions[i];
        if (!session || session->last_activity < threshold) {
            // Evict the stale session
            free(session);
            sessions[i] = NULL;
        }
    }
}

// Function to manage memory usage and evict sessions
void manage_memory(Session** sessions, int capacity) {
    evict_stale_sessions(sessions, capacity);
}
