#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <unistd.h>
#include <sys/mman.h>

// Define a struct for record
typedef struct {
    int val;
} Record;

// Function to check if a number is prime
bool is_prime(int num) {
    if (num <= 1)
        return false;
    for (int i = 2; i * i <= num; i++) {
        if (num % i == 0)
            return false;
    }
    return true;
}

// Function to find the next prime number
int next_prime(int num) {
    while (!is_prime(num)) {
        num++;
    }
    return num;
}

// Function to allocate memory and initialize arrays and hash table
Record** allocate_and_init(int n, int min_val, int max_val, int hash_table_size, size_t memory_budget) {
    Record **records = NULL;
    long *offsets = NULL;
    int *keys = NULL;
    int *hash_table = NULL;

    // Calculate the actual hash table size based on the given size and prime number
    int actual_hash_table_size = next_prime(hash_table_size);

    // Allocate memory for arrays and hash table
    offsets = (long*)malloc(n * sizeof(long));
    keys = (int*)malloc(n * sizeof(int));
    records = (Record**)malloc(n * sizeof(Record*));
    hash_table = (int*)calloc(actual_hash_table_size, sizeof(int));

    // Initialize arrays and hash table
    for (int i = 0; i < n; i++) {
        offsets[i] = rand() % (long)INT_MAX;
        keys[i] = rand() % INT_MAX;
        records[i] = (Record*)malloc(sizeof(Record));
        records[i]->val = rand() % (max_val - min_val + 1) + min_val;

        // Map each key to a unique index in the hash table
        int index = keys[i] % actual_hash_table_size;
        if (hash_table[index] != i) {
            hash_table[index] = i;
        } else {
            // Handle collision
            index = (index + 1) % actual_hash_table_size;
            while (hash_table[index] != i) {
                index = (index + 1) % actual_hash_table_size;
            }
        }
    }

    // Validate memory usage and handle failures gracefully
    size_t total_memory_usage = sizeof(long) * n + sizeof(int) * n + sizeof(Record*) * n + actual_hash_table_size * sizeof(int);
    if (total_memory_usage > memory_budget) {
        // Handle failure
        free(offsets);
        free(keys);
        for (int i = 0; i < n; i++) {
            free(records[i]);
        }
        free(records);
        free(hash_table);
        return NULL;
    }

    // Track and limit the total number of unique keys
    int num_unique_keys = 0;
    for (int i = 0; i < actual_hash_table_size; i++) {
        if (hash_table[i] != -1) {
            num_unique_keys++;
        }
    }
    if (num_unique_keys > n) {
        // Handle excessive growth and evict older keys
        for (int i = 0; i < num_unique_keys; i++) {
            int key_index = hash_table[i];
            for (int j = key_index; j < n - 1; j++) {
                records[j]->val = records[j + 1]->val;
                hash_table[(keys[j] % actual_hash_table_size)] = j;
            }
            free(records[num_unique_keys - 1]);
        }
    }

    // Return a pointer to the array of records
    return records;
}

// Function to clean up and free allocated memory
void cleanup(Record** records, int n) {
    for (int i = 0; i < n; i++) {
        free(records[i]);
    }
    free(records);
}
