#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* name;
    double value;
} item;

// Function to create a new list
item** create_list() {
    return (item**)malloc(sizeof(item*) * 1);
}

// Function to add an item to the list
void add_item(item** list, int size, const char* name, double value) {
    // Create a new item and allocate memory for it
    item* newItem = (item*)malloc(sizeof(item));
    newItem->name = (char*)malloc(strlen(name) + 1);
    strcpy(newItem->name, name);
    newItem->value = value;

    // Add the new item to the list and increment size
    *list = realloc(*list, sizeof(item*) * (size + 1));
    (*list)[size] = newItem;
    size++;
}

// Function to update an existing item by name
void update_item(item** list, int size, const char* name, double value) {
    for (int i = 0; i < size; i++) {
        if (strcmp((*list)[i]->name, name) == 0) {
            (*list)[i]->value = value;
            return;
        }
    }
}

// Function to remove an item by name
void remove_item(item** list, int* size, const char* name) {
    for (int i = 0; i < *size; i++) {
        if (strcmp((*list)[i]->name, name) == 0) {
            // Copy the last item to the current position
            (*list)[i] = (*list)[*size - 1];
            // Decrement size
            (*size)--;
            // Free memory for the removed item
            free((*list)[*size]->name);
            free((*list)[*size]);
            *list = realloc(*list, sizeof(item*) * (*size + 1));
            return;
        }
    }
}

// Function to iterate over the list and print each item's details
void print_list(item** list, int size) {
    for (int i = 0; i < size; i++) {
        printf("Name: %s, Value: %.2f\n", (*list)[i]->name, (*list)[i]->value);
    }
}

// Function to free memory allocated for the list
void destroy_list(item** list, int size) {
    for (int i = 0; i < size; i++) {
        // Free memory for each item
        free((*list)[i]->name);
        free((*list)[i]);
    }
    // Free memory for the list itself
    free(*list);
}

// Example usage:
int main() {
    int size = 0;
    item* list = create_list();
    add_item(&list, size, "Item1", 10.5);
    add_item(&list, size, "Item2", 20.8);
    print_list(&list, size);
    update_item(&list, size, "Item2", 25.3);
    print_list(&list, size);
    remove_item(&list, &size, "Item1");
    print_list(&list, size);
    destroy_list(&list, size);
    return 0;
}
