#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Define the structure for item
typedef struct {
    char* name;
    double value;
} Item;

// Define the structure for the dynamic linked list
typedef struct {
    Item* data;
    int size;
    pthread_mutex_t lock;
} List;

// Function to initialize the list
List* init_list() {
    List* new_list = (List*)malloc(sizeof(List));
    new_list->data = NULL;
    new_list->size = 0;
    pthread_mutex_init(&new_list->lock, NULL);
    return new_list;
}

// Function to add an item to the list
void add_item(List* list, Item* new_item) {
    pthread_mutex_lock(&list->lock);

    // Dynamically allocate memory for the new item
    Item* temp = (Item*)malloc(sizeof(Item));
    temp->name = strdup(new_item->name);
    temp->value = new_item->value;

    // Add the new item to the list and update its size
    if (list->data == NULL) {
        list->data = temp;
    } else {
        Item* current = list->data;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = temp;
    }

    // Update the size of the list
    list->size++;

    pthread_mutex_unlock(&list->lock);
}

// Function to update an item in the list
void update_item(List* list, char* name, double new_value) {
    pthread_mutex_lock(&list->lock);

    Item* current = list->data;
    while (current != NULL) {
        if (strcmp(current->name, name) == 0) {
            current->value = new_value;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to remove an item from the list
void remove_item(List* list, char* name) {
    pthread_mutex_lock(&list->lock);

    Item* prev = NULL;
    Item* current = list->data;
    while (current != NULL) {
        if (strcmp(current->name, name) == 0) {
            if (prev == NULL) {
                list->data = current->next;
            } else {
                prev->next = current->next;
            }
            free(current->name);
            free(current);
            list->size--;
            break;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to print the items in the list
void print_list(List* list) {
    Item* current = list->data;
    while (current != NULL) {
        printf("%s - %f\n", current->name, current->value);
        current = current->next;
    }
}

// Function to free the memory allocated for the list
void free_list(List* list) {
    pthread_mutex_lock(&list->lock);

    Item* current = list->data;
    while (current != NULL) {
        Item* next = current->next;
        free(current->name);
        free(current);
        current = next;
    }

    free(list->data);
    pthread_mutex_unlock(&list->lock);
}

// Main function to test the operations
int main() {
    List* list = init_list();

    // Add some items to the list
    Item item1 = {"item1", 10.0};
    add_item(list, &item1);

    Item item2 = {"item2", 20.0};
    add_item(list, &item2);

    Item item3 = {"item3", 30.0};
    add_item(list, &item3);

    // Update an item in the list
    update_item(list, "item1", 15.0);

    // Print the items in the list
    print_list(list);

    // Remove an item from the list
    remove_item(list, "item2");

    // Print the items in the list after removal
    print_list(list);

    // Free the memory allocated for the list
    free_list(list);

    return 0;
}
