#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure to store records
typedef struct {
    int key;
    double value;
    char* string;
} Record;

// Define the data structure to manage dynamic storage
typedef struct {
    Record** records; // Array of pointers to Records
    size_t capacity; // Current capacity of the array
    size_t size; // Number of filled slots in the array
    pthread_mutex_t mutex; // Mutex for synchronization
} DynamicArray;

// Function to create a new dynamic array with initial capacity
DynamicArray* create_array(size_t capacity) {
    DynamicArray* arr = (DynamicArray*)malloc(sizeof(DynamicArray));
    arr->records = (Record**)malloc(capacity * sizeof(Record*));
    arr->capacity = capacity;
    arr->size = 0;
    pthread_mutex_init(&arr->mutex, NULL);
    return arr;
}

// Function to resize the dynamic array
void resize_array(DynamicArray* arr) {
    size_t new_capacity = arr->capacity * 2;
    Record** new_records = (Record**)realloc(arr->records, new_capacity * sizeof(Record*));
    arr->records = new_records;
    arr->capacity = new_capacity;
}

// Function to add a record to the dynamic array
void add_record(DynamicArray* arr, int key, double value, char* string) {
    pthread_mutex_lock(&arr->mutex);
    if (arr->size == arr->capacity) {
        resize_array(arr);
    }
    Record* new_record = (Record*)malloc(sizeof(Record));
    new_record->key = key;
    new_record->value = value;
    new_record->string = string;
    arr->records[arr->size] = new_record;
    arr->size++;
    pthread_mutex_unlock(&arr->mutex);
}

// Function to find and print the maximum integer value from records
void find_max_key(DynamicArray* arr) {
    int max_key = INT_MIN;
    pthread_mutex_lock(&arr->mutex);
    for (int i = 0; i < arr->size; i++) {
        if (arr->records[i]->key > max_key) {
            max_key = arr->records[i]->key;
        }
    }
    pthread_mutex_unlock(&arr->mutex);
    printf("Maximum key: %d\n", max_key);
}

// Function to serialize the dynamic array to a file
void serialize_array(DynamicArray* arr, FILE* file) {
    pthread_mutex_lock(&arr->mutex);
    for (int i = 0; i < arr->size; i++) {
        Record* record = arr->records[i];
        fwrite(&record->key, sizeof(int), 1, file);
        fwrite(&record->value, sizeof(double), 1, file);
        size_t string_len = strlen(record->string);
        fwrite(&string_len, sizeof(size_t), 1, file);
        fwrite(record->string, 1, string_len + 1, file);
    }
    pthread_mutex_unlock(&arr->mutex);
}

// Function to deserialize the dynamic array from a file
void deserialize_array(DynamicArray* arr, FILE* file) {
    pthread_mutex_lock(&arr->mutex);
    Record** new_records = (Record**)malloc(arr->capacity * sizeof(Record*));
    arr->records = new_records;
    size_t i = 0;
    while (i < arr->size && !feof(file)) {
        int key;
        fread(&key, sizeof(int), 1, file);
        double value;
        fread(&value, sizeof(double), 1, file);
        size_t string_len;
        fread(&string_len, sizeof(size_t), 1, file);
        char* string = (char*)malloc(string_len + 1);
        fread(string, 1, string_len + 1, file);
        Record* new_record = (Record*)malloc(sizeof(Record));
        new_record->key = key;
        new_record->value = value;
        new_record->string = string;
        arr->records[i] = new_record;
        i++;
    }
    arr->size = i;
    pthread_mutex_unlock(&arr->mutex);
}
