['Here is the C code for managing a scalable and robust user profile database:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PROFILES 10000

typedef struct {
    char* name;
    char* email;
    struct tm birthdate;
} UserProfile;

// Database structure to manage profiles
typedef struct {
    UserProfile* profiles;
    int count;
    pthread_mutex_t lock;
} UserProfileDatabase;

// Function to initialize the database
void init_database(UserProfileDatabase* db) {
    db->profiles = (UserProfile*)malloc(MAX_PROFILES * sizeof(UserProfile));
    db->count = 0;
    pthread_mutex_init(&db->lock, NULL);
}

// Function to add a new profile to the database
void add_profile(UserProfileDatabase* db, UserProfile* profile) {
    pthread_mutex_lock(&db->lock);
    if (db->count < MAX_PROFILES) {
        db->profiles[db->count] = *profile;
        db->count++;
    }
    pthread_mutex_unlock(&db->lock);
}

// Function to retrieve a specific user's profile
UserProfile* get_profile(UserProfileDatabase* db, char* name) {
    pthread_mutex_lock(&db->lock);
    for (int i = 0; i < db->count; i++) {
        if (!strcmp(db->profiles[i].name, name)) {
            UserProfile* profile = malloc(sizeof(UserProfile));
            *profile = db->profiles[i];
            pthread_mutex_unlock(&db->lock);
            return profile;
        }
    }
    pthread_mutex_unlock(&db->lock);
    return NULL;
}

// Function to delete a user's profile
void delete_profile(UserProfileDatabase* db, char* name) {
    pthread_mutex_lock(&db->lock);
    for (int i = 0; i < db->count; i++) {
        if (!strcmp(db->profiles[i].name, name)) {
            memmove(&db->profiles[i], &db->profiles[i + 1], (db->count - i) * sizeof(UserProfile));
            db->count--;
        }
    }
    pthread_mutex_unlock(&db->lock);
}

// Function to serialize the database to a file
void serialize_database(const UserProfileDatabase* db, FILE* file) {
    fwrite(&db->count, sizeof(int), 1, file);
    for (int i = 0; i < db->count; i++) {
        fwrite(&db->profiles[i], sizeof(UserProfile), 1, file);
    }
}

// Function to deserialize the database from a file
void deserialize_database(UserProfileDatabase* db, FILE* file) {
    int count;
    fread(&count, sizeof(int), 1, file);
    db->count = count;
    db->profiles = (UserProfile*)malloc(count * sizeof(UserProfile));
    for (int i = 0; i < count; i++) {
        fread(&db->profiles[i], sizeof(UserProfile), 1, file);
    }
}

// Function to interact with the database through a command-line interface
void run_interface() {
    // Initialize the database
    UserProfileDatabase db;
    init_database(&db);

    // Main loop for interacting with the database
    while (1) {
        printf("Enter a command (add, get, delete, list, quit): ");
        char command[10];
        scanf("%s", command);
        if (!strcmp(command, "add")) {
            // Add a new profile
            UserProfile profile;
            printf("Enter user name: ");
            scanf("%s", &profile.name);
            printf("Enter email: ");
            scanf("%s", &profile.email);
            printf("Enter date of birth (YYYY-MM-DD): ");
            scanf("%s", &profile.birthdate.tm_yday);
            add_profile(&db, &profile);
        } else if (!strcmp(command, "get")) {
            // Retrieve a specific user's profile
            char name[20];
            printf("Enter user name: ");
            scanf("%s", &name);
            UserProfile* profile = get_profile(&db, name);
            if (profile) {
                printf("User found:\nName: %s\nEmail: %s\nBirthdate: %d-%02d-%02d\n",
                       profile->name, profile->email,
                       1900 + profile->birthdate.tm_year, profile->birthdate.tm_mon + 1, profile->birthdate.tm_mday);
                free(profile);
            } else {
                printf("User not found.\n");
            }
        } else if (!strcmp(command, "delete")) {
            // Delete a user's profile
            char name[20];
            printf("Enter user name: ");
            scanf("%s", &name);
            delete_profile(&db, name);
        } else if (!strcmp(command, "list")) {
            // List all profiles
            for (int i = 0; i < db.count; i++) {
                printf("Name: %s\nEmail: %s\nBirthdate: %d-%02d-%02d\n",
                       db.profiles[i].name, db.profiles[i].email,
                       1900 + db.profiles[i].birthdate.tm_year, db.profiles[i].birthdate.tm_mon + 1, db.profiles[i].birthdate.tm_mday);
            }
        } else if (!strcmp(command, "quit")) {
            // Quit the program
            break;
        } else {
            printf("Invalid command. Try again.\n");
        }
    }

    // Serialize the database to a file
    FILE* file = fopen("profiles.dat", "wb");
    serialize_database(&db, file);
    fclose(file);

    // Free memory allocated for profiles
    free(db.profiles);
}

int main() {
    run_interface();
    return 0;
}
