// Define a structure for an element in the linked list
typedef struct {
    float value;
    bool flag;
    struct element* next;
} element;

// Function to create and initialize an element with random float value
element* init_element(float min, float max) {
    element* new_node = (element*)malloc(sizeof(element));
    if (!new_node) {
        printf("Memory allocation failed!\n");
        return NULL;
    }
    new_node->value = (float)rand() / RAND_MAX * (max - min) + min;
    while (1) {
        new_node->flag = rand() % 2 == 0;
        if (!new_node->flag || (rand() % 100 < 50)) { // Ensure at least 50% of elements have flag set
            break;
        }
    }
    return new_node;
}

// Function to insert an element into the linked list
void insert_element(element** head, float min, float max) {
    element* new_node = init_element(min, max);
    if (!(*head)) {
        *head = new_node;
    } else {
        element* current = *head;
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
    }
}

// Function to print the linked list
void print_list(element* head) {
    printf("Linked List: \n");
    for (; head; head = head->next) {
        printf("Value: %f, Flag: %s\n", head->value, head->flag ? "Set" : "Not Set");
    }
}

int main() {
    srand(time(NULL)); // Seed random number generator
    element* head = NULL;
    int num_elements = 10; // Specify the number of elements
    float min_range = 0.1f; // Specify the minimum range for float values
    float max_range = 5.0f; // Specify the maximum range for float values

    for (int i = 0; i < num_elements; i++) {
        insert_element(&head, min_range, max_range);
    }

    print_list(head);

    return 0;
}

