        int len = rand() % max_string_length;
        for (int j = 0; j < len; ++j)
            str[j] = (char)(rand() % 52); // alphanumeric characters

        str[len] = '\0'; // null-terminate string
        sprintf(records[i].buffer, "%s", str);

        free(str); // deallocate temporary string buffer

        records[i].key = rand() % 100; // random key within specified range
        records[i].value = (double)rand() / RAND_MAX; // random value within [0,1]
    }

    return records;
}

void free_records(record* records, int num_records) {
    for (int i = 0; i < num_records; ++i)
        free((char*)records[i].buffer); // deallocate string buffers

    free(records); // deallocate array of records
}
