#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct element {
    float value;
    bool flag;
    struct element* next;
    int index;
} element;

void init_list(element** head, element** tail) {
    *head = NULL;
    *tail = NULL;
}

element* create_element(float val, int idx) {
    element* new_elem = (element*)malloc(sizeof(element));
    if (!new_elem) return NULL; // partial cleanup
    new_elem->value = val;
    new_elem->flag = rand() % 2 == 0;
    new_elem->next = NULL;
    new_elem->index = idx;
    return new_elem;
}

void add_element(element** head, element** tail, float val, int idx) {
    element* new_elem = create_element(val, idx);
    if (!new_elem) return; // partial cleanup
    if (*head == NULL) {
        *head = new_elem;
        *tail = new_elem;
    } else {
        new_elem->next = (*head)->next;
        (*head)->next = new_elem;
        if (new_elem->next) *tail = new_elem->next; // update tail
        else *tail = new_elem;
    }
}

void print_list(element* head, char direction) {
    if (direction == 'f') { // forward
        while (head) {
            printf("Value: %f Flag: %d Index: %d\n", head->value, head->flag, head->index);
            head = head->next;
        }
    } else { // backward
        element* curr = *tail;
        while (curr) {
            printf("Value: %f Flag: %d Index: %d\n", curr->value, curr->flag, curr->index);
            curr = curr->prev;
        }
    }
}

void free_list(element** head, element** tail) {
    element* curr = *head;
    while (curr) {
        element* next = curr->next;
        free(curr);
        curr = next;
    }
    *head = NULL;
    *tail = NULL;
}
