// Initialize the memory pool with a specified number of blocks
mem_pool* init_mem_pool(size_t num_blocks) {
    mem_pool* pool = malloc(sizeof(mem_pool));
    pool->blocks = malloc(num_blocks * sizeof(void*));
    pool->capacity = num_blocks;
    pool->used = 0;
    return pool;
}

// Allocate memory from the pool and increment its usage counter
void* alloc_mem_pool(mem_pool* pool, size_t size) {
    if (pool->used >= pool->capacity) {
        // Handle out-of-memory condition
    }
    void* ptr = *(void**)malloc(size);
    pool->blocks[pool->used++] = ptr;
    return ptr;
}

// Deallocate memory from the pool and decrement its usage counter
void dealloc_mem_pool(mem_pool* pool, void* ptr) {
    for (size_t i = 0; i < pool->used; i++) {
        if (*(void**)pool->blocks[i] == ptr) {
            free(ptr);
            pool->blocks[i] = pool->blocks[--pool->used];
            break;
        }
    }
}

