#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the maximum number of strings (10,000)
#define MAX_STRINGS 10000

typedef struct {
    char* str;
    int ref_count;
} StringRecord;

typedef struct {
    StringRecord* records;
    size_t capacity;
    size_t count;
    pthread_rwlock_t lock;
} FlexibleStringDatabase;

// Function to initialize the database
FlexibleStringDatabase* init_database() {
    FlexibleStringDatabase* db = (FlexibleStringDatabase*)malloc(sizeof(FlexibleStringDatabase));
    db->records = (StringRecord*)calloc(MAX_STRINGS, sizeof(StringRecord));
    db->capacity = MAX_STRINGS;
    db->count = 0;
    pthread_rwlock_init(&db->lock, NULL);
    return db;
}

// Function to insert a new string into the database
void insert_string(FlexibleStringDatabase* db, char* str) {
    pthread_rwlock_wrlock(&db->lock);
    for (size_t i = 0; i < db->count; i++) {
        if (!strcmp(db->records[i].str, str)) {
            // If the string already exists, increment its reference count
            db->records[i].ref_count++;
            pthread_rwlock_unlock(&db->lock);
            return;
        }
    }
    // If the string does not exist, add it to the database and reset its reference count
    if (db->count >= db->capacity) {
        // Dynamically resize the internal data structure if necessary
        size_t new_capacity = db->capacity * 2;
        StringRecord* new_records = (StringRecord*)realloc(db->records, new_capacity * sizeof(StringRecord));
        db->records = new_records;
        db->capacity = new_capacity;
    }
    db->records[db->count].str = str;
    db->records[db->count].ref_count = 1;
    db->count++;
    pthread_rwlock_unlock(&db->lock);
}

// Function to increment the reference count for a string
void increment_ref_count(FlexibleStringDatabase* db, char* str) {
    pthread_rwlock_wrlock(&db->lock);
    for (size_t i = 0; i < db->count; i++) {
        if (!strcmp(db->records[i].str, str)) {
            // Increment the reference count of the existing string
            db->records[i].ref_count++;
            pthread_rwlock_unlock(&db->lock);
            return;
        }
    }
    pthread_rwlock_unlock(&db->lock);
}

// Function to serialize the database to a file
void serialize_database(FlexibleStringDatabase* db, FILE* file) {
    fwrite(&db->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < db->count; i++) {
        size_t str_len = strlen(db->records[i].str);
        fwrite(&str_len, sizeof(size_t), 1, file);
        fwrite(db->records[i].str, sizeof(char), str_len + 1, file);
        fwrite(&db->records[i].ref_count, sizeof(int), 1, file);
    }
}

// Function to deserialize the database from a file
FlexibleStringDatabase* deserialize_database(FILE* file) {
    FlexibleStringDatabase* db = init_database();
    size_t count;
    fread(&count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < count; i++) {
        size_t str_len;
        char* str = malloc((str_len + 1) * sizeof(char));
        fread(&str_len, sizeof(size_t), 1, file);
        fread(str, sizeof(char), str_len + 1, file);
        int ref_count;
        fread(&ref_count, sizeof(int), 1, file);
        // Add the deserialized string to the database
        insert_string(db, str);
    }
    return db;
}

// Function to find and print the most frequently accessed string in the database
void find_most_frequent(FlexibleStringDatabase* db) {
    StringRecord* max_record = NULL;
    int max_ref_count = 0;
    pthread_rwlock_rdlock(&db->lock);
    for (size_t i = 0; i < db->count; i++) {
        if (db->records[i].ref_count > max_ref_count) {
            max_record = &db->records[i];
            max_ref_count = db->records[i].ref_count;
        }
    }
    pthread_rwlock_unlock(&db->lock);
    printf("The most frequently accessed string is: %s\n", max_record->str);
}

int main() {
    FlexibleStringDatabase* db = init_database();
    // Insert some sample strings
    insert_string(db, "Hello");
    insert_string(db, "World");
    insert_string(db, "Hello");  // This should increment the reference count of "Hello"
    // Serialize the database to a file
    FILE* file = fopen("database.bin", "wb");
    serialize_database(db, file);
    fclose(file);
    // Deserialize the database from the file
    file = fopen("database.bin", "rb");
    FlexibleStringDatabase* deserialized_db = deserialize_database(file);
    fclose(file);
    // Find and print the most frequently accessed string in the deserialized database
    find_most_frequent(deserialized_db);
    return 0;
}

