typedef struct {
    char name[20];
    char** emails;
    char** phoneNumbers;
} Profile;

Profile* createProfile(int idx) {
    Profile* profile = (Profile*)malloc(sizeof(Profile));
    strcpy(profile->name, "Profile ");
    profile->emails = (char**)malloc(5 * sizeof(char*));
    for (int i = 0; i < 5; i++) {
        char* email = (char*)malloc(20 * sizeof(char));
        sprintf(email, "user%d@example.com", idx);
        profile->emails[i] = email;
    }
    profile->phoneNumbers = (char**)malloc(3 * sizeof(char*));
    for (int i = 0; i < 3; i++) {
        char* phoneNumber = (char*)malloc(15 * sizeof(char));
        sprintf(phoneNumber, "123-456-%d", idx);
        profile->phoneNumbers[i] = phoneNumber;
    }
    return profile;
}

void resizeArrays(Profile** profiles, int newSize) {
    for (int i = 0; i < newSize; i++) {
        if (!profiles[i]->emails) {
            profiles[i]->emails = (char**)malloc(5 * sizeof(char*));
        }
        if (!profiles[i]->phoneNumbers) {
            profiles[i]->phoneNumbers = (char**)malloc(3 * sizeof(char*));
        }
    }
}

void printProfile(Profile* profile) {
    printf("Name: %s\n", profile->name);
    for (int i = 0; i < 5; i++) {
        printf("Email: %s\n", profile->emails[i]);
    }
    for (int i = 0; i < 3; i++) {
        printf("Phone Number: %s\n", profile->phoneNumbers[i]);
    }
}

void freeProfile(Profile* profile) {
    if (profile->emails) {
        for (int i = 0; i < 5; i++) {
            free(profile->emails[i]);
        }
        free(profile->emails);
    }
    if (profile->phoneNumbers) {
        for (int i = 0; i < 3; i++) {
            free(profile->phoneNumbers[i]);
        }
        free(profile->phoneNumbers);
    }
}

void freeAllMemory(Profile** profiles, int size) {
    for (int i = 0; i < size; i++) {
        freeProfile(profiles[i]);
    }
    free(profiles);
}

void serializeProfilesToFile(Profile** profiles, int size, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        printf("Error opening file.\n");
        return;
    }
    for (int i = 0; i < size; i++) {
        fwrite(profiles[i]->name, sizeof(char), strlen(profiles[i]->name), file);
        int emailCount = 5;
        fwrite(&emailCount, sizeof(int), 1, file);
        for (int j = 0; j < 5; j++) {
            char* email = profiles[i]->emails[j];
            fwrite(email, sizeof(char), strlen(email), file);
        }
        int phoneNumberCount = 3;
        fwrite(&phoneNumberCount, sizeof(int), 1, file);
        for (int j = 0; j < 3; j++) {
            char* phoneNumber = profiles[i]->phoneNumbers[j];
            fwrite(phoneNumber, sizeof(char), strlen(phoneNumber), file);
        }
    }
    fclose(file);
}

Profile** deserializeProfilesFromFile(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        printf("Error opening file.\n");
        return NULL;
    }
    int size;
    fread(&size, sizeof(int), 1, file);
    Profile** profiles = (Profile**)malloc(size * sizeof(Profile));
    for (int i = 0; i < size; i++) {
        profiles[i] = (Profile*)malloc(sizeof(Profile));
        fread(profiles[i]->name, sizeof(char), strlen(profiles[i]->name), file);
        int emailCount;
        fread(&emailCount, sizeof(int), 1, file);
        for (int j = 0; j < emailCount; j++) {
            char* email = (char*)malloc(20 * sizeof(char));
            fread(email, sizeof(char), strlen(email), file);
            profiles[i]->emails[j] = email;
        }
        int phoneNumberCount;
        fread(&phoneNumberCount, sizeof(int), 1, file);
        for (int j = 0; j < phoneNumberCount; j++) {
            char* phoneNumber = (char*)malloc(15 * sizeof(char));
            fread(phoneNumber, sizeof(char), strlen(phoneNumber), file);
            profiles[i]->phoneNumbers[j] = phoneNumber;
        }
    }
    fclose(file);
    return profiles;
}

int main() {
    int numProfiles = 10;
    Profile** profiles = (Profile**)malloc(numProfiles * sizeof(Profile));
    for (int i = 0; i < numProfiles; i++) {
        profiles[i] = createProfile(i);
    }

    // Serialize the data structure
    serializeProfilesToFile(profiles, numProfiles, "profiles.bin");

    // Deserialize and free the memory
    Profile** deserializedProfiles = deserializeProfilesFromFile("profiles.bin");
    for (int i = 0; i < numProfiles; i++) {
        freeProfile(deserializedProfiles[i]);
    }
    freeAllMemory(deserializedProfiles, numProfiles);

    return 0;
}

