} User;

User *users;
int user_count = 0;
int name_index = 0;
int max_name_length = 0;

void initialize_users() {
    users = (User *)malloc(MAX_USERS * sizeof(User));
    for (int i = 0; i < MAX_USERS; i++) {
        users[i].name = NULL;
        users[i].age = 0;
        users[i].emails = NULL;
    }
}

void free_users() {
    for (int i = 0; i < user_count; i++) {
        if (users[i].name) {
            free(users[i].name);
        }
        if (users[i].emails) {
            for (int j = 0; j < MAX_EMAILS; j++) {
                if (users[i].emails[j]) {
                    free(users[i].emails[j]);
                }
            }
            free(users[i].emails);
        }
    }
    free(users);
}

void add_user() {
