    for (int i = 0; i < username_length; i++) {
        users[user_count].name[MAX_NAME_LENGTH - 1] = '0' + rand() % 10;
        MAX_NAME_LENGTH--;
    }
    users[user_count].age = MIN_AGE + rand() % USERNAME_RANGE;
    users[user_count].emails = (char **)malloc(MAX_EMAILS * sizeof(char *));
    for (int i = 0; i < MAX_EMAILS; i++) {
        users[user_count].emails[i] = (char *)malloc(MAX_NAME_LENGTH * sizeof(char));
        sprintf(users[user_count].emails[i], "user%d@example.com", user_count);
        users[user_count++].age = MIN_AGE + rand() % USERNAME_RANGE;
    }
}

void find_oldest_user() {
    User oldest_user = users[0];
    for (int i = 1; i < user_count; i++) {
        if (users[i].age > oldest_user.age) {
            oldest_user = users[i];
        }
    }
    printf("Oldest user: %s, age: %d\n", oldest_user.name, oldest_user.age);
}

void print_users() {
    for (int i = 0; i < user_count; i++) {
        printf("%s, age: %d\n", users[i].name, users[i].age);
    }
}

int main() {
    srand(time(NULL));
    initialize_users();
    for (int i = 0; i < MAX_USERS; i++) {
        add_user();
    }
    find_oldest_user();
    print_users();
    free_users();
    return 0;
}
