// Define a struct to represent a configuration item
typedef struct {
    char* key;
    char* value;
} ConfigItem;

// Define a struct to manage the configuration store
typedef struct {
    pthread_mutex_t lock; // Lock for thread-safe access
    ConfigItem** items; // Dynamic array of configuration items
    int size; // Current size of the array
    int capacity; // Maximum capacity of the array
} ConfigStore;

// Initialize the configuration store with a given initial size and capacity
ConfigStore* init_config_store(int initial_size, int capacity) {
    ConfigStore* store = (ConfigStore*)malloc(sizeof(ConfigStore));
    pthread_mutex_init(&store->lock, NULL);
    store->items = (ConfigItem**)malloc(initial_size * sizeof(ConfigItem*));
    store->size = 0;
    store->capacity = capacity;
    return store;
}

// Add a new configuration item to the store
void add_config_item(ConfigStore* store, char* key, char* value) {
    pthread_mutex_lock(&store->lock);
    if (store->size >= store->capacity) {
        // Resize the array if it's full
