#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a structure for configuration entries
typedef struct {
    char* key;
    int value;
    int priority;
} ConfigEntry;

// Define a hash table for storing configurations
typedef struct {
    size_t capacity;
    size_t size;
    ConfigEntry** entries;
    pthread_rwlock_t lock;
} ConfigHashTable;

// Function to create a new configuration hash table
ConfigHashTable* config_hash_table_create(size_t capacity) {
    ConfigHashTable* table = (ConfigHashTable*)malloc(sizeof(ConfigHashTable));
    table->capacity = capacity;
    table->size = 0;
    table->entries = (ConfigEntry**)calloc(capacity, sizeof(ConfigEntry*));
    pthread_rwlock_init(&table->lock, NULL);
    return table;
}

// Function to insert a new configuration entry into the hash table
void config_hash_table_insert(ConfigHashTable* table, char* key, int value, int priority) {
    size_t index = strlen(key) % table->capacity;
    ConfigEntry* entry = (ConfigEntry*)malloc(sizeof(ConfigEntry));
    entry->key = strdup(key);
    entry->value = value;
    entry->priority = priority;
    table->entries[index] = entry;
    pthread_rwlock_wrlock(&table->lock);
    table->size++;
    pthread_rwlock_unlock(&table->lock);
}

// Function to retrieve a configuration entry from the hash table
ConfigEntry* config_hash_table_get(ConfigHashTable* table, char* key) {
    size_t index = strlen(key) % table->capacity;
    ConfigEntry* entry = table->entries[index];
    if (entry && strcmp(entry->key, key) == 0) {
        return entry;
    }
    return NULL;
}

// Function to serialize a configuration entry
char* config_serialize(ConfigEntry* entry) {
    char* buffer = malloc(strlen(entry->key) + 32);
    sprintf(buffer, "{\"key\":\"%s\",\"value\":%d,\"priority\":%d}", entry->key, entry->value, entry->priority);
    return buffer;
}

// Function to deserialize a configuration entry
ConfigEntry* config_deserialize(char* buffer) {
    ConfigEntry* entry = (ConfigEntry*)malloc(sizeof(ConfigEntry));
    sscanf(buffer, "{\"key\":\"%s\",\"value\":%d,\"priority\":%d}", &entry->key, &entry->value, &entry->priority);
    return entry;
}

// Function to update the priority level of a configuration entry
void config_priority_update(ConfigHashTable* table, char* key, int newPriority) {
    size_t index = strlen(key) % table->capacity;
    ConfigEntry* entry = table->entries[index];
    if (entry && strcmp(entry->key, key) == 0) {
        pthread_rwlock_wrlock(&table->lock);
        entry->priority = newPriority;
        pthread_rwlock_unlock(&table->lock);
    }
}

// Function to identify and print the highest-priority configuration
void config_highest_priority(ConfigHashTable* table) {
    ConfigEntry* maxEntry = NULL;
    int maxValue = 0;
    pthread_rwlock_rdlock(&table->lock);
    for (size_t i = 0; i < table->capacity; i++) {
        if (table->entries[i]) {
            if (table->entries[i]->priority > maxValue) {
                maxValue = table->entries[i]->priority;
                maxEntry = table->entries[i];
            }
        }
    }
    pthread_rwlock_unlock(&table->lock);
    printf("Highest-priority configuration: %s with value %d and priority %d\n", maxEntry->key, maxEntry->value, maxEntry->priority);
}

// Function to list all configurations modified within a specified time frame
void config_modified_list(ConfigHashTable* table, int timestamp) {
    pthread_rwlock_rdlock(&table->lock);
    for (size_t i = 0; i < table->capacity; i++) {
        if (table->entries[i]) {
            ConfigEntry* entry = table->entries[i];
            if (entry->timestamp <= timestamp) {
                printf("Configuration %s with value %d and priority %d was modified at %d\n", entry->key, entry->value, entry->priority, timestamp);
            }
        }
    }
    pthread_rwlock_unlock(&table->lock);
}

int main() {
    // Create a new configuration hash table
    ConfigHashTable* table = config_hash_table_create(10000);

    // Insert some configuration entries
    config_hash_table_insert(table, "key1", 10, 1);
    config_hash_table_insert(table, "key2", 20, 2);
    config_hash_table_insert(table, "key3", 30, 3);

    // Update the priority level of a configuration entry
    config_priority_update(table, "key2", 4);

    // Identify and print the highest-priority configuration
    config_highest_priority(table);

    // List all configurations modified within a specified time frame
    config_modified_list(table, 1643723400);

    return 0;
}
```

