void* handleUserRequests(int socket) {
    // Initialize the request array and its size
    HttpRequest** requests = (HttpRequest**)malloc(sizeof(HttpRequest*) * 100000);
    int requestSize = 0;

    // Initialize the last accessed index of each request
    int* lastAccessedIndex = (int*)malloc(sizeof(int) * 100000);

    // Loop until there are no more incoming requests
    while (1) {
        HttpRequest* newRequest;
        int bytesRead;

        // Read a new request from the socket
        bytesRead = read(socket, &newRequest, sizeof(HttpRequest));
        if (bytesRead == -1) {
            break;  // Connection closed or error occurred
        }

        // Dynamically resize the request array as necessary
        if (requestSize >= 100000) {
            requestSize *= 2;
            requests = realloc(requests, sizeof(HttpRequest*) * requestSize);
        }

        // Add the new request to the end of the array
        requests[requestSize] = newRequest;
        lastAccessedIndex[requestSize] = requestSize;

        requestSize++;

        // Process each existing request in the array
        for (int i = 0; i < requestSize; i++) {
            HttpRequest* currentRequest = requests[i];

            // Perform any necessary processing on the request
            // ...

            lastAccessedIndex[i] = i;
        }
    }

    // Close the socket and free memory
    close(socket);
    free(requests);
    free(lastAccessedIndex);

    return NULL;
}

// Function to serialize the request array to a file
void serializeRequests(HttpRequest** requests, int requestSize) {
    FILE* file = fopen("requests.txt", "wb");
    if (file == NULL) {
        // Handle error
    }

    for (int i = 0; i < requestSize; i++) {
        HttpRequest* currentRequest = requests[i];

        fwrite(&currentRequest, sizeof(HttpRequest), 1, file);
    }

    fclose(file);
}

// Function to deserialize the request array from a file
HttpRequest** deserializeRequests() {
    FILE* file = fopen("requests.txt", "rb");
    if (file == NULL) {
        // Handle error
    }

    HttpRequest** requests = (HttpRequest**)malloc(sizeof(HttpRequest*) * 100000);
    int requestSize = 0;

    HttpRequest* currentRequest;
    while (1) {
        fread(&currentRequest, sizeof(HttpRequest), 1, file);

        if (feof(file)) {
            break;  // End of file reached
        }

        requests[requestSize] = currentRequest;
        requestSize++;

        // Perform any necessary processing on the deserialized request
        // ...
    }

    fclose(file);
    return requests;
}

// Function to log and analyze failed requests with specific error codes
void logFailedRequests(HttpRequest** requests, int requestSize) {
    FILE* file = fopen("failed_requests.txt", "w");
    if (file == NULL) {
        // Handle error
    }

    for (int i = 0; i < requestSize; i++) {
        HttpRequest* currentRequest = requests[i];

        // Log the failed request and its corresponding error code
        fprintf(file, "%s %d\n", currentRequest->uri, currentRequest->timestamp);
    }

    fclose(file);
}

// Function to calculate the average response time for successful requests
double calculateAverageResponseTime(HttpRequest** requests, int requestSize) {
    double totalResponseTime = 0.0;

    for (int i = 0; i < requestSize; i++) {
        HttpRequest* currentRequest = requests[i];

        // Calculate and add the response time for each successful request
        totalResponseTime += (double)(time(NULL) - currentRequest->timestamp);
    }

    return totalResponseTime / requestSize;
}
