#include <string.h>

typedef struct {
    int key;
    long offset;
    short value;
} record;

record *expandGraphStructure(record **records, size_t *records_size) {
    // Initialize parameters for graph expansion
    int num_records = 0;
    int max_key = 0;

    // Fetch initial graph parameters from external data source
    FILE *params_file = fopen("graph_params.txt", "r");
    if (params_file == NULL) {
        // Fallback mechanism to generate random parameters locally
        srand(time(NULL));
        num_records = rand() % 10000 + 1;
        max_key = rand() % 1000 + 1;
    } else {
        // Read parameters from file
        fscanf(params_file, "%d\n%d", &num_records, &max_key);
        fclose(params_file);
    }

    // Initialize arrays and record structures
    *records_size = num_records;
    *records = (record *)malloc(num_records * sizeof(record));
    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i].key = i % max_key;
        (*records)[i].offset = i;
        (*records)[i].value = rand() % 100 + 1;
    }

    // Initialize secondary structure for tracking last accessed index
    int *last_accessed = (int *)malloc(max_key * sizeof(int));
    for (int i = 0; i < max_key; ++i) {
        last_accessed[i] = -1;
    }

    return *records;
}

void setRecordValues(record *records, size_t records_size) {
    // Set value of each record's int field to a random value within range
    for (size_t i = 0; i < records_size; ++i) {
        records[i].value = rand() % 100 + 1;
    }
}

int findLargestKey(record *records, size_t records_size) {
    // Find and return the largest integer in the array
    int max_key = -1;
    for (size_t i = 0; i < records_size; ++i) {
        if (records[i].key > max_key)
            max_key = records[i].key;
    }
    return max_key;
}

void serializeRecords(record *records, size_t records_size, FILE *file) {
    // Serialize the data structure to a file for persistence
    fwrite(records, sizeof(record), records_size, file);
}

record *deserializeRecords(FILE *file, size_t *records_size) {
    // Deserialize the data structure back into memory
    record *records = (record *)malloc(*records_size * sizeof(record));
    fread(records, sizeof(record), *records_size, file);
    return records;
}
