#define MAX_MESSAGES 1000000
#define HASH_TABLE_SIZE 4096
#define TIMESTAMP_LENGTH 64
#define PAYLOAD_MAX_LENGTH 1024

typedef struct {
    int id;
    time_t timestamp;
    char payload[TIMESTAMP_LENGTH];
} Message;

Message *messages = NULL;
int message_count = 0;
int current_id = 1;

// Dynamic hash table for mapping message IDs to timestamps
struct {
    size_t size;
    Message **buckets;
} hash_table;

void init_hash_table() {
    hash_table.size = HASH_TABLE_SIZE;
    hash_table.buckets = calloc(hash_table.size, sizeof(Message *));
}

void resize_hash_table() {
    size_t new_size = hash_table.size * 2;
    Message **new_buckets = realloc(hash_table.buckets, new_size * sizeof(Message *));
    for (size_t i = 0; i < new_size; i++) {
        new_buckets[i] = NULL;
    }
    hash_table.size = new_size;
    free(hash_table.buckets);
    hash_table.buckets = new_buckets;
}

void insert_hash_entry(int id, time_t timestamp) {
    size_t index = id % hash_table.size;
    Message **bucket = &hash_table.buckets[index];
    for (Message *msg = *bucket; msg; msg = msg->next) {
        if (msg->id == id) {
            msg->timestamp = timestamp;
            return;
        }
    }
    // Insert new entry
    Message *new_msg = malloc(sizeof(Message));
    new_msg->id = id;
    new_msg->timestamp = timestamp;
    new_msg->next = *bucket;
    *bucket = new_msg;
}

void process_message(char *message) {
    int message_id = current_id++;
    time_t timestamp = time(NULL);
    int priority = rand() % 100; // Random priority level
    Message *new_msg = malloc(sizeof(Message));
    new_msg->id = message_id;
    new_msg->timestamp = timestamp;
    strcpy(new_msg->payload, message);
    messages = realloc(messages, (message_count + 1) * sizeof(Message));
    messages[message_count] = new_msg;
    message_count++;
}

void serialize_data() {
    // Serialize using Protocol Buffers
    google::protobuf::Message *pb_message = new google::protobuf::Message();
    pb_message->PackFrom((void *)messages, message_count * sizeof(Message));
    FILE *fp = fopen("data.pb", "wb");
    fwrite(pb_message, sizeof(google::protobuf::Message), 1, fp);
    fclose(fp);
}

int main() {
    init_hash_table();

    // Process messages from the broker
    while (1) {
        char *message = ...; // Get message from broker
        process_message(message);

        // Periodically serialize and persist data to disk
        if (message_count % 1000 == 0) {
            serialize_data();
        }
    }

    return 0;
}

void free_data() {
    for (int i = 0; i < message_count; i++) {
        free(messages[i]);
    }
    free(messages);
    free(hash_table.buckets);
}

void calculate_average_priority() {
    int total_priority = 0;
    for (int i = 0; i < message_count; i++) {
        total_priority += messages[i]->priority;
    }
    printf("Average priority level: %d\n", total_priority / message_count);
}
