file_metadata_array* read_file(char* filename, struct file_size* sizes, int num_files) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        return NULL; // Handle I/O error
    }

    int max_filename_len = 0;
    char* longest_filename = NULL;

    file_metadata_array* metadata_array = malloc(sizeof(struct file_metadata*) * num_files);
    if (metadata_array == NULL) {
        fclose(file);
        return NULL; // Handle memory allocation error
    }

    for (int i = 0; i < num_files; i++) {
        char line[256];
        if (fgets(line, sizeof(line), file) == NULL) {
            fclose(file);
            free(metadata_array);
            return NULL; // Handle I/O error or premature end of file
        }

        int filename_len = strlen(line) - 1; // Account for newline character
        if (filename_len > max_filename_len) {
            max_filename_len = filename_len;
            longest_filename = realloc(longest_filename, (max_filename_len + 1) * sizeof(char));
            memset(longest_filename, 0, max_filename_len + 1);
        }

        strcpy(longest_filename, line);

        metadata_array[i] = malloc(sizeof(struct file_metadata));
        if (metadata_array[i] == NULL) {
            fclose(file);
            free(metadata_array);
            return NULL; // Handle memory allocation error
        }

        metadata_array[i]->filename = longest_filename;
        metadata_array[i]->size = &sizes[i];
    }

    fclose(file);

    return metadata_array;
}

