#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>

typedef struct {
    char* filename;
    unsigned long size;
} file_size;

typedef struct {
    time_t timestamp;
} timestamp;

typedef struct {
    char* filename;
    unsigned long size;
    time_t timestamp;
} file_metadata;

file_metadata* read_file_data(const char* input_filename, int* num_entries) {
    file_metadata* metadata = NULL;
    file_size* sizes = NULL;
    timestamp* timestamps = NULL;
    int max_filename_len = 0;
    FILE* file = fopen(input_filename, "rb");
    if (file == NULL) {
        return NULL;
    }

    // Read and parse the compressed text file
    z_stream strm;
    strm.zalloc = Z_NULL;
    strm.zfree = Z_NULL;
    strm.opaque = Z_NULL;

    int num_lines = 0;
    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        if (num_lines > 0) {
            // Decompress the line
            strm.next_in = (unsigned char*)line;
            strm.avail_in = strlen(line);
            strm.total_out = 0;

            do {
                unsigned char out[1024];
                unsigned int len = sizeof(out);
                strm.next_out = out;
                strm.avail_out = len;

                deflateInit2(&strm, Z_DEFAULT_COMPRESSION, Z_DEFAULT_WINDOWBITS, Z_DEFAULT_MEMLEVEL, Z_DEFAULT_STRATEGY, 0);

                if (deflate(&strm, Z_FINISH) == Z_STREAM_END) {
                    break;
                }

                strm.total_out += len - strm.avail_out;
            } while (1);

            // Parse the decompressed line
            char* filename = strtok(line, "\n");
            file_size fs = {filename, 0};
            timestamp ts = {0};

            if (strtok(NULL, " ") != NULL) {
                int size = atoi(strtok(NULL, " "));
                fs.size = size;
                if (strtok(NULL, ",") != NULL) {
                    char* timestamp_str = strtok(NULL, ",");
                    ts.timestamp = atol(timestamp_str);
                }
            }

            // Allocate memory for the metadata structure
            file_metadata* meta = realloc(metadata, sizeof(file_metadata*) * (num_lines + 1));
            if (meta == NULL) {
                fclose(file);
                return NULL;
            }

            meta[num_lines].filename = malloc(strlen(filename) + 1);
            strcpy(meta[num_lines].filename, filename);

            // Store the size and timestamp
            meta[num_lines].size = fs.size;
            meta[num_lines].timestamp = ts.timestamp;

            metadata = meta;
            num_lines++;
        }
    }

    fclose(file);

    // Find the maximum filename length
    for (int i = 0; i < num_lines; i++) {
        if (strlen(metadata[i].filename) > max_filename_len) {
            max_filename_len = strlen(metadata[i].filename);
        }
    }

    // Allocate memory for the file_size and timestamp arrays
    sizes = realloc(sizes, sizeof(file_size*) * num_lines);
    timestamps = realloc(timestamps, sizeof(timestamp*) * num_lines);

    // Store the size and timestamp pointers in the respective arrays
    for (int i = 0; i < num_lines; i++) {
        sizes[i] = &fs;
        timestamps[i] = &ts;
    }

    *num_entries = num_lines;

    return metadata;
}

void free_file_data(file_metadata* metadata, int num_entries) {
    for (int i = 0; i < num_entries; i++) {
        free(metadata[i].filename);
    }
    free(metadata);
}
