#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int id;
    double weight;
} Node;

typedef struct {
    Node* nodes[1000000]; // array of pointers to node structures
    double* weights; // array of connection strengths
    int* edges; // array of edge indices
    Node** adjacency_list; // adjacency list for each node
    int num_nodes;
    int last_accessed_node;
} NetworkTopology;

void manageNetworkTopology(NetworkTopology* top, int num_new_nodes, int num_new_edges) {
    // Allocate memory for new nodes and edges
    Node* new_nodes = (Node*)malloc(num_new_nodes * sizeof(Node));
    Edge* new_edges = (Edge*)malloc(num_new_edges * sizeof(Edge));

    // Initialize new nodes and edges
    for (int i = 0; i < num_new_nodes; i++) {
        new_nodes[i].id = i;
        new_nodes[i].weight = 1.0;
    }
    for (int i = 0; i < num_new_edges; i++) {
        new_edges[i].node1 = &new_nodes[0]; // assign pointers to new nodes
        new_edges[i].node2 = &new_nodes[0];
        new_edges[i].weight = 1.0;
    }

    // Add new nodes and edges to existing network topology
    for (int i = 0; i < num_new_nodes; i++) {
        top->num_nodes++;
        top->adjacency_list[top->num_nodes - 1] = &new_nodes[i];
    }
    for (int i = 0; i < num_new_edges; i++) {
        // add new edges to existing adjacency list
        top->edges[top->num_nodes * 2 + i] = &new_edges[i];
    }

    // Update last accessed node index
    top->last_accessed_node = top->num_nodes - 1;
}

void serializeNetworkTopology(NetworkTopology* top, FILE* file) {
    fwrite(&top->num_nodes, sizeof(int), 1, file);
    fwrite(top->adjacency_list, sizeof(Node*), top->num_nodes, file);
    fwrite(top->edges, sizeof(Edge*), top->num_nodes * 2, file);
