#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the record structure
typedef struct {
    int key;
    long offset;
    short value;
} Record;

// Function to expand the graph structure
void expandGraphStructure(int** keys, long** offsets, Record*** records, int* numRecords) {
    // Initialize arrays and structures
    *numRecords = 10000; // Initial capacity for the record array
    *keys = (int*)malloc(*numRecords * sizeof(int));
    *offsets = (long*)malloc(*numRecords * sizeof(long));
    *records = (Record**)malloc(*numRecords * sizeof(Record));

    // Initialize secondary structure to track last accessed index of each key
    int* keyIndexTracker = (int*)malloc(*numRecords * sizeof(int));
    for (int i = 0; i < *numRecords; i++) {
        keyIndexTracker[i] = -1;
    }

    return;
}

// Function to serialize the data structure to a file
void serializeGraphStructure(const Record** records, int numRecords, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        // Handle error
    }
    for (int i = 0; i < numRecords; i++) {
        fwrite(&records[i]->key, sizeof(int), 1, file);
        fwrite(&records[i]->offset, sizeof(long), 1, file);
        fwrite(&records[i]->value, sizeof(short), 1, file);
    }
    fclose(file);
}

// Function to deserialize the data structure from a file
void deserializeGraphStructure(Record*** records, int* numRecords, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        // Handle error
    }
    *numRecords = 0;
    while (1) {
        Record* record = (Record*)malloc(sizeof(Record));
        fread(&record->key, sizeof(int), 1, file);
        fread(&record->offset, sizeof(long), 1, file);
        fread(&record->value, sizeof(short), 1, file);
        (*records)[(*numRecords)++] = record;
    }
    fclose(file);
}

// Function to dynamically add new records
void addRecord(int** keys, long** offsets, Record*** records, int* numRecords, int key, long offset, short value) {
    // Check for key and offset uniqueness
    for (int i = 0; i < *numRecords; i++) {
        if ((keys[i] == key) || (offsets[i] == offset)) {
            // Handle error - duplicate key or offset found
        }
    }

    // Allocate memory for new record
    Record* newRecord = (Record*)malloc(sizeof(Record));
    newRecord->key = key;
    newRecord->offset = offset;
    newRecord->value = value;

    // Shift existing records and update indices
    for (int i = *numRecords - 1; i > 0; i--) {
        keys[i] = keys[i - 1];
        offsets[i] = offsets[i - 1];
        (*records)[i]->key = key;
        (*records)[i]->offset = offset;
        (*records)[i]->value = value;
    }

    // Update the last accessed index of each key
    for (int i = 0; i < *numRecords; i++) {
        if ((*records)[i]->key == key) {
            keyIndexTracker[i] = *numRecords - 1;
        }
    }

    (*keys)[(*numRecords)++] = key;
    (*offsets)[(*numRecords)++] = offset;
    (*records)[(*numRecords)++] = newRecord;

    return;
}

int main() {
    int numRecords = 0;
    int* keys = NULL;
    long* offsets = NULL;
    Record** records = NULL;

    // Initialize and expand the graph structure
    expandGraphStructure(&keys, &offsets, &records, &numRecords);

    // Add new records to the expanded graph structure
    addRecord(&keys, &offsets, &records, &numRecords, 1, 2, 3);
    addRecord(&keys, &offsets, &records, &numRecords, 4, 5, 6);

    // Serialize and deserialize the data structure
    serializeGraphStructure(records, numRecords, "graph_structure.bin");
    int deserializedNumRecords = 0;
    Record** deserializedRecords = NULL;
    deserializeGraphStructure(&deserializedRecords, &deserializedNumRecords, "graph_structure.bin");

    return 0;
}
