typedef struct {
    int key;
    long offset;
    short value;
} record_t;

record_t* expandGraphStructure(record_t** records, int* num_records, int max_records) {
    if (*num_records >= max_records) {
        *records = realloc(*records, sizeof(record_t) * (max_records *= 2));
        if (!*records) return NULL; // handle memory allocation failure
    }

    record_t* new_record = (record_t*)malloc(sizeof(record_t));
    new_record->key = rand() % INT_MAX;
    new_record->offset = rand();
    new_record->value = rand() % USHRT_MAX;

    for (int i = 0; i < *num_records; ++i) {
        if (new_record->key == (*records)[i].key || new_record->offset == (*records)[i].offset) {
            free(new_record);
            return NULL; // handle duplicate key or offset
        }
    }

    record_t* temp = *records;
    *records = new_record;
    new_record = temp;

    ++(*num_records);

    return *records;
}

void setRecordValue(record_t* records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        records[i].value = rand() % USHRT_MAX;
    }
}

short findLargestInteger(record_t* records, int num_records) {
    short max_value = INT_MIN;
    for (int i = 0; i < num_records; ++i) {
        if (records[i].value > max_value) {
            max_value = records[i].value;
        }
    }
    return max_value;
}

void serializeRecords(record_t* records, int num_records, FILE* file) {
    for (int i = 0; i < num_records; ++i) {
        fwrite(&records[i], sizeof(record_t), 1, file);
    }
}

record_t* deserializeRecords(FILE* file) {
    record_t* records = NULL;
    int num_records = 0;

    while (fread(&records[num_records], sizeof(record_t), 1, file)) {
        ++num_records;
        records = realloc(records, sizeof(record_t) * (num_records + 1));
    }

    return records;
}

void printRecords(record_t* records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        printf("Key: %d, Offset: %ld, Value: %hd\n", records[i].key, records[i].offset, records[i].value);
    }
}
