#include <Python.h>
#include <uuid/uuid.h>
#include <time.h>

typedef struct {
    int timestamp;
    char level[6];
    char message[256];
    PyObject *metadata;
} logEntry;

void processAndPersistStructuredLogs(int size, PyObject **priority, PyObject **size_values) {
    // Initialize arrays
    PyObject **log_entries = PyMem_Malloc(size * sizeof(PyObject *));
    PyObject **duplicate_entries = PyMem_Malloc(size * sizeof(PyObject *));

    int i;
    for (i = 0; i < size; i++) {
        logEntry entry;

        // Initialize timestamp
        entry.timestamp = time(NULL);

        // Generate random message within specified length
        char *random_message = PyMem_Malloc(256);
        PyObject *metadata = PyTuple_Pack(1, PyBytes_FromStringAndSize(random_message, 256));
        PyMem_Free(random_message);

        // Initialize log level (e.g., "ERROR", "INFO")
        PyObject *log_level = PyBytes_FromString("ERROR");

        entry.message[0] = '\0';
        sprintf(entry.message, "%d", i);
        entry.metadata = metadata;
        memcpy(&entry.level, PyBytes_AsString(log_level), 5);

        // Create log entry structure
        PyObject *log_entry = PyTuple_Pack(4, PyLong_FromLong(entry.timestamp), log_level, PyBytes_FromStringAndSize(entry.message, strlen(entry.message)), metadata);
        PyObject *jwt_token = PyJWT_Generate("secret_key", log_entry);
        PyObject *encoded_log_entry = PyBase64_Encode(log_entry);

        // Store log entry in array
        log_entries[i] = log_entry;

        // Check for duplicate messages using Bloom Filter
        int is_duplicate;
        PyObject *bloom_filter = PyBloomFilter_Create(10000); // adjust to your desired size
        is_duplicate = PyBloomFilter_Check(bloom_filter, encoded_log_entry);
        if (is_duplicate) {
            duplicate_entries[i] = log_entry;
        } else {
            PyBloomFilter_Insert(bloom_filter, encoded_log_entry);
        }

        // Clean up
        Py_DECREF(metadata);
        Py_DECREF(log_level);
        Py_XDECREF(encoded_log_entry);
        Py_XDECREF(jwt_token);
    }

    // Print and filter log entries based on level
    PyObject *filtered_entries = PyTuple_Pack(1, log_entries);
    PyObject *total_duplicates = PyTuple_Pack(1, duplicate_entries);

    // Serialize data structure to file for persistence
    FILE *file = fopen("log_file.txt", "wb");
    fwrite(log_entries, sizeof(PyObject *), size, file);
    fclose(file);

    // Deserialize data structure from file
    FILE *file2 = fopen("log_file.txt", "rb");
    PyObject **deserialized_log_entries = PyMem_Malloc(size * sizeof(PyObject *));
    fread(deserialized_log_entries, sizeof(PyObject *), size, file2);
    fclose(file2);

    // Calculate total number of log entries meeting a certain criteria
    int total_filtered_entries = PyTuple_Size(filtered_entries);

    // Release memory and Python objects
    for (i = 0; i < size; i++) {
        Py_XDECREF(log_entries[i]);
        Py_XDECREF(duplicate_entries[i]);
    }
    PyMem_Free(log_entries);
    PyMem_Free(duplicate_entries);

    return total_filtered_entries;
}
