// Define a struct to hold transaction data
typedef struct {
    int id;
    double amount;
    time_t timestamp;
    char merchant[64];
} Transaction;

// Function to process transaction logs
void processTransactionLogs() {
    // Initialize arrays for IDs and amounts
    int* transactionIDs = NULL;
    double* transactionAmounts = NULL;
    Transaction* transactions = NULL;

    // Initialize the last accessed index of each ID
    int* idIndexMap = NULL;

    // Initialize variables to track the maximum number of transactions and current size
    int maxTransactions = 1000000; // Maximum 1 million transactions
    int currentSize = 0;
    int resizeThreshold = maxTransactions / 2; // Resize array when it reaches half capacity

    FILE* logFile = fopen("transaction_log.txt", "r");
    if (logFile == NULL) {
        printf("Error opening file.\n");
        return;
    }

    while (fscanf(logFile, "%d %lf %ld %s",
                 &transactionIDs[currentSize].id,
                 &transactionAmounts[currentSize],
                 &transactions[currentSize].timestamp,
                 transactions[currentSize].merchant) == 4) {
        // Resize arrays when the current size reaches the resize threshold
        if (currentSize >= resizeThreshold) {
            int newCapacity = currentSize * 2 + 1;
            transactionIDs = realloc(transactionIDs, newCapacity * sizeof(int));
            transactionAmounts = realloc(transactionAmounts, newCapacity * sizeof(double));
            transactions = realloc(transactions, newCapacity * sizeof(Transaction));

            idIndexMap = realloc(idIndexMap, newCapacity * sizeof(int));
            resizeThreshold *= 2;
        }

        currentSize++;
    }

    fclose(logFile);
}

int main() {
    processTransactionLogs();
    return 0;
}
