import java.util.concurrent.atomic.AtomicBoolean;

public class UserProfileLoader {

    public static UserProfile loadUserProfile(String filePath) {
        int retryCount = 0;
        while (retryCount < 3) {
            try {
                FileReader fileReader = new FileReader(filePath);
                BufferedReader bufferedReader = new BufferedReader(fileReader);
                String jsonContent = readJsonFile(bufferedReader);
                ObjectMapper mapper = new ObjectMapper();
                JsonNode profileData = mapper.readTree(jsonContent);

                // Validate the JSON data
                if (profileData.isArray() || profileData.isObject()) {
                    UserProfile userProfile = new UserProfile(profileData);
                    // Asynchronous update of user preferences in background thread
                    Thread thread = new Thread(() -> updateUserPreferences(userProfile));
                    thread.start();

                    return userProfile;
                } else {
                    fileReader.close();
                    bufferedReader.close();
                    return null;
                }
            } catch (IOException e) {
                if (retryCount < 2) {
                    // Transient error, retry loading the profile
                    System.out.println("Error: " + e.getMessage());
                    try {
                        Thread.sleep(1000); // Wait for a second before retrying
                    } catch (InterruptedException ex) {
                        Thread.currentThread().interrupt();
                    }
                    retryCount++;
                } else {
                    // Permanent error, return null
                    System.out.println("Error: Could not load profile. Retrying has been exhausted.");
                    return null;
                }
            } finally {
                try {
                    fileReader.close();
                    bufferedReader.close();
                } catch (IOException ex) {
                    // Handle the exception if the file reader or buffer reader cannot be closed
                }
            }
        }

        return null;
    }

    private static String readJsonFile(BufferedReader bufferedReader) throws IOException {
        StringBuilder sb = new StringBuilder();
        String line;

        while ((line = bufferedReader.readLine()) != null) {
            sb.append(line);
        }

        return sb.toString();
    }

