const { series, parallel } = require('async');
const { readFileSync } = require('fs');
const { parse } = require('json5');
const { blue, bold, green, red } = require('kleur');

const testRunner = (modulePath, configPath) => {
  const moduleConfig = parse(readFileSync(configPath));
  const tests = [];

  // Load the module and extract its tests
  const moduleExports = require(modulePath);
  for (const testName in moduleExports) {
    if (Object.prototype.hasOwnProperty.call(moduleExports, testName)) {
      tests.push({
        name: testName,
        test: moduleExports[testName],
        tags: moduleConfig.testTags || []
      });
    }
  }

  // Filter tests by tag
  const filteredTests = tests.filter((test) => {
    for (const tag of test.tags) {
      if (!moduleConfig.testExcludes.includes(tag)) return true;
    }
    return false;
  });

  // Run the tests in parallel, retrying failed tests a configurable number of times
  series([
    async () => {
      await parallel(filteredTests.map((test) => (async () => {
        try {
          await test.test();
          console.log(`✅ ${bold(test.name)}: Passed`);
        } catch (err) {
          let retries = 0;
          while (retries < moduleConfig.retryCount) {
            try {
              await test.test();
              console.log(`✅ ${bold(test.name)}: Passed after retry`);
              return;
            } catch (err) {
              retries++;
            }
          }
          console.error(`❌ ${red(test.name)}: Failed after ${retries} retries`);
        } finally {
          // Reset the mocking library
          require('blueslip').reset();
        }
      })())),
    async () => {
      const memoryUsage = process.memoryUsage().rss;
      console.log(`Memory Usage: ${green(memoryUsage.toFixed(2))} MB`);
    }
  ], (err) => {
    if (err) throw err;

    // Report test results
    const failedTests = filteredTests.filter((test) => test.status === 'failed');
    const retriedTests = filteredTests.filter((test) => test.retries > 0);
    console.log(`Test Results:`);
    console.log(`✅ Successful Tests: ${green(filteredTests.length - failedTests.length)}`);
    console.log(`❌ Failed Tests: ${red(failedTests.length)}`);
    console.log(`✨ Retried Tests: ${yellow(retriedTests.length)}`);

    // Provide API for retrieving detailed test results
    module.exports.getTestResults = () => {
      return filteredTests.map((test) => ({
        name: test.name,
        status: test.status,
        retries: test.retries,
        duration: test.duration
      }));
    };
  });
};

