const fs = require('fs');
const child_process = require('child_process');
const metadataService = require('metadata-service');

function processFileMetadata(paths) {
  const concurrentProcesses = Math.min(5, Math.floor(process.cpuUsage().system / 1000));
  const promises = paths.map((path) => new Promise((resolve, reject) => {
    child_process.fork('./file-metadater.js', [path], (error) => {
      if (error) {
        reject(error);
      }
    }).on('message', (metadata) => {
      resolve(metadata);
    });
  }));

  return Promise.all(promises).then((metadatas) => {
    const enrichedMetadatas = metadatas.map((metadata) => {
      try {
        const validatedMetadata = metadataService.validateAndEnrich(metadata);
        return validatedMetadata;
      } catch (error) {
        console.error(`Error enriching metadata for ${metadata.path}:`, error);
        return metadata;
      }
    });

    return enrichedMetadatas.filter((metadata) => metadata && metadata.size > 0).map((metadata) => ({
      path: metadata.path,
      size: metadata.size,
      lastModified: metadata.lastModified,
    }));
  }).catch((error) => {
    console.error('Error processing file metadata:', error);
    return [];
  });

  function fileMetadater(path) {
    const metadata = fs.statSync(path);

    process.send({ path, ...metadata });
  }
}

process.on('message', (path) => {
  try {
    fileMetadater(path);
  } catch (error) {
    console.error(`Error processing metadata for ${path}:`, error);
  }
});

process.on('exit', () => {
  console.info('File metadater process exiting');
});
