#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    char buffer[20];
    double value;
    bool flag;
    struct record* next;
    struct record* prev;
} record;

record* create_record(long offset, int key, double value) {
    record* new_record = (record*)malloc(sizeof(record));
    if (!new_record) {
        return NULL;
    }
    new_record->offset = offset;
    new_record->key = key;
    sprintf(new_record->buffer, "Default Buffer");
    new_record->value = value;
    new_record->flag = false;
    new_record->next = NULL;
    new_record->prev = NULL;
    return new_record;
}

record* insert_node(record** head, record* new_record, long offset) {
    if (!(*head)) {
        *head = new_record;
        return *head;
    }
    if (offset < 0) {
        printf("Invalid offset. Cannot insert at negative offset.\n");
        free(new_record);
        return NULL;
    }
    record* current = *head;
    while (current && current->offset < offset) {
        current = current->next;
    }
    if (!current || current->offset > offset) {
        new_record->prev = (*head);
        if ((*head)) {
            (*head)->next = new_record;
        } else {
            new_record->next = NULL;
        }
        *head = new_record;
    } else {
        new_record->prev = current->prev;
        new_record->next = current;
        if (current) {
            current->prev = new_record;
        } else {
            new_record->next = NULL;
        }
        if (new_record->prev) {
            new_record->prev->next = new_record;
        } else {
            *head = new_record;
        }
    }
    return *head;
}

record* delete_node(record** head, long offset) {
    record* current = *head;
    record* previous = NULL;
    while (current && current->offset != offset) {
        previous = current;
        current = current->next;
    }
    if (!current) {
        printf("Record not found.\n");
        return *head;
    }
    if (previous) {
        previous->next = current->next;
        if (current->next) {
            current->next->prev = previous;
        } else {
            *head = NULL;
        }
    } else {
        *head = current->next;
    }
    free(current);
    return *head;
}

record* allocate_records(record** head, int num_records) {
    record* new_head = NULL;
    for (int i = 0; i < num_records; i++) {
        record* new_record = create_record(i, i, (double)i / 10.0);
        if (!new_record) {
            return delete_nodes(&new_head, 0);
        }
        new_head = insert_node(&new_head, new_record, i);
    }
    return new_head;
}

record* delete_nodes(record** head, long offset) {
    record* current = *head;
    while (current && current->offset <= offset) {
        *head = delete_node(head, current->offset);
        current = *head;
    }
    if (!current) {
        free(*head);
        return NULL;
    } else {
        record* temp = current->next;
        free(current);
        *head = temp;
        return *head;
    }
}

int main() {
    srand(time(NULL));
    record* head = allocate_records(&head, 10);
    // Test the linked list
    for (record* node = head; node != NULL; node = node->next) {
        printf("Offset: %ld, Key: %d, Value: %.2f, Flag: %s\n", node->offset, node->key, node->value, node->flag ? "True" : "False");
    }
    // Test deletion
    head = delete_nodes(&head, 5);
    for (record* node = head; node != NULL; node = node->next) {
        printf("Offset: %ld, Key: %d, Value: %.2f, Flag: %s\n", node->offset, node->key, node->value, node->flag ? "True" : "False");
    }
    return 0;
}
