['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct entry {
    char* key;
    size_t length;
    double value;
} Entry;

typedef struct hash_entry {
    Entry entry;
    struct hash_entry* next;
} HashEntry;

typedef struct hash_table {
    HashEntry** buckets;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
}HashTable;

// Custom hash function
size_t custom_hash(const char* key, size_t capacity) {
    size_t hash = 0;
    for (size_t i = 0; i < strlen(key); i++) {
        hash = (hash * 31 + key[i]) % capacity;
    }
    return hash;
}

// Initialize the hash table with a specified initial capacity
void init_hash_table(HashTable* table, size_t capacity) {
    table->buckets = (HashEntry**)malloc(capacity * sizeof(HashEntry*));
    for (size_t i = 0; i < capacity; i++) {
        table->buckets[i] = NULL;
    }
    table->capacity = capacity;
    table->count = 0;
    pthread_mutex_init(&table->lock, NULL);
}

// Insert a new entry into the hash table
void insert_hash_table(HashTable* table, Entry* entry) {
    size_t index = custom_hash(entry->key, table->capacity);
    HashEntry* new_entry = (HashEntry*)malloc(sizeof(HashEntry));
    new_entry->entry = *entry;
    new_entry->next = table->buckets[index];
    table->buckets[index] = new_entry;
    pthread_mutex_lock(&table->lock);
    table->count++;
    if ((double)table->count / table->capacity > 0.7) {
        resize_hash_table(table, table->capacity * 2);
    }
    pthread_mutex_unlock(&table->lock);
}

// Resize the hash table when the load factor exceeds a predefined threshold
void resize_hash_table(HashTable* table, size_t new_capacity) {
    HashTable new_table;
    init_hash_table(&new_table, new_capacity);
    for (size_t i = 0; i < table->capacity; i++) {
        HashEntry* current = table->buckets[i];
        while (current != NULL) {
            insert_hash_table(&new_table, &current->entry);
            current = current->next;
        }
    }
    for (size_t i = 0; i < table->capacity; i++) {
        free(table->buckets[i]);
    }
    free(table->buckets);
    *table = new_table;
}

// Delete an entry from the hash table
void delete_hash_table(HashTable* table, char* key) {
    size_t index = custom_hash(key, table->capacity);
    HashEntry* current = table->buckets[index];
    HashEntry* previous = NULL;
    while (current != NULL) {
        if (strcmp(current->entry.key, key) == 0) {
            if (previous == NULL) {
                table->buckets[index] = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            pthread_mutex_lock(&table->lock);
            table->count--;
            if ((double)table->count / table->capacity < 0.3 && table->capacity > 16) {
                resize_hash_table(table, table->capacity / 2);
            }
            pthread_mutex_unlock(&table->lock);
            return;
        }
        previous = current;
        current = current->next;
    }
}

// Lookup an entry in the hash table
void lookup_hash_table(HashTable* table, char* key) {
    size_t index = custom_hash(key, table->capacity);
    HashEntry* current = table->buckets[index];
    while (current != NULL) {
        if (strcmp(current->entry.key, key) == 0) {
            printf("Key: %s, Length: %zu, Value: %.2lf\n", key, current->entry.length, current->entry.value);
            return;
        }
        current = current->next;
    }
    printf("Entry not found.\n");
}

// Iterate over all entries in the hash table and print their details
void iterate_hash_table(HashTable* table) {
    if (table->count == 0) {
        printf("Hash table is empty.\n");
        return;
    }
    for (size_t i = 0; i < table->capacity; i++) {
        HashEntry* current = table->buckets[i];
        while (current != NULL) {
            printf("Key: %s, Length: %zu, Value: %.2lf\n", current->entry.key, current->entry.length, current->entry.value);
            current = current->next;
        }
    }
}
