record* createRecord(long offset, int key) {
    record* newRecord = (record*)malloc(sizeof(record));
    newRecord->offset = offset;
    newRecord->key = key;
    newRecord->value = (double)rand() / RAND_MAX; // Random value
    newRecord->flag = false;
    return newRecord;
}

// Linked list node structure
typedef struct Node {
    record* data;
    struct Node* next;
    struct Node* prev;
} Node;

Node* createNode(record* data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = NULL;
    newNode->prev = NULL;
    return newNode;
}

record** recordArray = NULL; // Array of records
int recordCount = 0;

// Function to dynamically allocate and initialize a flexible record structure
record** createRecordList(int capacity) {
    record* records = (record*)malloc(capacity * sizeof(record));
    for (int i = 0; i < capacity; i++) {
        records[i].offset = rand();
        records[i].key = i;
        records[i].value = (double)rand() / RAND_MAX; // Random value
        records[i].flag = false;
    }
    recordArray = &records[0];
    recordCount = capacity;
    return recordArray;
}

// Function to insert a new record at the specified position
record** insertRecord(record** list, int capacity, long offset, int key) {
    Node* newNode = createNode(createRecord(offset, key));
    if (*list == NULL || (*list)->data->offset > newNode->data->offset) {
        // Insert at beginning
        newNode->next = *list;
        if (*list != NULL)
            (*list)->prev = &newNode->data;
        *list = newNode;
    } else {
        Node* prev = *list;
        while (prev->next != NULL && prev->next->data->offset < newNode->data->offset) {
            prev = prev->next;
        }
        if (prev->next == NULL || prev->next->data->offset > newNode->data->offset) {
            // Insert at end
            prev->next = newNode;
            newNode->prev = &prev->data;
            newNode->next = NULL;
        } else {
            // Insert in middle
            newNode->prev = &prev->data;
            newNode->next = prev->next;
            prev->next->prev = &newNode->data;
            prev->next = newNode;
        }
    }
    return list;
}

// Function to free all nodes and records
void freeRecordList(record** list) {
    Node* temp = *list;
    while (temp != NULL) {
        Node* next = temp->next;
        free(temp);
        temp = next;
    }
    recordCount = 0;
    *list = NULL;
}

// Function to handle memory allocation failures
void* myMalloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL)
        printf("Memory allocation failed\n");
    return ptr;
}

