#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

// Structure for record
typedef struct {
    long offset;
    int key;
    int value;
} Record;

// Structure for timestamp
typedef struct {
    time_t timestamp;
} Timestamp;

// Structure for message string
typedef char Message[256];

// Function to process and persist records
void processAndPersistRecords() {
    // Declare variables
    Record *records = NULL;
    int recordCount = 0;
    Timestamp *timestamps = NULL;
    int timestampCount = 0;
    Message *messages = NULL;
    int messageCount = 0;

    // Read records from standard input
    while (1) {
        Record newRecord;
        scanf("%ld %d %d", &newRecord.offset, &newRecord.key, &newRecord.value);

        // Check for invalid or duplicate entries
        if (newRecord.key < 0 || newRecord.value < 0 || newRecord.key == recordCount) continue;

        // Initialize record and timestamp arrays if necessary
        if (recordCount >= 10000000) {
            // Resize arrays if necessary
            records = realloc(records, sizeof(Record) * (recordCount + 1));
            timestamps = realloc(timestamps, sizeof(Timestamp) * (timestampCount + 1));
            messages = realloc(messages, sizeof(Message) * (messageCount + 1));

            recordCount++;
            timestampCount++;
            messageCount++;
        }

        // Process and persist records
        if (recordCount < 10000000) {
            records[recordCount].offset = newRecord.offset;
            records[recordCount].key = newRecord.key;
            records[recordCount].value = newRecord.value;

            timestamps[timestampCount].timestamp = time(NULL);
            messages[messageCount] = "New record processed and persisted.";

            timestampCount++;
            messageCount++;
        }
    }

    // Deserialize data structure from file
    FILE *file = fopen("data.txt", "wb");
    if (file) {
        fwrite(&recordCount, sizeof(int), 1, file);
        fwrite(records, sizeof(Record), recordCount, file);

        fclose(file);
    } else {
