#include <string.h>

// Structure for a single entry
typedef struct {
    char* key;
    size_t length;
    double value;
} Entry;

// Structure for the hash table
typedef struct {
    Entry** entries; // Array of pointers to entries
    int capacity; // Current capacity of the hash table
    int size; // Number of actual entries in the hash table
    int loadFactorThreshold; // Threshold for resizing the hash table
} HashTable;

// Function to create a new hash table with initial capacity and threshold
HashTable* hashTableCreate(int capacity, int loadFactorThreshold) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->entries = (Entry**)calloc(capacity, sizeof(Entry*));
    table->capacity = capacity;
    table->size = 0;
    table->loadFactorThreshold = loadFactorThreshold;
    return table;
}

// Function to insert an entry into the hash table
void hashTableInsert(HashTable* table, Entry* entry) {
    int index = hashFunction(entry->key, table->capacity);
    for (int i = 0; i < table->capacity; i++) {
        if (table->entries[index]->key == NULL) {
            table->entries[index] = entry;
            table->size++;
            return;
        }
        index = (index + 1) % table->capacity;
    }
}

// Function to get an entry from the hash table
Entry* hashTableGet(HashTable* table, char* key) {
    int index = hashFunction(key, table->capacity);
    for (int i = 0; i < table->capacity; i++) {
        if (table->entries[index]->key != NULL && strcmp(table->entries[index]->key, key) == 0) {
            return table->entries[index];
        }
        index = (index + 1) % table->capacity;
    }
    return NULL;
}

// Function to resize the hash table
void hashTableResize(HashTable* table) {
    int newCapacity = table->capacity * 2;
    HashTable* newTable = hashTableCreate(newCapacity, table->loadFactorThreshold);
    for (int i = 0; i < table->capacity; i++) {
        Entry* entry = table->entries[i];
        while (entry != NULL) {
            int newIndex = hashFunction(entry->key, newCapacity);
            for (int j = 0; j < newCapacity; j++) {
                if (newTable->entries[newIndex]->key == NULL) {
                    newTable->entries[newIndex] = entry;
                    break;
                }
                newIndex = (newIndex + 1) % newCapacity;
            }
            entry = entry->next;
        }
    }
    free(table->entries);
    table->entries = newTable->entries;
    table->capacity = newCapacity;
}

// Simple hash function
int hashFunction(char* key, int capacity) {
    size_t sum = 0;
    for (size_t i = 0; i < strlen(key); i++) {
        sum += key[i];
    }
    return (int)(sum % capacity);
}
