#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* key;
    size_t length;
    double value;
} entry;

typedef enum {
    OK,
    WARNING,
    ERROR
} status;

typedef struct {
    double value;
    int timestamp;
    status stat;
} metric;

// Custom hash function for managing dynamic collections of entries
size_t customHash(const char* key) {
    size_t hash = 0;
    while (*key != '\0') {
        hash += (size_t)*key++;
    }
    return hash % 10000; // Scale to at least 10,000 entries
}

// Lock-free hash table implementation for managing dynamic collections of entries
typedef struct {
    int size;
    entry** table;
} hash_table;

hash_table* createHashTable(int size) {
    hash_table* ht = (hash_table*)malloc(sizeof(hash_table));
    ht->size = size;
    ht->table = (entry**)malloc(size * sizeof(entry*));
    for (int i = 0; i < size; i++) {
        ht->table[i] = NULL;
    }
    return ht;
}

void destroyHashTable(hash_table* ht) {
    for (int i = 0; i < ht->size; i++) {
        entry* node = ht->table[i];
        while (node != NULL) {
            entry* next = node->key;
            free(node);
            node = next;
        }
    }
    free(ht->table);
    free(ht);
}

int insertEntry(hash_table* ht, const char* key, size_t length, double value) {
    size_t hash = customHash(key);
    entry* node = (entry*)malloc(sizeof(entry));
    node->key = strdup(key);
    node->length = length;
    node->value = value;
    if (ht->table[hash] == NULL) {
        ht->table[hash] = node;
    } else {
        // Handle collision using chaining
        entry* current = ht->table[hash];
        while (current != NULL) {
            current = current->key;
        }
        current->next = node;
    }
    return 0; // Success
}

int deleteEntry(hash_table* ht, const char* key) {
    size_t hash = customHash(key);
    entry* node = ht->table[hash];
    while (node != NULL) {
        if (strcmp(node->key, key) == 0) {
            free(node->key);
            free(node);
            ht->table[hash] = node->next;
            return 0; // Success
        }
        node = node->next;
    }
    return -1; // Key not found
}

int lookupEntry(hash_table* ht, const char* key) {
    size_t hash = customHash(key);
    entry* node = ht->table[hash];
    while (node != NULL) {
        if (strcmp(node->key, key) == 0) {
            return 1; // Found
        }
        node = node->next;
    }
    return 0; // Key not found
}

// Dynamic array implementation for managing metrics
typedef struct {
    int size;
    metric* arr;
} metric_array;

metric_array* createMetricArray(int size) {
    metric_array* ma = (metric_array*)malloc(sizeof(metric_array));
    ma->size = size;
    ma->arr = (metric*)malloc(size * sizeof(metric));
    for (int i = 0; i < size; i++) {
        ma->arr[i].value = 0.0;
        ma->arr[i].timestamp = -1;
        ma->arr[i].stat = OK;
    }
    return ma;
}

void destroyMetricArray(metric_array* ma) {
    for (int i = 0; i < ma->size; i++) {
        free(&ma->arr[i]);
    }
    free(ma->arr);
    free(ma);
}

int addMetric(metric_array* ma, double value, int timestamp, status stat) {
    if (ma->size == 0) {
        return -1; // Array not initialized
    }
    for (int i = 0; i < ma->size; i++) {
        if (ma->arr[i].timestamp == -1) {
            ma->arr[i].value = value;
            ma->arr[i].timestamp = timestamp;
            ma->arr[i].stat = stat;
            return 0; // Success
        }
    }
    return -2; // No available slot for new metric
}

int filterMetrics(metric_array* ma) {
    // Print metrics with status "ERROR"
    for (int i = 0; i < ma->size; i++) {
