            printf("Metric %d: value=%f, timestamp=%d, status=ERROR\n", i, ma->arr[i].value, ma->arr[i].timestamp);
        }
    }
    return 0;
}

double calculateAverage(metric_array* ma) {
    double sum = 0.0;
    int count = 0;
    for (int i = 0; i < ma->size; i++) {
        if (ma->arr[i].stat != ERROR) {
            sum += ma->arr[i].value;
            count++;
        }
    }
    return sum / count;
}

// Serialization and deserialization functions
