// Function to manage dynamic collection of user profiles
void manageUserProfiles() {
    int i;
    UserProfile* profiles = NULL;
    FILE* file = fopen("user_profiles.bin", "wb");

    // Allocate initial memory for 10,000 profiles
    profiles = (UserProfile*)malloc(MAX_PROFILES * sizeof(UserProfile));
    if (!profiles) {
        printf("Memory allocation failed.\n");
        return;
    }

    while (1) {
        // Add new profile or update existing one
        int choice;
        printf("Enter 0 to add a new profile, 1 to update an existing profile, and 2 to exit: ");
        scanf("%d", &choice);

        switch (choice) {
            case 0:
                // Validate email address using external API
                char* email = malloc(strlen(gets("Enter the user's email: ")) + 1);
                strcpy(email, gets("Enter the user's email: "));

                int retryCount = 0;
                while (retryCount < 3) {
