                        // Add new profile to memory
                        profiles[getFreeIndex(profiles)].username = malloc(strlen(gets("Enter the username: ")) + 1);
                        strcpy(profiles[getFreeIndex(profiles)].username, gets("Enter the username: "));
                        profiles[getFreeIndex(profiles)].age = atoi(gets("Enter the user's age: "));
                        profiles[getFreeIndex(profiles)].email = email;

                        // Update cache
                        emailCache[getFreeIndex(profiles)] = 1;
                        cacheHitCount++;

                        break;
                    }

                    retryCount++;
                }

                if (retryCount >= 3) {
                    printf("Failed to validate email address.\n");
                } else {
                    printf("Profile added successfully.\n");
                }

                free(email);
                break;
            case 1:
                // Update existing profile
                char* updateUsername = malloc(strlen(gets("Enter the username of the profile to update: ")) + 1);
                strcpy(updateUsername, gets("Enter the username of the profile to update: "));

                int index = -1;
                for (i = 0; i < getUsedIndex(profiles); i++) {
                    if (!strcmp(profiles[i].username, updateUsername)) {
                        index = i;
                        break;
                    }
                }

                if (index != -1) {
                    char* email = malloc(strlen(gets("Enter the new email: ")) + 1);
                    strcpy(email, gets("Enter the new email: "));

                    // Validate email address using external API
                    int retryCount = 0;
                    while (retryCount < 3) {
                        if (validateEmailAPI(email)) {
                            // Update profile in memory
                            profiles[index].email = email;

                            break;
                        }

                        retryCount++;
                    }

                    if (retryCount >= 3) {
                        printf("Failed to validate email address.\n");
                    } else {
                        printf("Profile updated successfully.\n");
                    }

                    free(email);
                } else {
                    printf("Profile not found.\n");
                }

                free(updateUsername);
                break;
            case 2:
                // Exit the program
                freeMemory();
                return;
        }
    }
}

// Function to validate email address using external API
int validateEmailAPI(char* email) {
    // Simulate the API call and potential delay
    srand(time(NULL));
    int retryCount = 0;
    while (retryCount < 3) {
        if (rand() % 2 == 0) {
            // Email is valid, return success
            return 1;
        } else {
            // Email is invalid or API request failed, simulate the delay and retry
            sleep(rand() % 10 + 1);
            retryCount++;
        }
    }

    // Maximum retries exceeded, return failure
    return -1;
}

// Function to get a free index in the profile array
int getFreeIndex(UserProfile* profiles) {
    for (int i = 0; i < MAX_PROFILES; i++) {
        if (!profiles[i].username) {
            return i;
        }
    }

    // No free indices found, resize the array if necessary
    if (getUsedIndex(profiles) >= MAX_PROFILES / 2) {
        UserProfile* newProfiles = (UserProfile*)realloc(profiles, MAX_PROFILES * sizeof(UserProfile));
        if (!newProfiles) {
            printf("Memory allocation failed.\n");
            return -1;
        }

        profiles = newProfiles;
    }

    // No free indices found in the resized array, return -1
    return -1;
}

// Function to get the number of used indexes in the profile array
int getUsedIndex(UserProfile* profiles) {
    int i;
    for (i = 0; i < MAX_PROFILES; i++) {
        if (!profiles[i].username) {
            break;
        }
    }

    return i;
}

// Function to free all allocated memory when the data structure is no longer needed
void freeMemory() {
    // Free memory allocated for profiles
    for (int i = 0; i < getUsedIndex(profiles); i++) {
        if (profiles[i].username) {
            free(profiles[i].username);
        }

        if (profiles[i].email) {
            free(profiles[i].email);
        }
    }

    // Free memory allocated for profiles array
    free(profiles);
}

int main() {
    manageUserProfiles();
    return 0;
}
