#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 1000000
#define RECORD_KEY_RANGE 10000

typedef struct {
    int value;
} record_t;

typedef struct {
    long offset;
    int key;
    record_t data;
} record_container_t;

record_container_t* records = NULL;
int record_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Resize the records array when necessary
void resize_records(int new_size) {
    if (new_size <= 0) return;

    // Allocate a new array with the correct size
    record_container_t* new_records = malloc(new_size * sizeof(record_container_t));

    // Copy existing data to the new array
    for (int i = 0; i < record_count; i++) {
        memcpy(&new_records[i], &records[i], sizeof(record_container_t));
    }

    // Update the records pointer and count
    free(records);
    records = new_records;
    record_count = new_size;
}

// Insert a new record into the data structure
void add_record(int key, int value) {
    pthread_mutex_lock(&lock);

    if (record_count >= MAX_RECORDS) {
        // Resize the array if it's full
        resize_records(record_count + 1000);
    }

    records[record_count].offset = (long)record_count;
    records[record_count].key = key;
    records[record_count].data.value = value;

    record_count++;

    pthread_mutex_unlock(&lock);
}

// Load the data structure from a file
void load_records(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return;

    // Deserialize the data
    for (int i = 0; i < MAX_RECORDS; i++) {
        record_container_t record;
        fread(&record, sizeof(record), 1, file);
        // Update the records array
        add_record(record.key, record.data.value);
    }

    fclose(file);
}

// Save the data structure to a file
void save_records(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    // Serialize the data
    for (int i = 0; i < record_count; i++) {
        fwrite(&records[i], sizeof(record_container_t), 1, file);
    }

    fclose(file);
}

// Authenticate and authorize access to the data structure
void authenticate(int key) {
    pthread_mutex_lock(&lock);

    // Check if the key is within the allowed range
    if (key < 0 || key >= RECORD_KEY_RANGE) {
        printf("Invalid key\n");
        exit(1);
    }

    // Find the record with the matching key
    for (int i = 0; i < record_count; i++) {
        if (records[i].key == key) {
            // Allow access to the record
            pthread_mutex_unlock(&lock);
            return;
        }
    }

    printf("Key not found\n");
    exit(1);

}

int main() {
    load_records("data.bin");

    add_record(0, 10);
    add_record(1234, 20);
    add_record(RECORD_KEY_RANGE - 1, 30);

    authenticate(1234);

    save_records("data.bin");

    return 0;
}
