    pthread_mutex_lock(&profiles_lock);
    for (int i = 0; i < profiles_count; i++) {
        if (strcmp(profiles[i]->username, username) == 0) {
            free(profiles[i]->email);
            profiles[i]->email = strdup(email);
            break;
        }
    }
    pthread_mutex_unlock(&profiles_lock);
}

