record_t** expandGraphStructure(int* initialCapacity) {
    int capacity = *initialCapacity;
    record_t** graph = (record_t**)malloc(sizeof(record_t*) * capacity);

    // Initialize records with default values
    for (int i = 0; i < capacity; i++) {
        graph[i] = (record_t*)malloc(sizeof(record_t));
        graph[i]->key = -1;
        graph[i]->offset = -1;
        graph[i]->value = -1;
    }

    return graph;
}

void resizeGraphStructure(record_t** graph, int* capacity) {
    *capacity *= 2; // Double the current capacity
    record_t** newGraph = (record_t**)malloc(sizeof(record_t*) * *capacity);

    for (int i = 0; i < *capacity / 2; i++) {
        newGraph[i] = graph[i];
        graph[i]->key = -1;
        graph[i]->offset = -1;
        graph[i]->value = -1;
    }

    free(graph);
    graph = newGraph;
}

int main() {
    int initialCapacity = 1000; // Initial capacity
    record_t** graph = expandGraphStructure(&initialCapacity);

    return 0;
}
