typedef struct {
    char* value;
    size_t length;
} entry;

entry** processStrings(int maxRecords) {
    int recordCount = 0;
    entry** records = NULL;
    size_t* offsets = NULL;

    while (1) {
        char line[1024];
        fgets(line, sizeof(line), stdin);

        if (feof(stdin)) break;

        char* value = malloc(strlen(line));
        strcpy(value, line);
        int length = strlen(line);

        // Allocate memory for new record
        records = realloc(records, (recordCount + 1) * sizeof(entry*));
        offsets = realloc(offsets, (recordCount + 2) * sizeof(size_t));

        records[recordCount] = malloc(sizeof(entry));
        records[recordCount]->value = value;
        records[recordCount]->length = length;

        // Update offset
        offsets[recordCount] = recordCount;

        recordCount++;
    }

    return records;
}

void serializeRecords(entry** records, FILE* file) {
    fwrite(&recordCount, sizeof(int), 1, file);
    for (int i = 0; i < recordCount; i++) {
        size_t length = strlen(records[i]->value);
        fwrite(&length, sizeof(size_t), 1, file);
        fwrite(records[i]->value, 1, length, file);
    }
}

entry** deserializeRecords(FILE* file) {
    int recordCount;
    fread(&recordCount, sizeof(int), 1, file);

    entry** records = malloc(recordCount * sizeof(entry*));
    size_t* offsets = malloc((recordCount + 1) * sizeof(size_t));

    for (int i = 0; i < recordCount; i++) {
        size_t length;
        fread(&length, sizeof(size_t), 1, file);
        char* value = malloc(length + 1);
        fread(value, 1, length, file);
        value[length] = '\0';
        records[i] = malloc(sizeof(entry));
        records[i]->value = value;
        records[i]->length = length;
    }

    free(offsets);

    return records;
}

char* generateRandomHash(char* str) {
    // Use a standard library function to generate a random hash
    srand(time(NULL));
    char* hash = malloc(32);
    sprintf(hash, "%x", rand());
    return hash;
}

void printLongestString(entry** records) {
    entry* longest = NULL;
    size_t maxLength = 0;

    for (int i = 0; i < recordCount; i++) {
        if (records[i]->length > maxLength) {
            maxLength = records[i]->length;
            longest = records[i];
        }
    }

    printf("Longest string: %s\n", longest->value);
}

void freeRecords(entry** records) {
    for (int i = 0; i < recordCount; i++) {
        free(records[i]->value);
        free(records[i]);
    }
    free(records);
}
