        return processedInputString;
    } else {
        free(records);  // Free allocated memory if input string exceeds size limit
        free(offsets);
        free(keys);
        return NULL;  // Return NULL in case of error
    }

    // Step 5: Return Value
    char* result = (char*)malloc((strlen(inputString) + 2) * sizeof(char));  // +2 for the appended '/' and null-terminator
