record* allocate_memory(int numOffsets, int numKeys, int numRecords) {
    if (numOffsets <= 0 || numKeys <= 0 || numRecords <= 0) {
        LOG_ERROR("Invalid input parameters");
        return NULL;
    }

    // Initialize random seed
    srand(time(NULL));

    long* offsets = malloc(numOffsets * sizeof(long));
    int* keys = malloc(numKeys * sizeof(int));

    if (!offsets || !keys) {
        LOG_ERROR("Failed to allocate memory for offsets and keys");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize offsets and keys
    for (int i = 0; i < numOffsets; i++) {
        offsets[i] = rand() % 1001;
    }
    for (int i = 0; i < numKeys; i++) {
        keys[i] = rand() % 501 + 1;
    }

    record* records = malloc(numRecords * sizeof(record));

    if (!records) {
        LOG_ERROR("Failed to allocate memory for records");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize records
    for (int i = 0; i < numRecords; i++) {
        record temp;
        temp.offset = offsets[i % numOffsets];
        temp.value = rand() % 1000;
        records[i] = temp;
    }

    free(offsets);
    free(keys);

    return records;
}

void deallocate_memory(record* records) {
    if (!records) {
        return;
    }
    free(records);
}
