typedef struct {
    int key;
    long offset;
} Record;

Record* processIntegers() {
    // Initialize variables and data structure
    int numRecords = 0;
    Record** records = NULL;

    // Read integers from standard input and store them in the data structure
    while (1) {
        int integer;
        if (scanf("%d", &integer) != 1) break;

        // Allocate memory for a new record and copy the integer value
        Record* record = (Record*)malloc(sizeof(Record));
        record->key = integer;
        record->offset = 0; // Initialize offset for this record

        // Resize the array of records if necessary
        if (numRecords == 10) {
            numRecords *= 2;
            records = (Record**)realloc(records, sizeof(Record*) * numRecords);
        }

        // Store the new record in the array
        if (records[numRecords - 1] != NULL) {
            records[numRecords++] = record;
        } else {
            free(record); // Handle error: array not initialized yet
        }
    }

    return records;
}

void serializeData(Record** records, int numRecords) {
    FILE* file = fopen("data", "wb");
    if (file == NULL) {
        // Error handling for serialization failure
    } else {
        fwrite(&numRecords, sizeof(int), 1, file);
        for (int i = 0; i < numRecords; i++) {
            fwrite(&records[i]->key, sizeof(int), 1, file);
            fwrite(&records[i]->offset, sizeof(long), 1, file);
        }
        fclose(file);
    }
}

void deserializeData(Record** records) {
    FILE* file = fopen("data", "rb");
    if (file == NULL) {
        // Error handling for deserialization failure
    } else {
        int numRecords;
        fread(&numRecords, sizeof(int), 1, file);

        *records = (Record*)calloc(numRecords, sizeof(Record));
        for (int i = 0; i < numRecords; i++) {
            fread(&((*records)[i]->key), sizeof(int), 1, file);
            fread(&((*records)[i]->offset), sizeof(long), 1, file);
        }
        fclose(file);
    }
}

void printLargestInteger(Record** records, int numRecords) {
    int largestKey = -2147483648;
    for (int i = 0; i < numRecords; i++) {
        if (records[i]->key > largestKey) {
            largestKey = records[i]->key;
        }
    }
    printf("Largest integer: %d\n", largestKey);
}

