    int numRecords = 0;

    // Iterate through the array to find the largest key
    for (int i = 0; i < 10; i++) {
        if (records[i] != NULL) {
            numRecords = i + 1;
            break;
        }
    }

    printLargestInteger(&records, numRecords);
}

