    free(metrics);
}

int calculate_disjoint_sets(long *offsets, int keys[], record_t records[]) {
    // Initialize Union-Find data structure
    int max_key = 0;
    for (int i = 0; i < record_count; i++) {
        if (records[i].key > max_key) {
            max_key = records[i].key;
        }
    }
    int *parent = (int *)malloc((max_key + 1) * sizeof(int));
    int *rank = (int *)malloc((max_key + 1) * sizeof(int));

    // Initialize disjoint sets
    for (int i = 0; i <= max_key; i++) {
        parent[i] = i;
        rank[i] = 0;
    }

    // Find and union disjoint sets based on record keys
    int disjoint_sets = 0;
    for (int i = 0; i < record_count; i++) {
        int root1 = find(parent, records[i].key);
        int root2 = find(parent, records[(i + 1) % record_count].key);
        if (root1 != root2) {
            union_sets(parent, rank, root1, root2);
            disjoint_sets++;
        }
    }

    // Free allocated memory
    free(parent);
    free(rank);

    return disjoint_sets;
}

long get_time_taken() {
    // Calculate time taken in milliseconds
    struct timespec start, end;
    clock_gettime(CLOCK_REALTIME, &start);
    // Add your code here to measure the time taken
    clock_gettime(CLOCK_REALTIME, &end);
    long time_taken = (end.tv_nsec - start.tv_nsec) / 1000000;
    return time_taken;
}

int main() {
