// Function to read and write data from/to disk
void serialize_database(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return; // Handle I/O error

    int i;
    for (i = 0; i < NUM_SLOTS; i++) {
        Record record;
        if (database[i].key != 0) {
            memcpy(&record, &database[i], sizeof(Record));
            fwrite(&record, sizeof(Record), 1, file);
        }
    }

    fclose(file);
}

void deserialize_database(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return; // Handle I/O error

    int i;
    Record record;
    while (fread(&record, sizeof(Record), 1, file)) {
        database[i].key = record.key;
        database[i].value = record.value;
        i++;
    }

    fclose(file);
}

// Function to manage contention and concurrent access
void* lock_and_access(void* arg) {
    pthread_mutex_lock(&lock);
    // Perform read or write operation on the database
    pthread_mutex_unlock(&lock);
    return NULL;
}

