#define MAX_SHAPES 10000
#define RATE_LIMIT 100
#define RETRY_ATTEMPTS 3
#define EXPO_BACKOFF_FACTOR 2.0

typedef struct {
    int id;
    char type[20];
    float width, height;
    float radius;
    char color[20];
} Shape;

Shape* shapes[MAX_SHAPES];
int shapeCount = 0;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int rateLimitAttempts = 0;
float rateLimitBackoffTime = 1.0;

void manageShapeCollection(const char* jsonFile) {
    // Initialize JSON parser
    json_object* json = json_object_from_file(jsonFile);

    if (!json) return; // Handle error

    // Iterate through JSON objects
    json_object_iter* iter = json_object_iter_create(json);
    while (json_object_iter_has_more(iter)) {
        json_object* shapeJson = json_object_iter_next(iter);

        // Extract shape attributes
        char type[20];
        float width, height, radius;
        char color[20];
        int id = json_object_get_int(shapeJson, "id");
        strcpy(type, json_object_get_string(shapeJson, "type"));
        width = json_object_get_float(shapeJson, "width");
        height = json_object_get_float(shapeJson, "height");
        radius = json_object_get_float(shapeJson, "radius");
        strcpy(color, json_object_get_string(shapeJson, "color"));

        // Add shape to collection
        if (shapeCount < MAX_SHAPES) {
            shapes[shapeCount] = (Shape*)malloc(sizeof(Shape));
            shapes[shapeCount]->id = id;
            strcpy(shapes[shapeCount]->type, type);
            shapes[shapeCount]->width = width;
            shapes[shapeCount]->height = height;
            shapes[shapeCount]->radius = radius;
            strcpy(shapes[shapeCount]->color, color);
            shapeCount++;
        } else {
            // Handle overflow
        }

        json_object_put(shapeJson); // Release JSON object
    }

    json_object_iter_free(iter);
    json_object_free(json);
}

void addShape(int id, char* type, float width, float height, float radius, char* color) {
    pthread_mutex_lock(&mutex);

    if (shapeCount < MAX_SHAPES && rateLimitAttempts < RATE_LIMIT) {
        Shape* newShape = (Shape*)malloc(sizeof(Shape));
        newShape->id = id;
        strcpy(newShape->type, type);
        newShape->width = width;
        newShape->height = height;
        newShape->radius = radius;
        strcpy(newShape->color, color);
        shapeCount++;

        // Implement rate limiter and backoff
        if (shapeCount % RATE_LIMIT == 0) {
            rateLimitBackoffTime *= EXPO_BACKOFF_FACTOR;
            rateLimitAttempts = 0;
        }
    } else {
        if (rateLimitAttempts < RETRY_ATTEMPTS) {
            sleep(rateLimitBackoffTime);
            rateLimitBackoffTime /= EXPO_BACKOFF_FACTOR;
        } else {
            // Handle rate limit exceeded
        }
    }

    pthread_mutex_unlock(&mutex);
}

void removeShape(int id) {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < shapeCount; i++) {
        if (shapes[i]->id == id) {
            free(shapes[i]);
            memmove(shapes + i, shapes + i + 1, sizeof(Shape*) * (shapeCount - i - 1));
            shapeCount--;
            break;
        }
    }

    pthread_mutex_unlock(&mutex);
}

void queryShapes() {
    // Implement query functionality
}

int main() {
    manageShapeCollection("shapes.json");
    // Test add and remove functions
    return 0;
}
