#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a struct for each record
typedef struct {
    int key;
    long value;
} Record;

// Define a hash table structure with custom allocator
typedef struct {
    Record** buckets;
    int size;
    int count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    void* memory_pool;
} HashTable;

// Define a function to create and initialize the hash table
HashTable* hash_table_create(int initial_size) {
    // Allocate memory for the hash table
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->buckets = (Record**)calloc(initial_size, sizeof(Record*));
    table->size = initial_size;
    table->count = 0;
    pthread_mutex_init(&table->lock, NULL);
    pthread_cond_init(&table->cond, NULL);
    table->memory_pool = malloc(initial_size * sizeof(void*));

    return table;
}

// Define a function to add a new record to the hash table
void hash_table_insert(HashTable* table, int key, long value) {
    int index = key % table->size;
    Record* new_record = (Record*)malloc(sizeof(Record));
    new_record->key = key;
    new_record->value = value;

    pthread_mutex_lock(&table->lock);
    if (table->buckets[index] == NULL) {
        table->buckets[index] = new_record;
    } else {
        // Rehashing logic goes here
        // ...
    }
    table->count++;
    pthread_cond_signal(&table->cond);
    pthread_mutex_unlock(&table->lock);
}

// Define a function to query the hash table for a specific key
long hash_table_query(HashTable* table, int key) {
    int index = key % table->size;
    Record* record = table->buckets[index];
    while (record != NULL && record->key != key) {
        record = record->next;
    }
    if (record == NULL || record->key != key) {
        return -1; // Key not found
    }
    return record->value;
}

// Define a function to serialize the hash table to disk
void hash_table_serialize(HashTable* table, FILE* file) {
    pthread_mutex_lock(&table->lock);
    for (int i = 0; i < table->size; i++) {
        Record* record = table->buckets[i];
        while (record != NULL) {
            fwrite(&record->key, sizeof(int), 1, file);
            fwrite(&record->value, sizeof(long), 1, file);
            record = record->next;
        }
    }
    pthread_mutex_unlock(&table->lock);
}

// Define a function to deserialize the hash table from disk
void hash_table_deserialize(HashTable* table, FILE* file) {
    pthread_mutex_lock(&table->lock);
    int size;
    fread(&size, sizeof(int), 1, file);
    table->size = size;
    for (int i = 0; i < size; i++) {
        Record* record = (Record*)malloc(sizeof(Record));
        fread(&record->key, sizeof(int), 1, file);
        fread(&record->value, sizeof(long), 1, file);
        table->buckets[i] = record;
    }
    pthread_mutex_unlock(&table->lock);
}

// Define a function to print the contents of the hash table
void print_hash_table(HashTable* table) {
    for (int i = 0; i < table->size; i++) {
        Record* record = table->buckets[i];
        while (record != NULL) {
            printf("Key: %d, Value: %ld\n", record->key, record->value);
            record = record->next;
        }
    }
}

int main() {
    // Create the hash table
    HashTable* table = hash_table_create(100);

    // Read key-value pairs from standard input
    int key, value;
    while (scanf("%d %ld", &key, &value) == 2) {
        hash_table_insert(table, key, value);
    }

    // Print the contents of the hash table
    print_hash_table(table);

    // Serialize the hash table to disk
    FILE* file = fopen("data.bin", "wb");
    if (file != NULL) {
        hash_table_serialize(table, file);
        fclose(file);
    }

    // Deserialize the hash table from disk
    file = fopen("data.bin", "rb");
    if (file != NULL) {
        hash_table_deserialize(table, file);
        fclose(file);
    }

    return 0;
}
