void processAndManageMetrics(int max_metrics) {
    metric_t *metrics = NULL;
    int *timestamps = NULL;
    double *values = NULL;
    size_t current_size = 0, capacity = 10; // initial capacity
    size_t last_timestamp_index[capacity] = {0};

    for (int i = 0; i < max_metrics; i++) {
        if (i >= capacity) {
            // resize arrays and metrics when necessary to accommodate new data
            capacity *= 2;
            metrics = realloc(metrics, sizeof(metric_t) * capacity);
            timestamps = realloc(timestamps, sizeof(int) * capacity);
            values = realloc(values, sizeof(double) * capacity);
            last_timestamp_index = realloc(last_timestamp_index, sizeof(size_t) * capacity);

            for (int j = 0; j < current_size; j++) {
                last_timestamp_index[j] = i;
            }
        }

        // read a list of numerical values and timestamps from standard input
        int timestamp;
        double value;
        scanf("%d %lf", &timestamp, &value);

        if (metrics == NULL) {
            metrics = malloc(sizeof(metric_t));
            timestamps = malloc(sizeof(int));
            values = malloc(sizeof(double));

            current_size = 1;
        } else {
            metric_t *new_metrics = realloc(metrics, sizeof(metric_t) * (current_size + 1));
            int *new_timestamps = realloc(timestamps, sizeof(int) * (current_size + 1));
            double *new_values = realloc(values, sizeof(double) * (current_size + 1));

            new_metrics[current_size].value = value;
            new_metrics[current_size].timestamp = timestamp;
            new_metrics[current_size].status = ERROR; // initialize with default status

            for (int j = 0; j < current_size; j++) {
                last_timestamp_index[j] = new_metrics[j].timestamp;
            }

            metrics = new_metrics;
            timestamps = new_timestamps;
            values = new_values;

            current_size++;
        }
    }
}
