            int count = 0;

            while (fscanf(file, "%lf %d %s\n", &entries[count].value, &entries[count].timestamp, statusToString(&entries[count].status)) == 3) {
                if (count >= 1000000) {
                    break;
                }
                count++;
            }

            for (int i = 0; i < count; i++) {
                printf("%lf %d %s\n", entries[i].value, entries[i].timestamp, statusToString(entries[i].status));
            }
        }
    } else {
        MetricEntry *entries;

        while (fscanf(file, "%lf %d %s\n", &entries[count++].value, &entries[count++].timestamp, statusToString(&entries[count++].status)) == 3) {
            if (count >= 1000000) {
                break;
            }
        }

        for (int i = 0; i < count; i++) {
            printf("%lf %d %s\n", entries[i].value, entries[i].timestamp, statusToString(entries[i].status));
        }
    }

    fclose(file);
}

void filterMetrics(MetricEntry *entries, int start, int end) {
    for (int i = 0; i < count; i++) {
        if (entries[i].timestamp >= start && entries[i].timestamp <= end) {
            printf("%lf %d %s\n", entries[i].value, entries[i].timestamp, statusToString(entries[i].status));
        }
    }
}

double calculateAverageMetricValue(MetricEntry *entries, int count) {
    double sum = 0.0;

    for (int i = 0; i < count; i++) {
        sum += entries[i].value;
    }

    return sum / count;
}
