    for (i = 0; i < numRecords; i++) {
        fwrite(&records[i]->key, sizeof(int), 1, serializeFile);
        fwrite(&records[i]->offset, sizeof(long), 1, serializeFile);
        fwrite(&records[i]->value, sizeof(short), 1, serializeFile);
