        fread(&deserializedRecord.value, sizeof(short), 1, deserializeFile);
        // Process deserialized record
    }
    fclose(deserializeFile);

    // Free allocated memory
    for (i = 0; i < numRecords; i++) {
        free(records[i]);
    }
    free(records);
    free(offsets);
    free(keys);
}
