#define MAX_RECORDS 10000000
#define MAX_KEY 1000000
#define MAX_VALUE 1000

typedef struct {
    int key;
    long offset;
    int value;
} record;

record *records = NULL;
int num_records = 0;
int last_accessed[MAX_KEY] = {0};
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int cache_hits = 0, cache_misses = 0;
int total_keys = 0;
int max_key = 0;

void* fetch_records(void *arg) {
    int i, num_fetches = 0;
    int *start_key = (int*) arg;
    pthread_mutex_lock(&mutex);
    for(i = 0; i < MAX_RECORDS/10; i++) {
        if(records == NULL || records[num_records].key > max_key + i) {
            break;
        }
        num_fetches++;
    }
    pthread_mutex_unlock(&mutex);
    printf("Fetch %d records from %d to %d\n", num_fetches, *start_key, *start_key+num_fetches-1);
    return NULL;
}

int main() {
    pthread_t threads[MAX_RECORDS/10];
    int i;

    // Allocate memory for records
    records = (record*) malloc(MAX_RECORDS * sizeof(record));
    if(records == NULL) {
        printf("Memory allocation failed\n");
        exit(1);
    }

    // Initialize the first 1000 records with random values
    srand(time(NULL));
    for(i = 0; i < 1000; i++) {
        int key, value;
        do {
            key = rand() % MAX_KEY;
            value = rand() % MAX_VALUE;
        } while (value == 0);
        records[i].key = key;
        records[i].offset = i * sizeof(record);
        records[i].value = value;
    }

    // Create threads to fetch records from the external data source
    for(i = 0; i < MAX_RECORDS/10; i++) {
        int start_key = (i+1) * MAX_KEY / MAX_RECORDS;
        pthread_create(&threads[i], NULL, fetch_records, &start_key);
    }

    // Wait for all threads to finish
    for(i = 0; i < MAX_RECORDS/10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

