#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 1000
#define MAX_RECORDS 10e6
#define RECORD_KEY_SIZE sizeof(int)
#define RECORD_OFFSET_SIZE sizeof(long)
#define RECORD_TIMESTAMP_SIZE sizeof(double)

typedef struct {
    int key;
    long offset;
    double timestamp;
} record_t;

typedef struct {
    int capacity;
    int size;
    record_t *records;
    pthread_mutex_t mutex;
} data_structure_t;

data_structure_t* initialize_data_structure(int initial_capacity) {
    data_structure_t* ds = (data_structure_t*)malloc(sizeof(data_structure_t));
    ds->capacity = initial_capacity;
    ds->size = 0;
    ds->records = (record_t*)malloc(initial_capacity * sizeof(record_t));
    pthread_mutex_init(&ds->mutex, NULL);
    return ds;
}

int resize_data_structure(data_structure_t* ds) {
    int new_capacity = ds->capacity * 2;
    if (new_capacity > MAX_RECORDS) {
        new_capacity = MAX_RECORDS;
    }
    record_t* new_records = (record_t*)malloc(new_capacity * sizeof(record_t));
    memcpy(new_records, ds->records, ds->size * sizeof(record_t));
    free(ds->records);
    ds->records = new_records;
    ds->capacity = new_capacity;
    return 0;
}

int insert_record(data_structure_t* ds, int key, long offset, double timestamp) {
    if (ds->size >= ds->capacity) {
        resize_data_structure(ds);
    }
    record_t* new_record = (record_t*)malloc(sizeof(record_t));
    new_record->key = key;
    new_record->offset = offset;
    new_record->timestamp = timestamp;
    pthread_mutex_lock(&ds->mutex);
    if (ds->size >= ds->capacity) {
        return -1; // error: out of space
    }
    int idx = 0;
    while (idx < ds->size && ds->records[idx].key <= key) {
        idx++;
    }
    memcpy(&ds->records[idx], new_record, sizeof(record_t));
    free(new_record);
    ds->size++;
    pthread_mutex_unlock(&ds->mutex);
    return 0; // success
}

int lookup_record(data_structure_t* ds, int key, record_t** result) {
    pthread_mutex_lock(&ds->mutex);
    int idx = 0;
    while (idx < ds->size && ds->records[idx].key <= key) {
        if (ds->records[idx].key == key) {
            *result = &ds->records[idx];
            pthread_mutex_unlock(&ds->mutex);
            return 0; // found
        }
        idx++;
    }
    pthread_mutex_unlock(&ds->mutex);
    return -1; // not found
}

int update_record(data_structure_t* ds, int key, long offset, double timestamp) {
    record_t* result = NULL;
    if (lookup_record(ds, key, &result)) {
        return -1; // error: not found
    }
    result->offset = offset;
    result->timestamp = timestamp;
    return 0; // success
}

int delete_record(data_structure_t* ds, int key) {
    record_t* result = NULL;
    if (lookup_record(ds, key, &result)) {
        return -1; // error: not found
    }
    int idx = 0;
    while (idx < ds->size && ds->records[idx].key <= key) {
        if (ds->records[idx].key == key) {
            memcpy(&ds->records[idx], &ds->records[idx + 1], (ds->size - idx - 1) * sizeof(record_t));
            free(&ds->records[ds->size - 1]);
            ds->size--;
            return 0; // success
        }
        idx++;
    }
    return -1; // error: not found
}

int serialize_data_structure(data_structure_t* ds, FILE* file) {
    fwrite(&ds->capacity, sizeof(int), 1, file);
    fwrite(&ds->size, sizeof(int), 1, file);
    for (int i = 0; i < ds->size; i++) {
        fwrite(&ds->records[i].key, RECORD_KEY_SIZE, 1, file);
        fwrite(&ds->records[i].offset, RECORD_OFFSET_SIZE, 1, file);
        fwrite(&ds->records[i].timestamp, RECORD_TIMESTAMP_SIZE, 1, file);
    }
    return 0;
}

int deserialize_data_structure(data_structure_t* ds, FILE* file) {
    int capacity = 0;
    fread(&capacity, sizeof(int), 1, file);
    int size = 0;
    fread(&size, sizeof(int), 1, file);
    if (size > capacity) {
        return -1; // error: corrupted data
    }
    ds->records = (record_t*)malloc(size * sizeof(record_t));
    for (int i = 0; i < size; i++) {
        fread(&ds->records[i].key, RECORD_KEY_SIZE, 1, file);
        fread(&ds->records[i].offset, RECORD_OFFSET_SIZE, 1, file);
        fread(&ds->records[i].timestamp, RECORD_TIMESTAMP_SIZE, 1, file);
    }
    return 0;
}

int compact_data_structure(data_structure_t* ds) {
    int new_size = 0;
    for (int i = 0; i < ds->size; i++) {
        if (ds->records[i].key != 0) {
            new_size++;
        } else {
            free(&ds->records[i]);
        }
    }
    record_t* new_records = (record_t*)malloc(new_size * sizeof(record_t));
    int j = 0;
    for (int i = 0; i < ds->size; i++) {
        if (ds->records[i].key != 0) {
            new_records[j] = ds->records[i];
            j++;
        }
    }
    free(ds->records);
    ds->records = new_records;
    ds->size = new_size;
    return 0;
}

void* custom_allocator(void* ptr) {
    // implement a custom allocator
    return NULL;
}

int main() {
    data_structure_t* ds = initialize_data_structure(INITIAL_CAPACITY);
    // test insert, lookup, update, delete operations
    // serialize and deserialize the data structure
    // perform compaction
    return 0;
}
