#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the maximum number of records (10 million)
#define MAX_RECORDS 10000000

// Define the record structure
typedef struct {
    long offset;
    int key;
    double timestamp;
    int value;
    char timestamp_str[64];
} Record;

// Define the key index structure
typedef struct {
    int last_accessed_index;
    Record* records;
} KeyIndex;

// Define the memory pool for record structures
void* record_pool = NULL;
size_t record_pool_size = 0;
int record_pool_capacity = 0;

// Initialize the memory pool for record structures
void init_record_pool() {
    if (record_pool) return;

    record_pool_size = sizeof(Record);
    record_pool_capacity = 1024; // Start with a moderate size

    record_pool = malloc(record_pool_capacity * record_pool_size);
    memset(record_pool, 0, record_pool_size * record_pool_capacity);
}

// Allocate a new record from the memory pool
Record* allocate_record() {
    if (record_pool) {
        for (int i = 0; i < record_pool_capacity; i++) {
            Record* record = (Record*) ((char*) record_pool + i * record_pool_size);
            if (!record->key && !record->timestamp_str[0]) { // Check for unallocated records
                return record;
            }
        }
    }

    // If no available records, dynamically allocate a new pool
    size_t new_capacity = record_pool_capacity * 2; // Double the capacity
    void* new_pool = realloc(record_pool, new_capacity * record_pool_size);
    if (!new_pool) {
        printf("Memory allocation failed!\n");
        exit(EXIT_FAILURE);
    }

    record_pool = new_pool;
    record_pool_capacity = new_capacity;

    return (Record*) ((char*) record_pool + (record_pool_capacity - 1) * record_pool_size);
}

// Free a record from the memory pool
void free_record(Record* record) {
    // Reset the record's fields to indicate it's no longer in use
    record->key = 0;
    memset(record->timestamp_str, 0, sizeof(record->timestamp_str));

    // If we're out of records, shrink the pool if necessary
    for (int i = 0; i < record_pool_capacity; i++) {
        Record* prev_record = (Record*) ((char*) record_pool + i * record_pool_size);
        if (!prev_record->key && !prev_record->timestamp_str[0]) { // Check for unallocated records
            record_pool_capacity--;
            break;
        }
    }
}

// Serialize the data structure to a file for persistence
void serialize_data(struct {
    int last_accessed_index;
    Record* records;
} key_index, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        printf("Error opening file!\n");
        exit(EXIT_FAILURE);
    }

    fwrite(&key_index.last_accessed_index, sizeof(key_index.last_accessed_index), 1, file);
    size_t num_records = strlen((const char*) key_index.records);
    fwrite(&num_records, sizeof(num_records), 1, file);
    fwrite(key_index.records, record_pool_size, num_records, file);

    fclose(file);
}

// Deserialize the data structure from a file
void deserialize_data(struct {
    int last_accessed_index;
    Record* records;
} *key_index, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        printf("Error opening file!\n");
        exit(EXIT_FAILURE);
    }

    fread(&key_index->last_accessed_index, sizeof(key_index->last_accessed_index), 1, file);
    size_t num_records;
    fread(&num_records, sizeof(num_records), 1, file);
    key_index->records = malloc(num_records * record_pool_size);
    fread(key_index->records, record_pool_size, num_records, file);

    fclose(file);
}

// Track the last accessed index of each key
