    int new_key_range = 0;
    for (int i = 0; i < num_records; i++) {
        if (graph_params[i] > new_key_range) {
            new_key_range = graph_params[i];
        }
    }

    // Resize arrays and records as needed to accommodate new data
    record_t *new_records = NULL;
    int *new_keys = NULL;
    long *new_offsets = NULL;

    while (*records_size < num_records + 1000) {
        new_records = (record_t *) realloc(*records, sizeof(record_t) * (*records_size + 1000));
        new_keys = (int *) realloc(*keys, sizeof(int) * (*records_size + 1000));
        new_offsets = (long *) realloc(*offsets, sizeof(long) * (*records_size + 1000));

        if (!new_records || !new_keys || !new_offsets) {
            printf("Memory allocation failed.\n");
            return;
        }

        *records = new_records;
        *keys = new_keys;
        *offsets = new_offsets;

        // Initialize secondary structure to track last accessed index of each key
        int *key_indices = (int *) calloc(*records_size + 1000, sizeof(int));
        if (!key_indices) {
            printf("Memory allocation failed.\n");
            return;
        }

        for (int i = 0; i < *records_size; i++) {
            key_indices[i] = i;
        }
        // Add new records
        for (int i = *records_size; i < *records_size + 1000; i++) {
            int random_key = rand() % max_key_range;
            long random_offset = rand() % (new_key_range + 1);
            short random_value = (short) rand();

            new_records[i].key = random_key;
            new_records[i].offset = random_offset;
            new_records[i].value = random_value;

            new_keys[i] = random_key;
            new_offsets[i] = random_offset;
        }

        free(key_indices);
    }
}

void setRecordValue(record_t *records, int records_size) {
    for (int i = 0; i < records_size; i++) {
        int random_value = (short) rand();
        records[i].value = random_value;
    }
}

int findLargestKey(record_t *records, int records_size) {
    int max_key = records[0].key;
    for (int i = 1; i < records_size; i++) {
        if (records[i].key > max_key) {
            max_key = records[i].key;
        }
    }
    return max_key;
}

void serializeRecords(record_t *records, int records_size, FILE* file) {
    for (int i = 0; i < records_size; i++) {
        fprintf(file, "%d %ld %hd\n", records[i].key, records[i].offset, records[i].value);
    }
}

record_t *deserializeRecords(FILE* file) {
    record_t *records = NULL;
    int records_size = 0;

    FILE* temp_file = tmpfile();
    if (temp_file == NULL) {
        printf("Failed to create temporary file.\n");
        return NULL;
    }

    // Read serialized data from file
    while (1) {
        char buffer[256];
        size_t bytes_read = fread(buffer, 1, sizeof(buffer), file);
        if (bytes_read < sizeof(buffer)) {
            break;
        }

        // Parse and deserialize record data
        int key = atoi(strtok(buffer, " "));
        long offset = atol(strtok(NULL, " "));
        short value = (short) atoi(strtok(NULL, " "));

        // Resize array as needed to accommodate new records
        if (!records) {
            records_size = 1;
            records = (record_t *) malloc(sizeof(record_t));
        } else {
            record_t *new_records = (record_t *) realloc(records, sizeof(record_t) * ++records_size);
            records = new_records;
        }

        records[records_size - 1].key = key;
        records[records_size - 1].offset = offset;
        records[records_size - 1].value = value;
    }

    fclose(temp_file);

    return records;
}

int main() {
    int num_records = 0; // Initialize number of records
    int *keys = NULL;      // Array for storing record keys
    long *offsets = NULL;   // Array for storing record offsets

    // Allocate initial memory for arrays and records
    record_t *records = (record_t *) malloc(sizeof(record_t));
    keys = (int *) malloc(sizeof(int));
