        scanf("%d", &num_records);

        if (num_records <= 0) break;

        expandGraphStructure(&records, &num_records, &keys, &offsets);
    }

    // Set random value for each record
    setRecordValue(records, num_records);

    // Find and print the largest integer in the array
    int max_key = findLargestKey(records, num_records);
    printf("The largest key is: %d\n", max_key);

    // Serialize data structure to a file for persistence
    FILE* serialized_file = fopen("graph_data.txt", "w");
    if (serialized_file == NULL) {
        printf("Failed to open file 'graph_data.txt'.\n");
    } else {
        serializeRecords(records, num_records, serialized_file);
        fclose(serialized_file);
    }

    // Deserialize data structure from a file
    FILE* deserialized_file = fopen("graph_data.txt", "r");
    if (deserialized_file == NULL) {
        printf("Failed to open file 'graph_data.txt'.\n");
    } else {
        record_t *deserialized_records = deserializeRecords(deserialized_file);
        fclose(deserialized_file);

        // Print deserialized data
