void dynamicProfileManager(int num_profiles) {
    u_char* ip_address = malloc(16);
    int status_code = 0;
    char* hostname = "example.com";
    struct addrinfo hints, *res;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Initialize arrays
    char** emails = (char**)malloc(num_profiles * sizeof(char*));
    char** names = (char**)malloc(num_profiles * sizeof(char*));
    profile** preferences = (profile**)malloc(num_profiles * sizeof(profile*));
    long* file_sizes = malloc(num_profiles * sizeof(long));
