        int level;
        char* message;
    };
    logEntry** logs = (logEntry**)malloc(num_profiles * sizeof(logEntry*));
    for(int i = 0; i < num_profiles; i++) {
        logs[i] = malloc(sizeof(struct logEntry));
        logs[i]->timestamp = time(NULL);
        logs[i]->level = rand() % 3;
        logs[i]->message = (char*)malloc(1024 * sizeof(char));
    }

    // Set up DNS resolution
    getaddrinfo(hostname, NULL, &hints, &res);
    inet_ntop(AF_INET, &((struct sockaddr_in *)res->ai_addr)->sin_addr, ip_address, 16);

    // Manage profiles
