        profile* p = (profile*)malloc(sizeof(profile));
        p->name = malloc(1024 * sizeof(char));
        p->email = malloc(256 * sizeof(char));
        p->preferences = rand() % 2;

        // Add to arrays
        emails[i] = p->email;
        names[i] = p->name;
        preferences[i] = p;
        file_sizes[i] = i * 1024;
    }

    // Serialize data structure to file
    FILE* file = fopen("profiles.bin", "wb");
    fwrite(&num_profiles, sizeof(int), 1, file);
    for(int i = 0; i < num_profiles; i++) {
        fwrite(names[i], sizeof(char), strlen(names[i]) + 1, file);
        fwrite(emails[i], sizeof(char), strlen(emails[i]) + 1, file);
        fwrite(&preferences[i]->preferences, sizeof(int), 1, file);
        fwrite(&file_sizes[i], sizeof(long), 1, file);
    }

    // Deserialize data structure from file
    int num_profiles_deserialized;
    fread(&num_profiles_deserialized, sizeof(int), 1, file);
    for(int i = 0; i < num_profiles_deserialized; i++) {
        profile* p = (profile*)malloc(sizeof(profile));
        fread(names[i], sizeof(char), strlen(names[i]) + 1, file);
        fread(emails[i], sizeof(char), strlen(emails[i]) + 1, file);
        fread(&p->preferences, sizeof(int), 1, file);
        fread(&file_sizes[i], sizeof(long), 1, file);
    }

    // Filter and print profiles
    for(int i = 0; i < num_profiles_deserialized; i++) {
        if(p->preferences & NOTIFICATIONS_ENABLED) {
            printf("Profile %s has notifications enabled.\n", names[i]);
        }
    }

    // Calculate total number of profiles meeting criteria
    int count = 0;
    for(int i = 0; i < num_profiles_deserialized; i++) {
        if(p->preferences & NOTIFICATIONS_ENABLED) {
            count++;
        }
    }

    printf("Total number of profiles with notifications enabled: %d\n", count);

    // Log operations
    logEntry* log_entry;
    for(int i = 0; i < num_profiles_deserialized; i++) {
        log_entry = logs[i];
        printf("Timestamp: %ld, Level: %d, Message: %s\n", log_entry->timestamp, log_entry->level, log_entry->message);
    }

    // Clean up
    free(ip_address);
    for(int i = 0; i < num_profiles_deserialized; i++) {
        free(names[i]);
        free(emails[i]);
        free((void*)preferences[i]);
        free(logs[i]->message);
    }
    free(names);
    free(emails);
    free(preferences);
    free(file_sizes);

    pthread_mutex_destroy(&lock);
}
