void initMemoryPool(MemoryPool* pool, size_t size) {
    pool->base = malloc(size);
    pool->size = size;
}

// Deallocate the memory pool
void deallocateMemoryPool(MemoryPool* pool) {
    free(pool->base);
    pool->size = 0;
}

// Define a record structure
typedef struct {
    int key;
    long offset;
    short value;
} Record;

// Manage dynamic data and expand graph
void manageDynamicDataAndExpandGraph(Record** records, size_t* capacity, size_t newCapacity) {
    // Allocate memory for the new capacity
    void* newData = malloc(newCapacity * sizeof(Record));

    // Copy existing records to the new array
    if (*capacity > 0) {
        memcpy(newData, *records, *capacity * sizeof(Record));
    }

    // Update the record array and capacity
    deallocateMemoryPool((MemoryPool*)*records);
    *records = (Record*)newData;
    *capacity = newCapacity;
}

