#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define structure for record
typedef struct {
    int key;
    long *offsets;
} Record;

// Define structure for data store
typedef struct {
    Record **records;
    int size;
    pthread_mutex_t lock;
} DataStore;

// Function to create a new data store with initial capacity
DataStore* newDataStore(int initCapacity) {
    DataStore* ds = (DataStore*)malloc(sizeof(DataStore));
    ds->records = (Record**)malloc(initCapacity * sizeof(Record*));
    ds->size = 0;
    pthread_mutex_init(&ds->lock, NULL);
    return ds;
}

// Function to add a new record to the data store
void addRecord(DataStore* ds, int key, long *offsets) {
    pthread_mutex_lock(&ds->lock);

    // If the data store is full, resize it
    if (ds->size >= ds->records->size) {
        ds->records = (Record**)realloc(ds->records, (ds->size + 1) * sizeof(Record*));
    }

    Record* newRecord = (Record*)malloc(sizeof(Record));
    newRecord->key = key;
    newRecord->offsets = offsets;
    ds->records[ds->size] = newRecord;
    ds->size++;

    pthread_mutex_unlock(&ds->lock);
}

// Function to search for a record in the data store
void* searchRecord(DataStore* ds, int key) {
    pthread_mutex_lock(&ds->lock);

    // Search for the record
    for (int i = 0; i < ds->size; i++) {
        if (ds->records[i]->key == key) {
            pthread_mutex_unlock(&ds->lock);
            return ds->records[i];
        }
    }

    pthread_mutex_unlock(&ds->lock);
    return NULL;
}

// Function to free all allocated resources
void freeDataStore(DataStore* ds) {
    for (int i = 0; i < ds->size; i++) {
        free(ds->records[i]->offsets);
        free(ds->records[i]);
    }
    free(ds->records);
    pthread_mutex_destroy(&ds->lock);
    free(ds);
}

// Example usage:
int main() {
    DataStore* ds = newDataStore(1000);

    // Add some records
    long offset1 = 123456789;
    long offset2 = 987654321;
    addRecord(ds, 1, &offset1);
    addRecord(ds, 2, &offset2);

    // Search for a record
    Record* foundRecord = searchRecord(ds, 1);

    if (foundRecord) {
        printf("Found record with key %d and offset %ld\n", foundRecord->key, *foundRecord->offsets);
    } else {
        printf("No record found with key 1\n");
    }

    // Free the data store
    freeDataStore(ds);

    return 0;
}

