        prefs[i] = strdup(preferences[pref_idx]);
    }
    new_profile->prefs = prefs;
    new_profile->pref_count = MAX_PREFS;

    if (profile_count >= (int)(profiles->size)) {
        profiles = resize_profiles(profiles->size * 2);
    }

    profiles[profile_count++] = new_profile;
}

void serialize_profiles(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        return;  // handle error
    }

    for (int i = 0; i < profile_count; i++) {
        fwrite(profiles[i].username, sizeof(char), strlen(profiles[i].username), file);
        fwrite(&profiles[i]->email, sizeof(char), strlen(profiles[i]->email), file);
        int pref_count = profiles[i]->pref_count;
