char* serialize_event(Event* event) {
    json_object* json_event = json_object_new_object();
    json_object_object_add(json_event, "timestamp", json_object_new_int(event->timestamp));
    json_object_object_add(json_event, "status_code", json_object_new_int(event->status_code));
    if(event->message != NULL) {
        json_object_object_add(json_event, "message", json_string_new(event->message));
    }
    char* json_str = json_object_to_json_string(json_event);
    json_decref(json_event);
    return json_str;
}

Event* deserialize_event(char* json_str) {
    json_object* json_event = json_string_to_json_object(json_str);
    Event* event = (Event*) malloc(sizeof(Event));
    event->timestamp = json_object_get_int(json_event, "timestamp");
    event->status_code = json_object_get_int(json_event, "status_code");
    if(json_object_has_key(json_event, "message")) {
        char* message = json_object_get_string(json_event, "message");
        event->message = strdup(message);
    } else
        event->message = NULL;
    return event;
}

void free_events(Event** events, int num_events) {
    for(int i = 0; i < num_events; i++) {
        free_event(events[i]);
    }
    free(events);
