#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    unsigned int id;
    char* name;
} item;

item* collection = NULL;
unsigned int collection_size = 0;

// Cache mechanism
#define CACHE_SIZE 10
item** cache = NULL;
int cache_count = 0;
pthread_mutex_t cache_mutex = PTHREAD_MUTEX_INITIALIZER;

void cache_add(item* item) {
    pthread_mutex_lock(&cache_mutex);
    if (cache_count < CACHE_SIZE) {
        cache[cache_count++] = item;
    } else {
        // Evict the least recently used item
        for (int i = 0; i < cache_count - 1; i++) {
            cache[i] = cache[i + 1];
        }
        cache[--cache_count] = item;
    }
    pthread_mutex_unlock(&cache_mutex);
}

item* cache_get(unsigned int id) {
    pthread_mutex_lock(&cache_mutex);
    for (int i = 0; i < cache_count; i++) {
        if (cache[i]->id == id) {
            // Return the cached item
            pthread_mutex_unlock(&cache_mutex);
            return cache[i];
        }
    }
    pthread_mutex_unlock(&cache_mutex);
    return NULL;
}

// Iterator interface
void* iterator(void*) {
    for (unsigned int i = 0; i < collection_size; i++) {
        item* item = &collection[i];
        printf("id: %u, name: %s\n", item->id, item->name);
        // Cache frequently accessed items
        if (i % 10 == 0) { // Adjust the frequency based on cache size and eviction policy
            cache_add(item);
        }
    }
    return NULL;
}

void add_item(item* new_item) {
    collection = (item*) realloc(collection, (collection_size + 1) * sizeof(item));
    if (!collection) {
        printf("Memory allocation failed\n");
        return;
    }
    new_item->name = (char*) malloc(strlen(new_item->name) + 1);
    strcpy(new_item->name, new_item->name);
    collection[collection_size++] = *new_item;
}

void free_items() {
    for (unsigned int i = 0; i < collection_size; i++) {
        free(collection[i].name);
    }
    free(collection);
}

int main() {
    // Initialize the cache
    cache = (item**) malloc(CACHE_SIZE * sizeof(item*));
    pthread_mutex_init(&cache_mutex, NULL);

    // Add items to the collection
    item new_item1 = {1, "Item 1"};
    item new_item2 = {2, "Item 2"};
    add_item(&new_item1);
    add_item(&new_item2);

    // Start an iterator thread
    pthread_t iterator_thread;
    pthread_create(&iterator_thread, NULL, iterator, NULL);

    // Simulate concurrent access from multiple threads
    pthread_t thread1, thread2, thread3;
    pthread_create(&thread1, NULL, () -> {
        for (unsigned int i = 0; i < collection_size; i++) {
            item* item = &collection[i];
            printf("Thread 1: id: %u, name: %s\n", item->id, item->name);
        }
    }, NULL);
    pthread_create(&thread2, NULL, () -> {
        for (unsigned int i = 0; i < collection_size; i++) {
            item* item = &collection[i];
            printf("Thread 2: id: %u, name: %s\n", item->id, item->name);
        }
    }, NULL);
    pthread_create(&thread3, NULL, () -> {
        for (unsigned int i = 0; i < collection_size; i++) {
            item* item = &collection[i];
            printf("Thread 3: id: %u, name: %s\n", item->id, item->name);
        }
    }, NULL);

    // Wait for threads to complete
    pthread_join(iterator_thread, NULL);
    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);
    pthread_join(thread3, NULL);

    // Free allocated memory
    free_items();

    return 0;
}

