```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    double amount;
    char type[16];
    char* description;
} transaction_t;

// Function to dynamically allocate memory for a new transaction structure
transaction_t* create_transaction(double amount, const char* type) {
    transaction_t* tx = (transaction_t*)malloc(sizeof(transaction_t));
    if (!tx) return NULL; // Handle allocation failure

    tx->amount = amount;
    strcpy(tx->type, type);

    // Dynamically allocate memory for the description
    int desc_len = 64; // Initial size for the description string
    tx->description = (char*)malloc((desc_len + 1) * sizeof(char));
    if (!tx->description) return NULL; // Handle allocation failure

    tx->description[0] = '\0'; // Initialize with null character

    return tx;
}

// Function to free memory allocated for a transaction structure
void destroy_transaction(transaction_t* tx) {
    if (tx) {
        if (tx->description) free(tx->description);
        free(tx); // Free the transaction structure itself
    }
}

// Function to serialize an array of transactions into a CSV format
char* serialize_transactions(const transaction_t** transactions, int num_transactions) {
    char* csv = NULL; // Initialize with null
    int total_len = 0;

    for (int i = 0; i < num_transactions; i++) {
        transaction_t* tx = transactions[i];
        // Calculate the length of the CSV line for this transaction
        int line_len = sprintf(NULL, "%.2f,\"%s\",\"%s\"", tx->amount, tx->type, tx->description) + 1;
        total_len += line_len;

        // Reallocate memory if necessary (e.g., when concatenating strings)
        char* temp_csv = (char*)realloc(csv, total_len * sizeof(char));
        if (!temp_csv) return NULL; // Handle allocation failure

        csv = temp_csv;
        // Append the CSV line for this transaction
        sprintf(csv + strlen(csv), "%.2f,\"%s\",\"%s\"\n", tx->amount, tx->type, tx->description);
        csv += line_len;
    }

    return csv;
}

// Function to deserialize a CSV string into an array of transactions
transaction_t** deserialize_transactions(const char* csv) {
    // Initialize the result array and pointer
    int num_transactions = 0; // Count the number of transactions
    char* token = strtok(csv, "\n"); // Split by newline character

    transaction_t** transactions = NULL;
    while (token) {
        // Create a new transaction structure
        transaction_t* tx = create_transaction(atof(strtok(token, ",")), strtok(NULL, "\""));
        if (!tx) return NULL; // Handle allocation failure

        // Update the result array and pointer
        int i = num_transactions++;
        transactions = (transaction_t**)realloc(transactions, (num_transactions + 1) * sizeof(transaction_t*));
        if (!transactions) return NULL; // Handle allocation failure
        transactions[num_transactions - 1] = tx;

        token = strtok(NULL, "\n"); // Move to the next line in the CSV string
    }

    return transactions;
}

int main() {
    transaction_t* transactions[] = {create_transaction(10.5, "purchase"), create_transaction(20.0, "refund")};

    char* csv = serialize_transactions(transactions, 2);
    printf("%s\n", csv);

    transaction_t** deserialized_transactions = deserialize_transactions(csv);

    for (int i = 0; i < num_transactions; i++) {
        destroy_transaction(deserialized_transactions[i]);
    }
    free(deserialized_transactions);

    return 0;
}
