#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int key;
    long offset;
    short value;
} record;

void expandGraphStructure(int numRecords) {
    record **records = NULL;
    int *keys = NULL;
    long *offsets = NULL;
    int currentCapacity = 10; // Initial capacity
    int currentSize = 0;

    // Allocate memory for arrays
    records = (record **)malloc(currentCapacity * sizeof(record *));
    keys = (int *)malloc(currentCapacity * sizeof(int));
    offsets = (long *)malloc(currentCapacity * sizeof(long));

    // Initialize arrays
    for (int i = 0; i < currentCapacity; i++) {
        records[i] = (record *)malloc(sizeof(record));
        keys[i] = -1;
        offsets[i] = -1;
    }

    // Main loop to add new records
    for (int i = 0; i < numRecords; i++) {
        int key = rand() % 10000; // Generate random key within range [0, 10000]
        long offset = rand() % 1000000; // Generate random offset within range [0, 1000000]
        short value = (short)rand(); // Generate random value

        // Check for uniqueness of key and offset
        if (findKeyOffset(keys, currentSize, key) && findKeyOffset(offsets, currentSize, offset)) {
            // Add new record
            records[currentSize]->key = key;
            records[currentSize]->offset = offset;
            records[currentSize]->value = value;

            keys[currentSize] = key;
            offsets[currentSize++] = offset;

            // Resize arrays if necessary
            if (currentSize >= currentCapacity) {
                currentCapacity *= 2; // Double capacity for efficiency
                int *tempKeys = (int *)malloc(currentCapacity * sizeof(int));
                long *tempOffsets = (long *)malloc(currentCapacity * sizeof(long));
                record **tempRecords = (record **)malloc(currentCapacity * sizeof(record *));
                memcpy(tempKeys, keys, currentSize * sizeof(int));
                memcpy(tempOffsets, offsets, currentSize * sizeof(long));
                for (int i = 0; i < currentSize; i++) {
                    tempRecords[i] = records[i];
                }
                free(keys);
                free(offsets);
                for (int i = 0; i < currentCapacity; i++) {
                    free(records[i]);
                }
                free(records);
                records = tempRecords;
                keys = tempKeys;
                offsets = tempOffsets;
            }
        } else {
            // Handle memory allocation failure
            printf("Memory allocation failed. Aborting.\n");
            exit(1);
        }
    }

    // Free allocated memory
    for (int i = 0; i < currentSize; i++) {
        free(records[i]);
    }
    free(records);
    free(keys);
    free(offsets);
}
