void* createArrays(size_t maxSize, size_t* numRecords, int** keys, long** offsets, Record*** records) {
    // Calculate the total number of elements in each array
    size_t totalRecords = (size_t) (maxSize / sizeof(Record));

    // Dynamically allocate memory for arrays and initialize records
    *keys = malloc(totalRecords * sizeof(int));
    *offsets = malloc(totalRecords * sizeof(long));
    *records = malloc(totalRecords * sizeof(Record));

    if (*keys == NULL || *offsets == NULL || *records == NULL) {
        // Log error and return failure
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    // Initialize arrays and record values
    for (size_t i = 0; i < totalRecords; i++) {
        (*keys)[i] = i % 100 + 1;
        (*offsets)[i] = i * 2;
        (*records)[i].value = i % 10;
    }

    // Set the number of records created
    *numRecords = totalRecords;

    return NULL;  // No error, indicate success
}

int main() {
    size_t maxSize = 1000;
    size_t numRecords;
    int* keys;
    long* offsets;
    Record** records;

    createArrays(maxSize, &numRecords, &keys, &offsets, &records);

    // Use the allocated arrays...
    for (size_t i = 0; i < numRecords; i++) {
        printf("Key: %d, Offset: %ld, Value: %d\n", keys[i], offsets[i], records[i]->value);
    }

    // Free allocated memory
    free(keys);
    free(offsets);
    for (size_t i = 0; i < numRecords; i++) {
        free(records[i]);
    }
    free(records);

    return 0;
}

