    scanf("%d", &num_records);

    // Allocate memory for the records array and initialize linked list
    record* records = (record*)malloc(num_records * sizeof(record));
    record* head = NULL;

    // Allocate memory for offset and id arrays
    long* offsets = (long*)malloc(num_records * sizeof(long));
    uint64_t* ids = (uint64_t*)malloc(num_records * sizeof(uint64_t));

    // Initialize last accessed indices for key and timestamp arrays
    int last_key_index = -1;
    int last_timestamp_index = -1;

    // Initialize secondary structures to track last accessed index of each key and timestamp
    int* last_accessed_key_indices = (int*)malloc(num_records * sizeof(int));
    int* last_accessed_timestamp_indices = (int*)malloc(num_records * sizeof(int));

    for (int i = 0; i < num_records; i++) {
