        if (rand() % 2) {
            records[i].int_key = rand() % 100;
        } else {
            records[i].float_field = (float)(rand() / (double)RAND_MAX);
        }

        // Update last accessed index of each key and timestamp
        last_accessed_key_indices[records[i].int_key] = i;
        last_accessed_timestamp_indices[records[i].offset] = i;

        // Add record to linked list
        if (!head) {
            head = &records[i];
        } else {
            record* current = head;
            while (current->next) {
                current = current->next;
            }
            current->next = &records[i];
        }

        // Update offset and id arrays
        offsets[i] = records[i].offset;
        ids[i] = records[i].id;
    }

    // Serialize data structure to file for persistence
    FILE* file = fopen("data.bin", "wb");
    fwrite(&num_records, sizeof(int), 1, file);
    fwrite(records, num_records * sizeof(record), 1, file);
    fclose(file);

