#define MAX_PROFILES 10000
#define PROFILE_SIZE sizeof(profile_t)

typedef struct {
    int id;
    char name[64];
    int age;
    char* email;
    time_t last_login;
} profile_t;

profile_t* profiles = NULL;
int num_profiles = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to serialize the profiles
void serialize_profiles(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) return;

    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_profiles; i++) {
        fwrite(&profiles[i], PROFILE_SIZE, 1, file);
    }
    pthread_mutex_unlock(&mutex);

    fclose(file);
}

// Function to deserialize the profiles
void deserialize_profiles(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) return;

    profile_t temp;
    int i = 0;
    pthread_mutex_lock(&mutex);
    while (fread(&temp, PROFILE_SIZE, 1, file)) {
        profiles[i] = temp;
        i++;
    }
    num_profiles = i;
    pthread_mutex_unlock(&mutex);

    fclose(file);
}

// Function to add a new profile
void add_profile(int id, char* name, int age, char* email) {
    profile_t* new_profile = (profile_t*)malloc(PROFILE_SIZE);
    if (new_profile == NULL) return;

    new_profile->id = id;
    strcpy(new_profile->name, name);
    new_profile->age = age;
    new_profile->email = (char*)malloc(strlen(email) + 1);
    strcpy(new_profile->email, email);

    pthread_mutex_lock(&mutex);
    if (num_profiles < MAX_PROFILES) {
        profiles[num_profiles] = *new_profile;
        num_profiles++;
    }
    pthread_mutex_unlock(&mutex);

    free(new_profile->email);
    free(new_profile);
}

// Function to update the last login timestamp for a profile
void update_last_login(int id, time_t timestamp) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_profiles; i++) {
        if (profiles[i].id == id) {
            profiles[i].last_login = timestamp;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}
