    for (int i = 0; i < num_records; i++) {
        printf("Key: %d, Value: %d\n", records[i].key, records[i].value);
    }
    pthread_mutex_unlock(&mutex);
}

int main() {
    pthread_t threads[10];

    // create and initialize the data structure
    for (int i = 0; i < MAX_RECORDS; i++) {
