    char* changelog;
} ReleaseNote;

typedef struct Node {
    ReleaseNote release;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    int count;
    int downloadCount[1000];
} ReleaseNotes;

ReleaseNotes* initReleaseNotes() {
    ReleaseNotes* rn = (ReleaseNotes*)malloc(sizeof(ReleaseNotes));
    rn->head = NULL;
    rn->count = 0;
    for(int i=0; i<1000; i++) rn->downloadCount[i] = 0;
    return rn;
}

void freeReleaseNotes(ReleaseNotes* rn) {
    Node* temp = rn->head;
    while(temp != NULL) {
        Node* nextTemp = temp->next;
        free(temp);
        temp = nextTemp;
    }
    free(rn);
}

int addReleaseNote(ReleaseNotes* rn, int id, const char* version, time_t date, const char* changelog) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->release.id = id;
    strcpy(newNode->release.version, version);
    newNode->release.date = date;
    newNode->release.changelog = strdup(changelog);
    newNode->next = rn->head;
    rn->head = newNode;
    rn->count++;
    return 0;
}

void serializeReleaseNotes(ReleaseNotes* rn, FILE* file) {
    Node* temp = rn->head;
    while(temp != NULL) {
        fprintf(file, "%d %s %ld %s\n", temp->release.id, temp->release.version, (long int)temp->release.date, temp->release.changelog);
        free(temp->release.changelog);
        temp = temp->next;
    }
}

ReleaseNotes* deserializeReleaseNotes(FILE* file, ReleaseNotes* rn) {
    char buffer[1024];
    while(fgets(buffer, 1024, file)) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        sscanf(buffer, "%d %s %ld %s", &newNode->release.id, newNode->release.version, &newNode->release.date, newNode->release.changelog);
        newNode->next = rn->head;
        rn->head = newNode;
        rn->count++;
    }
    return rn;
}
