```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef enum { ONLINE, OFFLINE, PENDING } DeviceStatus;

typedef struct {
    int id;
    char* ip_address;
    char* mac_address;
    DeviceStatus status;
} Device;

Device* device_list = NULL;
int num_devices = 0;

// Function to initialize the array of devices
void init_device_list() {
    if (!device_list) {
        device_list = (Device*)malloc(sizeof(Device));
        num_devices = 1;
    } else {
        Device* new_array = (Device*)realloc(device_list, (num_devices + 1) * sizeof(Device));
        if (new_array == NULL) {
            printf("Memory allocation failed\n");
            return;
        }
        device_list = new_array;
        num_devices++;
    }
}

// Function to add a new device
void add_device(int id, char* ip_address, char* mac_address, DeviceStatus status) {
    if (num_devices >= 50000) {
        printf("Device list full. Cannot add more devices.\n");
        return;
    }

    if (id < 0 || strlen(ip_address) > 15 || strlen(mac_address) > 17) {
        printf("Invalid device details\n");
        return;
    }

    Device* new_device = (Device*)malloc(sizeof(Device));
    new_device->id = id;
    new_device->ip_address = strdup(ip_address);
    new_device->mac_address = strdup(mac_address);
    new_device->status = status;

    if (!device_list) {
        device_list = new_device;
        num_devices++;
    } else {
        Device* temp = device_list;
        while (num_devices > 1 && temp->id < id) {
            temp = temp + 1;
        }
        // Shift existing devices to make room for the new device
        memmove(temp + 1, temp, sizeof(Device) * (num_devices - id));
        temp = temp + id;
        *temp = *new_device;
    }
}

// Function to remove a device
void remove_device(int id) {
    if (!device_list || num_devices < id) {
        printf("Device not found\n");
        return;
    }

    Device* temp = device_list;
    for (int i = 0; i < id; i++) {
        temp++;
    }

    // Shift devices to fill the gap
    memmove(temp, temp + 1, sizeof(Device) * (num_devices - id));
    num_devices--;
}

// Function to update a device's status
void update_device_status(int id, DeviceStatus status) {
    if (!device_list || num_devices < id) {
        printf("Device not found\n");
        return;
    }

    Device* temp = device_list;
    for (int i = 0; i < id; i++) {
        temp++;
    }

    temp->status = status;
}

// Function to print the device list
void print_device_list() {
    if (!device_list) {
        printf("No devices in the list\n");
        return;
    }

    Device* temp = device_list;
    for (int i = 0; i < num_devices; i++) {
        printf("ID: %d, IP Address: %s, MAC Address: %s, Status: ", temp->id, temp->ip_address, temp->mac_address);
        switch (temp->status) {
            case ONLINE:
                printf("Online\n");
                break;
            case OFFLINE:
                printf("Offline\n");
                break;
            case PENDING:
                printf("Pending\n");
                break;
        }
        temp++;
    }
}
