#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int key;
    long offset;
    short value;
} record;

void expandGraphStructure(record **records, int *numRecords, int capacity) {
    if (*numRecords >= capacity) {
        capacity *= 2; // double the capacity
        *records = (record *)realloc(*records, sizeof(record) * capacity);
        if (!*records) {
            printf("Memory allocation failed\n");
            return;
        }
    }

    for (int i = *numRecords; i < capacity; i++) {
        record newRecord;
        newRecord.key = i;
        newRecord.offset = (long)i * 2;
        newRecord.value = rand() % 100; // random value within the range
        (*records)[i] = newRecord;
    }

    *numRecords = capacity;
}

void serializeData(record *records, int numRecords) {
    FILE *file = fopen("data.bin", "wb");
    if (!file) {
        printf("Failed to open file\n");
        return;
    }

    fwrite(&numRecords, sizeof(int), 1, file);
    for (int i = 0; i < numRecords; i++) {
        fwrite(&records[i], sizeof(record), 1, file);
    }

    fclose(file);
}

record *deserializeData() {
    record *data;
    int numRecords;

    FILE *file = fopen("data.bin", "rb");
    if (!file) {
        printf("Failed to open file\n");
        return NULL;
    }

    fread(&numRecords, sizeof(int), 1, file);
    data = (record *)malloc(sizeof(record) * numRecords);
    for (int i = 0; i < numRecords; i++) {
        fread(&data[i], sizeof(record), 1, file);
    }

    fclose(file);

    return data;
}

void findLargestKey(record *records, int numRecords) {
    int largest = records[0].key;
    for (int i = 1; i < numRecords; i++) {
        if (records[i].key > largest) {
            largest = records[i].key;
        }
    }

    printf("Largest key: %d\n", largest);
}

void printData(record *records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        printf("Key: %d, Offset: %ld, Value: %hd\n", records[i].key, records[i].offset, records[i].value);
    }
}

int main() {
    record *records;
    int numRecords;

    // initialize data
    records = (record *)malloc(sizeof(record));
    numRecords = 0;

    while (1) {
        int key;
        scanf("%d", &key);

        if (key == -1) {
            break;
        }

        expandGraphStructure(&records, &numRecords, numRecords + 1);

        printf("Added record: Key %d, Offset %ld, Value %hd\n", records[numRecords-1].key, records[numRecords-1].offset, records[numRecords-1].value);
    }

    serializeData(records, numRecords);

    // free memory
    free(records);

    return 0;
}

