#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define RECORD_SIZE sizeof(record)

typedef struct record {
    int key;
    long offset;
} record;

record** arrays;
int num_arrays = 0;
pthread_mutex_t mutex;
FILE* log_file = NULL;

void init_arrays(int num_records) {
    array = (record**)malloc(num_records * sizeof(record*));
    for (int i = 0; i < num_records; i++) {
        array[i] = (record*)malloc(RECORD_SIZE);
    }
}

void free_arrays() {
    for (int i = 0; i < num_arrays; i++) {
        free(array[i]);
    }
    free(array);

    fclose(log_file);
}

int record_new(int key, long offset) {
    pthread_mutex_lock(&mutex);
    record* new_record = (record*)malloc(RECORD_SIZE);
    new_record->key = key;
    new_record->offset = offset;
    array[num_arrays++] = new_record;
    pthread_mutex_unlock(&mutex);

    return num_arrays - 1;
}

void record_free(int index) {
    pthread_mutex_lock(&mutex);
    free(array[index]);
    for (int i = index; i < num_arrays - 1; i++) {
        array[i] = array[i + 1];
    }
    num_arrays--;
    pthread_mutex_unlock(&mutex);
}

int update_record(int key, long offset) {
    pthread_mutex_lock(&mutex);

    // Handle real-time updates
    for (int i = 0; i < num_arrays; i++) {
        if (array[i]->key == key) {
            array[i]->offset = offset;
            break;
        }
    }

    pthread_mutex_unlock(&mutex);
}

void* thread_func(void* arg) {
    // Perform external data source updates
    for (int i = 0; i < 1000; i++) {
        int key = rand() % 10000;
        long offset = (long)rand();
        record_new(key, offset);
        // Log performance metrics
        if ((i + 1) % 10 == 0) {
            FILE* log_file = fopen("log.txt", "a");
            fprintf(log_file, "Peak memory usage: %d KB\n", num_arrays * RECORD_SIZE / 1024);
            fclose(log_file);
        }
    }

    return NULL;
}

int main() {
    // Initialize arrays
    init_arrays(10000);

    // Create and join threads for updating records in parallel
    pthread_t thread;
    pthread_create(&thread, NULL, thread_func, NULL);
    pthread_join(thread, NULL);

    // Handle memory exhaustion
    if (num_arrays > 5000) {
        record_free(0);
    }

    free_arrays();

    return 0;
}

