        (*keys)[i] = rand() % 100;
    }

    return 0;
}

// Function to handle memory allocation failures gracefully
void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Error: Memory allocation failed in %s:%d\n", __FILE__, __LINE__);
        exit(1);
    }
    return ptr;
}

// Function to free memory safely
void safe_free(void* ptr) {
    if (ptr != NULL) {
        free(ptr);
    }
}
