    offsets = (int*)malloc((count + 1) * sizeof(int));
    lastAccessed = (int**)malloc(MAX_KEY_RANGE * sizeof(int*));
    for (int i = 0; i < MAX_KEY_RANGE; i++)
        lastAccessed[i] = (int*)malloc(sizeof(int));
