#define MAX_RECORDS 10000
#define LOG_FILE "data.log"
#define THREAD_SAFE_LOCK pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    int key;
    int value;
} Record;

Record* records[MAX_RECORDS];
int record_count = 0;
int total_operations = 0;

// Serialize data to file, compressing with zlib
void serialize_to_file() {
    FILE* f = fopen(LOG_FILE, "wb");
    if (!f) {
        LOG_ERROR("Failed to open log file for writing.");
        return;
    }

    int bytes_written = 0;
    int record_size = sizeof(Record);
    char buffer[MAX_RECORDS * record_size];

    for (int i = 0; i < record_count; i++) {
        Record* record = &records[i];
        memcpy(&buffer[bytes_written], record, record_size);
        bytes_written += record_size;
    }

    // Compress data using zlib
    uLongf compressed_data;
    int compression_result = compress((Bytef*) buffer, &bytes_written, &compressed_data);
    if (compression_result != Z_OK) {
        LOG_ERROR("Compression failed.");
    } else {
        fwrite(&compressed_data, 1, bytes_written, f);
    }

    fclose(f);
}

// Deserialize data from file, decompressing with zlib
void deserialize_from_file() {
    FILE* f = fopen(LOG_FILE, "rb");
    if (!f) {
        LOG_ERROR("Failed to open log file for reading.");
        return;
    }

    int bytes_read = 0;
    char buffer[MAX_RECORDS * sizeof(Record)];
    uLongf compressed_data;

    // Decompress data using zlib
    int decompression_result = uncompress((Bytef*) &buffer, &bytes_read, (Bytef*) f, 1024);
    if (decompression_result != Z_OK) {
        LOG_ERROR("Decompression failed.");
    } else {
        record_count = bytes_read / sizeof(Record);

        for (int i = 0; i < record_count; i++) {
            Record* record = &records[i];
            memcpy(record, &buffer[i * sizeof(Record)], sizeof(Record));
        }
    }

    fclose(f);
}

// Thread-safe access methods
void read_record(int key) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < record_count; i++) {
        if (records[i]->key == key) {
            // Handle read operation
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}

void write_record(Record* record) {
    pthread_mutex_lock(&lock);

    records[record_count++] = record;

    pthread_mutex_unlock(&lock);
}

// Periodic integrity check in background thread
void* integrity_thread(void*) {
    while (1) {
        // Check data integrity and log any errors or inconsistencies
        if (!check_data_integrity()) {
            LOG_ERROR("Data integrity error detected.");
        }

        sleep(5);  // Adjust this interval based on your application's requirements
    }
}

// Initialize the data structure
void init() {
    pthread_create(&integrity_thread_id, NULL, integrity_thread, NULL);

    for (int i = 0; i < MAX_RECORDS; i++) {
        records[i] = (Record*) malloc(sizeof(Record));
    }
}

// Clean up and free resources
void cleanup() {
    for (int i = 0; i < record_count; i++) {
        free(records[i]);
    }

    pthread_mutex_destroy(&lock);
}
