    for (int i = 0; i < size; i++) {
        parent[i] = i;
    }
    int *rank = (int *)malloc(size * sizeof(int));
    for (int i = 0; i < size; i++) {
        rank[i] = 0;
    }

    // Allocate memory for arrays of 'long' values representing offsets
    long *offsets = (long *)malloc(size * sizeof(long));

    // Implement serialization and deserialization mechanisms for data structure
    FILE *fp = fopen("your_file_name", "wb");
    if (fp) {
        fwrite(metrics, size * sizeof(metric_t), 1, fp);
        fclose(fp);
    }

    // Support filtering and printing metrics with a specific status
