        for (int i = 0; i < size; i++) {
            if (statuses[i] == status) {
                printf("Timestamp: %d, Value: %.2f, Status: %s\n", timestamps[i], values[i], (status == OK ? "OK" : "ERROR"));
            }
        }
    }

    // Support calculating the average metric value
    double calculateAverage() {
        double sum = 0;
        for (int i = 0; i < size; i++) {
            sum += values[i];
        }
        return sum / size;
    }

    // Return list of disjoint sets, total number of disjoint sets, and time taken
    int *disjointSets = (int *)malloc(size * sizeof(int));
    for (int i = 0; i < size; i++) {
        disjointSets[i] = parent[i];
    }
    int numDisjointSets = 0;
    for (int i = 0; i < size; i++) {
        if (parent[i] != i) {
            numDisjointSets++;
            // Handle error
        }
    }

    double timeTaken = (double)(clock() - clock()) / CLOCKS_PER_SEC * 1000;

    return disjointSets, numDisjointSets, timeTaken;
}
