#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct node {
    double value;
    struct node* next;
} Node;

typedef struct {
    int capacity;
    int size;
    double** table;
} HashTable;

Node* new_node(double value);
HashTable* new_hash_table(int capacity);

void insert(HashTable* hash, double key, double value);
double* search(HashTable* hash, double key);
void update(HashTable* hash, double key, double value);
void delete(HashTable* hash, double key);

int main() {
    return 0;
}

Node* new_node(double value) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->value = value;
    node->next = NULL;
    return node;
}

HashTable* new_hash_table(int capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->capacity = capacity;
    table->size = 0;
    table->table = (double**)calloc(capacity, sizeof(double*));
    for (int i = 0; i < capacity; i++) {
        table->table[i] = NULL;
    }
    return table;
}

void insert(HashTable* hash, double key, double value) {
    int index = hash_function(hash->capacity, key);
    Node* node = new_node(value);
    if (hash->table[index] == NULL) {
        hash->table[index] = node;
    } else {
        node->next = hash->table[index];
        hash->table[index] = node;
    }
    hash->size++;
}

double* search(HashTable* hash, double key) {
    int index = hash_function(hash->capacity, key);
    Node* node = hash->table[index];
    while (node != NULL && node->value != key) {
        node = node->next;
    }
    if (node == NULL) return NULL;
    return &node->value;
}

void update(HashTable* hash, double key, double value) {
    int index = hash_function(hash->capacity, key);
    Node* node = hash->table[index];
    while (node != NULL && node->value != key) {
        node = node->next;
    }
    if (node != NULL) node->value = value;
}

void delete(HashTable* hash, double key) {
    int index = hash_function(hash->capacity, key);
    Node* prev = NULL;
    Node* node = hash->table[index];
    while (node != NULL && node->value != key) {
        prev = node;
        node = node->next;
    }
    if (node != NULL) {
        if (prev == NULL) {
            hash->table[index] = node->next;
        } else {
            prev->next = node->next;
        }
        free(node);
    }
}

int hash_function(int capacity, double key) {
    return (key * 127 + 1) % capacity;
}
