typedef enum {
    DEBUG,
    INFO,
    WARNING,
    ERROR,
} LogLevel;

typedef struct {
    int timestamp;
    char message[256];
    LogLevel level;
} LogEntry;

void handleAndStoreLogEntries(int numNewEntries, int** timestamps, char*** messages, LogEntry*** logEntries, int* lastTimestampIndex) {
    // Calculate the number of new entries needed
    int newNumEntries = 1000000 - *numNewEntries;

    if (*numNewEntries + newNumEntries > 10000000) {
        printf("Error: Too many log entries. Limit exceeded.\n");
        return;
    }

    // Allocate memory for the new entries
    *timestamps = realloc(*timestamps, (*lastTimestampIndex + 1 + newNumEntries) * sizeof(int));
    *messages = realloc(*messages, (*lastTimestampIndex + 1 + newNumEntries) * sizeof(char*));
    *logEntries = realloc(*logEntries, (*lastTimestampIndex + 1 + newNumEntries) * sizeof(LogEntry*));

    // Initialize the new entries
    for (int i = *lastTimestampIndex; i < *lastTimestampIndex + newNumEntries; i++) {
        (*timestamps)[i] = i;
        char* message = malloc(256);
        sprintf(message, "This is a log entry with timestamp %d and level DEBUG", i);
        (*messages)[i] = message;
        (*logEntries)[i] = malloc(sizeof(LogEntry));
        (*logEntries)[i]->timestamp = i;
        strcpy((*logEntries)[i]->message, message);
        (*logEntries)[i]->level = DEBUG;
    }

    // Update the last timestamp index
    *lastTimestampIndex += newNumEntries;
}

void printLogEntries(LogLevel level) {
    for (int i = 0; i < 10000000; i++) {
        if ((*logEntries)[i]->level <= level) {
            printf("Timestamp: %d, Message: %s, Level: %s\n", (*logEntries)[i]->timestamp, (*logEntries)[i]->message, logLevelToString((*logEntries)[i]->level));
        }
    }
}

char* logLevelToString(LogLevel level) {
    switch (level) {
        case DEBUG:
            return "DEBUG";
        case INFO:
            return "INFO";
        case WARNING:
            return "WARNING";
        case ERROR:
            return "ERROR";
    }
}
