#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <sys/types.h>
#include <pthread.h>

// Define the maximum number of records allowed
#define MAX_RECORDS 1000000

// Define the key range limit
#define KEY_RANGE 18446744073709551615ULL

typedef struct {
    uint64_t key;
    long offset;
    time_t timestamp;
} record;

record *records = NULL;
size_t num_records = 0;
size_t records_capacity = MAX_RECORDS;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
time_t last_access_time[MAX_RECORDS];

void *allocate_record(size_t count) {
    size_t i;
    record *new_records = (record *)malloc(count * sizeof(record));
    for (i = 0; i < count; i++) {
        new_records[i].key = rand() % KEY_RANGE;
        new_records[i].offset = rand();
        new_records[i].timestamp = time(NULL);
    }
    return new_records;
}

void resize_records(size_t new_capacity) {
    record *new_records = allocate_record(new_capacity);
    size_t i, j = 0;

    pthread_mutex_lock(&mutex);

    for (i = 0; i < records_capacity; i++) {
        if (j < num_records && i < new_capacity) {
            new_records[i] = records[i];
            last_access_time[i] = last_access_time[j++];
        } else {
            break;
        }
    }

    free(records);
    records = new_records;
    records_capacity = new_capacity;

    pthread_mutex_unlock(&mutex);
}

void serialize_data(struct FILE *file) {
    size_t i;

    pthread_mutex_lock(&mutex);

    fwrite(&num_records, sizeof(size_t), 1, file);
    for (i = 0; i < num_records; i++) {
        fwrite(&records[i].key, sizeof(uint64_t), 1, file);
        fwrite(&records[i].offset, sizeof(long), 1, file);
        fwrite(&records[i].timestamp, sizeof(time_t), 1, file);
    }

    pthread_mutex_unlock(&mutex);
}

void deserialize_data(struct FILE *file) {
    size_t i;
    record temp;

    pthread_mutex_lock(&mutex);

    fread(&num_records, sizeof(size_t), 1, file);
    for (i = 0; i < num_records; i++) {
        fread(&temp.key, sizeof(uint64_t), 1, file);
        fread(&temp.offset, sizeof(long), 1, file);
        fread(&temp.timestamp, sizeof(time_t), 1, file);
        records[i] = temp;
    }

    pthread_mutex_unlock(&mutex);
}

void prune_records() {
    size_t i;

    pthread_mutex_lock(&mutex);

    for (i = 0; i < num_records; i++) {
        if ((time(NULL) - records[i].timestamp) > 3600) { // prune records that are older than an hour
            memmove(&records[i], &records[i + 1], (num_records - i - 1) * sizeof(record));
            num_records--;
            i--; // re-check the same position
        }
    }

    pthread_mutex_unlock(&mutex);
}

void free_memory() {
    if (records != NULL) {
        free(records);
    }
}
