#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    int key;
    long offset;
    time_t timestamp;
} Record;

// Define the dynamic array structure
typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

// Initialize a new dynamic array with the given initial capacity
DynamicArray* dynamic_array_init(size_t initial_capacity) {
    DynamicArray* arr = (DynamicArray*)malloc(sizeof(DynamicArray));
    arr->records = (Record*)calloc(initial_capacity, sizeof(Record));
    arr->capacity = initial_capacity;
    arr->size = 0;
    pthread_mutex_init(&arr->mutex, NULL);
    return arr;
}

// Resize the dynamic array if necessary
void dynamic_array_resize(DynamicArray* arr, size_t new_size) {
    if (new_size > arr->capacity) {
        arr->records = (Record*)realloc(arr->records, new_size * sizeof(Record));
        arr->capacity = new_size;
    }
}

// Add a record to the dynamic array
void dynamic_array_add(DynamicArray* arr, Record* record) {
    pthread_mutex_lock(&arr->mutex);
    if (arr->size == arr->capacity) {
        dynamic_array_resize(arr, arr->capacity * 2 + 1);
    }
    arr->records[arr->size] = *record;
    arr->size++;
    pthread_mutex_unlock(&arr->mutex);
}

// Retrieve a record from the dynamic array
Record* dynamic_array_get(DynamicArray* arr, int key) {
    pthread_mutex_lock(&arr->mutex);
    for (int i = 0; i < arr->size; i++) {
