#include <string.h>

// Define task structure
typedef struct {
    int id;
    char status[10];
    int priority;
} Task;

// Define task management system
typedef struct {
    int size;
    Task** tasks;
    pthread_mutex_t lock;
} TaskManager;

TaskManager* create_task_manager(int size) {
    TaskManager* manager = (TaskManager*)malloc(sizeof(TaskManager));
    manager->size = size;
    manager->tasks = (Task**)calloc(size, sizeof(Task*));
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void add_task(TaskManager* manager, Task task) {
    pthread_mutex_lock(&manager->lock);
    int i;
    for(i = 0; i < manager->size; i++) {
        if(manager->tasks[i] == NULL) {
            manager->tasks[i] = (Task*)malloc(sizeof(Task));
            *manager->tasks[i] = task;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void update_task(TaskManager* manager, int id, char new_status[10], int priority) {
    pthread_mutex_lock(&manager->lock);
    int i;
    for(i = 0; i < manager->size; i++) {
        if(manager->tasks[i]->id == id) {
            strcpy(manager->tasks[i]->status, new_status);
            manager->tasks[i]->priority = priority;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void delete_task(TaskManager* manager, int id) {
    pthread_mutex_lock(&manager->lock);
    int i;
    for(i = 0; i < manager->size; i++) {
        if(manager->tasks[i]->id == id) {
            free(manager->tasks[i]);
            manager->tasks[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

// Serialize tasks to file
void serialize_tasks(TaskManager* manager, char* filename) {
    FILE* file = fopen(filename, "wb");
    if(file == NULL) {
        return;
    }
    int i;
    for(i = 0; i < manager->size; i++) {
        if(manager->tasks[i] != NULL) {
            fwrite(&manager->tasks[i]->id, sizeof(int), 1, file);
            fwrite(manager->tasks[i]->status, sizeof(char), strlen(manager->tasks[i]->status), file);
            fwrite(&manager->tasks[i]->priority, sizeof(int), 1, file);
        }
    }
    fclose(file);
}

// Deserialize tasks from file
TaskManager* deserialize_tasks(char* filename) {
    TaskManager* manager = create_task_manager(1000); // Initialize with a default size
    FILE* file = fopen(filename, "rb");
    if(file == NULL) {
        return NULL;
    }
    int i;
    for(i = 0; i < manager->size; i++) {
        if(fread(&manager->tasks[i]->id, sizeof(int), 1, file) != 1) {
            break;
        }
        manager->tasks[i]->status = (char*)malloc(strlen(manager->tasks[i]->status)+1);
        fread(manager->tasks[i]->status, sizeof(char), strlen(manager->tasks[i]->status), file);
        manager->tasks[i]->status[strlen(manager->tasks[i]->status)] = '\0';
        fread(&manager->tasks[i]->priority, sizeof(int), 1, file);
    }
    fclose(file);
    return manager;
}

void free_task_manager(TaskManager* manager) {
    int i;
    for(i = 0; i < manager->size; i++) {
        if(manager->tasks[i] != NULL) {
            free(manager->tasks[i]->status);
            free(manager->tasks[i]);
        }
    }
    free(manager->tasks);
    free(manager);
}

int main() {
    // Initialize task management system
    TaskManager* manager = create_task_manager(1000);

    // Add tasks
    Task task1 = {1, "New", 5};
    add_task(manager, task1);
    Task task2 = {2, "In Progress", 3};
    add_task(manager, task2);

    // Update tasks
    update_task(manager, 1, "Done", 10);

    // Delete tasks
    delete_task(manager, 2);

    // Serialize and deserialize tasks
    serialize_tasks(manager, "tasks.bin");
    TaskManager* deserialized_manager = deserialize_tasks("tasks.bin");

    // Free resources
    free_task_manager(manager);
    free_task_manager(deserialized_manager);

    return 0;
}
