#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the job structure
typedef struct {
    int job_id;
    char status[10];
    int priority;
    time_t start_time;
    time_t completion_time;
} Job;

// Define the job management system
typedef struct {
    pthread_mutex_t lock; // Mutex for concurrent access
    Job *jobs; // Dynamic array of jobs
    int size; // Current number of jobs
    pthread_cond_t cond; // Condition variable for notifications
} JobSystem;

// Initialize the job management system
JobSystem* init_job_system(int capacity) {
    JobSystem* sys = (JobSystem*) malloc(sizeof(JobSystem));
    sys->jobs = (Job*) malloc(capacity * sizeof(Job));
    sys->size = 0;
    pthread_mutex_init(&sys->lock, NULL);
    pthread_cond_init(&sys->cond, NULL);
    return sys;
}

// Add a job to the system
void add_job(JobSystem* sys, Job job) {
    pthread_mutex_lock(&sys->lock);
    sys->jobs[sys->size++] = job;
    pthread_mutex_unlock(&sys->lock);
}

// Update a job's status in the system
void update_job_status(JobSystem* sys, int job_id, char* new_status) {
    pthread_mutex_lock(&sys->lock);
    for (int i = 0; i < sys->size; i++) {
        if (sys->jobs[i].job_id == job_id) {
            strcpy(sys->jobs[i].status, new_status);
            break;
        }
    }
    pthread_mutex_unlock(&sys->lock);
}

// Delete a job from the system
void delete_job(JobSystem* sys, int job_id) {
    pthread_mutex_lock(&sys->lock);
    for (int i = 0; i < sys->size; i++) {
        if (sys->jobs[i].job_id == job_id) {
            memmove(sys->jobs + i, sys->jobs + i + 1, sizeof(Job) * (sys->size - i));
            sys->size--;
            break;
        }
    }
    pthread_mutex_unlock(&sys->lock);
}

// Retrieve a job from the system
Job* get_job(JobSystem* sys, int job_id) {
    pthread_mutex_lock(&sys->lock);
    for (int i = 0; i < sys->size; i++) {
        if (sys->jobs[i].job_id == job_id) {
            Job* job = &sys->jobs[i];
            pthread_mutex_unlock(&sys->lock);
            return job;
        }
    }
    pthread_mutex_unlock(&sys->lock);
    return NULL;
}

// Serialize the job system to a file
void serialize_job_system(JobSystem* sys, FILE* file) {
    fwrite(&sys->size, sizeof(int), 1, file);
    for (int i = 0; i < sys->size; i++) {
        Job job = sys->jobs[i];
        fwrite(&job.job_id, sizeof(int), 1, file);
        fwrite(job.status, sizeof(char) * 10, 1, file);
        fwrite(&job.priority, sizeof(int), 1, file);
        fwrite(&job.start_time, sizeof(time_t), 1, file);
        fwrite(&job.completion_time, sizeof(time_t), 1, file);
    }
}

// Deserialize the job system from a file
JobSystem* deserialize_job_system(FILE* file) {
    JobSystem* sys = (JobSystem*) malloc(sizeof(JobSystem));
    int size;
    fread(&size, sizeof(int), 1, file);
    sys->jobs = (Job*) malloc(size * sizeof(Job));
    for (int i = 0; i < size; i++) {
        Job job;
        fread(&job.job_id, sizeof(int), 1, file);
        fread(job.status, sizeof(char) * 10, 1, file);
        fread(&job.priority, sizeof(int), 1, file);
        fread(&job.start_time, sizeof(time_t), 1, file);
        fread(&job.completion_time, sizeof(time_t), 1, file);
        sys->jobs[i] = job;
    }
    pthread_mutex_init(&sys->lock, NULL);
    pthread_cond_init(&sys->cond, NULL);
    return sys;
}

// Free all allocated resources
void free_job_system(JobSystem* sys) {
    if (sys == NULL) return;
    free(sys->jobs);
    pthread_mutex_destroy(&sys->lock);
    pthread_cond_destroy(&sys->cond);
    free(sys);
}
