    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Allocate memory for arrays and structures
    int* timestamps = (int*)malloc(maxMetrics * sizeof(int));
    double* values = (double*)malloc(maxMetrics * sizeof(double));
