    char* uniqueId;
    srand(time(NULL)); // seed for random number generation

    for (i = 0; i < maxMetrics; i++) {
        // Generate a unique ID using a predefined character set
        int length = rand() % (maxStringLength - 1) + 1;
        unsigned char buffer[length];
        for (int j = 0; j < length; j++) {
            buffer[j] = 'a' + (rand() % 26);
        }
        buffer[length] = '\0';
        uniqueId = (char*)malloc((length + 1) * sizeof(char));
        strcpy(uniqueId, buffer);

        // Generate a random timestamp
        int timestamp = rand();

        // Create a new metric structure
        metrics[i].value = (double)i;
        metrics[i].timestamp = timestamp;
        metrics[i].status = OK;

        // Free the unique ID memory
        free(uniqueId);
    }

    return metrics;
}

void printMetrics(metric_t* metrics, int numMetrics) {
    int i;
    for (i = 0; i < numMetrics; i++) {
        if (metrics[i].status == ERROR) {
            printf("Metric %d: Error\n", i);
        } else {
            printf("Metric %d: Value %.2f, Timestamp %d, Status OK\n", i, metrics[i].value, metrics[i].timestamp);
        }
    }
}

double calculateAverage(metric_t* metrics, int numMetrics) {
    double sum = 0;
    int i;
    for (i = 0; i < numMetrics; i++) {
        sum += metrics[i].value;
    }
    return sum / numMetrics;
}

int main() {
    // Initialize the metrics manager with a specified number of metrics
    metric_t* metrics = metricsManager(10000, 10);

    // Print all metrics
    printMetrics(metrics, 10000);

    // Calculate and print the average value
    double average = calculateAverage(metrics, 10000);
    printf("Average Value: %.2f\n", average);

    return 0;
}

