void* allocArrays(int offsetSize, int keySize, int recordSize) {
    // Allocate memory for three arrays in contiguous block using malloc
    size_t totalBytes = (sizeof(long) * offsetSize + sizeof(int) * keySize + sizeof(Record) * recordSize);
    void* ptr = malloc(totalBytes);

    if (!ptr) return NULL;

    return ptr;
}

void cleanupArrays(void* ptr, int offsetSize, int keySize, int recordSize) {
    // Release allocated memory
    free(ptr);
}

