#define MAX_DOCS 1000000

// Define the status enum
enum { UNPROCESSED, PROCESSED, ERROR };

typedef struct {
    double value;
    int timestamp;
    enum status status;
} Document;

// Resource manager function
void* resourceManager(void* arg) {
    // Initialize arrays for documents and timestamps
    Document* docs = (Document*) malloc(MAX_DOCS * sizeof(Document));
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
    int* timestamps = (int*) malloc(MAX_DOCS * sizeof(int));

    // Initialize the document pool with a default size
    int num_docs = 0;

    // Define a function to add a new document
    void addDocument(double value, enum status status) {
        pthread_mutex_lock(&lock);
        docs[num_docs].value = value;
        docs[num_docs].timestamp = timestamps[num_docs] = rand();
        docs[num_docs].status = status;
        num_docs++;
        pthread_cond_signal(&cond);
        pthread_mutex_unlock(&lock);
    }

    // Define a function to get the document at a given index
    Document* getDocument(int idx) {
        pthread_mutex_lock(&lock);
        if (idx >= 0 && idx < num_docs) {
            return &docs[idx];
        }
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Define a function to delete a document at a given index
    void deleteDocument(int idx) {
        pthread_mutex_lock(&lock);
        if (idx >= 0 && idx < num_docs) {
            memmove(docs + idx, docs + idx + 1, (num_docs - idx - 1) * sizeof(Document));
            timestamps[idx] = timestamps[num_docs - 1];
            num_docs--;
            pthread_cond_signal(&cond);
        }
        pthread_mutex_unlock(&lock);
    }

    // Define a function to resize the document pool
    void resizePool(int new_size) {
        pthread_mutex_lock(&lock);
        if (new_size > 0 && num_docs < new_size) {
            Document* temp = (Document*) realloc(docs, new_size * sizeof(Document));
            int* temp_timestamps = (int*) realloc(timestamps, new_size * sizeof(int));
            docs = temp;
            timestamps = temp_timestamps;
        }
        pthread_mutex_unlock(&lock);
    }

