```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <bcrypt/bcrypt.h>

typedef struct {
    double value;
    int timestamp;
    enum { OK, ERROR } status;
} metric;

metric* manageMetricsAndDataSets(int numMetrics) {
    // Allocate memory for arrays
    metric* metrics = (metric*)malloc(numMetrics * sizeof(metric));
    long* offsets = (long*)malloc((numMetrics + 1) * sizeof(long));
    int* keys = (int*)malloc(numMetrics * sizeof(int));
    record* records = (record*)malloc(numMetrics * sizeof(record));

    // Initialize data structures
    for (int i = 0; i < numMetrics; i++) {
        metrics[i].timestamp = i;
        metrics[i].status = OK;
        keys[i] = rand() % 10000000;
        records[i].value = (double)rand() / RAND_MAX;
    }

    // Implement Union-Find data structure
    int* parent = (int*)malloc(numMetrics * sizeof(int));
    for (int i = 0; i < numMetrics; i++) {
        parent[i] = i;
    }
    int* rank = (int*)malloc(numMetrics * sizeof(int));
    for (int i = 0; i < numMetrics; i++) {
        rank[i] = 0;
    }

    // Find disjoint sets
    for (int i = 0; i < numMetrics; i++) {
        int root = find(i, parent);
        for (int j = i + 1; j < numMetrics; j++) {
            if (keys[j] == keys[i]) {
                unionSets(root, find(j, parent), parent);
            }
        }
    }

    // Get disjoint sets and statistics
    int setCount = getSetCount(parent);
    long* setSizes = (long*)malloc(setCount * sizeof(long));
    for (int i = 0; i < setCount; i++) {
        setSizes[i] = getSetSize(i, parent, rank);
    }

    // Print disjoint sets and statistics
    printf("Disjoint Sets: ");
    for (int i = 0; i < setCount; i++) {
        printf("%ld ", setSizes[i]);
    }
    printf("\nTotal Set Count: %d\n", setCount);

    return metrics;
}

// Find the root of a set in Union-Find
int find(int x, int* parent) {
    if (parent[x] != x) {
        parent[x] = find(parent[x], parent);
    }
    return parent[x];
}

// Union two sets in Union-Find
void unionSets(int x, int y, int* parent) {
    int rootX = find(x, parent);
    int rootY = find(y, parent);
    if (rootX != rootY) {
        if (rank[rootX] > rank[rootY]) {
            parent[rootY] = rootX;
        } else {
            parent[rootX] = rootY;
            if (rank[rootX] == rank[rootY]) {
                rank[rootY]++;
            }
        }
    }
}

// Get the total number of disjoint sets
int getSetCount(int* parent) {
    int setCount = 0;
    for (int i = 0; i < numMetrics; i++) {
        if (parent[i] == i) {
            setCount++;
        }
    }
    return setCount;
}

// Get the size of a disjoint set
long getSetSize(int setIndex, int* parent, int* rank) {
    long setSize = 0;
    for (int i = 0; i < numMetrics; i++) {
        if (parent[i] == setIndex) {
            setSize++;
        }
    }
    return setSize;
}

record {
    int value;
};
