        transaction_ids = realloc(transaction_ids, sizeof(int*) * (num_transactions + MAX_TRANSACTIONS));
        amounts = realloc(amounts, sizeof(double*) * (num_transactions + MAX_TRANSACTIONS));
        last_processed_timestamps = realloc(last_processed_timestamps, sizeof(int) * (num_transactions + MAX_TRANSACTIONS));

        for (int i = 0; i < num_transactions; i++) {
            transaction_t* transaction = &transactions[i];
            int timestamp;
            int transaction_id;
            double amount;

            fscanf(stdin, "%d %d %lf\n", &timestamp, &transaction_id, &amount);

            transaction->timestamp = timestamp;
            transaction->amount = amount;

            timestamps[i] = &transaction->timestamp;
            transaction_ids[i] = &transaction_id;
            amounts[i] = &amount;
        }

        for (int i = 0; i < num_transactions; i++) {
            fwrite(&transactions[i], sizeof(transaction_t), 1, file);
            fflush(file);
        }
    }

    fclose(file);

    // Read and process last processed timestamps
    int* last_processed_timestamps = malloc(sizeof(int) * (num_transactions + MAX_TRANSACTIONS));
    for (int i = 0; i < num_transactions; i++) {
        fscanf(stdin, "%d\n", &last_processed_timestamps[i]);
    }

    // Calculate and print total transaction amount
    double total_amount = 0.0;
    for (int i = 0; i < num_transactions; i++) {
        total_amount += transactions[i].amount;
    }
    printf("Total transaction amount: %lf\n", total_amount);
}

void serializeData(FILE* file) {
    fwrite(transactions, sizeof(transaction_t), MAX_TRANSACTIONS, file);
    fflush(file);
}

transaction_t* deserializeData() {
    transaction_t* transactions = malloc(sizeof(transaction_t) * MAX_TRANSACTIONS);

    FILE* file = fopen("transactions.bin", "rb");
    if (file == NULL) {
        printf("Failed to open file.\n");
        return NULL;
    }

    fread(transactions, sizeof(transaction_t), MAX_TRANSACTIONS, file);
    fclose(file);

    return transactions;
}

int main() {
    optimizeDataProcessor();

    // Deserialize data and calculate total transaction amount
    transaction_t* deserialized_transactions = deserializeData();
    double total_amount = 0.0;
    for (int i = 0; i < MAX_TRANSACTIONS; i++) {
        total_amount += deserialized_transactions[i].amount;
    }
    printf("Total transaction amount: %lf\n", total_amount);

    return 0;
}
