Profile** profiles = NULL;
int profile_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* resize_list(void* arg) {
    pthread_setcancelstate(PTHREAD_CANCEL_ENABLE, NULL);
    while (profile_count >= PROFILE_THRESHOLD) {
        int new_size = profile_count + PROFILE_THRESHOLD;
        Profile** new_profiles = realloc(profiles, sizeof(Profile*) * new_size);
        if (!new_profiles) {
            printf("Memory allocation failed.\n");
            return NULL;
        }
        profiles = new_profiles;
    }
    pthread_exit(NULL);
}

void add_profile(char* name, int age, char* email) {
    Profile* profile = (Profile*)malloc(sizeof(Profile));
    profile->name = name;
    profile->age = age;
    profile->email = email;
    pthread_mutex_lock(&lock);
    if (profile_count >= PROFILE_THRESHOLD) {
        pthread_create(NULL, NULL, resize_list, NULL);
    }
    profiles = realloc(profiles, sizeof(Profile*) * (profile_count + 1));
    profiles[profile_count] = profile;
    profile_count++;
    pthread_mutex_unlock(&lock);
}

void update_profile(char* name, int age, char* email) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < profile_count; i++) {
        if (strcmp(profiles[i]->name, name) == 0) {
            profiles[i]->age = age;
            profiles[i]->email = email;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

void remove_profile(char* name) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < profile_count; i++) {
        if (strcmp(profiles[i]->name, name) == 0) {
            free(profiles[i]);
            memmove(profiles + i, profiles + i + 1, sizeof(Profile*) * (profile_count - i - 1));
            profile_count--;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

void* query_by_name(void* arg) {
    char* name = (char*)arg;
    for (int i = 0; i < profile_count; i++) {
        if (strcmp(profiles[i]->name, name) == 0) {
            // Profile found. Handle the result accordingly.
            return NULL;
        }
    }
    // Profile not found. Handle the result accordingly.
    return NULL;
}

void* query_by_email(void* arg) {
    char* email = (char*)arg;
    for (int i = 0; i < profile_count; i++) {
        if (strcmp(profiles[i]->email, email) == 0) {
            // Profile found. Handle the result accordingly.
            return NULL;
        }
    }
    // Profile not found. Handle the result accordingly.
    return NULL;
}

void log_profile_change(char* name, int age, char* email) {
    // Log profile update.
