#include <string.h>

typedef struct {
    int key;
    long offset;
    short value;
} record;

void expandGraphStructure(int numRecords) {
    record *records = NULL;
    long *offsets = NULL;
    int *keys = NULL;
    record *newRecords = NULL;
    int newNumRecords = 0;

    // Initialize arrays
    records = (record *)malloc(numRecords * sizeof(record));
    offsets = (long *)malloc((numRecords + 1) * sizeof(long));
    keys = (int *)malloc((numRecords + 1) * sizeof(int));

    for (int i = 0; i < numRecords; i++) {
        records[i].key = i;
        records[i].offset = offsets[i] = (long)i;
        records[i].value = (short)(i % 256);
    }

    while (newNumRecords < numRecords) {
        int newNum = numRecords + (rand() % 1000) + 1;
        record *tempRecords = (record *)realloc(records, newNum * sizeof(record));
        long *tempOffsets = (long *)realloc(offsets, (newNum + 1) * sizeof(long));
        int *tempKeys = (int *)realloc(keys, (newNum + 1) * sizeof(int));

        if (!tempRecords || !tempOffsets || !tempKeys) {
            printf("Memory allocation failure.\n");
            return;
        }

        newRecords = tempRecords;
        offsets = tempOffsets;
        keys = tempKeys;

        for (int i = numRecords; i < newNum; i++) {
            records[i].key = i;
            records[i].offset = offsets[i] = (long)i;
            records[i].value = (short)(i % 256);
        }

        numRecords = newNum;
    }
}
