pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initRecords() {
    if (records) free(records);
    records = (Record*)malloc(MAX_RECORDS * sizeof(Record));
    recordCount = 0;
}

void setRandomKeys(int min, int max) {
    for (int i = 0; i < recordCount; i++) {
        records[i].key = rand() % (max - min + 1) + min;
    }
}

void addRecord(int key, const char* value) {
    if (recordCount >= MAX_RECORDS) {
        printf("Error: Maximum number of records reached.\n");
        return;
    }

    Record* newRecord = (Record*)malloc(sizeof(Record));
    newRecord->key = key;
    newRecord->value = strdup(value);
    newRecord->refCount = 1;

    if (recordCount > 0) {
        Record* temp = records;
        records = (Record*)malloc((recordCount + 1) * sizeof(Record));
        memcpy(records, temp, recordCount * sizeof(Record));
        free(temp);
    } else {
        records = newRecord;
    }

    recordCount++;
}

void removeRecord(int key) {
    for (int i = 0; i < recordCount; i++) {
        if (records[i].key == key) {
            free(records[i].value);
            if (--records[i].refCount > 0) continue;

            Record* temp = records;
            records = (Record*)malloc((recordCount - 1) * sizeof(Record));
            memcpy(records, i + 1, (recordCount - 1 - i) * sizeof(Record));
            free(temp);
            recordCount--;
            return;
        }
    }
}

void incrementRefCount(int key) {
    for (int i = 0; i < recordCount; i++) {
        if (records[i].key == key) {
            records[i].refCount++;
            return;
        }
    }
}

void decrementRefCount(int key) {
    for (int i = 0; i < recordCount; i++) {
        if (records[i].key == key && --records[i].refCount > 0) continue;

        Record* temp = records;
        records = (Record*)malloc((recordCount - 1) * sizeof(Record));
        memcpy(records, i + 1, (recordCount - 1 - i) * sizeof(Record));
        free(temp);
        recordCount--;
    }
}

void findLargestKey() {
    int largestKey = 0;
    for (int i = 0; i < recordCount; i++) {
        if (records[i].key > largestKey) largestKey = records[i].key;
    }

    printf("Largest integer key: %d\n", largestKey);
}

void serializeRecords(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        printf("Error: Unable to open file for serialization.\n");
        return;
    }

    pthread_mutex_lock(&lock);

    for (int i = 0; i < recordCount; i++) {
        fwrite(&records[i], sizeof(Record), 1, file);
    }

    fclose(file);
    pthread_mutex_unlock(&lock);
}

void deserializeRecords(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        printf("Error: Unable to open file for deserialization.\n");
        return;
    }

    pthread_mutex_lock(&lock);

    initRecords();

    Record record;
    while (fread(&record, sizeof(Record), 1, file)) {
        addRecord(record.key, record.value);
    }

    fclose(file);
    pthread_mutex_unlock(&lock);
}

int main() {
    // Initialize records
    initRecords();

    // Add some records
    addRecord(42, "Hello");
    addRecord(24, "World");
    addRecord(13, "Code");

    // Set random keys
    setRandomKeys(1, 100);

    // Serialize records
    serializeRecords("records.bin");

    // Deserialize records
    deserializeRecords("records.bin");

    // Find the largest key
    findLargestKey();

    return 0;
}
