// Initialize record array with initial capacity
void initRecordArray(RecordArray* arr, size_t capacity) {
    arr->records = (DataRecord*)malloc(capacity * sizeof(DataRecord));
    arr->capacity = capacity;
    arr->size = 0;
}

// Insert a new data record into the array
void insertRecord(RecordArray* arr, DataRecord record) {
    if (arr->size >= arr->capacity) {
        // Resize the array to double its size
        arr->records = (DataRecord*)realloc(arr->records, arr->capacity * 2 * sizeof(DataRecord));
        arr->capacity *= 2;
    }
    arr->records[arr->size] = record;
    arr->size++;
}

// Batch processing function to process multiple records at once
void batchProcess(RecordArray* arr, int start, int end) {
    for (int i = start; i < end; i++) {
        // Process the data record
        DataRecord record = arr->records[i];
        // ...
    }
}

// Query the array for records matching specific criteria
DataRecord* queryRecords(RecordArray* arr, int key, double value) {
    DataRecord* result = NULL;
    size_t count = 0;

    for (int i = 0; i < arr->size; i++) {
        if (arr->records[i].key == key && arr->records[i].value == value) {
            result = (DataRecord*)realloc(result, ++count * sizeof(DataRecord));
            memcpy(&result[count - 1], &arr->records[i], sizeof(DataRecord));
        }
    }

    return result;
}

// Serialize the data structure to a file
void serialize(RecordArray* arr, FILE* file) {
    fwrite(&arr->size, sizeof(size_t), 1, file);
