#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

// Define a struct for database records
typedef struct {
    int key;
    long value;
} Record;

// Define a struct for the hash table
typedef struct {
    size_t capacity;
    size_t size;
    Record** buckets;
    pthread_mutex_t mutex;
    sem_t available_slots;
    pthread_cond_t cond;
} HashTable;

// Initialize the hash table
HashTable* init_hash_table(size_t initial_capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->capacity = initial_capacity;
    table->size = 0;
    table->buckets = (Record**)calloc(initial_capacity, sizeof(Record*));
    pthread_mutex_init(&table->mutex, NULL);
    sem_init(&table->available_slots, 0, initial_capacity);
    pthread_cond_init(&table->cond, NULL);
    return table;
}

// Insert a record into the hash table
void insert_record(HashTable* table, int key, long value) {
    Record* new_rec = (Record*)malloc(sizeof(Record));
    new_rec->key = key;
    new_rec->value = value;

    pthread_mutex_lock(&table->mutex);
    size_t idx = key % table->capacity;
    while (table->buckets[idx] != NULL && table->buckets[idx]->key != key) {
        sem_wait(&table->available_slots);
        idx = (idx + 1) % table->capacity;
    }
    if (!table->buckets[idx]) {
        table->size++;
        table->buckets[idx] = new_rec;
    } else {
        pthread_cond_signal(&table->cond);
    }
    pthread_mutex_unlock(&table->mutex);
}

// Look up a record in the hash table
Record* lookup_record(HashTable* table, int key) {
    Record* found = NULL;

    pthread_mutex_lock(&table->mutex);
    size_t idx = key % table->capacity;
    while (table->buckets[idx] != NULL && table->buckets[idx]->key != key) {
        sem_wait(&table->available_slots);
        idx = (idx + 1) % table->capacity;
    }
    if (table->buckets[idx]) {
        found = table->buckets[idx];
    }

    pthread_mutex_unlock(&table->mutex);

    return found;
}

// Garbage collect unused records
void garbage_collect(HashTable* table) {
    // Iterate over the hash table and free unused records
    for (size_t i = 0; i < table->capacity; i++) {
        if (!table->buckets[i]) {
            continue;
        }
        Record* rec = table->buckets[i];
        pthread_mutex_lock(&table->mutex);
        sem_wait(&table->available_slots);
        free(rec);
        table->size--;
        pthread_mutex_unlock(&table->mutex);
    }
}

// Main program
int main() {
    HashTable* table = init_hash_table(1000);

    // Example usage:
    for (int i = 0; i < 5000; i++) {
        insert_record(table, i, i * i);
    }

    garbage_collect(table);

    return 0;
}
