int generate_timestamp(int throttle) {
    static clock_t last_flush;
    if ((clock() - last_flush) / CLOCKS_PER_SEC > FLUSH_INTERVAL || throttle == 0) {
        flush_data();
        last_flush = clock();
    }
    return (int)(rand() * TIMESTAMP_RANGE / RAND_MAX);
}

