// Custom memory allocator using a buddy system
void* custom_malloc(size_t size) {
    // Initialize buddy system variables
    static void* free_list = NULL;
    static void* current_block = NULL;
    static int block_size = 0;

    if (free_list == NULL) {
        // Initialize the first free block
        free_list = malloc(1024);
        block_size = 1024;
    }

    // Find a suitable free block of the required size
    void* result = free_list;
    while (result < free_list + block_size - size && (char*)result + size > free_list) {
        if ((char*)result == (char*)free_list + block_size / 2) {
            // Reorganize the buddy system for more efficient allocation
            void* temp = free_list;
            free_list = (void*)((char*)free_list + block_size / 2);
            block_size /= 2;
            free(temp);
        }
        result = (void*)((char*)result + size);
    }

    if (result > free_list) {
        // Split the current block into two smaller blocks
        void* temp = malloc(block_size - size);
        memcpy(temp, (void*)((char*)free_list + block_size - size), size);
        free((void*)((char*)free_list + block_size - size));
        free_list = temp;
    }

    return result;
}

