#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <unistd.h>
#include <pthread.h>

#define RECORD_SIZE 12
#define MAX_RECORDS 10000
#define VALUE_RANGE 1000

typedef struct {
    long offset;
    int key;
    int value;
} record_t;

record_t* records = NULL;
int record_count = 0;
int max_records = 0;
int value_range = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
int memory_threshold = 0;

void* my_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr && record_count >= max_records * (1 - memory_threshold / 100)) {
        // Reclaim memory
        printf("Reclaiming memory\n");
        free(ptr);
        return my_malloc(size);
    }
    return ptr;
}

void insert_record(record_t* new_record) {
    pthread_mutex_lock(&mutex);
    record_count++;
    if (record_count >= max_records) {
        record_count = 0;
    }
    records[record_count] = *new_record;
    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&mutex);
}

void update_record(long offset, int new_value) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < record_count; i++) {
        if (records[i].offset == offset) {
            records[i].value = new_value;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

record_t* get_record(long offset) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < record_count; i++) {
        if (records[i].offset == offset) {
            record_t* ret = &records[i];
            pthread_mutex_unlock(&mutex);
            return ret;
        }
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void recover_from_storage() {
    // Code to read from persistent storage
    FILE* file = fopen("data_store.bin", "rb");
    if (!file) {
        printf("Error reading data store\n");
        return;
    }
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    rewind(file);
    records = my_malloc(record_count * RECORD_SIZE);
    fread(records, RECORD_SIZE, record_count, file);
    fclose(file);
}

void persist_to_storage() {
    // Code to write to persistent storage
    FILE* file = fopen("data_store.bin", "wb");
    if (!file) {
        printf("Error writing data store\n");
        return;
    }
    fwrite(records, RECORD_SIZE, record_count, file);
    fclose(file);
}

void* thread_func(void* arg) {
    while (1) {
        pthread_mutex_lock(&mutex);
        while (record_count >= max_records * (1 - memory_threshold / 100)) {
            pthread_cond_wait(&cond, &mutex);
        }
        // Code to handle concurrent access
        pthread_mutex_unlock(&mutex);
        sleep(1); // Simulate some work
    }
    return NULL;
}

int main() {
    // Initialize data store
    max_records = MAX_RECORDS;
    value_range = VALUE_RANGE;
    record_count = 0;
    records = my_malloc(max_records * RECORD_SIZE);

    pthread_t thread;
    pthread_create(&thread, NULL, thread_func, NULL);

    while (1) {
        // Simulate user input
        int choice;
        printf("Enter 1 to insert a record, 2 to update a record, or 3 to retrieve a record: ");
        scanf("%d", &choice);
        if (choice == 1) {
            record_t new_record;
            new_record.offset = rand();
            new_record.key = rand() % 1000;
            new_record.value = rand() % value_range;
            insert_record(&new_record);
        } else if (choice == 2) {
            long offset;
            int new_value;
            printf("Enter the record offset: ");
            scanf("%ld", &offset);
            printf("Enter the new value: ");
            scanf("%d", &new_value);
            update_record(offset, new_value);
        } else if (choice == 3) {
            long offset;
            printf("Enter the record offset to retrieve: ");
            scanf("%ld", &offset);
            record_t* retrieved = get_record(offset);
            if (retrieved) {
                printf("Record found with key %d and value %d\n", retrieved->key, retrieved->value);
            } else {
                printf("Record not found\n");
            }
        }
    }

    return 0;
}
