// Helper function to validate and store a list of integers and floating-point numbers from standard input
Record* processFloatsAndInts(int** data, int size) {
    // Allocate memory for the records array
    Record* records = (Record*)malloc(size * sizeof(Record));

    // Initialize record pointers
    Record* current = records;

    for (int i = 0; i < size; i++) {
        float num;
        if (scanf("%f", &num) != 1) {
            printf("Invalid input format. Please enter a valid floating-point number.\n");
            return NULL;
        }

        // Store the record
        current->key = i;
        current->offset = (long)num;
        current->value = (short)(int)num;

        // Move to next record
        current++;
    }

    *data = records;
    return records;
}

// Function to process data and expand graph dynamically
void processDataAndExpandGraph(int** data, int size) {
    // Initialize the number of records
    int numRecords = 0;

    // Check for edge case: empty input list
    if (size == 0) {
        return;
    }

    // Process the data and expand the graph dynamically
    Record* current = *data;

    while (current != NULL) {
        // Initialize record pointers
        Record* nextRecord = current + size;

        // Check for edge case: list with mixed valid and invalid inputs
        if (nextRecord->key >= 0 && nextRecord->offset > INT_MAX || nextRecord->value < -32768 || nextRecord->value > 32767) {
            printf("Invalid input. Please enter a valid integer within the range [-32768, 32767].\n");
            return;
        }

        // Check for edge case: list containing only negative numbers
        if (nextRecord->key < 0) {
            printf("List contains only negative numbers.\n");
            return;
        }

        // Check for uniqueness of keys and offsets across all records
        Record* temp = current - 1;

        while (temp >= *data && temp->offset == nextRecord->offset) {
            if (temp->key == nextRecord->key) {
                printf("Duplicate key or offset found. Please ensure unique values.\n");
                return;
            }
            temp--;
        }

        // Store the record
        current++;
    }
}

int main() {
    int numRecords = 0;

    while (numRecords <= 10000 && scanf("%d", &numRecords) == 1) {
        printf("Enter the maximum number of records: ");
    }

    if (numRecords > 10000) {
        printf("Maximum limit of 10,000 records exceeded. Please try again.\n");
        return -1;
    }

    int size = numRecords * sizeof(Record);

    // Initialize record pointers
    Record* records = (Record*)malloc(size);

    if (records == NULL) {
        printf("Memory allocation failed.\n");
        return -2;
    }

    // Store the data and expand the graph dynamically
