['Here is the C function to manage a doubly linked list:

```c
#include <stdio.h>
#include <stdlib.h>

// Node structure definition
typedef struct Node {
    long offset;
    int key;
    struct Node* next;
    struct Node* prev;
} Node;

// Doubly Linked List structure definition
typedef struct DLL {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
} DLL;

// Function to initialize the doubly linked list
DLL* dll_init() {
    DLL* dll = (DLL*)malloc(sizeof(DLL));
    if (!dll) return NULL; // Handle memory allocation error

    dll->head = NULL;
    dll->tail = NULL;
    pthread_mutex_init(&dll->lock, NULL);

    return dll;
}

// Function to insert a new node at the specified position
int dll_insert(DLL* dll, long offset, int key) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return -1; // Handle memory allocation error

    newNode->offset = offset;
    newNode->key = key;

    pthread_mutex_lock(&dll->lock);

    // Insert at the beginning
    if (dll->head == NULL || dll->head->key > key) {
        newNode->next = dll->head;
        if (dll->head != NULL)
            dll->head->prev = &newNode;
        else
            dll->tail = &newNode;
        dll->head = newNode;

    // Insert at the end
    } else if (dll->tail->key < key) {
        newNode->prev = dll->tail;
        dll->tail->next = &newNode;
        dll->tail = newNode;

    // Insert in between two nodes
    } else {
        Node* current = dll->head;
        while (current != NULL && current->key <= key)
            current = current->next;
        if (current == NULL) {
            newNode->prev = &dll->head;
            dll->head = newNode;

        } else if (current->key > key) {
            newNode->next = current;
            newNode->prev = current->prev;
            current->prev = &newNode;
            if (current->prev != NULL)
                current->prev->next = &newNode;
            else
                dll->head = newNode;

        } else {
            newNode->prev = current;
            newNode->next = current->next;
            current->next = &newNode;
            current->next->prev = &newNode;
        }
    }

    pthread_mutex_unlock(&dll->lock);

    return 0; // Successful insertion
}

// Function to traverse the list in forward direction
void dll_traverse_forward(DLL* dll, void (*visit)(Node*)) {
    Node* current = dll->head;
    while (current != NULL) {
        visit(current);
        current = current->next;
    }
}

// Function to traverse the list in backward direction
void dll_traverse_backward(DLL* dll, void (*visit)(Node*)) {
    Node* current = dll->tail;
    while (current != NULL) {
        visit(current);
        current = current->prev;
    }
}

// Function to delete a node from the list
int dll_delete(DLL* dll, int key) {
    pthread_mutex_lock(&dll->lock);

    Node* current = dll->head;
    while (current != NULL && current->key != key)
        current = current->next;

    if (current == NULL || current->key != key) {
        pthread_mutex_unlock(&dll->lock);
        return -1; // Node not found
    }

    if (current == dll->head) {
        dll->head = current->next;
        if (dll->head != NULL)
            dll->head->prev = NULL;
        else
            dll->tail = NULL;

    } else if (current == dll->tail) {
        dll->tail = current->prev;
        dll->tail->next = NULL;

    } else {
        current->prev->next = current->next;
        current->next->prev = current->prev;
    }

    free(current);
    pthread_mutex_unlock(&dll->lock);

    return 0; // Successful deletion
}
