record_t* expandGraphStructure(record_t** graph, int* num_records, int min_key, int max_key) {
    // Allocate memory for new records array
    *num_records *= 2;
    record_t* new_graph = (record_t*) realloc(*graph, (*num_records) * sizeof(record_t));

    if (!new_graph) return NULL; // Handle out-of-memory error

    // Initialize arrays for offset and key values
    long* offsets = (long*) calloc((*num_records), sizeof(long));
    int* keys = (int*) calloc((*num_records), sizeof(int));

    if (!offsets || !keys) {
        free(new_graph);
        return NULL; // Handle out-of-memory error
    }

    // Generate random record values
    for (int i = 0; i < *num_records; ++i) {
        keys[i] = rand() % (max_key - min_key + 1) + min_key;
        offsets[i] = i;
    }

    // Copy existing records to new array
    int idx = 0;
    for (int i = 0; i < (*num_records) / 2; ++i) {
        new_graph[idx].key = keys[i];
        new_graph[idx++].offset = offsets[i];
        new_graph[idx].value = rand() % 32768; // Generate random short value
        idx++;
    }

    free(offsets);
    free(keys);

    return new_graph;
}

