    int max_value = INT_MIN;
    for (int i = 0; i < num_records; ++i) {
        if (graph[i].value > max_value)
            max_value = graph[i].value;
    }
    return max_value;
}

void serializeGraph(record_t* graph, int num_records, char* filename) {
    FILE* file = fopen(filename, "wb");
    fwrite(&num_records, sizeof(int), 1, file);
    fwrite(graph, sizeof(record_t), num_records, file);
    fclose(file);
}

record_t* deserializeGraph(char* filename) {
    record_t* graph;
    int num_records;
    FILE* file = fopen(filename, "rb");
    if (!file) return NULL; // Handle file not found error

    fread(&num_records, sizeof(int), 1, file);

    graph = (record_t*) malloc(num_records * sizeof(record_t));
    fread(graph, sizeof(record_t), num_records, file);
    fclose(file);

    return graph;
}
