```c
// Node structure
typedef struct {
    double key;
    struct node* left;
    struct node* right;
} Node;

// BST functions
Node* insert(Node* root, double key);
void in_order_traversal(Node* root);
void pre_order_traversal(Node* root);
void post_order_traversal(Node* root);
void delete_node(Node** root, double key);

// Self-balancing mechanism (AVL tree)
int height(Node* node);
Node* left_rotate(Node* x);
Node* right_rotate(Node* y);
Node* balance(Node* z);

Node* insert(Node* root, double key) {
    if (root == NULL || key < root->key) {
        Node* new_node = malloc(sizeof(Node));
        new_node->key = key;
        new_node->left = new_node->right = NULL;

        if (root == NULL)
            return new_node;
        else if (key < root->key)
            root->left = insert(root->left, key);
        else
            root->right = insert(root->right, key);

        int balance_factor = height(root->left) - height(root->right);
        if (balance_factor > 1) {
            if (height(root->left->left) >= height(root->left->right))
                return right_rotate(root);
            else
                root->left = left_rotate(root->left);
            return right_rotate(root);
        }
        else if (balance_factor < -1) {
            if (height(root->right->right) >= height(root->right->left))
                return left_rotate(root);
            else
                root->right = right_rotate(root->right);
            return left_rotate(root);
        }

        return root;
    }
    return root;
}

void in_order_traversal(Node* root) {
    if (root != NULL) {
        in_order_traversal(root->left);
        printf("%f ", root->key);
        in_order_traversal(root->right);
    }
}

void pre_order_traversal(Node* root) {
    if (root != NULL) {
        printf("%f ", root->key);
        pre_order_traversal(root->left);
        pre_order_traversal(root->right);
    }
}

void post_order_traversal(Node* root) {
    if (root != NULL) {
        post_order_traversal(root->left);
        post_order_traversal(root->right);
        printf("%f ", root->key);
    }
}

void delete_node(Node** root, double key) {
    Node* temp = *root;
    if (*root == NULL)
        return;

    if (key < temp->key) {
        temp->left = delete_node(&temp->left, key);
    }
    else if (key > temp->key) {
        temp->right = delete_node(&temp->right, key);
    }
    else {
        if (temp->left == NULL || temp->right == NULL) {
            Node* temp2 = temp;
            temp = temp->left ? temp->left : temp->right;
            free(temp2);
        }
        else {
            temp->key = find_min(temp->right)->key;
            temp->right = delete_node(&temp->right, temp->key);
        }
    }

    if (height(temp) < 0)
        *root = balance(temp);

    return;
}

int height(Node* node) {
    int height = 0;
    while (node != NULL) {
        height++;
        node = node->left;
    }
    return height - 1;
}

Node* left_rotate(Node* x) {
    Node* y = x->right;
    Node* T2 = y->left;

    y->left = x;
    x->right = T2;

    return y;
}

Node* right_rotate(Node* y) {
    Node* x = y->left;
    Node* T2 = x->right;

    x->right = y;
    y->left = T2;

    return x;
}

Node* balance(Node* z) {
    int lheight = height(z->left);
    int rheight = height(z->right);

    if (lheight > rheight + 1) {
        if (height(z->left->left) >= height(z->left->right))
            return right_rotate(z);
        else
            z->left = left_rotate(z->left);
        return right_rotate(z);
    }
    else if (rheight > lheight + 1) {
        if (height(z->right->right) >= height(z->right->left))
            return left_rotate(z);
        else
            z->right = right_rotate(z->right);
        return left_rotate(z);
    }

    return z;
}
