typedef struct {
    int deadline;
    int complexity;
    struct project* next;
} project;

project* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void insert_project(project* new_project, int position) {
    if (position > 0) {
        project* current = head;
        for (int i = 0; i < position - 1; i++) {
            current = current->next;
        }
        project* temp = head;
        while (temp->next != current) {
            temp = temp->next;
        }
        new_project->next = current->next;
        current->next = new_project;
    } else {
        new_project->next = head;
        head = new_project;
    }
}

void update_project(project* project_ptr, int deadline_new, int complexity_new) {
    if (project_ptr) {
        project_ptr->deadline = deadline_new;
        project_ptr->complexity = complexity_new;
    }
}

void remove_project(int position) {
    project* current = head;
    for (int i = 0; i < position - 1; i++) {
        current = current->next;
    }
    if (current && current->next) {
        project* temp = current->next;
        current->next = temp->next;
        free(temp);
    } else {
        head = NULL;
    }
}

void print_project_list() {
    project* current = head;
    while (current != NULL) {
        printf("Deadline: %d, Complexity: %d\n", current->deadline, current->complexity);
        current = current->next;
    }
}
