    srand(seed);

    *records_ptr = (Record**)malloc(sizeof(Record*) * 3);
    if (*records_ptr == NULL) {
        // Handle memory allocation failure
        return;
    }

    Record** offset_records = &(*records_ptr)[0];
    Record** key_records = &(*records_ptr)[1];
    Record** record_records = &(*records_ptr)[2];

