        Record* new_record = create_record(value, data);
        if (!new_record) {
            // Handle memory allocation failure
            return;
        }

        Record* last_record = NULL;
        for (int j = 0; j < i; j++) {
            Record* current_record = *record_records++;
            current_record->next = new_record;
            new_record->prev = current_record;
            if (j == i - 1) {
                new_record->prev = last_record;
                last_record->next = new_record;
            }
        }

        offset_records[i] = &new_record->value;
        key_records[i] = &i;
