// Function to dynamically allocate memory and initialize the arrays
Record* initArrays(int numRecords, int maxListSize, int requestSnapshot) {
    // Initialize random seed for generating unique values
    srand(time(NULL));

    // Calculate total memory required for 'record' structures
    long totalMem = sizeof(Record) * (numRecords + 1);

    // Allocate memory for 'records', 'offsets', and 'keys'
    Record* records = (Record*)malloc(totalMem);
    if (!records) {
        return NULL;
    }

    long* offsets = (long*)malloc(sizeof(long) * numRecords);
    if (!offsets) {
        free(records);
        return NULL;
    }

    int* keys = (int*)malloc(sizeof(int) * numRecords);
    if (!keys) {
        free(records);
        free(offsets);
        return NULL;
    }

    // Initialize arrays with unique values based on the provided seed
    populateArrays(&records, &offsets, keys, numRecords);

    // Initialize linked list and circular doubly-linked structure
    Record* head = &records[0];
    for (int i = 1; i < numRecords; i++) {
        head->next = &records[i];
        head = &records[i];
    }
    head->next = &records[0]; // Circularly link the last node back to the first

    if (requestSnapshot) {
        Record** snapshot = (Record**)malloc(sizeof(Record*) * numRecords);
        for (int i = 0; i < numRecords; i++) {
            snapshot[i] = &records[i];
        }
        return head, snapshot;
    } else {
        return head;
    }
}

