#define EVENT_ID_SIZE 16     // size of unique event ID

typedef struct {
    int timestamp;
    char type;               // 'A', 'B', or 'C'
    char id[EVENT_ID_SIZE];   // unique identifier, up to 16 characters
} Event;

// dynamic array of events
Event* events;
size_t capacity = 0;
size_t size = 0;

void resize(int factor) {
    int new_capacity = capacity * factor;
    Event* new_events = (Event*) realloc(events, new_capacity * sizeof(Event));
    if (!new_events) {
        printf("Error: failed to allocate memory\n");
        exit(1);
    }
    events = new_events;
    capacity = new_capacity;
}

void insert_event(Event e) {
    if (size == capacity) {
        resize(2); // double the capacity
    }

    events[size++] = e;
}

Event* find_event(const char* id) {
    for (int i = 0; i < size; i++) {
        if (!strcmp(events[i].id, id)) {
            return &events[i];
        }
    }
    return NULL;
}

void delete_event(const char* id) {
    Event* event = find_event(id);
    if (event == NULL) {
        printf("Error: event not found\n");
        return;
    }

    // shift remaining events forward
    for (int i = event - events; i < size; i++) {
        events[i] = events[i + 1];
    }
    size--;

    // if capacity is reached, rehash the array
    if (size >= capacity * 0.8) {
        resize(2); // double the capacity
    }
}

void compact() {
    int new_size = 0;
    for (int i = 0; i < size; i++) {
        if (events[i].id[0] != '\0') { // skip empty events
            events[new_size++] = events[i];
        } else {
            printf("Error: found empty event\n");
        }
    }

    Event* new_events = (Event*) realloc(events, new_size * sizeof(Event));
    if (!new_events) {
        printf("Error: failed to allocate memory\n");
        exit(1);
    }
    events = new_events;
    size = new_size;
}

void serialize_to_file(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        printf("Error: failed to open file for writing\n");
        return;
    }

    int offset = 0;
    fwrite(&size, sizeof(size_t), 1, file);
    for (int i = 0; i < size; i++) {
        fwrite(&events[i], sizeof(Event), 1, file);
    }
}

void deserialize_from_file(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        printf("Error: failed to open file for reading\n");
        return;
    }

    fread(&size, sizeof(size_t), 1, file);
    events = (Event*) malloc(size * sizeof(Event));
    for (int i = 0; i < size; i++) {
        fread(&events[i], sizeof(Event), 1, file);
    }
}

int main() {
    // initialize the event array with a capacity of 16
    events = (Event*) malloc(16 * sizeof(Event));
    capacity = 16;
    size = 0;

    // simulate inserting, finding, and deleting events
