        printf("Found event: %d, '%c'\n", event->timestamp, event->type);
    } else {
        printf("Event not found\n");
    }
    delete_event("event1");

    // serialize and deserialize the event array
    serialize_to_file("events.dat");
    deserialize_from_file("events.dat");

    return 0;
}
