#define MAX_RECORDS 10000000
#define BLOCK_SIZE 1024
#define TABLE_SIZE 256

typedef struct {
    double value1;
    long value2;
    int value3;
} Record;

Record* table;
pthread_mutex_t lock;
int record_count = 0;
int current_block = -1;
int next_available_slot = 0;

void* allocate_record() {
    if (current_block == TABLE_SIZE) {
        return NULL; // No more blocks available
    }
    return &table[next_available_slot++];
}

void resize_table() {
    int new_table_size = TABLE_SIZE * 2;
    Record* new_table = (Record*)malloc(new_table_size * sizeof(Record));

    if (!new_table) {
        printf("Error: unable to allocate memory for resized table.\n");
        return; // Error handling
    }

    current_block = -1;
    next_available_slot = 0;

    // Copy records from old table to new table
    for (int i = 0; i < TABLE_SIZE; i++) {
        Record* block_start = &table[i * BLOCK_SIZE];
        int block_count = fmin(TABLE_SIZE, record_count % TABLE_SIZE);

        for (int j = 0; j < block_count; j++) {
            new_table[next_available_slot++] = block_start[j];
        }
    }

    // Deallocate old table
    free(table);
    table = new_table;
}

void serialize_to_file() {
    FILE* file = fopen("data.txt", "wb");

    if (!file) {
        printf("Error: unable to open data file for writing.\n");
        return; // Error handling
    }

    fwrite(&record_count, sizeof(int), 1, file);
    fwrite(&current_block, sizeof(int), 1, file);

    for (int i = 0; i < TABLE_SIZE; i++) {
        Record* block_start = &table[i * BLOCK_SIZE];
        int block_count = fmin(TABLE_SIZE, record_count % TABLE_SIZE);

        fwrite(block_start, sizeof(Record), block_count, file);
    }

    fclose(file);
}

void deserialize_from_file() {
    FILE* file = fopen("data.txt", "rb");

    if (!file) {
        printf("Error: unable to open data file for reading.\n");
        return; // Error handling
    }

    fread(&record_count, sizeof(int), 1, file);
    fread(&current_block, sizeof(int), 1, file);

    table = (Record*)malloc(TABLE_SIZE * BLOCK_SIZE * sizeof(Record));

    for (int i = 0; i < TABLE_SIZE; i++) {
        Record* block_start = &table[i * BLOCK_SIZE];
        int block_count = fmin(TABLE_SIZE, record_count % TABLE_SIZE);

        fread(block_start, sizeof(Record), block_count, file);
    }

    fclose(file);
}

