EntityCollection* entity_collection_new(size_t initial_capacity) {
    EntityCollection* collection = (EntityCollection*)malloc(sizeof(EntityCollection));
    collection->entities = (Entity*)calloc(initial_capacity, sizeof(Entity));
    collection->capacity = initial_capacity;
    collection->count = 0;
    return collection;
}

void entity_collection_insert(EntityCollection* collection, Entity new_entity) {
    if (collection->count >= collection->capacity * 3/4) {
        // Reallocate memory to prevent fragmentation
        size_t new_capacity = collection->capacity * 2;
        Entity* new_entities = (Entity*)realloc(collection->entities, new_capacity * sizeof(Entity));
        collection->entities = new_entities;
        collection->capacity = new_capacity;
    }
    collection->entities[collection->count] = new_entity;
    collection->count++;
}

void entity_collection_delete_by_uid(EntityCollection* collection, int target_uid) {
    for (size_t i = 0; i < collection->count; i++) {
        if (collection->entities[i].uid == target_uid) {
            memmove(&collection->entities[i], &collection->entities[i+1], sizeof(Entity)*(collection->count - i - 1));
            collection->count--;
            return;
        }
    }
}

Entity* entity_collection_get_by_uid(EntityCollection* collection, int target_uid) {
    for (size_t i = 0; i < collection->count; i++) {
        if (collection->entities[i].uid == target_uid) {
            return &collection->entities[i];
        }
