```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the structure to represent records
typedef struct {
    int value;
} record_t;

// Define the structure to represent the data storage system
typedef struct {
    long* offsets;
    int* keys;
    record_t** records;
    int* last_accessed;
    int size;
    int capacity;
} storage_system_t;

// Function to create a new storage system with an initial capacity
storage_system_t* create_storage_system(int initial_capacity) {
    storage_system_t* ss = malloc(sizeof(storage_system_t));
    ss->offsets = malloc(initial_capacity * sizeof(long));
    ss->keys = malloc(initial_capacity * sizeof(int));
    ss->records = malloc(initial_capacity * sizeof(record_t*));
    ss->last_accessed = malloc(initial_capacity * sizeof(int));
    ss->size = 0;
    ss->capacity = initial_capacity;
    return ss;
}

// Function to insert a new record into the storage system
void insert_record(storage_system_t* ss, int key, int value) {
    if (ss->size == ss->capacity) {
        // Dynamically resize the arrays when full
        ss->capacity *= 2;
        ss->offsets = realloc(ss->offsets, ss->capacity * sizeof(long));
        ss->keys = realloc(ss->keys, ss->capacity * sizeof(int));
        ss->records = realloc(ss->records, ss->capacity * sizeof(record_t*));
        ss->last_accessed = realloc(ss->last_accessed, ss->capacity * sizeof(int));
    }
    ss->offsets[ss->size] = (long)ss->keys;
    ss->keys[ss->size] = key;
    ss->records[ss->size] = malloc(sizeof(record_t));
    (*ss->records[ss->size])->value = value;
    ss->last_accessed[ss->size] = -1; // Mark as not accessed yet
    ss->size++;
}

// Function to update an existing record in the storage system
void update_record(storage_system_t* ss, int key, int new_value) {
    for (int i = 0; i < ss->size; i++) {
        if (ss->keys[i] == key) {
            // Update the value of the existing record
            (*ss->records[i])->value = new_value;
            return;
        }
    }
}

// Function to delete a record from the storage system
void delete_record(storage_system_t* ss, int key) {
    for (int i = 0; i < ss->size; i++) {
        if (ss->keys[i] == key) {
            // Move the last record to fill the gap and update offsets
            long offset = ss->offsets[ss->size - 1];
            int* new_key = &ss->keys[i];
            record_t* new_record = ss->records[i];
            for (int j = i; j < ss->size - 1; j++) {
                ss->keys[j] = ss->keys[j + 1];
                ss->offsets[j] = ss->offsets[j + 1];
                ss->records[j] = ss->records[j + 1];
                ss->last_accessed[j] = ss->last_accessed[j + 1];
            }
            ss->size--;
            free(ss->keys[ss->size]);
            free(ss->records[ss->size]);
            free(&ss->last_accessed[ss->size]);
            break;
        }
    }
}

// Function to serialize the storage system to a file
void serialize_storage_system(storage_system_t* ss, char* filename) {
    FILE* f = fopen(filename, "wb");
    if (f == NULL) return; // Handle error

