HashTable* createHashTable(size_t capacity) {
    HashTable* hashTable = (HashTable*)malloc(sizeof(HashTable));
    hashTable->capacity = capacity;
    hashTable->size = 0;
    hashTable->events = (Event**)calloc(capacity, sizeof(Event*));
    return hashTable;
}

