void insertEvent(HashTable* hashTable, Event* event) {
    size_t index = event->uniqueId % hashTable->capacity;
    if (!hashTable->events[index]) {
        hashTable->events[index] = (Event*)malloc(sizeof(Event));
        *hashTable->events[index] = *event;
        hashTable->size++;
    } else {
        // Handle collision
        size_t nextIndex = (index + 1) % hashTable->capacity;
        if (!hashTable->events[nextIndex]) {
