#include <string.h>
#include <inttypes.h>

typedef struct {
    char name[64];
    uint32_t ID;
    double value;
} CustomObject;

typedef struct {
    CustomObject* data;
    size_t capacity;
    size_t size;
    uint32_t* last_accessed_IDs; // Hash table to track the last accessed index of each object by its ID
} DynamicList;

DynamicList* create_dynamic_list(size_t initial_capacity) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    list->data = (CustomObject*)calloc(initial_capacity, sizeof(CustomObject));
    list->capacity = initial_capacity;
    list->size = 0;
    list->last_accessed_IDs = (uint32_t*)calloc(list->capacity, sizeof(uint32_t));
    return list;
}

void add_object(DynamicList* list, CustomObject obj) {
    if (list->size >= list->capacity) {
        list->capacity *= 2; // Double the capacity when needed
        list->data = (CustomObject*)realloc(list->data, list->capacity * sizeof(CustomObject));
        list->last_accessed_IDs = (uint32_t*)realloc(list->last_accessed_IDs, list->capacity * sizeof(uint32_t));
    }
    memcpy(&list->data[list->size], &obj, sizeof(CustomObject));
    list->last_accessed_IDs[list->size] = obj.ID;
    list->size++;
}

void remove_object(DynamicList* list, uint32_t ID) {
    for (int i = 0; i < list->size; i++) {
        if (list->data[i].ID == ID) {
            // Move the last object to the removed position and decrement size
            memcpy(&list->data[i], &list->data[list->size - 1], sizeof(CustomObject));
            list->last_accessed_IDs[i] = list->last_accessed_IDs[list->size - 1];
            list->size--;
            break;
        }
    }
}

void update_object(DynamicList* list, uint32_t ID, CustomObject obj) {
    for (int i = 0; i < list->size; i++) {
        if (list->data[i].ID == ID) {
            memcpy(&list->data[i], &obj, sizeof(CustomObject));
            break;
        }
    }
}

CustomObject* get_object(DynamicList* list, uint32_t ID) {
    for (int i = 0; i < list->size; i++) {
        if (list->data[i].ID == ID) {
            return &list->data[i];
        }
    }
    return NULL;
}

void serialize_dynamic_list(DynamicList* list, FILE* file) {
    fwrite(&list->capacity, sizeof(size_t), 1, file);
    fwrite(&list->size, sizeof(size_t), 1, file);
    for (int i = 0; i < list->size; i++) {
        CustomObject obj;
        memcpy(&obj, &list->data[i], sizeof(CustomObject));
        fwrite(&obj.ID, sizeof(uint32_t), 1, file);
        fwrite(&obj.value, sizeof(double), 1, file);
        strcpy(obj.name, list->data[i].name); // Copy the name string
        fwrite(&strchr(list->data[i].name, '\0'), sizeof(char), strlen(obj.name), file);
    }
}

DynamicList* deserialize_dynamic_list(FILE* file) {
    DynamicList* list = create_dynamic_list(1000); // Start with an initial capacity of 1000

    size_t capacity;
    fread(&capacity, sizeof(size_t), 1, file);
    size_t size;
    fread(&size, sizeof(size_t), 1, file);

    for (int i = 0; i < size; i++) {
        CustomObject obj;
        fread(&obj.ID, sizeof(uint32_t), 1, file);
        fread(&obj.value, sizeof(double), 1, file);
        fread(obj.name, sizeof(char), capacity * sizeof(char), file); // Read the name string
        add_object(list, obj);
    }

    return list;
}

void free_dynamic_list(DynamicList* list) {
    for (int i = 0; i < list->size; i++) {
        free(&list->data[i].name); // Free the name strings
    }
    free(list->data);
    free(list->last_accessed_IDs);
    free(list);
}

int main() {
    DynamicList* list = create_dynamic_list(1000);

    // Add objects, remove an object, update a value, and retrieve an object
    CustomObject obj1 = {"John", 123, 3.14};
    add_object(list, obj1);
    CustomObject obj2 = {"Jane", 456, 2.71};
    add_object(list, obj2);

    remove_object(list, 456);

    update_object(list, 123, (CustomObject){.name="John Updated", .ID=123, .value=3.14159});

    CustomObject* retrieved_obj = get_object(list, 123);
    printf("Retrieved object: %s (%d) - %.5lf\n", retrieved_obj->name, retrieved_obj->ID, retrieved_obj->value);

    FILE* file = fopen("data.bin", "wb");
    serialize_dynamic_list(list, file);
    fclose(file);

    DynamicList* deserialized_list = deserialize_dynamic_list(fopen("data.bin", "rb"));
    free_dynamic_list(deserialized_list);

    return 0;
}
