#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/mman.h>

typedef struct {
    char name[64];
    int id;
    double value;
} CustomObject;

// Define a custom hash table structure
typedef struct {
    unsigned long size; // Size of the hash table
    CustomObject** buckets; // Array to store hash values
    int collisionCount; // Count of collisions in the hash table
} HashTable;

// Function to create a new hash table with a given initial capacity
HashTable* createHashTable(int initialCapacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->size = initialCapacity;
    table->buckets = (CustomObject**)malloc(sizeof(CustomObject*) * initialCapacity);
    for(int i=0; i<table->size; i++)
        table->buckets[i] = NULL;
    table->collisionCount = 0;
    return table;
}

// Function to resize the hash table
void resizeHashTable(HashTable* table, int newCapacity) {
    HashTable* newTable = createHashTable(newCapacity);
    for(int i=0; i<table->size; i++) {
        CustomObject* obj = table->buckets[i];
        while(obj != NULL) {
            int index = obj->id % newCapacity;
            obj->next = newTable->buckets[index];
            newTable->buckets[index] = obj;
            obj = obj->next;
        }
    }
    free(table->buckets);
    table->size = newCapacity;
    table->buckets = newTable->buckets;
}

// Function to insert an object into the hash table
void insertObject(HashTable* table, CustomObject* obj) {
    int index = obj->id % table->size;
    if(table->buckets[index] == NULL)
        table->buckets[index] = obj;
    else {
        // Handle collision using chaining
        CustomObject* current = table->buckets[index];
        while(current->next != NULL)
            current = current->next;
        current->next = obj;
        table->collisionCount++;
    }
}

// Function to remove an object by ID from the hash table
void removeObject(HashTable* table, int id) {
    for(int i=0; i<table->size; i++) {
        CustomObject* current = table->buckets[i];
        while(current != NULL) {
            if(current->id == id) {
                // Remove the object from the chain
                if(current->next != NULL)
                    current->next = current->next->next;
                else
                    table->buckets[i] = current->next;
                free(current);
                return;
            }
            current = current->next;
        }
    }
}

// Function to update an object's value by ID from the hash table
void updateObject(HashTable* table, int id, double newValue) {
    for(int i=0; i<table->size; i++) {
        CustomObject* current = table->buckets[i];
        while(current != NULL) {
            if(current->id == id) {
                current->value = newValue;
                return;
            }
            current = current->next;
        }
    }
}

// Function to retrieve an object by ID from the hash table
CustomObject* getObject(HashTable* table, int id) {
    for(int i=0; i<table->size; i++) {
        CustomObject* current = table->buckets[i];
        while(current != NULL) {
            if(current->id == id)
                return current;
            current = current->next;
        }
    }
    return NULL;
}

// Function to serialize the hash table to a file
void serialize(HashTable* table, FILE* file) {
    fwrite(&table->size, sizeof(int), 1, file);
    for(int i=0; i<table->size; i++) {
        CustomObject* obj = table->buckets[i];
        while(obj != NULL) {
            fwrite(&obj->id, sizeof(int), 1, file);
            fwrite(&obj->value, sizeof(double), 1, file);
            obj = obj->next;
        }
    }
}

// Function to deserialize the hash table from a file
HashTable* deserialize(FILE* file) {
    HashTable* table = createHashTable(16); // Initial capacity
    int size;
    fread(&size, sizeof(int), 1, file);
    for(int i=0; i<size; i++) {
        CustomObject* obj = (CustomObject*)malloc(sizeof(CustomObject));
        fread(&obj->id, sizeof(int), 1, file);
        fread(&obj->value, sizeof(double), 1, file);
        int index = obj->id % table->size;
        if(table->buckets[index] == NULL)
            table->buckets[index] = obj;
        else {
            // Handle collision using chaining
            CustomObject* current = table->buckets[index];
            while(current->next != NULL)
                current = current->next;
            current->next = obj;
            table->collisionCount++;
        }
    }
    return table;
}

int main() {
    // Example usage
    HashTable* table = createHashTable(16);
    CustomObject* obj1 = (CustomObject*)malloc(sizeof(CustomObject));
    strcpy(obj1->name, "Object 1");
    obj1->id = 1;
    obj1->value = 10.0;

    CustomObject* obj2 = (CustomObject*)malloc(sizeof(CustomObject));
    strcpy(obj2->name, "Object 2");
    obj2->id = 2;
    obj2->value = 20.0;

    insertObject(table, obj1);
    insertObject(table, obj2);

    // Serialize the hash table to a file
    FILE* file = fopen("data.dat", "wb");
    serialize(table, file);
    fclose(file);

    // Deserialize the hash table from the file
    HashTable* deserializedTable = deserialize(fopen("data.dat", "rb"));
    fclose(file);

    // Retrieve and update objects
    CustomObject* objRetrieved = getObject(deserializedTable, 1);
    if(objRetrieved != NULL)
        printf("Object retrieved: %s (ID: %d, Value: %.2lf)\n",
               objRetrieved->name, objRetrieved->id, objRetrieved->value);

    updateObject(deserializedTable, 1, 30.0);

    // Remove an object
    removeObject(deserializedTable, 2);

    return 0;
}
