#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 10000
#define LOG_FILE "record_log.txt"

typedef struct {
    int key;
    double value;
    char* str;
} Record;

Record* records = NULL;
int record_count = 0;
int record_max_size = MAX_RECORDS * sizeof(Record);
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
FILE* log_file = fopen(LOG_FILE, "a+");

void resize_records(int new_size) {
    Record* new_records = (Record*)malloc(new_size * sizeof(Record));
    Record* old_records = records;
    records = new_records;
    free(old_records);
}

void add_record(int key, double value, char* str) {
    pthread_mutex_lock(&lock);
    if (record_count == record_max_size) {
        int new_max_size = record_max_size * 2;
        resize_records(new_max_size);
        record_max_size = new_max_size;
    }
    records[record_count].key = key;
    records[record_count].value = value;
    records[record_count].str = str;
    record_count++;
    pthread_mutex_unlock(&lock);
}

void log_change(int index, char* action) {
    fprintf(log_file, "Record %d: %s\n", index, action);
    fflush(log_file);
}

void serialize_records(FILE* file) {
    fwrite(&record_count, sizeof(int), 1, file);
    for (int i = 0; i < record_count; i++) {
        fwrite(&records[i], sizeof(Record), 1, file);
    }
}

void deserialize_records(FILE* file) {
    int count;
    fread(&count, sizeof(int), 1, file);
    records = (Record*)malloc(count * sizeof(Record));
    for (int i = 0; i < count; i++) {
        fread(&records[i], sizeof(Record), 1, file);
    }
}

void* thread_func(void* arg) {
    int key = *(int*)arg;
    // perform read-heavy or occasional write operations
    add_record(key, 3.14, "Hello");
    log_change(key, "added");
    return NULL;
}

int main() {
    pthread_t threads[MAX_RECORDS];
    for (int i = 0; i < MAX_RECORDS; i++) {
        int* key = (int*)malloc(sizeof(int));
        *key = i;
        pthread_create(&threads[i], NULL, thread_func, key);
    }
    for (int i = 0; i < MAX_RECORDS; i++) {
        pthread_join(threads[i], NULL);
    }
    fclose(log_file);
    return 0;
}
