#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>

typedef struct {
    char* name;
    int id;
    double value;
} CustomObject;

// Function to create a new CustomObject
CustomObject* custom_object_create(char* name, int id, double value) {
    CustomObject* obj = (CustomObject*)malloc(sizeof(CustomObject));
    obj->name = strdup(name);
    obj->id = id;
    obj->value = value;
    return obj;
}

// Function to add an object to the list
void custom_object_add(CustomObject** objects, int* size, CustomObject* obj) {
    if (*size == 0 || (*objects)[*size - 1]->id != obj->id) {
        *size += 1;
        *objects = (CustomObject**)realloc(*objects, sizeof(CustomObject*) * (*size + 1));
        (*objects)[*size - 1] = obj;
    } else {
        int i;
        for (i = *size; i > 0; i--) {
            if ((*objects)[i-1]->id != obj->id) break;
            (*objects)[i-1] = obj;
            free((*objects)[i]);
            *size -= 1;
        }
    }
}

// Function to remove an object from the list
void custom_object_remove(CustomObject** objects, int* size, int id) {
    int i;
    for (i = 0; i < *size; i++) {
        if ((*objects)[i]->id == id) {
            for (int j = i + 1; j < *size; j++) {
                (*objects)[i] = (*objects)[j];
                free((*objects)[j]);
            }
            *size -= 1;
            break;
        }
    }
}

// Function to update an object's value
void custom_object_update(CustomObject** objects, int* size, int id, double value) {
    for (int i = 0; i < *size; i++) {
        if ((*objects)[i]->id == id) {
            (*objects)[i]->value = value;
            break;
        }
    }
}

// Function to retrieve an object by ID
CustomObject* custom_object_get(CustomObject** objects, int size, int id) {
    for (int i = 0; i < size; i++) {
        if ((*objects)[i]->id == id) return (*objects)[i];
    }
    return NULL;
}

// Function to serialize the list of CustomObjects
void custom_object_serialize(CustomObject** objects, int size, FILE* file) {
    fwrite(&size, sizeof(int), 1, file);
    for (int i = 0; i < size; i++) {
        fwrite(&((*objects)[i]->name), sizeof(char*), 1, file);
        fwrite(&((*objects)[i]->id), sizeof(int), 1, file);
        fwrite(&((*objects)[i]->value), sizeof(double), 1, file);
    }
}

// Function to deserialize the list of CustomObjects
void custom_object_deserialize(CustomObject** objects, int* size, FILE* file) {
    fread(size, sizeof(int), 1, file);
    *objects = (CustomObject**)malloc(sizeof(CustomObject*) * (*size));
    for (int i = 0; i < *size; i++) {
        char* name = malloc(strlen((*objects)[i]->name) + 1);
        fread(name, sizeof(char*), 1, file);
        int id;
        fread(&id, sizeof(int), 1, file);
        double value;
        fread(&value, sizeof(double), 1, file);
    }
}

// Function to test the custom object management
