    CustomObject* obj2 = custom_object_create("Object 2", 2, 20.0);
    custom_object_add(&objects, &size, obj1);
    custom_object_add(&objects, &size, obj2);

    // Serialize the list to a file
    FILE* file = fopen("data.txt", "wb");
    custom_object_serialize(objects, size, file);
    fclose(file);

    // Deserialize the list from the file
    file = fopen("data.txt", "rb");
    int newSize;
