    fread(&next_index, sizeof(int), 1, file);
    records = (record_t*)calloc(next_index, sizeof(record_t));
    offsets = (long*)calloc(next_index, sizeof(long));
    keys = (int*)calloc(next_index, sizeof(int));
    strings = (char**)malloc(next_index * sizeof(char*));

    for (i = 0; i < next_index; i++) {
        fread(&records[i].key, sizeof(int), 1, file);
        size_t str_len;
        fread(&str_len, sizeof(size_t), 1, file);
        records[i].string = (char*)malloc((size_t)(str_len) * sizeof(char));
        fread(records[i].string, sizeof(char), str_len, file);
        fread(&records[i].offset, sizeof(long), 1, file);
    }

    fclose(file);
}

void record_access(record_t* record) {
    pthread_mutex_lock(&mutex);
    record->access_count++;
    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&mutex);
}
