#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the maximum number of records
#define MAX_RECORDS 10000

// Define the record structure
typedef struct {
    int key;
    char* value;
    int ref_count;
} Record;

// Define the data structure to store and manipulate the collection of records
typedef struct {
    Record** records;
    int num_records;
    pthread_mutex_t mutex;
} RecordCollection;

// Initialize a new record with dynamically allocated string value and reference count
Record* init_record(int key, char* value) {
    Record* rec = (Record*)malloc(sizeof(Record));
    rec->key = key;
    rec->value = (char*)malloc(strlen(value) + 1);
    strcpy(rec->value, value);
    rec->ref_count = 0;
    return rec;
}

// Free the dynamically allocated memory for a record
void free_record(Record* rec) {
    if (rec != NULL) {
        free(rec->value);
        free(rec);
    }
}

// Create a new record collection with initial capacity and synchronization mutex
RecordCollection* create_collection(int initial_capacity) {
    RecordCollection* col = (RecordCollection*)malloc(sizeof(RecordCollection));
    col->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    col->num_records = 0;
    pthread_mutex_init(&col->mutex, NULL);
    return col;
}

// Add a record to the collection
void add_record(RecordCollection* col, Record* rec) {
    pthread_mutex_lock(&col->mutex);

    // Resize the array if necessary
    if (col->num_records >= sizeof(col->records) / sizeof(col->records[0])) {
        col->records = (Record**)realloc(col->records, MAX_RECORDS * sizeof(Record*));
    }

    // Increment reference count and add record to the collection
    rec->ref_count++;
    col->records[col->num_records++] = rec;

    pthread_mutex_unlock(&col->mutex);
}

// Remove a record from the collection with reference counting and synchronization
void remove_record(RecordCollection* col, Record* rec) {
    pthread_mutex_lock(&col->mutex);

    // Decrement reference count and remove record if not in use
    rec->ref_count--;
    for (int i = 0; i < col->num_records; i++) {
        if (rec == col->records[i] && rec->ref_count <= 0) {
            free_record(rec);
            memmove(&col->records[i], &col->records[i + 1], (col->num_records - i - 1) * sizeof(Record*));
            col->num_records--;
            break;
        }
    }

    pthread_mutex_unlock(&col->mutex);
}

// Serialize the record collection to a file
void serialize_collection(RecordCollection* col, const char* filename) {
    FILE* f = fopen(filename, "wb");
    if (f == NULL) return;

    // Write the number of records and each record's key-value pair
    fwrite(&col->num_records, sizeof(int), 1, f);
    for (int i = 0; i < col->num_records; i++) {
        Record* rec = col->records[i];
        fwrite(&rec->key, sizeof(int), 1, f);
        size_t len = strlen(rec->value);
        fwrite(&len, sizeof(size_t), 1, f);
        fwrite(rec->value, 1, len + 1, f);
    }

    fclose(f);
}

// Deserialize the record collection from a file
RecordCollection* deserialize_collection(const char* filename) {
    RecordCollection* col = create_collection(MAX_RECORDS);

    FILE* f = fopen(filename, "rb");
    if (f == NULL) return NULL;

    // Read the number of records and each record's key-value pair
    int num_records;
    fread(&num_records, sizeof(int), 1, f);
    for (int i = 0; i < num_records; i++) {
        Record* rec = init_record(0, NULL);  // Initialize with default values

        fread(&rec->key, sizeof(int), 1, f);
        size_t len;
        fread(&len, sizeof(size_t), 1, f);
        char* value = (char*)malloc(len + 1);
        fread(value, 1, len + 1, f);
        rec->value = value;

        add_record(col, rec);
    }

    fclose(f);

    return col;
}

// Find and print the largest integer in the collection
void find_largest_key(RecordCollection* col) {
    int max_key = INT_MIN;
    pthread_mutex_lock(&col->mutex);

    for (int i = 0; i < col->num_records; i++) {
        Record* rec = col->records[i];
        if (rec->key > max_key) max_key = rec->key;
    }

    pthread_mutex_unlock(&col->mutex);
    printf("Largest key: %d\n", max_key);
}

int main() {
    // Create a new record collection
    RecordCollection* col = create_collection(MAX_RECORDS);

    // Add records to the collection
    add_record(col, init_record(1, "Hello"));
    add_record(col, init_record(2, "World"));
    add_record(col, init_record(3, "This"));

    // Serialize the record collection
    serialize_collection(col, "records.bin");

    // Deserialize and print the largest key
    RecordCollection* deserialized_col = deserialize_collection("records.bin");
    find_largest_key(deserialized_col);

    // Clean up
    for (int i = 0; i < deserialized_col->num_records; i++) {
        free_record(deserialized_col->records[i]);
    }
    free_deserialized_col(deserialized_col);
    return 0;
}

