#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct {
    char username[20];
    char email[30];
    time_t date_of_birth;
} Profile;

void* malloc_or_die(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        printf("Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

Profile** dynamic_array(int capacity) {
    return (Profile**)malloc_or_die(capacity * sizeof(Profile*));
}

void resize_array(Profile** arr, int old_capacity, int new_capacity) {
    Profile** temp = (Profile**)malloc_or_die(new_capacity * sizeof(Profile*));

    for (int i = 0; i < old_capacity && i < new_capacity; i++) {
        temp[i] = arr[i];
    }
    for (int i = old_capacity; i < new_capacity; i++) {
        temp[i] = NULL;
    }

    free(arr);
    arr = temp;
}

Profile* create_profile() {
    Profile* profile = (Profile*)malloc_or_die(sizeof(Profile));
    // Populate username and email fields with random values
    // Ensure no two profiles have the same username or email within the specified constraints
    strcpy(profile->username, "random_username");
    strcpy(profile->email, "random_email@example.com");
    time_t now = time(NULL);
    profile->date_of_birth = now;

    return profile;
}

void free_profiles(Profile** arr, int capacity) {
    for (int i = 0; i < capacity; i++) {
        if (arr[i] != NULL) {
            free(arr[i]);
            arr[i] = NULL;
        }
    }

    free(arr);
}

Profile* find_oldest_profile(Profile** profiles, int capacity) {
    Profile* oldest = NULL;

    for (int i = 0; i < capacity; i++) {
        if (profiles[i]->date_of_birth > oldest->date_of_birth) {
            oldest = profiles[i];
        }
    }

    return oldest;
}

void serialize_profiles(Profile** profiles, int capacity, FILE* file) {
    // Serialize the array of profiles to a file
    for (int i = 0; i < capacity; i++) {
        if (profiles[i] != NULL) {
            fwrite(profiles[i]->username, sizeof(char), strlen(profiles[i]->username), file);
            fwrite(&profiles[i]->email, sizeof(char), strlen(profiles[i]->email), file);
            fwrite(&profiles[i]->date_of_birth, sizeof(time_t), 1, file);
        }
    }

    fclose(file);
}

Profile** deserialize_profiles(FILE* file) {
    Profile** profiles = NULL;
    int capacity = 0;

    // Read the number of profiles from the file
    fseek(file, 0, SEEK_END);
    size_t fileSize = ftell(file);

    if (fileSize > 0) {
        rewind(file);
        fread(&capacity, sizeof(int), 1, file);

        profiles = dynamic_array(capacity);

        for (int i = 0; i < capacity; i++) {
            Profile* profile = create_profile();
            fread(profile->username, sizeof(char), strlen(profiles[i]->username), file);
            fread(&profile->email, sizeof(char), strlen(profiles[i]->email), file);
            fread(&profile->date_of_birth, sizeof(time_t), 1, file);

            profiles[i] = profile;
        }
    }

    fclose(file);

    return profiles;
}

int main() {
    // Initialize the dynamic array
    Profile** profiles = NULL;
    int capacity = 0;

    // Allocate memory for the initial 10 profiles
    profiles = (Profile**)malloc_or_die(10 * sizeof(Profile*));
    for (int i = 0; i < 10; i++) {
        profiles[i] = create_profile();
    }
    capacity = 10;

    // Populate each profile’s username and email fields with random values
    // Ensure no two profiles have the same username or email within the specified constraints

    // Resize the array when necessary to accommodate new profiles
    // Implement mechanisms to optimize memory usage and performance

    // Serialize the data structure to a file for persistence
    FILE* file = fopen("profiles.bin", "wb");
    serialize_profiles(profiles, capacity, file);
    fclose(file);

    // Deserialize the data structure from the file back into memory
    file = fopen("profiles.bin", "rb");
    Profile** deserialized_profiles = deserialize_profiles(file);
    fclose(file);

    // Find and print the oldest profile based on the date of birth
    Profile* oldest_profile = find_oldest_profile(deserialized_profiles, capacity);
    printf("Oldest profile: %s - %s - %ld\n", oldest_profile->username, oldest_profile->email, oldest_profile->date_of_birth);

    // Free all allocated memory when the data structure is no longer needed
    free_profiles(profiles, capacity);
    free_profiles(deserialized_profiles, capacity);

    return 0;
}
