#define MAX_SESSIONS 1000
#define SESSION_INFO_SIZE sizeof(struct Session)

typedef struct {
    char* sessionId;
    char* ipAddress;
    time_t loginTimestamp;
} Session;

Session** sessionList = NULL;
int sessionCount = 0;

void addSession(Session* newSession) {
    Session** updatedList = (Session**)realloc(sessionList, (sessionCount + 1) * SESSION_INFO_SIZE);
    if (!updatedList) {
        printf("Memory allocation failed. Aborting.\n");
        exit(-1);
    }
    sessionList = updatedList;
    sessionList[sessionCount] = newSession;
    sessionCount++;
}

void removeSession(const char* sessionId) {
    for (int i = 0; i < sessionCount; i++) {
        if (strcmp(sessionList[i]->sessionId, sessionId) == 0) {
            free(sessionList[i]);
            memmove(&sessionList[i], &sessionList[i + 1], (sessionCount - i - 1) * SESSION_INFO_SIZE);
            sessionCount--;
            break;
        }
    }
}

Session* findLongestInactiveSession() {
    time_t longestActiveTime = time(NULL);
    Session* longestInactiveSession = NULL;

    for (int i = 0; i < sessionCount; i++) {
        if ((time(NULL) - sessionList[i]->loginTimestamp) > (longestActiveTime)) {
            longestActiveTime = time(NULL) - sessionList[i]->loginTimestamp;
            longestInactiveSession = sessionList[i];
        }
    }

    return longestInactiveSession;
}

int main() {
    // Initialize the file for serialization
    FILE* file = fopen("sessions.txt", "wb");
    if (!file) {
        printf("File opening failed. Aborting.\n");
        exit(-1);
    }

    // Serialize existing sessions (if any)
    // ...

    while (1) {
        int choice;
        printf("Choose an option:\n1. Add session\n2. Remove session\n3. Find longest inactive session\n4. Save and quit\n");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                Session* newSession = (Session*)malloc(SESSION_INFO_SIZE);
                printf("Enter session ID: ");
                fgets(newSession->sessionId, SESSION_ID_MAX_LENGTH, stdin);
                printf("Enter IP address: ");
                fgets(newSession->ipAddress, IP_ADDRESS_MAX_LENGTH, stdin);
                time(&newSession->loginTimestamp);
                addSession(newSession);
                break;
            case 2:
                char sessionIdToRemove[SESSION_ID_MAX_LENGTH];
                printf("Enter session ID to remove: ");
                fgets(sessionIdToRemove, SESSION_ID_MAX_LENGTH, stdin);
                removeSession(sessionIdToRemove);
                break;
            case 3:
                Session* longestInactive = findLongestInactiveSession();
                if (longestInactive) {
                    printf("The longest inactive session is %s with IP address %s and login time %ld\n",
                           longestInactive->sessionId, longestInactive->ipAddress, longestInactive->loginTimestamp);
                } else {
                    printf("No sessions found.\n");
                }
                break;
            case 4:
                // Serialize the current state of the session list
                fwrite(sessionList, SESSION_INFO_SIZE * sessionCount, 1, file);

                fclose(file);
                return 0;

            default:
                printf("Invalid option. Please choose again.\n");
        }
    }

    fclose(file);
    return 0;
}

