#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define a custom hash table with collision resolution using chaining
typedef struct {
    int key;
    void* value;
    struct Node* next;
} Node;

Node* create_node(int key, void* value) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->key = key;
    node->value = value;
    node->next = NULL;
    return node;
}

void free_node(Node* node) {
    if (node != NULL) {
        free(node);
    }
}

// Define a custom hash table
typedef struct {
    int size;
    Node** buckets;
} HashTable;

HashTable* create_hash_table(int size) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->size = size;
    table->buckets = (Node**)malloc(size * sizeof(Node*));
    for (int i = 0; i < size; i++) {
        table->buckets[i] = NULL;
    }
    return table;
}

void free_hash_table(HashTable* table) {
    if (table != NULL) {
        for (int i = 0; i < table->size; i++) {
            Node* node = table->buckets[i];
            while (node != NULL) {
                Node* next = node->next;
                free_node(node);
                node = next;
            }
        }
        free(table->buckets);
        free(table);
    }
}

// Define the event log structure
typedef struct {
    int timestamp;
    char event_type;
    char metadata[256];
} EventLog;

EventLog* create_event_log(int timestamp, char event_type, char* metadata) {
    EventLog* log = (EventLog*)malloc(sizeof(EventLog));
    log->timestamp = timestamp;
    log->event_type = event_type;
    strcpy(log->metadata, metadata);
    return log;
}

void free_event_log(EventLog* log) {
    if (log != NULL) {
        free(log);
    }
}

// Define the external parameters structure
typedef struct {
    int num_events;
    int metadata_range;
} ExternalParams;

ExternalParams* create_external_params(int num_events, int metadata_range) {
    ExternalParams* params = (ExternalParams*)malloc(sizeof(ExternalParams));
    params->num_events = num_events;
    params->metadata_range = metadata_range;
    return params;
}

void free_external_params(ExternalParams* params) {
    if (params != NULL) {
        free(params);
    }
}

// Define the main function
int main() {
    // Initialize the hash tables
    HashTable* timestamp_table = create_hash_table(1024);
    HashTable* event_type_table = create_hash_table(256);
    HashTable* event_log_table = create_hash_table(1024);
    HashTable* external_params_table = create_hash_table(1);

    // Read timestamps and event types from standard input
    int timestamp, event_type;
    while (scanf("%d %c", &timestamp, &event_type) == 2) {
        // Parse the timestamp to determine the interval
        time_t interval = timestamp / 3600; // hourly intervals

        // Initialize the event log structure
        EventLog* log = create_event_log(timestamp, event_type, (char*)malloc(256));

        // Insert the log into the hash tables
        Node* node = create_node(interval, log);
        Node* existing = timestamp_table->buckets[interval % timestamp_table->size];
        if (existing == NULL) {
            timestamp_table->buckets[interval % timestamp_table->size] = node;
        } else {
            while (existing->next != NULL) {
                existing = existing->next;
            }
            existing->next = node;
        }

        node = create_node(event_type, log);
        existing = event_type_table->buckets[event_type];
        if (existing == NULL) {
            event_type_table->buckets[event_type] = node;
        } else {
            while (existing->next != NULL) {
                existing = existing->next;
            }
            existing->next = node;
        }

        // Increment the event type counter
        int* count = (int*)malloc(sizeof(int));
        *count = 1;
        node = create_node(event_type, count);
        existing = event_log_table->buckets[event_type];
        if (existing == NULL) {
            event_log_table->buckets[event_type] = node;
        } else {
            while (existing->next != NULL) {
                existing = existing->next;
            }
            existing->next = node;
        }

        // Fetch initial graph parameters from an external data source
        ExternalParams* params = create_external_params(100, 256);
        node = create_node(params, log);
        existing = external_params_table->buckets[0];
        if (existing == NULL) {
            external_params_table->buckets[0] = node;
        } else {
            while (existing->next != NULL) {
                existing = existing->next;
            }
            existing->next = node;
        }

        // Serialize the log data to a file
        FILE* file = fopen("log.data", "wb");
        fwrite(log, sizeof(EventLog), 1, file);
        fclose(file);

        // Deserialize the log data from a file
        file = fopen("log.data", "rb");
        fread(log, sizeof(EventLog), 1, file);
        fclose(file);

        free_log(log);

        // Find and print the most frequent event type in the entire dataset
        int max_count = 0;
        char* most_frequent_event_type = NULL;
        Node* node = event_log_table->buckets[0];
        while (node != NULL) {
            int count = *(int*)node->value;
            if (count > max_count) {
                max_count = count;
                most_frequent_event_type = &((char*)node->value)[0];
            }
            node = node->next;
        }
        printf("Most frequent event type: %c\n", *most_frequent_event_type);

        // Free the allocated memory
        free_hash_table(timestamp_table);
        free_hash_table(event_type_table);
        free_hash_table(event_log_table);
        free_hash_table(external_params_table);
    }

    return 0;
}
