    exportJSON(graph, jsonFile);
    fclose(jsonFile);

    // Export graph structure to XML format
    FILE* xmlFile = fopen("graph.xml", "w");
    exportXML(graph, xmlFile);
    fclose(xmlFile);

    return 0;
}
