```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Define the maximum number of records and key range
#define MAX_RECORDS 10000
#define MAX_KEY_RANGE 1000000

// Define the data structure
typedef struct {
    long *offsets;
    int *keys;
    double *values;
} Record;

Record *records = NULL; // Pointer to the record array
int records_count = 0; // Number of records in the array

// Lock for concurrent access
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to resize the record arrays
void resize_records(int new_size) {
    if (new_size > MAX_RECORDS) {
        printf("Error: Trying to create more than %d records.\n", MAX_RECORDS);
        return;
    }

    Record *new_records = realloc(records, sizeof(Record) * new_size);
    if (!new_records) {
        printf("Error: Failed to resize record array.\n");
        return;
    }

    int i;
    for (i = 0; i < records_count; i++) {
        new_records[i].offsets = realloc(new_records[i].offsets, sizeof(long) * new_size);
        if (!new_records[i].offsets) {
            printf("Error: Failed to resize offset array.\n");
            return;
        }

        new_records[i].keys = realloc(new_records[i].keys, sizeof(int) * new_size);
        if (!new_records[i].keys) {
            printf("Error: Failed to resize key array.\n");
            return;
        }

        new_records[i].values = realloc(new_records[i].values, sizeof(double) * new_size);
        if (!new_records[i].values) {
            printf("Error: Failed to resize value array.\n");
            return;
        }
    }

    free(records);
    records = new_records;
}

// Function to add a new record
void add_record(int key, double value) {
    pthread_mutex_lock(&lock);

    Record *new_record = (Record *)malloc(sizeof(Record));
    if (!new_record) {
        printf("Error: Failed to allocate memory for new record.\n");
        return;
    }

    new_record->offsets = (long *)malloc(sizeof(long));
    if (!new_record->offsets) {
        printf("Error: Failed to allocate memory for offset array.\n");
        free(new_record);
        return;
    }

    new_record->keys = (int *)malloc(sizeof(int));
    if (!new_record->keys) {
        printf("Error: Failed to allocate memory for key array.\n");
        free(new_record->offsets);
        free(new_record);
        return;
    }

    new_record->values = (double *)malloc(sizeof(double));
    if (!new_record->values) {
        printf("Error: Failed to allocate memory for value array.\n");
        free(new_record->offsets);
        free(new_record->keys);
        free(new_record);
        return;
    }

    *new_record->offsets = 0;
    *new_record->keys = key;
    *new_record->values = value;

    if (records_count == MAX_RECORDS) {
        resize_records(MAX_RECORDS * 2);
    }

    int i;
    for (i = 0; i < records_count; i++) {
        if (key >= *records[i].keys && key <= *records[i + 1].keys) {
            int pos = i;
            while (pos > 0 && *records[pos - 1].keys >= key) {
                pos--;
            }
            memmove(&records[pos], &records[pos + 1], sizeof(Record) * (records_count - pos));
        }
    }

    records[records_count] = *new_record;
    records_count++;

    pthread_mutex_unlock(&lock);
}

// Function to serialize the data structure
void serialize_records(const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        printf("Error: Failed to open file for writing.\n");
        return;
    }

    fwrite(&records_count, sizeof(int), 1, file);
    int i;
    for (i = 0; i < records_count; i++) {
        fwrite(&records[i]->keys, sizeof(int), 1, file);
        fwrite(&records[i]->values, sizeof(double), 1, file);
        fwrite(&records[i]->offsets, sizeof(long), 1, file);
    }

    fclose(file);
}

// Function to deserialize the data structure
void deserialize_records(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        printf("Error: Failed to open file for reading.\n");
        return;
    }

    int records_count_deserialized;
    fread(&records_count_deserialized, sizeof(int), 1, file);

    Record *new_records = (Record *)malloc(sizeof(Record) * records_count_deserialized);
    if (!new_records) {
        printf("Error: Failed to allocate memory for deserialized records.\n");
        fclose(file);
        return;
    }

    int i;
    for (i = 0; i < records_count_deserialized; i++) {
        fread(&new_records[i].keys, sizeof(int), 1, file);
        fread(&new_records[i].values, sizeof(double), 1, file);
        fread(&new_records[i].offsets, sizeof(long), 1, file);
    }

    free(records);
    records = new_records;
    records_count = records_count_deserialized;

    fclose(file);
}

// Function to prune outdated records
void prune_records(int age_threshold) {
    int i;
    for (i = 0; i < records_count; i++) {
        if (*records[i].offsets <= age_threshold) {
            // Free the record's memory
            free(records[i].keys);
            free(records[i].values);
            free(records[i].offsets);

            // Shift the remaining records down to fill the gap
            memmove(&records[i], &records[i + 1], sizeof(Record) * (records_count - i));
        }
    }

    records_count -= i;
}

// Function to track memory usage and distribution
void track_memory_usage() {
    int i;
    for (i = 0; i < records_count; i++) {
        // Track memory usage per record
    }
}

int main() {
    // Initialize the data structure
    records = (Record *)malloc(sizeof(Record));
    if (!records) {
        printf("Error: Failed to allocate initial memory.\n");
        return 1;
    }

    add_record(0, 10.0);
    add_record(100, 20.0);
    // ...
    serialize_records("data.bin");

    // Deserialize and use the data structure
    deserialize_records("data.bin");

    prune_records(100);

    track_memory_usage();

    return 0;
}
