#define MAX_ELEMENTS 10000000
#define BUFF_SIZE 1024

typedef struct {
    int* data;
    size_t size;
} Array;

Array* newArray(size_t initialSize) {
    Array* arr = (Array*)malloc(sizeof(Array));
    arr->data = (int*)calloc(initialSize, sizeof(int));
    arr->size = initialSize;
    return arr;
}

void freeArray(Array* arr) {
    if (arr != NULL) {
        free(arr->data);
        free(arr);
    }
}

void printLargest(Array* arr) {
    int largest = arr->data[0];
    for (size_t i = 1; i < arr->size; i++) {
        if (arr->data[i] > largest) {
            largest = arr->data[i];
        }
    }
    printf("The largest integer is: %d\n", largest);
}

Array* readIntegers(FILE* file, Array* arr) {
    size_t bytesRead = 0;
    int buffer[BUFF_SIZE];

    while (fscanf(file, "%d", &buffer[bytesRead]) == 1 && bytesRead < arr->size) {
        bytesRead++;
    }

    for (size_t i = 0; i < bytesRead; i++) {
        arr->data[i] = buffer[i];
    }
    return arr;
}

int main() {
    Array* arr = newArray(MAX_ELEMENTS);
    FILE* file = fopen("input.txt", "r");
    if (file == NULL) {
        fprintf(stderr, "Error opening file.\n");
        exit(1);
    }

    clock_t start = clock();
    arr = readIntegers(file, arr);
    clock_t end = clock();

    printf("Processing time: %f seconds\n", (double)(end - start) / CLOCKS_PER_SEC);

    printLargest(arr);

    freeArray(arr);

    return 0;
}
