        if (bytes_received < 0) {
            printf("recvfrom error");
            return NULL;
        }

        packetEntry new_packet;
        // parse the received packet
        new_packet.protocolType = ...;  // extract protocol type from buffer
        new_packet.sourceIP = ...;       // extract source IP from buffer
        new_packet.destinationIP = ...;  // extract destination IP from buffer
        new_packet.payloadLength = ...;  // extract payload length from buffer
        new_packet.timestamp = ...;      // extract timestamp from buffer

