            free(packets);
            packets = new_packets;
        }

        // add the packet to the array
        memmove(&packets[totalPackets], &new_packet, PACKET_METADATA_SIZE);

        totalPackets++;
        pthread_mutex_unlock(&lock);

        if (totalPackets % 100 == 0) {
