typedef struct {
    int value;
    char* string;
} record;

record** processPipeline(int size, const char** words, int minRand, int maxRand) {
    record** records = NULL;

    // Allocate memory for the structure
    if ((records = (record**)malloc(size * sizeof(record*))) == NULL) {
        return NULL;  // Memory allocation failed
    }

    for (int i = 0; i < size; i++) {
        // Initialize record
        record* currentRecord = (record*)malloc(sizeof(record));

        if (currentRecord == NULL) {
            for (int j = i - 1; j >= 0; j--) {
                free(records[j]->string);
                free(records[j]);
            }

            free(records);
            return NULL;  // Memory allocation failed
        }

        currentRecord->value = rand() % (maxRand - minRand + 1) + minRand;

        // Allocate memory for the string and initialize it with a random word
        size_t wordLength = strlen(words[rand() % size]);
        char* string = (char*)malloc(wordLength * sizeof(char) + 1);
        strcpy(string, words[rand() % size]);
        currentRecord->string = string;

        records[i] = currentRecord;
    }

    return records;
}

int main() {
    // Example usage
    int size = 5;
    const char* words[] = {"apple", "banana", "cherry", "date", "elderberry"};

    record** records = processPipeline(size, words, 1, 100);

    if (records == NULL) {
        printf("Memory allocation failed.\n");
    } else {
        for (int i = 0; i < size; i++) {
            printf("Record %d: value=%d, string='%s'\n", i, records[i]->value, records[i]->string);

            free(records[i]->string);
            free(records[i]);
        }

        free(records);
    }

    return 0;
}
