typedef struct {
    int value;
    char* str;
} record_t;

record_t** manage_memory(int size, char** words, int min_range, int max_range, int allow_duplicates);

int main() {
    // Example usage:
    int size = 10;
    char* words[] = {"hello", "world", "foo", "bar", "baz"};
    int min_range = 1;
    int max_range = 100;

    record_t** records = manage_memory(size, words, min_range, max_range, 0);

    for (int i = 0; i < size; i++) {
        printf("Record %d: Value = %d, String = %s\n", i+1, records[i]->value, records[i]->str);
    }

    // Don't forget to free the allocated memory!
    for (int i = 0; i < size; i++) {
        free(records[i]->str);
        free(records[i]);
    }
    free(records);

    return 0;
}

record_t** manage_memory(int size, char** words, int min_range, int max_range, int allow_duplicates) {
    srand(time(NULL)); // Initialize random number generator

    record_t** records = (record_t**)malloc(size * sizeof(record_t*));
    for (int i = 0; i < size; i++) {
        records[i] = (record_t*)malloc(sizeof(record_t));

        int value = rand() % (max_range - min_range + 1) + min_range;
        char* str = get_random_string(words, allow_duplicates);
        if (!str) {
            // Handle allocation failure
            printf("Error: Memory allocation failed.\n");
            exit(1);
        }

        records[i]->value = value;
        records[i]->str = str;
    }

    return records;
}

char* get_random_string(char** words, int allow_duplicates) {
    if (allow_duplicates) {
        // Choose a random word from the list
        size_t idx = rand() % strlen(words);
        return strdup(words[idx]);
    } else {
        // Ensure uniqueness by looping until we find an unused word
        for (size_t i = 0; i < strlen(words); i++) {
            char* str = strdup(words[i]);
            // Check if the string is already in use
            bool found = false;
            for (int j = 0; j < size; j++) {
                if (strcmp(records[j]->str, str) == 0) {
                    found = true;
                    break;
                }
            }
            if (!found) {
                return str;
            } else {
                free(str);
            }
        }
        // If we reach here, it means all words are already in use
        printf("Error: No more unique words available.\n");
        exit(1);
    }
}
