record **init_pipeline(int size, const char **words, int min, int max, int max_len, int use_custom_allocator) {
    record **pipeline = NULL;
    if (use_custom_allocator) {
        pipeline = (record **)custom_allocator(size);
    } else {
        pipeline = (record **)malloc(sizeof(record *) * size);
    }

    for (int i = 0; i < size; i++) {
        record *rec = NULL;
        rec = (record *)malloc(sizeof(record));
        if (rec == NULL) {
            // Handle memory allocation failure
            printf("Memory allocation failed. Exiting.\n");
            return NULL;
        }

        rec->value = rand() % (max - min + 1) + min;

        int str_len = strlen(words[i]);
        char *str = (char *)malloc((str_len + 1) * sizeof(char));
        strcpy(str, words[i]);

        rec->str = str;
        if (i == 0) {
            pipeline[0] = rec;
        } else {
            for (int j = 0; j < i - 1; j++) {
                pipeline[j]->next = rec;
            }
            pipeline[i - 1]->next = rec;
        }

        free(rec);
    }

    return pipeline;
}

