#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
    short value;
} record_t;

void expandGraphStructure(record_t **records, int *recordCount) {
    // Define constants for array sizes
    const int RECORD_CAPACITY = 10000;
    const int KEY_RANGE = 1000; // Adjust this as needed

    if (*recordCount >= RECORD_CAPACITY) {
        // Resize the records array and initialize new memory
        record_t *newRecords = (record_t *)malloc(RECORD_CAPACITY * sizeof(record_t));
        for (int i = *recordCount; i < RECORD_CAPACITY; i++) {
            newRecords[i].key = rand() % KEY_RANGE;
            newRecords[i].offset = i;
            newRecords[i].value = (short)rand();
        }
        // Copy existing records to the new array
        for (int i = 0; i < *recordCount; i++) {
            newRecords[i] = (*records)[i];
        }
        free(*records);
        *records = newRecords;
    }

    int newRecordCount = *recordCount + RECORD_CAPACITY / 2;
    // Allocate memory for the key and offset arrays
    long *keys = (long *)malloc(newRecordCount * sizeof(long));
    short *values = (short *)malloc(newRecordCount * sizeof(short));

    for (int i = 0; i < newRecordCount; i++) {
        keys[i] = rand() % KEY_RANGE;
        values[i] = (short)rand();
    }

    // Initialize the record array with default values
    for (int i = *recordCount; i < newRecordCount; i++) {
        (*records)[i].key = keys[i];
        (*records)[i].offset = i;
        (*records)[i].value = values[i];
    }

    free(keys);
    free(values);

    *recordCount = newRecordCount;
}

void setRecordValue(record_t **records, int recordIndex) {
    if (recordIndex < 0 || recordIndex >= *recordCount) {
        return; // Handle invalid record index
    }
    (*records)[recordIndex].value = (short)rand();
}

int findLargestKey(record_t *records, int recordCount) {
    int maxKey = records[0].key;
    for (int i = 1; i < recordCount; i++) {
        if (records[i].key > maxKey) {
            maxKey = records[i].key;
        }
    }
    return maxKey;
}

void serializeGraphStructure(record_t *records, int recordCount, char *filename) {
    FILE *file = fopen(filename, "wb");
    fwrite(records, sizeof(record_t), recordCount, file);
    fclose(file);
}

record_t *deserializeGraphStructure(char *filename) {
    FILE *file = fopen(filename, "rb");
    int recordCount;
    fread(&recordCount, sizeof(int), 1, file);

    record_t *records = (record_t *)malloc(recordCount * sizeof(record_t));
    fread(records, sizeof(record_t), recordCount, file);
    fclose(file);
    return records;
}

int main() {
    // Initialize the record array
    int recordCount = 0;
    record_t *records = NULL;

    // Read initial graph parameters from an external data source
    // ...

    while (1) {
        // Expand the graph structure as needed
        expandGraphStructure(&records, &recordCount);

        // Set random values for new records
        setRecordValue(&records, recordCount - 1);

        // Find and print the largest integer in the array
        int maxKey = findLargestKey(records, recordCount);
        printf("Max key: %d\n", maxKey);

        // Serialize the graph structure to a file for persistence
        serializeGraphStructure(records, recordCount, "graph_data.bin");

        // Deserialize the graph structure from the file
        records = deserializeGraphStructure("graph_data.bin");
    }

    return 0;
}
