record* expandGraphStructure(int* keys, int numKeys, int maxRecordSize, long totalOffset) {
    // allocate memory for arrays
    record** records = (record**)malloc((numKeys + 1) * sizeof(record*));
    long* offsets = (long*)malloc((numKeys + 1) * sizeof(long));
    int* values = (int*)malloc((numKeys + 1) * sizeof(int));

    // initialize arrays
    for (int i = 0; i < numKeys; i++) {
        records[i] = (record*)malloc(sizeof(record));
        records[i]->key = keys[i];
        records[i]->offset = totalOffset++;
        records[i]->value = rand() % 100;
    }

    // add record
    records[numKeys] = (record*)malloc(sizeof(record));
    records[numKeys]->key = numKeys + 1;
    records[numKeys]->offset = totalOffset++;
    records[numKeys]->value = rand() % 100;

    // initialize union-find data structure
    int* parent = (int*)malloc((numKeys + 1) * sizeof(int));
    for (int i = 0; i < numKeys + 1; i++) {
        parent[i] = i;
    }

    // perform union-find operations
    int disjointSets = 0;
    for (int i = 0; i < numKeys + 1; i++) {
        // find key set
        int root = i;
        while (root != parent[root]) {
            root = parent[root];
        }
        // union with keys
        for (int j = i; j <= numKeys; j++) {
            if (records[j]->key == records[i]->key) {
                int newRoot = j;
                while (newRoot != parent[newRoot]) {
                    newRoot = parent[newRoot];
                }
                if (root != newRoot) {
                    root = newRoot;
                    disjointSets++;
                }
            }
        }
    }

    // free memory
    for (int i = 0; i < numKeys + 1; i++) {
        free(records[i]);
    }
    free(records);
    free(offsets);
    free(values);
    free(parent);

    return records;
}
