        // Add new record to the existing array while maintaining uniqueness of keys and offsets
        for (int j = 0; j < numKeys; j++) {
            if (!recordExists(&records[i], &keysArr[i])) {
                int idx = i;
                while (idx > 0) {
                    idx--;
                    if (isKeyUnique(records[idx].key, keysArr[idx]) && isOffsetUnique(records[idx].offset)) {
                        break;
                    }
                }

                // Shift records to the right
                for (int k = numKeys - 1; k > idx; k--) {
                    records[k] = records[k - 1];
                    keysArr[k] = keysArr[k - 1];
                    offsets[k] = offsets[k - 1];
                }

                // Insert new record at the correct position
                records[idx].key = keys[j];
                records[idx].offset = (long)i;
                records[idx].value = (short)rand() % 10000; // Generate random value within a given range
            } else {
                printf("Error: Key already exists.\n");
                return NULL;
            }
        }

        free(lastAccessedIndex);
    }

    // Set the value of each record's int field to a random value within a given range
    for (int i = 0; i < numKeys; i++) {
        records[i].value = (short)rand() % 10000;
    }

    return records;
}

// Helper function to check if a key already exists in the array
int isKeyUnique(int key, int* keysArr) {
    for (int i = 0; i < numKeys; i++) {
        if (key == keysArr[i]) {
            return 0;
        }
    }
    return 1;
}

// Helper function to check if an offset already exists in the array
int isOffsetUnique(long offset) {
    for (int i = 0; i < numKeys; i++) {
        if (offset == records[i].offset) {
            return 0;
        }
    }
    return 1;
}

// Helper function to check if a record already exists in the array
int recordExists(record* record, int* key) {
    for (int i = 0; i < numKeys; i++) {
        if (record->key == *key && record->offset == records[i].offset) {
            return 1;
        }
    }
    return 0;
}

// Function to set the value of each record's int field to a random value within a given range
void setValue(record* records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        records[i].value = (short)rand() % 10000;
    }
}

// Function to find and print the largest integer in the array
int largestInteger(int* keysArr, int numKeys) {
    int max = INT_MIN;
    for (int i = 0; i < numKeys; i++) {
        if (keysArr[i] > max) {
            max = keysArr[i];
        }
    }
    return max;
}

// Serialize the data structure to a file
void serialize(record* records, int numRecords, char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        printf("Error: Unable to open file.\n");
        return;
    }

    for (int i = 0; i < numRecords; i++) {
        fwrite(&records[i], sizeof(record), 1, file);
    }
}

// Deserialize the data structure from a file
record* deserialize(char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        printf("Error: Unable to open file.\n");
        return NULL;
    }

    record* records = (record*)malloc(10000 * sizeof(record));
    int numRecords = 0;

    while (fread(&records[numRecords], sizeof(record), 1, file)) {
        numRecords++;
    }

    fclose(file);
    return records;
}
